// Generated by scripts/import_questions.py; source text and answers are preserved.
window.QUESTION_BANK = {"title":"2026中华知识竞赛·初赛题库","source":"2026中华知识竞赛·初赛题库.xlsx","questions":[{"id":1,"type":"判断题","text":"“山不在高，有仙则名。水不在深，有龙则灵”出自《陋室铭》，这篇文章的作者有“诗佛”之称。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"《陋室铭》的作者是刘禹锡，有“诗佛”之称的是王维。"},{"id":2,"type":"判断题","text":"白朴的《天净沙·秋思》属于羁旅之作，既“深得唐人绝句妙景”，又兼具宋词清隽疏朗之自然，被尊为“秋思之祖”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"《天净沙·秋思》的作者是马致远。"},{"id":3,"type":"判断题","text":"“近取诸身，远取诸物”是老祖宗最初的造字方式；“画成其物，随体诘诎”是书法最初的表现形式。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"“近取诸身，远取诸物”阐述的是老祖宗最初的造字方式。“画成其物，随体诘诎”原句是“象形者，画成其物，随体诘诎，日月是也。”出自《说文解字》，意思是所谓的象形字说的是把具体的物体以绘画的形式表现出来，形成文字，根据物体的不同绘画形式也不同，比如日和月就是象形字。结合《说文解字叙》可知这里说的是书法最初的表现形式。"},{"id":4,"type":"判断题","text":"古代帝王把帝位让给贤能的人称为禅让，是原始社会末期部落首领的选举制度。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"禅让是指统治者把部落首领之位让给有才华，有能力的人，让更贤能的人统治国家。尧是黄帝以后比较著名部落联盟首领，尧去世后，尧把部落联盟首领位置让于舜，推舜为帝。这种让位，历史上称为“禅让”。"},{"id":5,"type":"判断题","text":"三省六部：三省为中书省、门下省、尚书省。三省的长官都是宰相。六部：吏部、户部、礼部、兵部、刑部、工部。各部长官称尚书。六部制从隋唐开始实行，一直延续到清末。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"隋唐时，三省同为最高政务机构，一般中书省管决策，门下省管审议，尚书省管执行。中书省长官称中书令，门下省长官称侍中，尚书省长官称尚书令。尚书省下辖六部，吏部(管官吏的任免与考核等)、户部(管土地户口、赋税、财政等)、礼部(管典礼、科举、学校等)、兵部(管军事)、刑部(管司法刑狱)、工部(管工程营造、屯田水利等)，各部副职称侍郎。"},{"id":6,"type":"判断题","text":"礼部为六部之一，掌管礼仪、祭祀、土地、户籍等职事，部长官称为礼部尚书。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“礼部”，在明代有尚书一人，左、右侍郎各一人，下设四司，分别为：仪制清吏司，掌嘉礼、军礼及管理学务、科举考试事；祠祭清吏司，掌吉礼、凶礼事务；主客清吏司，掌宾礼及接待外宾事务；精膳清吏司，掌筵飨等事务。"},{"id":7,"type":"判断题","text":"兵部是古代“六部”之一，掌管全国武官选用和兵籍、军械、军令等事宜。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"兵部为中国古代官署名，六部之一，相当于今日的国防部。其长官为兵部尚书。兵部又称夏官、武部。掌管武官选用及兵籍、兵械、军令等。"},{"id":8,"type":"判断题","text":"“举孝廉”是古代一种自下而上的选官制度，即中央和地方一定级别的官吏根据考察情况，将未有官职的士人推荐给中央政府。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"举孝廉是汉朝的一种由下向上推选人才为官的制度，孝廉是察举制的主要科目之一。被举人的资历，大多为州郡属吏或通晓经书的儒生"},{"id":9,"type":"判断题","text":"“征辟”是古代一种自下而上的选官制度。被征辟者经过试用，确有能力，就正式授予官职。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“征辟”是自上而下的选官制度。一般由皇帝派人去聘任特别有名望的人叫作征召，三公以下召举布衣入仕叫作辟除，合称为“征辟”，为汉代选用官吏的一种制度。皇帝征召的士人，多授予博士或待诏的称号，公府辟除的士人一般通称掾吏。"},{"id":10,"type":"判断题","text":"“终养”又称“归养”，是指因亲人年老或病重而辞官侍奉。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"奉养父母，以终其天年。多指辞官归家以终养年老亲人。"},{"id":11,"type":"判断题","text":"古代官吏告老退休称“致仕”，也称“休致”。官员年老有病，由本人提出申请，获准后致仕，国家据其职位，给予一定的赏赐。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"古代官吏的退休制，形成于春秋时期，汉代承先秦，并进一步完备。汉代丞相以下皆须致仕，称“归老”“乞骸骨”。自魏晋以后，历代相沿。"},{"id":12,"type":"判断题","text":"“告老”本指古代社会官员因年老辞去职务，有时也是官员因故辞职的一种借口。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"指封建时代臣子或官员因年老辞去职务，后泛指年老退休。语出《左传·襄公七年》：“冬十月，晋韩献子告老。”"},{"id":13,"type":"判断题","text":"移疾指官员上书称病，实际是官员受到权臣诋毁，不得不请求退职的委婉说法。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"移疾，指官员上书称病，多为居官者求退的委婉语。"},{"id":14,"type":"判断题","text":"皇帝指定的皇位继承人称为“皇太子”。一般为皇帝的嫡长子，但也有例外，由皇帝选定册立。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"商周时期天子及诸侯的嫡长子，称太子或世子。自汉朝开始，只有法定继承人(即皇帝的嫡长子)，才能称太子或皇太子，而诸侯王或藩王的正式继承人只能称“世子”。封建社会的太子，其地位仅次于皇帝，并拥有类似于朝廷的东宫。"},{"id":15,"type":"判断题","text":"太子指封建时代君主儿子中被确定继承君位的人，有时也可指其他儿子。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"太子指封建时代君主儿子中被确定继承君位的人。其他儿子不能称太子。"},{"id":16,"type":"判断题","text":"嗣位指继承君位，我囯封建王朝通常实行长子继承制，君位由最年长的儿子继承。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"我囯封建王朝通常实行嫡长子继承制，嫡长子是嫡妻(正妻)所生的长子。"},{"id":17,"type":"判断题","text":"中国古代朝廷中最尊显的三个官职的名称为“三公”。但朝代不同、时期不同，三公之官名称不同，职掌也不同。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"三公，始于周朝，或以司徒、司马、司空为三公，或以太师、太傅、太保为三公。秦汉称丞相、太尉、御史大夫。唐宋沿用此称。明清以太师、太傅、太保为三公，但已无实际职权，只用作大臣的最高荣誉。"},{"id":18,"type":"判断题","text":"秦代三公即丞相、太尉和御史大夫。丞相位最高，尊称为相国，通称为宰相，秉承皇帝旨意辅佐朝政；太尉掌管全国军事；御史大夫负责监察并帮助丞相处理事务。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"丞相，最高行政长官，辅助皇帝处理政务，同时负责对文武百官的管理。太尉，最高军政长官，负责管理全国军事事务。御史大夫，负责监察百官，也是副丞相。"},{"id":19,"type":"判断题","text":"尚书，始置于战国，历代相沿，是执掌文书的官员，因尚书在皇帝左右办事，掌管文书奏章，地位很重要。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"尚书，是中国封建时代的政府高官名称。在清朝，六部和理藩院等部门的主官称为尚书。"},{"id":20,"type":"判断题","text":"我国战国时期中央就设有监察官，称为御史，一直沿袭至清代。主要职责是对百官进行纠察弹劾。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"西汉时建立了独立的监察机构——御史府，后改称御史台。历代御史台的长官称御史大夫或御史中丞等。明代把御史台改为都察院，长官为左右都御史，清代沿袭。"},{"id":21,"type":"判断题","text":"古代朝廷中分职设官，各有专司，所以可用“有司”来指称朝廷中的各级官员。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“有司”意为“有具体职务、做具体工作的官吏”或“泛指官吏”。不能用来指称朝廷中的各级官员。"},{"id":22,"type":"判断题","text":"唐代县以上的行政单位称州或郡，长官是刺史或太守。首都或陪都所在地的州叫府，长官叫尹或少尹。唐初中央派官员出巡各州，监察地方行政，称为黜陟使，有权罢免或提升地方官吏。职权和汉代的州刺史相似。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"唐代县以上的行政单位称州或郡，长官是刺史或太守。首都或陪都所在地的州叫府，长官叫尹或少尹。唐初中央派官员出巡各州，监察地方行政，称为黜陟使，有权罢免或提升地方官吏。职权和汉代的州刺史相似。"},{"id":23,"type":"判断题","text":"提辖，主管军队武装、训练、督捕盗贼、维护地方治安等。宋代州郡多设提辖兵马一官。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"宋代州郡多设置提辖，或由守臣兼任，专管统辖军队，训练教阅、督捕盗贼"},{"id":24,"type":"判断题","text":"“征、辟、任、除、拜、授、迁”都是指任用官员，用法相同。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“征”是皇帝特聘；“辟”是官府或高官聘用；“任”又称“保”，指高官保任其子弟为官；“除”有“除旧官，任新官”之意，就是改任；“拜”“授”是正常授官，有时是平级调任，有时是升职；“迁”指官职晋升或调动。"},{"id":25,"type":"判断题","text":"古代任官，还有摄官、兼官、加官、试守的制度。“摄”是代行职守；“兼”指兼职，以低职兼高职为“行”，以高职兼低职为“领”或“平”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"汉代以低职兼高职为“行”，以高职兼低职为“领”；而到了唐宋，以低职兼高职为“守”，以高职兼低职为“行”。"},{"id":26,"type":"判断题","text":"封邑是指古代君主把自己国土的某一块地方作为奖励赐给功臣，如淮阴侯韩信所在的淮阴就是刘邦赐给他的封邑。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"封邑是把国土中某一块地方的财政收入或者赋税奖励给某人，不是把国土奖励给他。"},{"id":27,"type":"判断题","text":"三省六部制里，主管工程营造、屯田水利的是户部。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"是工部。"},{"id":28,"type":"判断题","text":"在唐代，官员官服的颜色因官位的高低而有所不同，高级官员一般是紫色或红色，有“大紫大红”“红得发紫”等说法，官阶低的一般是青色或黑色，从《琵琶行》“司马青衫”可以看出，李白当时的官阶比较低。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“司马青衫”指的是白居易，不是李白。"},{"id":29,"type":"判断题","text":"“出”在古代一般是指地方的官员到朝廷担任要职，如《琵琶行》中有“予出官二年”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"是指京官到地方就任。"},{"id":30,"type":"判断题","text":"古人幼时命名，成年取字，字和名有意义上的联系。字是为了便于他人称谓，对平辈或尊辈称字出于礼貌和尊敬。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"有三种情况直称姓名：自称；用于介绍或作传；称所厌恶、所轻视的人。"},{"id":31,"type":"判断题","text":"以字行，是指在古代社会生活中，某人的字得以通行使用，他的名反而不常用。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"汉字文化圈中，中国、朝鲜半岛、越南等地之古人，一般有“名”也有“字”。“以字行”即是因为种种原因，世人多仅称呼此人的“字”，而不熟悉其“名”。例如明朝著名内阁首辅，阁臣杨士奇，名寓，字士奇，但世人通常仅知其字，所以称之为“以字行”。反之，如李白，名白，字太白，因名、字都为世人所熟悉，就不能说是“以字行”。"},{"id":32,"type":"判断题","text":"古代男子有名有字，名是出生后不久父亲起的，字是二十岁举行冠礼后才起的。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"人的称号。古人不仅有“名”，而且有“字”。婴儿出生三个月后由父亲命“名”。古时汉族男子二十岁时举行成人礼冠礼，并取“字”；女子十五岁许嫁,举行笄礼，并取“字”。"},{"id":33,"type":"判断题","text":"古代王侯将相、高级官吏、著名文士死后会被追加的称号叫“谥号”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"谥号是指社会地位相对较高人物死之后，后人按其生平事迹进行评定后给予或褒或贬评价的文字，始于西周，曾广泛通行于汉字文化圈"},{"id":34,"type":"判断题","text":"“郡望”表示某一地域范围内的名门大族。如韩愈虽是河内河阳人，但因昌黎韩氏为唐代望族，故韩愈常以“昌黎韩愈”自称。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"“郡望”一词，是“郡”与“望”的合称。“郡”是行政区划，“望”是名门望族，“郡望”连用，即表示某一地域或范围内的名门大族。古称郡中为众人所仰望的贵显家族。"},{"id":35,"type":"判断题","text":"古人称自己一方的亲属朋友时，常用“家”“舍”等谦辞。如“家父”，又作“家严”“家君”；“家母”，又作“家慈”；舍弟、舍妹、舍侄。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"比如[北齐]颜之推《颜氏家训·风操》：“陈思王 称其父为家父，母为家母。”"},{"id":36,"type":"判断题","text":"古人称对方时，表示尊敬客气的态度，常用“令”“尊”“贤”等敬辞。其中“令”用以称呼对方的亲属，如令尊、令堂、令兄、令郎、令爱等；“尊”用来称与对方有关的人或物，如“尊上”(称对方的父母)、“尊意”(对方的意思)；“贤”，用于尊称平辈或晚辈，如“贤郎”(对方的儿子)、“贤弟”等。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"比如《三国演义》第三回：“肃与贤弟少得相见，令尊却常会来。”"},{"id":37,"type":"判断题","text":"古人的年龄有时不用数字表示，不直接说出某人多少岁，而是用一种与年龄有关的称谓来代替，如“豆蔻”指十三四岁的男子。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“豆蔻”指十三四岁的少女。"},{"id":38,"type":"判断题","text":"垂髫：借指三岁到九岁的儿童。总角：八岁到十四岁的少年。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"古人的年龄有时不用数字表示，不直接说出某人多少岁，而是用一种与年龄有关的称谓来代替。"},{"id":39,"type":"判断题","text":"古人对死的称谓等级森严，天子、帝后之死曰崩，诸侯、太子之死曰薨，大夫之死曰卒，庶人之死曰不禄。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"士的死曰不禄，庶人之死曰死。"},{"id":40,"type":"判断题","text":"“幸”通常指封建帝王到达某地，也叫巡幸。“召幸”特指皇帝对妃嫔的召见、宠幸。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"出自《汉书．卷二十五．郊祀志上》：「上始巡幸郡县，寖寻于泰山矣！」。"},{"id":41,"type":"判断题","text":"冠族是指当地最有钱、最有势力，人口最多的豪门世族。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"冠族是指名门望族。"},{"id":42,"type":"判断题","text":"古人成年取字，名和字使用有别，名供晚辈呼唤，字供长辈或平辈呼唤。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"名供长辈呼唤，字供晚辈或平辈呼唤。"},{"id":43,"type":"判断题","text":"古人的称谓有谦敬之分，对别人称自己的父亲时用“令尊”，称呼对方的父亲用“家父”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"对别人称自己的父亲时用“家父”，称呼对方的父亲用“令尊家父”。"},{"id":44,"type":"判断题","text":"朕是古人的自称，本来没有贵贱之分，自秦始皇开始专用为皇帝的自称。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"朕最早见于商代甲骨文  。《说文》：“朕，我也，阙。”段玉裁注分析朕字之构形之义是：朕，从舟，灷声，本义是舟的裂缝；还有预兆，迹象，秦始皇二十六年起定为帝王自称之词，我等义。"},{"id":45,"type":"判断题","text":"古人对于父母的死有委婉的称谓，父亲去世曰“内艰”，母亲去世曰“外艰”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"父亲去世曰“外艰”，母亲去世曰“内艰”。"},{"id":46,"type":"判断题","text":"对于皇帝的称谓，在古代不同时期有不同的称法，有称庙号的，如“汉武帝”，有称年号的，如“唐太宗”，有称谥号的，如“康熙”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"汉武帝是谥号，唐太宗是庙号，康熙是年号。"},{"id":47,"type":"判断题","text":"古人幼时命名，成年取字。字是为了便于他人称谓，对平辈或者尊辈一般称字，如“苏东坡”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"苏轼，字子瞻，号东坡居士，东坡算号。"},{"id":48,"type":"判断题","text":"普通人称自己已故的父亲为“先考”；已故的母亲称为“妣”、“先妣”；已故父母就合称“考妣”，如成语“如丧考妣”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"如丧考妣， 好像死了父母那样悲痛。形容非常伤心和着急，今多为贬义。出自《尚书·舜典》。"},{"id":49,"type":"判断题","text":"古代对已婚妇女的称呼因身份不同而有别，“天子之妃曰后，诸侯曰夫人，大夫曰孺人，士曰妇人，庶人曰妻。”","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"天子的配偶叫后，诸侯的配偶叫夫人，大夫的配偶叫孺人，士的配偶叫妇人，庶人的配偶叫妻。"},{"id":50,"type":"判断题","text":"谥号，专指有功之臣死后，朝廷赐予的寓含善意评价或表扬性质的称号。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"不一定是功臣，也不一定是善意的评价。"},{"id":51,"type":"判断题","text":"谥号专指皇帝死后依其生前事迹所给予的带有评价性质的称号。如文帝、武帝等属于褒谥，厉帝、炀帝属于恶谥。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"谥号不一定是皇帝专用，大臣也有。"},{"id":52,"type":"判断题","text":"在古代宗法社会中，嫡长子指旧时嫡妻所生的长子，因其地位最高，又称“宗子”，有继承父亲地位和财产的权利。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"嫡长子是指古代宗法制正妻所生的第一个儿子。"},{"id":53,"type":"判断题","text":"“封禅”指在都城的城郊祭天、祭地的盛典。历代好大喜功的帝王都给予特别的重视。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“封禅”专指在泰山的天地祭祀。《史记·封禅书》：“此泰山上筑土为坛以祭天，报天之功，故曰封。此泰山下小山上除地，报地之功，故曰禅。”"},{"id":54,"type":"判断题","text":"古代的宗庙制是天子七庙，诸侯五庙，大夫三庙，士一庙，庶人不准设庙。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"宗庙制度，简称庙制。是指儒家为已故祖先建立灵魂依归之所设立的次序和祭祀制度。庙制规定，天子立七庙，诸侯立五庙，大夫立三庙，士立一庙，庶人无庙，以此区分亲疏贵贱"},{"id":55,"type":"判断题","text":"古代帝王临朝的典礼仪式称“朝仪”，是体现一代帝王之尊及典制完备的重要标志，具有强烈的政治色彩。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"各朝对朝仪都有严格的规定和等级区别。一般规定：天子面向南，三公面向北以东为上。朝仪之位已定，天子和臣子行揖礼，礼毕退朝，后世泛称人臣朝君之礼仪为“朝仪”。"},{"id":56,"type":"判断题","text":"古代诸侯会定期朝见天子叫“朝聘”。每年派大夫朝见称为“小聘”；每隔三年派卿朝见为“大聘”；每隔五年亲自朝见为“朝”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"古代诸侯亲自或派使臣按期朝见天子的礼仪。春秋时期，政在霸主，诸侯朝见霸主，亦称朝聘。"},{"id":57,"type":"判断题","text":"揖让，一指古代宾主相见的礼节。按尊卑分为三种，称为三揖：一为土揖，专用于没有婚姻关系的异姓，行礼时推手微向下；二为时揖，专用于有婚姻关系的异姓，行礼时推手平而置于前；三为天揖，专用于同姓宾客，行礼时推手微向上。一指禅让，即让位于比自己更贤能的人。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"长揖，不分尊卑的相见礼，拱手高举，自上而下；拱，一种相见礼，两手在胸前相合表示敬意。"},{"id":58,"type":"判断题","text":"祖道，出行者祭祀路神和设宴送行的礼仪。“至易水上，既祖，取道”(《荆轲刺秦王》)中的“祖”就是“祖道”，引申为饯行和送别。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"祖道指古代为出行者祭祀路神和设宴送行的礼仪。"},{"id":59,"type":"判断题","text":"虚左，古代座次以左为尊，空着左边的位置以待宾客。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"古时一般以右为尊，但是在车上例外以左为尊。空着左边的位置。古代以左为尊，虚左表示对宾客的尊敬。"},{"id":60,"type":"判断题","text":"孝，指对父母要孝顺、服从；悌，指对兄长要敬重、顺从。孔子非常重视孝悌，把孝悌作为实行“仁”的根本，提出“三年无改于父道”“父母在，不远游”等一系列孝悌主张。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"孝悌简言之：孝敬父母、尊重爱护兄弟姐妹。"},{"id":61,"type":"判断题","text":"古人在祭祀前沐浴、更衣、独居，以示虔诚。这些活动叫“斋戒”。斋戒时要求“五思”(思其居处、笑语、志意、所乐、所嗜)，主要是为了使思想集中、统一。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《史记·秦始皇本纪》：“齐人徐巿等上书，言海中有三神山，名曰蓬莱、方丈、瀛洲，仙人居之。请得斋戒，与童男女求之。”"},{"id":62,"type":"判断题","text":"纨绔子弟代指富贵人家的子弟。因为纨是一种细而有光泽的绢帛；绔是套裤，是套在最外面御寒的。穷人一般穿不起绔，而富贵人家子弟不仅穿纨，还讲究“纨绔”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"旧时指官僚、地主等有钱有势人家成天吃喝玩乐、不务正业的子弟。"},{"id":63,"type":"判断题","text":"古人称已嫁出的女子回娘家省父母为“归宁”，也指男子归省父母。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"归宁又可称为做客、返外家。流行于南北广大地区。指已嫁女子，回娘家归问父母之行动。起源很早，《诗经》已有“归事父母”之记载。"},{"id":64,"type":"判断题","text":"牺牲：古代祭祀用的牲畜，色纯为“牺”，如牛羊猪；色杂为“牲”，如鸡鸭鹅。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"体全为“牲”。"},{"id":65,"type":"判断题","text":"古代帝王祭祀时，牛羊豕三牲全备为“太牢”，只有羊豕没有牛为“少牢”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"出自《管子·事语》：“俎豆之礼不致牲，诸侯太牢，大夫少牢，不若此，则六畜不育。"},{"id":66,"type":"判断题","text":"顿首，古代的一种见面礼，行礼时点点头以示问候。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"顿首，俗称叩头，行礼时，头碰地即起。通常用于下对上及平辈之间的敬礼。"},{"id":67,"type":"判断题","text":"稽首，古代的拜礼，行礼时头碰地须停留一段时间，新婚夫妇拜天地父母常用此大礼。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"中国传统礼仪的稽首动作和佛教的叩头动作是不一样的，手的动作是不一样的，当然它所代表的意义也是不一样的。佛教的叩头动作手心是向上的，意为承接佛法。"},{"id":68,"type":"判断题","text":"古代男子二十岁成年，行加冠礼并取字取号，故男子二十岁称为“弱冠”，如苏轼字子瞻，号东坡居士。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"男子二十岁成年只取字，不取号。"},{"id":69,"type":"判断题","text":"斋戒，古人祭祀或做重大事情前，为表虔诚，往往要沐浴更衣并忌荤，不喝酒，不吃肉。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"斋戒时并非不吃肉，而是忌食有辛辣有臭气的食物，如葱蒜、芥末等。"},{"id":70,"type":"判断题","text":"嗣位是指继承君位，我国封建王朝奉行长子继承制，君位只能由最年长的儿子继承。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"这个说法太过于绝对，一般是嫡长子继承，但到了清代康熙之后，这一传统被打破。"},{"id":71,"type":"判断题","text":"春节，我国传统习俗中最隆重的节日，又称元日、新春、新正等。春节习俗是庆贺过去的一年，祈祝新年快乐、五谷丰登、人畜兴旺，多与农事有关。迎龙舞龙为取悦龙神保佑，风调雨顺；舞狮源于震慑糟蹋庄稼、残害人畜之怪兽的传说。燃鞭炮、贴春联、挂年画、拜年贺喜等习俗至今仍广为流行。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"古时候，人们把谷物的成长周期称为“年”。民间一般从上年的腊月初八或腊月二十三开始，一直到来年的正月十五都称为“春节”。"},{"id":72,"type":"判断题","text":"元宵节，古称上元节、灯节。源于“火把节”，汉代民众在乡间田野持火把驱赶虫兽，希望减轻虫害，祈祷好的收成。吃元宵是我国由来已久的习俗。元宵节的习俗还有赏花灯、猜灯谜、舞龙灯、迎紫姑、走百病等。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"元宵节，又称上元节、小正月、元夕或灯节，时间为每年农历正月十五。"},{"id":73,"type":"判断题","text":"端午节，又称端阳、重午、重五。端午原是月初午日的仪式，因“五”与“午”同音，农历五月初五遂成端午节。一般认为，该节与纪念屈原有关。习俗有喝雄黄酒、挂香袋、吃粽子、插花和菖蒲、斗百草、驱“五毒”等。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"端午节，又称端阳节、龙舟节、重五节、天中节等，是集拜神祭祖、祈福辟邪、欢庆娱乐和饮食为一体的民俗大节。"},{"id":74,"type":"判断题","text":"七夕节，又称乞巧节。每年七月初七晚上，妇女们趁织女与牛郎团圆之际，摆设香案，穿针引线，向她乞求织布、绣花的技巧。在葡萄架下，静听牛郎织女的谈话。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"七夕节由星宿崇拜演化而来，为传统意义上的七姐诞，因拜祭“七姐”活动在七月七晩上举行，故名“七夕”。"},{"id":75,"type":"判断题","text":"中秋节，又称团圆节。农历八月在秋季之中，八月十五又在八月之中，故称中秋。秋高气爽，明月当空，故有赏月与祭月之俗。圆月带来的团圆的联想，使中秋节更加深入人心。中秋节的主要习俗有赏月、祭月、观潮、吃月饼等。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"中秋节，又称祭月节、月光诞、月夕、秋节、仲秋节、拜月节、月娘节、月亮节、团圆节等，是中国民间传统节日。"},{"id":76,"type":"判断题","text":"重阳节，《易经》将“九”定为阳数，两九相重，故农历九月初九为“重阳”。重阳时节，秋高气爽，风清月洁，故有登高望远、赏菊赋诗、喝菊花酒、插茱萸等习俗。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"重阳节，是中国民间传统节日，节期在每年农历九月初九日。"},{"id":77,"type":"判断题","text":"除夕，农历十二月三十，因此也叫“年三十”，那一天人们往往通宵不眠，有除旧迎新的意思。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"除夕是农历一年最后一天的晚上，不一定是十二月三十，有时是十二月廿九。"},{"id":78,"type":"判断题","text":"古人用干支纪年、纪月、纪日，如甲子、乙丑等，一个循环下来共有六十种排列组合。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"简化后的天干地支：“甲、乙、丙、丁、戊、己、庚、辛、壬、癸”称为十天干，“子、丑、寅、卯、辰、巳、午、未、申、酉、戌、亥”称为十二地支。\n十天干和十二地支依次相配，组成六十个基本单位，两者按固定的顺序相互配合，组成了干支纪元法。天干地支的发明影响深远，依旧在使用天干地支，用于历法、术数、计算、命名等各方面。"},{"id":79,"type":"判断题","text":"古人用十二地支纪时，其中子时是指23点至1点，辰时是指7点至9点，午时是指11点至13点。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"中国古时把一天划分为十二个时辰，每个时辰相等于现在的两小时。相传古人根据中国十二生肖中的动物的出没时间来命名各个时辰。十二时辰制。西周时就已使用。汉代命名为夜半、鸡鸣、平旦、日出、食时、隅中、日中、日昳、晡时、日入、黄昏、人定。又用十二地支来表示，以夜半二十三点至一点为子时，一至三点为丑时，三至五点为寅时，依次递推。"},{"id":80,"type":"判断题","text":"古人拿十二种动物配十二地支，寅为虎，午为马，戌为狗。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"子鼠，丑牛，寅虎，卯兔，辰龙，巳蛇，午马，未羊，申猴，酉鸡，戌狗，亥猪。"},{"id":81,"type":"判断题","text":"二十四节气中排第一的立春，排最后的是除夕。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"除夕不是二十四节气里的，排最后的是大寒。"},{"id":82,"type":"判断题","text":"农历每月的第一天叫“朔”，最后一天叫“晦”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"出自《汉书·李寻传》：“朔晦正终始，弦为绳墨，望成君德，春夏南，秋冬北。”"},{"id":83,"type":"判断题","text":"公历纪元是目前世界上最通用的纪年，它是在公元1世纪逐渐流行开来的。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"公历纪元是目前世界上最通用的纪年。相传在约公元532年时，基督教修道士迪奥尼修斯·埃克西鸠厄斯推算出，耶稣诞生于532年前，即罗马纪元754年，应以次年作为耶稣诞生后第533年，从此在欧洲基督纪元与罗马纪元并行。到15世纪基督纪元逐渐代替了罗马纪元。"},{"id":84,"type":"判断题","text":"古人把每个季节三个月顺次称为孟、仲、季，仲夏就是夏季的第二个月。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"一年十二个月依次为：孟春、仲春、季春，孟夏、仲夏、季夏，孟秋、仲秋、季秋，孟冬、仲冬、季冬。"},{"id":85,"type":"判断题","text":"《五经正义》是唐代孔颖达奉命主持编订的。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《五经正义》是唐代孔颖达等奉敕编写的五经义疏著作。该作品于唐高宗时成书，完成了五经内容上的统一。"},{"id":86,"type":"判断题","text":"东曦，古代神话中太阳神的名字叫曦和，驾着六条无角的龙拉的车子在天空驰骋。东曦指初升的太阳。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"出自《促织》：“东曦既驾，僵卧长愁。”"},{"id":87,"type":"判断题","text":"山东，山可指崤山、华山、太行山、泰山等数种不同的山，而所指地域不尽相同。大多是以崤山为标准的“山东”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"山东，作为一个地理区域的名称，最早始于战国时期，当时秦人称崤山、函谷关以东的地区为“山东”，为一个地域性的泛称。由于战国七雄之中，除秦国以外的韩、赵、魏、齐、楚、燕六国都在崤函以东，故也有“山东六国”之称。"},{"id":88,"type":"判断题","text":"关东，函谷关或潼关以东地区，近代指山海关以东的东北地区；关西，函谷关或潼关以西地区；关中，古人习惯上将函谷关以西地区称为关中；关内，山海关以西或嘉峪关以东一带地区；关外，山海关以东或嘉峪关以西或居庸关以北一带地区。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"关东出相指函谷关以东的地区多出宰相，典出《晋书·姚兴载记》。秦汉时普遍用地处崤山谷地的函谷关、大散关作为区分东、中、西三大地域的界标，分别称关东、关中、关西。以上等等表明秦汉关东由来。"},{"id":89,"type":"判断题","text":"“朔漠”原指北方沙漠地带，有时也泛指北方。古代越族居住在江、浙、闽、粤各地，各部落各有名称，而统称“百粤”，也叫“百越”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"出自《后汉书·袁安传》：“今朔漠既定，宜令南单于反其北庭。”"},{"id":90,"type":"判断题","text":"“中原”即中州、中土，是区别于边疆地区的说法。狭义指今河南及其附近地区；广义指黄河中下游地区或整个黄河流域。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"陆游《示儿》“王师北定中原日”中的“中原”特指当时沦陷于金人的淮河以北地区。"},{"id":91,"type":"判断题","text":"三辅，西汉时本指治理京畿地区的三位官员，后指这三位官员管辖的地区。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《张衡传》：“衡少善属文，游于三辅。”"},{"id":92,"type":"判断题","text":"古代的“河”专指黄河，“江”专指“长江”，所以《鸿门宴》里“将军战河南”的“河南”是指“黄河以南的地区”，不是今天所说的“河南省”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《过秦论》：“然后践华为城，因河为池。”"},{"id":93,"type":"判断题","text":"曾使“洛阳纸贵”的作品是曹植的《洛神赋》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为左思的《三都赋》。"},{"id":94,"type":"判断题","text":"根据“上北下南，左西右东”的地理常识推断，古代的“江左”是指长江以西的地区。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"古代的政治中心在北方，君王坐北朝南，其左边是东，因此，江左是指长江以东一带。"},{"id":95,"type":"判断题","text":"古代以中原为中心，人们将处于东、西、南、北方的少数民族分别称为东夷、西戎（西羌）、南蛮（南闽）、北狄，有鄙视之意。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《礼记王制》：“东曰夷、西曰戎、南曰蛮、北曰狄”。"},{"id":96,"type":"判断题","text":"“路”是宋代时期区域的名称，与今天的省区大致相似，如福建路、广东路。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"无论在唐代、宋朝，还是五代十国、辽国和金国，道或路是最高行政区划单位始终没有变。"},{"id":97,"type":"判断题","text":"“夫运筹帷幄之中，决胜千里之外，吾不如子房”，最早出自《史记·汉高祖本纪》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"出自西汉·司马迁《史记·高祖本纪》：“夫运筹策帷幄之中，决胜于千里之外，吾不如子房。”"},{"id":98,"type":"判断题","text":"中国古代历代各级官府都会直接举办和管理学校，称为“官学”。由政府提供“廪膳”，选派教师，指定教材，监选生员。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"“官学”与“私学”相对，分中央官学和地方官学。其中朝廷直接举办和管辖的属中央官学，如唐代的国子学、大学、四门学、弘文馆、崇文馆，元明清的太学、国子监等。"},{"id":99,"type":"判断题","text":"在宋代，主管教育的行政机关称为“国子监”，同时又是国家最高学府。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"国子监，中国古代最高学府和教育管理机构。晋武帝司马炎始设国子学，至隋炀帝时，改为国子监。唐、宋时期，国子监作为国家教育管理机构，统辖其下设的国子学、太学、四门学等，各学皆立博士，设祭酒一人负责管理。"},{"id":100,"type":"判断题","text":"我国古代藏书、校书、讲学的地方称为“书院”，主要是校勘经典、辨明典章、收罗人才。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"书院始于唐代，宋代书院大兴。以白鹿洞、石鼓、应天府、岳麓四大书院最为著名。"},{"id":101,"type":"判断题","text":"中国科举时代，学校里的幼童称为“童生”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"明清科举考试，凡考试未合格，没被称为秀才以前，无论年龄大小，都称为童生，又称文童、儒童。"},{"id":102,"type":"判断题","text":"古代向朝廷荐举人才，泛称贡士，唐以后亦称科举制度为贡举。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"清代科举中参加会试被录取者称为贡士，其第一名称会元。贡士均需参加殿试，殿试后根据成绩排名，由皇帝赐予进士出身。"},{"id":103,"type":"判断题","text":"“其曲弥高，其和弥寡”是屈原的名句。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“其曲弥高，其和弥寡”出自宋玉。"},{"id":104,"type":"判断题","text":"班固作《汉书》时删去《史记·大宛传》，不再为西域少数民族专门立传。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"《汉书》继承《史记》为少数民族专门立传的优良传统，运用新史料将《史记·大宛传》扩充为《西域传》，叙述了西域几十个地区和邻国的历史以补充，增补了大量汉武帝以后的史实。"},{"id":105,"type":"判断题","text":"《诗经》中的“雅”分为小雅和大雅，主要分别作于西周初期和晚期。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"时间对应相反。"},{"id":106,"type":"判断题","text":"公车，官府的马车。古代臣民上书或被征召，都由官府的马车接送。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“公车”是汉代官署名，负责接待臣民，非接送臣民。"},{"id":107,"type":"判断题","text":"“振恤”，即赈济与抚恤，即面对灾荒来袭时，各级政府和民间做的相应的反应和对策。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"振恤，“振”通“赈”，即赈济与抚恤的意思，并且偏重于安抚。出自《吕氏春秋·怀宠》。"},{"id":108,"type":"判断题","text":"“介”指古代战士带的帽子，“胄”指用来防身的一种武器，即铠甲。介胄分别指头盔和铠甲。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"对“介”和“胄”的解释全部颠倒了，前者指铠甲，后者指头盔。"},{"id":109,"type":"判断题","text":"大学是我国古代的最高学府，有时也是教育行政机构。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应该是“太学”或“国子监”。"},{"id":110,"type":"判断题","text":"博士和教授都是指古代的学者或博学多才之人，与官职没有任何关系。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“博士”是秦汉时掌管书籍文典、通晓史事的官职，“教授”一开始也是学官名。"},{"id":111,"type":"判断题","text":"征辟是汉代选拔官吏的一种形式。“征”一般是皇帝亲自征聘人才，“辟”则大多数是由中央高官或地方政府向朝廷推荐人才。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《后汉书·庾乘传》：“﹝ 乘 ﹞后徵辟并不起，号曰：‘徵君’。"},{"id":112,"type":"判断题","text":"古代科举考试，由低级到高级一般经历以下四个阶段：院试、会试、乡试、殿试。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"由低级到高级一般经历以下四个阶段：院试、乡试、会试、殿试。"},{"id":113,"type":"判断题","text":"“风骚”：风，《诗经》里的“国风”；骚，《楚辞》里的“离骚”。后来用“风骚”借指文采。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《宋书·谢灵运传论》：“原其飇流所始，莫不同祖《风》《骚》。"},{"id":114,"type":"判断题","text":"《左传》，我国第一部叙事详备的编年体史书。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"作品原名为《左氏春秋》，汉代改称《春秋左氏传》、《春秋内传》、《左氏》，汉朝以后多称《左传》。它是儒家重要经典之一，是历代儒客学子重要研习史书。"},{"id":115,"type":"判断题","text":"《史记》，我国第一部纪传体断代史。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"是第一部纪传体通史。"},{"id":116,"type":"判断题","text":"“姬”姓，中华上古八大姓之一，得姓始祖为华夏民族的人文初祖--黄帝，黄帝因长居姬水，以姬为姓。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"姬姓，中华上古八大姓之一，为黄帝之姓、周朝的国姓。春秋战国时代的姬姓诸侯国有吴国、鲁国、燕国、卫国、晋国、郑国、曹国、蔡国，有近5000年历史。姬姓的得姓始祖为华夏民族的人文初祖——黄帝，黄帝因长居姬水，以姬为姓。"},{"id":117,"type":"判断题","text":"二十四史：从《史记》到《清史》的二十四部纪传体史书。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"是从《史记》到《明史》，清代只有《清史稿》。"},{"id":118,"type":"判断题","text":"《汉书》，又名《前汉书》，东汉班固所著，是中国第一部纪传体断代史。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《汉书》全书主要记述了上起汉高祖元年（公元前206年），下至新朝王莽地皇四年（公元23年）共230年的史事。《汉书》包括纪十二篇，表八篇，志十篇，传七十篇，共一百篇，后人划分为一百二十卷，全书共八十万字。"},{"id":119,"type":"判断题","text":"“经史子集”是中国古籍按内容区分的四大部类。经，指儒家经典著作；史，即正史。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"“经史子集”是古代人将古籍按内容区分的四大部类。一些大型的古籍丛书往往囊括四部，并用以命名，如《四库全书》、《四部丛刊》、《四部备要》等，可见四部分类对古籍的重要意义。经：经书，是指儒家经典著作；史：史书，即正史；子：先秦百家著作，宗教；集：文集，即诗词汇编。泛指我国古代典籍。出处：《新唐书·艺文志一》：“两都各聚书四部，以甲乙丙丁为次，列经史子集四库。"},{"id":120,"type":"判断题","text":"冠冕是贵族男子的头衣，平民男性的头发则以头巾为主，贵族则在冠之下附巾。如葛巾、幅巾、纶巾等。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"贵族男子二十岁行冠礼，在亲人和乡贤的祝福下，将头发梳起来，并带上冠固定头发，从此就是成年人了。男子年满二十称为“弱冠”。"},{"id":121,"type":"判断题","text":"人们常用“数九寒天”来指冬天天气最冷的时候。“数九”是从立冬开始，到立春结束。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“是从立冬开始”错。应从“冬至”开始。数九又称冬九九，是一种中国民间节气。数九从每年阳历12月下旬冬至开始。"},{"id":122,"type":"判断题","text":"古代将上下身分为两件的衣服总称“衣裳”，这里的“衣”和“裳”是两个词，“衣”指上身的衣服，“裳”指下身的衣服，也叫“裙”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"女子服饰中，短上衣叫“襦”。把裙子穿在襦外面，就成了襦裙。在裙子外面又加了一件上衣叫作“袄”，以袄掩裙，袄可长可短，在明代最为常见。"},{"id":123,"type":"判断题","text":"短褐，用麻或毛捻成线编织的粗衣，不但重，无光华，而且不暖。对地位低下的人来说，则为平时所穿，因此“短褐”成了平民的标志。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《荀子·大略》“衣则竖褐不完”。"},{"id":124,"type":"判断题","text":"袖，又称“袂”，古语“联袂”就是连在一起拉着手的意思。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"“联袂”是一同做某件事的意思。“挥袂”则是挥手的意思。由此可见，古代常常用“袂”来代指手。"},{"id":125,"type":"判断题","text":"黔首，以黑巾裹头，代指平民，即本业为农业与小手工业，末业为小商贾等各种不事生产的人。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"秦始皇时期开始作为官方辞令使用。“分天下以为三十六郡，郡置守、尉、监。更名民曰‘黔首’”（《史记·秦始皇本纪》），含义与当时常见的民、庶民同。"},{"id":126,"type":"判断题","text":"白丁，古代平民着白衣，故常以“白丁”称呼平民百姓；布衣、麻衣，借指平民。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"平民不能衣锦绣，多穿布衣。布衣之交，即贫贱之交。"},{"id":127,"type":"判断题","text":"青衫，黑色的单衣。唐代官职低的服色为青黑色。后人也常用“司马青衫”形容悲伤凄切。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"白居易《琵琶行》诗：“座中泣下谁最多，江州司马青衫湿。”"},{"id":128,"type":"判断题","text":"“笏”又称“笏板”，当纸张还没有发明的时候，文字都记录在上面，上朝的时候可以提醒自己重要的事情。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"缙绅，插笏于绅带间，旧时官宦的装束，亦借指士大夫。"},{"id":129,"type":"判断题","text":"“席”是跪坐时用的垫子。这是由于最初中国人是席地而坐的，坐的时候，比较庄重的坐姿是跪坐。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《诗经·邶风·柏舟》：“我心匪席，不可卷也。”"},{"id":130,"type":"判断题","text":"“鼎”用于煮肉和盛肉。鼎有圆形三足和方形四足两种，现存的鼎中，最著名的要数司母戊鼎。青铜鼎非常贵重，非大贵族不能使用。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"商后母戊鼎，又称司母戊鼎、司母戊大方鼎，是商后期（约前十四世纪至前十一世纪）铸品，于1939年出土于河南省安阳市武官村。"},{"id":131,"type":"判断题","text":"“箪”是一种像小筐的竹器，古代用它来盛饭。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"一箪食，一豆羹，得之则生，弗得则死。——《孟子·告子上》"},{"id":132,"type":"判断题","text":"按照一般说法，“五谷”是指稷（小米）、黍（黍子）、麦（大麦小麦）、菽（豆）、麻（大麻子）。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"平常俗称的“五谷”所指的五种谷物。“五谷”，古代有多种不同说法，最主要的有两种：一种指稻、黍、稷、麦、菽；另一种指麻、黍、稷、麦、菽。两者的区别是：前者有稻无麻，后者有麻无稻。古代经济文化中心在黄河流域，稻的主要产地在南方，而北方种稻有限，所以“五谷”中最初无稻。"},{"id":133,"type":"判断题","text":"“荤”本意是指葱、蒜等辛臭的蔬菜，后来指部分动物性食物，如鸡、鸭、鱼等。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"荤，臭菜也。――《说文》"},{"id":134,"type":"判断题","text":"在中国周代，马车就已经在一定程度上得到普及。根据马的数量，可以对车有不同的称呼：骈就是两匹马拉车，骖就是三匹马拉车，驷就是四匹马拉车。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"据说“天子驾六”，只有天子才能乘坐六匹马拉的车子。由于四马拉车最为常见，所以用“驷”来代指马车。“一言既出，驷马难追”表示说出口的话，即使是驾着四匹马拉的车子也无法追回来。"},{"id":135,"type":"判断题","text":"古代的轿子叫肩舆或腰舆，其区别是肩舆上肩抬，而腰舆抬在腰间。最早叫“辇”，本来是人推的车，后来成为专用的车或者轿子。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"杜牧《阿房宫赋》中说别国的王孙公主被“辞楼下殿，辇来于秦”，可见当时的辇还不是皇帝专用。"},{"id":136,"type":"判断题","text":"最初的田猎是一种非常严肃的军事和祭祀活动，后来田猎的制度消失，对贵族们来说，打猎成了休闲活动。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"出自田猎于此。——《孟子·梁惠王下》"},{"id":137,"type":"判断题","text":"刺配：脸上刺了字，发放送往远地充军。刺，即黥刑，在罪犯额面或肌肤上刺上字，用墨染上颜色；配，发往远地充军。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"黥刑又称墨刑，以刀刻凿人面体再用墨涂在刀伤创口上，使其永不褪色。汉以前，墨刑主要施于犯人面、额之上，适用于较轻的罪犯；以后，墨刑间或有之，主要用于逃奴、窃盗和辅助刑。"},{"id":138,"type":"判断题","text":"刖刑，又称剕刑，指砍去受罚者左脚、右脚或双脚的酷刑。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"从膑刑演变而来。膑刑是去掉犯人的膝盖骨，犯人受膑刑后不能行走，受刖刑即断足后，装上假肢仍可行走，故刖刑轻于膑刑。"},{"id":139,"type":"判断题","text":"笞刑，用竹板或荆条打人背部或臀部。笞刑打十至五十下。杖刑，用大荆条、大竹板或棍棒抽击人的背、臀或腿部。杖刑打五十至一百下。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"以竹、木板等拷打犯人臀部、背部或大腿的轻刑。始于战国时期，是古代“五刑”之一。针对轻微犯罪而设，或作为减刑后的刑罚。"},{"id":140,"type":"判断题","text":"戮刑，戮有羞辱和耻辱之意。戮刑视为奇耻大辱。戮分为生戮和死戮。生戮即先将犯人示众，然后再杀死；死戮是先将人杀死，然后再陈尸示众。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《旧唐书 酷吏传》记载：公元694年（武则天长寿二年）唐侍御史 “（万）国俊至广州，遍召流人，置于别所，矫制赐自尽，并号哭称冤不服。国俊乃引出，拥之水曲，以次加戮，三百余人，一时并命。” 这三百余人当是生戮。"},{"id":141,"type":"判断题","text":"从层次角度区分，中国传统文化的主文化为物质文化与精神文化。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"主文化是在一个社会中处于支配地位的正统文化，也可以称之为主流文化。比如在中国的传统社会中，儒家文化就是那一时期占统治地位的主流文化，统治者依靠儒家文化的传播来统一民众的思想。在不同的历史时期，一个社会的主文化也会随着时代的变迁而有所不同。而中国传统文化的主文化为物质文化与精神文化。"},{"id":142,"type":"判断题","text":"四大发明中，从起源到完成，经历时间最长的一项是造纸术。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为指南针。"},{"id":143,"type":"判断题","text":"“龙媒”是指给人做媒。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为一种好马。"},{"id":144,"type":"判断题","text":"古代武状元考试，武试中打鼓考核最为重要。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为射箭。"},{"id":145,"type":"判断题","text":"中国的十二生肖是子鼠、丑牛、寅虎、卯兔、辰龙、巳蛇、午马、未羊、申猴、酉鸡、戌狗、亥猪。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"中国的十二生肖，又叫十二属相，是中国与十二地支相配以人的出生年份的十二种动物，包括鼠、牛、虎、兔、龙、蛇、马、羊、猴、鸡、狗、猪。"},{"id":146,"type":"判断题","text":"茶正式作为普及民间的大众饮品是在明朝。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为唐朝。"},{"id":147,"type":"判断题","text":"八股文的写作步骤为破题、承题、起讲、入手、起股、中股、后股、束股。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"八股文就是指文章的八个部分，文体有固定格式:由破题、承题、起讲、入题、起股、中股、后股、束股八部分组成，题目一律出自四书五经中的原文。后四个部分每部分有两股排比对偶的文字，合起来共八股。旧时科举，八股文要用孔子、孟子的口气说话，四副对子平仄对仗，不能用风花雪月的典故亵渎圣人，每篇文章包括从起股到束股四个部分。"},{"id":148,"type":"判断题","text":"汉字六书是象形、指事、形声、会意、转注、假借 。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"六书，汉字的六种造字方法: 象形、 指事、 形声、 会意、 转注、 假借， 其中象形、指事、会意、形声主要是“造字法”，转注、假借是“用字法”。"},{"id":149,"type":"判断题","text":"与《梅花谱》并列为两大中国象棋传世古谱之一的是《自出洞来无敌手》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为《橘中秘》。"},{"id":150,"type":"判断题","text":"现行的二十四节气是刘安创立的。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"二十四节气是中国古代人民的伟大发明创造，它最早完整、科学的记载，出自西汉时期淮南王刘安的《淮南子·天文训》。"},{"id":151,"type":"判断题","text":"西安兵马佣的主人是秦始皇。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为秦宣太后。"},{"id":152,"type":"判断题","text":"明代纯以彩色在熟纸绘绢上作写意的画家是孙隆。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"孙隆，又名龙，字廷振，号都痴，毗邻人（今常州人），明开国忠敏侯孙兴祖之孙。大概与林良同时期画家，为宣德年间宫廷重要画家。擅画翎毛、虫草，不作墨线，纯以色彩点染而成，谓之“没骨“，别具一格。亦善山水。画翎毛草虫，全以彩色渲染，生动鲜活，饶有机趣，自成一家，对后代影响很大。"},{"id":153,"type":"判断题","text":"我国有句古语，斗柄东指，天下皆春，在春夏秋冬中，北斗七星的斗柄依次指向东南西北。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"北斗七星的斗柄依次指向东南西北。"},{"id":154,"type":"判断题","text":"地雷最早出现在唐朝。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为明朝。"},{"id":155,"type":"判断题","text":"以《谏逐客书》为代表的李斯散文最鲜明的特色是流畅谐偶。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为铺陈排比。"},{"id":156,"type":"判断题","text":"认为天与人之间是“交相胜，还相用”的关系的思想家是王勃。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为刘禹锡。"},{"id":157,"type":"判断题","text":"“冻吟可但笔锋健，醒狂不觉屐齿折”其中“不觉屐齿折”这个典故来源于采石之战。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为淝水之战。"},{"id":158,"type":"判断题","text":"素有“世界屋脊”之称的是藏族。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"藏族被称为世界屋脊的民族，因为他们生活在青藏高原。"},{"id":159,"type":"判断题","text":"相传我国古代能作“掌上舞”的人是貂蝉。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为赵飞燕。"},{"id":160,"type":"判断题","text":"“吾师心，心师目，目师华山”是由赵原提出的。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为王履。"},{"id":161,"type":"判断题","text":"《八仙过海》中，张果老是骑在驴背上过海的。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"张果老是骑着驴背过河的。"},{"id":162,"type":"判断题","text":"记载食物疗法的《食疗本草》出自唐朝。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《食疗本草》是唐前饮食疗法和营养学的本草专著，出自唐朝。"},{"id":163,"type":"判断题","text":"庖丁解牛中的“庖丁”指的是厨师。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"庖丁解牛比喻经过反复实践，掌握了事物的客观规律，做事得心应手，运用自如"},{"id":164,"type":"判断题","text":"词的别称有长短句、诗余。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"南宋以后，文人称词为诗余。作词要求典雅纯正，避用艳丽的词藻、婉约的内容、粗俗的格调，运用诗的清空雅正语言及风格，故称词为诗余"},{"id":165,"type":"判断题","text":"律诗偶数句押平声韵，每句平仄皆有规定，每篇必有对仗。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"平仄，是中国诗词中用字的声调。“平”指平直，“仄”指曲折。根据隋朝至宋朝时期修订的韵书，如《切韵》《广韵》等，中古汉语有四种声调，称为平、上、去、入。除了平声，其余三种声调有变化，故统称为仄声。"},{"id":166,"type":"判断题","text":"国画是我国传统的美术形式，我国存世最早最完整的国画作品是周昉的《簪花仕女图》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为顾恺之的《女史箴图》。"},{"id":167,"type":"判断题","text":"泼水节是苗族的节日。每逢新年，人们都互相泼洒洁净的水，表示 除污秽，迎接吉祥幸福的新年。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"泼水节，是中国傣族、阿昌族、布朗族、佤族、德昂族等少数民族和中南半岛某些民族的新年节日。为傣族一年中最盛大的传统节日。中国傣族节期在傣历六七月(清明节后十日左右)。现已固定在公历4月13至15日。节日期间，人们相互泼水祝福，并举行拜佛、赛龙舟、放高升、点孔明灯等活动"},{"id":168,"type":"判断题","text":"陆机被称为“太康之英”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"中国文学史上,被称作“太康之英”的是陆机。"},{"id":169,"type":"判断题","text":"中国古代小说源远流长，小说在唐代叫做话本。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为传奇。"},{"id":170,"type":"判断题","text":"《贵妃醉酒》、《杜十娘》、《琐麟囊》、《梁红玉》依次是梅兰芳、程砚秋、荀慧生、尚小云的代表作。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"杜十娘是明代冯梦龙所著《警世通言·杜十娘怒沉百宝箱》中的女主人公；《锁麟囊》是翁偶虹根据《剧说》中一则引自《只麈谭》的故事创作剧本，程砚秋设计唱腔、排演的京剧剧目。"},{"id":171,"type":"判断题","text":"中国传统屋顶主要有六种形式：悬山顶、硬山顶、庑殿顶、歇山顶、攒尖顶、卷棚顶，其中以悬山顶为级别最高。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"重檐庑殿顶是古代建筑中最高级的屋顶样式。"},{"id":172,"type":"判断题","text":"六子全书有《老子》、《庄子》、《列子》、《荀子》、《孟子》、《文中子中说》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"《六子全书》六十卷，明顾春编，嘉靖十二年（1533）顾春世德堂刻本，二函十四册，钤印为“五老峰主人”和“钬坚所藏”。“六子”即为老子《道德经》二卷，《南华真经》十卷、《冲虚至德真经》八卷，《荀子》二卷、《新纂门目五臣音注扬子法言》十卷，《中说》十卷。"},{"id":173,"type":"判断题","text":"我国现存年代最早的一首用文字谱记写的琴曲是《碣石调·幽兰》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《碣石调·幽兰》是至今仅存的一首用原始文字谱保留下来的琴曲,据传是梁代琴家丘明所传的一首古琴曲,现收录在《神奇秘谱》中的是唐人的手抄本,是现存最早的古琴曲谱。"},{"id":174,"type":"判断题","text":"唐代有一种诗叫“长吉体”，开创“长吉体”诗歌的是李白。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"开创长吉体诗歌的是唐代著名诗人李贺。李贺，字长吉，李贺的诗作想象极为丰富，经常应用神话传说来托古寓今，所以有“诗鬼”之称。长吉体指唐元和年间诗人李贺的诗作所独有的风格意境。长吉体诗在思想构造上面善于运用神话传说和怪诞、华美的语汇，创造出异想天开、从未有过的意象。"},{"id":175,"type":"判断题","text":"八个样板戏：《沙家浜》、《红灯记》、《西厢记》、《海港》、《奇袭白虎团》、《红色娘子军》、《白毛女》、《沙家浜》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“京剧《红灯记》《智取威虎山》《沙家浜》《海港》《奇袭白虎团》，芭蕾舞剧《红色娘子军》《白毛女》，交响音乐《沙家浜》”。"},{"id":176,"type":"判断题","text":"九流：儒家、道家、阴阳家、法家、名家、墨家、评论家、杂家、农家。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"九流，秦至汉初的九大学术流派。在《汉书·艺文志》指：道家、儒家、阴阳家、法家、农家、名家、墨家、纵横家、杂家。"},{"id":177,"type":"判断题","text":"杂剧在元代文学中有突出的地位，代表作有关汉卿的《窦娥冤》、王实甫的《西厢记》、孔尚任的《桃花扇》和马致远的《汉宫秋》等。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"孔尚任的《桃花扇》是清代代表作。"},{"id":178,"type":"判断题","text":"钟惺《浣花溪记》中所写的浣花溪位于现在的甘肃天水，","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为四川成都。"},{"id":179,"type":"判断题","text":"所谓从“笔尖下发现的行星”指的是冥王星。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为海王星。"},{"id":180,"type":"判断题","text":"我国的第一位女诗人是朱淑真。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"中国第一位女诗人是：蔡琰（文姬）。"},{"id":181,"type":"判断题","text":"清代苏南已经开始试种双季稻，一年三熟。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"清代苏南已经开始试种双季稻, 一年三熟,充分运用了江南气候条件。"},{"id":182,"type":"判断题","text":"杜甫是我国文学史上诗作留存最多的大诗人。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为陆游。"},{"id":183,"type":"判断题","text":"《洛神赋》的作者曹植是建安时期成就卓著的作家。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"《洛神赋》是三国时期曹魏文学家曹植创作的辞赋。"},{"id":184,"type":"判断题","text":"传说，盘古用斧头开辟了天地。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"南朝萧梁的任昉撰的《述异记》称盘古身体化为天地各物。《五运历年纪》及《古小说钩沉》辑的《玄中记》亦有类似记载。"},{"id":185,"type":"判断题","text":"“尊长前，声要低。低不闻，却⾮宜”出⾃《⼩⼉语》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"出⾃《弟⼦规》。"},{"id":186,"type":"判断题","text":"很多有关动物的⽂字，如“鱼”“龟”“鸟”“⽺”，都是象形字，最初是按照动物的样⼦描画下来的。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"象形字，是描摹事物外形特征的表意文字。它纯粹利用图形来作文字使用，而这些文字又与所代表的东西，在形状上很相像。象形字是最早产生的文字。它用文字的线条或笔画，把要表达物体的外形特征，具体地勾画出来。"},{"id":187,"type":"判断题","text":"“迟⽇江⼭丽，春风花草⾹”中“迟日”指的是迟到的太阳。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"迟⽇：春天⽇渐长，所以说迟⽇。"},{"id":188,"type":"判断题","text":"古代夏至时，百姓们会将冬季窖藏的冰块取出使用，以便消暑。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"只有皇宫才会有⽤冰的条件。"},{"id":189,"type":"判断题","text":"传说中⽉亮⾥包着⼀只⾦⾊的、三条腿的乌鸦，所以⽉亮⼜被称为“金乌”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"太阳被称为“金乌”。"},{"id":190,"type":"判断题","text":"炎帝⼜被⼈们尊称为“五⾕先帝”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"炎帝制耒耜，种五谷，奠定了农工基础。耒耜的使用和种五谷，解决了民以食为天的大事，促进了农业生产的发展，为人类由原始游牧生活向农耕文明转化创造了条件。"},{"id":191,"type":"判断题","text":"夏⾄后⽓温继续升⾼，⼤约再过⼆⼗多天，便会进⼊三伏天，这是夏季最凉爽的时段。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"三伏天是⼀年中最热的时段。"},{"id":192,"type":"判断题","text":"《官仓⿏》（官仓⽼⿏⼤如⽃，见⼈开仓亦不⾛。健⼉⽆粮百姓饥，谁遣朝朝⼊君⼝）⼀诗只是表达了诗⼈对官仓管理不善、到处都有⽼⿏偷吃粮⾷现象的不满。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"诗⼈借官仓管理不善，对贪官污吏进⾏讽刺。"},{"id":193,"type":"判断题","text":"“兄道友，弟道恭。兄弟睦，情在中”出⾃《弟⼦规》，告诉我们要与兄弟姐妹和睦相处。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"原⽂为“兄道友，弟道恭。兄弟睦，孝在中。”"},{"id":194,"type":"判断题","text":"《鸟鸣涧》的作者是唐代诗⼈⽩居易。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"作者是王维。"},{"id":195,"type":"判断题","text":"点苍⼭亦称“灵鹫⼭”，⼜称“灵⼭”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"⼜称“苍⼭”。在云南省⼤理市西北、洱海及漾濞江间，北起洱源，南⽌下关，绵延50多千⽶。"},{"id":196,"type":"判断题","text":"传说中⽤⼸箭射落九个太阳的神仙是仓颉。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为后羿。"},{"id":197,"type":"判断题","text":"传说中民族的始祖是炎帝，⼜称神农。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"炎帝，是中国上古时期姜姓部落的首领尊称，号神农氏，又号魁隗氏、连山氏、列山氏，别号朱襄（尚有争议，也有说朱襄氏部落曾有三代首领尊号炎帝）。"},{"id":198,"type":"判断题","text":"夸⽗是传说中追赶太阳的巨⼈。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"夸父是中国上古时期神话传说人物之一，又名博父、举父，夸父是幽冥神、地母后土（厚土娘娘）的孙儿。"},{"id":199,"type":"判断题","text":"腊祭是中国传统的祭祀活动，把捕猎所得献给神灵或祖先亡灵，祈求丰收吉祥。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"腊祭，是历史悠久的民间传统祭祀文化，指在新旧交接的岁末十二月举行的祭祀。"},{"id":200,"type":"判断题","text":"张骞出使西域，经过艰苦跋涉，终于找到了⼤⽉⽒国，和他们⼀起结盟，联合起来抗击了匈奴。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"张骞找到了⼤⽉⽒国，⼤⽉⽒⼈已经过上了安居乐业的⽣活，不再想报仇了。"},{"id":201,"type":"判断题","text":"⽩居易，字乐天；李⽩，字太⽩；杜甫，字务观。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"杜甫，字⼦美。"},{"id":202,"type":"判断题","text":"《拳经捷要篇》是郑成功的著作。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"《拳经捷要篇》是明代抗倭名将戚继光所著。"},{"id":203,"type":"判断题","text":"围棋标准棋盘纵横各有15条线，棋⼦分⿊⽩两⾊，⿊⼦先，⽩⼦后，轮流下⼦。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"围棋标准棋盘纵横各有19条线。"},{"id":204,"type":"判断题","text":"1957年，南京龙江船⼚遗址出⼟了长11⽶的郑和宝船⼤舵杆。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"另据造船史家杨的推算，则船长为 57米。一艘长 57米的海船的排水量为1200吨左右，比起葡萄牙航海家达·伽马所用的 300吨的船以及哥伦布所用 280吨的旗舰都大得多。"},{"id":205,"type":"判断题","text":"郭守敬组织开挖了“通惠河”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"通惠河不仅是北京的一条经济命脉，而且也是京城著名的风景游览区，通惠河主要位于通州区和朝阳区。"},{"id":206,"type":"判断题","text":"宋应星每次去京城参加会试的路上，都会到沿途的作坊、⽥间等劳动现场，观察各⾏各业的⼯作⽅法和流程。正因如此， 他才会在会试中取得第⼀名的好成绩。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"宋应星⼏次到京城参加会试，却⼀次⼜⼀次落榜了。"},{"id":207,"type":"判断题","text":"在那达慕⼤会上，赛马分为奔马赛和⾛马赛，奔马赛⽐的是速度，⾛马赛⽐的是马匹的外表。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"⾛马赛⽐的是技巧。"},{"id":208,"type":"判断题","text":"蚕眠之前的叶子不宜湿，蚕眠之后的叶子却要湿润，蚕吐出的丝才鲜亮。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"我国珠江三角洲地区盛产蚕丝，我国的蚕丝主要产地除珠江三角洲外，还有华东平原和四川盆地。"},{"id":209,"type":"判断题","text":"《观书有感》（半亩方塘一鉴开）是一首借景寓理的诗，这首诗的作者是北宋著名的哲学家、文学家朱熹。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应该是南宋。"},{"id":210,"type":"判断题","text":"“姑苏城外寒山寺，夜半钟声到客船”出自张继的《枫桥夜泊》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"月落乌啼霜满天，江枫渔火对愁眠。\n姑苏城外寒山寺，夜半钟声到客船"},{"id":211,"type":"判断题","text":"“一带一路”指的是丝绸之路经济带和21世纪海上丝绸之路。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"“一带一路”是“丝绸之路经济带”和“21世纪海上丝绸之路”的简称，2013年9月和10月由中国国家主席习近平分别提出建设“新丝绸之路经济带”和“21世纪海上丝绸之路”的合作倡议"},{"id":212,"type":"判断题","text":"“半亩方塘一鉴开，天光云影共徘徊”中，“鉴”的意思是镜子，形容水很清澈。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"半亩大的方形池塘像一面镜子一样展现在眼前，天空的光彩和浮云的影子都在镜子中一起移动。"},{"id":213,"type":"判断题","text":"古代把山南水北称为“阳”，洛阳坐落于洛河北岸，因此得名。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"由于我国大部分地区都位于北回归线以北，太阳直射点始终位于北回归线以南，阳光主要从南方照向北方，南坡为阳坡，南面能够得到更多的太阳辐射，获取更多的热量。因此山南为阳，山北为阴"},{"id":214,"type":"判断题","text":"古人为了使铜钱不乱转，将铜钱中间开出方孔，所以后来人们把铜钱戏称为“孔方兄”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"古代的铜钱是一种辅币，一千个为一贯。在铸造时为了方便细加工，常将铜钱穿在一根棒上，为了在加工铜钱时铜钱不乱转，所以将铜钱当中开成方孔。后来人们就称钱为“孔方兄”，有时候寓指拜金主义"},{"id":215,"type":"判断题","text":"“兵藏武库，马入华山”一般用来形容天下太平。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"北周·庚信《贺平邺都表》：“当今鹿台已散，离宫已遗，兵藏武库，马入华山。"},{"id":216,"type":"判断题","text":"漏壶是古代的一种盛水工具，常常用来测量水量。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"漏壶是一种古代的计时工具。"},{"id":217,"type":"判断题","text":"汉服中，左衣襟向右腋掩去，盖住右衣襟，称为“左祍”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应该称为“右祍”。"},{"id":218,"type":"判断题","text":"杜甫草堂位于四川省成都市。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"杜甫草堂，是中国唐代大诗人杜甫流寓成都时的故居，位于四川省成都市青羊区青华路38号。杜甫先后在此居住近四年，创作诗歌240余首。唐末诗人韦庄寻得草堂遗址，重结茅屋，使之得以保存，宋元明清历代都有修葺扩建"},{"id":219,"type":"判断题","text":"杜牧是盛唐时期的诗人。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"杜牧是晚唐时期的诗人。"},{"id":220,"type":"判断题","text":"王维，字摩诘，曾任尚书右丞，世称王右丞。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"王维参禅悟理，精通诗书音画，以诗名盛于开元、天宝间，尤长五言，多咏山水田园，与孟浩然合称“王孟”，因笃诚奉佛，有“诗佛”之称"},{"id":221,"type":"判断题","text":"范成大，北宋诗人，是“中兴四大诗人”之一，他的田园诗尤为著名。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"南宋诗人。"},{"id":222,"type":"判断题","text":"云南省少数民族众多，有白族、彝族、独龙族、哈尼族等。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"全省少数民族人口数超过100万人的有彝族、哈尼族、白族、傣族、壮族、苗族6个；超过10万人不到100万人的有回族、傈僳族、拉祜族、佤族、纳西族、瑶族、景颇族、藏族、布朗族9个；超过1万人不到10万人的有布依族、普米族、阿昌族、怒族、基诺族、蒙古族、德昂族、满族8个；超过6000人不到1万人的有水族、独龙族2个。云南少数民族交错分布，表现为大杂居与小聚居，彝族、回族在全省大多数县均有分布"},{"id":223,"type":"判断题","text":"法家学派的先驱为春秋时期的管仲、子产。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"法家思想渊源可上溯到春秋时的管仲、士匄、子产，而实际的始祖，当推战国初的李悝。此外还有吴起、慎到、申不害、商鞅、韩非子等，均被称为“前期法家”，而以商鞅为前期法家的主要代表人物"},{"id":224,"type":"判断题","text":"作为兵学鼻祖的孙子以自然天论为前提。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"孙武（约前545年－约前470年），字长卿，春秋末期齐国乐安人 [1]  。中国春秋时期著名的军事家、政治家，尊称兵圣或孙子（孙武子），又称“兵家至圣”，被誉为“百世兵家之师”、“东方兵学的鼻祖”"},{"id":225,"type":"判断题","text":"“天人合一”源于奴隶社会的需要。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“天人合一”为中国哲学思想，儒、道、释等诸家各有阐述。天指天空，也指天道，还指自然大道，道家道教所说的天，多指自然、天道。天人合一，多指人与道合而“天地与我并生，万物与我为一”的境界，也指天人相合相应。"},{"id":226,"type":"判断题","text":"道的“无”“恒”“一”“朴”是一切事物原初状态。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"道教继承和发展了先秦道家思想，将“道”作为最高信仰，从中演化出最高经典，最上道术及最高的神灵，构建了庞大的经典道术神仙体系"},{"id":227,"type":"判断题","text":"佛教传入中国后，与儒、道等本土文化碰撞融合，渐成中国文化的重要组成部分。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"佛教于西汉末年传入中国"},{"id":228,"type":"判断题","text":"两汉文学中最有价值的是乐府诗中的民歌。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"汉乐府，是指专门管理乐舞演唱教习的机构。乐府初设于秦，是当时少府下辖中专门管理乐舞演唱教习的机构。\n\n公元前112年，正式成立于西汉汉武帝时期。乐府的职责是采集民间歌谣或文人的诗来配乐，以备朝廷祭祀或宴会时演奏之用。它搜集整理的诗歌，后世就叫“乐府诗“，或简称“乐府“。"},{"id":229,"type":"判断题","text":"中国真正有文字的历史从殷墟甲骨文开始，从此进入信史时代。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"信史时代是指有文字或出土文物记载着当时社会的情况的时代，后人称为信史时代。与它相反的，就是传疑时代或是传说时代。"},{"id":230,"type":"判断题","text":"《孙子兵法》号称“百世谈兵之祖”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《孙子兵法》又称《孙武兵法》、《吴孙子兵法》、《孙子兵书》、《孙武兵书》等，是中国现存最早的兵书，也是世界上最早的军事著作，早于克劳塞维茨《战争论》约2300年，被誉为“兵学圣典”。共有六千字左右，一共十三篇。"},{"id":231,"type":"判断题","text":"程颐制定的《白鹿洞书院学规》是其他众多书院借鉴的范本。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应该为朱熹。"},{"id":232,"type":"判断题","text":"诗句“露从今夜白，月是故乡明”的作者是唐代诗人李白。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应为杜甫。"},{"id":233,"type":"判断题","text":"“小品”多指写作形式固定，篇幅短小精悍，诙谐搞笑的散文文体。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“诙谐搞笑”不正确，“小品”多指写作形式灵活，注重个性和创见的散文文体。"},{"id":234,"type":"判断题","text":"算筹是中国古代的计算工具。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"算筹是中国古代的计算工具,是横截面为圆形、方形或三角形的小棍,使用木、竹、骨等物制成。"},{"id":235,"type":"判断题","text":"南北朝是中国古代数学的蓬勃发展时期。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"南北朝是中国古代数学的蓬勃发展时期,计有《孙子算经》、《夏侯阳算经》、《张丘建算经》等算学著作问世。"},{"id":236,"type":"判断题","text":"齐国的稷下学宫是战国各家私学的汇集地。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"稷下学宫，是世界上最早的官办高等学府，也是中国最早的社会科学院、政府智库。始建于齐桓公田午时期。位于齐国国都临淄（今山东省淄博市临淄区）稷门附近。"},{"id":237,"type":"判断题","text":"诗言志，是我国古代文论家对诗的本质特征的认识。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"诗言志，是我国古代文论家对诗的本质特征的认识。《诗经》的作者关于作诗目的的叙述中就有“诗言志”这种观念的萌芽。作为一个理论术语提出来，最早大约是在《左传·襄公二十七年》记赵文子对叔向所说的“诗以言志”。后来“诗言志”的说法就更为普遍。《尚书·尧典》中记的舜话说：“诗言志，歌永言，声依永，律和声。”《庄子·天下篇》说：“诗以道志。”《荀子·儒效》篇云：“《诗》言是其志也。”"},{"id":238,"type":"判断题","text":"中国的戏曲起源于原始的乐舞，巫人以舞降神，巫舞逐渐演变为民间歌舞和小调。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"中国的戏曲起源于原始的乐舞,后来巫术盛行,巫人以舞降神,巫舞逐渐演变为民间歌舞和小调。古代在每年腊月还举行一种驱鬼逐疫的仪式,叫做“驱傩”或“大傩”。"},{"id":239,"type":"判断题","text":"东晋时的画家顾恺之、张僧繇和陆探微合称“六朝三杰”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"六朝三杰是指在中国绘画史上,六朝时期著名的三位书画家:东晋顾恺之、南朝宋陆探微,和南朝梁张僧繇。"},{"id":240,"type":"判断题","text":"张择端是北宋时期最著名的大画家，其长卷风俗画《清明上河图》是当时风俗画的代表。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"清明上河图，中国十大传世名画之一。为北宋风俗画，北宋画家张择端仅见的存世精品，属国宝级文物，现藏于北京故宫博物院。"},{"id":241,"type":"判断题","text":"《九章算术》成书于公元1世纪，被称为“中国算法”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《九章算术》是《算经十书》中最重要的一部，成于公元一世纪左右。其作者已不可考，一般认为它是经历代各家的增补修订，而逐渐发展完备成为现今定本的，西汉的张苍、耿寿昌曾经做过增补和整理，其时大体已成定本。"},{"id":242,"type":"判断题","text":"西周时期，诗歌与音乐是结合在一起的，十五国风是十五种地方性的民歌。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"西周时期，诗歌与音乐是结合在一起的。十五国风是十五种地方性的民歌，各有不同特点、声调和风格。雅与颂也各有不同的格律，都能配乐歌唱，组成一定的乐章，这些乐章是国家制定的礼乐的重要组成部分，应用相当广泛。"},{"id":243,"type":"判断题","text":"《庄子》分为外篇、内篇和和杂篇。外篇是庄子的思想精华所在。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"内篇是庄子的思想精华所在。"},{"id":244,"type":"判断题","text":"中国第一长洞是贵州绥阳的双河溶洞。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"中国第一长洞是贵州绥阳的双河溶洞。其位于贵州省遵义市绥阳县温泉镇，距绥阳县城50公里，距遵义市92公里。"},{"id":245,"type":"判断题","text":"天一阁是中国现存最早传世最久的私家藏书阁，现位于浙江宁波市区。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"天一阁,位于今浙江省宁波市,是中国现存历史最悠久的私家藏书楼,也是世界上最古老的三大私家藏书楼之一。"},{"id":246,"type":"判断题","text":"我国迄今为止出土的最庞大的一组战国编钟是1978年出土于湖北随县(今随州市)的曾侯乙编钟。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"曾侯乙编钟,战国早期文物,中国首批禁止出国(境)展览文物。1978年在湖北随县(今随州市)出土。是由六十五件青铜编钟组成的庞大乐器,其音域跨五个半八度,十二个半音齐备。"},{"id":247,"type":"判断题","text":"孔子在教育上取得巨大成就，所谓弟子三千，贤者七十二。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"“弟子三千，贤人七十二”的意思是：孔子的学生有三千人，身通六艺的只有七十二个。出自《史记·孔子世家》所记：“孔子以诗书礼乐教，弟子盖三千焉，身通六艺者七十有二人。”"},{"id":248,"type":"判断题","text":"“齐物”的思想不仅体现在《齐物论》中，《庄子·至乐》中鼓盆而歌的故事也能体现这一思想。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"“齐物”的思想认为宇宙间一切事物，如生死寿夭，是非得失，物我有无，都应当同等看待。"},{"id":249,"type":"判断题","text":"《太公兵法》相传是辅佐周武王伐纣的姜太公写的兵书。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《姜太公兵书》为该八大兵书之一。商周之交， 姜太公在山中避纣时苦心研究兵法，并写出太公兵书，成为中国古代八大兵书之一。"},{"id":250,"type":"判断题","text":"桌与案有形制上的区别，腿的位置缩进一块的是桌，腿的位置顶住四角的为案。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"腿的位置缩进一块的是案，腿的位置顶住四角的为桌。"},{"id":251,"type":"判断题","text":"“许人一物，千金不移”出自《幼学琼林》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"出自《增广贤文》。"},{"id":252,"type":"判断题","text":"乐府原是封建朝廷设立的音乐管理机构，最初始于西周，汉朝依然沿用了这一名称。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"乐府原是封建朝廷设立的音乐管理机构，最初始于秦代。"},{"id":253,"type":"判断题","text":"汉代乐府的主要任务是采集编撰各地民间歌谣，将一些文人诗作制曲配乐，演唱或演奏新的歌舞等。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"公元前112年，汉王朝在汉武帝时正式设立乐府，其任务是收集编纂各地民间音乐、整理改编与创作音乐、进行演唱及演奏等。"},{"id":254,"type":"判断题","text":"清末魏学洢的散文《核舟记》，介绍了一个由核桃雕刻而成的小舟，这个核舟再现了“大苏泛赤壁”的情景。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"明末。"},{"id":255,"type":"判断题","text":"庋具俗称“框架类家具”。度，意为“储藏”，故庋具即储物类家具。储物类家具有两大类\n一为柜，一为箱。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"在中国传统家具中，有一类家具叫庋具，包括柜、架、橱和箱等，是储物类家具。"},{"id":256,"type":"判断题","text":"清朝的《古今图书集成》是我国现存的最大的一部类书。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"我国现存的规模最大、保存最完 整的类书则是《古今图书集成》。 《古今图书集成》系清圣祖(即玄烨、俗称康熙帝)亲自命令编撰,本名《古今图书汇编》,又称《文献汇编》。"},{"id":257,"type":"判断题","text":"九品中正制，即在各州各郡设立中正官，负责察访评定本地之人，并按照其声望和才智划分为一品、二品、三品、四品、五品、六品、七品、八品、九品，向上推举官员人选。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"按照其声望和才智划分为上上、上中、上下、中上、中中、中下、下上、下中、下下九品。"},{"id":258,"type":"判断题","text":"慈恩是古龙武侠小说《神雕侠侣》中的人物。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"金庸。"},{"id":259,"type":"判断题","text":"严格意义上说，青铜不是纯铜，而是一种铜合金。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"青铜是合金。青铜是铜和锡的合金,就是在纯铜(紫铜)中加入锡或铅的合金。"},{"id":260,"type":"判断题","text":"《周礼·考工记》记载有“金有六齐”说，详细记录了铸造不同种类的青铜器时的铜锡比例。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"“六齐”规律是位于黄河下游的齐国的冶金工匠们关于冶铸青铜合金时铜锡配比的经验总结｡比如在冶炼熔铸过程中，对不同火候的辨认与掌握，《考工记》有详细记载:凡铸金之状，金与锡黑浊之气竭，黄白次之;黄白之气竭，青白次之;青白之气竭，青气次之，然后可铸也｡"},{"id":261,"type":"判断题","text":"古人在龟甲兽骨上刻画记事，产生了“甲骨文”，后来随着冶铜技术的进步，人民又将文字刻写在青铜器上，出现了“钟鼎文”，也称“铭文”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"甲骨文是中国商代和西周早期王室用于占卜记事而刻（或写）在龟甲和兽骨上的文字；钟鼎文，也叫金文或铭文，是铸刻在青铜器的钟或鼎上的一种文字。"},{"id":262,"type":"判断题","text":"人们把由竹片连成的可以书卷的竹简称为“简牍”或者“尺素”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应该是“尺牍”。"},{"id":263,"type":"判断题","text":"成语故事“多多益善”的主角是项羽。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“多多益善”出自《史记》：“上（刘邦）曰：‘于君何如？’（韩信）曰：‘臣多多而益善耳。’”因此故事的主角是韩信。"},{"id":264,"type":"判断题","text":"高山流水相传是魏晋南北朝时期民间演奏家伯牙所作的古琴曲。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"《高山流水》，中国古琴曲，属于中国十大古曲之一。传说先秦的琴师伯牙一次在荒山野地弹琴，樵夫钟子期竟能领会这是 描绘“峨峨兮若泰山”和“洋洋兮若江河”。伯牙惊道：“善哉，子之心而与吾心同。”钟子期死后，伯牙痛失知音，摔琴绝弦，终生不弹，故有高山流水之曲。"},{"id":265,"type":"判断题","text":"榻在古代使用非常广泛，因其低矮，无栏杆无围子，移动方便，因此常常作为小憩的用具。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"榻在古代使用非常广泛，因其低矮，无栏杆无围子，移动方便，因此常常作为小憩的用具。"},{"id":266,"type":"判断题","text":"算盘的木框内以直柱贯穿，称作“档”，档中以一木柱横穿，称作“梁”。梁上有五颗算珠，\n每一颗算珠计算时作数五;梁下有两颗算珠，每一颗算珠计算时作数一。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"梁上有两颗算珠，梁下有五颗算珠。"},{"id":267,"type":"判断题","text":"老子认为“无为而无不为”，无为是指不做任何行动。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“无为”就是不做任何违反自然规律、有损道德规范、违反社会法则，有害众生的事。但这里的“无为”并不是什么都不做，并不是不为，而是含有不妄为、不乱为、顺应客观态势、尊重自然规律的意思。老子说过“无为而无不为”，意思是说：不妄为，就没有什么事情做不成的。"},{"id":268,"type":"判断题","text":"架子床，出现在明代，有四架或者六架，偶尔有八架，它不是单纯的卧具，常常用来待客。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"它是单纯的卧具，不能用以待客。"},{"id":269,"type":"判断题","text":"屏风是古代室内用于挡风或隔断视线的用具，材质多样，可以自由移动，既能隔出秘密空间，又有很强的装饰作用。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"屏风，中国传统建筑物内部挡风用的一种家具，所谓“屏其风也”。屏风作为传统家具的重要组成部分，历史由来已久。屏风一般陈设于室内的显著位置，起到分隔、美化、挡风、协调等作用。它与古典家具相互辉映，相得益彰，浑然一体，成为中式家居装饰不可分割的整体，而呈现出一种和谐之美、宁静之美。"},{"id":270,"type":"判断题","text":"晚年白居易和刘长卿唱和颇多，时人称为“刘白”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"晚年白居易和刘禹锡唱和颇多，时人称为“刘白”。"},{"id":271,"type":"判断题","text":"《战国策》，主要记述了战国时期的纵横家的政治主张和言行策略。西汉刘向编定。它是一部纪传体史书。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"《战国策》是国别体。"},{"id":272,"type":"判断题","text":"“轻诺必寡信”的意思是小声许下的诺言肯定不会实现。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"这句话的意思是：随意的许诺往往会因为难于实现而使自己丧失信用。"},{"id":273,"type":"判断题","text":"三国时期，以道家清净养生、无为治世为主的黄老学向宗教化发展，又与方仙道结合，行成了黄老道，行其术者被称为方士。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应该是西汉末年。"},{"id":274,"type":"判断题","text":"“君子素其位而行”指君子要按自己平常所处的地位做该做的事，不羡慕这以外的事。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"指的是君子安于现在所处的地位去做应做的事，不生非分之想。"},{"id":275,"type":"判断题","text":"洛阳因坐落于洛河南岸而得名。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"古代称山南水北为阳。"},{"id":276,"type":"判断题","text":"《劝学》中有：“君子生非异也，善假于物也。”这里的“假”是“假设”的意思。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“假”是“借助”的意思。"},{"id":277,"type":"判断题","text":"“闻过则改”的意思是做一件事情要坚持不懈，就能取得成功。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"闻过则改的意思是知道了错误就立刻改正，不将错就错。"},{"id":278,"type":"判断题","text":"我国古代纺织过程中，先将线染好颜色，再上机进行织布。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"先织布再练染。"},{"id":279,"type":"判断题","text":"八股文的文体有固定格式：由破题、承题、起讲、入题、起股、中股、后股、束股八部分组成。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"八股文就是指文章的八个部分，文体有固定格式：由破题、承题、起讲、入题、起股、中股、后股、束股八部分组成，题目一律出自四书五经中的原文。后四个部分每部分有两股排比对偶的文字，合起来共八股。"},{"id":280,"type":"判断题","text":"张衡是东汉中期浑天说的代表人物之一，他指出月球本身并不发光，月光其实是日光的反射。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"张衡是东汉中期浑天说的代表人物之一;他指出月球本身并不发光,月光其实是日光的反射;他还正确地解释了月食的成因,并且认识到宇宙的无限性和行星运动的快慢与距离地球远近的关系。"},{"id":281,"type":"判断题","text":"在出土的青铜器中，刀远远多于剑，材料特性使然。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应该是剑远远多于刀。"},{"id":282,"type":"判断题","text":"“小品”多指写作形式固定，篇幅短小精悍，不落窠臼，注重个性、情怀和创见的散文文体。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“小品”多写作形式灵活。"},{"id":283,"type":"判断题","text":"“大道之行也，天下为公，选贤与能，讲信修睦”选自《孟子》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"选自《礼记》。"},{"id":284,"type":"判断题","text":"2007年，广东省阳江市海域打捞上来南宋时期沉船“南海一号”，船舱中装有6万余件南宋瓷器。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"“南海一号”是迄今为止，世界上发现的海上沉船中年代最早、船体最大、保存最完整的远洋贸易商船，对研究我国乃至整个东亚、东南亚的古代造船史、航运史、贸易史都有着重要意义。"},{"id":285,"type":"判断题","text":"关于满汉全席的最早记载出现在《扬州画舫录》一书中。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"满汉全席兴起于清代，是集满族与汉族菜点之精华而形成的历史上最著名的中华大宴。乾隆甲申年间李斗所著《扬州画舫录》中记有一份满汉全席食单，是关于满汉全席的最早记载。满汉全席以东北、山东、北京、江浙菜为主。"},{"id":286,"type":"判断题","text":"京杭大运河历史悠久，它贯通海河、黄河、淮河、长江、钱塘江五大水系。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"大运河南起余杭（今杭州），北到涿郡（今北京），途经今浙江、江苏、山东、河北四省及天津、北京两市，贯通海河、黄河、淮河、长江、钱塘江五大水系，主要水源为微山湖，大运河全长约1797公里。"},{"id":287,"type":"判断题","text":"2000年10月，都江堰被联合国列入“世界文化遗产名录”；2014年6月，大运河被联合国列入“世界文化遗产名录”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"2000年10月，都江堰被联合国列入“世界文化遗产名录”;2014年6月，大运河被联合国列入“世界文化遗产名录”。"},{"id":288,"type":"判断题","text":"古代称筷子为“箸”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"古代称筷子为“箸”。箸是中国汉族发明的进食工具，后来这种工具开始传入了朝鲜、日本、越南等汉字文化圈国家。"},{"id":289,"type":"判断题","text":"以李梦阳、李攀龙为首的“前后七子”提出了“文必秦汉，诗必盛唐”的口号。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"明代中后期,以李梦阳、李攀龙为首的“前后七子”提出了“文必秦汉,诗必盛唐”的口号。"},{"id":290,"type":"判断题","text":"“宜将剩勇追穷寇，不可沽名学霸王”中的“霸王”指的是关羽。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"指的是项羽。"},{"id":291,"type":"判断题","text":"不以物喜，不以己悲;居庙堂之高则忧其民;处江湖之远则忧其君。这里庙堂指的是寺庙。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"朝廷。"},{"id":292,"type":"判断题","text":"词集《珂雪词》出自清词词人曹贞吉。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"词集《珂雪词》为清代曹贞吉著。他为人嗜书，工诗文，与嘉善诗人曹尔堪并称为“南北二曹”，词尤有名，被誉为清初词坛上“最为大雅”的词家。"},{"id":293,"type":"判断题","text":"古人论琴，有“四德九善”之说。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应该是“四善九德”。"},{"id":294,"type":"判断题","text":"“千载谁堪伯仲间”的“堪”的意思是“能够”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"堪：能够。伯仲：原指兄弟间的次第。这里比喻人物不相上下，难分优劣高低。"},{"id":295,"type":"判断题","text":"《袁氏世范》有很多经典名言广泛流传，比如“小人当敬远”“小人为恶不必谏”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"“小人当敬远”“小人为恶不必谏”出自《袁氏世范》。"},{"id":296,"type":"判断题","text":"《孙权劝学》节选自南宋政治家、史学家司马光编纂的《资治通鉴》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"司马光是北宋时代。"},{"id":297,"type":"判断题","text":"甲骨文出现在周代，是我国所发现的最早的成熟汉字。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"殷商时代。"},{"id":298,"type":"判断题","text":"相传仓颉造字时，惊天地、泣鬼神，天降谷子，称作“谷雨”，人们把这一天作为祭祀仓颉的节日。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"仓颉造字，是中国古代神话传说之一，仓颉造字的地方叫“凤凰衔书台”。出自《淮南子·本经训》：“昔者仓颉作书，而天雨粟，鬼夜哭。”仓颉，称苍颉，复姓侯刚，号史皇氏，曾把流传于先民中的文字加以搜集、整理、规范和使用，在创造汉字的过程中起了重要作用，为中华民族文明的传承做出了不朽的功绩。但普遍认为汉字由仓颉一人创造只是传说，不过他可能是汉字的整理者，被后人尊为“造字圣人”。"},{"id":299,"type":"判断题","text":"天地神灵扶庙社，京华父老望和銮。出师一表通今古，夜半挑灯更细看。这里和銮指的是金銮殿。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"天子的车驾。"},{"id":300,"type":"判断题","text":"汉字的特点使书法艺术形成了独特的艺术规律和美学价值，金文古朴大方，小篆形象直观，隶书龙飞凤舞，草书整齐优美。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应该是隶书整齐优美，草书龙飞凤舞。"},{"id":301,"type":"判断题","text":"汉魏间,曹操与曹植、曹冲父子三人在文学上均有很高的成就，后人合称之头“三曹”。“三曹”是建安文学的代表作家，其现实主义的创作特征与遒劲刚健、慷慨悲凉的创作风格被后人称为“建安风骨”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"曹冲应改为曹丕。"},{"id":302,"type":"判断题","text":"唐代时，出现了第一个蹴鞠民间团体齐云社。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应该是宋代。"},{"id":303,"type":"判断题","text":"柳永是宋代著名词人，他有一首词是专门描写宋代杭州的，其中描写杭州“有三秋桂子，十里荷花”，这首词是《八声甘州》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"这首词是《望海潮》。"},{"id":304,"type":"判断题","text":"在《明夷待访录》中，黄宗羲第一次比较完整地提出了具有近代资产阶级民主政治和民主主义精神的教育思想。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《明夷待访录》比法国民主主义启蒙教育思想家卢梭的《社会契约论》发表早一百年。在这部著作中，黄宗羲第一次比较完整地提出了具有近代资产阶级民主政治和民主主义精神的教育思想，并为限制封建专制特权，推行民主政治制度改革，设计了一套普及教育的学制体系。"},{"id":305,"type":"判断题","text":"我国第一部系统的绘画理论著作是谢赫的《古画品录》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《古画品录》是南齐时代的⼈物画家谢赫（公元479—502年）绘画理论著作，也是我国绘画史上第⼀部完整的绘画理论著作。"},{"id":306,"type":"判断题","text":"鲁迅在《中国小说史略》中称《儒林外史》为“用传奇法，而以志怪”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应该是《聊斋志异》。"},{"id":307,"type":"判断题","text":"西汉末年有一位名叫“左伯”的造纸能手，他造出来的纸厚薄均匀、质地细密、色泽鲜明，时人称“左伯纸”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"东汉末年。"},{"id":308,"type":"判断题","text":"由于《楚辞》的诗歌形式是在楚国民歌的基础上加工而成，篇中又大量引用楚地的风十物产和方言词汇，多用兮字，且五言、六言、七言不等，所以称为“楚辞”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《楚辞》是我国第一部浪漫主义诗歌总集。由于诗歌的形式是在楚国民歌的基础上加工 形成,篇中又大量引用楚地的风土物产和方言词汇,所以叫“楚辞”。"},{"id":309,"type":"判断题","text":"《楚辞》的作者是屈原。屈原，名平，字原，是战国时楚国的贵族，也是我国浪漫主义诗歌传统的奠基人，代表作有《离骚》《九章》《湘夫人》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"《楚辞》为西汉刘向所辑，收录了战国时期楚国屈原、宋玉等人的作品。"},{"id":310,"type":"判断题","text":"我国古代把一昼夜分为12个时辰，每个时辰相当于现在的2个小时。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"时辰是古代计时单位，古代人把一天划分为十二个时辰，每个时辰相等于现在的两小时。相传是根据十二生肖中的动物的出没时间来命名各个时辰。"},{"id":311,"type":"判断题","text":"文与道的关系，是中国古代文论的中心问题。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"文学本原论（文与道之间的关系）就是中国古代文论的中心问题。"},{"id":312,"type":"判断题","text":"中国现存最早的古代木结构建筑实例是重建于宋代的山西五台山的南禅寺大殿。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应该是唐代。"},{"id":313,"type":"判断题","text":"建安风骨，又称“汉魏风骨”，其主要特点是意境宏大，格调高昂，具有鲜明的时代特征和个性特征，呈现出雄健深沉、慷慨悲凉的艺术风格。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"“建安风骨也称汉魏风骨，是汉魏之际的文学风格，具有慷慨悲凉、雄健深沉等特点。简要介绍建安时期的作品真实地反映了现实的动乱和人民的苦难，抒发建功立业的理想和积极进取的精神。"},{"id":314,"type":"判断题","text":"“客从远方来，遗我双鲤鱼”中，“双鲤鱼”指丰厚的礼物。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“双鲤鱼”指信函。"},{"id":315,"type":"判断题","text":"《蒹葭》中有：“溯洄从之，道阻且长。溯游从之，宛在水中央。”这里，“溯洄”的意思是逆流而上，“溯游”的意思是“顺流而下”。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"溯洄指逆着河流的道路往上游走。"},{"id":316,"type":"判断题","text":"李商隐《隋宫》中：“乘兴南游不戒严，九重谁省谏书函？”这里“乘兴南游”的是隋文帝。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"乘兴南游的是隋炀帝。"},{"id":317,"type":"判断题","text":"麻纸是中国古人的重要发明。由东汉蔡伦改进，成为中国古代图书典籍的用纸之一。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"麻纸是中国古人的重要发明。由东汉蔡伦改进，成为中国古代图书典籍的用纸之一。麻纸是一种大部分以黄麻、布头、破履为主原料生产的强韧纸张。"},{"id":318,"type":"判断题","text":"“君子于役，如之何勿思”与“即今三月莺花满，长作江南梦里人”都赞扬了边境百姓守土御敌的斗争精神。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"这两句诗都表达了思妇对在远方服役的丈夫的思念之情。"},{"id":319,"type":"判断题","text":"“珠算”一词最早出现于东汉徐岳的《数术记遗》中。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"“珠算”一词最早见于东汉徐岳所撰的《数术记遗》，其中有云：“珠算控带四时，经纬三才。”"},{"id":320,"type":"判断题","text":"最能集中体现魏晋风度的著作当属南朝刘义庆所著的《世说新语》一书。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《世说新语》是南朝时期的文言志人小说集,由南朝刘义庆所撰写,也有称是由刘义庆所组织门客编写。其内容主要是记载东汉后期到魏晋间一些名士的言行与轶事。"},{"id":321,"type":"判断题","text":"伯夷、叔齐两人是好朋友关系，因为义不食周粟，而饿死于首阳山。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"他们两人是兄弟关系。"},{"id":322,"type":"判断题","text":"雅乐舞蹈的主要内容是“六大舞”，也称“六代舞”，代表六个朝代。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"雅乐舞蹈的主要内容是“六大舞”，也称“六代舞”，代表六个朝代。为首的据传是起自黄帝的《云门》（又称《云门大卷》、《咸池》和《承云》），依次是尧帝传下的《大章》（又名《大咸》），舜帝的《大韶》，夏禹的《大夏》（又称《夏龠》），商汤《桑林》，然后是现实题材——反映武王伐纣功绩的《大武》。"},{"id":323,"type":"判断题","text":"我们生活中习惯说的“陶瓷”，实际上是陶器和瓷器的合称。陶器与瓷器的区别主要在于使用材料和烧成温度不同。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"陶器与瓷器的区别在于，一使用材料；二烧成温度，二者缺一不可。陶器可以使用包括瓷土在内的各种矿物粘土制作，烧成温度较低，多在700—1000℃之间，胎体基本烧结，不再遇水分解，但气孔率和吸水率较高。在显微镜下观察胎体，极少存在玻璃相莫来石结晶体，换句话说就是没有瓷化，敲击之声较沉闷。而瓷器使用的是氧化铝含量较高的瓷土即高龄土烧制。瓷器的烧成温度至少在1100℃以上，胎质基本瓷化，显微观察有大量莫来石结晶体存在，气孔率和吸水率较低，敲击之声清脆。"},{"id":324,"type":"判断题","text":"汉文帝罢黜百家、独尊儒术，儒学上升为官学。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"汉武帝推行的“罢黜百家,独尊儒术”的政策,使儒学从过去的民间私学变为官学。"},{"id":325,"type":"判断题","text":"顾炎武倡导国家兴亡 、匹夫有责的爱国主义道德观。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"顾炎武在《日知录》中提出“天下兴亡，匹夫有责”的著名观点。这句名言充分体现了爱国主义精神，鼓舞了人民的爱国热情。"},{"id":326,"type":"判断题","text":"孝悌的基本内容是父慈子孝、兄友弟恭。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"孝悌”是“仁”的根本。它的基本内容是父慈子孝、兄友弟恭,在社会道德生活中具有崇高的地位,得到普遍的奉行。"},{"id":327,"type":"判断题","text":"词的重要组成部分是词调，俗称“词牌”。每个词牌都有自己特定的格式，对于句数和每句的字数有明确的限定，对于用韵和平仄则没有限定。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"词对于用韵和平仄也有明确的限定。"},{"id":328,"type":"判断题","text":"中国的美术、绘画首先是通过带有各种图案的丝绸、锦绣、陶瓷、漆器等日用品、工艺品而传入欧洲的。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"中国的美术、绘画首先是通过带有各种图案的丝绸、锦绣、陶瓷、漆器等日用品、工艺品而传人欧洲的。因此，中国的丝绸、锦绣、陶瓷、漆器对当时欧洲人来说，不仅是实用物品，而且是具有观赏价值的艺术品。"},{"id":329,"type":"判断题","text":"“封侯非我意，但愿海波平”的作者是郑成功。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"作者是是戚继光。"},{"id":330,"type":"判断题","text":"史评体著作按其内容可分为两种，一是史书评论，一是史事评论。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"史评体著作按其内容可分为两种，一是史书评论，一是史事评论。史事评论就是史学家对历史事实进行评论,目的是总结历史上治乱兴衰的经验教训,为现实服务. 史书评论就是对史学著作进行评论。"},{"id":331,"type":"判断题","text":"三通是指《通典》、《通志》、《文献通考》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"“三通”是《通典》《通志》和《文献通考》的合称。《通典》由唐朝杜佑撰写，全书共二百卷，约一百九十万字，是中国历史上第一部体例完备的政书。《通志》由南宋郑樵撰写，是一部以人物为中心的纪传体通史。《文献通考》简称《通考》，由宋元时代着名学者马端临编撰写，是继《通典》《通志》之后，规模最大的一部记述历代典章制度的着作。"},{"id":332,"type":"判断题","text":"李白把现实主义诗歌推向了最高峰。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"李白把浪漫主义诗歌推向了最高峰。"},{"id":333,"type":"判断题","text":"马致远是元代杂剧的奠基人。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"元代杂剧作家有200人左右，剧目有600种左右，现存的有150多种。元代最著名的戏剧家是关汉卿，他一生创作了许多剧本，流传至今有10多种，代表作是悲剧《窦娥冤》，元杂剧的奠基人就是关汉卿。"},{"id":334,"type":"判断题","text":"金元散曲，指的是金元时期的小令和套数。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"金元散曲,指的是金元时期的小令和套数,小令和词调同源,是一支支独立的曲子;套数则源自宋金时期的说唱诸宫调,是由多只曲子依照一定的调性组织起来的。"},{"id":335,"type":"判断题","text":"三山五园，是对北京西北郊、以清代皇家园林为代表的历史文化遗产的统称。三山是指万寿山、香山、玉泉山，五园是指颐和园、静宜园、静明园、畅春园和圆明园。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"三山五园，是对北京西北郊、以清代皇家园林为代表的历史文化遗产的统称。三山是指万寿山、香山、玉泉山，五园是指颐和园、静宜园、静明园、畅春园和圆明园。"},{"id":336,"type":"判断题","text":"公元前613年，当时中国人观察“有星孛入北斗”，这是世界上公认的首次关于哈雷彗星的确切纪录，此记录记载于《春秋》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"鲁国《春秋》说：鲁文公十四年（公元前613年）“秋七月，有星孛入于北斗。”"},{"id":337,"type":"判断题","text":"《开元占经》保存了汉民族最古老的关于恒星位置观测的记录。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《开元占经》全名《大唐开元占经》，清人又或名《唐开元占经》，成书时间约在公元718年~726年之间。作者是瞿昙悉达，是中国古代天文学著作之一。"},{"id":338,"type":"判断题","text":"《数书九章》是中国古代数学的高峰。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《数书九章》是南宋数学家秦九韶所著数学著作。该书在数学内容上颇多创新，是对《九章算术》的继承和发展。它概括了宋元时期数学的主要成就，标志着中国古代数学的高峰。"},{"id":339,"type":"判断题","text":"青花瓷最早始于宋朝。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"原始的青花瓷在唐代已经开始出现端倪，成熟的青花瓷则是在唐代中期才慢慢出现，到了明代时期青花已经变成了瓷器物品的主流品种。"},{"id":340,"type":"判断题","text":"诗句“戏与山妻谈故事”中的“山妻”是诗人对他人妻子的谦称。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"应该是诗人对自己棋子妻子的谦称。"},{"id":341,"type":"判断题","text":"《尚书》是中国古代散文已经形成的标志。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《尚书》，是上古历史文献集。标志着中国古代散文已经形成。书中文章可分为记言、叙事两类。"},{"id":342,"type":"判断题","text":"“何须浅碧深红色，自是花中第一流”中的“花”指的是桂花。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"淡黄色的桂花，并不鲜艳，但体态轻盈。于幽静之处，不惹人注意，只留给人香味。不需要具有名花的红碧颜色。桂花色淡香浓，应属最好的。"},{"id":343,"type":"判断题","text":"史前时期玉器玉材材质大都属于蛇纹石。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"人们将蛇纹石当作建筑用材料，有些可当作耐火材料，颜色好看的还可以制成装饰品或工艺品。除此以外，蛇纹石还可用来制造化肥。"},{"id":344,"type":"判断题","text":"“千古兴亡多少事？悠悠。不尽长江滚滚流”的作者是宋代词人陆游。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"作者是辛弃疾。"},{"id":345,"type":"判断题","text":"“春种一粒粟，秋收万颗子”出自《悯农》，作者是李白。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"作者是李绅。"},{"id":346,"type":"判断题","text":"晏殊，字同叔，擅长写小令，是晚唐著名的词人。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"不是晚唐词人，应该是宋代词人。"},{"id":347,"type":"判断题","text":"“都缘自有离恨，故画作远山长”中，“远山长”是远处高大的山峰。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"“远山长”是指眉毛画得又细又长。"},{"id":348,"type":"判断题","text":"《古诗十九首》的第一首是《行行重行行》，是一首表达游子思乡而不得归的诗。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"是一首妻子思念出门在外的丈夫的诗。"},{"id":349,"type":"判断题","text":"《静夜思》、《秋浦歌》、《赠汪伦》、《古朗月行》、《望庐山瀑布》、《独坐敬亭山》、《春望》、《送孟浩然之广陵》等诗都是李白写的。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"《春望》是杜甫写的。"},{"id":350,"type":"判断题","text":"《陈太丘与友期行》中“入门不顾”的“顾”与“一步三顾”中的“顾”意思相同。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"都是回顾的意思。"},{"id":351,"type":"判断题","text":"\"三皇五帝\"是史书上确有年代记载的真实人物。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"\"三皇五帝\"属于神话传说和历史考古断处，没有确切的年代与资料证明，是先夏文化时期各文化阶段的象征。"},{"id":352,"type":"判断题","text":"万里长城东起山海关，西到嘉峪关，这段被称为长城的\"主线\"。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"万里长城东起山海关、西到嘉峪关，全长达1.3万多里，这部分被称为长城的\"主线\"，是长城文化的核心。"},{"id":353,"type":"判断题","text":"除万里长城外，山东、陕西、辽宁等地还保存有齐长城、魏长城、燕长城等古长城遗址。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"山东穆陵关两侧的战国齐长城、陕西华阴的魏长城、辽宁建平县的烧锅营子燕长城等都是古长城遗址。"},{"id":354,"type":"判断题","text":"清朝的汉族大臣也可以像满族大臣一样，对皇帝自称\"奴才\"。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"\"奴才\"是满族主奴之间的自家称呼，汉臣与皇帝没有主奴关系，只能称\"臣\"；乾隆年间汉臣马人龙奏折自称\"奴才\"还遭到斥责。"},{"id":355,"type":"判断题","text":"古代官员出行鸣锣开道，鸣锣十三下代表皇帝出行。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"鸣锣七下表县太爷出行，九下表府一级官员出行，十一下表省级官员出行，鸣锣十三下则代表皇帝出行。"},{"id":356,"type":"判断题","text":"汉代朝廷每五天给官吏放一次假，让官员回家洗澡休息，称为\"休沐\"。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"汉代重视洗沐，\"五日一假洗沐\"以法律形式固定下来，这个假日被称为\"休沐\"。"},{"id":357,"type":"判断题","text":"唐代官员的休沐改为每十天休息洗浴一次。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"唐代考虑到五日一假太频繁，改为官吏每10天休息洗浴一次，称为\"旬休\"。"},{"id":358,"type":"判断题","text":"\"七擒孟获\"的故事在正史《三国志》中有明确记载。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"《三国志》并无\"七擒孟获\"的记载，此事最早见于《汉晋春秋》等，经《三国演义》渲染后家喻户晓。"},{"id":359,"type":"判断题","text":"种种史料记载表明，曹操并没有设置\"七十二疑冢\"。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"据《祭魏武帝文》等记载，曹操没有设置七十二疑冢，该传闻多出自盗墓贼或小说家的杜撰。"},{"id":360,"type":"判断题","text":"世界上最早的纸币\"交子\"出现于北宋时期的四川地区。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"世界上最早的纸币是\"交子\"，出现于北宋的四川地区。"},{"id":361,"type":"判断题","text":"最早的针灸用针是金属针。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"最早的针灸用针并不是金属的，最初用的是砭石（石头针），金属针是后来才出现的。"},{"id":362,"type":"判断题","text":"在\"牛痘\"接种法发明之前，中国古人早已用接种\"人痘\"的方法预防天花。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"有比\"牛痘\"更早的\"人痘术\"，中国人很早就通过接种人痘来预防天花。"},{"id":363,"type":"判断题","text":"\"秀才\"在中国历代科举中始终是最低一级、最容易考取的功名。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"秀才最初泛指才华出众之人，唐代秀才曾是科举中地位很高的科目，直到明清才成为最低一级的功名。"},{"id":364,"type":"判断题","text":"古代\"八百里加急\"公文，每天都必须严格跑满八百里。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"\"八百里加急\"是最高等级的要求，公文按紧急程度分级传递，并非每天都要求飞驰八百里。"},{"id":365,"type":"判断题","text":"\"黄帝战蚩尤\"确有其事，是有史料确切记载的真实战争。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"黄帝战蚩尤与\"三皇五帝\"一样属于上古神话传说，没有确切的年代和史料可以证明。"},{"id":366,"type":"判断题","text":"项羽设下的\"鸿门宴\"确实暗藏杀机、凶险万分。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"楚汉相争时项羽在鸿门设宴，范增示意项庄舞剑意在沛公，刘邦险象环生，后世遂以\"鸿门宴\"代指暗藏杀机的宴会。"},{"id":367,"type":"判断题","text":"王昭君出塞后被称为\"明妃\"，是为了避晋代司马昭的名讳。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"王昭君并没有被汉元帝封为\"妃\"，到匈奴后为\"阏氏\"，晋代为避司马昭的讳才改称\"明妃\"。"},{"id":368,"type":"判断题","text":"武则天是中国历史上唯一称过帝的女性。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"武则天是唯一的正统女皇帝，但并非唯一称帝的女性，民间起义女领袖陈硕真就曾自称\"文佳皇帝\"。"},{"id":369,"type":"判断题","text":"\"老佛爷\"是慈禧太后独有的专称。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"\"老佛爷\"并非慈禧的专称，清代皇帝也常被称为\"老佛爷\"，只是慈禧使用最多而令人误会。"},{"id":370,"type":"判断题","text":"\"太子洗马\"是专门替太子洗马的仆役。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"\"洗马\"即\"先马\"，是辅佐太子、出行时前驱引路的官职，并非洗马的仆役。"},{"id":371,"type":"判断题","text":"\"丞相\"和\"宰相\"完全是一回事。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"\"宰相\"是对辅助君主、总领百官的最高行政长官的通称，历代名称与制度不同；\"丞相\"只是其中的一个具体官职名，二者不能画等号。"},{"id":372,"type":"判断题","text":"史料记载岳飞背上确有\"尽忠报国\"四字，但\"岳母刺字\"的具体情节是后世演绎。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"史载岳飞背上有\"尽忠报国\"四字，但\"岳母刺字\"的故事带有传奇色彩，属后世演绎。"},{"id":373,"type":"判断题","text":"权宦魏忠贤曾被称为\"九千九百岁\"。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"魏忠贤权势熏天，竟被称\"九千九百岁\"，距\"万岁\"仅一步之遥。"},{"id":374,"type":"判断题","text":"\"三堂会审\"中的\"三堂\"指刑部、大理寺、都察院。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"\"三堂会审\"的\"三堂\"即中央三大司法机关：刑部、大理寺、都察院。"},{"id":375,"type":"判断题","text":"\"纸上谈兵\"说的是赵括，他在长平之战中兵败身亡。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"\"纸上谈兵\"说的是只会空谈兵法的赵括，他在长平之战中被秦军大败，自己也在乱军中身亡。"},{"id":376,"type":"判断题","text":"西汉抗击匈奴的名将李广被称为\"飞将军\"。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"李广英勇善战、行动神速，匈奴畏之，称其为\"飞将军\"。"},{"id":377,"type":"判断题","text":"诸葛亮在历史上真的用\"空城计\"吓退了司马懿。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"\"空城计\"是小说家的虚构，正史并无诸葛亮以空城计吓退司马懿的记载。"},{"id":378,"type":"判断题","text":"明代兴起的\"马吊\"牌与后来的麻将有关。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"明代兴起的\"打马吊\"与现在的麻将有关，是麻将的雏形之一。"},{"id":379,"type":"判断题","text":"明宣宗因痴迷斗蟋蟀而被称为\"促织天子\"。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"明宣宗痴迷蟋蟀（促织），因而被人称为\"促织天子\"。"},{"id":380,"type":"判断题","text":"\"登龙门\"与\"跳龙门\"是一回事。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"\"登龙门\"原指得到名流接引而身价倍增，后世也指科场得意；\"跳龙门\"专指科举及第，二者含义并不相同。"},{"id":381,"type":"判断题","text":"\"冷板凳\"一词来源于戏曲梨园行当。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"\"冷板凳\"来源于梨园行，指后台待场艺人坐的冷清凳子，后引申为清苦冷落的职务。"},{"id":382,"type":"判断题","text":"民间讲究大年初一不吃稀饭。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"\"年初一，不吃稀\"是春节的一大讲究，民间忌讳清早吃稀饭。"},{"id":383,"type":"判断题","text":"古代君王临朝听政要\"面南背北\"而坐，因为南方为尊。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"\"南面\"为尊，古时君王一定要\"面南\"治天下，尊长以坐北朝南见生晚辈。"},{"id":384,"type":"判断题","text":"《红楼梦》完全是曹雪芹本人的自传。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"贾宝玉的原型是否为曹雪芹本人并无定论，《红楼梦》并非完全意义上的作者自传。"},{"id":385,"type":"判断题","text":"梁山一百单八将的座次是应\"天罡地煞\"之数有意安排的。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"一百单八将的座次对应天罡地煞之数，是作者有意安排，并非巧合。"},{"id":386,"type":"判断题","text":"林冲上梁山时，王伦要他先交纳\"投名状\"。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"林冲误入白虎堂犯下死罪，投奔梁山时还要纳\"投名状\"，方为接纳。"},{"id":387,"type":"判断题","text":"\"韦编三绝\"说的是孔子晚年反复研读《周易》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"\"韦编三绝\"讲孔子读《易》勤奋，把编联竹简的皮绳都磨断了多次。"},{"id":388,"type":"判断题","text":"曹操曾用金璧赎回蔡文姬，他与蔡文姬之父蔡邕确是好友。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"曹操与蔡邕是好朋友，因此用金璧把流落匈奴的蔡文姬赎了回来。"},{"id":389,"type":"判断题","text":"夏朝是中国历史上第一个王朝。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"禹死后其子启继位，世袭制取代禅让制，夏朝成为中国历史上第一个王朝。"},{"id":390,"type":"判断题","text":"\"烽火戏诸侯\"的主角是周幽王与褒姒。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"周幽王为博褒姒一笑点燃烽火戏弄诸侯，最终失信于诸侯而亡国。"},{"id":391,"type":"判断题","text":"秦二世胡亥是秦始皇指定的合法继承人。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"秦始皇本意传位公子扶苏，胡亥的即位是赵高、李斯篡改遗诏的结果。"},{"id":392,"type":"判断题","text":"\"文景之治\"时期朝廷推行休养生息政策。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"汉文帝、景帝轻徭薄赋、与民休息，出现\"文景之治\"的治世局面。"},{"id":393,"type":"判断题","text":"光武帝刘秀建立的王朝史称东汉。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"刘秀重建刘氏政权，定都洛阳，因洛阳在长安之东，史称东汉。"},{"id":394,"type":"判断题","text":"\"贞观之治\"时期的人口已经远远超过隋朝鼎盛时期。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"隋朝鼎盛时人口约五千万，贞观之治虽然繁荣，人口远未恢复到隋朝水平。"},{"id":395,"type":"判断题","text":"迁都北京的明朝皇帝是明成祖朱棣。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"朱棣即位后营建北京城，于1421年正式迁都北京。"},{"id":396,"type":"判断题","text":"\"普天之下，莫非王土\"反映的是分封制下土地名义上归周王所有。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"分封制下全国土地名义上都属于周天子，即\"普天之下，莫非王土\"。"},{"id":397,"type":"判断题","text":"\"九品中正制\"主要实行于魏晋南北朝时期。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"九品中正制创立于曹魏，盛行于魏晋南北朝，是科举制出现前的主要选官制度。"},{"id":398,"type":"判断题","text":"\"尚书\"在秦汉时只是皇帝身边的小官，后来才演变为高官。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"尚书原为少府属下的小官，替皇帝收发文书，东汉以后权力渐重，隋唐成为六部长官。"},{"id":399,"type":"判断题","text":"明朝内阁初设时，大学士的品级并不高。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"明成祖设内阁时大学士仅五品，后来因接近皇帝、批答章奏而权势渐重。"},{"id":400,"type":"判断题","text":"清代\"军机处\"设立于雍正年间。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"雍正年间因用兵西北而设军机房，后改称军机处，成为清代中枢机构。"},{"id":401,"type":"判断题","text":"宰相制度在明代被正式废除。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"洪武十三年朱元璋借胡惟庸案废除丞相制度，从此不再设宰相。"},{"id":402,"type":"判断题","text":"狄仁杰是武周时期的著名宰相。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"狄仁杰在武则天时期两度拜相，以断案如神、举贤荐能著称。"},{"id":403,"type":"判断题","text":"\"萧规曹随\"中曹参继任相位后一切遵循萧何旧制。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"曹参接替萧何为相，举事无所变更，史称\"萧规曹随\"。"},{"id":404,"type":"判断题","text":"\"毛遂自荐\"中的毛遂是孟尝君的门客。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"毛遂是赵国平原君的门客，自荐随平原君赴楚谈判定纵。"},{"id":405,"type":"判断题","text":"\"管鲍之交\"说的是管仲与鲍叔牙的深厚友谊。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"鲍叔牙知人善荐，力荐管仲为相，二人交谊深厚，世称\"管鲍之交\"。"},{"id":406,"type":"判断题","text":"秦始皇陵\"兵马俑\"是秦始皇陵的陪葬坑。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"兵马俑坑是秦始皇陵的陪葬坑，被誉为\"世界第八大奇迹\"。"},{"id":407,"type":"判断题","text":"《孙子兵法》的作者是春秋末期的孙武。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《孙子兵法》十三篇为春秋末期齐人孙武所著，是世界上现存最早的兵书。"},{"id":408,"type":"判断题","text":"\"三十六计\"中的每一计都有真实的战例可考。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"\"三十六计\"是古人对谋略的总结整理，其中不少取自传说或文学演绎，并非每计都有确切战例。"},{"id":409,"type":"判断题","text":"古代作战击鼓进军、鸣金收兵。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"击鼓表示进军冲锋，鸣金（敲钲）表示收兵撤退。"},{"id":410,"type":"判断题","text":"\"烽火\"是古代边防报警的信号。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"白天燃烟叫燧，夜间举火叫烽，烽火是边境报警传递军情的信号。"},{"id":411,"type":"判断题","text":"古代\"车裂\"俗称\"五马分尸\"，商鞅即遭此刑。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"车裂以车马分裂人体，商鞅被诬谋反，兵败身死后遭车裂之刑。"},{"id":412,"type":"判断题","text":"\"连坐\"指一人犯罪、亲属邻里连带受罚，商鞅变法时大力推行。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"商鞅变法实行什伍连坐法，一人犯罪，邻里不告发者同罪。"},{"id":413,"type":"判断题","text":"中国是世界上最早种植水稻的国家之一。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"河姆渡等遗址出土的稻谷证明，中国长江流域是世界上最早栽培水稻的地区之一。"},{"id":414,"type":"判断题","text":"牛耕在春秋战国时期逐步推广。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"春秋末期铁农具和牛耕出现，战国时期逐步推广，大大提高了农业生产力。"},{"id":415,"type":"判断题","text":"都江堰使成都平原成为\"天府之国\"。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"都江堰灌溉川西平原，旱涝保收，成都平原从此被称为\"天府之国\"。"},{"id":416,"type":"判断题","text":"古代\"镖局\"是专门护送财物、保障旅途安全的机构。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"镖局以武师押运银钱货物，收取镖资，是旧时保护运输安全的行业。"},{"id":417,"type":"判断题","text":"唐代长安城有东、西两市，是集中交易的商业区。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"唐长安城实行坊市分离，东市西市是固定的商业区，\"买东西\"一词与此有关。"},{"id":418,"type":"判断题","text":"《九章算术》是中国古代重要的数学著作。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《九章算术》成书于汉代，系统总结了先秦到汉代的数学成就。"},{"id":419,"type":"判断题","text":"火药是炼丹家在炼丹过程中偶然发明的。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"火药源于方士炼丹的意外发现，唐末开始用于军事。"},{"id":420,"type":"判断题","text":"指南针应用于航海不晚于北宋。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"北宋朱彧《萍洲可谈》已有广州海船用指南针航海的记载。"},{"id":421,"type":"判断题","text":"毕昇发明了泥活字印刷术。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"北宋庆历年间毕昇发明胶泥活字，是活字印刷术的开端。"},{"id":422,"type":"判断题","text":"沈括的《梦溪笔谈》被誉为\"中国科学史上的坐标\"。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《梦溪笔谈》记录了大量科技成就，英国学者李约瑟称其为\"中国科学史上的坐标\"。"},{"id":423,"type":"判断题","text":"李时珍用约二十七年时间写成《本草纲目》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"李时珍历时二十七年，三易其稿，完成一百九十多万字的《本草纲目》。"},{"id":424,"type":"判断题","text":"中医\"望、闻、问、切\"四诊法与扁鹊有关。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"四诊法在扁鹊（秦越人）时代已具雏形，后世归功于他。"},{"id":425,"type":"判断题","text":"孔子有弟子三千，其中贤者七十二人。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"相传孔子弟子三千，身通六艺者七十二人。"},{"id":426,"type":"判断题","text":"《论语》是孔子亲自撰写的著作。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["错误"],"explanation":"《论语》由孔子的弟子及再传弟子编纂，记录孔子及其弟子的言行。"},{"id":427,"type":"判断题","text":"\"己所不欲，勿施于人\"出自《论语》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"这是《论语》中孔子对\"恕\"的解释，是儒家处理人际关系的黄金法则。"},{"id":428,"type":"判断题","text":"孟子被后世尊称为\"亚圣\"。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"孟子继承并发展了孔子学说，地位仅次于孔子，被称为\"亚圣\"。"},{"id":429,"type":"判断题","text":"荀子是先秦儒家最后一位大师。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"荀子是战国末期儒家代表，先秦儒家思想的集大成者。"},{"id":430,"type":"判断题","text":"王阳明创立\"心学\"，主张\"知行合一\"。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"明代王阳明发展心学，提出\"知行合一\"\"致良知\"。"},{"id":431,"type":"判断题","text":"《周易》一书由\"经\"和\"传\"两部分组成。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《周易》包括卦爻辞的\"经\"和解释经文的\"传\"（十翼）两部分。"},{"id":432,"type":"判断题","text":"八卦相传为伏羲所创。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"传说伏羲仰观天文、俯察地理而画八卦。"},{"id":433,"type":"判断题","text":"韩非是先秦法家思想的集大成者。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"韩非综合商鞅之\"法\"、申不害之\"术\"、慎到之\"势\"，是法家集大成者。"},{"id":434,"type":"判断题","text":"成语\"塞翁失马\"出自《淮南子》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"\"塞翁失马，焉知非福\"出自《淮南子·人间训》。"},{"id":435,"type":"判断题","text":"\"精卫填海\"的故事出自《山海经》。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"炎帝之女溺于东海化为精卫鸟，衔木石以填海，事见《山海经》。"},{"id":436,"type":"判断题","text":"《诗经》分为\"风\"\"雅\"\"颂\"三部分。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"《诗经》按音乐性质分为风（国风）、雅（大雅小雅）、颂三部分。"},{"id":437,"type":"判断题","text":"《诗经》的主要表现手法是赋、比、兴。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"赋是铺陈直叙，比是打比方，兴是托物起兴，合称\"诗经六义\"之三。"},{"id":438,"type":"判断题","text":"爱国诗人屈原投的是汨罗江。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"楚国郢都被秦攻破后，屈原悲愤交加，投汨罗江而死。"},{"id":439,"type":"判断题","text":"汉赋是汉代流行的文学体裁。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"赋是汉代最具代表性的文体，讲究铺陈排比、辞藻华丽。"},{"id":440,"type":"判断题","text":"陶渊明是东晋著名的田园诗人。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"陶渊明弃官归隐，开田园诗派，\"采菊东篱下\"是其名句。"},{"id":441,"type":"判断题","text":"李白被称为\"诗仙\"，杜甫被称为\"诗圣\"。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"李白诗风飘逸，人称\"诗仙\"；杜甫忧国忧民，被尊为\"诗圣\"。"},{"id":442,"type":"判断题","text":"唐代\"古文运动\"的领袖是韩愈和柳宗元。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"韩愈、柳宗元倡导古文运动，反对骈文，主张文以载道。"},{"id":443,"type":"判断题","text":"甲骨文是目前所见最早的成体系的汉字。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"甲骨文已具备汉字构形的基本方法，是迄今所见最早的成熟汉字体系。"},{"id":444,"type":"判断题","text":"甲骨文发现于清末的河南安阳殷墟。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"1899年王懿荣首先鉴识甲骨文，其出土地为河南安阳小屯村殷墟。"},{"id":445,"type":"判断题","text":"秦始皇统一后\"书同文\"，以小篆为标准字体。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"秦统一后推行小篆为全国统一的规范文字。"},{"id":446,"type":"判断题","text":"楷书是由隶书演变而来的。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"楷书萌芽于汉末，由隶书简化演变而成，盛行于魏晋南北朝。"},{"id":447,"type":"判断题","text":"《四库全书》按经、史、子、集四部分类。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"乾隆年间编成的《四库全书》按经史子集四部分类，是我国最大的一部丛书。"},{"id":448,"type":"判断题","text":"孔子创办私学，打破了\"学在官府\"的垄断局面。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"孔子首开私人讲学之风，使学术下移民间。"},{"id":449,"type":"判断题","text":"太学设立于汉武帝时期。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"汉武帝采纳董仲舒建议，设立太学，是中国古代第一所官办最高学府。"},{"id":450,"type":"判断题","text":"岳麓书院是宋代著名的书院。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"岳麓书院创建于北宋，与白鹿洞、嵩阳、应天书院并称四大书院。"},{"id":451,"type":"判断题","text":"科举殿试一甲只录取三人。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"殿试一甲赐进士及第，仅取三名，即状元、榜眼、探花。"},{"id":452,"type":"判断题","text":"古代考试作弊夹带文字称\"怀挟\"。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"科举考场上夹带小抄、资料进场被称为\"怀挟\"，一经查出即予重惩。"},{"id":453,"type":"判断题","text":"\"颜筋柳骨\"说的是颜真卿、柳公权书法各自的特色。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"颜体浑厚丰腴、筋力饱满，柳体骨力劲健，故称\"颜筋柳骨\"。"},{"id":454,"type":"判断题","text":"\"扬州八怪\"是清代活跃于扬州画坛的画家群体。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"扬州八怪指清代扬州一批风格独特的画家，如郑板桥、金农等。"},{"id":455,"type":"判断题","text":"《千里江山图》是北宋王希孟的青绿山水名作。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"十八岁的王希孟在宋徽宗指点下绘成《千里江山图》，是青绿山水的巅峰之作。"},{"id":456,"type":"判断题","text":"编钟是中国古代重要的打击乐器。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"编钟由大小不同的钟编成，按音阶排列，用于宗庙祭祀和宴飨。"},{"id":457,"type":"判断题","text":"曾侯乙编钟出土于湖北随州。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"1978年湖北随州曾侯乙墓出土的编钟共六十五件，音域宽广。"},{"id":458,"type":"判断题","text":"中国是世界上最早种茶、饮茶的国家。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"中国是茶的故乡，种茶、制茶、饮茶都起源于中国。"},{"id":459,"type":"判断题","text":"被后人尊为\"茶圣\"的唐代人是陆羽。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"陆羽著《茶经》，系统总结种茶、制茶、饮茶之道，被尊为\"茶圣\"。"},{"id":460,"type":"判断题","text":"满汉全席是清代宫廷中盛大的宴席。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"满汉全席集满、汉菜肴之大成，是清代宫廷豪华宴席的总称。"},{"id":461,"type":"判断题","text":"四合院是北京等北方地区典型的传统民居。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"四合院四面房屋围合庭院，坐北朝南，是北方民居的典型形式。"},{"id":462,"type":"判断题","text":"福建土楼是客家民居的典型代表。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"福建西南部客家人聚族而居建起的圆楼方楼，被称为土楼。"},{"id":463,"type":"判断题","text":"围棋古称\"弈\"，是中国古人发明的棋类。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"围棋古称弈，相传为尧所造，是中国最古老的棋类游戏之一。"},{"id":464,"type":"判断题","text":"中国象棋棋盘上\"楚河汉界\"的名称与楚汉相争有关。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"\"楚河汉界\"源于刘邦项羽以鸿沟为界中分天下的历史。"},{"id":465,"type":"判断题","text":"春节在古代曾被称为\"元旦\"，指农历正月初一。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"辛亥革命前，农历正月初一称\"元旦\"，后公历1月1日改称元旦。"},{"id":466,"type":"判断题","text":"除夕\"守岁\"寓意辞旧迎新。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"除夕围炉不眠、待到天明叫守岁，寓意珍惜时光、辞旧迎新。"},{"id":467,"type":"判断题","text":"清明节既是节气又是传统节日。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"\"清明\"在二十四节气中占一位，又融合寒食禁火、扫墓踏青等习俗而成为节日。"},{"id":468,"type":"判断题","text":"端午节有赛龙舟、吃粽子的习俗。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"龙舟竞渡、包粽子相传都与纪念屈原有关。"},{"id":469,"type":"判断题","text":"腊月二十三（或二十四）祭灶，俗称\"小年\"。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"祭灶是春节的前奏，民间称这一天为小年。"},{"id":470,"type":"判断题","text":"贴春联时，上联一般贴在面对大门的右侧。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"按传统，上联贴右、下联贴左（面对大门），横批从右往左读。"},{"id":471,"type":"判断题","text":"属相（生肖）十二年一个轮回。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"十二生肖与十二地支相配，十二年一个轮回。"},{"id":472,"type":"判断题","text":"古代把一夜分为五更。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"一夜分为五更，每更约两个小时，三更即半夜。"},{"id":473,"type":"判断题","text":"\"五岳\"指泰山、华山、衡山、恒山、嵩山。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"东岳泰山、西岳华山、南岳衡山、北岳恒山、中岳嵩山，合称五岳。"},{"id":474,"type":"判断题","text":"\"文房四宝\"以湖笔、徽墨、宣纸、端砚最为著名。","options":[{"key":"正确","text":"正确"},{"key":"错误","text":"错误"}],"answer":["正确"],"explanation":"浙江湖州的笔、安徽徽州的墨、宣城的纸、肇庆的砚并称四宝名品。"},{"id":475,"type":"单选题","text":"春节贴____字，是中国民间由来已久的风俗，寄托了人们对美好生活的向往，也是对未来的祝愿。","options":[{"key":"A","text":"福"},{"key":"B","text":"喜"},{"key":"C","text":"吉"},{"key":"D","text":"祥"}],"answer":["A"],"explanation":"春节贴“福”字，是中国民间由来已久的风俗，寄托了人们对美好生活的向往，也是对未来的祝愿。据宋代《梦粱录》记载:“岁旦在迩，席铺百货，画门神桃符，迎春牌儿……”“士庶家不论大小，俱洒扫门闾，去尘秽，净庭户，换门神，挂钟馗，钉桃符，贴春牌，祭祀祖宗”。文中的“贴春牌”即是写在红纸上的“福”字。"},{"id":476,"type":"单选题","text":"有“文章巨公”和“百代文宗”之名的是____。","options":[{"key":"A","text":"李白"},{"key":"B","text":"韩愈"},{"key":"C","text":"杜甫"},{"key":"D","text":"白居易"}],"answer":["B"],"explanation":"韩愈，字退之，有“文章巨公”和“百代文宗”之称。"},{"id":477,"type":"单选题","text":"《定风波》这首词是苏轼被贬于____时外出有感而作的。","options":[{"key":"A","text":"黄州"},{"key":"B","text":"惠州"},{"key":"C","text":"儋州"},{"key":"D","text":"杭州"}],"answer":["A"],"explanation":"苏轼的《定风波·莫听穿林打叶声》是记事抒怀之词。作于宋神宗元丰五年（公元1082年）春，当时是苏轼因“乌台诗案”被贬为黄州团练副使的第三个春天。词人与朋友春日出游突遇风雨，词人却毫不在乎，泰然处之，吟咏自若，缓步而行。"},{"id":478,"type":"单选题","text":"“琴棋书画”是中国古代文人修身必备，被誉为“文人四友”，这里的“棋”指的是____。","options":[{"key":"A","text":"围棋"},{"key":"B","text":"中国象棋"},{"key":"C","text":"国际象棋"},{"key":"D","text":"跳棋"}],"answer":["A"],"explanation":"四艺，通常指中国文人所推崇和要掌握的四门艺术，即琴、棋、书、画，又称为“文人四艺”，或“秀才四艺”。“琴”指的是弹琴（多指古琴）、“棋”指的是弈棋（多指围棋和中国象棋）、“书”指的是书法、“画”指的是绘画。"},{"id":479,"type":"单选题","text":"写出下诗中缺失部分：____花落去，似曾相识燕归来。","options":[{"key":"A","text":"无可奈何"},{"key":"B","text":"似曾相识"},{"key":"C","text":"等闲识得"},{"key":"D","text":"无边落木"}],"answer":["A"],"explanation":"出自宋代晏殊的《浣溪沙·一曲新词酒一杯》\n一曲新词酒一杯，去年天气旧亭台。夕阳西下几时回？\n无可奈何花落去，似曾相识燕归来。小园香径独徘徊。"},{"id":480,"type":"单选题","text":"“唐太宗”的“太宗”指的是他的____。","options":[{"key":"A","text":"庙号"},{"key":"B","text":"谥号"},{"key":"C","text":"年号"},{"key":"D","text":"尊号"}],"answer":["A"],"explanation":"庙号是中国君主死后在庙中被供奉时所称呼的名号，起源于重视祭祀与敬拜的商朝。唐太宗，名李世民（599年1月23日—649年7月10日。他的名字意思是“济世安民”，太宗是他死后的庙号。"},{"id":481,"type":"单选题","text":"“三人行，必有我师”、“敏而好学，不耻下问”出自____。","options":[{"key":"A","text":"《孟子》"},{"key":"B","text":"《论语》"},{"key":"C","text":"《大学》"},{"key":"D","text":"《中庸》"}],"answer":["B"],"explanation":"《论语》，是春秋时期思想家、教育家孔子的弟子及再传弟子记录孔子及其弟子言行而编成的语录文集，成书于战国前期。全书共20篇492章，以语录体为主，叙事体为辅，较为集中地体现了孔子及儒家学派的政治主张、伦理思想、道德观念、教育原则等。"},{"id":482,"type":"单选题","text":"“好来宝”是____族的即兴诗。","options":[{"key":"A","text":"蒙古"},{"key":"B","text":"维吾尔"},{"key":"C","text":"藏族"},{"key":"D","text":"壮族"}],"answer":["A"],"explanation":"好来宝是中国蒙古族曲艺曲种，用蒙古语演唱。好来宝在蒙古语中意为“联韵”，即各句唱词的头一个音节谐韵，故又称联头韵。有的则将好来宝译为“连起来唱”或 “串起来唱”。2008年6月7日，好来宝经国务院批准列入第二批国家级非物质文化遗产名录。"},{"id":483,"type":"单选题","text":"世界遗产委员会第24届会议决定把龙门石窟列入《世界遗产名录》，龙门石窟位于河南省____市。","options":[{"key":"A","text":"洛阳"},{"key":"B","text":"郑州"},{"key":"C","text":"开封"},{"key":"D","text":"安阳"}],"answer":["A"],"explanation":"龙门石窟位于河南省洛阳市，是世界上造像最多、规模最大的石刻艺术宝库，被联合国科教文组织评为“中国石刻艺术的最高峰”，位居中国各大石窟之首。现为世界文化遗产、全国重点文物保护单位、国家AAAAA级旅游景区。"},{"id":484,"type":"单选题","text":"中国的四大发明是造纸术、指南针、火药、____。","options":[{"key":"A","text":"印刷术"},{"key":"B","text":"纺织术"},{"key":"C","text":"冶铁术"},{"key":"D","text":"制瓷术"}],"answer":["A"],"explanation":"中国四大发明是造纸术、指南针、火药、印刷术。四大发明是中国古代创新的智慧成果和科学技术，四大发明的概念却来源于西方学者，并在之后被中国人接受。意大利数学家杰罗姆·卡丹早在1550年就第一个指出，中国对世界所具有影响的“三大发明”：是司南（指南针）、印刷术和火药。来华传教士艾约瑟最先在三大发明中加入造纸术。"},{"id":485,"type":"单选题","text":"我国思想家____曾提出：学校应成为民主议政的场所。","options":[{"key":"A","text":"黄宗羲"},{"key":"B","text":"孔子"},{"key":"C","text":"孟子"},{"key":"D","text":"朱熹"}],"answer":["A"],"explanation":"黄宗羲“学校议政”思想主要体现于其著作《明夷待访录学校》中。该书曾被称为“反对君主专制主义的战斗檄文，代表了中国古代民主思想的最高成就”。学校议政思想可以概括为：学校反映民意，参与决策，舆论监督限制皇权、官权。在他看来，不是皇帝，而是“学校”形成的舆论，才是天下是非的标准，身为天子的皇上也要以其是非为是非。"},{"id":486,"type":"单选题","text":"“破釜沉舟”这个成语出于____。","options":[{"key":"A","text":"巨鹿之战"},{"key":"B","text":"长平之战"},{"key":"C","text":"官渡之战"},{"key":"D","text":"赤壁之战"}],"answer":["A"],"explanation":"巨鹿之战，是秦末大起义中项羽率领数万楚军（后期各诸侯义军也参战）同秦名将章邯、王离所率四十万秦军主力在巨鹿（现属邢台市平乡县地区）进行的一场重大决战性战役，也是中国历史上著名的以少胜多的战役之一。项羽破釜沉舟，以大无畏精神在各诸侯军畏缩不进时率先猛攻秦军，带动诸侯义军，一起最终全歼王离军，并于八个月后迫使另二十万章邯秦军投降。从此项羽确立了在各路义军中的领导地位。经此一战，加之刘邦西路大军攻破武关、蓝田，秦朝主力尽丧，加速覆亡。"},{"id":487,"type":"单选题","text":"“博士”作为官名最早出现在____朝。","options":[{"key":"A","text":"秦"},{"key":"B","text":"汉"},{"key":"C","text":"唐"},{"key":"D","text":"宋"}],"answer":["A"],"explanation":"博士，古为官名。秦汉时是掌管书籍文典、通晓史事的官职。"},{"id":488,"type":"单选题","text":"“吴带当风”是形容我国唐代画家____的笔法。","options":[{"key":"A","text":"吴道子"},{"key":"B","text":"阎立本"},{"key":"C","text":"张萱"},{"key":"D","text":"周昉"}],"answer":["A"],"explanation":"吴道子是中国山水画的祖师，被后人尊称为“画圣”，素有“吴带当风”的美誉，他的人物绘画更是“冠绝于世”。所绘人物，善用状如兰叶或蓴菜条之线条表现衣褶，使有飘举之势，人称“吴带当风”；又喜以焦墨勾线，略加淡彩设色，又称“吴装”。"},{"id":489,"type":"单选题","text":"我国历史上第一部编年体史书是____。","options":[{"key":"A","text":"《左传》"},{"key":"B","text":"《春秋》"},{"key":"C","text":"《史记》"},{"key":"D","text":"《资治通鉴》"}],"answer":["B"],"explanation":"《春秋》是中国第一部编年体史书，共三十五卷，是儒家经典之一且为十三经中篇幅最长的，在四库全书中列为经部。记述范围从公元前722（鲁隐公元年）至公元前468。"},{"id":490,"type":"单选题","text":"徐霞客曾经盛赞一座山为“四海名山皆过目，就中此景难图录”。这座山指的是____。","options":[{"key":"A","text":"黄山"},{"key":"B","text":"庐山"},{"key":"C","text":"雁荡山"},{"key":"D","text":"武夷山"}],"answer":["C"],"explanation":"徐霞客曾经盛赞一座山为：“四海名山皆过目，就中此景难图录。”这座山指的就是以山水奇秀闻名，素有“海上名山、寰中绝胜”之誉，史称中国“东南第一山”的雁荡山。据说，是因山顶有湖，芦苇茂密，结草为荡，南归秋雁多宿于此，故名雁荡。雁荡山开山凿胜始于南北朝，兴于唐，盛于宋。历代文人墨客纷至沓来，谢灵运、沈括、徐霞客等都是雁荡山的忠实拥趸，留下了不少诗篇。"},{"id":491,"type":"单选题","text":"____是中国境内最早的直立人。","options":[{"key":"A","text":"北京人"},{"key":"B","text":"元谋人"},{"key":"C","text":"山顶洞人"},{"key":"D","text":"蓝田人"}],"answer":["B"],"explanation":"元谋人，学名元谋直立人，或称元谋猿人，是在中国发现的直立人化石。1965年发现于云南元谋上那蚌村附近，共计左右门齿两颗。"},{"id":492,"type":"单选题","text":"三星堆遗址位于四川省广汉市，古蜀文化遗址，被誉为____文明之源。","options":[{"key":"A","text":"辽河"},{"key":"B","text":"黄河"},{"key":"C","text":"珠江"},{"key":"D","text":"长江"}],"answer":["D"],"explanation":"三星堆古遗址位于四川省广汉市西北的鸭子河南岸，分布面积12平方千米，距今已有5000至3000年历史，是迄今在西南地区发现的范围最大、延续时间最长、文化内涵最丰富的古城、古国、古蜀文化遗址。三星堆遗址被称为20世纪人类最伟大的考古发现之一，昭示了长江流域与黄河流域一样，同属中华文明的母体，被誉为“长江文明之源”。"},{"id":493,"type":"单选题","text":"最早关于八段锦的记录是在____代。","options":[{"key":"A","text":"唐"},{"key":"B","text":"明"},{"key":"C","text":"宋"},{"key":"D","text":"清"}],"answer":["C"],"explanation":"依据现有文献，八段锦之名最早出现在南宋洪迈撰写的《夷坚乙志》。"},{"id":494,"type":"单选题","text":"北宋书法四大家是黄庭坚、苏轼、米芾、____。","options":[{"key":"A","text":"苏轼"},{"key":"B","text":"蔡襄"},{"key":"C","text":"赵孟頫"},{"key":"D","text":"柳公权"}],"answer":["B"],"explanation":"宋四家是中国北宋时期四位书法家苏轼、黄庭坚、米芾和蔡襄的合称。这四个人大致可以代表宋代的书法风格，而且成就最高，故称“宋四家”。"},{"id":495,"type":"单选题","text":"“三吏三别”是《石壕吏》、《潼关吏》、《新安吏》和____、《垂老别》、《无家别》。","options":[{"key":"A","text":"《新婚别》《从军别》"},{"key":"C","text":"《离别别》"},{"key":"D","text":"《征人别》"}],"answer":["A"],"explanation":"“三吏三别”即《新安吏》《石壕吏》《潼关吏》《新婚别》《无家别》《垂老别》，是杜甫的作品，深刻写出了民间疾苦及在乱世之中身世飘荡的孤独，揭示了战争给人民带来的巨大不幸和困苦，表达了作者对倍受战祸摧残的老百姓的同情。","warnings":["原表选项 B 为空，已按原表保留其余选项与答案，建议核对原题。"]},{"id":496,"type":"单选题","text":"四大名旦是梅兰芳、程砚秋、尚小云、____。","options":[{"key":"A","text":"张君秋"},{"key":"B","text":"荀慧生"},{"key":"C","text":"言慧珠"},{"key":"D","text":"李世济"}],"answer":["B"],"explanation":"京剧四大名旦是指梅兰芳、程砚秋、尚小云、荀慧生，他们是中国京剧旦角行当中四大艺术流派的创始人。他们的优秀艺术，给人留下了不可磨灭的印象。"},{"id":497,"type":"单选题","text":"《水浒传》中吴用的绰号是____。","options":[{"key":"A","text":"智多星"},{"key":"B","text":"及时雨"},{"key":"C","text":"豹子头"},{"key":"D","text":"黑旋风"}],"answer":["A"],"explanation":"智多星是《水浒传》人物吴用的绰号。吴用满腹经纶，通晓文韬武略，足智多谋，常以诸葛亮自比，道号“加亮先生”，人称“智多星”。"},{"id":498,"type":"单选题","text":"“海上生明月，天涯共此时”的作者是____。","options":[{"key":"A","text":"李白"},{"key":"B","text":"杜甫"},{"key":"C","text":"张九龄"},{"key":"D","text":"王维"}],"answer":["C"],"explanation":"“海上生明月，天涯共此时”出自张九龄的《望月怀远》。表示一轮明日从海上慢慢升起，远在天边的亲人这时候一定和我一样在凝视着它。后用来表达对远方亲人的思念之情。"},{"id":499,"type":"单选题","text":"“无边落木萧萧下，不尽长江滚滚来”是____的作品。","options":[{"key":"A","text":"李白"},{"key":"B","text":"杜甫"},{"key":"C","text":"王维"},{"key":"D","text":"白居易"}],"answer":["B"],"explanation":"“无边落木萧萧下，不尽长江滚滚来”出自唐朝诗人杜甫的古诗作品《登高》第三四句，其全诗文如下：风急天高猿啸哀，渚清沙白鸟飞回。无边落木萧萧下，不尽长江滚滚来。万里悲秋常作客，百年多病独登台。艰难苦恨繁霜鬓，潦倒新停浊酒杯。"},{"id":500,"type":"单选题","text":"红杏尚书指的是____。","options":[{"key":"A","text":"欧阳修"},{"key":"B","text":"宋祁"},{"key":"C","text":"晏殊"},{"key":"D","text":"柳永"}],"answer":["B"],"explanation":"宋祁(公元998年-公元1061年)，字子京，小字选郎。是北宋官员、著名文学家、史学家、词人。司空宋庠之弟，宋祁与兄长宋庠并有文名，时称“二宋”。诗词语言工丽，因《玉楼春》词中有“红杏枝头春意闹”，世称“红杏尚书”。"},{"id":501,"type":"单选题","text":"词这种文体起于唐代盛于____代。","options":[{"key":"A","text":"元"},{"key":"B","text":"明"},{"key":"C","text":"清"},{"key":"D","text":"宋"}],"answer":["D"],"explanation":"词最初称为“曲词”或“曲子词”,是配音乐的。 后来词也跟乐府一样，逐渐跟音乐分离，成为诗的别体，所以有人把词 称为“诗余”。 因其每句的长短丌一，所以又称“长短句”。"},{"id":502,"type":"单选题","text":"将军百战死，壮士十年归中用了____的修辞手法。","options":[{"key":"A","text":"比喻"},{"key":"B","text":"互文"},{"key":"C","text":"拟人"},{"key":"D","text":"夸张"}],"answer":["B"],"explanation":"互文这种修辞手法，是古汉语中一种特殊的修辞手法。即 互文见义 ，是指在有意思相对或文句相关的词句里面，前后两句词语互相呼应，互相交错，意义上互相渗透、互相补充，使文句更加整齐和谐、更加精炼的一种修辞手法。"},{"id":503,"type":"单选题","text":"负荆请罪的故事主角是廉颇和____。","options":[{"key":"A","text":"诸葛亮"},{"key":"B","text":"蔺相如"},{"key":"C","text":"周瑜"},{"key":"D","text":"曹操"}],"answer":["B"],"explanation":"《史记·廉颇蔺相如列传》：相如曰：“夫以秦王之威，而相如廷叱之，辱其群臣，相如虽弩，独畏廉将军哉！顾吾念之，强秦之所以不敢加兵予赵者，徒以吾两人在也，今两虎共斗，其势不俱生，吾所以为此者，以先国家之急而后私仇也。”廉颇闻之，肉袒负荆。因宾客至蔺相如门谢罪，曰：“鄙贱之人，不知将军宽之至此也!”卒相与欢，为刎颈之交。后世据此典故提炼出成语“负荆请罪”。"},{"id":504,"type":"单选题","text":"“师者，所以传道受业解惑也。”中的“道”指的是____家礼教、思想。","options":[{"key":"A","text":"儒"},{"key":"B","text":"道"},{"key":"C","text":"法"},{"key":"D","text":"墨"}],"answer":["A"],"explanation":"此句出自韩愈的《师说》，意思是：老师，是用来传授知识、教授学业、解答疑惑的人。“道”指的是儒家礼教、思想。"},{"id":505,"type":"单选题","text":"岳飞出征前，岳母在他的背上刺了____四个大字。","options":[{"key":"A","text":"精忠报国"},{"key":"B","text":"忠君报国"},{"key":"C","text":"尽忠报国"},{"key":"D","text":"报国杀敌"}],"answer":["C"],"explanation":"岳飞出仕之前，其母在其背上刺上“尽忠报国”四字，以期岳飞日后能够为国竭尽忠诚。这是中国最著名的历史典故之一，常用以教育，激发青少年的爱国主义精神。"},{"id":506,"type":"单选题","text":"“就像没有那回事一样，形容态度镇定，不把事情放在心上。”这句话描述的是成语____。","options":[{"key":"A","text":"泰然自若"},{"key":"B","text":"处之泰然"},{"key":"C","text":"若无其事"},{"key":"D","text":"从容不迫"}],"answer":["C"],"explanation":"好像没有那么回事似的，形容不动声色或漠不关心。"},{"id":507,"type":"单选题","text":"《道德经》它是依据____的教诲编写而编写的。","options":[{"key":"A","text":"孔子"},{"key":"B","text":"庄子"},{"key":"C","text":"墨子"},{"key":"D","text":"老子"}],"answer":["D"],"explanation":"《道德真经》即《道德经》，又称《老子》、《老子五千文》。共81章，5000余言，分上下篇。老子著。"},{"id":508,"type":"单选题","text":"我国传统图案里以石榴象征____。","options":[{"key":"A","text":"富贵"},{"key":"B","text":"长寿"},{"key":"C","text":"吉祥"},{"key":"D","text":"多子"}],"answer":["D"],"explanation":"在中国传统文化中，石榴是吉祥的象征。它的果实里有很多石榴籽，寓意多子多福。所以可以送给已婚夫妇，代表多子多福。"},{"id":509,"type":"单选题","text":"“欲将轻骑逐”中“将”的意思是____。","options":[{"key":"A","text":"率领"},{"key":"B","text":"将要"},{"key":"C","text":"将领"},{"key":"D","text":"把"}],"answer":["A"],"explanation":"欲将轻骑逐，大雪满弓刀。出自卢纶的《和张仆射塞下曲六首》，意思是：正想要率领轻骑一路追杀，纷纷大雪，却已经洒满了将士的弓刀。"},{"id":510,"type":"单选题","text":"“在危急的时刻，猛然想出办法。”这句话描述的是成语____。","options":[{"key":"A","text":"急中生智"},{"key":"B","text":"随机应变"},{"key":"C","text":"从容不迫"},{"key":"D","text":"胸有成竹"}],"answer":["A"],"explanation":"急中生智是，汉语成语，拼音是jí zhōng shēng zhì，意思是形容事态紧急的时候，突然想出办法。出自《和微之诗二十三首序》。"},{"id":511,"type":"单选题","text":"“斯恶已”中“恶”的解释是____。","options":[{"key":"A","text":"丑陋"},{"key":"B","text":"邪恶"},{"key":"C","text":"厌恶"},{"key":"D","text":"恶劣"}],"answer":["A"],"explanation":"天下皆知美之为美,斯恶已。皆知善之为善,斯不善已。摘自《老子·道经·第二章》 解释：当天下的人都知道都认为这件事是美好的话,那么它丑恶的一面就显现出来了。"},{"id":512,"type":"单选题","text":"我国文房四宝是____。","options":[{"key":"A","text":"琴棋书画"},{"key":"B","text":"笔墨纸砚"},{"key":"C","text":"梅兰竹菊"},{"key":"D","text":"诗词歌赋"}],"answer":["B"],"explanation":"笔墨纸砚，是中国独有的文书工具，即文房四宝。"},{"id":513,"type":"单选题","text":"《礼记》中认为人的七情是指喜、怒、哀、乐、爱、恶、____。","options":[{"key":"A","text":"惧"},{"key":"B","text":"欲"},{"key":"C","text":"忧"},{"key":"D","text":"思"}],"answer":["B"],"explanation":"七情按《礼记》的观点指喜、怒、哀、惧、爱、恶、欲，按儒家的说法是喜、怒、哀、惧、爱、恶、欲，按佛教的说法则是喜、怒、忧、惧、爱、憎、欲，而医家的七情是喜、怒、忧、思、悲、恐、惊。"},{"id":514,"type":"单选题","text":"“天下第一行书”是王羲之的____。","options":[{"key":"A","text":"《快雪时晴帖》"},{"key":"B","text":"《丧乱帖》"},{"key":"C","text":"《兰亭集序》"},{"key":"D","text":"《二谢帖》"}],"answer":["C"],"explanation":"《兰亭集序》，又题为《临河序》、《禊帖》、《三月三日兰亭序》等。晋穆帝永和九年（公元353）三月三日，时任会稽内史的王羲之与友人谢安、孙绰等四十一人会聚兰亭，赋诗饮酒。王羲之将诸人名爵及所赋诗作编成一集，并作序一篇，记述流觞曲水一事，并抒写由此而引发的内心感慨。这篇序文就是《兰亭集序》。此序受石崇《金谷诗序》影响很大，其成就又远在《金谷诗序》之上。"},{"id":515,"type":"单选题","text":"书法史上的“二王”是指王羲之和____两位书法家。","options":[{"key":"A","text":"王徽之"},{"key":"B","text":"王凝之"},{"key":"C","text":"王献之"},{"key":"D","text":"王玄之"}],"answer":["C"],"explanation":"“二王”书法家是指王羲之和王献之，他们二人为父子，是东晋时期的大书法家。"},{"id":516,"type":"单选题","text":"《祭侄文稿》被誉为“天下第二行书”，它的作者是____。","options":[{"key":"A","text":"柳公权"},{"key":"B","text":"欧阳询"},{"key":"C","text":"颜真卿"},{"key":"D","text":"褚遂良"}],"answer":["C"],"explanation":"《祭侄文稿》，全名《祭侄赠赞善大夫季明文文稿》，俗谓《祭侄稿》。为唐朝书法家颜真卿所书，后世誉为“天下行书第二”，真迹现藏于台北国立故宫博物院。"},{"id":517,"type":"单选题","text":"我国文学史上第一部诗歌总集____。","options":[{"key":"A","text":"《楚辞》"},{"key":"B","text":"《乐府诗集》"},{"key":"C","text":"《诗经》"},{"key":"D","text":"《古诗十九首》"}],"answer":["C"],"explanation":"《诗经》，是中国古代诗歌开端，最早的一部诗歌总集，收集了西周初年至春秋中叶(前11世纪至前6世纪)的诗歌，共311篇，其中6篇为笙诗，即只有标题，没有内容，称为笙诗六篇(《南陔》《白华》《华黍》《由庚》《崇丘》《由仪》)，反映了周初至周晚期约五百年间的社会面貌。"},{"id":518,"type":"单选题","text":"杰出的女纺织家黄道婆向____妇女学习棉纺织技术。","options":[{"key":"A","text":"壮族"},{"key":"B","text":"傣族"},{"key":"C","text":"黎族"},{"key":"D","text":"彝族"}],"answer":["C"],"explanation":"黄道婆，又名黄婆、黄母，是原松江府乌泥泾(今属上海市)人，宋末元初著名的棉纺织家、技术改革家。幼时为童养媳，曾因不堪虐待流落崖州(治所在今海南省三亚市崖城镇)，定居约40年，向黎族妇女学习棉纺织技艺并有改进，总结出“错纱、配色、综线、挈花”的织造技术。"},{"id":519,"type":"单选题","text":"傈傈族语属于____语系。","options":[{"key":"A","text":"汉藏"},{"key":"B","text":"阿尔泰"},{"key":"C","text":"南岛"},{"key":"D","text":"印欧"}],"answer":["A"],"explanation":"傈僳语属汉藏语系-藏缅语族-彝语支。"},{"id":520,"type":"单选题","text":"芳华越剧团的创始人是____。","options":[{"key":"A","text":"袁雪芬"},{"key":"B","text":"尹桂芳"},{"key":"C","text":"傅全香"},{"key":"D","text":"王文娟"}],"answer":["B"],"explanation":"福建省芳华越剧团，原为上海市芳华越剧团，由著名越剧表演艺术家尹桂芳于1946年在上海创建。"},{"id":521,"type":"单选题","text":"“徐黄异体”指的是五代画家____和黄筌的花鸟画风格。","options":[{"key":"A","text":"徐渭"},{"key":"B","text":"黄居寀"},{"key":"C","text":"徐熙"},{"key":"D","text":"赵昌"}],"answer":["C"],"explanation":"徐熙画派，中国画流派之一。为五代花鸟画派的一支，代表画家徐熙。北宋郭若虚在《图画见闻志》\"论黄、徐体异\"时说\"黄家富贵，徐熙野逸。\"又说\"徐熙江南处士\"，\"多状江南所有，汀花野竹，水鸟渊鱼。\"此派多作粗笔浓墨，略施杂彩，而笔迹不隐，素有\"落墨花\"之称。"},{"id":522,"type":"单选题","text":"中国现存最大的两座古代木构殿堂是____和凌恩殿。","options":[{"key":"A","text":"中和殿"},{"key":"B","text":"保和殿"},{"key":"C","text":"乾清宫"},{"key":"D","text":"太和殿"}],"answer":["D"],"explanation":"太和殿俗称金銮殿，为汉族宫殿建筑之精华，东方三大殿之一。中国现存最大的木结构大殿。位于北京紫禁城(故宫)南北主轴线的显要位置，明永乐十八年(1420年)建成，称奉天殿。明嘉靖四十一年(1562年)改称皇极殿，清顺治二年(1645年)改今名。建成后屡遭焚毁，多次重建，今殿为清康熙三十四年(1695年)重建后的形制。"},{"id":523,"type":"单选题","text":"补全诗句：“沧海月明珠有泪，蓝田日暖____。”","options":[{"key":"A","text":"玉生烟"},{"key":"B","text":"珠生辉"},{"key":"C","text":"月生辉"},{"key":"D","text":"石生烟"}],"answer":["A"],"explanation":"沧海月明珠有泪，蓝田日暖玉生烟：在明亮的月色中，我的眼泪流泻不止；在温暖的阳光下，依稀望见蓝田山上紫玉化成的青烟。"},{"id":524,"type":"单选题","text":"在我国古代，“鱼书”指的是____。","options":[{"key":"A","text":"鱼类图鉴"},{"key":"B","text":"书信"},{"key":"C","text":"捕鱼工具"},{"key":"D","text":"渔业书籍"}],"answer":["B"],"explanation":"鱼书是古时对书信的称谓。纸张出现以前，书信多写在白色丝绢上，为使传递过程中不致损毁，古人常把书信扎在两片竹木简中，简多刻成鱼形，故称鱼书。"},{"id":525,"type":"单选题","text":"袁雪芬、严凤英、红线女、叶盛兰分别是越剧、____、粤剧、京剧的著名演员。","options":[{"key":"A","text":"评剧"},{"key":"B","text":"黄梅戏"},{"key":"C","text":"豫剧"},{"key":"D","text":"吕剧"}],"answer":["B"],"explanation":"袁雪芬、严凤英、红线女、叶盛兰分别是越剧、黄梅戏、粤剧、京剧的著名演员。"},{"id":526,"type":"单选题","text":"《兰亭序》、《九成宫醴泉铭》、《石门颂》、《泰山刻石》分别是行书、楷书、隶书和____的代表作。","options":[{"key":"A","text":"大篆"},{"key":"B","text":"草书"},{"key":"C","text":"小篆"},{"key":"D","text":"魏碑"}],"answer":["C"],"explanation":"《泰山刻石》是刊刻于秦代的一方摩崖石刻，分为两部分，传为李斯撰文并书丹， 又称“李斯碑”等，属小篆书法作品。"},{"id":527,"type":"单选题","text":"诗句“天下伤心处，劳劳送客亭。春风知别苦，不遣柳条青”的作者是____。","options":[{"key":"A","text":"杜甫"},{"key":"B","text":"李白"},{"key":"C","text":"王维"},{"key":"D","text":"白居易"}],"answer":["B"],"explanation":"《劳劳亭》，是由唐代著名诗人、文学家、浪漫主义诗人李白所作的一首五言绝句，其所作年代殆已不可切考，似为作者漫游金陵时作。诗中虽有送别之意，却无送别之人、之事，只是因地起意，借景抒情，故以亭为题来表达人间的离别之苦。"},{"id":528,"type":"单选题","text":"京杭大运河数段中最早开凿的是____。","options":[{"key":"A","text":"邗沟"},{"key":"B","text":"通济渠"},{"key":"C","text":"永济渠"},{"key":"D","text":"江南河"}],"answer":["A"],"explanation":"京杭大运河最早开凿的河段是邗沟，从春秋吴王夫差十年起，以通江淮为起始点，之后是隋朝的运河系统，历经了元、明、清三个朝代的扩展，才初具规模，有了世界第一大运河的雏形，为我国的经济文化繁荣发展做出了杰出的贡献。"},{"id":529,"type":"单选题","text":"儒家文化主要是政治、伦理道德文化。如果说儒家文化是“入世”文化的话，那么道、佛文化则是____文化。","options":[{"key":"A","text":"出世"},{"key":"B","text":"入世"},{"key":"C","text":"现世"},{"key":"D","text":"济世"}],"answer":["A"],"explanation":"儒家文化主要是政治、伦理道德文化。如果说儒家文化是“入世”文化的话，那么道、佛文化则是“出世”文化。它们相辅相成，互为表里，构成传统文化的主体。出世：古代一种对世俗之事不关注的思想。“世”则指凡尘俗世。"},{"id":530,"type":"单选题","text":"耄耋之年指____岁。","options":[{"key":"A","text":"五六十"},{"key":"B","text":"八九十"},{"key":"C","text":"七八十"},{"key":"D","text":"六七十"}],"answer":["B"],"explanation":"耄耋之年是一个汉语成语，用作对老年人的泛称，指八九十岁。出自曹操《对酒》：“耄耋皆得以寿终，恩泽广及草木昆虫。”"},{"id":531,"type":"单选题","text":"上元节的时间是____，张灯为戏，又叫“灯节”。","options":[{"key":"A","text":"正月初一"},{"key":"B","text":"正月十五"},{"key":"C","text":"五月初五"},{"key":"D","text":"八月十五"}],"answer":["B"],"explanation":"元宵节，又称上元节、小正月、元夕或灯节，时间为每年农历正月十五。\n正月是农历的元月，古人称“夜”为“宵”，正月十五是一年中第一个月圆之夜，所以称正月十五为“元宵节”。根据道教“三元”的说法，正月十五又称为“上元节”。元宵节习俗自古以来就以热烈喜庆的观灯习俗为主。"},{"id":532,"type":"单选题","text":"汉字六书是____、指事、形声、会意、转注、假借。","options":[{"key":"A","text":"象形"},{"key":"B","text":"象声"},{"key":"C","text":"指示"},{"key":"D","text":"假使"}],"answer":["A"],"explanation":"六书，首见于《周礼·地官·保氏》，汉代学者把汉字的构成和使用方式归纳成六种类型，总称六书。普遍采取的是许慎的名称、班固的次序。后世学者定名为象形、指事、会意、形声、转注、假借。 六书是后人对汉字进行分析而归纳出来的系统，也是最早的关于汉字构造的系统理论。当有了六书系统以后，人们再造新字时，都以该系统为依据。"},{"id":533,"type":"单选题","text":"书法九势是____、转笔、藏峰、藏头、护尾、疾势、掠笔、涩势、横鳞竖勒。","options":[{"key":"A","text":"落笔"},{"key":"B","text":"起笔"},{"key":"C","text":"收笔"},{"key":"D","text":"运笔"}],"answer":["A"],"explanation":"书法九势为落笔、转笔、藏锋、藏头、护尾、疾势、掠笔、涩势、横鳞竖勒，为汉代书法家蔡邕对书法中行笔技巧的总结。"},{"id":534,"type":"单选题","text":"竹林七贤是____、刘伶、阮籍、山涛、阮咸、向秀、王戎。","options":[{"key":"A","text":"曹植"},{"key":"B","text":"嵇康"},{"key":"C","text":"陶渊明"},{"key":"D","text":"谢灵运"}],"answer":["B"],"explanation":"竹林七贤指的是三国魏正始年间（240年—249年），嵇康、阮籍、山涛、向秀、刘伶、王戎及阮咸七人。因常在当时的山阳县(今河南焦作修武县，可能为现今云台山一带)竹林之下，喝酒、纵歌，肆意酣畅，世谓七贤，后与地名竹林合称。"},{"id":535,"type":"单选题","text":"饮中八仙为____、贺知章、李适之、李琎、崔宗之、苏晋、张旭、焦遂。","options":[{"key":"A","text":"杜甫"},{"key":"B","text":"王维"},{"key":"C","text":"李白"},{"key":"D","text":"白居易"}],"answer":["C"],"explanation":"醉八仙，指唐朝嗜酒的八位学者名人，亦称酒中八仙、饮中八仙。《新唐书·李白传》载，李白、贺知章、李适之、汝阳王李琎、崔宗之、苏晋、张旭、焦遂为“酒中八仙人”。杜甫有《饮中八仙歌》。瓷器画面绘饮中八仙，每每于人物之上书以人名，以清朝为多见。"},{"id":536,"type":"单选题","text":"扬州八怪是郑板桥、汪士慎、李鱓、黄慎、金农、高翔、李方鹰、____。","options":[{"key":"A","text":"吴昌硕"},{"key":"B","text":"罗聘"},{"key":"C","text":"齐白石"},{"key":"D","text":"任伯年"}],"answer":["B"],"explanation":"扬州八怪，是清康熙中期至乾隆末年活跃于扬州地区的一批风格相近的书画家总称，美术史上也常称其为“扬州画派”，指：金农、郑燮、黄慎、李鱓、李方膺、汪士慎、罗聘、高翔。"},{"id":537,"type":"单选题","text":"“河鼓二”在天文学上是指____。","options":[{"key":"A","text":"织女星"},{"key":"B","text":"牛郎星"},{"key":"C","text":"天狼星"},{"key":"D","text":"北极星"}],"answer":["B"],"explanation":"河鼓二指天鹰座α星，又称“牛郎星”。古代传说牛郎织女七月七日鹊桥相会。实际上牛郎织女相距16光年，即使乘现代最强大的火箭，几百年后也不曾相会。河鼓二的两侧各有一颗较暗的星，分别称为河鼓一、河鼓三，它们与河鼓二合称为“河鼓三星”。河鼓三星像一根长长的扁担，所以民间又叫它“扁担星”。"},{"id":538,"type":"单选题","text":"唐宋八大家是____、柳宗元、欧阳修、苏洵、苏轼、苏辙、王安石、曾巩。","options":[{"key":"A","text":"韩愈"},{"key":"B","text":"李白"},{"key":"C","text":"杜甫"},{"key":"D","text":"白居易"}],"answer":["A"],"explanation":"唐宋八大家，又称为“唐宋散文八大家”，是唐代和宋代八位散文家的合称，分别为唐代韩愈、柳宗元和宋代欧阳修、苏洵、苏轼、苏辙、王安石、曾巩八位。其中韩愈、柳宗元是唐代古文运动的领袖，欧阳修、三苏（苏轼、苏辙、苏洵）等四人是宋代古文运动的核心人物，王安石、曾巩是临川文学的代表人物。他们先后掀起的古文革新浪潮，使诗文发展的陈旧面貌焕然一新。"},{"id":539,"type":"单选题","text":"四大民间传说是____、孟姜女、梁山伯与祝英台、白蛇与许仙。","options":[{"key":"A","text":"牛郎织女"},{"key":"B","text":"八仙过海"},{"key":"C","text":"嫦娥奔月"},{"key":"D","text":"愚公移山"}],"answer":["A"],"explanation":"在我国的古典文学宝库中，除了有史书记载的古典文学作品外，还有一类就是民间广为流传的神话传说，它不仅数量众多，内容丰富，而且绚丽多彩，充满诗情画意和艺术魅力，其中牛郎织女、孟姜女、梁山伯与祝英台与白蛇传被称为中国四大民间传说。"},{"id":540,"type":"单选题","text":"元代四大戏剧是____、王实甫《西厢记》、马致远《汉宫秋》、白朴《梧桐雨》。","options":[{"key":"A","text":"关汉卿《窦娥冤》"},{"key":"B","text":"洪升《长生殿》"},{"key":"C","text":"白朴《墙头马上》"},{"key":"D","text":"郑光祖《倩女离魂》"}],"answer":["A"],"explanation":"元代四大戏剧是关汉卿的《窦娥冤》、王实甫的《西厢记》、汤显祖的《牡丹亭》、洪升的《长生殿》。"},{"id":541,"type":"单选题","text":"相声八德是____、玉德隆、焦德海、张德全、周德山、马德禄、刘德治、李德祥。","options":[{"key":"A","text":"马三立"},{"key":"B","text":"李德钖"},{"key":"C","text":"侯宝林"},{"key":"D","text":"刘宝瑞"}],"answer":["B"],"explanation":"李德钖(1881-1926)，相声艺人。原名李佩亭，艺名万人迷。北京人。时人誉之为“相声大王”，与其他七位“德”字辈著名相声艺人并称“相声八德”。作品有《老老年》《对对子》《哭当票》《十八愁绕口令》。"},{"id":542,"type":"单选题","text":"五代是后梁、后唐、后晋、后汉、____。","options":[{"key":"A","text":"后周"},{"key":"B","text":"北周"},{"key":"C","text":"北齐"},{"key":"D","text":"南齐"}],"answer":["A"],"explanation":"五代是指唐天佑四年(907年)唐朝灭亡后依次定都于中原地区的五个政权，即后梁、后唐、后晋、后汉和后周。"},{"id":543,"type":"单选题","text":"五贡是____、拔贡、岁贡、副贡、优贡。","options":[{"key":"A","text":"功贡"},{"key":"B","text":"恩贡"},{"key":"C","text":"劳贡"},{"key":"D","text":"勋贡"}],"answer":["B"],"explanation":"清代科举制度中对五类贡生的总称.。包括:恩贡、拔贡、副贡、岁贡和优贡。这五类都是正途出身资格。另有捐纳取得的贡生，称为例贡。"},{"id":544,"type":"单选题","text":"六历是____、《颛顼历》、《夏历》、《殷历》、《周历》、《鲁历》。","options":[{"key":"A","text":"《神农历》"},{"key":"B","text":"《伏羲历》"},{"key":"C","text":"《黄帝历》"},{"key":"D","text":"《尧历》"}],"answer":["C"],"explanation":"古六历通常是指从春秋战国到秦朝时期制定的黄帝、颛、夏、殷、周、鲁六种历法。六历的不同主要是“历元”（年的起算点）、施行地区和所用的元朔。"},{"id":545,"type":"单选题","text":"三山是指安徽____、江西庐山、浙江雁荡山。","options":[{"key":"A","text":"天柱山"},{"key":"B","text":"九华山"},{"key":"C","text":"黄山"},{"key":"D","text":"齐云山"}],"answer":["C"],"explanation":"三山是指旅游胜地闻名的黄山、庐山、雁荡山。"},{"id":546,"type":"单选题","text":"五岭是指____、都庞岭、萌诸岭、骑田岭、大庾岭。","options":[{"key":"A","text":"武夷山"},{"key":"B","text":"越城岭"},{"key":"C","text":"南岭"},{"key":"D","text":"秦岭"}],"answer":["B"],"explanation":"五岭：三个在湘桂间，因此一般是由西到东地排列，指越城岭(湘桂间)、都庞岭(湘桂间)、萌渚岭(湘桂间)、骑田岭(湘南)、大庾岭(赣粤间，腹地在江西大庾县)，横亘在湖南、两广、江西之间。是史称南岭者的主要构成。"},{"id":547,"type":"单选题","text":"“但愿人长久，千里共婵娟”，其中“婵娟”指的是____。","options":[{"key":"A","text":"时光"},{"key":"B","text":"书信"},{"key":"C","text":"美人"},{"key":"D","text":"月亮"}],"answer":["D"],"explanation":"“婵娟,指美好的事物，在这首诗里特指月亮。“但愿人长久，千里共婵娟。”的意思是:只希望自己思念的人平安长久，不管相隔千山万水，都可以一起看到明月皎洁美好的样子。这句话常用于表达对远方亲人的思念之情以及美好祝愿。"},{"id":548,"type":"单选题","text":"“爆竹声中一岁除，春风送暖入屠苏”，这里的“屠苏”指的是____。","options":[{"key":"A","text":"服饰"},{"key":"B","text":"房屋"},{"key":"C","text":"酒"},{"key":"D","text":"食物"}],"answer":["C"],"explanation":"屠苏，是酒名。古代汉族风俗于农历正月初一饮屠苏酒以避瘟疫。"},{"id":549,"type":"单选题","text":"“月上柳梢头，人约黄昏后”描写的传统节日是____。","options":[{"key":"A","text":"端午节"},{"key":"B","text":"中秋节"},{"key":"C","text":"元宵节"},{"key":"D","text":"七夕节"}],"answer":["C"],"explanation":"“月上柳梢头，人约黄昏后”是北宋诗人欧阳修写的一首词，名为：《生查子•元夕》 ，全词：去年元夜时，花市灯如昼。月上柳梢头，人约黄昏后。今年元夜时，月与灯依旧。不见去年人，泪湿春衫袖。整首词创作背景是一年的伊始之际——元宵。"},{"id":550,"type":"单选题","text":"百家姓中没有____姓。","options":[{"key":"A","text":"肖"},{"key":"B","text":"萧"},{"key":"C","text":"赵"},{"key":"D","text":"钱"}],"answer":["A"],"explanation":"百家姓中没有肖姓,只有萧姓。 《百家姓》成文于北宋初,原收集姓氏411个,后增补到504个，其中单姓444个，复姓60个。在《百家姓》中并没有肖姓。我国在20世纪70年代推行二简字之后，“萧”整个字的所有义项都被合并到“肖”(不仅姓氏)。于是所有的萧姓被写为肖姓，可后来正式废除二简字。"},{"id":551,"type":"单选题","text":"诸子百家中名家的特点是注重逻辑辩证，____这个典故能表达名家的这一特点。","options":[{"key":"A","text":"守株待兔"},{"key":"B","text":"白马非马"},{"key":"C","text":"刻舟求剑"},{"key":"D","text":"掩耳盗铃"}],"answer":["B"],"explanation":"“名家”是先秦时期以辩论名实问题为中心的一个思想派别,重视“名”(概念)和“实”(事)的关系的研究。包括“白马非马”、“离坚白”、“合同异”等观点。"},{"id":552,"type":"单选题","text":"古人的婚礼在____（时间）举行。","options":[{"key":"A","text":"清晨"},{"key":"B","text":"正午"},{"key":"C","text":"深夜"},{"key":"D","text":"黄昏"}],"answer":["D"],"explanation":"古人结婚时间一般是黄昏。无论是因为黄昏的昏和结婚的婚读音很接近的缘故，还是因为黄昏风景美丽的缘故，古人大多数都选择在黄昏结婚。"},{"id":553,"type":"单选题","text":"“天时不如地利，地利不如人和”出自____。","options":[{"key":"A","text":"《韩非子》"},{"key":"B","text":"《老子》"},{"key":"C","text":"《孟子》"},{"key":"D","text":"《论语》"}],"answer":["C"],"explanation":"《天时不如地利，地利不如人和》出自《孟子·公孙丑下》。天时不如地利，地利不如人和的意思是：有利的时机和气候不如有利的地势，有利的地势不如人心所向。"},{"id":554,"type":"单选题","text":"文学史上被称作“小李杜”的是杜牧和____。","options":[{"key":"A","text":"李白"},{"key":"B","text":"杜甫"},{"key":"C","text":"李商隐"},{"key":"D","text":"李贺"}],"answer":["C"],"explanation":"唐诗中以李白、杜甫的作品最享负盛名。至中晚唐，诗风的发展已近末流。因珠玉在前，后人已难有突破。当时一般诗人虽偶有佳作，但惟有杜牧和李商隐二人，能被时人一致公认为最杰出的作家。鉴於二人刚巧一位姓李,一位姓杜，与盛唐李杜相同，故称其为小李杜，以示与李白杜甫齐名。"},{"id":555,"type":"单选题","text":"我国书法艺术博大精深，“欧体”是指____的字体。","options":[{"key":"A","text":"欧阳修"},{"key":"B","text":"欧阳通"},{"key":"C","text":"欧阳询"},{"key":"D","text":"欧大任"}],"answer":["C"],"explanation":"书法上的“欧体”是指欧阳询的字体，对应于楷书四大家“颜柳欧赵”中的欧，欧体结构严谨，于平正中见险绝，被尊为“唐人楷书第一”。"},{"id":556,"type":"单选题","text":"“大禹治水”的故事家喻户晓，大禹治理的是____流域的洪水。","options":[{"key":"A","text":"长江"},{"key":"B","text":"淮河"},{"key":"C","text":"黄河"},{"key":"D","text":"珠江"}],"answer":["C"],"explanation":"大禹治水(鲧禹治水)是古代的汉族神话传说故事，著名的上古大洪水传说。他是黄帝的后代，三皇五帝时期，黄河泛滥，鲧、禹父子二人受命于尧、舜二帝，任崇伯和夏伯，负责治水。这一时期，黄河流域水患特别严重，百姓经常因为水患而流离失所，庄家更是颗粒无收，正因如此，治理黄河水患的问题一直困扰着人们。到了尧舜时期，黄河流域流水情况更加不稳定，已经到了不可不治的状况了。"},{"id":557,"type":"单选题","text":"《西游记》中唐僧的原型是____。","options":[{"key":"A","text":"鉴真"},{"key":"B","text":"法显"},{"key":"C","text":"玄奘"},{"key":"D","text":"一行"}],"answer":["C"],"explanation":"唐僧，俗家姓陈，生于河南洛阳，法号“玄奘”，被尊称为“三藏法师”，世俗称为“唐僧”，小名叫“江流儿”。中国古典名著《西游记》中的主角之一，原型为唐代高僧玄奘。"},{"id":558,"type":"单选题","text":"被誉为“万园之园”的是____。","options":[{"key":"A","text":"颐和园"},{"key":"B","text":"拙政园"},{"key":"C","text":"圆明园"},{"key":"D","text":"留园"}],"answer":["C"],"explanation":"圆明园是清代大型皇家园林，由圆明园及其附园长春园和绮春园（后改称万春园）组成，通称为“圆明三园”。圆明园占地面积3.5平方千米，规模宏伟，有一百五十余景，融会了各式园林风格，有“万园之园”之称，被誉为“一切造园艺术的典范”。"},{"id":559,"type":"单选题","text":"京剧《贵妃醉酒》是根据____这部古代戏曲改编而成的。","options":[{"key":"A","text":"《西厢记》"},{"key":"B","text":"《牡丹亭》"},{"key":"C","text":"《桃花扇》"},{"key":"D","text":"《长生殿》"}],"answer":["D"],"explanation":"京剧中《贵妃醉酒》是由《长生殿》这部古代戏曲改编而成的，这首曲子讲述的是唐玄宗和杨玉环的爱情故事。"},{"id":560,"type":"单选题","text":"“讳疾忌医”典故中的君王是____。","options":[{"key":"A","text":"楚庄王"},{"key":"B","text":"晋文公"},{"key":"C","text":"齐桓公"},{"key":"D","text":"蔡桓公"}],"answer":["D"],"explanation":"讳疾忌医是一个汉语成语，最早出自战国韩非的《韩非子·喻老》，讲述扁鹊为蔡桓公多次“诊病”而蔡桓公却多次“忌医”的故事。"},{"id":561,"type":"单选题","text":"“一门父子三词客，千古文章八大家”这幅对联中提到的“三父子”是苏洵、苏轼、____。","options":[{"key":"A","text":"苏秦"},{"key":"B","text":"苏代"},{"key":"C","text":"苏过"},{"key":"D","text":"苏辙"}],"answer":["D"],"explanation":"“一门父子三词客，千古文章八大家”中三词客为：北宋苏洵、苏轼、苏辙；这是对苏轼、苏辙、苏洵三父子在文坛上的成就的褒奖"},{"id":562,"type":"单选题","text":"“一问三不知”，“三不知”说的是事情的开始、经过、____。","options":[{"key":"A","text":"原因"},{"key":"B","text":"影响"},{"key":"C","text":"背景"},{"key":"D","text":"结果"}],"answer":["D"],"explanation":"出自《左传·哀公二十七年》，原意是对某一事情的开始、发展、结果都不知道，现在用来表示对实际情况一点也不知道。"},{"id":563,"type":"单选题","text":"“弱冠”指的是男子____岁。","options":[{"key":"A","text":"十八"},{"key":"B","text":"十六"},{"key":"C","text":"十五"},{"key":"D","text":"二十"}],"answer":["D"],"explanation":"古代男子二十岁行冠礼，表示已经成人，因还没到壮年，叫作弱冠，后泛指男子二十左右的年纪。"},{"id":564,"type":"单选题","text":"唱念做打是中国戏曲表演的四种艺术手段，也是戏曲表演的四项根本功，其中____指的是器械表演。","options":[{"key":"A","text":"打"},{"key":"B","text":"念"},{"key":"C","text":"唱"},{"key":"D","text":"做"}],"answer":["D"],"explanation":"唱念做打是京剧表演的四种艺术手段，也是京剧表演的四项基本功。唱指歌唱，念指具有音乐性的念白，二者相辅相成，构成歌舞化的京剧表演艺术两大要素之一的“歌”，做指舞蹈化的形体动作，打指武打和翻跌的技艺，二者相互结合，构成歌舞化的京剧表演艺术两大要素之一的“舞”。"},{"id":565,"type":"单选题","text":"水浒一百单八将中有____位女性。","options":[{"key":"A","text":"三"},{"key":"B","text":"四"},{"key":"C","text":"五"},{"key":"D","text":"二"}],"answer":["A"],"explanation":"水浒传108将中的三名女将分别是顾大嫂、扈三娘、还有孙二娘，其中顾大嫂的结局最好。"},{"id":566,"type":"单选题","text":"____节来源于二十四节气。","options":[{"key":"A","text":"清明"},{"key":"B","text":"端午"},{"key":"C","text":"中秋"},{"key":"D","text":"春节"}],"answer":["A"],"explanation":"清明节的得名源于我国农历24节气中的清明节气。清明节气共有15天，作为节气的清明，时间在春分之后。"},{"id":567,"type":"单选题","text":"____是我国北宋年间司马光主编的一部编年体。","options":[{"key":"A","text":"《资治通鉴》"},{"key":"B","text":"《史记》"},{"key":"C","text":"《汉书》"},{"key":"D","text":"《后汉书》"}],"answer":["A"],"explanation":"《资治通鉴》（常简作《通鉴》），由北宋司马光主编的一部多卷本编年体史书，共294卷，历时19年完成。主要以时间为纲，事件为目，从周威烈王二十三年（公元前403年）写起，到五代后周世宗显德六年（公元959年）征淮南停。"},{"id":568,"type":"单选题","text":"“尚巧主景”是前人对____的诗的评价。","options":[{"key":"A","text":"岑参"},{"key":"B","text":"王昌龄"},{"key":"C","text":"高适"},{"key":"D","text":"王之涣"}],"answer":["A"],"explanation":"“尚巧主景”指的是岑参边塞诗善于抓住边塞富有特色的景物进行描写，善于渲染景物、长于寓情于景、注重通过对客体的描绘传达诗人的主观情感的特点。"},{"id":569,"type":"单选题","text":"诗句“二十四桥明月夜，玉人何处教吹箫”中的“二十四桥”位于____。","options":[{"key":"A","text":"扬州"},{"key":"B","text":"苏州"},{"key":"C","text":"杭州"},{"key":"D","text":"南京"}],"answer":["A"],"explanation":"一说扬州城里原有二十四座桥；一说即吴家砖桥，因古时有二十四位美女吹箫于桥上而得名。"},{"id":570,"type":"单选题","text":"苏轼在《念奴娇·赤壁怀古》中提到了“羽扇纶巾，谈笑间，樯橹灰飞烟灭”，“羽扇纶巾”形容的是____。","options":[{"key":"A","text":"周瑜"},{"key":"B","text":"诸葛亮"},{"key":"C","text":"曹操"},{"key":"D","text":"孙权"}],"answer":["A"],"explanation":"羽扇纶巾，意思是拿着羽毛扇子，戴着青丝绶的头巾。形容态度从容。出自宋·苏轼《念奴娇·赤壁怀古》，指代汉末儒将周瑜的便装打扮 。"},{"id":571,"type":"单选题","text":"“归去来兮，吾归何处？”是苏轼所发出的哀叹之音,似有归隐田园之意。东晋一田园诗人曾有《归去来兮辞》文章，其诗人是____。","options":[{"key":"A","text":"陶渊明"},{"key":"B","text":"谢灵运"},{"key":"C","text":"阮籍"},{"key":"D","text":"嵇康"}],"answer":["A"],"explanation":"《归去来兮辞》是晋宋之际文学家陶渊明创作的抒情小赋，也是一篇脱离仕途回归田园的宣言。这篇文章作于作者辞官之初，叙述了他辞官归隐后的生活情趣和内心感受，表现了他对官场的认识以及对人生的思索，表达了他洁身自好、不同流合污的精神情操。"},{"id":572,"type":"单选题","text":"唐诗大变于中唐，代表这种新变的第一诗人群是____诗派。","options":[{"key":"A","text":"韩孟"},{"key":"B","text":"元白"},{"key":"C","text":"山水田园"},{"key":"D","text":"边塞"}],"answer":["A"],"explanation":"“韩孟诗派”是中唐的一个诗歌创作流派，以韩愈为领袖，包括孟郊、李贺、卢仝、马异、刘叉。他们主张“不平则鸣”，苦吟以抒愤，并互相切磋酬唱他们具有变态的审美趣味，“以丑为美”，以震荡光怪为美，以瘁索枯槁为美，以五彩斑斓为美。表现出重主观心理、尚奇险怪异的创作倾向。诗歌形成一种奇崛硬险的风格。他们在艺术上力求避熟就生，标新立异，力矫大历诗风的平弱纤巧。这种诗歌的新的追求与新的变化，积极推动了盛唐以后诗歌艺术境界的开拓。"},{"id":573,"type":"单选题","text":"元曲在元代被称作____。","options":[{"key":"A","text":"新乐府"},{"key":"B","text":"长短句"},{"key":"C","text":"乐府"},{"key":"D","text":"词余"}],"answer":["A"],"explanation":"元曲在元代被称“乐府”，“新乐府”，“北乐府”。人们通常所说的元曲，包括剧曲和散曲。剧曲指的是杂剧的曲辞，它是戏剧这一在舞台上表演的综合艺术的密不可分的组成部分。"},{"id":574,"type":"单选题","text":"鲁迅先生称史记为“史家之绝唱，____”。","options":[{"key":"A","text":"有韵之《尚书》"},{"key":"B","text":"无韵之离骚"},{"key":"C","text":"史家之经典"},{"key":"D","text":"千古之绝唱"}],"answer":["B"],"explanation":"“史家之绝唱，无韵之离骚”的意思是史家独一无二的文章，没有韵的《离骚》。史家之绝唱，无韵之离骚是鲁迅对司马迁《史记》的评价，这是一个相当高的评价。《离骚》是屈原的代表作，在我国古代文学史上有着划时代的意义，书写了高洁的志向和人格。"},{"id":575,"type":"单选题","text":"与曹操有关的著名典故为____。","options":[{"key":"A","text":"三顾茅庐"},{"key":"B","text":"望梅止渴"},{"key":"C","text":"草船借箭"},{"key":"D","text":"火烧赤壁"}],"answer":["B"],"explanation":"南朝宋，刘义庆《世说新语·假谲》：有一次曹操带兵在外行军，一时找不到取水的地方，士兵都渴极了，曹操就骗他们说：“前面有个大梅林，梅子又甜又酸，可以解渴。”士兵听了，一个个都流出了口水，暂时止住了口渴。"},{"id":576,"type":"单选题","text":"我国古代最早提出“废黜百家，独尊儒术”的是____。","options":[{"key":"A","text":"孔子"},{"key":"B","text":"董仲舒"},{"key":"C","text":"孟子"},{"key":"D","text":"荀子"}],"answer":["B"],"explanation":"“罢黜百家，独尊儒术”，是董仲舒于元光元年(公元前134年)提出的治国思想，在汉武帝时开始推行。"},{"id":577,"type":"单选题","text":"碧螺春是____茶的一种。","options":[{"key":"A","text":"红"},{"key":"B","text":"绿"},{"key":"C","text":"黑"},{"key":"D","text":"白"}],"answer":["B"],"explanation":"碧螺春是中国传统名茶，中国十大名茶之一，属于绿茶类，已有1000多年历史。碧螺春产于江苏省苏州市吴县太湖的东洞庭山及西洞庭山(今苏州吴中区)一带，所以又称“洞庭碧螺春”。"},{"id":578,"type":"单选题","text":"____是我国湖北省的简称。","options":[{"key":"A","text":"湘"},{"key":"B","text":"鄂"},{"key":"C","text":"豫"},{"key":"D","text":"皖"}],"answer":["B"],"explanation":"湖北省，位于中国中部偏南、长江中游，洞庭湖以北，故名湖北，简称“鄂”，省会武汉。"},{"id":579,"type":"单选题","text":"____指的是我国武汉市的美称。","options":[{"key":"A","text":"蓉城"},{"key":"B","text":"江城"},{"key":"C","text":"春城"},{"key":"D","text":"山城"}],"answer":["B"],"explanation":"江城，指江河在本地文化中占据突出地位的城市，现特指湖北省武汉市。"},{"id":580,"type":"单选题","text":"“文武二圣”指的是孔子和____。","options":[{"key":"A","text":"刘备"},{"key":"B","text":"关羽"},{"key":"C","text":"曹操"},{"key":"D","text":"孙权"}],"answer":["B"],"explanation":"“文武二圣”分别指的是孔子和关羽。两者代表了文武两个方面的最高成就。"},{"id":581,"type":"单选题","text":"“乌纱帽”正式成为做官为宦的代名词是在____朝。","options":[{"key":"A","text":"唐"},{"key":"B","text":"明"},{"key":"C","text":"宋"},{"key":"D","text":"元"}],"answer":["B"],"explanation":"乌纱帽，古代官吏戴的一种帽子。乌纱帽原是民间常见的一种便帽，官员头戴乌纱帽起源于东晋，但作为正式官服的一个组成部分，却始于隋朝，兴盛于唐朝，到宋朝时加上了“双翅”，明朝以后，乌纱帽才正式成为做官为宦的代名词 。"},{"id":582,"type":"单选题","text":"《史记》中的“列传”共有____篇。","options":[{"key":"A","text":"十二"},{"key":"B","text":"七十"},{"key":"C","text":"三十"},{"key":"D","text":"十"}],"answer":["B"],"explanation":"《史记》共一百三十篇。《史记》全书包括十二本纪（记历代帝王政绩）、三十世家（记诸侯国和汉代诸侯、勋贵兴亡）、七十列传（记重要人物的言行事迹，主要叙人臣。其中最后一篇为自序）、十表（大事年表）、八书（记各种典章制度记礼、乐、音律、历法、天文、封禅、水利、财用）。"},{"id":583,"type":"单选题","text":"长江三峡是指由巫峡、瞿塘峡和____。","options":[{"key":"A","text":"虎跳峡"},{"key":"B","text":"三门峡"},{"key":"C","text":"西陵峡"},{"key":"D","text":"刘家峡"}],"answer":["C"],"explanation":"长江三峡又名峡江或大三峡，位于中国重庆市、恩施州、宜昌市地区境内的长江干流上，西起重庆市奉节县的白帝城，东至湖北省宜昌市的南津关，全长193千米，由瞿塘峡、巫峡、西陵峡组成。"},{"id":584,"type":"单选题","text":"五经《诗》、《书》、《易》、《礼》、《春秋》，其中《礼》为三礼，包含____、周礼、仪礼。","options":[{"key":"A","text":"《礼运》"},{"key":"B","text":"《礼器》"},{"key":"C","text":"《礼记》"},{"key":"D","text":"《曲礼》"}],"answer":["C"],"explanation":"三礼指《仪礼》、《周礼》、《礼记》儒家经典。古代中国礼乐文化的理论形态，对礼法、礼义作了最权威的记载和解释，对历代礼制的影响最为深远。"},{"id":585,"type":"单选题","text":"孔子的政治思想核心内容是“礼”与____，在治国的方略上，他主张“为政以德”，用道德和礼教来治理国家是最高尚的治国之道。","options":[{"key":"A","text":"义"},{"key":"B","text":"智"},{"key":"C","text":"仁"},{"key":"D","text":"信"}],"answer":["C"],"explanation":"孔子是儒家创始人，他的思想核心是“仁”“礼”。 “仁”的主张是“仁者爱人”，这一主张是要求统治阶级体察民情，反对苛政。“礼”的主张是“克己复礼”，就是说要克制自己，使自己符合“礼”要求。"},{"id":586,"type":"单选题","text":"“四象二十八星宿”是我国古代天文学最重要的成就，也是中国传统文化中最神秘的部分之一。其中的“四象”被称为“四方神”，影响及于我国古代的军事、宗教、文学、风水等各个领域。四象指的是青龙、____、朱雀、玄武。","options":[{"key":"A","text":"黄龙"},{"key":"B","text":"麒麟"},{"key":"C","text":"白虎"},{"key":"D","text":"凤凰"}],"answer":["C"],"explanation":"“四象”通常指的是左青龙,右白虎,前朱雀,后玄武。古代汉族人民把东、西、南、北四方每一方的七宿想象为四种动物形象，叫作四象。"},{"id":587,"type":"单选题","text":"我国古代贵族四术为诗、书、礼和____。","options":[{"key":"A","text":"射"},{"key":"B","text":"御"},{"key":"C","text":"乐"},{"key":"D","text":"数"}],"answer":["C"],"explanation":"《诗经》中的歌曲曾被列为上层社会教育的主要科目，所谓诗、书、礼、乐并称“四术”。"},{"id":588,"type":"单选题","text":"中国四大名绣为苏绣、湘绣、蜀绣、____。","options":[{"key":"A","text":"浙绣"},{"key":"B","text":"闽绣"},{"key":"C","text":"粤绣"},{"key":"D","text":"鲁绣"}],"answer":["C"],"explanation":"中国四大名绣，是指中国中部湖南省的“湘绣”，中国西部四川省的“蜀绣”，中国南部广东省的“粤绣”和中国东部江苏省的“苏绣”的合称。"},{"id":589,"type":"单选题","text":"中国古代的四大书院分别是____、岳麓书院、嵩阳书院、应天书院。","options":[{"key":"A","text":"东林书院"},{"key":"B","text":"石鼓书院"},{"key":"C","text":"白鹿洞书院"},{"key":"D","text":"茅山书院"}],"answer":["C"],"explanation":"“四大书院”指应天府书院（今河南商丘睢阳区商丘古城南湖畔）、岳麓书院（今湖南长沙岳麓区岳麓山）、白鹿洞书院（今江西九江庐山市庐山）和嵩阳书院（今河南郑州登封市嵩山）。"},{"id":590,"type":"单选题","text":"六义是诗经学名词，指的是风、雅、颂、赋、比、____。","options":[{"key":"A","text":"讽"},{"key":"B","text":"喻"},{"key":"C","text":"兴"},{"key":"D","text":"咏"}],"answer":["C"],"explanation":"《诗经》是中国文学史上第一部诗歌总集，收入西周初期至春秋中叶间的诗歌三百零五篇。所谓《诗经》中的“六义”，是指“风、雅、颂”三种诗歌形式与“赋、比、兴”三种表现手法。"},{"id":591,"type":"单选题","text":"“按图索骥”中的“骥”本意指的是____。","options":[{"key":"A","text":"虎"},{"key":"B","text":"豹"},{"key":"C","text":"马"},{"key":"D","text":"鹿"}],"answer":["C"],"explanation":"索：找；骥：良马。按照画像去寻求好马。比喻墨守成规办事；也比喻按照线索去寻求。"},{"id":592,"type":"单选题","text":"被称为菊月的月份是____。","options":[{"key":"A","text":"八月"},{"key":"B","text":"十月"},{"key":"C","text":"九月"},{"key":"D","text":"七月"}],"answer":["C"],"explanation":"一月：瑞月 二月：花月 三月：桐月 四月：梅月 五月：蒲月 六月：荷月 七月：兰月 八月：桂月 九月：菊月 十月：阳月 十一月：辜月 十二月：霜月"},{"id":593,"type":"单选题","text":"“环肥燕瘦”中的“燕”是指谁_____","options":[{"key":"A","text":"杨玉环"},{"key":"B","text":"西施"},{"key":"C","text":"赵飞燕"},{"key":"D","text":"王昭君"}],"answer":["C"],"explanation":"环是指的唐玄宗贵妃杨玉环，燕是指的汉成帝皇后赵飞燕。形容女子形态不同，各有各好看的地方。也借喻艺术作品风格不同，而各有所长。"},{"id":594,"type":"单选题","text":"屈原在____中写道，“吾令羲和弭节兮，望崦嵫而勿迫。”","options":[{"key":"A","text":"《九歌》"},{"key":"B","text":"《天问》"},{"key":"C","text":"《离骚》"},{"key":"D","text":"《九章》"}],"answer":["C"],"explanation":"《离骚》是战国诗人屈原创作的文学作品。“离骚”，东汉王逸释为：“离，别也；骚，愁也。”《离骚》以理想与现实的冲突为主线，以花草禽鸟的比兴和瑰奇迷幻的“求女”神境作象征，借助于自传性回忆中的情感激荡，和复沓纷至、倏生倏灭的幻境交替展开全诗。作品倾诉了对楚国命运和人民生活的关心，“哀民生之多艰”，叹奸佞之当道。主张“举贤而授能”，“循绳墨而不颇”。提出“皇天无私阿”，对天命论进行批判。作品中大量的比喻和丰富的想像，表现出积极浪漫主义精神，并开创了中国文学上的“骚”体诗歌形式，对后世有深远影响。有东汉王逸《楚辞章句》、南宋朱熹《楚辞集注》、清代戴震《屈原赋注》等注本。"},{"id":595,"type":"单选题","text":"“尔曹身与名俱灭，不废江河万古流。”出自____的《戏为六绝句》(其二)。","options":[{"key":"A","text":"李白"},{"key":"B","text":"王维"},{"key":"C","text":"白居易"},{"key":"D","text":"杜甫"}],"answer":["D"],"explanation":"出处：唐，杜甫《戏为六绝句》（其二）全文为：王杨卢骆当时体，轻薄为文哂未休。尔曹身与名俱灭，不废江河万古流。"},{"id":596,"type":"单选题","text":"“相见争如不见，有〔多〕情何似无情。”出自宋代____的《西江月》。","options":[{"key":"A","text":"苏轼"},{"key":"B","text":"欧阳修"},{"key":"C","text":"柳永"},{"key":"D","text":"司马光"}],"answer":["D"],"explanation":"相见争如不见，有情何似无情。出自宋代司马光的《西江月》，全文是：“宝髻松松挽就，铅华淡淡妆成。青烟翠雾罩轻盈，飞絮游丝无定。相见争如不见，有情何似无情。笙歌散后酒初醒，深院月斜人静。”"},{"id":597,"type":"单选题","text":"“夫仁者，己欲立而立人，己欲达而达人”出自____。","options":[{"key":"A","text":"《中庸》"},{"key":"B","text":"《大学》"},{"key":"C","text":"《孟子》"},{"key":"D","text":"《论语》"}],"answer":["D"],"explanation":"“己欲立而立人，己欲达而达人”出自于《论语·雍也》，意思是：仁爱之人，自己决定对人建立仁爱之心，别人才会对你仁爱，自己决定对人豁达（宽容），别人才会对你豁达（宽容）。"},{"id":598,"type":"单选题","text":"“泪眼问花花不语，乱红飞过秋千去。”出自____的《蝶恋花》。","options":[{"key":"A","text":"李清照"},{"key":"B","text":"柳永"},{"key":"C","text":"苏轼"},{"key":"D","text":"欧阳修"}],"answer":["D"],"explanation":"出自欧阳修的《蝶恋花》。全文是：“庭院深深深几许，杨柳堆烟，帘幕无重数。玉勒雕鞍游冶处,楼高不见章台路。雨横风狂三月暮，门掩黄昏，无计留春住。泪眼问花花不语，乱红飞过秋千去。”"},{"id":599,"type":"单选题","text":"及笄之年是指____岁。","options":[{"key":"A","text":"二十"},{"key":"B","text":"十八"},{"key":"C","text":"十六"},{"key":"D","text":"十五"}],"answer":["D"],"explanation":"及笄是指女子满了15岁。形容古代女子已到了结婚的年龄。"},{"id":600,"type":"单选题","text":"中元节是我国的传统节日之一,而在民间中元节也被人们称为____。","options":[{"key":"A","text":"寒食节"},{"key":"B","text":"乞巧节"},{"key":"C","text":"灯节"},{"key":"D","text":"鬼节"}],"answer":["D"],"explanation":"中元节是我国的传统节日之一，而在民间中元节也被人们称为鬼节。当日祭拜时着装得体，以黑色灰色着装为宜。忌红色等大红大紫之色。否则容易招致煞气，惹祸上身。拜祭时要态度端正，不要大声喧哗，出言不逊或有不雅举止。据说否则会打扰到死者的灵魂，重者更会招致怨气。七月十五要外出游玩的朋友，要在太阳落山前返回。否则阳气退去，阴气见长，体弱多病之人则容易受到阴气袭扰。"},{"id":601,"type":"单选题","text":"补全词：“杜郎俊赏，算而今，重到须惊。纵豆蔻词工，青楼梦好，____。”","options":[{"key":"A","text":"别是一般滋味"},{"key":"B","text":"忍把浮名"},{"key":"C","text":"谁会凭阑意"},{"key":"D","text":"难赋深情"}],"answer":["D"],"explanation":"出自宋诗人姜夔的《扬州慢·淮左名都》。全文为：淳熙丙申至日，予过维扬。夜雪初霁，荠麦弥望。入其城，则四顾萧条，寒水自碧，暮色渐起，戍角悲吟。予怀怆然，感慨今昔，因自度此曲。千岩老人以为有“黍离”之悲也。淮左名都，竹西佳处，解鞍少驻初程。过春风十里。尽荠麦青青。自胡马窥江去后，废池乔木，犹厌言兵。渐黄昏，清角吹寒。都在空城。杜郎俊赏，算而今、重到须惊。纵豆蔻词工，青楼梦好，难赋深情。"},{"id":602,"type":"单选题","text":"2013年4月，本着生态性、文化性、地方特色与时代性相结合的原则统筹考虑，最终选出“屯溪八景”，分别是谜窟探奇、新安怀古、华山思贤、老街问市、三江烟霞、稽灵松涛、龙山禅月和____。","options":[{"key":"A","text":"南湖秋月"},{"key":"B","text":"东湖春晓"},{"key":"C","text":"西湖烟雨"},{"key":"D","text":"鬲山荷韵"}],"answer":["D"],"explanation":"“屯溪八景”分别是“谜窟探奇”、“新安怀古”、“华山思贤”、“老街问市”、“三江烟霞”、“稽灵松涛”、“龙山禅月”和“鬲山荷韵”。"},{"id":603,"type":"单选题","text":"____与武当山、青城山、龙虎山并称中国四大道教名山。","options":[{"key":"A","text":"九华山"},{"key":"B","text":"五台山"},{"key":"C","text":"普陀山"},{"key":"D","text":"齐云山"}],"answer":["D"],"explanation":"四大道教名山为中国四处最主要的道教圣地，分别是：位于湖北十堰的武当山；位于江西鹰潭的龙虎山；位于安徽黄山的齐云山和位于四川都江堰的青城山。"},{"id":604,"type":"单选题","text":"清代出现的以满族菜为主，沿袭明代宫廷风格的菜肴，被称为____。","options":[{"key":"A","text":"宫廷菜"},{"key":"B","text":"满族菜"},{"key":"C","text":"明代菜"},{"key":"D","text":"满汉全席"}],"answer":["D"],"explanation":"满汉全席，清朝时期宫廷盛宴。既有宫廷菜肴之特色，又有地方风味之精华；突出满族与汉族菜的特殊风味，烧烤、火锅、涮涮锅几乎不可缺少的菜点，同时又展示了汉族烹调的特色，扒、炸、炒、熘、烧等兼备，实乃中华菜系文化的瑰宝和最高境界。满汉全席原是清代宫廷中举办宴会时满人和汉人合坐的一种全席。"},{"id":605,"type":"单选题","text":"中国画史上，被公认为水准最高的山水画作是元代画作____。","options":[{"key":"A","text":"《溪山行旅图》"},{"key":"B","text":"《清明上河图》"},{"key":"C","text":"《千里江山图》"},{"key":"D","text":"《富春山居图》"}],"answer":["D"],"explanation":"富春山居图是元代画家黄公望于1350年创作的纸本水墨画，中国十大传世名画之一。"},{"id":606,"type":"单选题","text":"五岳中以“险”著称的是____。","options":[{"key":"A","text":"泰山"},{"key":"B","text":"衡山"},{"key":"C","text":"嵩山"},{"key":"D","text":"华山"}],"answer":["D"],"explanation":"五岳即东岳泰山、西岳华山、北岳恒山、中岳嵩山、南岳衡山。论景观，五岳又各具特色：泰山雄、衡山秀、华山险，恒山奇，嵩山奥。"},{"id":607,"type":"单选题","text":"中国传统的祥瑞动物中，“四灵”指的是麟、龙、凤、龟，再加上____，则称为“五灵”。","options":[{"key":"A","text":"熊"},{"key":"B","text":"豹"},{"key":"C","text":"狮"},{"key":"D","text":"虎"}],"answer":["D"],"explanation":"五灵，谓麟、凤、龟、龙、白虎。《杜预春秋左氏传序》：“麒凤五灵，王者之嘉瑞也。”《疏》：“麟、凤与龟、龙、白虎五者，神灵之鸟兽，王者之嘉瑞也，独举麟、凤而云五灵，知二兽以外，为龟、龙、白虎。”"},{"id":608,"type":"单选题","text":"成语“胸有成竹”源于宋代____画竹的故事。","options":[{"key":"A","text":"文同"},{"key":"B","text":"苏轼"},{"key":"C","text":"米芾"},{"key":"D","text":"蔡襄"}],"answer":["A"],"explanation":"北宋时候，有一个著名的画家，名叫文同，他是当时画竹子的高手。文同为了画好竹子，不管是春夏秋冬，也不管是刮风下雨，或是天晴天阴，他都常年不断地在竹林子里头钻来钻去，为的就是把竹子不同时期的姿态记在心头。由于文同长年累月地对竹子作了细微的观察和研究，竹子在春夏秋冬四季的形状有什么变化；在阴晴雨雪天，竹子的颜色、姿势又有什么两样；在强烈的阳光照耀下和在明净的月光映照下，竹子又有什么不同；不同的竹子，又有哪些不同的样子，他都摸得一清二楚。所以画起竹子来，根本用不着画草图。有个名叫晁补之的人，称赞文同说：文同画竹，早已胸有成竹了。"},{"id":609,"type":"单选题","text":"凉州词是乐府曲名，内容多描写西北边塞的风光及战争情景，请问凉州在现在的哪个省____？","options":[{"key":"A","text":"甘肃"},{"key":"B","text":"青海"},{"key":"C","text":"宁夏"},{"key":"D","text":"陕西"}],"answer":["A"],"explanation":"凉州词，又称凉州曲，是盛唐时流行的一种曲调名。凉州即今武威市，甘肃省辖地级市，位于甘肃省中部。"},{"id":610,"type":"单选题","text":"“知己知彼，百战不殆”是举世闻名的兵法名句，出自《孙子兵法》，其作者是我国古代杰出的军事家____。","options":[{"key":"A","text":"孙武"},{"key":"B","text":"孙膑"},{"key":"C","text":"吴起"},{"key":"D","text":"白起"}],"answer":["A"],"explanation":"“知彼知己，百战不殆”，意思是对敌人的情况和自己的情况都有透彻的了解，作战就不会失败，出自《孙子兵法·谋攻篇》。"},{"id":611,"type":"单选题","text":"历史上共有十个黄帝亲往曲阜祭祀孔子，最早的是____。","options":[{"key":"A","text":"刘邦"},{"key":"B","text":"汉武帝"},{"key":"C","text":"唐太宗"},{"key":"D","text":"宋太祖"}],"answer":["A"],"explanation":"中国历史上第一位到曲阜祭祀孔子的皇帝是汉高祖刘邦。"},{"id":612,"type":"单选题","text":"中国古代祭祀天地的仪式很多，其中最为隆重的是____。","options":[{"key":"A","text":"封禅"},{"key":"B","text":"郊祭"},{"key":"C","text":"庙祭"},{"key":"D","text":"社祭"}],"answer":["A"],"explanation":"封禅，封为“祭天”，禅为“祭地”，意思是指中国古代帝王在太平盛世或天降祥瑞之时的祭祀天地的大型典礼，一般由帝王亲自到泰山上举行。远古暨夏商周三代，已有封禅的传说。出自《管子·封禅篇》。"},{"id":613,"type":"单选题","text":"自秦至今，我国一直沿用的行政区划单位是____。","options":[{"key":"A","text":"县"},{"key":"B","text":"郡"},{"key":"C","text":"州"},{"key":"D","text":"省"}],"answer":["A"],"explanation":"秦始皇即位时推行“郡县制”；秦代沿袭了秦的郡县制，与郡国并存；东汉形成“州、郡、县三级制”；隋又改为“郡(州)、县二级制”；唐设“道”对地方实行监察，将“郡”改称“州”，实行“道、州、县三级制”；宋改“道”为“路”，实行“路、州、县三级制”；元推行行省制,形成“省、道路、州(府)、县四级制”；明承元制，改行省为“承宣布政使司”,形成“司、府(州)、县”三级制；清承明制，改司为省，省名与今相近。由此，“县”是自秦迄今一直沿用的行政区划单位。"},{"id":614,"type":"单选题","text":"北魏时期，提出“除去三张伪法”，鼓动灭佛、改革天师道的道士是____。","options":[{"key":"A","text":"寇谦之"},{"key":"B","text":"葛洪"},{"key":"C","text":"陶弘景"},{"key":"D","text":"陆修静"}],"answer":["A"],"explanation":"北魏道士寇谦之称太上老君亲临嵩岳授以“天师之位”，赐以《云中音诵新科之戒》20卷，传其服气导引口诀之法；令其“清整道教，除去三张（指张陵、张衡、张鲁——引者）伪法，租米钱税及男女合气之术”。"},{"id":615,"type":"单选题","text":"中国有四大高原，分别是云贵高原、青藏高原、黄土高原和____。","options":[{"key":"A","text":"内蒙古高原"},{"key":"B","text":"帕米尔高原"},{"key":"C","text":"云贵高原"},{"key":"D","text":"黄土高原"}],"answer":["A"],"explanation":"中国最大的四个高原分别为：青藏高原、内蒙古高原、黄土高原、云贵高原。它们集中分布在地势第一、二级阶梯上，由于高度、位置、成因和受外力侵蚀作用的不同，高原的外貌特征也各异。中国陆地的主要地形即为高原和山地。"},{"id":616,"type":"单选题","text":"《金匮要略》是我国著名医学家____的传世著作。","options":[{"key":"A","text":"张仲景"},{"key":"B","text":"华佗"},{"key":"C","text":"孙思邈"},{"key":"D","text":"李时珍"}],"answer":["A"],"explanation":"《金匮要略》是我国东汉著名医学家张仲景所著《伤寒杂病论》的杂病部分，也是我国现存最早的一部论述杂病诊治的专书，原名《金匮要略方论》。“金匮”是存放古代帝王圣训和实录的地方，意指本书内容之珍贵。全书分上、中、下三卷，共25篇，载疾病60余种，收方剂262首。所述病证以内科杂病为主，兼及外科、妇科疾病及急救卒死、饮食禁忌等内容。被后世誉为“方书之祖”。"},{"id":617,"type":"单选题","text":"中国“四大石窟”指的是____、云冈石窟、龙门石窟、麦积山石窟。","options":[{"key":"A","text":"莫高窟"},{"key":"B","text":"炳灵寺石窟"},{"key":"C","text":"克孜尔石窟"},{"key":"D","text":"响堂山石窟"}],"answer":["A"],"explanation":"四大石窟指的是以中国佛教文化为特色的巨型石窟艺术景观，包括：莫高窟（甘肃敦煌）、云冈石窟（山西大同）、龙门石窟（河南洛阳）、麦积山石窟（甘肃天水），是中国古代传统文化艺术的历史瑰宝。"},{"id":618,"type":"单选题","text":"战国七雄指的是齐、楚、燕、韩、赵、魏、____。","options":[{"key":"A","text":"秦"},{"key":"B","text":"鲁"},{"key":"C","text":"宋"},{"key":"D","text":"卫"}],"answer":["A"],"explanation":"战国七雄是战国时期七个最强大的诸侯国的统称，包括齐、楚、燕、韩、赵、魏、秦这七个诸侯国。"},{"id":619,"type":"单选题","text":"“敦煌学”的概念由____提出。","options":[{"key":"A","text":"陈寅恪"},{"key":"B","text":"王国维"},{"key":"C","text":"罗振玉"},{"key":"D","text":"王静安"}],"answer":["A"],"explanation":"1925年8月，日本学者石滨纯太郎在大阪怀德堂讲演时，使用过“敦煌学”一词。1930年，著名国学大师陈寅恪先生在为陈垣先生编《敦煌劫余录》所作序中，概括了“敦煌学”的概念。"},{"id":620,"type":"单选题","text":"我国历史上第一个提出不依靠农业富国的改革家是____。","options":[{"key":"A","text":"商鞅"},{"key":"B","text":"桑弘羊"},{"key":"C","text":"王安石"},{"key":"D","text":"张居正"}],"answer":["B"],"explanation":"桑弘羊(公元前152年——公元前80年)，西汉法家人物、专长为财政。因能“言利事，析秋毫”，深得汉武帝赏识，被委以重任，历任大农丞、大农令、搜粟都尉兼大司农等要职，统管中央财政近40年之久。是我国历史上第一个提出不依靠农业富国的改革家。"},{"id":621,"type":"单选题","text":"我国最早一部家庭教育专著是____的《颜氏家训》。","options":[{"key":"A","text":"颜真卿"},{"key":"B","text":"颜之推"},{"key":"C","text":"颜杲卿"},{"key":"D","text":"颜回"}],"answer":["B"],"explanation":"《颜氏家训》是汉民族历史上第一部内容丰富，体系宏大的家训，也是一部学术著作。作者颜之推，是南北朝时期著名的文学家、教育家。"},{"id":622,"type":"单选题","text":"“鹅湖之会”是书院史上的著名事件，他指的是朱熹和____在鹅湖书院进行的辩论。","options":[{"key":"A","text":"陆九龄"},{"key":"B","text":"陆九渊"},{"key":"C","text":"吕祖谦"},{"key":"D","text":"张栻"}],"answer":["B"],"explanation":"著名学者吕祖谦为了调和朱熹“理学”和陆九渊“心学”两派之间在学术上的矛盾，邀请他们在江西鹅湖寺举行学术交流，史称“鹅湖之会”。这次大会进行了三天，双方各持己见、互不相让。虽然学术上的分歧没能得到解决。但是这次讨论会影响很大，是中国哲学史上堪称典范的一次学术讨论会，而且开启了书院会讲的先河。"},{"id":623,"type":"单选题","text":"纯粹的教育书院出现于____。","options":[{"key":"A","text":"唐代"},{"key":"B","text":"北宋"},{"key":"C","text":"南宋"},{"key":"D","text":"元代"}],"answer":["B"],"explanation":"书院是中国传统高等教育中最有价值的一部份。先秦时候孔子兴办私学﹐可说是书院教育之雏形﹔而汉唐时候的精舍﹐可说是书院的前身﹔到北宋时候﹐书院教育才正式确立。"},{"id":624,"type":"单选题","text":"根据古代“左庙右学”的传统，国子监与____毗邻。","options":[{"key":"A","text":"社稷坛"},{"key":"B","text":"孔庙"},{"key":"C","text":"天坛"},{"key":"D","text":"地坛"}],"answer":["B"],"explanation":"国子监是我国元、明、清三代国家管理教育的最高行政机关和国家设立的最高学府，孔庙则是皇家祭孔之地，两者相伴形成“左庙右学”。"},{"id":625,"type":"单选题","text":"汉代的五经博士是专门传授儒家经学的____。","options":[{"key":"A","text":"官员"},{"key":"B","text":"学官"},{"key":"C","text":"学者"},{"key":"D","text":"儒生"}],"answer":["B"],"explanation":"五经博士在汉武帝时设立，是专门传授儒家经学的学官。汉初，《易》、《书》、《诗》、《礼》、《春秋》每经只有一家，每经置一博士，各以家法教授，故称五经博士。"},{"id":626,"type":"单选题","text":"最初的指南针是____。","options":[{"key":"A","text":"司南"},{"key":"B","text":"罗盘"},{"key":"C","text":"指南鱼"},{"key":"D","text":"指南龟"}],"answer":["A"],"explanation":"指南针最早叫司南，是中国古代四大发明之一。司南是中国古代辨别方向用的一种仪器，是中国古代劳动人民在长期的实践中对物体磁性认识的发明。"},{"id":627,"type":"单选题","text":"世界上第一部国家药典是我国____朝政府组织编修的。","options":[{"key":"A","text":"唐"},{"key":"B","text":"宋"},{"key":"C","text":"明"},{"key":"D","text":"清"}],"answer":["A"],"explanation":"世界上第一部国家药典是中国唐朝的《新修本草》，共54卷，分药图、药经、本草三部分，记载药物844种。"},{"id":628,"type":"单选题","text":"江南三大名楼是____、岳阳楼、黄鹤楼。","options":[{"key":"A","text":"滕王阁"},{"key":"B","text":"鹳雀楼"},{"key":"C","text":"蓬莱阁"},{"key":"D","text":"大观楼"}],"answer":["A"],"explanation":"江南三大名楼指的是江西南昌的滕王阁、湖北武汉的黄鹤楼和湖南岳阳的岳阳楼。"},{"id":629,"type":"单选题","text":"苏州四大园林指的是____、狮子林、拙政园和留园。","options":[{"key":"A","text":"沧浪亭"},{"key":"B","text":"网师园"},{"key":"C","text":"环秀山庄"},{"key":"D","text":"艺圃"}],"answer":["A"],"explanation":"沧浪亭、狮子林、拙政园和留园并称苏州四大园林，代表着宋（公元960～1278年）、元（公元1271～1368年）、明（公元1368～1644年）、清（公元1644～1911年）四个朝代的艺术风格，被称为苏州四大名园。"},{"id":630,"type":"单选题","text":"被誉为“中国戏曲之母”的剧种是____。","options":[{"key":"A","text":"昆曲"},{"key":"B","text":"京剧"},{"key":"C","text":"越剧"},{"key":"D","text":"黄梅戏"}],"answer":["A"],"explanation":"昆剧（别称昆腔、昆曲），原名“昆山腔”，发源于元末明初的苏州府昆山县，是中国戏曲的剧种之一，被誉为“百戏之祖”。"},{"id":631,"type":"单选题","text":"诗歌起源于_____","options":[{"key":"A","text":"劳动"},{"key":"B","text":"祭祀"},{"key":"C","text":"爱情"},{"key":"D","text":"战争"}],"answer":["A"],"explanation":"诗歌起源于上古的社会生活，因劳动生产、两性相恋、原始宗教等而产生的一种有韵律、富有感情色彩的语言形式。"},{"id":632,"type":"单选题","text":"被誉为“唐人楷书第一”的是____。","options":[{"key":"A","text":"欧阳询"},{"key":"B","text":"颜真卿"},{"key":"C","text":"柳公权"},{"key":"D","text":"褚遂良"}],"answer":["A"],"explanation":"欧阳询唐朝著名书法家、书法理论家，与虞世南、褚遂良、薛稷并称初唐四大家。"},{"id":633,"type":"单选题","text":"《广陵散》成为千古名曲，与“竹林七贤”之一的____有很大关系。","options":[{"key":"A","text":"嵇康"},{"key":"B","text":"阮籍"},{"key":"C","text":"山涛"},{"key":"D","text":"刘伶"}],"answer":["A"],"explanation":"据《晋书》记载，此曲乃嵇康游玩洛西时，为一古人所赠。"},{"id":634,"type":"单选题","text":"佛教四大名山是九华山、____、普陀山、峨眉山。","options":[{"key":"A","text":"五台山"},{"key":"B","text":"武当山"},{"key":"C","text":"青城山"},{"key":"D","text":"齐云山"}],"answer":["A"],"explanation":"中国佛教四大名山分别是安徽九华山、山西五台山、浙江普陀山、四川峨眉山，分别是地藏王菩萨、文殊菩萨、观世音菩萨、普贤菩萨的道场。"},{"id":635,"type":"单选题","text":"中国历史上第一部比较系统的封建成文法典是____。","options":[{"key":"A","text":"《法经》"},{"key":"B","text":"《秦律》"},{"key":"C","text":"《汉律》"},{"key":"D","text":"《唐律疏议》"}],"answer":["A"],"explanation":"《法经》是中国历史上第一部比较系统的封建成文法典，但它并不是我国历史上第一部成文法典，在《法经》之前，已经颁布了很多法典，只是不太完善。"},{"id":636,"type":"单选题","text":"天干地支纪年始于汉代，这种纪年是以_____为起点","options":[{"key":"A","text":"立春"},{"key":"B","text":"正月初一"},{"key":"C","text":"冬至"},{"key":"D","text":"春分"}],"answer":["A"],"explanation":"干支纪年是以立春作为一年的开始。农历最根本包含两部分,即农历历月和节气,其它的部分是由这两部分派生出来的,是为农业服务的。所以是以立春作为一年的起点。"},{"id":637,"type":"单选题","text":"中国古代典章制度史的创立者是____。","options":[{"key":"A","text":"杜佑"},{"key":"B","text":"司马迁"},{"key":"C","text":"班固"},{"key":"D","text":"司马光"}],"answer":["A"],"explanation":"中国第一部典章制度的百科全书是唐朝杜佑的《通典》，该书记载：“（汉）文帝十三年，以御史不奉法，下失其职，乃遗承相史出刺并督监察御史。”"},{"id":638,"type":"单选题","text":"我国古代将科举殿试的第三名称为____。","options":[{"key":"A","text":"探花"},{"key":"B","text":"榜眼"},{"key":"C","text":"状元"},{"key":"D","text":"传胪"}],"answer":["A"],"explanation":"探花是中国古代科举考试中对位列第三的进士的称谓，与第一名状元、第二名榜眼合称“三鼎甲”。"},{"id":639,"type":"单选题","text":"都江堰位于四川省，是____时期在李冰父子的主持下兴建的。","options":[{"key":"A","text":"战国"},{"key":"B","text":"秦代"},{"key":"C","text":"汉代"},{"key":"D","text":"唐代"}],"answer":["A"],"explanation":"都江堰始建于战国时期，是蜀郡太守李冰父子在前人鳖灵开凿的基础上组织修建的大型水利工程。"},{"id":640,"type":"单选题","text":"颐和园是乾隆皇帝为其母孝圣宪皇太后祝寿而建，其前身是____。","options":[{"key":"A","text":"清漪园"},{"key":"B","text":"圆明园"},{"key":"C","text":"静明园"},{"key":"D","text":"静宜园"}],"answer":["A"],"explanation":"颐和园，中国清朝时期皇家园林，前身为清漪园，坐落在北京西郊，距城区十五公里，占地约二百九十公顷，与圆明园毗邻。"},{"id":641,"type":"单选题","text":"“天下第一泉”共有四处，分别是庐山谷帘泉、____、济南趵突泉、镇江中泠泉。","options":[{"key":"A","text":"北京玉泉"},{"key":"B","text":"无锡惠山泉"},{"key":"C","text":"杭州虎跑泉"},{"key":"D","text":"苏州观音泉"}],"answer":["A"],"explanation":"分别是北京玉泉山玉泉、山东济南趵突泉、镇江扬子江中冷泉和庐山康王谷谷帘泉。"},{"id":642,"type":"单选题","text":"中国历史上的第一个王朝的建立者是____。","options":[{"key":"A","text":"大禹"},{"key":"B","text":"启"},{"key":"C","text":"黄帝"},{"key":"D","text":"尧"}],"answer":["A"],"explanation":"公元前2070年，禹建立了夏朝，这是我国历史上第一个王朝。"},{"id":643,"type":"单选题","text":"考古发现，____已经大量使用石器并且懂得人工取火和管理火。","options":[{"key":"A","text":"元谋人"},{"key":"B","text":"北京人"},{"key":"C","text":"山顶洞人"},{"key":"D","text":"半坡人"}],"answer":["B"],"explanation":"北京人遗址是世界上出土古人类遗骨和遗迹最丰富的遗址。先后发现五个比较完整的北京人头盖骨化石和一些其他部位的化石，还有大量的石器和石片，共十万件以上。距今约七十万年至二十万年，发现于北京周口店，保留了猿的某些特征，使用打制石器，已会使用天然火，过着群居的生活。"},{"id":644,"type":"单选题","text":"由汉武帝派遣出使西域的第一个使者是____。","options":[{"key":"A","text":"班超"},{"key":"B","text":"张骞"},{"key":"C","text":"甘英"},{"key":"D","text":"苏武"}],"answer":["B"],"explanation":"张骞富有开拓和冒险精神，建元二年(前139年)，奉汉武帝之命，由甘父做向导，率领一百多人出使西域，打通了汉朝通往西域的南北道路，即赫赫有名的丝绸之路，汉武帝以军功封其为博望侯。"},{"id":645,"type":"单选题","text":"迄今发现的铭文最多的古代青铜器是____。","options":[{"key":"A","text":"后母戊鼎"},{"key":"B","text":"毛公鼎"},{"key":"C","text":"大克鼎"},{"key":"D","text":"散氏盘"}],"answer":["B"],"explanation":"毛公鼎为西周晚期的重器，鼎内壁铸有铭文，32行，近500字，是现存青铜器铭文中最长的一篇，堪称西周青铜器中铭文之最。其内容叙事完整，记载详实，被誉为“抵得一篇《尚书》”，是研究西周晚年政治史的重要史料。"},{"id":646,"type":"单选题","text":"被誉为“中华第一玉龙”的玉猪龙，是____时期的玉器。","options":[{"key":"A","text":"良渚文化"},{"key":"B","text":"红山文化"},{"key":"C","text":"仰韶文化"},{"key":"D","text":"龙山文化"}],"answer":["B"],"explanation":"玉猪龙是红山文化时期中的代表玉器,又被称为玉兽玦,被专家们认为是龙最早的雏形。"},{"id":647,"type":"单选题","text":"古代被称为“国瓷”的著名瓷器品种是____。","options":[{"key":"A","text":"青瓷"},{"key":"B","text":"青花瓷"},{"key":"C","text":"白瓷"},{"key":"D","text":"粉彩瓷"}],"answer":["B"],"explanation":"青花瓷，属于釉下彩瓷，是我国的国瓷。白地蓝花，素雅洁净，是景德镇的名品佳作。"},{"id":648,"type":"单选题","text":"提出“宇宙便是吾心，吾心便是宇宙”哲学家是____。","options":[{"key":"A","text":"朱熹"},{"key":"B","text":"陆九渊"},{"key":"C","text":"王阳明"},{"key":"D","text":"程颢"}],"answer":["B"],"explanation":"陆九渊是宋代著名的理学家、主观唯心主义哲学家。他主张“吾心即是宇宙”，又倡“心即理”说。"},{"id":649,"type":"单选题","text":"战国时代，与儒家学说并称为两大显学的是____。","options":[{"key":"A","text":"道家"},{"key":"B","text":"墨家"},{"key":"C","text":"法家"},{"key":"D","text":"名家"}],"answer":["B"],"explanation":"战国时代的两大显学是：儒家和墨家。显学的意思：指盛行于世而影响较大的学术派别。"},{"id":650,"type":"单选题","text":"《庄子》名篇《逍遥游》中写：“北冥有鱼，其名为鲲。鲲之大，不知其几千里也。”这种名叫鲲的大鱼可以变化成鸟，请问鸟的名字是____。","options":[{"key":"A","text":"鸾"},{"key":"B","text":"鹏"},{"key":"C","text":"凤"},{"key":"D","text":"鹤"}],"answer":["B"],"explanation":"北冥有鱼，其名为鲲。鲲之大，不知其几千里也。化而为鸟，其名为鹏。鹏之背，不知其几千里也，怒而飞，其翼若垂天之云。"},{"id":651,"type":"单选题","text":"以法制为中心，综合运用“法势术”是法家成熟的表现，而提出这一理论的是____。","options":[{"key":"A","text":"商鞅"},{"key":"B","text":"韩非子"},{"key":"C","text":"申不害"},{"key":"D","text":"慎到"}],"answer":["B"],"explanation":"“法势术”这一理论是由秦国的韩非子提出的。在韩非之前已有申不害、商鞅、慎到等法家人物对法家学说做了许多论述，商鞅主要讲“法”，申不害主要讲“术”，慎到主要讲“势”。"},{"id":652,"type":"单选题","text":"首次在中国哲学史上明确提出“知行合一”的是____。","options":[{"key":"A","text":"朱熹"},{"key":"B","text":"王阳明"},{"key":"C","text":"陆九渊"},{"key":"D","text":"程颐"}],"answer":["B"],"explanation":"知行合一，致良知，是阳明文化的核心。明武宗正德四年（1509），心学集大成者王守仁在贵阳文明书院讲学，首次提出知行合一说。"},{"id":653,"type":"单选题","text":"建构了以“理”“气”解释宇宙人生的哲学理论体系的是____先生。","options":[{"key":"A","text":"阳明"},{"key":"B","text":"紫阳"},{"key":"C","text":"象山"},{"key":"D","text":"横渠"}],"answer":["B"],"explanation":"朱熹（1130年10月22日－1200年4月23日），字元晦，一字仲晦，斋号晦庵、考亭，晚称晦翁，又称紫阳先生，建构了以“理”“气”解释宇宙人生的哲学理论体系。"},{"id":654,"type":"单选题","text":"“水则载舟，水则载舟”是我国古代思想史上____提出的著名论点。","options":[{"key":"A","text":"孔子"},{"key":"B","text":"荀子"},{"key":"C","text":"孟子"},{"key":"D","text":"老子"}],"answer":["B"],"explanation":"“水则载舟,水则覆舟”出自《荀子・王制》。荀子,战国末期赵国人,著名思想家、文学家、政治家,荀子对儒家思想有所发展,在人性问题上,提倡性恶论,否认天赋的道德观念,强调后天环境和教育对人的影响。"},{"id":655,"type":"单选题","text":"“天人合一”的说法是宋代哲学家____明确提出的。","options":[{"key":"A","text":"朱熹"},{"key":"B","text":"张载"},{"key":"C","text":"程颢"},{"key":"D","text":"陆九渊"}],"answer":["B"],"explanation":"真正明确提出“天人合一”的是北宋哲学家张载。张载在天、人关系的研究上独树一帜，承前启后，以《孟子》《中庸》《大学》等经典之“性”“诚”“明”的理念贯通天人。"},{"id":656,"type":"单选题","text":"儒家提倡的“内圣外王”之道有其循序渐进的途径，依次是修身、齐家、治国、____。","options":[{"key":"A","text":"格物致知"},{"key":"B","text":"平天下"},{"key":"C","text":"致良知"},{"key":"D","text":"诚意正心"}],"answer":["B"],"explanation":"《礼记·大学》：“古之欲明明德于天下者，先治其国；欲治其国者，先齐其家；欲齐其家者，先修其身；欲修其身者，先正其心；欲正其心者，先诚其意；欲诚其意者，先致其知，致知在格物。物格而后知至，知至而后意诚，意诚而后心正，心正而后身修，身修而后家齐，家齐而后国治，国治而后天下平。”"},{"id":657,"type":"单选题","text":"属于道教的三天尊的是玉清原始天尊、上清灵宝君和太清____。","options":[{"key":"A","text":"玉皇大帝"},{"key":"B","text":"道德天尊"},{"key":"C","text":"真武大帝"},{"key":"D","text":"太上老君"}],"answer":["B"],"explanation":"三清天尊是道教对其所崇奉的三位最高天神的合称。指居于三清仙境的三位尊神，即玉清境清微天元始天尊、上清境禹馀天灵宝天尊、太清境大赤天道德天尊。其中所谓玉清境、上清境、太清境是所居仙境的区别，清微天、禹余天、大赤天是所统天界的划分，而天尊的意思则是说，极道之尊，至尊至极，故名天尊。"},{"id":658,"type":"单选题","text":"中国现存最大的清真寺是喀什的____。","options":[{"key":"A","text":"南关清真寺"},{"key":"B","text":"艾提尕尔清真寺"},{"key":"C","text":"西关清真寺"},{"key":"D","text":"化觉巷清真大寺"}],"answer":["B"],"explanation":"中国最大的清真寺是新疆的艾提尕尔清真寺。2001年06月25日，艾提尕尔清真寺作为明代古建筑，被国务院批准列入第五批全国重点文物保护单位名单。"},{"id":659,"type":"单选题","text":"“太守与客来饮于此，饮少辄醉，而年又最高，故自号曰醉翁也”中的“太守”是____。","options":[{"key":"A","text":"苏轼"},{"key":"B","text":"柳宗元"},{"key":"C","text":"欧阳修"},{"key":"D","text":"范仲淹"}],"answer":["C"],"explanation":"《醉翁亭记》最后一句：“太守谓谁？庐陵欧阳修也。”"},{"id":660,"type":"单选题","text":"宣纸是中国独特的手工艺品，享有“千年寿纸”的美誉。它名字的来历与什么有关____。","options":[{"key":"A","text":"材质"},{"key":"B","text":"用途"},{"key":"C","text":"产地"},{"key":"D","text":"创制者"}],"answer":["C"],"explanation":"宣纸得名于其产地——安徽宣城。"},{"id":661,"type":"单选题","text":"顾恺之创作的是____。","options":[{"key":"A","text":"《步辇图》"},{"key":"B","text":"《游春图》"},{"key":"C","text":"《洛神赋图》"},{"key":"D","text":"《历代帝王图》"}],"answer":["C"],"explanation":"《洛神赋图》是东晋顾恺之的画作，原《洛神赋图》卷为设色绢本。是由多个故事情节组成的类似连环画而又融会贯通的长卷。"},{"id":662,"type":"单选题","text":"阎立本创作的是____。","options":[{"key":"A","text":"《富春山居图》"},{"key":"B","text":"《游春图》"},{"key":"C","text":"《历代帝王图》"},{"key":"D","text":"《洛神赋图》"}],"answer":["C"],"explanation":"《历代帝王图》又名《列帝图》、《十三帝图》、《古列帝图卷》、《古帝王图》，传为唐代阎立本画作，绢本，设色，现存后人摹本。"},{"id":663,"type":"单选题","text":"展子虔创作的是____。","options":[{"key":"A","text":"《洛神赋图》"},{"key":"B","text":"《历代帝王图》"},{"key":"C","text":"《游春图》"},{"key":"D","text":"《步辇图》"}],"answer":["C"],"explanation":"《游春图》是隋朝画家展子虔创作的绘画作品，绢本、青绿设色，画上有宋徽宗题写的“展子虔游春图”六个字，现存北京故宫博物院绘画馆。、"},{"id":664,"type":"单选题","text":"书法史上“楷书四大家”指的是欧阳询、____、柳公权、赵孟頫。","options":[{"key":"A","text":"褚遂良"},{"key":"B","text":"虞世南"},{"key":"C","text":"颜真卿"},{"key":"D","text":"薛稷"}],"answer":["C"],"explanation":"楷书四大家是对书法史上以楷书著称的四位书法家的合称,也称四大楷书。他们分别指：唐朝欧阳询(欧体)、唐朝颜真卿(颜体)、唐朝柳公权(柳体)、元代赵孟頫(赵体)。"},{"id":665,"type":"单选题","text":"现存面积最大的地面城池是____。","options":[{"key":"A","text":"开封城"},{"key":"B","text":"北京城"},{"key":"C","text":"西安城"},{"key":"D","text":"南京城"}],"answer":["C"],"explanation":"古代的城市称作城池，“城”指城墙，“池”指城外环绕城墙的河池，俗称“护城河”。西安城是我国现存面积最大、保存最完整的古城。"},{"id":666,"type":"单选题","text":"北京故宫是____时期修建的。","options":[{"key":"A","text":"明太祖"},{"key":"B","text":"清世祖"},{"key":"C","text":"明成祖"},{"key":"D","text":"清圣祖"}],"answer":["C"],"explanation":"紫禁城是明成祖朱棣在位时建造的，于明成祖永乐四年（1406年）开始建设，以南京故宫为蓝本营建，到永乐十八年（1420年）建成。它是一座长方形城池，南北长961米，东西宽753米，四面围有高10米的城墙，城外有宽52米的护城河。紫禁城内的建筑分为外朝和内廷两部分。"},{"id":667,"type":"单选题","text":"最早修建长城的是春秋时的____国。","options":[{"key":"A","text":"秦"},{"key":"B","text":"燕"},{"key":"C","text":"楚"},{"key":"D","text":"赵"}],"answer":["C"],"explanation":"最早修建长城是春秋时期的楚国，《左传》上所说楚国“汉水以为池，方城以为城”的方城，即指此。"},{"id":668,"type":"单选题","text":"秦长城实际上是把春秋战国时期 秦国、燕国、____三国修建的长城连在一起。","options":[{"key":"A","text":"齐国"},{"key":"B","text":"韩国"},{"key":"C","text":"赵国"},{"key":"D","text":"魏国"}],"answer":["C"],"explanation":"秦始皇三十三年（公元前214年）遣大将蒙恬北逐匈奴，筑长城万余里，以防匈奴南进，史称秦长城。秦长城实际是在原先战国时期秦长城，赵长城，燕长城三国长城的基础上修建。"},{"id":669,"type":"单选题","text":"历史上，春秋战国时期、秦代、____、北朝、隋代、金代、明代修筑长城。","options":[{"key":"A","text":"唐代"},{"key":"B","text":"宋代"},{"key":"C","text":"汉代"},{"key":"D","text":"元代"}],"answer":["C"],"explanation":"历史上，春秋战国时期、秦代、汉代、北朝、隋代、金代、明代修筑长城。持续近2000年，长城东西绵延上万华里，因此又称作万里长城。长城建筑于两千多年前的春秋战国时代，现存的长城遗迹主要为建于14世纪的明长城。"},{"id":670,"type":"单选题","text":"佛教的创始人是乔达摩·____。","options":[{"key":"A","text":"牟尼"},{"key":"B","text":"达摩"},{"key":"C","text":"悉达多"},{"key":"D","text":"玄奘"}],"answer":["C"],"explanation":"乔达摩·悉达多是古印度著名思想家，古印度迦毗罗卫国释迦族人，佛教的创始者，被后世尊称为释迦牟尼佛。"},{"id":671,"type":"单选题","text":"中国三大古建筑群的是____、曲阜孔庙、承德避暑山庄。","options":[{"key":"A","text":"苏州园林"},{"key":"B","text":"平遥古城"},{"key":"C","text":"北京故宫"},{"key":"D","text":"丽江古城"}],"answer":["C"],"explanation":"中国三大古建筑群，即北京故宫、曲阜孔庙和承德避暑山庄，中国三大古建筑群均已列入世界文化遗产名录。"},{"id":672,"type":"单选题","text":"被誉为“古民居博物馆”的是____。","options":[{"key":"A","text":"晋派民居"},{"key":"B","text":"闽派民居"},{"key":"C","text":"徽派民居"},{"key":"D","text":"粤派民居"}],"answer":["C"],"explanation":"徽派民居是汉族传统民居建筑的一个重要流派，被誉为“古民居博物馆”。无论南方还是北方的汉族，其传统民居的共同特点都是坐北朝南，注重内采光；以木梁承重，以砖、石、土砌护墙；以堂屋为中心，以雕梁画栋和装饰屋顶、檐口见长。"},{"id":673,"type":"单选题","text":"古代茶圣是____。","options":[{"key":"A","text":"蔡襄"},{"key":"B","text":"皎然"},{"key":"C","text":"陆羽"},{"key":"D","text":"卢仝"}],"answer":["C"],"explanation":"陆羽（733—804），字鸿渐，复州竟陵（今湖北天门）人，一名疾，字季疵，号竟陵子、桑苎翁、东冈子，又号“茶山御史”。是唐代著名的茶学家，被誉为“茶仙”，尊为“茶圣”，祀为“茶神”。"},{"id":674,"type":"单选题","text":"“何以解忧，唯有杜康”这句诗出自东汉末年____的《短歌行》。","options":[{"key":"A","text":"陶渊明"},{"key":"B","text":"曹丕"},{"key":"C","text":"曹操"},{"key":"D","text":"曹植"}],"answer":["C"],"explanation":"“何以解忧，唯有杜康”这句诗出自东汉末年曹操的《短歌行》。"},{"id":675,"type":"单选题","text":"李清照号____。","options":[{"key":"A","text":"青莲居士"},{"key":"B","text":"香山居士"},{"key":"C","text":"易安居士"},{"key":"D","text":"六一居士"}],"answer":["C"],"explanation":"李清照，南宋女词人。号易安居士，今山东济南人。长于诗、文、词,兼书法、绘画,且通音律。"},{"id":676,"type":"单选题","text":"著名的候风地动仪的研制者是____。","options":[{"key":"A","text":"祖冲之"},{"key":"B","text":"僧一行"},{"key":"C","text":"张衡"},{"key":"D","text":"郭守敬"}],"answer":["C"],"explanation":"候风地动仪的发明者东汉大科学家张衡。早在公元132年，中国就发明了地球的探测器——地动仪。它是中国古代科文并茂的巨星——张衡创制发明的，也是世界上最早的一台会测报地震方向的科学仪器，它首开人类科学测报地震的先河。"},{"id":677,"type":"单选题","text":"明代三大针灸巨著指的是《针灸大全》《针灸聚英》和____。","options":[{"key":"A","text":"《难经》"},{"key":"B","text":"《针灸甲乙经》"},{"key":"C","text":"《针灸大成》"},{"key":"D","text":"《黄帝内经》"}],"answer":["C"],"explanation":"明代是针灸学术发展的鼎盛时期，理论逐渐深入和细化，涌现了大批的学术著作，如三大针灸巨著：《针灸大全》、《针灸节要》、《针灸聚英》等。"},{"id":678,"type":"单选题","text":"李白号____。","options":[{"key":"A","text":"易安居士"},{"key":"B","text":"香山居士"},{"key":"C","text":"六一居士"},{"key":"D","text":"青莲居士"}],"answer":["D"],"explanation":"李白（701年—762年） ，字太白，号青莲居士，又号“谪仙人”。"},{"id":679,"type":"单选题","text":"属于徐光启的著作是____。","options":[{"key":"A","text":"《天工开物》"},{"key":"B","text":"《齐民要术》"},{"key":"C","text":"《本草纲目》"},{"key":"D","text":"《农政全书》"}],"answer":["D"],"explanation":"《农政全书》是明代徐光启创作的农书，成书于明朝万历年间，大致上可分为农政措施和农业技术两部分。"},{"id":680,"type":"单选题","text":"国子监的最高官员称为____。","options":[{"key":"A","text":"司业"},{"key":"B","text":"监丞"},{"key":"C","text":"博士"},{"key":"D","text":"祭酒"}],"answer":["D"],"explanation":"国子监以师为官，最高职位是祭酒，一般的教学和管理人员也是朝廷命官，由吏部统一管理任免。国子监的学生称为监生，监生又分官生和民生。"},{"id":681,"type":"单选题","text":"最早记录指南针存在偏差的是____。","options":[{"key":"A","text":"《齐民要术》"},{"key":"B","text":"《天工开物》"},{"key":"C","text":"《本草纲目》"},{"key":"D","text":"《梦溪笔谈》"}],"answer":["D"],"explanation":"沈括是世界上第一个指出指南针不完全指南北的人，记载于《梦溪笔谈》中。"},{"id":682,"type":"单选题","text":"____被誉为“天下名茶之冠”。","options":[{"key":"A","text":"碧螺春"},{"key":"B","text":"铁观音"},{"key":"C","text":"祁门红茶"},{"key":"D","text":"西湖龙井"}],"answer":["D"],"explanation":"杭州西湖龙井，被誉为“天下名茶之冠”，产于湘江省杭州市西湖周围的群山之中。"},{"id":683,"type":"单选题","text":"唐太宗李世民登基前曾发动“玄武门事变”，按照古代五行说，大兴宫的“玄武门”一定位于该宫的____。","options":[{"key":"A","text":"南方"},{"key":"B","text":"东方"},{"key":"C","text":"西方"},{"key":"D","text":"北方"}],"answer":["D"],"explanation":"玄武门之变，是唐高祖武德九年六月初四（公元626年7月2日），是由当时唐高祖李渊次子秦王李世民在唐王朝的首都长安城（今陕西省西安）太极宫的北宫门--玄武门附近发动的一次政变。"},{"id":684,"type":"单选题","text":"传统节日中，源于佛教传说的是____。","options":[{"key":"A","text":"清明节"},{"key":"B","text":"端午节"},{"key":"C","text":"中秋节"},{"key":"D","text":"腊八节"}],"answer":["D"],"explanation":"腊八节，即每年农历十二月八日，又称为“法宝节”“佛成道节”“成道会”等。本为佛教纪念释迦牟尼佛成道之节日，后逐渐也成为民间节日。"},{"id":685,"type":"单选题","text":"在中国的饮茶史上，____皇帝是著名的泉水评定专家，被誉为“茶帝”。","options":[{"key":"A","text":"康熙"},{"key":"B","text":"唐太宗"},{"key":"C","text":"宋徽宗"},{"key":"D","text":"乾隆"}],"answer":["D"],"explanation":"乾隆皇帝爱新觉罗弘历（1711——1799）在世89年,是我国历史上在位时间最长,寿命最长的皇帝,也是最爱茶的皇帝。"},{"id":686,"type":"单选题","text":"中国的三大传统节日是____、中秋节、端午节。","options":[{"key":"A","text":"清明节"},{"key":"B","text":"元宵节"},{"key":"C","text":"重阳节"},{"key":"D","text":"春节"}],"answer":["D"],"explanation":"中国的三大传统节日是春节、端午节、中秋节。"},{"id":687,"type":"单选题","text":"人殉制度是中国历史上最残忍的制度，他终止于____时期。","options":[{"key":"A","text":"清世祖"},{"key":"B","text":"明成祖"},{"key":"C","text":"明太祖"},{"key":"D","text":"明英宗"}],"answer":["D"],"explanation":"明英宗朱祁镇即位后，对人殉制度非常厌恶，明确提出废止人殉，曾下旨说“藩王薨，妃、夫人以下不必从死，年少有父母者遣归”。"},{"id":688,"type":"单选题","text":"二胡名曲《二泉映月》中的“二泉”指的是天下第二泉，它位于____。","options":[{"key":"A","text":"杭州"},{"key":"B","text":"苏州"},{"key":"C","text":"镇江"},{"key":"D","text":"无锡"}],"answer":["D"],"explanation":"二泉映月中的二泉，是江苏无锡市的西郊惠山九龙十三泉，中声名最大的“天下第二泉”，人们也称它为二泉。"},{"id":689,"type":"单选题","text":"既不能以公历日期也不能以夏历日期准确确定日期的传统节日是____。","options":[{"key":"A","text":"春节"},{"key":"B","text":"端午节"},{"key":"C","text":"中秋节"},{"key":"D","text":"清明节"}],"answer":["D"],"explanation":"清明节不是固定日期，不过清明在阳历中的日期会在4月4日、4月5日和4月6日这三个日子中变动。统计结果表明，在1582年采用现行公历至2100年的518年中，清明在4月4日的为219年，4月5日的为281年，4月6日的最少只有18年。"},{"id":690,"type":"单选题","text":"盖碗茶是____族所喜爱的特色饮茶方式。","options":[{"key":"A","text":"藏"},{"key":"B","text":"蒙古"},{"key":"C","text":"壮"},{"key":"D","text":"回"}],"answer":["D"],"explanation":"盖碗茶是西北回族的一种独特的饮茶方式，相传始于唐代，相传至今，颇受回族人民喜爱。"},{"id":691,"type":"单选题","text":"葬俗中，为佛教所提倡，却为儒家强烈反对的是____。","options":[{"key":"A","text":"土葬"},{"key":"B","text":"水葬"},{"key":"C","text":"天葬"},{"key":"D","text":"火葬"}],"answer":["D"],"explanation":"佛教传入中国后，其理论不断影响儒家社会的生活方式，其主张的火葬之法也逐步为民间社会普遍接受。宋儒出于对儒家义理的维护，强烈反对这种习俗，试图扭转这一违背儒家思想的丧葬习俗。"},{"id":692,"type":"单选题","text":"我国古代铜活字印书史上造字时间最长、耗费资金最大、刻字数量最多的人物是____。","options":[{"key":"A","text":"王祯"},{"key":"B","text":"毕升"},{"key":"C","text":"周必大"},{"key":"D","text":"林春祺"}],"answer":["D"],"explanation":"在我国古代印刷史上，林春祺造铜活字印书，造字时间最长，耗费资金最大，刻字数量最多。"},{"id":693,"type":"单选题","text":"王维的诗句“朝为越溪女，暮作吴宫妃。”说的是我国古代的著名美女____。","options":[{"key":"A","text":"王昭君"},{"key":"B","text":"貂蝉"},{"key":"C","text":"杨玉环"},{"key":"D","text":"西施"}],"answer":["D"],"explanation":"《西施咏》：“艳色天下重，西施宁久微。朝为越溪女，暮作吴宫妃。贱日岂殊众，贵来方悟稀。邀人傅脂粉，不自著罗衣。君宠益娇态，君怜无是非。当时浣纱伴，莫得同车归。持谢邻家子，效颦安可希。”《西施咏》是唐代诗人王维创作的一首诗。此诗借西施从平民到宫廷宠妃的历史典故，揭示人生浮沉全凭际遇的炎凉世态，并表达对小人的嘲讽，揭露当时社会上潜藏的危机，抒发诗人怀才不遇的不平与感慨。"},{"id":694,"type":"单选题","text":"诗句“年年乞与人间巧，不道人间巧已多？”描述的是我国____。","options":[{"key":"A","text":"元宵节"},{"key":"B","text":"端午节"},{"key":"C","text":"中秋节"},{"key":"D","text":"七夕节"}],"answer":["D"],"explanation":"诗句“年年乞与人间巧，不道人间巧已多？”描述的是我国七夕节，又称七巧节、七姐节、女儿节、乞巧节等）是中国民间的传统节日，由星宿崇拜衍化而来，为传统意义上的七姐诞，因拜祭“七姐”活动在七月七晩上举行，故名“七夕”。"},{"id":695,"type":"单选题","text":"“苦心人，无不负，卧薪尝胆，三千越申可吞吴。”描写的是____。","options":[{"key":"A","text":"项羽"},{"key":"B","text":"刘邦"},{"key":"C","text":"夫差"},{"key":"D","text":"勾践"}],"answer":["D"],"explanation":"出自蒲松龄“落第自勉联”：有志者，事竟成，破釜沉舟，百二秦关终属楚；苦心人，天不负，卧薪尝胆，三千越甲可吞吴。越王勾践（约前520年―前465年），姒姓，名勾践，又名鸠浅、菼执，夏禹后裔，越王允常之子，春秋末年越国国君。前496年即位，曾败于吴国，被迫求和。返国后重用范蠡、文种，卧薪尝胆使越国国力渐渐恢复起来。前482年，吴王夫差兴兵参加黄池之会，以彰显武力率精锐而出。越王勾践抓住机会率兵而起，大败吴师。夫差仓卒与晋国定盟而返，与勾践连战惨败。不得已与越议和。前473年夫差被迫自尽，灭吴国称霸，是春秋时期最后一位霸主。"},{"id":696,"type":"单选题","text":"我国广州市的别称是____。","options":[{"key":"A","text":"春城"},{"key":"B","text":"江城"},{"key":"C","text":"蓉城"},{"key":"D","text":"羊城"}],"answer":["D"],"explanation":"羊城是广州别称，广东省省会，位于广东省中南部，东江、西江、北江交汇处，珠江三角洲北缘，濒临中国南海。"},{"id":697,"type":"单选题","text":"为了感念苏东坡的功德，杭州流传着一道名菜____。","options":[{"key":"A","text":"西湖醋鱼"},{"key":"B","text":"龙井虾仁"},{"key":"C","text":"宋嫂鱼羹"},{"key":"D","text":"东坡肉"}],"answer":["D"],"explanation":"东坡肉相传为北宋词人苏轼（四川省眉山市人）所创制（一说为苏轼小妾王朝云在苏轼被贬黄州之际为改善饮食所创），最早发源地是四川眉山。"},{"id":698,"type":"单选题","text":"五谷中的“黍”是指____。","options":[{"key":"A","text":"小米"},{"key":"B","text":"黄米"},{"key":"C","text":"大米"},{"key":"D","text":"小麦"}],"answer":["B"],"explanation":"黄米又称黍、糜子、黄米、夏小米、黄小米，有糯质和非糯质之别，糯质黍多作以醇酒，非糯质黍，称为穄，以食用为主。"},{"id":699,"type":"单选题","text":"田园诗派的开创者是____。","options":[{"key":"A","text":"陶渊明"},{"key":"B","text":"王维"},{"key":"C","text":"孟浩然"},{"key":"D","text":"谢灵运"}],"answer":["A"],"explanation":"陶渊明，字元亮，又名潜，世称靖节先生，私谥靖节，世称靖节先生，浔阳柴桑（今江西九江）人，东晋著名诗人、辞赋家、散文家，被誉为“隐逸诗人之宗”“田园诗派之鼻祖”，江西首位文学巨匠。"},{"id":700,"type":"单选题","text":"我国的第一部长篇历史小说是____。","options":[{"key":"A","text":"《三国演义》"},{"key":"B","text":"《水浒传》"},{"key":"C","text":"《西游记》"},{"key":"D","text":"《红楼梦》"}],"answer":["A"],"explanation":"《三国演义》（全名为《三国志通俗演义》，又称《三国志传》）是中国古典四大名著之一，亦是中国第一部长篇历史章回小说，作者是元末明初的罗贯中。"},{"id":701,"type":"单选题","text":"清朝文学家蒲松龄号“柳泉居士”，世称____。","options":[{"key":"A","text":"易安居士"},{"key":"B","text":"六一居士"},{"key":"C","text":"聊斋先生"},{"key":"D","text":"香山居士"}],"answer":["C"],"explanation":"蒲松龄（1640年6月5日-1715年2月25日），字留仙，一字剑臣，别号柳泉居士，世称聊斋先生，自称异史氏。"},{"id":702,"type":"单选题","text":"《水调歌头·明月几时有》一词的小序中提到的“子由”是苏轼的____。","options":[{"key":"A","text":"哥哥"},{"key":"B","text":"父亲"},{"key":"C","text":"儿子"},{"key":"D","text":"弟弟"}],"answer":["D"],"explanation":"子由是苏轼弟弟苏辙的字。"},{"id":703,"type":"单选题","text":"被尊为“曲状元”的是____。","options":[{"key":"A","text":"郑光祖"},{"key":"B","text":"关汉卿"},{"key":"C","text":"白朴"},{"key":"D","text":"马致远"}],"answer":["D"],"explanation":"马致远，字千里，号东篱，被尊称为“曲状元”，在元代的文学史上具有极高的声誉。"},{"id":704,"type":"单选题","text":"____在古时是指结婚时把夫妻头发束在一起。","options":[{"key":"A","text":"纳征"},{"key":"B","text":"结发"},{"key":"C","text":"纳采"},{"key":"D","text":"合饮"}],"answer":["B"],"explanation":"结发是古时候的婚姻习俗，当夫妻成婚时，各取头上一根头发，合而作一结，男女双方结为夫妻。这就是古诗中所说的：“结发为夫妻，恩爱两不疑”。"},{"id":705,"type":"单选题","text":"著名的元代杂剧西厢记取材于____。","options":[{"key":"A","text":"《莺莺传》"},{"key":"B","text":"《牡丹亭》"},{"key":"C","text":"《长生殿》"},{"key":"D","text":"《桃花扇》"}],"answer":["A"],"explanation":"元曲《西厢记》取材唐代传奇《莺莺传》。"},{"id":706,"type":"单选题","text":"____是关于农业生产和农事活动的著作。","options":[{"key":"A","text":"《本草纲目》"},{"key":"B","text":"《齐民要术》"},{"key":"C","text":"《天工开物》"},{"key":"D","text":"《农政全书》"}],"answer":["B"],"explanation":"《齐民要术》大约成书于北魏末年(公元533年-544年)，是北朝北魏时期，南朝宋至梁时期，中国杰出农学家贾思勰所著的一部综合性农学著作，也是世界农学史上专著之一，是中国现存最早的一部完整的农书。"},{"id":707,"type":"单选题","text":"秦灭六国，统一天下，大兴土木，依山建起____，亭台楼阁参差环抱，绵延三百余里气势非凡。","options":[{"key":"A","text":"大明宫"},{"key":"B","text":"长乐宫"},{"key":"C","text":"阿房宫"},{"key":"D","text":"未央宫"}],"answer":["C"],"explanation":"杜牧《阿房宫赋》第一句：“六王毕，四海一，蜀山兀，阿房出。”"},{"id":708,"type":"单选题","text":"瓷器唐三彩为白色、黄色和____。","options":[{"key":"A","text":"绿色"},{"key":"B","text":"紫色"},{"key":"C","text":"蓝色"},{"key":"D","text":"红色"}],"answer":["A"],"explanation":"唐三彩，中国古代陶瓷烧制工艺的珍品，全名唐代三彩釉陶器，是盛行于唐代的一种低温釉陶器，釉彩有黄、绿、白、褐、蓝、黑等色彩，而以黄、绿、白三色为主。"},{"id":709,"type":"单选题","text":"先秦两汉时期成就最高，影响最大，通过人物描写来反映历史面貌的是____。","options":[{"key":"A","text":"《史记》"},{"key":"B","text":"《汉书》"},{"key":"C","text":"《左传》"},{"key":"D","text":"《战国策》"}],"answer":["A"],"explanation":"“通过人物描写反映历史面貌”，可知此书是纪传体，因为纪传体是通过记叙人物活动反映历史事件的史书体例。《史记》为西汉司马迁所作，是中国第一部纪传体通史，以人物传记为中心来反映历史内容，记载了从黄帝以来至汉武帝时期的历史，被列为“二十四史之首”。"},{"id":710,"type":"单选题","text":"“在天愿做比翼鸟，在地愿为连理枝。”这句诗描写的是____和杨贵妃的爱情故事。","options":[{"key":"A","text":"唐宪宗"},{"key":"B","text":"唐高宗"},{"key":"C","text":"唐明皇"},{"key":"D","text":"唐太宗"}],"answer":["C"],"explanation":"这句诗出自白居易的《长恨歌》，描述的是唐明皇和杨贵妃的爱情故事，无论是在天上地下，彼此都不希望分开。这句诗展现了忠贞不渝的爱情观。"},{"id":711,"type":"单选题","text":"《红楼梦》中有“小宝钗\"，“小黛玉”之称的两人是袭人、____。","options":[{"key":"A","text":"鸳鸯"},{"key":"B","text":"麝月"},{"key":"C","text":"平儿"},{"key":"D","text":"晴雯"}],"answer":["D"],"explanation":"小宝钗指的是袭人，他们俩都是封建思想的代表，实时劝谏宝玉读书封侯，与达官贵人结交。小黛玉指的是晴雯，第一是晴雯和黛玉关系本来就不错，又都是不喜欢宝玉读书考举人进士，厌恶世俗经济学问的人。"},{"id":712,"type":"单选题","text":"郑谷有诗曰“何事文星与酒星，一时钟在李先生。高鸣大醉三千百，留着人家伴月明。”诗中的“李先生”指的____。","options":[{"key":"A","text":"李清照"},{"key":"B","text":"李贺"},{"key":"C","text":"李商隐"},{"key":"D","text":"李白"}],"answer":["D"],"explanation":"诗中的李先生指的是李白。这首诗是“芳林十哲”之一的郑谷读了李白的诗以后写的。"},{"id":713,"type":"单选题","text":"王昌龄《出塞》一诗 “但使龙城飞将在”中的“飞将”指的是____。","options":[{"key":"A","text":"李陵"},{"key":"B","text":"霍去病"},{"key":"C","text":"卫青"},{"key":"D","text":"李广"}],"answer":["D"],"explanation":"西汉英勇善战,被匈奴称为“飞将军”的名将李广。"},{"id":714,"type":"单选题","text":"“七月流火，九月授衣”，其中“七月流火”指的是：____。","options":[{"key":"A","text":"天气渐渐转凉"},{"key":"B","text":"七月天气炎热"},{"key":"C","text":"流星划过夜空"},{"key":"D","text":"火灾多发季节"}],"answer":["A"],"explanation":"出自《诗经·豳风·七月》，“七月流火，九月授衣”指夏去秋来，天气转凉。"},{"id":715,"type":"单选题","text":"“但愿人长久，千里共婵娟”，苏东坡借这首词表达了对____的思念之情。","options":[{"key":"A","text":"父亲"},{"key":"B","text":"妻子"},{"key":"C","text":"兄弟"},{"key":"D","text":"朋友"}],"answer":["C"],"explanation":"“但愿人长久，千里共婵娟。”苏东坡借这首词表达了对弟弟苏辙的思念之情。"},{"id":716,"type":"单选题","text":"五湖指的是洞庭湖、鄱阳湖、太湖、巢湖、____。","options":[{"key":"A","text":"青海湖"},{"key":"B","text":"洪泽湖"},{"key":"C","text":"西湖"},{"key":"D","text":"千岛湖"}],"answer":["B"],"explanation":"五湖指洞庭湖、鄱阳湖、太湖、巢湖和洪泽湖。"},{"id":717,"type":"单选题","text":"元杂剧中的女主唱称为____。","options":[{"key":"A","text":"旦本"},{"key":"B","text":"末本"},{"key":"C","text":"净本"},{"key":"D","text":"丑本"}],"answer":["A"],"explanation":"旦本戏是戏剧用语，指元杂剧由女主角演唱的杂剧为旦本戏。"},{"id":718,"type":"单选题","text":"“匪女之为美，美人之贻”中的“贻”的意思是____。","options":[{"key":"A","text":"赠送"},{"key":"B","text":"遗留"},{"key":"C","text":"丢失"},{"key":"D","text":"购买"}],"answer":["A"],"explanation":"贻的意思是指： 赠给。解释：不是你的美好(让我动心)，(而是因为)美人送给我的(我才珍惜)。"},{"id":719,"type":"单选题","text":"旧时我国的老百姓称____为“仓神”。","options":[{"key":"A","text":"老鼠"},{"key":"B","text":"牛"},{"key":"C","text":"马"},{"key":"D","text":"猪"}],"answer":["A"],"explanation":"旧时我国民间曾将正月二十五日定为“填仓节”。人们管老鼠叫“仓神”。到“填仓节”这天，家家仓囤装满粮食，并虔诚祭祀，祈求“老鼠仓神”口下留情，少来偷吃，并祷祝年年五谷丰登，粮油满仓。"},{"id":720,"type":"单选题","text":"“名不正言不顺”表达了中国的____思想。","options":[{"key":"A","text":"法家"},{"key":"B","text":"道家"},{"key":"C","text":"儒家"},{"key":"D","text":"墨家"}],"answer":["C"],"explanation":"“名不正言不顺”是儒家的思想。出处：《论语·子路》：“名不正则言不顺，言不顺则事不成。”"},{"id":721,"type":"单选题","text":"山东曲阜有“三孔”，分别是“孔府”、“ 孔林 ”和____。","options":[{"key":"A","text":"孔院"},{"key":"B","text":"孔祠"},{"key":"C","text":"孔墓"},{"key":"D","text":"孔庙"}],"answer":["D"],"explanation":"曲阜三孔由孔庙、孔府和孔林构成，位于山东省曲阜市，是中国唯一且规模最大的集祭祀孔子的寺庙、孔子嫡系后裔的府邸和孔子及其子孙墓地于一体的建筑群。"},{"id":722,"type":"单选题","text":"“格萨尔王”史诗是我国____的优秀作品。","options":[{"key":"A","text":"彝族"},{"key":"B","text":"维吾尔族"},{"key":"C","text":"藏族"},{"key":"D","text":"蒙古族"}],"answer":["C"],"explanation":"格萨尔王史诗是藏族人民集体创作的一部伟大的英雄史诗，历史悠久，结构宏伟，卷帙浩繁，内容丰富，气势磅礴，流传广泛。"},{"id":723,"type":"单选题","text":"“霓裳羽衣”是我国____代的宫廷乐舞。","options":[{"key":"A","text":"明"},{"key":"B","text":"宋"},{"key":"C","text":"元"},{"key":"D","text":"唐"}],"answer":["D"],"explanation":"霓裳羽衣舞，是一种唐代的宫廷乐舞，唐玄宗作曲。"},{"id":724,"type":"单选题","text":"“字字看来皆是血，十年辛苦不寻常”描述的是名著____的成书过程。","options":[{"key":"A","text":"《红楼梦》"},{"key":"B","text":"《三国演义》"},{"key":"C","text":"《水浒传》"},{"key":"D","text":"《西游记》"}],"answer":["A"],"explanation":"《红楼梦》，又名《石头记》《金玉缘》，是清代作家曹雪芹创作的章回体长篇小说，被誉为中国古典四大名著之首。“字字看来皆是血，十年辛苦不寻常。”是《红楼梦》甲戌本第一回之前《凡例》的末尾。《凡例》的末段内容与其他诸本第一回第一段基本相同，是对全书的总评。"},{"id":725,"type":"单选题","text":"吴伟业名句“恸哭三军俱缟素，冲冠一怒为红颜”中的“红颜”指的是____。","options":[{"key":"A","text":"陈圆圆"},{"key":"B","text":"李师师"},{"key":"C","text":"苏小小"},{"key":"D","text":"柳如是"}],"answer":["A"],"explanation":"“恸哭六军俱缟素，冲冠一怒为红颜”出自清朝诗人吴伟业作品的《圆圆曲》。缟素：指吴三桂的军队为崇祯皇帝服丧。冲冠：发怒。这里指吴三桂为失去陈圆圆而发怒。"},{"id":726,"type":"单选题","text":"中国最古老的史书体裁是____。","options":[{"key":"A","text":"国别体"},{"key":"B","text":"编年体"},{"key":"C","text":"纪传体"},{"key":"D","text":"纪事本末体"}],"answer":["B"],"explanation":"编年体记录历史的方式最早起源于中国，是中国最古老的历史体裁，以年代为线索编排有关历史事件的史书体例。"},{"id":727,"type":"单选题","text":"“三国演义”中的“三英战吕布”的“三英”指的是____、关羽、张飞。","options":[{"key":"A","text":"马超"},{"key":"B","text":"诸葛亮"},{"key":"C","text":"赵云"},{"key":"D","text":"刘备"}],"answer":["D"],"explanation":"三英战吕布中的三英指的是刘备，关羽，张飞三人。"},{"id":728,"type":"单选题","text":"严复所说的“孔门四科”具体指德行、政事、文学和____。","options":[{"key":"A","text":"礼义"},{"key":"B","text":"孝悌"},{"key":"C","text":"言语"},{"key":"D","text":"忠义"}],"answer":["C"],"explanation":"后世学者将德行、政事、文学、言语，视为“孔门四科”。"},{"id":729,"type":"单选题","text":"中华文化源远流长，我国四大文化遗产分别为《明清档案》、《殷墟甲骨》、《居延汉简》、____。","options":[{"key":"A","text":"《二十四史》"},{"key":"B","text":"《敦煌经卷》"},{"key":"C","text":"《永乐大典》"},{"key":"D","text":"《四库全书》"}],"answer":["B"],"explanation":"四大文化遗产是指四本记录了中国历史的书籍，分别是《明清档案》、《殷墟甲骨》、《居延汉简》和《敦煌经卷》。"},{"id":730,"type":"单选题","text":"清代散文流派____主张“义理”、“考据”、“辞章”合而为一。其作品以山川游记、记事小品为佳，一些文论，影响较大。","options":[{"key":"A","text":"竟陵派"},{"key":"B","text":"公安派"},{"key":"C","text":"桐城派"},{"key":"D","text":"阳湖派"}],"answer":["C"],"explanation":"桐城派是中国清代文坛上最大的散文流派，亦称“桐城古文派”，世通称“桐城派”。主张“义理”、“考据”、“辞章”合而为一。"},{"id":731,"type":"单选题","text":"“不愤不启，不悱不发”中的____是想弄明白而弄不明白的意思。","options":[{"key":"A","text":"发"},{"key":"B","text":"愤"},{"key":"C","text":"悱"},{"key":"D","text":"启"}],"answer":["B"],"explanation":"愤：心里想弄明白可还是不明白。"},{"id":732,"type":"单选题","text":"科举中，会出现一人兼解元、会元、状元的“连中三元”，其分别是在____、会试、殿试考试中取得的。","options":[{"key":"A","text":"县试"},{"key":"B","text":"府试"},{"key":"C","text":"乡试"},{"key":"D","text":"院试"}],"answer":["C"],"explanation":"连中三元，汉语成语，意思是指接连在乡试、会试、殿试中考中了第一名。出自明·冯梦龙《警世通言》卷十八。"},{"id":733,"type":"单选题","text":"对乐府诗的分类，以郭茂倩的____最为完备。","options":[{"key":"A","text":"《玉台新咏》"},{"key":"B","text":"《乐府诗集》"},{"key":"C","text":"《文选》"},{"key":"D","text":"《全唐诗》"}],"answer":["B"],"explanation":"《乐府诗集》是北宋文学家郭茂倩编撰的上古至唐、五代的乐府诗歌总集，成书于北宋时期。每一类有总序，每一曲有题解，对乐曲的起源、性质、演唱配器等均有详尽说明。其中还保存了不少已失传著作的内容。"},{"id":734,"type":"单选题","text":"《汉书》的志尤为人们所重视。其中由《史记·平准书》演变而来的志被命名为____。","options":[{"key":"A","text":"《刑法志》"},{"key":"B","text":"《食货志》"},{"key":"C","text":"《地理志》"},{"key":"D","text":"《艺文志》"}],"answer":["B"],"explanation":"《食货志》是由《史记》的《平准书》演变来的，但有很大发展，内容也更加丰富了。"},{"id":735,"type":"单选题","text":"赵州桥是隋朝工匠____修建的。","options":[{"key":"A","text":"鲁班"},{"key":"B","text":"宇文恺"},{"key":"C","text":"李春"},{"key":"D","text":"喻皓"}],"answer":["C"],"explanation":"建于隋朝年间公元595年－605年，由著名匠师李春设计建造，距今已有1400多年的历史，是当今世界上现存第二早（还有一座小商桥）、保存最完整的古代单孔敞肩石拱桥。"},{"id":736,"type":"单选题","text":"中国大一统国家的形成，乃至两千多年的封建王朝历史，是从____开始的。","options":[{"key":"A","text":"秦始皇"},{"key":"B","text":"汉高祖"},{"key":"C","text":"汉武帝"},{"key":"D","text":"隋文帝"}],"answer":["A"],"explanation":"秦始王嬴政 公元前259～前210 秦始皇是一位伟大的中国皇帝。他在位期间（公元前238～前210），用武力统一了中国，实行了一系列影响广泛的改革。"},{"id":737,"type":"单选题","text":"陕西皮影戏的代表剧目是____。","options":[{"key":"A","text":"《哪吒闹海》"},{"key":"B","text":"《白毛女》"},{"key":"C","text":"《三打白骨精》"},{"key":"D","text":"《白蛇传》"}],"answer":["A"],"explanation":"皮影戏是中国汉族民间广为流传的傀儡戏之一，一门古老的汉族传统艺术。表演时，艺人们在白色幕布后面，一边用手操纵戏曲人物，一边用当地流行的曲调唱述故事，同时配以打击乐器和弦乐，有浓厚的乡土气息。在关中地区很为流行。皮影戏演出简便，表演领域广阔，演技细腻，活跃于广大农村，深受农民的欢迎。其代表作为《哪吒闹海》。"},{"id":738,"type":"单选题","text":"“蒹葭苍苍，白露为霜。所谓伊人，在水一方”中“蒹葭”是指____。","options":[{"key":"A","text":"芦苇"},{"key":"B","text":"水草"},{"key":"C","text":"荷花"},{"key":"D","text":"浮萍"}],"answer":["A"],"explanation":"蒹葭者，芦苇也，飘零之物，随风而荡，却止于其根，若飘若止，若有若无。思绪无限，恍惚飘摇，而牵挂于根。根者，情也。相思莫不如是。露之为物，瞬息消亡。"},{"id":739,"type":"单选题","text":"常用作表示第五位顺序的字是____。","options":[{"key":"A","text":"戎"},{"key":"B","text":"戍"},{"key":"C","text":"戊"},{"key":"D","text":"戌"}],"answer":["C"],"explanation":"戊，天干的第五位，用作顺序第五的代称。"},{"id":740,"type":"单选题","text":"文字是人类文明的重要标志，我国最古老的文字是____。","options":[{"key":"A","text":"隶书"},{"key":"B","text":"金文"},{"key":"C","text":"小篆"},{"key":"D","text":"甲骨文"}],"answer":["D"],"explanation":"中国迄今发现的最古老的比较成熟的文字是甲骨文，是刻在龟甲和兽骨上的文字。"},{"id":741,"type":"单选题","text":"宋史上最为后人所敬仰的状元当属南宋末年的____，他在国难之时，毁家纾难，无奈被俘，曾作“人生自古谁无死，留取丹心照汗青”，正义凛然，青史流芳。","options":[{"key":"A","text":"岳飞"},{"key":"B","text":"文天祥"},{"key":"C","text":"陆秀夫"},{"key":"D","text":"张世杰"}],"answer":["B"],"explanation":"出自《过零丁洋》作者文天祥。"},{"id":742,"type":"单选题","text":"故宫的三大殿是指太和殿、中和殿、保和殿，三大殿是封建皇帝行使权力或者举行盛典时用的宫殿。如果新皇帝要举行登基大典，一般会在____举行。","options":[{"key":"A","text":"太和殿"},{"key":"B","text":"中和殿"},{"key":"C","text":"保和殿"},{"key":"D","text":"乾清宫"}],"answer":["A"],"explanation":"太和殿俗称金銮殿，明清两朝皇帝都在太和殿举行盛大典礼，如皇帝登基即位、皇帝大婚、册立皇后、命将出征等。"},{"id":743,"type":"单选题","text":"俗语说“化干戈为玉帛”，干戈都是兵器，其中“干”指的是____。","options":[{"key":"A","text":"盾牌"},{"key":"B","text":"长矛"},{"key":"C","text":"大刀"},{"key":"D","text":"弓箭"}],"answer":["A"],"explanation":"“化干戈为玉帛”比喻消除仇怨，使战争转化为和平，使争吵转化为友好。干和戈是古代常用武器，“干”指盾牌，“戈”指用青铜或铁制成，装有长柄的武器。"},{"id":744,"type":"单选题","text":"《山海经》中“迷谷”指的是____。","options":[{"key":"A","text":"动物"},{"key":"B","text":"植物"},{"key":"C","text":"山谷"},{"key":"D","text":"神仙"}],"answer":["B"],"explanation":"《山海经》中迷谷是一种植物。"},{"id":745,"type":"单选题","text":"“勿以恶小而为之，勿以善小而不为。”语出三国志，出自____。","options":[{"key":"A","text":"孙权"},{"key":"B","text":"刘备"},{"key":"C","text":"曹操"},{"key":"D","text":"诸葛亮"}],"answer":["B"],"explanation":"“勿以恶小而为之，勿以善小而不为”，出自蜀汉昭烈帝刘备的诏书中。意思是不要因为是件较小的坏事就去做，不要因为是件较小的善事就毫不关心。"},{"id":746,"type":"单选题","text":"我国古代第一部文学评论专著是____。","options":[{"key":"A","text":"《沧浪诗话》"},{"key":"B","text":"《典论・论文》"},{"key":"C","text":"《诗品》"},{"key":"D","text":"《文心雕龙》"}],"answer":["D"],"explanation":"《文心雕龙》是中国现存最早的一部文章学论著，由于书中所论多涉及文学创作，故现代学者又多视之为现存最早的一部用中文撰写的综合性的文学批评专著。"},{"id":747,"type":"单选题","text":"我国古代诗人中流传下来的诗作数量第一的诗人是____。","options":[{"key":"A","text":"李白"},{"key":"B","text":"杜甫"},{"key":"C","text":"白居易"},{"key":"D","text":"陆游"}],"answer":["D"],"explanation":"我国古代诗人中流传下来的诗作数量第一的诗人是陆游。陆游具有多方面文学才能，尤以诗的成就为最，自言“六十年间万首诗”，存世有九千三百余首。"},{"id":748,"type":"单选题","text":"凤凰涅槃出自____先生的同名作品《凤凰涅槃》。","options":[{"key":"A","text":"巴金"},{"key":"B","text":"茅盾"},{"key":"C","text":"鲁迅"},{"key":"D","text":"郭沫若"}],"answer":["D"],"explanation":"凤凰涅槃一说出自于郭沫若先生同名作品，非中国古代传说，在中国古代神话传说中并无凤凰会浴火重生的说法。"},{"id":749,"type":"单选题","text":"西王母住在____山。","options":[{"key":"A","text":"蓬莱"},{"key":"B","text":"方丈"},{"key":"C","text":"瀛洲"},{"key":"D","text":"昆仑"}],"answer":["D"],"explanation":"西王母住在昆仑山。"},{"id":750,"type":"单选题","text":"“其鸣自叫也，见则其邑有讹火。”中的“讹火”指的是____。","options":[{"key":"A","text":"火山喷发"},{"key":"B","text":"闪电"},{"key":"C","text":"磷火"},{"key":"D","text":"火灾"}],"answer":["C"],"explanation":"讹火意思是指怪火，也指磷火。"},{"id":751,"type":"单选题","text":"与王建齐名，并称“张王乐府”的唐代诗人是____。","options":[{"key":"A","text":"张继"},{"key":"B","text":"张九龄"},{"key":"C","text":"张籍"},{"key":"D","text":"张若虚"}],"answer":["C"],"explanation":"张籍（约766年- 约830年），字文昌，和州乌江（今安徽和县乌江镇）人，唐代诗人，世称“张水部”、“张司业”。张籍为韩门大弟子，其乐府诗与王建齐名，并称“张王乐府”。"},{"id":752,"type":"单选题","text":"“刑天舞干戚”“女娲补天”“精卫填海”都是出自____。","options":[{"key":"A","text":"《淮南子》"},{"key":"B","text":"《山海经》"},{"key":"C","text":"《列子》"},{"key":"D","text":"《楚辞》"}],"answer":["B"],"explanation":"它们都出自《山海经》。"},{"id":753,"type":"单选题","text":"《山海经》现存共18篇，最早的版本由____（朝代）刘向刘歆父子校刊而成。","options":[{"key":"A","text":"东晋"},{"key":"B","text":"西汉"},{"key":"C","text":"东汉"},{"key":"D","text":"西晋"}],"answer":["B"],"explanation":"刘向、刘歆父子是西汉时期的人。"},{"id":754,"type":"单选题","text":"根据《史记》当中的记载，秦始皇姓____。","options":[{"key":"A","text":"赢"},{"key":"B","text":"赵"},{"key":"C","text":"秦"},{"key":"D","text":"吕"}],"answer":["B"],"explanation":"庄襄王为秦质子于赵，见吕不韦姬，悦而取之，生始皇。以秦昭王四十八年正月生于邯郸。及生，名为政，姓赵氏。"},{"id":755,"type":"单选题","text":"战国时期著名变法家商鞅姓____。","options":[{"key":"A","text":"公孙"},{"key":"B","text":"姬"},{"key":"C","text":"商"},{"key":"D","text":"卫"}],"answer":["B"],"explanation":"商鞅（约公元前390年－公元前338年），姬姓，公孙氏，名鞅，卫国人。"},{"id":756,"type":"单选题","text":"____是六国中最后灭亡的。","options":[{"key":"A","text":"燕国"},{"key":"B","text":"齐国"},{"key":"C","text":"楚国"},{"key":"D","text":"赵国"}],"answer":["B"],"explanation":"从公元前230年攻打韩国到前221年灭齐国结束，共计10年的时间，先后按顺序消灭韩、赵、魏、楚、燕、齐六国，结束了中国自春秋以来长达500多年的诸侯割据纷争的局面。"},{"id":757,"type":"单选题","text":"____的内容反映的历史时期是春秋时期。","options":[{"key":"A","text":"《史记》"},{"key":"B","text":"《国语》"},{"key":"C","text":"《左传》"},{"key":"D","text":"《战国策》"}],"answer":["C"],"explanation":"《左传》内容反映的历史时期是春秋时期。《左传》记叙了春秋时期250多年的历史，主要记录了周王室的衰微，诸侯争霸的历史，对各类礼仪规范、典章制度、社会风俗、民族关系、道德观念、天文地理、历法时令、古代文献、神话传说、歌谣言语均有记述和评论。"},{"id":758,"type":"单选题","text":"“花甲”是指____岁。","options":[{"key":"A","text":"五十"},{"key":"B","text":"六十"},{"key":"C","text":"七十"},{"key":"D","text":"八十"}],"answer":["B"],"explanation":"不满周岁——襁褓；\n2-3岁——孩提；\n7岁（女）——髫年；\n8岁（男）——龆年；\n幼年泛称——总角；\n10岁以下——黄口，即乃稚气未脱的少儿代称也；\n13岁（女）——豆蔻年华，\n15岁（女）——及笄之年；\n15岁（男）——志学之年；\n16岁（女）——破瓜年华、碧玉年华，二八年华；\n15~20岁——舞象之年；\n20岁（女）——桃李年华；\n20岁（男）——弱冠；\n30岁（女）——半老徐娘；\n30岁（男）——而立之年；\n40岁（男）——不惑之年、强壮之年；\n50岁——年逾半百、知非之年、知命之年、艾服之年、大衍之年；\n60岁——花甲、平头甲子、耳顺之年、杖乡之年、还历之年；\n70岁——古稀、杖国之年、致事之年、致政之年，从心之年、悬车之年；\n80~90岁——耄耋之年；\n100岁——期颐，又可称为“人瑞”。"},{"id":759,"type":"单选题","text":"“危局如斯敢惜身?愿将生命作牺牲”是女革命家秋瑾的豪迈诗篇。她在同盟会成立后领导的武装起义是____。","options":[{"key":"A","text":"浙皖起义"},{"key":"B","text":"黄花岗起义"},{"key":"C","text":"武昌起义"},{"key":"D","text":"萍浏醴起义"}],"answer":["A"],"explanation":"1907年，秋瑾与徐锡麟等组织光复军，拟于7月6日在浙江、安徽同时起义，事泄被捕。"},{"id":760,"type":"单选题","text":"“抛绣球、碰红蛋、抢花炮”是我国____歌圩节举行的活动。","options":[{"key":"A","text":"傣族"},{"key":"B","text":"壮族"},{"key":"C","text":"苗族"},{"key":"D","text":"彝族"}],"answer":["B"],"explanation":"壮族的歌圩节是壮族民间传统歌节，流行于广西、云南等地。在每年春、秋两季，尤其是三月三，要搭彩棚、摆歌台，举办唱山歌的歌圩。节日期间还举行抛绣球、碰红蛋、踢毽子、抢花炮等活动。"},{"id":761,"type":"单选题","text":"“八仙”之中手握芭蕉扇的是____。","options":[{"key":"A","text":"何仙姑"},{"key":"B","text":"铁拐李"},{"key":"C","text":"汉钟离"},{"key":"D","text":"吕洞宾"}],"answer":["C"],"explanation":"汉钟离，本名钟离权。又称为正阳祖师。法宝是芭蕉扇，此宝扇扇火火灭，扇水水潇，变化无穷，能遮天蔽日。"},{"id":762,"type":"单选题","text":"因写出《三都赋》而让大家竞相传写，导致洛阳纸贵的是____。","options":[{"key":"A","text":"王羲之"},{"key":"B","text":"潘岳"},{"key":"C","text":"陆机"},{"key":"D","text":"左思"}],"answer":["D"],"explanation":"“洛阳纸贵”原义是晋代左思《三都赋》写成之后，抄写的人非常多，洛阳的纸因此都涨价了；后比喻著作广泛流传，风行一时。"},{"id":763,"type":"单选题","text":"在我国有一座石窟又名“千佛洞”指的是____。","options":[{"key":"A","text":"云冈石窟"},{"key":"B","text":"龙门石窟"},{"key":"C","text":"麦积山石窟"},{"key":"D","text":"莫高窟"}],"answer":["D"],"explanation":"莫高窟又名“千佛洞”，现有洞窟735个，保存壁画4.5万多平方米，彩塑2400余尊，唐宋木构窟檐5座，是中国石窟艺术发展演变的一个缩影，在石窟艺术中享有崇高的历史地位。"},{"id":764,"type":"单选题","text":"凿壁偷光，勤学苦读的是____。","options":[{"key":"A","text":"孙敬"},{"key":"B","text":"苏秦"},{"key":"C","text":"车胤"},{"key":"D","text":"匡衡"}],"answer":["D"],"explanation":"凿壁偷光，是一个寓言故事演化而成的成语，出自《西京杂记》。该成语原指西汉匡衡凿穿墙壁引邻舍之烛光读书，后用来形容家贫而读书刻苦学习的事情。"},{"id":765,"type":"单选题","text":"在中国书法史上被誉为“草圣”的书法家是____。","options":[{"key":"A","text":"张旭"},{"key":"B","text":"怀素"},{"key":"C","text":"王羲之"},{"key":"D","text":"王献之"}],"answer":["A"],"explanation":"张旭,盛唐时期知名书法家,以狂草著名,被尊为“草圣”,唐文宗曾下诏称李商隐的诗、裴文的舞剑与戏法张旭的草书为“三绝”,代表作品有《古诗四帖》。"},{"id":766,"type":"单选题","text":"甲骨文，是中国的一种古老文字，又称“契文”、“甲骨卜辞”、殷墟文字或“龟甲兽骨文”。是汉字的早期形式，是现存中国王朝时期最古老的一种成熟文字，最早出土于河南省安阳市殷墟。历史上发现、收藏和研究甲骨文的第一人是____。","options":[{"key":"A","text":"王懿荣"},{"key":"B","text":"刘鹗"},{"key":"C","text":"罗振玉"},{"key":"D","text":"王国维"}],"answer":["A"],"explanation":"光绪二十五年（1899年），王懿荣因通晓医术在鹤年堂抓药时，买到一种叫龙骨的药材，对其上面的图形文字进行研究，并通过山东古董商人范维卿大量收购，王懿荣首次发现甲骨文，并将其断为商代。该发现轰动中外学术界，把汉字的历史推到公元前1700多年的殷商时代，成为甲骨文研究的奠基人。"},{"id":767,"type":"单选题","text":"弈秋是我国春秋时期著名的____老师。","options":[{"key":"A","text":"围棋"},{"key":"B","text":"象棋"},{"key":"C","text":"书法"},{"key":"D","text":"兵法"}],"answer":["A"],"explanation":"弈秋是第一个史上有记载的围棋专业棋手，也是史上第一个卜、卜徒父是也。此名弈秋，故知秋为其名，因通国皆谓之善弈，故以弈加名称之。"},{"id":768,"type":"单选题","text":"10世纪初（916年）契丹族首领____，统一契丹各部，建立契丹国（辽）。","options":[{"key":"A","text":"耶律阿保机"},{"key":"B","text":"耶律德光"},{"key":"C","text":"耶律隆绪"},{"key":"D","text":"耶律洪基"}],"answer":["A"],"explanation":"10世纪初，契丹族的杰出首领耶律阿保机统一了契丹各部，916年，他建立契丹政权，定都上京，今内蒙古巴林左旗南，后来改国号为辽。"},{"id":769,"type":"单选题","text":"古代宫殿大门前成对的石狮一般都是____。","options":[{"key":"A","text":"左雄右雌"},{"key":"B","text":"左雌右雄"},{"key":"C","text":"都是雄狮"},{"key":"D","text":"都是雌狮"}],"answer":["A"],"explanation":"在宫殿大门外一般都有一对石狮或铜狮，按建筑方位，古代宫殿大门前成对的石狮一般都是左雄右雌（石狮子在大门两口的摆放都是以人从大门里出来的方向为参照的），符合中国传统男左女右的阴阳哲学。"},{"id":770,"type":"单选题","text":"他擅篆、隶、真、行、草多种书体，在书法方面颇有造诣，推动了楷书的发展，被后世尊为“楷书鼻祖”，他就是____。","options":[{"key":"A","text":"钟繇"},{"key":"B","text":"王羲之"},{"key":"C","text":"欧阳询"},{"key":"D","text":"颜真卿"}],"answer":["A"],"explanation":"钟繇（锺繇）擅篆、隶、真、行、草多种书体，在书法方面颇有造诣，推动了楷书（小楷）的发展，对后世书法影响深远，后世尊为“楷书鼻祖”。"},{"id":771,"type":"单选题","text":"与黄培芳、谭敬昭并称为“粤东三子”的清代作家是____。","options":[{"key":"A","text":"张维屏"},{"key":"B","text":"梁启超"},{"key":"C","text":"康有为"},{"key":"D","text":"黄遵宪"}],"answer":["A"],"explanation":"粤东三子指清广东三诗人。“三子”受翁方纲诗论影响，以张维屏成就较大。出自《清史稿·文苑·张维屏传》：张维屏，字子树，番禺人。工诗，计偕入都，翁方纲尝异之。与黄培芳、谭敬昭，称粤东三子。"},{"id":772,"type":"单选题","text":"“东施效颦”中，东施效仿的是____。","options":[{"key":"A","text":"王昭君"},{"key":"B","text":"西施"},{"key":"C","text":"貂蝉"},{"key":"D","text":"杨玉环"}],"answer":["B"],"explanation":"故西施病心而矉（通‘顰’，皱眉）其里，其里之丑人见而美之，归亦捧心而矉其里。其里之富人见之，坚闭门而不出；贫人见之，絜（通‘挈’，带领）妻子而去之走。彼知颦美，而不知颦之所以美。（《庄子·天运》）。"},{"id":773,"type":"单选题","text":"在古代，“杵臼”是一种捣鼓粮食或____的工具。","options":[{"key":"A","text":"药物"},{"key":"B","text":"矿石"},{"key":"C","text":"金属"},{"key":"D","text":"木材"}],"answer":["A"],"explanation":"杵臼是在古代，是指用来鼓捣粮食或药物等的工具，是一个不可分离的器具。"},{"id":774,"type":"单选题","text":"中国的茶饮风俗源于____地区。","options":[{"key":"A","text":"浙江"},{"key":"B","text":"福建"},{"key":"C","text":"四川"},{"key":"D","text":"云南"}],"answer":["C"],"explanation":"四川茶文化源远流长，四川是我国饮茶和种植茶叶的最早的地区之一，我国最早有价值的文献，也恰巧出自四川文人之手。"},{"id":775,"type":"单选题","text":"杭州虎跑泉与龙井茶相配，被称为____。","options":[{"key":"A","text":"天下双绝"},{"key":"B","text":"江南双绝"},{"key":"C","text":"西湖双绝"},{"key":"D","text":"钱塘双绝"}],"answer":["C"],"explanation":"西湖龙井驰名中外，色绿、香郁、味醇；虎跑泉水天下第三泉，泉水甘洌醇厚、水质纯净，而龙井茶只有虎跑水才能泡出它独特的茶香，因此二者被世人合称为“西湖双绝”."},{"id":776,"type":"单选题","text":"文献表明，火药的利用最晚不迟于____代。","options":[{"key":"A","text":"宋"},{"key":"B","text":"元"},{"key":"C","text":"明"},{"key":"D","text":"唐"}],"answer":["D"],"explanation":"据文献记载,最迟在唐代火药已经被发现和利用。唐代孙思邈的《孙真人丹经》首次制做记载了制造火药的方法,接中是世界上才关于火药的最早记载。"},{"id":777,"type":"单选题","text":"历史上著名的“针灸铜人”是在北宋太医____的主持下制造的。","options":[{"key":"A","text":"孙思邈"},{"key":"B","text":"王惟一"},{"key":"C","text":"华佗"},{"key":"D","text":"张仲景"}],"answer":["B"],"explanation":"王惟一是北宋医家，对针灸学很有研究，集宋以前针灸之大成，著有《铜人腧穴针灸图经》一书。同时,他主持制造了外科铜人，作为学生练针的样本。"},{"id":778,"type":"单选题","text":"年少时，梦见所用之笔头上生花，后来名闻天下的是____。","options":[{"key":"A","text":"杜甫"},{"key":"B","text":"王维"},{"key":"C","text":"李白"},{"key":"D","text":"白居易"}],"answer":["C"],"explanation":"《开元天宝遗事·梦笔头生花》：“李太白少时，梦所用之笔头上生花，后天才赡逸，名闻天下。”"},{"id":779,"type":"单选题","text":"____是历史上著名的医学家，他发明的药剂“麻沸散”，具有全身麻醉的功能。","options":[{"key":"A","text":"李时珍"},{"key":"B","text":"孙思邈"},{"key":"C","text":"张仲景"},{"key":"D","text":"华佗"}],"answer":["D"],"explanation":"华佗东汉末年著名的医学家，与董奉和张仲景被并称为“建安三神医”。他精通内、外、妇、儿、针灸各科，对外科尤为擅长，发明了“麻沸散”来辅助外科手术，被后人称为“外科圣手”“外科鼻祖”。"},{"id":780,"type":"单选题","text":"现代京剧的行当有生、旦、净、丑四行，而昆曲则除此之外，还有____。","options":[{"key":"A","text":"末"},{"key":"B","text":"外"},{"key":"C","text":"贴"},{"key":"D","text":"杂"}],"answer":["A"],"explanation":"京剧并非源于北京的剧种,而是由南方入京的安徽徽调和湖北汉调吸收流行于北京的风行梆子、昆曲、京腔的营养,融会本地语言形成的剧种。京剧有生、旦、净、丑四大行当,而昆曲除此之外还有末。"},{"id":781,"type":"单选题","text":"____的发明源于古代道士的“炼丹术”。","options":[{"key":"A","text":"造纸术"},{"key":"B","text":"火药"},{"key":"C","text":"印刷术"},{"key":"D","text":"指南针"}],"answer":["B"],"explanation":"火药火枪是我国古代的四大发明之一,源于古代的炼丹术。据文献记载,最迟在唐代火药已经被发现和利用,唐代孙思邈的《孙真人丹经》首次记载了制造火药的方法,是世界上关于火药的最早记载。"},{"id":782,"type":"单选题","text":"在淝水之战中，“闻风声鹤唳，皆以为王师已至”的是谁？","options":[{"key":"A","text":"苻坚"},{"key":"B","text":"谢安"},{"key":"C","text":"谢玄"},{"key":"D","text":"慕容垂"}],"answer":["A"],"explanation":"淝水之战指的是前秦皇帝苻坚对东晋发动的战争，失败后在奔逃的路上，远处山上郁郁葱葱的树木被风吹得簌簌作响，高度紧张的前秦士兵以为那是晋军的追兵，越发拼命逃窜。"},{"id":783,"type":"单选题","text":"最早的印本书籍____是在莫高窟发现的。","options":[{"key":"A","text":"《金刚经》"},{"key":"B","text":"《道德经》"},{"key":"C","text":"《论语》"},{"key":"D","text":"《诗经》"}],"answer":["A"],"explanation":"我国和世界现存最早的有日期的雕版排印的书是《金刚经》，撕掉于唐咸通九年(868)。这卷举世闻名的《金刚经》，原藏于甘肃敦煌莫高窟，1899年被发现，1907年后被英国人斯坦因盗去，原藏伦敦不列颠博物馆。"},{"id":784,"type":"单选题","text":"国内仅存的一座帝王庙位于____的阜成门。","options":[{"key":"A","text":"洛阳市"},{"key":"B","text":"北京市"},{"key":"C","text":"西安市"},{"key":"D","text":"南京市"}],"answer":["B"],"explanation":"帝王庙是供奉祭祀上至伏羲、轩辕祖先，下至明、清各朝的历代帝王和名臣的场所，是我国唯一纪念历代帝王名臣的坛庙。帝王庙位于北京西城区阜成门内大街路北。"},{"id":785,"type":"单选题","text":"中国第一大佛是四川的____。","options":[{"key":"A","text":"乐山大佛"},{"key":"B","text":"峨眉山金顶佛像"},{"key":"C","text":"荣县大佛"},{"key":"D","text":"屏山大佛"}],"answer":["A"],"explanation":"乐山大佛，又名凌云大佛，是中国最大的石刻佛像。"},{"id":786,"type":"单选题","text":"中国最早的佛经是____。","options":[{"key":"A","text":"《四十二章经》"},{"key":"B","text":"《金刚经》"},{"key":"C","text":"《心经》"},{"key":"D","text":"《楞严经》"}],"answer":["A"],"explanation":"中国古代最早的佛经是在东汉时期的《四十二章经》，相传为摄摩腾摄摩腾和竺法兰所译，这是我国翻译梵文佛经的开始。"},{"id":787,"type":"单选题","text":"与“达赖”并称为黄教两大转世系统的称号是____。","options":[{"key":"A","text":"法王"},{"key":"B","text":"活佛"},{"key":"C","text":"班禅"},{"key":"D","text":"国师"}],"answer":["C"],"explanation":"“达赖”和“班禅”是黄教两大活佛转世系统的称号。达赖的称号始于三世达赖喇嘛锁南嘉错,前两世都是后来追认的。班禅的称号比达赖略晚。"},{"id":788,"type":"单选题","text":"中国建立的第一个王朝是____。","options":[{"key":"A","text":"周朝"},{"key":"B","text":"商朝"},{"key":"C","text":"夏朝"},{"key":"D","text":"秦朝"}],"answer":["C"],"explanation":"中国史书记载的第一个朝代是夏朝制。"},{"id":789,"type":"单选题","text":"江苏之名是其境内江宁与____两地的合称。","options":[{"key":"A","text":"苏州"},{"key":"B","text":"扬州"},{"key":"C","text":"无锡"},{"key":"D","text":"常州"}],"answer":["A"],"explanation":"江苏的名字是以江宁、苏州各取一字得名。清康熙6年(1667年)设江苏省,取两江总督驻所江宁(今南京市)和巡抚驻所苏州(今苏州市)两府首字组成江苏省。取全称中的“苏”字作为简称。"},{"id":790,"type":"单选题","text":"秦朝的国家行政机构分为中央、“____”和县三级。","options":[{"key":"A","text":"州"},{"key":"B","text":"路"},{"key":"C","text":"郡"},{"key":"D","text":"省"}],"answer":["C"],"explanation":"秦建立后废除分封制，在全国推行郡县制。郡是中央政府以下最高一级地方行政机构；县是郡的下级行政机构。郡守是郡的最高行政长官，对上承受中央命令，对下督责所属各县。郡守和县令都由皇帝直接任免，对中央负责。"},{"id":791,"type":"单选题","text":"甲骨文也称____。","options":[{"key":"A","text":"隶书"},{"key":"B","text":"小篆"},{"key":"C","text":"卜辞"},{"key":"D","text":"金文"}],"answer":["C"],"explanation":"记录商代的社会情况的文字主要是甲骨文，是刻在甲骨上的文字，都是商代王室占卜的记录，因而也称卜辞。"},{"id":792,"type":"单选题","text":"现存最早的天文台遗址在今天的河南洛阳市，古名为____。","options":[{"key":"A","text":"浑天仪"},{"key":"B","text":"司天台"},{"key":"C","text":"灵台"},{"key":"D","text":"观星台"}],"answer":["C"],"explanation":"灵台位于故城河南省洛阳市汉魏阳城南郊,由班固于东汉中元元年(56)主持修建,是历史文献最早的天文台遗址。据文献记载,灵台连续使用达二百五并建十余年,为我国古代天文学的发展作出了巨大贡献。"},{"id":793,"type":"单选题","text":"唐代出现的一种著名的陶器被称为____。","options":[{"key":"A","text":"青花瓷"},{"key":"B","text":"白瓷"},{"key":"C","text":"唐三彩"},{"key":"D","text":"青瓷"}],"answer":["C"],"explanation":"陶瓷业在唐朝有重要发展，越窑青瓷、邢窑白瓷和唐三彩最为有名，其中唐三彩造型美观，釉色绚丽，是世界工艺的珍品。"},{"id":794,"type":"单选题","text":"所谓先秦的诸子百家，实际上就是指儒、墨、____、道、阴阳、名家、纵横家、兵家、农家和杂家这几个门派及其代表人物。","options":[{"key":"A","text":"名"},{"key":"B","text":"农"},{"key":"C","text":"法"},{"key":"D","text":"杂"}],"answer":["C"],"explanation":"诸子百家是对先秦晚期总称学术思想派别的总称，主要包括儒、道、墨、法、阴阳、农、名、兵、纵横和杂家。诸子百家各自阐发立论，已经形成了学术争鸣的局面，对中国古代思想史产生了可贵的神话传说影响。"},{"id":795,"type":"单选题","text":"集宋代理学之大成的学者是____。","options":[{"key":"A","text":"朱熹"},{"key":"B","text":"程颢"},{"key":"C","text":"程颐"},{"key":"D","text":"张载"}],"answer":["A"],"explanation":"朱熹，字元晦、仲晦，南宋徽州婺源县（今江西省上饶市婺源县）人，生于福建路南剑州尤溪县（今福建省三明市尤溪县），南宋理学家，宋代理学集大成者。"},{"id":796,"type":"单选题","text":"藏传佛教又称____，是在我国西藏、青海、内蒙古等地区流传的佛教。","options":[{"key":"A","text":"喇嘛教"},{"key":"B","text":"禅宗"},{"key":"C","text":"华严宗"},{"key":"D","text":"净土宗"}],"answer":["A"],"explanation":"藏传佛教，又称藏语系佛教，或俗称喇嘛教，是指传入中国西藏的佛教分支。"},{"id":797,"type":"单选题","text":"史书上将中国古代帝王在京城外祭祀天地的仪式称为____。","options":[{"key":"A","text":"郊祭"},{"key":"B","text":"封禅"},{"key":"C","text":"庙祭"},{"key":"D","text":"社祭"}],"answer":["A"],"explanation":"古代帝王除了往泰山封禅、往汾阴祭典后土之外,祭祀天地的仪式还有庙祭和郊祭两种,这两种仪式都始于周代。其中,郊祭则是所指在京城外郊区祭祀天地,史书称“郊祭”。"},{"id":798,"type":"单选题","text":"现存最古老的宗祠是位于山西省闻喜县的____。","options":[{"key":"A","text":"裴氏祠"},{"key":"B","text":"孔庙"},{"key":"C","text":"孟庙"},{"key":"D","text":"关帝庙"}],"answer":["A"],"explanation":"素有“中华宰相村”房氏之称的裴柏村是裴氏宗祠所在地,裴氏祠堂原称晋公祠,建于唐贞观三年(629年),有前殿、后殿、状元坊、碑廊等,规模宏大,但屡遭兵燹,屡修屡毁。"},{"id":799,"type":"单选题","text":"殿试制度完善于____时期；进士考试始于隋炀帝时期；三甲发榜始于宋太宗时期。","options":[{"key":"A","text":"宋太祖"},{"key":"B","text":"唐太宗"},{"key":"C","text":"唐玄宗"},{"key":"D","text":"武则天"}],"answer":["A"],"explanation":"殿试为科举考试中最高的一种,由武则天创制,但尚未成定制,宋太祖时始为常制。隋炀帝进士科考试始于炀帝大业三年(607),采用分科考试的方法选拔官员,是科举制宣告形成的标志。宋太宗太平兴国八年(983)开始分类“三甲”发榜。"},{"id":800,"type":"单选题","text":"现存最早的类书是隋末虞世南的____。","options":[{"key":"A","text":"《永乐大典》"},{"key":"B","text":"《太平御览》"},{"key":"C","text":"《艺文类聚》"},{"key":"D","text":"《北堂书钞》"}],"answer":["D"],"explanation":"现存最早的类书是隋末虞世南编纂的《北堂书钞》。"},{"id":801,"type":"单选题","text":"在中国古代建筑史上，“汉三宫”和“唐三宫”非常著名，前者长乐宫、未央宫和建章宫；后者指____、大明宫、和兴庆宫。","options":[{"key":"A","text":"长乐宫"},{"key":"B","text":"阿房宫"},{"key":"C","text":"紫禁城"},{"key":"D","text":"太极宫"}],"answer":["D"],"explanation":"我国古代历史时期的“汉三宫”是指长乐宫、未央宫和建章宫。其中，东宫由秦代旧宫整修改建而成；未央宫是明清两代以前中国古代最大的宫殿,为汉高祖前半期萧何督建；建章宫为汉景帝下令修建。“唐三宫”是指太极宫、大明宫、兴庆宫，其中，太极宫是在隋朝大兴宫的基础上改建而成，其北门为玄武门；大明宫是唐太宗专为李渊避暑而建；兴庆宫于唐玄宗时期建造，唐玄宗和杨贵妃的故事绝大多数发生于此。"},{"id":802,"type":"单选题","text":"古代帝王陵寝通常包含____、陵园和地宫三部分。","options":[{"key":"A","text":"神道"},{"key":"B","text":"祭殿"},{"key":"C","text":"墓碑"},{"key":"D","text":"陵冢"}],"answer":["D"],"explanation":"陵寝是古代帝王的坟墓。帝王的坟墓造得如山陵般又高又大,故称为“陵”；“寝”是密序死者灵魂起居之所，此外还有子孙祭天的祭殿。陵寝的构成包括陵园、陵冢和地宫三部分。"},{"id":803,"type":"单选题","text":"中国古塔按照造型来分类，有____、密檐式、喇嘛式、花式和金刚宝座式五种。","options":[{"key":"A","text":"过街式"},{"key":"B","text":"覆钵式"},{"key":"C","text":"亭阁式"},{"key":"D","text":"楼阁式"}],"answer":["D"],"explanation":"塔源于印度的“浮屠”,用于收藏佛祖舍利,又称“舍利塔”，后用于藏经、埋葬，成为纪念性建筑。按照它的造型可分为：楼阁式、密檐式、喇嘛式、花式和夜叉宝座式。"},{"id":804,"type":"单选题","text":"古代乐器按演奏方法分为吹、拉、弹、打四类，按乐器的材料可分为____、石、土、木、匏、革、丝、竹八类。","options":[{"key":"A","text":"银"},{"key":"B","text":"铁"},{"key":"C","text":"铜"},{"key":"D","text":"金"}],"answer":["D"],"explanation":"乐器按照各自使用的物质材料分为八种类别：即金，石，土，革，丝，木，匏，竹，称为八音。乐器分为四类：吹，拉，弹，唱。"},{"id":805,"type":"单选题","text":"南宋数学家____提出的“大衍求一术”被国际数学界称为“中国剩余定理”。","options":[{"key":"A","text":"祖冲之"},{"key":"B","text":"秦九韶"},{"key":"C","text":"刘徽"},{"key":"D","text":"杨辉"}],"answer":["B"],"explanation":"秦九韶是南宋汉学家，于淳祐七年(1247)著成《数书九章》十八卷。这是一部极其重要的巨著，它总结了前人在开方中剖析所使用的列筹方法，将其整齐而又系统地应用到有理的高次方程或无理根的求解上去，其中的“大衍求一术”(一次同余组解法)在世界数学握有史上占有崇高的优势地位，被称为“中国剩余定理”。"},{"id":806,"type":"单选题","text":"著名的《四库全书总目提要》是著名学者____撰写的。","options":[{"key":"A","text":"戴震"},{"key":"B","text":"姚鼐"},{"key":"C","text":"方苞"},{"key":"D","text":"纪晓岚"}],"answer":["D"],"explanation":"《四库全书总目提要》简称四库全书总目、四库总目、四库提要，共二百卷，是中国清代纪昀等编纂的一部大型解题书目，是中国古典目录学方法的集大成者。"},{"id":807,"type":"单选题","text":"我国家庭教育的鼻祖是____。","options":[{"key":"A","text":"孔子"},{"key":"B","text":"孟子"},{"key":"C","text":"荀子"},{"key":"D","text":"朱熹"}],"answer":["A"],"explanation":"我国的始于家庭教育最早始于西周时期，孔子是家庭教育的泰斗，尽管在他的论述中关于基础教育家庭教育的不是很多，但是我们仍然可以从中汲取智慧。他重视家庭中的起始教育，强调诚信与威严，将忠孝思想也渗透到家庭教育的思想之中，为后世传统基础教育理念的形成奠定了基础。"},{"id":808,"type":"单选题","text":"中国历史上正式设立的太学是在____时期。","options":[{"key":"A","text":"汉文帝"},{"key":"B","text":"汉武帝"},{"key":"C","text":"秦始皇"},{"key":"D","text":"汉高祖"}],"answer":["B"],"explanation":"太学是中国古代的的一种大学，始设于汉武帝元朔五年。"},{"id":809,"type":"单选题","text":"明清时，殿试的地点均在北京故宫的____殿。","options":[{"key":"A","text":"太和殿"},{"key":"B","text":"保和殿"},{"key":"C","text":"中和殿"},{"key":"D","text":"乾清宫"}],"answer":["B"],"explanation":"殿试又称御试、廷试、廷对，殿试为科举考试中的最高一段，由皇帝亲自出题考试，明清时，科举殿试的地点均在北京故宫保和殿。"},{"id":810,"type":"单选题","text":"《四书章句集注》是____从《礼记》中摘出《大学》和《中庸》两篇，合《论语》和《孟子》注释而成。","options":[{"key":"A","text":"董仲舒"},{"key":"B","text":"朱熹"},{"key":"C","text":"程颢"},{"key":"D","text":"程颐"}],"answer":["B"],"explanation":"南宋理学家，程朱理学集大成者。朱熹历高宗、孝宗、光宗、甯宗四朝。他总结了宋代理学思想，建立了庞大的理学体系，开创了紫阳学派。他还在建阳云谷“晦庵”草堂讲学，并校订了四书，成为后代科举应试科目。"},{"id":811,"type":"单选题","text":"大运河北起北京，南到杭州，故又称____，全长2400多公里，全面修建于隋炀帝时期，是世界上开凿最早、规模最大、里程最长的内陆运河，曾经与万里长城并称于世。","options":[{"key":"A","text":"通济渠"},{"key":"B","text":"京杭大运河"},{"key":"C","text":"浙东运河"},{"key":"D","text":"隋唐大运河"}],"answer":["B"],"explanation":"京杭大运河是“大运河”的一条干线，位于中国东部。它被列为世界文化遗产，是“南水北调”东线工程，也是世界上里程最长、工程最大和最古老的运河之一，与长城、坎儿井并称为中国古代的三项伟大工程，使用至今。"},{"id":812,"type":"单选题","text":"《本草纲目》的作者是____。","options":[{"key":"A","text":"孙思邈"},{"key":"B","text":"李时珍"},{"key":"C","text":"华佗"},{"key":"D","text":"张仲景"}],"answer":["B"],"explanation":"《本草纲目》是李时珍所著的集中国16世纪前本草学大成的中医典籍，该著作吸收了之前的草本书籍的精华，纠正了前人很多错误的地方，而且更是增加了数百种药物草本，有很多新的发现和突破，是中国历史上1600年以前最完整、最科学的一部医学著作。"},{"id":813,"type":"单选题","text":"现存的古碑荟萃之地，著名的有两处：第一位是____碑林；第二位是曲阜的孔庙碑林。","options":[{"key":"A","text":"南京"},{"key":"B","text":"开封"},{"key":"C","text":"西安"},{"key":"D","text":"洛阳"}],"answer":["C"],"explanation":"长方形者为碑，上圆而下方者为碣，合称“碑碣”。碑碣起源于先秦的无字碑（宫碑、丰碑和庙碑），墓前丰碑到秦汉演变为纪念性建筑；东汉时立碑刻字成为风气，用于歌功颂德、宣扬门阀；隋唐更甚，始立庙中，往往留存大量书法真迹。现存的古碑集中地主要有两处：西安碑林，位于陕西省西安市，为中国第一碑刻艺术宝库；孔庙碑林，位于山东省曲阜市，仅次于西安碑林，为中国第二碑林。"},{"id":814,"type":"单选题","text":"南宋四大书院中，由朱熹主持的是白鹿洞书院；由陆九渊主持的是象山书院；由吕祖谦主持的是丽泽书院；由张栻主持的是____。","options":[{"key":"A","text":"嵩阳书院"},{"key":"B","text":"应天书院"},{"key":"C","text":"石鼓书院"},{"key":"D","text":"岳麓书院"}],"answer":["D"],"explanation":"朱熹、吕祖谦、张栻和江西学派的陆九渊是南宋时期四位著名的理学家,他们主持的白鹿洞书院、丽泽书院、岳麓书 院、象山书院,世称南宋四大书院。"},{"id":815,"type":"单选题","text":"北京的“三海”也是著名的园林建筑，指的是____、中海、南海。","options":[{"key":"A","text":"东海"},{"key":"B","text":"北海"},{"key":"C","text":"西海"},{"key":"D","text":"前海"}],"answer":["B"],"explanation":"三海，即北海、中海、南海的合称，位于北京城内故宫和景山的西侧，明、清时期称为西苑。它是中国现存历史悠久、规模宏大、布置精美的宫苑之一"},{"id":816,"type":"单选题","text":"“四君子”指的是梅、兰、竹、____四种植物","options":[{"key":"A","text":"荷"},{"key":"B","text":"菊"},{"key":"C","text":"松"},{"key":"D","text":"柏"}],"answer":["B"],"explanation":"明代黄凤池辑有《梅竹兰菊四谱》，从此，梅、兰、竹、菊被称为“四君子”，世人常用“四君子”来寓意圣人高尚的品德。“四君子”是中国传统文化的题材，以梅、兰、竹、菊谓四君子，他们分别是指：梅花、兰花、翠竹、菊花。被人称为“四君子”，其品质分别是：傲、幽、澹、逸。“花中四君子”成为中国人借物喻志的象征，也是咏物诗文和艺人字画中常见的题材。其文化寓意为：梅，探波傲雪，高洁志士；兰，深谷幽香，世上贤达；竹，清雅澹泊，谦谦君子；菊，凌霜飘逸 ，世外隐士。他们都没有媚世之态、遗世而独立。在四君子之中而唯有梅花被古人的智慧创作出“梅花篆字”。"},{"id":817,"type":"单选题","text":"梅花的五瓣在传统文化中被比喻为寿、福、康宁、好德、善终，被称为____。","options":[{"key":"A","text":"人生五福"},{"key":"B","text":"五福临门"},{"key":"C","text":"五福捧寿"},{"key":"D","text":"五福同享"}],"answer":["A"],"explanation":"梅耐严寒,报春早,有清香,姿态秀雅,节操凝重,为文人雅士所垂青。梅花有五瓣,象征着寿、福、康宁、好德、善终的人生五福。"},{"id":818,"type":"单选题","text":"迄今发现的最早、最大、保存最好的古代都城遗址是河南偃师市发现的，它被认为是____早期都城遗址。","options":[{"key":"A","text":"商代"},{"key":"B","text":"夏代"},{"key":"C","text":"周代"},{"key":"D","text":"秦代"}],"answer":["A"],"explanation":"古代的大城市称作城池,“城”指城墙,“池”指城外环绕城墙的河池,俗称“护城河”。河南偃师周代都城遗址是迄今我国发现年代最早、规模最大、保存最难的古代都城遗址,属于商代早期城址,旧都传统上认为它就是商代的都城“西亳”。"},{"id":819,"type":"单选题","text":"有“东南名园之冠”美誉的园林是____。","options":[{"key":"A","text":"上海豫园"},{"key":"B","text":"苏州拙政园"},{"key":"C","text":"苏州留园"},{"key":"D","text":"扬州个园"}],"answer":["A"],"explanation":"豫园位于上海市中心的黄浦区,是明朝时期的私人湖畔,建于1559年。园内建筑设计精巧、布局细腻,以清幽秀丽、玲珑剔透见长,具有小中见大的特点,充分展现了中国园林的建筑与设计风格,是嘉兴园林中的一颗明珠,被誉为“东南名园之冠”。"},{"id":820,"type":"单选题","text":"中国书画史上，被称为“画圣”的是唐代的吴道子；被称为“书圣”的是晋代的____。","options":[{"key":"A","text":"王羲之"},{"key":"B","text":"王献之"},{"key":"C","text":"颜真卿"},{"key":"D","text":"欧阳询"}],"answer":["A"],"explanation":"吴道子是唐代第一大画家,被后世尊称为“画圣”,他一生主要包括创作壁画,作品数量惊人,代表作品有《天王送子图》《八十七神仙卷》,孔庙的镇庙之宝《孔子行教像》;王羲之是晋代著名书法家,他博采众长,自辟蹊径,自成一体,被誉为“书圣”,代表作品有《兰亭集序》。"},{"id":821,"type":"单选题","text":"中国画史上东晋时期____因才绝、画绝和痴绝被称为“三绝”，后来人们又把诗、书、画达到很高的造诣称为“三绝”。","options":[{"key":"A","text":"顾恺之"},{"key":"B","text":"陆探微"},{"key":"C","text":"张僧繇"},{"key":"D","text":"吴道子"}],"answer":["A"],"explanation":"东晋时的顾恺之帛画是人物画大师,以才绝、画绝、痴绝被称为“三绝”。“才绝”是说他才华横溢,“画绝”是说他画技高超,“痴绝”是说他做人太痴。他精通画论,提出“迁想妙得”“以形写神”等著名论点,对中国绘画的国际化发展有深远影响,其传世作品有碑帖《洛神赋图》《列女仁智图》。"},{"id":822,"type":"单选题","text":"秦代以后陆续修过的长城的王朝有10个，其中以汉、____两代规模最大。","options":[{"key":"A","text":"元"},{"key":"B","text":"唐"},{"key":"C","text":"明"},{"key":"D","text":"宋"}],"answer":["C"],"explanation":"战国时期，秦、燕、赵北邻匈奴，各自筑城自卫，但没有相连，其他诸国也在各自边界筑城。秦始皇统一中国后，派蒙恬、扶苏将原有秦、燕、赵三国长城连为一体，形成我们熟知的“万里长城”。在秦以后，共有十个王朝修建长城，以汉代和明代规模最大。"},{"id":823,"type":"单选题","text":"历史上的著名灭佛事件被称为“三武一宗”，指的是____、北周武帝、唐武宗和周世宗这四个皇帝。","options":[{"key":"A","text":"北魏孝文帝"},{"key":"B","text":"隋文帝"},{"key":"C","text":"北魏太武帝"},{"key":"D","text":"隋炀帝"}],"answer":["C"],"explanation":"“三武灭佛”，指的是北魏太武帝灭佛、北周武帝灭佛、唐武宗灭佛这三次事件的合称。这些在位者的谥号或庙号都带有个武字。若加上后周世宗时的灭佛则合称为“三武一宗灭佛”。"},{"id":824,"type":"单选题","text":"现代藏传佛教多属“黄教”，其创始人就是著名的____。","options":[{"key":"A","text":"班禅额尔德尼"},{"key":"B","text":"达赖喇嘛"},{"key":"C","text":"宗喀巴"},{"key":"D","text":"八思巴"}],"answer":["C"],"explanation":"宗喀巴（1357年-1419年10月25日），本名罗桑扎巴，13岁时在夏琼寺出家，青海湟中县人，藏传佛教格鲁派（黄教）创立者、佛教理论家，被藏族人尊称为第二佛陀。他的著述极多，重要著作有《密宗戒注释成就穗》《囊则敬寺所说比丘学处》《金刚持道次第秘密枢要解》等。在中国西藏、青海、内蒙、北京等地区的喇嘛寺院里，均设有宗喀巴塑像。宗喀巴于明代永乐十七年（公元1419年10月25日）在拉萨甘丹寺圆寂，享年63岁。"},{"id":825,"type":"单选题","text":"六经也称“六艺”，是经过孔子删定向弟子讲授的教材，它实际上指的是后世所说的“五经”和后来失传的____。","options":[{"key":"A","text":"《尚书》"},{"key":"B","text":"《诗经》"},{"key":"C","text":"《易经》"},{"key":"D","text":"《乐经》"}],"answer":["D"],"explanation":"六经是暗指经过孔子整理而经学传授的六部先秦古藉,它们是《诗经》《尚书》《仪礼》《乐经》《周易》《春秋》。其中《乐经》已失传,所以通常又称“五经”。"},{"id":826,"type":"单选题","text":"中国文化遗产的标志是太阳鸟金箔，中国旅游的标志是____。","options":[{"key":"A","text":"兵马俑"},{"key":"B","text":"长城"},{"key":"C","text":"故宫"},{"key":"D","text":"马踏飞燕"}],"answer":["D"],"explanation":"太阳鸟金箔2001年出土于四川成都金沙遗址。2005年08月17日,国家文物局国家文物局正式公布采行成都金沙“四鸟绕日”(太阳神鸟)金饰图案为“中国文化遗产标志”。马踏飞燕又称铜奔马,是东汉青铜器,1969年出土于甘肃省武威雷台墓。马踏飞燕自出土文物以来一直被视为中国古代高超铸造业的铸造业象征,1983年被确定为中国旅游标志。"},{"id":827,"type":"单选题","text":"针灸是根据中医的_______理论刺激特定穴位的治疗方法，其疗效在国际上已得到公认。","options":[{"key":"A","text":"脏腑"},{"key":"B","text":"气血"},{"key":"C","text":"阴阳"},{"key":"D","text":"经络"}],"answer":["D"],"explanation":"针灸治病，是直接作用于腧穴，通过经络的传导和反应，来调整人体的营卫气血和脏腑功能恢复体内阴阳的相对平衡，以达到治愈疾病的目的。"},{"id":828,"type":"单选题","text":"2006年5月，经国务院批准，未被列入第一批国家级非物质文化遗产名录的民俗节日有：____、七夕节、重阳节等。","options":[{"key":"A","text":"春节"},{"key":"B","text":"清明节"},{"key":"C","text":"中秋节"},{"key":"D","text":"腊八节"}],"answer":["D"],"explanation":"2006年5月，经国务院批准，被列入第一批国家级非物质文化遗产名录的民俗节日有：春节、清明节、端午节、中秋节、七夕节、重阳节等。"},{"id":829,"type":"单选题","text":"唐朝是我国饮茶历史上的鼎盛时期，流行于唐朝的饮茶方式不包括____？","options":[{"key":"A","text":"煎茶"},{"key":"B","text":"庵茶"},{"key":"C","text":"点茶"},{"key":"D","text":"煮茶"}],"answer":["C"],"explanation":"宋代流行点茶。"},{"id":830,"type":"单选题","text":"几千年来，中国人制造陶瓷，使用陶瓷，陶瓷文化已经融入中国人生活的方方面面。下列选项中，属于陶瓷的有____。","options":[{"key":"A","text":"四羊方尊"},{"key":"B","text":"莲鹤方壶"},{"key":"C","text":"后母戊鼎"},{"key":"D","text":"三彩胡人背猴骑俑"}],"answer":["D"],"explanation":"ABC项都属于青铜器。"},{"id":831,"type":"单选题","text":"中国地形多样，人们因地制宜，建造出适合自己的房屋,组成了丰富多彩的中式民居。以下地区与住房搭配不正确的有____。","options":[{"key":"A","text":"北京--四合院"},{"key":"B","text":"内蒙古--窑洞"},{"key":"C","text":"山西--大院"},{"key":"D","text":"福建--土楼"}],"answer":["B"],"explanation":"B项窑洞主要分布于黄土高原上，是当地居民的传统居住场所。"},{"id":832,"type":"单选题","text":"东汉时期张衡发明的水运浑象仪，巧妙地把计量时间用的____与____结合起来，以水流做动力，推动仪器模拟天体运行情况。","options":[{"key":"A","text":"日晷—浑象"},{"key":"B","text":"漏刻—浑象"},{"key":"C","text":"圭表—浑象"},{"key":"D","text":"沙漏—浑象"}],"answer":["B"],"explanation":"水运浑象仪的核心是将计量时间的装置与模拟天体运行的浑象结合。漏刻是古代常见的计时工具，通过水流的滴漏来计量时间，张衡利用漏刻的水流作为动力，驱动浑象旋转，模拟天体运行，B 选项正确。日晷通过太阳影子计时，圭表通过测量日影长度确定节气和时间，沙漏虽也是计时工具，但在张衡的水运浑象仪中，主要结合的是漏刻，而非日晷、圭表或沙漏，故正确答案为 B。"},{"id":833,"type":"单选题","text":"泰山的每一处都蕴含着悠久的历史和丰富的文化。以下不是位于泰山的古建筑有____。","options":[{"key":"A","text":"王母池"},{"key":"B","text":"万仙楼"},{"key":"C","text":"百尺峡"},{"key":"D","text":"碧霞祠"}],"answer":["C"],"explanation":"“百尺峡”也叫“百丈崖”，是华山的险境之一。"},{"id":834,"type":"单选题","text":"自古以来，黄河常常是诗人吟咏的对象。下列关于黄河的诗句与其作者对应不正确的有____。","options":[{"key":"A","text":"黄河之水天上来，奔流到海不复回--李白"},{"key":"B","text":"九曲黄河万里沙，浪淘风簸自天涯--刘禹锡"},{"key":"C","text":"黄河落天走东海。万里写人胸怀间--王维"},{"key":"D","text":"白日依山尽，黄河人海流--王之涣"}],"answer":["C"],"explanation":"黄河落天走东海，万里写入胸怀间出自李白的《赠裴十四》。"},{"id":835,"type":"单选题","text":"北岳恒山的悬空寺称得上是天下独绝，寺中同时供奉着佛、道、儒三家的始祖,他们分别是____。","options":[{"key":"A","text":"释迦牟尼、老子、孔子"},{"key":"B","text":"耶稣、老子、孔子"},{"key":"C","text":"释迦牟尼、庄子、孟子"},{"key":"D","text":"释迦牟尼、老子、孟子"}],"answer":["A"],"explanation":"佛教的始祖是释迦牟尼，道教的始祖是老子（李耳），儒家的始祖是孔子（孔丘），悬空寺作为三教合一的独特建筑，供奉的正是这三位始祖。"},{"id":836,"type":"单选题","text":"益者三友是____。","options":[{"key":"A","text":"友直、友谅、友多闻"},{"key":"B","text":"友便辟、友善柔、友便佞"},{"key":"C","text":"友仁、友义、友礼"},{"key":"D","text":"友智、友信、友勇"}],"answer":["A"],"explanation":"益者三友指友直，友谅，友多闻的朋友（友直是指正直的朋友，友谅是指诚信（谅，诚信）的朋友，友多闻是指见闻广博的朋友）。"},{"id":837,"type":"单选题","text":"西湖是中国著名的风景区，有着浓厚的历史文化气息，下列选项中不属于西湖古时旧称的有____。","options":[{"key":"A","text":"上湖"},{"key":"B","text":"钱塘湖"},{"key":"C","text":"西子湖"},{"key":"D","text":"重湖"}],"answer":["D"],"explanation":"重湖是洞庭湖的旧称。"},{"id":838,"type":"单选题","text":"彝族刺绣历史悠久，颜色以____为主。","options":[{"key":"A","text":"黑、红、黄"},{"key":"B","text":"黑、白、蓝"},{"key":"C","text":"红、绿、蓝"},{"key":"D","text":"红、黄、绿"}],"answer":["A"],"explanation":"彝族刺绣在色彩运用上具有鲜明的民族特色，传统上以黑、红、黄三种颜色为主。黑色象征大地和庄重，红色象征火焰、生命和热情，黄色象征太阳和光明，这三种颜色的搭配体现了彝族对自然和生活的认知，A 选项正确。其他选项中的颜色组合并非彝族刺绣的主流颜色，故正确答案为 A。"},{"id":839,"type":"单选题","text":"玉在我国古代具有十分深刻的寓意和文化内涵，人们认为玉拥有美好品质不包括____？","options":[{"key":"A","text":"仁"},{"key":"B","text":"利"},{"key":"C","text":"智"},{"key":"D","text":"洁"}],"answer":["B"],"explanation":"在《管子·水地》中，管仲认为玉有九种美德，分别为“仁、知、义、行、洁、勇、精、容、辞”。"},{"id":840,"type":"单选题","text":"象脚鼓的用料十分讲究，鼓身木料选用___，这样不容易开裂损坏","options":[{"key":"A","text":"梧桐木"},{"key":"B","text":"桦木"},{"key":"C","text":"椿木"},{"key":"D","text":"芒果木"}],"answer":["D"],"explanation":"象脚鼓是傣族等少数民族的重要乐器，其鼓身木料的选择尤为关键。芒果木质地坚硬、纹理细密，且具有较好的防潮性和稳定性，不易开裂损坏，是制作象脚鼓鼓身的传统优选材料，D 选项正确。梧桐木常用于制作古琴等乐器；桦木、椿木虽也是常见木材，但在象脚鼓制作中并非主流选用木料，故正确答案为 D。"},{"id":841,"type":"单选题","text":"下列选项中不属于怒江傈僳族自治州独特技艺的有____。","options":[{"key":"A","text":"“上刀山，下火海”技艺"},{"key":"B","text":"起奔乐器制作技艺"},{"key":"C","text":"柳溪竹雕制作技艺"},{"key":"D","text":"独龙族竹编技艺"}],"answer":["C"],"explanation":"柳溪竹雕制作技艺是云南省昭通市彝良县的·竹雕技艺。"},{"id":842,"type":"单选题","text":"藏族传统金属铸造工艺源远流长，不会采用以___为熔模材料的铸造方法。","options":[{"key":"A","text":"羊油"},{"key":"B","text":"松香"},{"key":"C","text":"檀香"},{"key":"D","text":"蜂蜡"}],"answer":["C"],"explanation":"檀香主要分布于广东、广西、海南、云南、福建等地区，并非藏族地区常见的熔模材料。"},{"id":843,"type":"单选题","text":"战国时期著名的思想家韩非在《韩非子》中提出____、____、____相结合的法治主张。","options":[{"key":"A","text":"仁、义、礼"},{"key":"B","text":"道、法、术"},{"key":"C","text":"法、礼、智"},{"key":"D","text":"法、术、势"}],"answer":["D"],"explanation":"韩非子结合商鞅、申不害、慎道三位前辈的思想，在其老师荀子之性恶论的基础上，提出了“法、术、势”的治国思想。"},{"id":844,"type":"单选题","text":"“损者三友”不包括____。","options":[{"key":"A","text":"友酒肉"},{"key":"B","text":"友便辟"},{"key":"C","text":"友善柔"},{"key":"D","text":"友便佞"}],"answer":["A"],"explanation":"孔子曰：“益者三友，损者三友。友直，友谅，友多闻，益矣。友便辟，友善柔，友便佞，损矣。”孔子说：“有益的朋友有三种，有害的朋友有三种。同正直的人交友，同诚信的人交友，同见闻广博的人交友，是有益的。同逢迎谄媚的人交友，同表面柔顺而内心奸诈的人交友，同花言巧语的人交友，是有害的。”"},{"id":845,"type":"单选题","text":"古人倡导的“三不朽”不包括以下哪个？","options":[{"key":"A","text":"立德"},{"key":"B","text":"立志"},{"key":"C","text":"立功"},{"key":"D","text":"立言"}],"answer":["B"],"explanation":"三不朽， 指立德、立功、立言。"},{"id":846,"type":"单选题","text":"以下选项中不属于“晚清四大名臣”的是____。","options":[{"key":"A","text":"张之洞"},{"key":"B","text":"袁世凯"},{"key":"C","text":"李鸿章"},{"key":"D","text":"左宗棠"}],"answer":["B"],"explanation":"晚清四大名臣分别为：曾国藩、左宗棠、李鸿章、张之洞。"},{"id":847,"type":"单选题","text":"下列成语典故中，出自《庄子》的除了____？","options":[{"key":"A","text":"邯郸学步"},{"key":"B","text":"东施效颦"},{"key":"C","text":"井底之蛙"},{"key":"D","text":"五十步笑百步"}],"answer":["D"],"explanation":"五十步笑百步是一则来源于寓言故事的成语，成语有关典故最早见于《孟子·梁惠王上》。"},{"id":848,"type":"单选题","text":"孟子在《生于忧患，死于安乐》一文中，在开头列举了一系列历史人物，这些历史人物不包括____。","options":[{"key":"A","text":"舜"},{"key":"B","text":"大禹"},{"key":"C","text":"管仲"},{"key":"D","text":"百里奚"}],"answer":["B"],"explanation":"《生于忧患，死于安乐》中孟子举了舜、傅说、胶鬲、管夷吾、孙叔敖、百里奚六位名人的事例，得出困境出人才的结论。"},{"id":849,"type":"单选题","text":"《大道之行也》的“矜、寡、孤、独、废疾者皆有所养”一句中，以下理解正确的是____。","options":[{"key":"A","text":"“矜” 指老而无子的人，“寡” 指幼而无父的人"},{"key":"B","text":"“孤” 指老而无妻的人，“独” 指老而无夫的人"},{"key":"C","text":"“废疾者” 指身体残疾、无法劳动的人"},{"key":"D","text":"该句体现了封建社会的等级制度"}],"answer":["C"],"explanation":"在 “矜、寡、孤、独、废疾者” 中，“矜”（通 “鳏”）指老而无妻的人，“寡” 指老而无夫的人，“孤” 指幼而无父的人，“独” 指老而无子的人，A、B 选项对 “孤” 和 “独” 的理解颠倒，错误；“废疾者” 指身体残疾、丧失劳动能力的人，C 选项正确；该句描绘的是 “大同社会” 中人人都能得到供养的理想景象，体现的是平等、互助的理念，而非封建社会的等级制度，D 选项错误。"},{"id":850,"type":"单选题","text":"《诗经》是我国第一部诗歌总集，其主要不包括哪个部分？","options":[{"key":"A","text":"“风”"},{"key":"B","text":"“雅”"},{"key":"C","text":"“言”"},{"key":"D","text":"“颂”"}],"answer":["C"],"explanation":"《诗经》是中国最早的诗歌总集，收集了地方乐调、西周王畿的乐调及祭祀用的宗教音乐，分别被称为“风、雅、颂”。"},{"id":851,"type":"单选题","text":"下列诗句中，表现送别时朋友之间深厚情谊的不包括以下____？","options":[{"key":"A","text":"但愿人长久，千里共婵娟"},{"key":"B","text":"洛阳亲友如相问，一片冰心在玉壶"},{"key":"C","text":"劝君更尽一杯酒，西出阳关无故人"},{"key":"D","text":"桃花潭水深千尺，不及汪伦送我情"}],"answer":["A"],"explanation":"“但愿人长久，千里共婵娟”出自苏轼写给弟弟的《水调歌头》，常用于表达对远方亲人的思念之情以及美好祝愿。"},{"id":852,"type":"单选题","text":"下列选项中，属于老子思想主张的有____。","options":[{"key":"A","text":"“仁者爱人”"},{"key":"B","text":"“无为而治”"},{"key":"C","text":"“制天命而用之”"},{"key":"D","text":"“兼爱、非攻”"}],"answer":["B"],"explanation":"老子是道家学派的创始人，其思想核心是 “道”，主张 “无为而治”，即统治者不过多干预，让事物自然发展，以达到社会和谐稳定，B 选项正确。“仁者爱人” 是孔子的儒家思想主张；“制天命而用之” 是荀子的思想，强调人可以利用自然规律；“兼爱、非攻” 是墨子的墨家思想主张，A、C、D 选项错误。"},{"id":853,"type":"单选题","text":"下列选项中，被称为“吴中四士”的除了以下____？","options":[{"key":"A","text":"贺知章"},{"key":"B","text":"张旭"},{"key":"C","text":"包融"},{"key":"D","text":"徐凝"}],"answer":["D"],"explanation":"“吴中四士”包括张若虚、贺知章、张旭和包融"},{"id":854,"type":"单选题","text":"欧阳修是北宋著名文学家，后人将他和____、____、____并称“千古文章四大家”。","options":[{"key":"A","text":"韩愈、柳宗元、苏轼"},{"key":"B","text":"李白、杜甫、白居易"},{"key":"C","text":"王安石、苏轼、苏辙"},{"key":"D","text":"韩愈、柳宗元、王安石"}],"answer":["A"],"explanation":"“千古文章四大家” 是指在散文创作上成就卓著的四位文学家，分别是唐代的韩愈、柳宗元和宋代的欧阳修、苏轼。"},{"id":855,"type":"单选题","text":"元代时期出现了很多优秀的杂剧家和曲作家，其中未被誉为“元曲四大家”的有____。","options":[{"key":"A","text":"马致远"},{"key":"B","text":"王实甫"},{"key":"C","text":"白朴"},{"key":"D","text":"郑光祖"}],"answer":["B"],"explanation":"“元曲四大家”包括关汉卿，马致远，郑光祖，白朴。"},{"id":856,"type":"单选题","text":"下列作品中，未被称为“元代四大爱情剧”的是____。","options":[{"key":"A","text":"《拜月亭》"},{"key":"B","text":"《西厢记》"},{"key":"C","text":"《汉宫秋》"},{"key":"D","text":"《倩女离魂》"}],"answer":["C"],"explanation":"“元代四大爱情剧”分别为关汉卿的《拜月亭》、王实甫的《西厢记》、白朴的《墙头马上》和郑光祖的《倩女离魂》。"},{"id":857,"type":"单选题","text":"《白雪歌送武判官归京》里描写了主将营帐中为武判官送行的情景，其中演奏的时候未用到___乐器？","options":[{"key":"A","text":"胡琴"},{"key":"B","text":"洞箫"},{"key":"C","text":"琵琶"},{"key":"D","text":"羌笛"}],"answer":["B"],"explanation":"《白雪歌送武判官归京》中“胡琴琵琶与羌笛”的意思是：胡琴琵琶羌笛合奏来助兴。所以演奏的时候用到了胡琴、琵琶、羌笛。"},{"id":858,"type":"单选题","text":"下列木材中不属于硬木的有____。","options":[{"key":"A","text":"楠木"},{"key":"B","text":"紫檀"},{"key":"C","text":"红木"},{"key":"D","text":"黄花梨"}],"answer":["A"],"explanation":"楠木为软木。"},{"id":859,"type":"单选题","text":"下列作品中，不属于草书作品的有____。","options":[{"key":"A","text":"张旭《肚痛帖》"},{"key":"B","text":"王献之《鸭头丸帖》"},{"key":"C","text":"怀素《自叙帖》"},{"key":"D","text":"王羲之《兰亭序》"}],"answer":["D"],"explanation":"D项《兰亭序》是行书作品。"},{"id":860,"type":"单选题","text":"围棋的别称体现了中国棋文化的深厚底蕴。下列词语中，不属于围棋别称的有____。","options":[{"key":"A","text":"黑白"},{"key":"B","text":"楚河"},{"key":"C","text":"手谈"},{"key":"D","text":"玉楸枰"}],"answer":["B"],"explanation":"“楚河”与象棋有关。"},{"id":861,"type":"单选题","text":"我国古代关于围棋的著作不包括____？","options":[{"key":"A","text":"《仙机武库》"},{"key":"B","text":"《幼学琼林》"},{"key":"C","text":"《忘忧清乐集》"},{"key":"D","text":"《石室仙机》"}],"answer":["B"],"explanation":"《幼学琼林》是中国古代启蒙的儿童读物，包含许多成语典故、著名人物、天文地理、典章制度等内容。"},{"id":862,"type":"单选题","text":"宋代确立了科举考试的三级考试制，不包括____？","options":[{"key":"A","text":"州试"},{"key":"B","text":"省试"},{"key":"C","text":"吏部试"},{"key":"D","text":"殿试"}],"answer":["C"],"explanation":"为了录取的公平，宋代形成了三级科举考试制度：州试，由地方官主持；省试，由尚书省礼部主持；殿试，由皇帝主持。"},{"id":863,"type":"单选题","text":"《史记》中的“本纪”原为历代帝王的传记。下列选项中，不是帝王却被载入“本纪”中的有____。","options":[{"key":"A","text":"项羽"},{"key":"B","text":"刘邦"},{"key":"C","text":"秦始皇"},{"key":"D","text":"汉武帝"}],"answer":["A"],"explanation":"《史记》中的 “本纪” 主要记载帝王事迹，但项羽虽未正式称帝，却在秦末推翻秦朝后，分封诸侯，自称 “西楚霸王”，实际掌握了当时的政权，具有与帝王相当的地位和影响力，司马迁为了肯定其历史功绩和地位，将其载入《项羽本纪》，A 选项正确。刘邦是汉高祖，秦始皇是秦朝开国皇帝，汉武帝是西汉皇帝，他们均为帝王，分别载入《高祖本纪》《秦始皇本纪》《孝武本纪》，B、C、D 选项错误。"},{"id":864,"type":"单选题","text":"古时百姓的称谓不包括____？","options":[{"key":"A","text":"黔首"},{"key":"B","text":"生民"},{"key":"C","text":"黎元"},{"key":"D","text":"阁下"}],"answer":["D"],"explanation":"“阁下” 是对有一定地位的人的尊称，多用于书信中"},{"id":865,"type":"单选题","text":"中国古代神话故事“干将莫邪”，在多本书籍中均有提及。下列记载了此故事的书籍有《孝子传》和____？","options":[{"key":"A","text":"《列士传》"},{"key":"B","text":"《聊斋志异》"},{"key":"C","text":"《搜神记》"},{"key":"D","text":"《史记》"}],"answer":["A"],"explanation":"干将莫邪是古代中国神话传说，最早出自汉朝刘向《列士传》和《孝子传》中。"},{"id":866,"type":"单选题","text":"下列关于道教的发展历程，说法错误的有____。","options":[{"key":"A","text":"隋唐至北宋是道教的兴盛时期。"},{"key":"B","text":"北魏寇谦之改革了道教，要求教徒“专以礼度为首”，为北天师道。"},{"key":"C","text":"《三经洞书目录》是道教史上第一部道经目录。"},{"key":"D","text":"张道陵撰写了《真灵位业图》，构造了道教的神仙谱系。"}],"answer":["D"],"explanation":"D项为陶弘景撰写了《真灵位业图》。"},{"id":867,"type":"单选题","text":"下列话语体现了循序渐进教学原则的有____。","options":[{"key":"A","text":"“不愤不启，不悱不发”"},{"key":"B","text":"“学不躐等”"},{"key":"C","text":"“温故而知新”"},{"key":"D","text":"“因材施教”"}],"answer":["B"],"explanation":"“学不躐等” 出自《礼记・学记》，“躐” 指超越，意思是学习不能超越等级和顺序，要按照一定的步骤逐步进行，体现了循序渐进的教学原则，B 选项正确。“不愤不启，不悱不发” 体现的是启发性教学原则；“温故而知新” 体现的是巩固性教学原则；“因材施教” 体现的是因材施教的教学原则，A、C、D 选项错误。"},{"id":868,"type":"单选题","text":"入世精神是中国历代优秀士大夫身体力行的人生追求。下列选项中不能体现这一精神的是____。","options":[{"key":"A","text":"“先天下之忧而忧，后天下之乐而乐”"},{"key":"B","text":"“天下兴亡，匹夫有责”"},{"key":"C","text":"“采菊东篱下，悠然见南山”"},{"key":"D","text":"“苟利国家生死以，岂因祸福避趋之”"}],"answer":["C"],"explanation":"入世精神指的是关注社会现实，积极参与社会事务，为国家和人民贡献力量的精神。“采菊东篱下，悠然见南山” 出自陶渊明的《饮酒・其五》，描绘了诗人归隐田园后的闲适生活，体现的是出世（归隐）精神，不能体现入世精神"},{"id":869,"type":"单选题","text":"勤俭节约是中华民族的传统美德，下面选项中与节约节俭无关的是____。","options":[{"key":"A","text":"“一粥一饭，当思来处不易；半丝半缕，恒念物力维艰”"},{"key":"B","text":"“谁知盘中餐，粒粒皆辛苦”"},{"key":"C","text":"“天生我材必有用，千金散尽还复来”"},{"key":"D","text":"“克勤于邦，克俭于家”"}],"answer":["C"],"explanation":"“天生我材必有用，千金散尽还复来” 出自李白的《将进酒》，表达了诗人对自身才华的自信和豪放洒脱的心态，与节约节俭无关"},{"id":870,"type":"单选题","text":"我国近代历史上涌现出很多爱国进步人士，清代爱国政治家林则徐就是这样的人，他曾经____。","options":[{"key":"A","text":"领导虎门销烟"},{"key":"B","text":"收复台湾"},{"key":"C","text":"创办洋务企业"},{"key":"D","text":"领导戊戌变法"}],"answer":["A"],"explanation":"1839 年，林则徐作为钦差大臣到广州禁烟，在虎门海滩当众销毁收缴的鸦片，史称 “虎门销烟”，这是中国近代史上反对外国侵略的重要事件，A 选项正确。"},{"id":871,"type":"单选题","text":"李清照是宋朝著名的女词人，下面选项中不属于李清照的作品有____。","options":[{"key":"A","text":"《如梦令•常记溪亭日暮》"},{"key":"B","text":"《声声慢•寻寻觅觅》"},{"key":"C","text":"《回乡偶书》"},{"key":"D","text":"《夏日绝句》"}],"answer":["C"],"explanation":"C项《回乡偶书》出自贺知章。"},{"id":872,"type":"单选题","text":"壮族人民会在歌圩这个传统文化娱乐活动上吃传统食物“五色饭”，请问“五色饭”不含有下列哪些颜色？","options":[{"key":"A","text":"红色"},{"key":"B","text":"粉色"},{"key":"C","text":"紫色"},{"key":"D","text":"黑色"}],"answer":["B"],"explanation":"五色饭是布依族、壮族等许多民族的传统风味小吃，一般呈黑、红、黄、白、紫5种色彩。"},{"id":873,"type":"单选题","text":"五言诗因每句五个字而得名，下面不属于五言诗的有____。","options":[{"key":"A","text":"《登鹳雀楼》"},{"key":"B","text":"《望庐山瀑布》"},{"key":"C","text":"《江雪》"},{"key":"D","text":"《静夜思》"}],"answer":["B"],"explanation":"《望庐山瀑布》每句有七个字，因此为七言诗。"},{"id":874,"type":"单选题","text":"下列关于郑成功的说法不正确的是____。","options":[{"key":"A","text":"郑成功出生于福建"},{"key":"B","text":"郑成功的父亲是一名渔夫"},{"key":"C","text":"郑成功收复台湾后，在台湾设置府县"},{"key":"D","text":"写有诗句“开辟荆榛逐荷夷，十年始克复先基”"}],"answer":["B"],"explanation":"郑成功的父亲为郑芝龙，初为海盗，后归顺明朝成为官员。"},{"id":875,"type":"单选题","text":"下列属于清代民族英雄的是____。","options":[{"key":"A","text":"岳飞"},{"key":"B","text":"文天祥"},{"key":"C","text":"林则徐"},{"key":"D","text":"郑成功"}],"answer":["C"],"explanation":"林则徐是清代著名的爱国政治家，他领导的虎门销烟打击了英国鸦片贩子的嚣张气焰，维护了中国的民族尊严，是清代的民族英雄"},{"id":876,"type":"单选题","text":"二十四节气反映了自然节律的变化。下列不属于二十四节气的是____。","options":[{"key":"A","text":"大暑"},{"key":"B","text":"小雨"},{"key":"C","text":"小雪"},{"key":"D","text":"大雪"}],"answer":["B"],"explanation":"二十四节气中并无“小雨”节气。"},{"id":877,"type":"单选题","text":"在端午节时，有些地方还有吃“五黄”的习俗，据说可以避 “五毒”。下列属于“五毒”的有____。","options":[{"key":"A","text":"蛇、蝎子、蜈蚣、蟾蜍、蜘蛛"},{"key":"B","text":"蛇、蝎子、蜈蚣、蟾蜍、壁虎"},{"key":"C","text":"蛇、蝎子、蜈蚣、蜥蜴、壁虎"},{"key":"D","text":"蛇、蝎子、蜈蚣、蟾蜍、蜥蜴"}],"answer":["B"],"explanation":"端午节所说的 “五毒” 是指五种常见的有毒动物，传统说法为蛇、蝎子、蜈蚣、蟾蜍（癞蛤蟆）、壁虎（守宫）"},{"id":878,"type":"单选题","text":"下列不属于纳西族文化的是____。","options":[{"key":"A","text":"东巴舞"},{"key":"B","text":"东巴经籍文学"},{"key":"C","text":"东巴文"},{"key":"D","text":"甩发舞"}],"answer":["D"],"explanation":"甩发舞是高山族原始舞蹈的遗存形式。"},{"id":879,"type":"单选题","text":"玉溪市因水得名，取其清流如玉之意。下列不属于玉溪市自然景观的有____。","options":[{"key":"A","text":"杞麓湖"},{"key":"B","text":"帽天山"},{"key":"C","text":"星云湖"},{"key":"D","text":"虎跳峡"}],"answer":["D"],"explanation":"虎跳峡位于云南省香格里拉市虎跳峡镇。"},{"id":880,"type":"单选题","text":"红河州因红河横贯全州腹地而得名。下面不属于红河州自然景观的有____。","options":[{"key":"A","text":"盘龙河"},{"key":"B","text":"阿庐古洞"},{"key":"C","text":"花鱼洞瀑布"},{"key":"D","text":"屏边大围山"}],"answer":["A"],"explanation":"盘龙河为中越国际河流，是云南省文山壮族苗族自治州文山市人民的母亲河。"},{"id":881,"type":"单选题","text":"下列属于西双版纳傣族自治州的民俗饮食文化的是____。","options":[{"key":"A","text":"五色饭"},{"key":"B","text":"手抓饭"},{"key":"C","text":"酥油茶"},{"key":"D","text":"青稞酒"}],"answer":["B"],"explanation":"手抓饭是西双版纳傣族等少数民族的传统饮食方式，通常将米饭、菜肴放在芭蕉叶上，用手抓食，体现了当地的民俗饮食文化"},{"id":882,"type":"单选题","text":"下列名言出自《弟子规》的是____。","options":[{"key":"A","text":"“三人行，必有我师焉”"},{"key":"B","text":"“父母呼，应勿缓；父母命，行勿懒”"},{"key":"C","text":"“己所不欲，勿施于人”"},{"key":"D","text":"“温故而知新，可以为师矣”"}],"answer":["B"],"explanation":"《弟子规》是清朝李毓秀所作的三言韵文，列举了为人子弟在家、外出，待人、接物等应该有的礼仪规范，上述句子均出于此。"},{"id":883,"type":"单选题","text":"以下寓言故事与出处对应不正确的是____。","options":[{"key":"A","text":"滥竽充数——《孟子》"},{"key":"B","text":"屠龙之术——《庄子》"},{"key":"C","text":"掩耳盗铃——《吕氏春秋》"},{"key":"D","text":"与狐谋皮——《符子》"}],"answer":["A"],"explanation":"滥竽充数是一则由寓言故事演化而来的成语，最早出自《韩非子·内储说上》。"},{"id":884,"type":"单选题","text":"下列名句与出处搭配不正确的选项有____。","options":[{"key":"A","text":"爱人者，人恒爱之——《孟子》"},{"key":"B","text":"驽马十驾，功在不舍——《韩非子》"},{"key":"C","text":"己欲立而立人，己欲达而达人——《论语》"},{"key":"D","text":"真者，精诚之至也——《庄子》"}],"answer":["B"],"explanation":"“驽马十驾，功在不舍”出自荀子的《劝学》，"},{"id":885,"type":"单选题","text":"梁山伯与祝英台坚贞的爱情故事感动了许多人。下列哪个不是梁山伯与祝英台的爱情故事中的桥段？","options":[{"key":"A","text":"水漫金山"},{"key":"B","text":"草桥结拜"},{"key":"C","text":"三载同窗"},{"key":"D","text":"十八相送"}],"answer":["A"],"explanation":"水漫金山是中国著名四大爱情传说之《白蛇传》中的一段情节。"},{"id":886,"type":"单选题","text":"中国传统绘画原本称为____等，明清时，西洋画传入中国才有了其他提法。","options":[{"key":"A","text":"丹青"},{"key":"B","text":"油画"},{"key":"C","text":"水彩画"},{"key":"D","text":"版画"}],"answer":["A"],"explanation":"中国传统绘画在古代常被称为 “丹青”，“丹” 指朱砂，“青” 指石青、石绿，是传统绘画中常用的颜料，后来 “丹青” 便成为绘画的代称"},{"id":887,"type":"单选题","text":"苏州一带画家承接元代文人画风格形成“吴门画派”。下列选项不属于“吴门四家”的有______。","options":[{"key":"A","text":"唐寅"},{"key":"B","text":"仇英"},{"key":"C","text":"文徵明"},{"key":"D","text":"祝枝山"}],"answer":["D"],"explanation":"“吴门四家”指的是四位著名的明代画家：沈周、文徵明、唐寅和仇英。"},{"id":888,"type":"单选题","text":"清代郑板桥注重意境创造，提出了以下理论,以竹喻人正是人格、精神、情操的自我写照。其中不包括？","options":[{"key":"A","text":"“眼中之竹”"},{"key":"B","text":"“笔中之竹”"},{"key":"C","text":"“胸中之竹”"},{"key":"D","text":"“手中之竹”"}],"answer":["B"],"explanation":"郑板桥提出的“眼中之竹、胸中之竹、手中之竹”，分别代表艺术家进行艺术体验、艺术构思和艺术表现的绘画过程。"},{"id":889,"type":"单选题","text":"山水画可以细多种类型，除了以下哪项？。","options":[{"key":"A","text":"青绿山水"},{"key":"B","text":"金碧山水"},{"key":"C","text":"水墨山水"},{"key":"D","text":"工笔山水"}],"answer":["D"],"explanation":"山水画为中国画的一种，主要描写山川等自然景色，主要分为：青绿山水、水墨山水、浅绛山水、金碧山水和没骨山水。"},{"id":890,"type":"单选题","text":"下列画家与其画作搭配错误的一项是____。","options":[{"key":"A","text":"《清明上河图》——张择端"},{"key":"B","text":"《虢国夫人游春图》——张萱"},{"key":"C","text":"《步辇图》——阎立本"},{"key":"D","text":"《富春山居图》——赵孟頫"}],"answer":["D"],"explanation":"D项作者是黄公望。"},{"id":891,"type":"单选题","text":"《清明上河图》生动地展现了北宋时期城市生活的多彩风貌，大致可以分为三段，其中不包括___？","options":[{"key":"A","text":"郊野春色"},{"key":"B","text":"大漠孤烟"},{"key":"C","text":"汴河码头"},{"key":"D","text":"市井街道"}],"answer":["B"],"explanation":"《清明上河图》展现的是汴京的城市景象，大漠孤烟为沙漠景色，不会出现在城市当中。"},{"id":892,"type":"单选题","text":"大观楼始建于康熙年间，见证了昆明三百多年来的成长、变化与发展，下面出自大观楼长联的选项不包括____。","options":[{"key":"A","text":"汉习楼船"},{"key":"B","text":"唐标铁柱"},{"key":"C","text":"宋挥玉斧"},{"key":"D","text":"洪武开疆"}],"answer":["D"],"explanation":"上联\n五百里滇池奔来眼底，披襟岸帻，喜茫茫空阔无边。看：东骧神骏，西翥灵仪，北走蜿蜒，南翔缟素。高人韵士何妨选胜登临。趁蟹屿螺洲，梳裹就风鬟雾鬓；更苹天苇地，点缀些翠羽丹霞，莫辜负：四围香稻，万顷晴沙，九夏芙蓉，三春杨柳。\n下联\n数千年往事注到心头，把酒凌虚，叹滚滚英雄谁在？想：汉习楼船，唐标铁柱，宋挥玉斧，元跨革囊。伟烈丰功费尽移山心力。尽珠帘画栋，卷不及暮雨朝云；便断碣残碑，都付与苍烟落照。只赢得：几杵疏钟，半江渔火，两行秋雁，一枕清霜。通读全诗，由此排除D选项。"},{"id":893,"type":"单选题","text":"我国有很多名楼皆因文人杰作而名扬天下，下列选项中文人与其所写的关于名楼的作品对应不正确的是____。","options":[{"key":"A","text":"辛弃疾——《岳阳楼记》"},{"key":"B","text":"王勃——《滕王阁序》"},{"key":"C","text":"王之涣——《登鹳雀楼》"},{"key":"D","text":"崔颢——《黄鹤楼》"}],"answer":["A"],"explanation":"A项岳阳楼记是范仲淹所写。"},{"id":894,"type":"单选题","text":"“《韩诗》曰：‘郑国之俗，三月上巳……’”讲述上巳节的习俗，其中，《韩诗》是今文学派之一，西汉时与____并称为“三家诗”。","options":[{"key":"A","text":"《鲁诗》《齐诗》"},{"key":"B","text":"《鲁诗》《楚诗》"},{"key":"C","text":"《齐诗》《楚诗》"},{"key":"D","text":"《燕诗》《鲁诗》"}],"answer":["A"],"explanation":"西汉时期，今文学派的《诗经》解读有 “三家诗”，分别是《韩诗》（韩婴所传）、《鲁诗》（鲁人申培所传）、《齐诗》（齐人辕固生所传），三者在当时影响深远，后《毛诗》兴起，“三家诗” 逐渐失传，故答案为 A。"},{"id":895,"type":"单选题","text":"《史记》不仅反映了中国古代历史，其本身也是一部优秀的文学作品，以下不属于列传五个部分的是____。","options":[{"key":"A","text":"志"},{"key":"B","text":"世家"},{"key":"C","text":"表"},{"key":"D","text":"书"}],"answer":["A"],"explanation":"《史记》分为本纪、世家、列传、表、书等五个部分。"},{"id":896,"type":"单选题","text":"孔林圣地承载着传播儒家文化的使命，影响一代又一代的人们，下列选项中有关孔林的叙述正确的是____。","options":[{"key":"A","text":"孔子“杏坛讲学”的杏坛亭是孔林的主要建筑之一"},{"key":"B","text":"孔林的主殿名为大成殿，与故宫太和殿、泰山岱庙天贶殿并称“东方三大殿”"},{"key":"C","text":"孔林的核心是“铁山园”"},{"key":"D","text":"孔子墓因墓形如隆起的马背，故名“马鬣封”"}],"answer":["D"],"explanation":"A选项中，孔子“杏坛讲学”的杏坛亭不是孔林的主要建筑之一，孔林的主要建筑包括大成殿、铁山园等，而杏坛亭位于孔庙内，并非孔林的一部分‌。B选项中，东方三大殿分别为山东曲阜孔庙的主殿大成殿、北京故宫太和殿、山东泰安岱庙天贶殿。C选项中，孔林的核心是“孔子墓”。"},{"id":897,"type":"单选题","text":"下列哪些材料不是用来制作活字印刷所使用的活字块的常见材料？","options":[{"key":"A","text":"木头"},{"key":"B","text":"胶泥"},{"key":"C","text":"金属"},{"key":"D","text":"龟甲"}],"answer":["D"],"explanation":"最早的活字是胶泥字（陶字）,木字、金属字是后来的进步之作。因此可以排除D选项。"},{"id":898,"type":"单选题","text":"中国瓷器闻名世界，下列选项中哪个不是清代的瓷器制作技艺？","options":[{"key":"A","text":"釉里红"},{"key":"B","text":"五彩"},{"key":"C","text":"粉彩"},{"key":"D","text":"珐琅彩"}],"answer":["A"],"explanation":"A项釉里红瓷是传统陶瓷中的艺术珍品，属于元代中期景德镇劳动人民的重要发明之一。"},{"id":899,"type":"单选题","text":"苏州园林中比较有代表性的有沧浪亭、狮子林、拙政园、留园，它们代表的朝代的艺术风格不包括____。","options":[{"key":"A","text":"唐"},{"key":"B","text":"宋"},{"key":"C","text":"元"},{"key":"D","text":"明"}],"answer":["A"],"explanation":"沧浪亭、狮子林、拙政园和留园分别代表着宋、元、明、清四个朝代的艺术风格，因此排除A选项。"},{"id":900,"type":"单选题","text":"下列关于金银器的说法，正确的是____。","options":[{"key":"A","text":"中国古代金银器仅用于装饰，无实用功能"},{"key":"B","text":"唐代金银器制作工艺达到顶峰，造型精美"},{"key":"C","text":"金银器在古代只有皇室才能使用"},{"key":"D","text":"古代金银器材质单一，仅用纯金、纯银制作"}],"answer":["B"],"explanation":"A 项古代金银器既有装饰功能，也有实用功能（如金银餐具、酒具），说法错误；B 项唐代经济繁荣，金银器制作工艺精湛，出现了锤揲、錾刻等复杂技艺，造型精美，达到顶峰，说法正确；C 项古代贵族、官员等也可使用金银器，并非仅皇室专属，说法错误；D 项古代金银器常采用金、银与其他金属合金制作，材质并非单一，说法错误，故答案为 B。"},{"id":901,"type":"单选题","text":"造纸术在四世纪传到了___，直至19世纪中叶，造纸术已传遍世界。","options":[{"key":"A","text":"欧洲"},{"key":"B","text":"朝鲜"},{"key":"C","text":"美洲"},{"key":"D","text":"非洲"}],"answer":["B"],"explanation":"造纸术的传播有明确时间线：东汉蔡伦改进造纸术后，首先传入邻近的朝鲜（4 世纪）和日本（7 世纪）；8 世纪传入阿拉伯地区，12 世纪左右经阿拉伯传入欧洲，后来逐步传到美洲、非洲，故答案为 B。"},{"id":902,"type":"单选题","text":"莫高窟为我们呈现出一个神秘、瑰丽的艺术世界，下列关于莫高窟壁画描述不正确的是____。","options":[{"key":"A","text":"莫高窟壁画题材与佛教息息相关，有佛像画、佛教故事的画作等"},{"key":"B","text":"莫高窟壁画绘画技巧风格多样，线条精细"},{"key":"C","text":"壁画所用的全部颜料均从矿石中提炼而来"},{"key":"D","text":"莫高窟壁画有4500平方米"}],"answer":["D"],"explanation":"D项目莫高窟壁画面积约45000平方米。"},{"id":903,"type":"单选题","text":"宋代是瓷器发展的重要时期，其中五大名窑包含____。","options":[{"key":"A","text":"汝窑、官窑、哥窑、钧窑、青花瓷窑"},{"key":"B","text":"汝窑、官窑、哥窑、唐三彩窑、定窑"},{"key":"C","text":"汝窑、官窑、哥窑、钧窑、定窑"},{"key":"D","text":"汝窑、官窑、哥窑、钧窑、青瓷窑"}],"answer":["C"],"explanation":"中国古代五大名窑是钧窑、汝窑、官窑、定窑、哥窑。"},{"id":904,"type":"单选题","text":"文山苗族花山节中必不可少的表演项目是芦笙舞表演，芦笙舞表演按照功能划分可以分为三大类，以下哪个不属于三大类？","options":[{"key":"A","text":"祭祀性"},{"key":"B","text":"习俗性"},{"key":"C","text":"娱乐性"},{"key":"D","text":"礼仪性"}],"answer":["C"],"explanation":"芦笙舞表演分为自娱性芦笙舞,习俗性芦笙舞以及表演性芦笙舞,同时还有礼仪性和祭祀性的芦笙舞"},{"id":905,"type":"单选题","text":"下列选项中哪些不是东巴经籍文学的代表作品？","options":[{"key":"A","text":"《创世纪》"},{"key":"B","text":"《黑白战争》"},{"key":"C","text":"《彩虹》"},{"key":"D","text":"《鲁般鲁饶》"}],"answer":["C"],"explanation":"《东巴经》除记载迎神驱鬼、祈福求寿、消灾消难等内容外,还记载了大量的纳西族古典文学作品,包括神话故事、叙事长诗、谚语歌谣等。 神话中最著名的是创世史诗《创世纪》、英雄史诗《黑白战争》、悲剧长诗《鲁般鲁饶》。它们合称纳西族的三大史诗。"},{"id":906,"type":"单选题","text":"下列选项中，不属于欧阳询楷书代表作的是____。","options":[{"key":"A","text":"《九成宫醴泉铭》"},{"key":"B","text":"《皇甫诞碑》"},{"key":"C","text":"《张翰帖》"},{"key":"D","text":"《化度寺碑》"}],"answer":["C"],"explanation":"C项《张翰帖》是唐代书法家欧阳询创作的纸本行书作品，有“天下第七行书”之称。"},{"id":907,"type":"单选题","text":"形声是一种造字方法。下列汉字不属于形声字的是____。","options":[{"key":"A","text":"睁"},{"key":"B","text":"吐"},{"key":"C","text":"咏"},{"key":"D","text":"灰"}],"answer":["D"],"explanation":"形声字是由两个文或字复合成体，其中的一个文或字表示事物的类别而另一个表示事物的读音，因此选择D选项。"},{"id":908,"type":"单选题","text":"关于夸父追日的神话故事，下列描述错误的是____。","options":[{"key":"A","text":"夸父倒下后变成了一座大山"},{"key":"B","text":"在追逐太阳的过程中，夸父即便又渴又累，也没有放弃"},{"key":"C","text":"夸父最终追上了太阳"},{"key":"D","text":"夸父最终死在了路上"}],"answer":["C"],"explanation":"夸父追日指的是相传在黄帝时期，夸父族首领夸父想要把太阳摘下，于是开始逐日，和太阳赛跑，在口渴时喝干了黄河、渭水之后，在奔于大泽路途中渴死。死后他的手杖化作桃林，身躯化作夸父山。"},{"id":909,"type":"单选题","text":"传说神农对中华民族的生存繁衍和发展做出了重要贡献。人们为了纪念这位无私爱民的首领，尊称他为____。","options":[{"key":"A","text":"舜帝"},{"key":"B","text":"“药圣”"},{"key":"C","text":"“五谷之神”"},{"key":"D","text":"“五谷先帝”"}],"answer":["D"],"explanation":"B项药圣是李时珍；C项五谷之神为后稷。"},{"id":910,"type":"单选题","text":"下面选项中，哪些不属于立春的习俗？","options":[{"key":"A","text":"鞭春牛"},{"key":"B","text":"游春"},{"key":"C","text":"吃春饼"},{"key":"D","text":"戴五彩线"}],"answer":["D"],"explanation":"D项，人民一般在端午节佩戴五色丝线以辟邪，兼有祈福纳吉的美好寓意。"},{"id":911,"type":"单选题","text":"清明节是我国的重要传统节日之一，下列哪些不属于清明节的节日习俗？","options":[{"key":"A","text":"扫墓"},{"key":"B","text":"踏青"},{"key":"C","text":"吃粽子"},{"key":"D","text":"放风筝"}],"answer":["C"],"explanation":"C项吃粽子是端午节的习俗。"},{"id":912,"type":"单选题","text":"下面选项中，关于绝句《池上》（小娃撑小艇）一诗分析正确的是____。","options":[{"key":"A","text":"“池上”意思是池塘里"},{"key":"B","text":"“浮萍”指一种水生植物"},{"key":"C","text":"“小艇”指小船"},{"key":"D","text":"这首诗的作者白居易是宋代诗人"}],"answer":["D"],"explanation":"D项，白居易是唐代诗人。"},{"id":913,"type":"单选题","text":"下列不属于寒食节节日习俗的有____。","options":[{"key":"A","text":"禁火"},{"key":"B","text":"吃冷食"},{"key":"C","text":"扫墓"},{"key":"D","text":"猜灯谜"}],"answer":["D"],"explanation":"D项猜灯谜又称打灯谜，是从古代就开始流传的元宵节特色活动。"},{"id":914,"type":"单选题","text":"孟浩然是唐代著名的山水田园派诗人。下列选项中，属于孟浩然所写诗句的有____。","options":[{"key":"A","text":"大漠孤烟直，长河落日圆"},{"key":"B","text":"春眠不觉晓，处处闻啼鸟"},{"key":"C","text":"举头望明月，低头思故乡"},{"key":"D","text":"飞流直下三千尺，疑是银河落九天"}],"answer":["B"],"explanation":"“春眠不觉晓，处处闻啼鸟” 出自孟浩然的《春晓》，B 选项正确；A 选项出自王维的《使至塞上》；C 选项出自李白的《静夜思》；D 选项出自李白的《望庐山瀑布》。"},{"id":915,"type":"单选题","text":"传说夸父在追赶太阳的路途上，因为口渴，喝干了哪些河流里的水？","options":[{"key":"A","text":"黄河、渭河"},{"key":"B","text":"长江、淮河"},{"key":"C","text":"珠江、钱塘江"},{"key":"D","text":"黑龙江、松花江"}],"answer":["A"],"explanation":"根据《山海经》等古籍记载，夸父追日时，因极度口渴，先喝干了黄河、渭河的水，随后又去喝北方大泽的水，未到便渴死；B、C、D 选项中的河流均与夸父追日的传说无关。"},{"id":916,"type":"单选题","text":"下列选项中，既属于农历二十四节气，又是我国传统节日的是____。","options":[{"key":"A","text":"立春"},{"key":"B","text":"清明节"},{"key":"C","text":"端午节"},{"key":"D","text":"中秋节"}],"answer":["B"],"explanation":"在二十四节气中，只有清明节同时是传统节日，兼具节气的自然属性（春分后十五日，万物清洁而明净）与节日的人文属性（祭祖、踏青）；A 选项立春是节气，但不是传统节日；C、D 选项是传统节日，但不属于二十四节气。"},{"id":917,"type":"单选题","text":"在我国，每个地区、每个民族都有自己的特色美食，下列选项中，哪些不属于云南地区的特色美食？","options":[{"key":"A","text":"过桥米线"},{"key":"B","text":"竹筒饭"},{"key":"C","text":"汽锅鸡"},{"key":"D","text":"虾饺"}],"answer":["D"],"explanation":"D项虾饺是广东的特色美食。"},{"id":918,"type":"单选题","text":"六经，是六部儒学经典的统称，下列选项中不属于六经的是____。","options":[{"key":"A","text":"《诗经》"},{"key":"B","text":"《论语》"},{"key":"C","text":"《礼记》"},{"key":"D","text":"《春秋》"}],"answer":["B"],"explanation":"六经，是指《诗》、《书》、《礼》、《易》、《乐》、《春秋》的合称。"},{"id":919,"type":"单选题","text":"尊老爱幼是我们中华民族的传统美德。下列选项中，不属于尊老爱幼的是____。","options":[{"key":"A","text":"单老孤稚有所养"},{"key":"B","text":"老吾老以及人之老，幼吾幼以及人之幼"},{"key":"C","text":"子不学，非所宜。幼不学，老何为"},{"key":"D","text":"臣无祖母，无以至今日；祖母无臣，无以终余年"}],"answer":["C"],"explanation":"C项意思是：一个人倘若小时候不好好学习，到老的时候既不懂做人的道理，又无知识，那么到老的时候都很难有所作为的，与题目不符。"},{"id":920,"type":"单选题","text":"柳永《八声甘州》抒写了词人漂泊在外的愁思和仕途失意的悲慨。以下哪个选项不是出自这首词？","options":[{"key":"A","text":"对潇潇、暮雨洒江天"},{"key":"B","text":"望故乡渺邈，归思难收"},{"key":"C","text":"罗幕轻寒，燕子双飞去"},{"key":"D","text":"叹年来踪迹，何事苦淹留"}],"answer":["C"],"explanation":"C项出自晏殊的《蝶恋花·槛菊愁烟兰泣露》。"},{"id":921,"type":"单选题","text":"古代通讯技术不发达，人们都用书信传递信息。下列词语中不是表示书信别称的是____。","options":[{"key":"A","text":"桃符"},{"key":"B","text":"尺牍"},{"key":"C","text":"尺素"},{"key":"D","text":"鲤鱼"}],"answer":["A"],"explanation":"A项桃符是春联的别名。"},{"id":922,"type":"单选题","text":"豪放派是形成于宋代的词学流派之一，豪放派的代表人物有____。","options":[{"key":"A","text":"柳永"},{"key":"B","text":"李清照"},{"key":"C","text":"苏轼"},{"key":"D","text":"秦观"}],"answer":["C"],"explanation":"苏轼是宋代豪放派的开创者之一，其词突破了婉约派的题材限制，风格豪迈开阔，C 选项正确；A 柳永、B 李清照、D 秦观均为婉约派词人，词风以婉转、细腻为主。"},{"id":923,"type":"单选题","text":"百日礼，是我国古代较为重要的礼俗之一。下列哪些关键词与“百日礼”有关？","options":[{"key":"A","text":"抓周"},{"key":"B","text":"剃胎发"},{"key":"C","text":"冠礼"},{"key":"D","text":"笄礼"}],"answer":["B"],"explanation":"百日礼（又称 “百晬”）的常见习俗包括为婴儿剃胎发（寓意洁净、健康成长）、穿百家衣等，B 选项正确；A 选项 “抓周” 是婴儿周岁时的礼俗，通过抓取物品预测未来兴趣；C 选项 “冠礼” 是男子二十岁的成人礼；D 选项 “笄礼” 是女子十五岁的成人礼。"},{"id":924,"type":"单选题","text":"《周礼》记载的“六艺”不包括____。","options":[{"key":"A","text":"诗"},{"key":"B","text":"礼"},{"key":"C","text":"射"},{"key":"D","text":"书"}],"answer":["A"],"explanation":"“六艺”分别是：礼、乐、射、御、书、数，因此排除A选项。"},{"id":925,"type":"单选题","text":"射箭已经成为现代奥运会的比赛项目之一，我国自古以来就有这项运动，下列哪些人物不是射箭能手？","options":[{"key":"A","text":"李广"},{"key":"B","text":"养由基"},{"key":"C","text":"蒙万赢"},{"key":"D","text":"长孙晟"}],"answer":["C"],"explanation":"C项蒙万赢是相扑高手。"},{"id":926,"type":"单选题","text":"汉语中有很多词语是从“纺织”中发展而来的。下列选项中的词语，哪些与纺织无关？","options":[{"key":"A","text":"经纬"},{"key":"B","text":"绸缎"},{"key":"C","text":"推敲"},{"key":"D","text":"绫罗"}],"answer":["C"],"explanation":"A 选项 “经纬” 原指织物的纵线（经）和横线（纬），与纺织相关；B 选项 “绸缎”、D 选项 “绫罗” 均为丝织品，属于纺织品类，与纺织相关；C 选项 “推敲” 源于唐代诗人贾岛斟酌诗句 “僧敲月下门” 还是 “僧推月下门” 的故事，指反复琢磨，与纺织无关。"},{"id":927,"type":"单选题","text":"作为中国古代四大发明之一，印刷术为人类文明的进步做出了重大贡献。下列哪些词语与印刷无关？","options":[{"key":"A","text":"雕版"},{"key":"B","text":"活字"},{"key":"C","text":"拓片"},{"key":"D","text":"针灸"}],"answer":["D"],"explanation":"A 选项 “雕版” 是雕版印刷的核心工具，与印刷相关；B 选项 “活字” 是活字印刷的核心部件，与印刷相关；C 选项 “拓片” 是通过拓印技术获取文字 / 图案的方式，与印刷原理有相通之处；D 选项 “针灸” 是中医的治疗方法，通过针刺和艾灸调理身体，与印刷无关。"},{"id":928,"type":"单选题","text":"在瓷器鉴赏节目中，我们常常能听到一些专业术语，下列哪个术语与瓷器无关？","options":[{"key":"A","text":"重皮"},{"key":"B","text":"棕眼"},{"key":"C","text":"倒口儿"},{"key":"D","text":"口磕"}],"answer":["C"],"explanation":"C项“倒口儿”是曲艺行业术语，意思是“说方言”。"},{"id":929,"type":"单选题","text":"故宫的宫殿按照使用性质分为外朝和内廷两大部分，下列宫殿位于外朝的是____。","options":[{"key":"A","text":"乾清宫"},{"key":"B","text":"太和殿"},{"key":"C","text":"交泰殿"},{"key":"D","text":"坤宁宫"}],"answer":["B"],"explanation":"故宫外朝是皇帝处理政务、举行大典的场所，核心宫殿包括太和殿、中和殿、保和殿；内廷是皇帝与后妃的居住、日常活动区域，包括乾清宫（皇帝寝宫）、交泰殿、坤宁宫（皇后寝宫）等。因此 B 选项太和殿位于外朝，A、C、D 选项位于内廷。"},{"id":930,"type":"单选题","text":"太和殿是故宫内规模最大、最高的殿宇。主要供____大朝会和其他大典，如皇帝登基或大婚册封时使用。","options":[{"key":"A","text":"正月初一"},{"key":"B","text":"五月初五"},{"key":"C","text":"八月十五"},{"key":"D","text":"九月初九"}],"answer":["A"],"explanation":"太和殿的核心用途是举行国家重大典礼，其中 “大朝会” 特指正月初一（春节）、冬至等重要节日，皇帝在此接受百官朝贺；B 选项五月初五是端午节，C 选项八月十五是中秋节，D 选项九月初九是重阳节，均无在太和殿举行大朝会的习俗。"},{"id":931,"type":"单选题","text":"清朝有专门供皇家使用的藏书楼即“北方四阁”,下列哪些不属于“北方四阁”？","options":[{"key":"A","text":"文渊阁"},{"key":"B","text":"文津阁"},{"key":"C","text":"文澜阁"},{"key":"D","text":"文源阁"}],"answer":["C"],"explanation":"“北方四阁”分别是：北京故宫的文渊阁、沈阳故宫的文溯阁、北京圆明园的文源阁、河北承德避暑山庄的文津阁。"},{"id":932,"type":"单选题","text":"颐和园规模宏大，气象万千。下列选项中，哪些景点位于颐和园中？","options":[{"key":"A","text":"拙政园"},{"key":"B","text":"佛香阁"},{"key":"C","text":"留园"},{"key":"D","text":"狮子林"}],"answer":["B"],"explanation":"佛香阁是颐和园的核心标志性建筑，位于万寿山山顶，B 选项正确；A 拙政园、C 留园、D 狮子林均是苏州古典园林，不属于颐和园。"},{"id":933,"type":"单选题","text":"华佗一生喜爱运动，他在吸取前人养生保健经验的基础上，创编了五禽戏。这“五禽”包括鸟、熊、____。","options":[{"key":"A","text":"虎、鹿、猿"},{"key":"B","text":"虎、马、兔"},{"key":"C","text":"龙、蛇、兔"},{"key":"D","text":"龙、鹿、猿"}],"answer":["A"],"explanation":"五禽戏是虎、鹿、熊、猿、鸟五种动物。"},{"id":934,"type":"单选题","text":"中国文化又可称为____。","options":[{"key":"A","text":"华夏文化"},{"key":"B","text":"玛雅文化"},{"key":"C","text":"两河文化"},{"key":"D","text":"爱琴文化"}],"answer":["A"],"explanation":"“华夏” 是中国古代的别称，“华夏文化” 即中国文化，A 选项正确；B 选项玛雅文化是美洲古代文明；C 选项两河文化是西亚底格里斯河、幼发拉底河流域的文明；D 选项爱琴文化是欧洲古希腊地区的古代文明，均与中国文化无关。"},{"id":935,"type":"单选题","text":"古代人们对月亮有着美好的想象，对其有很多种称呼，下列哪项不是古人对月亮的称呼？","options":[{"key":"A","text":"婵娟"},{"key":"B","text":"玉盘"},{"key":"C","text":"金乌"},{"key":"D","text":"桂魄"}],"answer":["C"],"explanation":"A 选项 “婵娟”（如 “但愿人长久，千里共婵娟”）、B 选项 “玉盘”（如 “小时不识月，呼作白玉盘”）、D 选项 “桂魄”（因传说月中有桂树，故称桂魄）均是月亮的别称；C 选项 “金乌” 是古代对太阳的称呼（传说太阳中有三足金乌），不是月亮的称呼。"},{"id":936,"type":"单选题","text":"《四时幽赏录》主要记述西湖一年四季的不同境趣，如春时____，夏时____，秋时“西泠桥畔醉红树”，冬时“三茅山顶望雪霁”。","options":[{"key":"A","text":"“苏堤春晓赏桃花”；“曲院风荷闻暗香”"},{"key":"B","text":"“孤山月下看梅花”；“湖心亭畔听蝉鸣”"},{"key":"C","text":"“柳浪闻莺赏新绿”；“平湖秋月品清茗”"},{"key":"D","text":"“六和塔上观潮涌”；“断桥残雪觅诗意”"}],"answer":["B"],"explanation":"《四时幽赏录》是明代高濂所著，其对西湖四季幽赏场景的记述贴合西湖实景与文人雅趣。选项 A 中 “苏堤春晓” 是西湖十景之一，但 “赏桃花” 并非《四时幽赏录》春时核心记述；选项 C “平湖秋月” 是秋季景观，与 “夏时” 搭配错误；选项 D “六和塔观潮” 多在中秋前后，“断桥残雪” 是冬季景观，均不符合四季对应逻辑。而 “孤山月下看梅花” 符合西湖孤山春季梅景的雅致，“湖心亭畔听蝉鸣” 贴合夏季西湖的清幽意境，与原文秋、冬景致的风格一致，故选择 B。"},{"id":937,"type":"单选题","text":"“中国四大名园”被公认为中国最优秀的园林建筑，它们分别是颐和园和____。","options":[{"key":"A","text":"苏州拙政园"},{"key":"B","text":"北京圆明园"},{"key":"C","text":"杭州西湖"},{"key":"D","text":"南京中山陵"}],"answer":["A"],"explanation":"中国四大名园分别是拙政园、颐和园、避暑山庄、留园。"},{"id":938,"type":"单选题","text":"蜡染是我国古老的少数民族民间传统纺织印染手工艺，古称蜡缬，与绞缬和____并称为我国古代三大印花技艺。","options":[{"key":"A","text":"夹缬"},{"key":"B","text":"胶浆印"},{"key":"C","text":"植物印"},{"key":"D","text":"织锦"}],"answer":["A"],"explanation":"到了唐代，印染工艺十分发达，著名的有蜡缬、绞缬、夹缬,这是中国古代三大印花技艺。"},{"id":939,"type":"单选题","text":"历史上对学生的称谓种类繁多，下列称谓哪些不是对学生的称呼？","options":[{"key":"A","text":"生员"},{"key":"B","text":"监生"},{"key":"C","text":"弟子"},{"key":"D","text":"足下"}],"answer":["D"],"explanation":"D项足下常用于对平辈或是朋友之间的敬称。"},{"id":940,"type":"单选题","text":"以下哪个不是中国传统的祭祖节日？","options":[{"key":"A","text":"除夕"},{"key":"B","text":"清明节"},{"key":"C","text":"端午节"},{"key":"D","text":"重阳节"}],"answer":["C"],"explanation":"清明节、中元节、重阳节、除夕是中国民间传统的四大祭祖大节，因此排除C选项。"},{"id":941,"type":"单选题","text":"历史上出现的“上品无寒门，下品无势族”、“四世三公”等现象，证明了在以古代农业自然经济为基础的宗法社会里的____。","options":[{"key":"A","text":"科举制度公平"},{"key":"B","text":"门阀制度盛行"},{"key":"C","text":"平民机会均等"},{"key":"D","text":"皇权高度集中"}],"answer":["B"],"explanation":"“上品无寒门，下品无势族” 描述的是魏晋南北朝九品中正制下，官员选拔被世家大族垄断；“四世三公” 指一个家族四代人均担任三公（高级官职），体现了世家大族的特权。这两个现象均证明古代宗法社会中 “门阀制度” 盛行（门阀即世代为官的世家大族）；A 选项科举制度公平与现象相悖（科举制打破门阀垄断）；C 选项平民机会均等与 “上品无寒门” 矛盾；D 选项皇权高度集中与门阀制度无关（门阀甚至会削弱皇权）。"},{"id":942,"type":"单选题","text":"以下哪个不属于“岁寒三友”？","options":[{"key":"A","text":"兰花"},{"key":"B","text":"松树"},{"key":"C","text":"翠竹"},{"key":"D","text":"梅花"}],"answer":["A"],"explanation":"“岁寒三友”意思是松、竹经冬不凋，梅花耐寒开放，因此有“岁寒三友”之称。"},{"id":943,"type":"单选题","text":"下列选项中，未体现爱国主义精神的有____。","options":[{"key":"A","text":"位卑未敢忘忧国"},{"key":"B","text":"苟利国家生死以，岂因祸福避趋之"},{"key":"C","text":"人生自古谁无死，留取丹心照汗青"},{"key":"D","text":"周虽旧邦，其命维新"}],"answer":["D"],"explanation":"D项出自《诗经》，意思是周虽然是旧的邦国，但其使命在革新。"},{"id":944,"type":"单选题","text":"我国古代就已出现了专门为学童编写的书目。下列选项中，不属于古代启蒙教材的有____。","options":[{"key":"A","text":"《三字经》"},{"key":"B","text":"《增广贤文》"},{"key":"C","text":"《菜根谭》"},{"key":"D","text":"《弟子规》"}],"answer":["C"],"explanation":"C项《菜根谭》是以处世思想为主的格言式小品文集，采用语录体，揉合了儒家的中庸思想和佛家的出世思想的人生处世哲学。"},{"id":945,"type":"单选题","text":"以明清以来流行的样式为例，古典家具大体上可以分为五类，分别是坐具、承具以及____。","options":[{"key":"A","text":"电器"},{"key":"B","text":"卧具"},{"key":"C","text":"现代沙发"},{"key":"D","text":"塑料椅"}],"answer":["B"],"explanation":"以明清以来流行的样式为例,古典家具大体上可以分为卧具、庋具、坐具、承具、杂具五类。"},{"id":946,"type":"单选题","text":"下列诗句中，描写的是洞庭湖的有____。","options":[{"key":"A","text":"月落乌啼霜满天，江枫渔火对愁眠"},{"key":"B","text":"湖光秋月两相和，潭面无风镜未磨"},{"key":"C","text":"最爱湖东行不足，绿杨阴里白沙堤"},{"key":"D","text":"孤帆远影碧空尽，唯见长江天际流"}],"answer":["B"],"explanation":"A项地处苏州；C项描写的是钱塘湖。D选项描写长江（黄鹤楼送别场景）"},{"id":947,"type":"单选题","text":"下列句子中，描写西湖风光的有____。","options":[{"key":"A","text":"雾凇沆砀，天与云与山与水，上下一白"},{"key":"B","text":"寒雨连江夜入吴，平明送客楚山孤"},{"key":"C","text":"一道残阳铺水中，半江瑟瑟半江红"},{"key":"D","text":"天门中断楚江开，碧水东流至此回"}],"answer":["A"],"explanation":"B项描述王昌龄在芙蓉楼送别时的吴江夜雨，C项是诗人白居易在赴杭州任刺史的途中写的，表示出诗人自愿远离朝廷后轻松愉悦的解放情绪和个性色彩。"},{"id":948,"type":"单选题","text":"茶马古道是中国西南民族经济文化交流的走廊。下面对茶马古道介绍错误的是____。","options":[{"key":"A","text":"易武、倚帮都是茶马古道上的重要古镇"},{"key":"B","text":"茶马古道始于明清"},{"key":"C","text":"运输的最主要货物是云南大叶种晒青紧压茶"},{"key":"D","text":"普洱是茶马古道上独具优势的货物产地和中转集散地，具有悠久的历史"}],"answer":["B"],"explanation":"B项茶马古道始于唐代。"},{"id":949,"type":"单选题","text":"明代围棋之风兴盛，流派纷起，以下除了哪个选项，形成了三个著名的流派？","options":[{"key":"A","text":"永嘉派"},{"key":"B","text":"江西派"},{"key":"C","text":"新安派"},{"key":"D","text":"京师派"}],"answer":["B"],"explanation":"明代正德、嘉靖年间，形成了三个著名的围棋流派：以鲍一中为冠的永嘉派，以程汝亮为冠的新安派，以及以颜伦、李釜为冠的京师派，因此排除B选项。"},{"id":950,"type":"单选题","text":"下列人物传记不是出自《史记》的有____。","options":[{"key":"A","text":"《项羽本纪》"},{"key":"B","text":"《张淳传》"},{"key":"C","text":"《高祖本纪》"},{"key":"D","text":"《吕不韦列传》"}],"answer":["B"],"explanation":"B项《张淳传》出自《明史》。"},{"id":951,"type":"单选题","text":"《三国演义》中出现了两次美人计，涉及的两位美人分别是貂蝉和____。","options":[{"key":"A","text":"孙尚香"},{"key":"B","text":"小乔"},{"key":"C","text":"蔡琰"},{"key":"D","text":"王昭君"}],"answer":["A"],"explanation":"《三国演义》中有两个著名的美人计，第一个是貂蝉离间吕布与董卓，另一个则是孙权把妹妹孙尚香嫁给刘备，预想骗其到东吴作人质。"},{"id":952,"type":"单选题","text":"戏曲演员要具备的四项基本功，俗称“四功”，不包括____。","options":[{"key":"A","text":"唱"},{"key":"B","text":"说"},{"key":"C","text":"念"},{"key":"D","text":"做"}],"answer":["B"],"explanation":"“四功”是唱、念、做、打，因此排除B选项。“唱”指歌唱，是戏曲表演中的核心内容；“念”指具有音乐性的念白；“做”指舞蹈化的形体动作，即戏曲演员在戏曲表演过程中做工的基本功夫；“打”指武打和翻跌的技艺，即戏曲表演艺术中武戏中的武打功夫。"},{"id":953,"type":"单选题","text":"一般来说，评书的艺术手法有四种，其中包括摆砌末和____。","options":[{"key":"A","text":"开脸儿"},{"key":"B","text":"开肩"},{"key":"C","text":"压嗓子"},{"key":"D","text":"扯段儿"}],"answer":["A"],"explanation":"评书的艺术手法有四种,分别为:开脸儿、摆砌末、赋赞以及垛句。"},{"id":954,"type":"单选题","text":"下列选项中不属于京韵大鼓代表作品的有____。","options":[{"key":"A","text":"探晴雯》"},{"key":"B","text":"《关公战秦琼》"},{"key":"C","text":"《长坂坡》"},{"key":"D","text":"《大西厢》"}],"answer":["B"],"explanation":"B项《关公战秦琼》是相声艺术的经典作品。"},{"id":955,"type":"单选题","text":"下列不属于韩愈在文学上的主张有____。","options":[{"key":"A","text":"“致君尧舜上，再使风俗淳”"},{"key":"B","text":"“文道合一”"},{"key":"C","text":"“务去陈言”"},{"key":"D","text":"“文从字顺”"}],"answer":["A"],"explanation":"A项“致君尧舜上，再使风俗淳”，出自唐代杜甫《奉赠韦左丞丈二十二韵》诗。"},{"id":956,"type":"单选题","text":"每逢春节，大街小巷就会挂上红色的中国结，以营造喜庆的节日氛围。下列不属于中国结特点的有____。","options":[{"key":"A","text":"上下一致"},{"key":"B","text":"左右对称"},{"key":"C","text":"首尾互衔"},{"key":"D","text":"正反不同"}],"answer":["D"],"explanation":"中国结讲究上下一致，左右对称，正反相同，首尾可接，因此排除D选项。"},{"id":957,"type":"单选题","text":"下列不属于相声演员四大基本功的是____。","options":[{"key":"A","text":"说"},{"key":"B","text":"逗"},{"key":"C","text":"唱"},{"key":"D","text":"捧"}],"answer":["D"],"explanation":"相声的四大基本功是说、学、逗、唱。"},{"id":958,"type":"单选题","text":"下列有关戏曲角色行当的说法错误的有____。","options":[{"key":"A","text":"花旦主要扮演天真活泼或性格泼辣的青年女性，常带有喜剧色彩"},{"key":"B","text":"武旦主要扮演勇武的女性，多是擅长武艺的巾帼英雄"},{"key":"C","text":"武丑包括方巾丑、褶子丑、茶衣丑等"},{"key":"D","text":"彩旦主要扮演滑稽或奸刁的女性，又称“丑旦”"}],"answer":["C"],"explanation":"C项方巾丑、褶子丑、茶衣丑属于文丑。"},{"id":959,"type":"单选题","text":"下列关于鲁班的说法中错误的是____。","options":[{"key":"A","text":"鲁班姓鲁，名公输"},{"key":"B","text":"传说锯子为鲁班所发明"},{"key":"C","text":"“班门弄斧”的成语故事与鲁班有关"},{"key":"D","text":"《墨子》中记载了鲁班造云梯的故事"}],"answer":["A"],"explanation":"A项鲁班姓公输，名般，或称“公输子”“班输”等。因他是春秋时期鲁国人，又被称为“鲁班”。"},{"id":960,"type":"单选题","text":"我国古代神医扁鹊医术出神入化，下列有关扁鹊的描述中错误的有____。","options":[{"key":"A","text":"“病入膏肓”的故事与扁鹊有关"},{"key":"B","text":"他在总结前人经验的基础上，结合自己的行医实践，创制了“四诊法”"},{"key":"C","text":"他被誉为“中医学的奠基人”"},{"key":"D","text":"他是春秋时期的医学家，姓秦，名越人"}],"answer":["D"],"explanation":"D项扁鹊是战国时期的医学家。"},{"id":961,"type":"单选题","text":"下列不属于“干栏式”建筑的有____。","options":[{"key":"A","text":"傣族竹楼"},{"key":"B","text":"景颇族矮脚长屋"},{"key":"C","text":"独龙族千脚落地屋"},{"key":"D","text":"客家围龙屋"}],"answer":["D"],"explanation":"D项客家围龙屋属于半圆形客家围屋（客家围村）。"},{"id":962,"type":"单选题","text":"范蠡是我国历史上著名的谋士和大商人，他的事迹主要记载在____等书中。","options":[{"key":"A","text":"《论语》"},{"key":"B","text":"《史记》"},{"key":"C","text":"《道德经》"},{"key":"D","text":"《诗经》"}],"answer":["B"],"explanation":"范蠡的事迹主要记载在《史记》与《国语》等书中。"},{"id":963,"type":"单选题","text":"《周易》是儒家重要经典之一。下列关于《周易》的说法，错误的是____。","options":[{"key":"A","text":"内容包括《经》和《传》两个部分"},{"key":"B","text":"《经》主要是六十四卦和三百八十四爻"},{"key":"C","text":"《传》是对《经》最早的解说，包含解释卦辞和爻辞的七种文辞"},{"key":"D","text":"《周易》是中国传统文化思想中社会科学与人文实践的理论根源"}],"answer":["D"],"explanation":"D选项《周易》是中国传统思想文化中自然哲学与人文实践的理论根源。"},{"id":964,"type":"单选题","text":"下列选项中属于屈原的作品的是____。","options":[{"key":"A","text":"《楚辞》"},{"key":"B","text":"《天问》"},{"key":"C","text":"《庄子》"},{"key":"D","text":"《三都赋》"}],"answer":["B"],"explanation":"A项是刘向汇集的作品集，D项是左思的作品。"},{"id":965,"type":"单选题","text":"昆曲是中国戏曲中的古老剧种之一，以下哪个不是昆曲的称谓。","options":[{"key":"A","text":"“昆山腔”"},{"key":"B","text":"“昆腔”"},{"key":"C","text":"“昆剧”"},{"key":"D","text":"“文曲”"}],"answer":["D"],"explanation":"昆曲,原名“昆山腔”或简称“昆腔”，清代以来被称为“昆曲”，现又被称为“昆剧”。"},{"id":966,"type":"单选题","text":"下列选项中，关于琴的诗词与其作者及出处对应错误的是____。","options":[{"key":"A","text":"七弦为益友，两耳是知音（白居易《船夜援琴》）"},{"key":"B","text":"泠泠七弦上，静听松风寒（韦应物《听弹琴》）"},{"key":"C","text":"为我一挥手，如听万壑松（李白《听蜀僧濬弹琴》）"},{"key":"D","text":"归去无眠，一夜余音在耳边（苏轼《减字木兰花》）"}],"answer":["B"],"explanation":"B项应为刘长卿的《听弹琴》。"},{"id":967,"type":"单选题","text":"纺织与我们的生活息息相关。下列诗句中与丝绸生产和流通无关的有____。","options":[{"key":"A","text":"夜市卖菱藕，春船载绮罗"},{"key":"B","text":"小妇连宵上绢机，大耆催税急于飞"},{"key":"C","text":"将缣来比素，新人不如故"},{"key":"D","text":"掷柳迁乔太有情，交交时作弄机声"}],"answer":["D"],"explanation":"D项描写的是鸟的鸣叫声像织布声。"},{"id":968,"type":"单选题","text":"下列句子中与采桑相关的有____。","options":[{"key":"A","text":"“种豆南山下，草盛豆苗稀”"},{"key":"B","text":"“桑之未落，其叶沃若”"},{"key":"C","text":"“稻花香里说丰年，听取蛙声一片”"},{"key":"D","text":"“风吹草低见牛羊”"}],"answer":["B"],"explanation":"B选项正确，“桑之未落，其叶沃若” 出自《诗经・卫风・氓》，“桑” 即桑树，“其叶沃若” 描绘了桑树叶茂盛的样子，桑树是采桑的对象，句子与采桑相关（采桑需用桑叶养蚕）。"},{"id":969,"type":"单选题","text":"惠施是战国时期名家的代表人物。以下不属于惠施的观点的是____。","options":[{"key":"A","text":"我知天下之中央，燕之北、越之南是也"},{"key":"B","text":"一尺之棰，日取其半，万世不竭"},{"key":"C","text":"泛爱万物，天地一体"},{"key":"D","text":"邻国相望，鸡犬之声相闻，民至老死，不相往来"}],"answer":["D"],"explanation":"D项为老子的观点."},{"id":970,"type":"单选题","text":"院落式民居在我国具有悠久的历史，它最早出现在秦汉之际。下列选项中不属于院落式民居的是____。","options":[{"key":"A","text":"“一颗印”民居"},{"key":"B","text":"天井式民居"},{"key":"C","text":"土楼民居"},{"key":"D","text":"碉房"}],"answer":["D"],"explanation":"D项属于穴居式民居。"},{"id":971,"type":"单选题","text":"下列词牌名得名于道教故事的是____。","options":[{"key":"A","text":"《沁园春》"},{"key":"B","text":"《鹊桥仙》"},{"key":"C","text":"《念奴娇》"},{"key":"D","text":"《菩萨蛮》"}],"answer":["B"],"explanation":"《鹊桥仙》得名于 “牛郎织女七夕鹊桥相会” 的传说，牛郎织女在道教文化中被视为神仙，故事带有道教神仙体系色彩，词牌名源于此道教相关故事。"},{"id":972,"type":"单选题","text":"下列选项中不属于历史演义小说的是____。","options":[{"key":"A","text":"余邵鱼《列国志传》"},{"key":"B","text":"冯梦龙《新列国志》"},{"key":"C","text":"诸圣邻《大唐秦王词话》"},{"key":"D","text":"熊大木《大宋中兴通俗演义》"}],"answer":["D"],"explanation":"D项熊大木的《大宋中兴通俗演义》是英雄传奇小说。"},{"id":973,"type":"单选题","text":"古人论琴，有“四善九德”之说，这“四善九德”说的都是音色和音质。其中，“四善”不包含____。","options":[{"key":"A","text":"苍"},{"key":"B","text":"松"},{"key":"C","text":"润"},{"key":"D","text":"脆"}],"answer":["C"],"explanation":"四善九德中“四善”指的是苍、松、脆、滑,也就是说古琴的音质一般具备苍老、清亮、浑厚圆润、古朴等特点，因此排除C选项。"},{"id":974,"type":"单选题","text":"书院的出现，形成了中国古代教育三足鼎立的局面。另外两个是____。","options":[{"key":"A","text":"官学、私学"},{"key":"B","text":"太学、国子监"},{"key":"C","text":"私塾、义学"},{"key":"D","text":"官学、书院"}],"answer":["A"],"explanation":"中国古代教育体系中，“三足鼎立” 指三种主要教育形式：官学、私学、书院。"},{"id":975,"type":"单选题","text":"早在春秋时期，以下哪个选项不是人们用圭表测试日影长短的方法确立的节气？","options":[{"key":"A","text":"立春"},{"key":"B","text":"春分"},{"key":"C","text":"夏至"},{"key":"D","text":"冬至"}],"answer":["A"],"explanation":"利用圭表测量日影的长短,就可以确定冬至(日影最长)夏至(日影最短)和春分、秋分(日影在最长、最短之间)四个节气。"},{"id":976,"type":"单选题","text":"下列哪些水利工程不是建于春秋战国时期？","options":[{"key":"A","text":"郑国渠"},{"key":"B","text":"灵渠"},{"key":"C","text":"都江堰"},{"key":"D","text":"漳水十二渠"}],"answer":["B"],"explanation":"B项灵渠，又称湘桂运河，或兴安运河，秦朝时期开凿的渠道。灵渠位于广西壮族自治区兴安县境内。建成于秦始皇三十三年（公元前二一四年）。"},{"id":977,"type":"单选题","text":"下列说法中，未包含环保思想的有____。","options":[{"key":"A","text":"草木荣华滋硕之时，则斧斤不入山林，不夭其生，不绝其长也"},{"key":"B","text":"天行有常，不为尧存，不为桀亡"},{"key":"C","text":"不夏月，毋敢夜草为灰"},{"key":"D","text":"凡窃木者，有刑罚"}],"answer":["B"],"explanation":"B项出自荀子《天论》。荀子认为，社会是清明富足还是动荡飘摇，全是人事的结果，和自然界没有什么关系。"},{"id":978,"type":"单选题","text":"诚信是一个人安身立命之本。下列选项中，未反映诚信的有____。","options":[{"key":"A","text":"无人信高洁，谁为表予心"},{"key":"B","text":"人而无信，不知其可也"},{"key":"C","text":"诚，五常之本，百行之源也"},{"key":"D","text":"人无信不立"}],"answer":["A"],"explanation":"A项出自骆宾王《咏蝉》，信是相信的意思。"},{"id":979,"type":"单选题","text":"关于兵器的种类，上古有“五兵”之说。以下选项不属于“五兵”的是____。","options":[{"key":"A","text":"戈"},{"key":"B","text":"戟"},{"key":"C","text":"矛"},{"key":"D","text":"剑"}],"answer":["D"],"explanation":"“五兵”指戈、殳、戟、酋矛、夷矛，因此排除D选项。"},{"id":980,"type":"单选题","text":"下列句子中，与中秋节有关的有____。","options":[{"key":"A","text":"“爆竹声中一岁除，春风送暖入屠苏”"},{"key":"B","text":"“清明时节雨纷纷，路上行人欲断魂”"},{"key":"C","text":"“但愿人长久，千里共婵娟”"},{"key":"D","text":"“遥知兄弟登高处，遍插茱萸少一人”"}],"answer":["C"],"explanation":"“但愿人长久，千里共婵娟” 出自苏轼《水调歌头・明月几时有》，“婵娟” 指明月，这首词是苏轼在中秋节思念弟弟苏辙所作，直接关联中秋节（赏月、思亲是中秋节核心习俗）。"},{"id":981,"type":"单选题","text":"下列关于《三国演义》的说法，错误的是____。","options":[{"key":"A","text":"四大名著之一，是我国第一部长篇章回小说"},{"key":"B","text":"是历史演义小说的开山之作"},{"key":"C","text":"大约成书于明清之际"},{"key":"D","text":"虚实结合，清代史学家章学诚认为它是“七分事实，三分虚构”"}],"answer":["C"],"explanation":"C项《三国演义》创作于元末明初洪武年间。"},{"id":982,"type":"单选题","text":"《三国演义》中讲述了许多经典故事，也塑造了很多栩栩如生的人物形象。下列经典故事，不属于《三国演义》的有____。","options":[{"key":"A","text":"舌战群儒"},{"key":"B","text":"三顾茅庐"},{"key":"C","text":"智取生辰纲"},{"key":"D","text":"计取荆州"}],"answer":["C"],"explanation":"C项“智取生辰纲”是《水浒传》中的故事情节。"},{"id":983,"type":"单选题","text":"《水浒传》中描写了一百零八位好汉，他们每个人都有自己的绰号，下列绰号与人物对应错误的是____。","options":[{"key":"A","text":"豹子头——林冲"},{"key":"B","text":"玉麒麟——卢俊义"},{"key":"C","text":"九纹龙——杨志"},{"key":"D","text":"黑旋风——李逵"}],"answer":["C"],"explanation":"C项九纹龙是史进的绰号。"},{"id":984,"type":"单选题","text":"宋江是《水浒传》中梁山好汉之首。下列不属于对宋江称呼的有____。","options":[{"key":"A","text":"“及时雨”"},{"key":"B","text":"“神算子”"},{"key":"C","text":"“呼保义”"},{"key":"D","text":"“宋押司”"}],"answer":["B"],"explanation":"B项“神算子”是蒋敬。"},{"id":985,"type":"单选题","text":"下列选项中，不属于《水浒传》中人物的是____。","options":[{"key":"A","text":"郭嘉"},{"key":"B","text":"王英"},{"key":"C","text":"卢俊义"},{"key":"D","text":"宋江"}],"answer":["A"],"explanation":"A项郭嘉是《三国演义》中的人物。"},{"id":986,"type":"单选题","text":"那达慕大会是蒙古族历史悠久的传统节日。在传统的那达慕大会上，男子要进行哪三项竞技活动？","options":[{"key":"A","text":"摔跤、赛马、射箭"},{"key":"B","text":"举重、游泳、跑步"},{"key":"C","text":"跳高、跳远、投掷"},{"key":"D","text":"拳击、武术、体操"}],"answer":["A"],"explanation":"自古以来,内蒙古大草原上的人们，热烈地崇拜摔跤、赛马和射箭的能手,将这三项比赛统称为“男儿三艺”。"},{"id":987,"type":"单选题","text":"清朝定都北京后，共经历了10位皇帝，下列不属于清朝皇帝年号的是____。","options":[{"key":"A","text":"康熙"},{"key":"B","text":"乾隆"},{"key":"C","text":"洪武"},{"key":"D","text":"光绪"}],"answer":["C"],"explanation":"“洪武” 是明朝开国皇帝朱元璋的年号，不属于清朝。"},{"id":988,"type":"单选题","text":"下列属于春秋时期法家思想先驱人物的是____。","options":[{"key":"A","text":"孔子"},{"key":"B","text":"管仲"},{"key":"C","text":"墨子"},{"key":"D","text":"韩非子"}],"answer":["B"],"explanation":"管仲是春秋时期齐国政治家，虽未形成完整的法家思想体系，但他在齐国推行的改革（如 “相地而衰征”“寄军令于内政”）强调以法治国、重视耕战，注重实际功效，为后世法家思想的形成奠定了基础，被视为法家思想先驱。"},{"id":989,"type":"单选题","text":"墨子认为“言必有三表”，其中，“三表”不包括____？","options":[{"key":"A","text":"“本”"},{"key":"B","text":"“原”"},{"key":"C","text":"“用”"},{"key":"D","text":"“爱”"}],"answer":["D"],"explanation":"“言必有三表，何谓三表，子墨子言曰，有本之者，有原之者，有用之者”，因此排除D选项。"},{"id":990,"type":"单选题","text":"《孙子兵法》在概括战争的要素时提出了“五事”，即道、天、地、将、法五项内容。下列关于这五项内容的具体含义，错误的是____。","options":[{"key":"A","text":"道——道德和正义"},{"key":"B","text":"天——有利的气象条件"},{"key":"C","text":"地——有利的地形地貌和地理位置"},{"key":"D","text":"将——善于作战的将领"}],"answer":["A"],"explanation":"A项“道”指君民一致"},{"id":991,"type":"单选题","text":"三十六计是指中国古代三十六个兵法策略。下列选项中，不属于“三十六计”的是____。","options":[{"key":"A","text":"瞒天过海"},{"key":"B","text":"围魏救赵"},{"key":"C","text":"纸上谈兵"},{"key":"D","text":"声东击西"}],"answer":["C"],"explanation":"“纸上谈兵” 是成语，源自战国时期赵括只懂兵法理论、不会实战的故事，并非 “三十六计” 中的策略。"},{"id":992,"type":"单选题","text":"北宋的苏轼是中国古代文化艺术集大成者。下列作品中，作者是苏轼的有____。","options":[{"key":"A","text":"《念奴娇・赤壁怀古》"},{"key":"B","text":"《蜀道难》"},{"key":"C","text":"《春望》"},{"key":"D","text":"《登高》"}],"answer":["A"],"explanation":"《念奴娇・赤壁怀古》是苏轼的代表作之一，属于豪放派词的经典，词中 “大江东去，浪淘尽，千古风流人物” 广为流传。"},{"id":993,"type":"单选题","text":"我国素以“礼仪之邦”著称，我国古代有“五礼”之说，下列选项中，不属于“五礼”的有____。","options":[{"key":"A","text":"嘉礼"},{"key":"B","text":"吉礼"},{"key":"C","text":"宾礼"},{"key":"D","text":"冠礼"}],"answer":["D"],"explanation":"“五礼”包括吉礼、凶礼、军礼、宾礼、嘉礼。"},{"id":994,"type":"单选题","text":"下列关于《论语》的说法，错误的是____。","options":[{"key":"A","text":"《论语》约成书于春秋战国时期，由孔子弟子及再传弟子编写而成"},{"key":"B","text":"儒家学派的经典著作之一，主要记录孔子及其弟子的言行"},{"key":"C","text":"全书共20篇，以语录体和对话体为主"},{"key":"D","text":"书中提出了“仁政”学说"}],"answer":["D"],"explanation":"D项仁政学说是孟子提出的。"},{"id":995,"type":"单选题","text":"下列人物中，“文章四友”不包括以下哪个选项？","options":[{"key":"A","text":"杨炯"},{"key":"B","text":"李峤"},{"key":"C","text":"杜审言"},{"key":"D","text":"崔融"}],"answer":["A"],"explanation":"“文章四友”是李峤、杜审言、崔融、苏味道，因此排除A选项。"},{"id":996,"type":"单选题","text":"下列哪些事物在古诗中未被用作表现春天的意象？","options":[{"key":"A","text":"荷花"},{"key":"B","text":"燕子"},{"key":"C","text":"小草"},{"key":"D","text":"杏花"}],"answer":["A"],"explanation":"A项荷花表现夏天的意象。"},{"id":997,"type":"单选题","text":"正所谓“故不积跬步，无以至千里”，下面选项中没有讲述这个道理的是____。","options":[{"key":"A","text":"绳锯木断，水滴石穿"},{"key":"B","text":"尺有所短，寸有所长"},{"key":"C","text":"冰冻三尺，非一日之寒"},{"key":"D","text":"不积小流，无以成江海"}],"answer":["B"],"explanation":"B项“尺有所短，寸有所长”比喻各有长处，也各有短处，彼此都有可取之处。"},{"id":998,"type":"单选题","text":"下列哪些作品不是张衡的著作？","options":[{"key":"A","text":"《西京赋》"},{"key":"B","text":"《归田赋》"},{"key":"C","text":"《东京赋》"},{"key":"D","text":"《过秦论》"}],"answer":["D"],"explanation":"D《过秦论》是贾谊政论文的代表作，分上中下三篇。全文从各个方面分析秦王朝的过失，故名为《过秦论》。"},{"id":999,"type":"单选题","text":"下面不属于藏戏传统剧目的是____。","options":[{"key":"A","text":"《文成公主》"},{"key":"B","text":"《诺桑王子》"},{"key":"C","text":"《牡丹亭》"},{"key":"D","text":"《朗萨雯蚌》"}],"answer":["C"],"explanation":"《牡丹亭》是明代汤显祖的昆曲剧目，讲述杜丽娘与柳梦梅的爱情故事，属于汉族戏曲，不属于藏戏传统剧目。"},{"id":1000,"type":"单选题","text":"白居易《大林寺桃花》中将春天的短暂美好通过桃花在山上山下的不同开放时间表现了出来，下列诗词中描写桃花的有____。","options":[{"key":"A","text":"“墙角数枝梅，凌寒独自开”"},{"key":"B","text":"“人间四月芳菲尽，山寺桃花始盛开”"},{"key":"C","text":"“接天莲叶无穷碧，映日荷花别样红”"},{"key":"D","text":"“停车坐爱枫林晚，霜叶红于二月花”"}],"answer":["B"],"explanation":"“人间四月芳菲尽，山寺桃花始盛开” 出自白居易《大林寺桃花》，直接描写了山寺中桃花在四月开放的景象，是描写桃花的诗词。"},{"id":1001,"type":"单选题","text":"中医博大精深，历史悠久，才人辈出。下列不属于中医学方面杰出人物的有____。","options":[{"key":"A","text":"张仲景"},{"key":"B","text":"宋应星"},{"key":"C","text":"孙思邈"},{"key":"D","text":"董奉"}],"answer":["B"],"explanation":"宋应星是明朝著名科学家，他的著作和研究领域涉及自然科学及人文科学的不同学科，而其中最杰出的作品《天工开物》被誉为“中国17世纪的工艺百科全书”。"},{"id":1002,"type":"单选题","text":"下列风景中不属于“洛阳八景”的有____。","options":[{"key":"A","text":"天津晓月"},{"key":"B","text":"太液秋风"},{"key":"C","text":"铜驼暮雨"},{"key":"D","text":"洛浦秋风"}],"answer":["B"],"explanation":"洛阳八大景：一、龙门山色 二、马寺钟声 三、金谷春晴 四、邙山晚眺 五、天津晓月 六、洛浦秋风 七、平泉朝游 八、铜驼暮雨"},{"id":1003,"type":"单选题","text":"宋明时期兴盛不衰的理学，又被称为____。","options":[{"key":"A","text":"汉学"},{"key":"B","text":"朴学"},{"key":"C","text":"新儒学"},{"key":"D","text":"玄学"}],"answer":["C"],"explanation":"宋明理学是在儒家思想基础上，融合道家、佛教思想形成的新儒学体系，以 “理” 为核心概念，探讨宇宙、人性、道德等问题，因此又被称为 “新儒学”。"},{"id":1004,"type":"单选题","text":"衡山美景很多，最著名的是“衡山四绝”。下列哪些美景不属于“衡山四绝”?","options":[{"key":"A","text":"藏经殿之秀"},{"key":"B","text":"水帘洞之奇"},{"key":"C","text":"温泉水之清"},{"key":"D","text":"祝融峰之高"}],"answer":["C"],"explanation":"衡山四绝是指方广寺之深、水帘洞之奇、藏经殿之秀、祝融峰之高。"},{"id":1005,"type":"单选题","text":"《陌上桑》中不是侧面描写罗敷美貌的句子是哪个选项？","options":[{"key":"A","text":"行者见罗敷，下担捋髭须"},{"key":"B","text":"少年见罗敷，脱帽著悄头"},{"key":"C","text":"秦氏有好女，自名为罗敷"},{"key":"D","text":"耕者忘其犁，锄者忘其锄"}],"answer":["C"],"explanation":"C项是正面描写。"},{"id":1006,"type":"单选题","text":"苏轼与____合称“三苏”。","options":[{"key":"A","text":"苏洵、苏辙"},{"key":"B","text":"苏舜钦、苏洵"},{"key":"C","text":"苏辙、苏舜钦"},{"key":"D","text":"苏洵、苏武"}],"answer":["A"],"explanation":"三苏是指其中的苏洵、苏轼、苏辙这三人。在唐宋时期，三苏是唐宋八大家当中的三位，其中苏洵是苏轼和苏辙的父亲，苏轼是苏辙的哥哥。"},{"id":1007,"type":"单选题","text":"成语“刮目相看”的故事中涉及下列哪个人物?","options":[{"key":"A","text":"吕蒙"},{"key":"B","text":"刘备"},{"key":"C","text":"张飞"},{"key":"D","text":"周瑜"}],"answer":["A"],"explanation":"主要涉及吕蒙与鲁肃。"},{"id":1008,"type":"单选题","text":"下列作品中属周部族史诗的，除了以下哪个选项？","options":[{"key":"A","text":"《生民》"},{"key":"B","text":"《公刘》"},{"key":"C","text":"《绵》"},{"key":"D","text":"《伐檀》"}],"answer":["D"],"explanation":"《诗经·大雅》中《生民》、《公刘》、《绵》、《皇矣》和《大明》这五首构成了周部族史诗,这五首史诗记录了周部族发展史的几次重要的部族大事,再现了周部族发展史,具有非凡的艺术魅力"},{"id":1009,"type":"单选题","text":"明代中晚期市民⽂学的理论表现是____。","options":[{"key":"A","text":"文以载道"},{"key":"B","text":"童心说"},{"key":"C","text":"性灵说"},{"key":"D","text":"格调说"}],"answer":["B"],"explanation":"“文以载道” 是宋代古文运动的核心理论（如韩愈、柳宗元倡导，宋代欧阳修等继承），强调文学的道德教化功能，A 项排除；“童心说” 由明代李贽提出，主张文学应表现 “童心”（未受世俗污染的纯真本性），契合中晚期市民阶层追求个性解放的需求，是市民文学的重要理论表现，B 项正确；“性灵说” 是清代袁枚等倡导的诗歌理论，强调抒发个人真情实感，C 项排除；“格调说” 是清代沈德潜提出的，主张诗歌应讲究格律、格调，尊崇儒家诗教，D 项排除。"},{"id":1010,"type":"单选题","text":"先秦诸子百家中，被称为“显学”的是儒家和____。","options":[{"key":"A","text":"墨家"},{"key":"B","text":"法家"},{"key":"C","text":"道家"},{"key":"D","text":"纵横家"}],"answer":["A"],"explanation":"儒家是先秦诸子百家中较大的一支学派,与墨家并称“显学”。"},{"id":1011,"type":"单选题","text":"下列人物属春秋时代的是____。","options":[{"key":"A","text":"孔子"},{"key":"B","text":"孟子"},{"key":"C","text":"荀子"},{"key":"D","text":"韩非子"}],"answer":["A"],"explanation":"孔子（前 551 - 前 479 年）生活于春秋末期，是儒家学派创始人"},{"id":1012,"type":"单选题","text":"下列人物不属于战国时代的是____。","options":[{"key":"A","text":"老子"},{"key":"B","text":"庄子"},{"key":"C","text":"韩非"},{"key":"D","text":"荀子"}],"answer":["A"],"explanation":"老子属于春秋时代人物。"},{"id":1013,"type":"单选题","text":"下列人物属儒家学派的是____。","options":[{"key":"A","text":"庄子"},{"key":"B","text":"墨子"},{"key":"C","text":"孟子"},{"key":"D","text":"韩非子"}],"answer":["C"],"explanation":"庄子属道家，墨子属墨家，韩非子属法家，A、B、D 项排除；孟子是战国时期儒家 “亚圣”，继承孔子 “仁” 的思想，提出 “仁政”“性善论”，属儒家学派，C 项正确。"},{"id":1014,"type":"单选题","text":"荀子是____。","options":[{"key":"A","text":"春秋时期儒家代表，主张 “性善论”"},{"key":"B","text":"战国时期儒家代表，主张 “性恶论”"},{"key":"C","text":"战国时期道家代表，主张 “无为而治”"},{"key":"D","text":"战国时期法家代表，主张 “法治”"}],"answer":["B"],"explanation":"荀子生活于战国末期，属儒家学派（非道家、法家），A、C、D 项排除；他与孟子 “性善论” 不同，主张 “性恶论”，认为人的本性需通过后天教化（“礼法并施”）约束，是战国儒家重要代表，B 项正确。"},{"id":1015,"type":"单选题","text":"“春秋三传”不包括____。","options":[{"key":"A","text":"《春秋》"},{"key":"B","text":"《春秋左氏传》"},{"key":"C","text":"《春秋公羊传》"},{"key":"D","text":"《春秋榖梁传》"}],"answer":["A"],"explanation":"古代“传”的意思是解读别的书的书籍。春秋三传就是解读《春秋》的书，包括《春秋左氏传》《春秋公羊传》《春秋榖梁传》。"},{"id":1016,"type":"单选题","text":"以下著作属于国别史的是____。","options":[{"key":"A","text":"《左传》"},{"key":"B","text":"《国语》"},{"key":"C","text":"《史记》"},{"key":"D","text":"《资治通鉴》"}],"answer":["B"],"explanation":"国别史以国家为单位记载历史，《国语》分记周、鲁、齐、晋、郑、楚、吴、越八国史事，是中国最早的国别体史书，B 项正确；《左传》是编年体（按时间顺序记载），《史记》是纪传体（以人物为中心），《资治通鉴》是编年体通史，A、C、D 项排除。"},{"id":1017,"type":"单选题","text":"以下著作属于编年史的是____。","options":[{"key":"A","text":"《国语》"},{"key":"B","text":"《战国策》"},{"key":"C","text":"《左传》"},{"key":"D","text":"《史记》"}],"answer":["C"],"explanation":"编年史以时间为线索编排历史事件。《左传》按鲁君年号（如隐公元年、桓公二年）记载春秋史事，属编年体，C 项正确；《国语》《战国策》是国别体，《史记》是纪传体，A、B、D 项排除。"},{"id":1018,"type":"单选题","text":"屈原的政治主张不包括____。","options":[{"key":"A","text":"举贤授能"},{"key":"B","text":"修明法度"},{"key":"C","text":"联齐抗秦"},{"key":"D","text":"兼爱与非攻"}],"answer":["D"],"explanation":"“兼爱”与“非攻”是墨家学派创始人墨子的主要思想观点。"},{"id":1019,"type":"单选题","text":"“汉赋四大家”不包含____。","options":[{"key":"A","text":"枚乘"},{"key":"B","text":"司马相如"},{"key":"C","text":"扬雄"},{"key":"D","text":"班固"}],"answer":["A"],"explanation":"汉赋四大家包括：司马相如、扬雄、班固、张衡。"},{"id":1020,"type":"单选题","text":"下列关于《九歌》的描述正确的有____。","options":[{"key":"A","text":"是屈原创作的单篇叙事诗，描写楚国历史"},{"key":"B","text":"是屈原整理的楚地祭神组诗，共11篇"},{"key":"C","text":"是宋玉创作的悲秋组诗，共9篇"},{"key":"D","text":"是汉代乐府民歌，反映民间生活"}],"answer":["B"],"explanation":"《九歌》非单篇、非叙事诗，也不侧重楚国历史，A 项排除；它是屈原根据楚地民间祭神乐歌整理加工而成的组诗，共 11 篇（含《东皇太一》《国殇》等），B 项正确；《九辩》是宋玉的悲秋组诗（9 篇），C 项排除；《九歌》是先秦楚辞，非汉代乐府，D 项排除。"},{"id":1021,"type":"单选题","text":"以下作品属于抒情小赋的是____。","options":[{"key":"A","text":"《吊屈原赋》"},{"key":"B","text":"《两都赋》"},{"key":"C","text":"《子虚赋》"},{"key":"D","text":"《鹦鹉赋》"}],"answer":["D"],"explanation":"赋按体裁形式可分为骚体赋、散体大赋和抒情小赋三种。《吊屈原赋》属于骚体赋体裁，《两都赋》属于大体体裁。《子虚赋》为典型的汉大赋。"},{"id":1022,"type":"单选题","text":"下列关于《史记》的描述正确的有____。","options":[{"key":"A","text":"是我国第一部编年体通史，作者司马迁"},{"key":"B","text":"是我国第一部纪传体通史，记载了从黄帝到汉武帝的历史"},{"key":"C","text":"是我国第一部国别体史书，作者班固"},{"key":"D","text":"是我国第一部纪传体断代史，记载了西汉历史"}],"answer":["B"],"explanation":"《史记》作者是司马迁，非班固；是纪传体通史（以人物传记为中心，贯通古今），非编年体（A 错）、国别体（C 错）、断代史（D 错，断代史是《汉书》）；其记载范围从黄帝到汉武帝太初年间，B 项正确。"},{"id":1023,"type":"单选题","text":"《史记》共分五部分，其中不包括____。","options":[{"key":"A","text":"十二本纪"},{"key":"B","text":"八志"},{"key":"C","text":"十表"},{"key":"D","text":"三十世家"}],"answer":["B"],"explanation":"《史记》是中国的一部纪传体通史，被人们称为信史，由西汉武帝时期的司马迁花了13年的时间所写成的。全书共一百三十卷，约五十二万六千五百字，有十表、八书、十二本纪、三十世家、七十列传。"},{"id":1024,"type":"单选题","text":"贾谊的作品不包括____。","options":[{"key":"A","text":"《新书》"},{"key":"B","text":"《论贵粟疏》"},{"key":"C","text":"《治安策》"},{"key":"D","text":"《论积贮疏》"}],"answer":["B"],"explanation":"《论贵粟疏》是汉代大臣晁错的文章，出自《汉书·食货志》，是当时给汉文帝的奏疏。文章全面论述了“贵粟”（重视粮食）的重要性，提出重农抑商、入粟于官、拜爵除罪等一系列主张。"},{"id":1025,"type":"单选题","text":"顾况诗歌的特点不包括____。","options":[{"key":"A","text":"受民歌影响"},{"key":"B","text":"通俗明快"},{"key":"C","text":"有怪奇风格"},{"key":"D","text":"高雅闲淡"}],"answer":["D"],"explanation":"顾况诗歌的特点包括受民歌影响、通俗明快、有怪奇风格。"},{"id":1026,"type":"单选题","text":"柳宗元的诗歌主要包括____。","options":[{"key":"A","text":"山水田园诗与贬谪抒怀诗"},{"key":"B","text":"边塞征战诗与咏史怀古诗"},{"key":"C","text":"宫廷应制诗与咏物诗"},{"key":"D","text":"闺怨诗与送别诗"}],"answer":["A"],"explanation":"柳宗元的诗作大部分作于贬官的永州、柳州时期。他诗作的重要内容就是抒写被贬谪的抑郁悲伤和思乡之情。柳宗元在贬谪期间也写过一些山水田园诗，并且试图以清静幽寂的自然境界来净化心灵，从而消除现实郁闷。"},{"id":1027,"type":"单选题","text":"《孔雀东南飞》的男女主人公是____。","options":[{"key":"A","text":"梁山伯与祝英台"},{"key":"B","text":"牛郎与织女"},{"key":"C","text":"焦仲卿与刘兰芝"},{"key":"D","text":"许仙与白娘子"}],"answer":["C"],"explanation":"《孔雀东南飞》的男主是焦仲卿,女主是刘兰芝。"},{"id":1028,"type":"单选题","text":"下列东汉乐府诗歌属乐府民歌中的爱情题材不包括____。","options":[{"key":"A","text":"《艳歌行》"},{"key":"B","text":"《上邪》"},{"key":"C","text":"《有所思》"},{"key":"D","text":"《江南》"}],"answer":["A"],"explanation":"《艳歌行》是汉代乐府古辞，属《相和歌辞·瑟调曲》。此诗写游子思乡。一个普通的家庭“兄弟两三人”为了生计，流浪他乡。因女主人为他们缝补衣裳而被归来的女主人丈夫发现而产生了误会。"},{"id":1029,"type":"单选题","text":"字写得是否漂亮，与毛笔的质量有直接的关系，毛笔的质量不包括____。","options":[{"key":"A","text":"尖"},{"key":"B","text":"齐"},{"key":"C","text":"圆"},{"key":"D","text":"粗"}],"answer":["D"],"explanation":"判断毛笔的质量主要在以下几个方面：笔有“四德”，即“尖、齐、圆、健”。"},{"id":1030,"type":"单选题","text":"下列作品属曹植的有____。","options":[{"key":"A","text":"《赠白马王彪》"},{"key":"B","text":"《蒿里行》"},{"key":"C","text":"《桃花源记》"},{"key":"D","text":"《山居秋暝》"}],"answer":["A"],"explanation":"《赠白马王彪》是曹植的重要诗作，写于其兄曹丕称帝后，因与白马王曹彪分别而作，诗中充满了对兄弟离散、政治压抑的悲愤，情感真挚深沉。B 项《蒿里行》是曹操的作品；C 项《桃花源记》是陶渊明的散文；D 项《山居秋暝》是王维的山水诗，故排除。"},{"id":1031,"type":"单选题","text":"下列作家属\"元嘉三大家”的有____。","options":[{"key":"A","text":"陶渊明"},{"key":"B","text":"谢灵运"},{"key":"C","text":"李白"},{"key":"D","text":"杜甫"}],"answer":["B"],"explanation":"“元嘉三大家” 是指南朝宋文帝元嘉年间的三位著名诗人，分别是谢灵运、颜延之、鲍照。"},{"id":1032,"type":"单选题","text":"“北地三才”指的是____。","options":[{"key":"A","text":"曹操、曹丕、曹植"},{"key":"B","text":"苏洵、苏轼、苏辙"},{"key":"C","text":"温子升、邢劭、魏收"},{"key":"D","text":"袁宗道、袁宏道、袁中道"}],"answer":["C"],"explanation":"北地三才，指在北朝文人中能自觉学习南朝文化，对南北文学的合流起到推动作用的作家温子昇、邢邵、魏收的并称。"},{"id":1033,"type":"单选题","text":"庾信的代表作是____。","options":[{"key":"A","text":"《哀江南赋》"},{"key":"B","text":"《两京赋》"},{"key":"C","text":"《三都赋》"},{"key":"D","text":"《赤壁赋》"}],"answer":["A"],"explanation":"庾信的辞赋与徐陵一起被称为“徐庾体”,代表作品有《怨歌行》、《杨柳歌》、《寄王琳》、《哀江南赋》等。"},{"id":1034,"type":"单选题","text":"骈文的主要特征不包括____。","options":[{"key":"A","text":"对偶"},{"key":"B","text":"夸饰"},{"key":"C","text":"用典"},{"key":"D","text":"声律"}],"answer":["B"],"explanation":"骈文的特点主要有：讲究声律的调谐、用字的绮丽、辞汇的对偶和用典。"},{"id":1035,"type":"单选题","text":"韩愈散文包括多种文体，其中不包括____。","options":[{"key":"A","text":"杂文"},{"key":"B","text":"赠序文"},{"key":"C","text":"稗志"},{"key":"D","text":"话本"}],"answer":["D"],"explanation":"韩愈散文包括多种文体，其中有杂文、赠序文、稗志和传记。"},{"id":1036,"type":"单选题","text":"下列说法错误的是____。","options":[{"key":"A","text":"《世说新语》记述了汉末至东晋的士族阶层的遗闻轶事，特别是士族人物的清谈"},{"key":"B","text":"《世说新语》是中国魏晋南北朝时期“笔记小说”的代表作"},{"key":"C","text":"《世说新语》的作者是干宝"},{"key":"D","text":"《世说新语》是一部志人小说"}],"answer":["C"],"explanation":"C选项《世说新语》的作者是刘义庆。"},{"id":1037,"type":"单选题","text":"下列句中名词作状语的不包括____。","options":[{"key":"A","text":"秦惠王车裂商君以徇"},{"key":"B","text":"既东封郑"},{"key":"C","text":"齐桓公合诸侯而国异姓"},{"key":"D","text":"其一犬坐于前"}],"answer":["C"],"explanation":"A选项，车裂是名词做状语，用车裂的刑罚。B选项，方位名词“东”作动词“封”的状语，表处所：在东边。D选项，犬是名词做状语，像狗一样。"},{"id":1038,"type":"单选题","text":"下列作品不属于岑参的有____。","options":[{"key":"A","text":"《白雪歌送武判官归京》"},{"key":"B","text":"《走马川行奉送出师西征》"},{"key":"C","text":"《燕歌行》（汉家烟尘）"},{"key":"D","text":"《逢人京使》"}],"answer":["C"],"explanation":"《燕歌行》（汉家烟尘）为高适作品。"},{"id":1039,"type":"单选题","text":"下列不属于李白的作品有____。","options":[{"key":"A","text":"《蜀道难》"},{"key":"B","text":"《登高》"},{"key":"C","text":"《行路难》（金樽清酒斗十千）"},{"key":"D","text":"《将进酒君不见）"}],"answer":["B"],"explanation":"《登高》是唐代诗人杜甫的诗作。故排除B选项。"},{"id":1040,"type":"单选题","text":"下列不属于杜甫的作品有____。","options":[{"key":"A","text":"《自京赴奉先县咏怀五百字》"},{"key":"B","text":"“三吏”、“三别”"},{"key":"C","text":"《梦游天姥吟留别》"},{"key":"D","text":"《茅屋为秋风所破歌》"}],"answer":["C"],"explanation":"《梦游天姥吟留别》是唐代诗人李白的诗作。故排除C选项。"},{"id":1041,"type":"单选题","text":"明清之际对君主专制展开猛烈批判的启蒙思潮代表⼈物有____。","options":[{"key":"A","text":"王阳明"},{"key":"B","text":"黄宗羲"},{"key":"C","text":"朱熹"},{"key":"D","text":"董仲舒"}],"answer":["B"],"explanation":"黄宗羲是明清之际启蒙思想家，在《明夷待访录》中猛烈批判君主专制，提出 “天下为主，君为客” 的主张，是该思潮的代表人物。"},{"id":1042,"type":"单选题","text":"下列作家不属于中唐的有____。","options":[{"key":"A","text":"李商隐"},{"key":"B","text":"刘禹锡"},{"key":"C","text":"韩愈"},{"key":"D","text":"元稹"}],"answer":["A"],"explanation":"李商隐为唐末的著名诗人，并非中唐时期。"},{"id":1043,"type":"单选题","text":"下列不属于“元白诗派“的有____。","options":[{"key":"A","text":"元稹"},{"key":"B","text":"白居易"},{"key":"C","text":"姚合"},{"key":"D","text":"王建"}],"answer":["C"],"explanation":"元白诗派：重写实，尚通俗，主要代表人物是白居易、元稹、王建、张籍等。"},{"id":1044,"type":"单选题","text":"白居易把自己的诗歌分为四类，其中不包括____。","options":[{"key":"A","text":"讽喻诗"},{"key":"B","text":"乐府诗"},{"key":"C","text":"感伤诗"},{"key":"D","text":"闲适诗"}],"answer":["B"],"explanation":"白居易曾把自己的诗分为四类：讽喻诗、闲适诗、感伤诗、杂律诗。"},{"id":1045,"type":"单选题","text":"“韩孟诗派“的代表人物有____。","options":[{"key":"A","text":"孟郊"},{"key":"B","text":"白居易"},{"key":"C","text":"元稹"},{"key":"D","text":"刘禹锡"}],"answer":["A"],"explanation":"“韩孟诗派”是中唐的一个诗歌创作流派,以韩愈为领袖,代表人物还有孟郊、李贺、卢仝、马异、刘叉等人。"},{"id":1046,"type":"单选题","text":"下列作品不属于韩愈的有____。","options":[{"key":"A","text":"《师说》"},{"key":"B","text":"《送孟东野序》"},{"key":"C","text":"《小石潭记》"},{"key":"D","text":"《杂说》"}],"answer":["C"],"explanation":"《小石潭记》是唐朝诗人柳宗元的作品。"},{"id":1047,"type":"单选题","text":"下列诗歌中属于李商隐作品的是____。","options":[{"key":"A","text":"《登高》"},{"key":"B","text":"《无题・相见时难别亦难》"},{"key":"C","text":"《琵琶行》"},{"key":"D","text":"《静夜思》"}],"answer":["B"],"explanation":"B 项《无题・相见时难别亦难》是李商隐的经典 “无题诗”，以隐晦的语言抒发爱情与仕途的失意，是晚唐无题诗的代表"},{"id":1048,"type":"单选题","text":"晚唐继承新乐府写实批判精神的诗人有____。","options":[{"key":"A","text":"杜牧"},{"key":"B","text":"李商隐"},{"key":"C","text":"皮日休"},{"key":"D","text":"温庭筠"}],"answer":["C"],"explanation":"除了皮日休,继承元、白新乐府写实批判精神的晚唐诗人,还有聂夷中(837--884)、杜荀鹤(846--907)、罗隐(833--909)等,他们忧时忧民,用诗歌揭露尖锐的社会矛盾,语言质朴浅近。"},{"id":1049,"type":"单选题","text":"宋初诗坛流行的诗歌流派不包括____。","options":[{"key":"A","text":"白体"},{"key":"B","text":"西昆体"},{"key":"C","text":"晚唐体"},{"key":"D","text":"馆阁体"}],"answer":["D"],"explanation":"宋初诗派林立,但主要有白体、西昆体、晚唐体三派。"},{"id":1050,"type":"单选题","text":"下列作家不属于北宋初期的有____。","options":[{"key":"A","text":"柳开"},{"key":"B","text":"王禹僵"},{"key":"C","text":"杨亿"},{"key":"D","text":"白居易"}],"answer":["D"],"explanation":"白居易是唐代伟大的现实主义诗人，故排除D选项。"},{"id":1051,"type":"单选题","text":"江西诗派“一祖三宗”中的“三宗”不包括____。","options":[{"key":"A","text":"陈与义"},{"key":"B","text":"黄庭坚"},{"key":"C","text":"杜甫"},{"key":"D","text":"陈师道"}],"answer":["C"],"explanation":"江西诗派有“一祖三宗”之说,其中“一祖”是指杜甫,而“三宗”是指黄庭坚、陈师道、陈与义三人。江西诗派强调的特点是“点石成金”和“夺胎换骨”。"},{"id":1052,"type":"单选题","text":"黄庭坚著名的文论观点有____。","options":[{"key":"A","text":"“点铁成金”"},{"key":"B","text":"“文章合为时而著”"},{"key":"C","text":"“惟陈言之务去”"},{"key":"D","text":"“诗中有画”"}],"answer":["A"],"explanation":"A 项 “点铁成金” 是黄庭坚的核心文论观点，意为借用古人的诗意、典故，经过改造创新，使作品 “化腐朽为神奇”，是江西诗派的重要创作原则；B 项是白居易的主张；C 项是韩愈的主张；D 项是苏轼对王维的评价，故答案为 A。"},{"id":1053,"type":"单选题","text":"下列关于苏轼的描述错误的是____。","options":[{"key":"A","text":"宋代文学发展到巅峰时期的伟大代表作家"},{"key":"B","text":"宋代古文家里最重视“文”的一位"},{"key":"C","text":"苏轼是婉约派的代表词人"},{"key":"D","text":"对宋诗能别开生面起关键作用的作家"}],"answer":["C"],"explanation":"苏轼代表的是豪放派。"},{"id":1054,"type":"单选题","text":"下列作家中，属于南宋“中兴四大诗人”的有____。","options":[{"key":"A","text":"苏轼"},{"key":"B","text":"陆游"},{"key":"C","text":"黄庭坚"},{"key":"D","text":"柳永"}],"answer":["B"],"explanation":"南宋“中兴四大诗人”包括尤袤、杨万里、范成大、陆游。"},{"id":1055,"type":"单选题","text":"下列著作属于陆游的有____。","options":[{"key":"A","text":"《漱玉词》"},{"key":"B","text":"《剑南诗稿》"},{"key":"C","text":"《容斋随笔》"},{"key":"D","text":"《稼轩长短句》"}],"answer":["B"],"explanation":"B 项《剑南诗稿》是陆游的诗集，收录其诗歌九千余首，内容涵盖家国情怀、田园生活等，是陆游诗歌成就的集中体现。"},{"id":1056,"type":"单选题","text":"下列作家属于辛派词人的有____。","options":[{"key":"A","text":"李清照"},{"key":"B","text":"姜夔"},{"key":"C","text":"刘过"},{"key":"D","text":"柳永"}],"answer":["C"],"explanation":"辛派词人指的是南渡前后词风与辛弃疾相似或相近的作家。既包括早于辛弃疾的南渡初期作家张元干、颖孝祥等，也包括和辛弃疾同时或后于辛弃疾在作词方面追步辛弃疾的作家陈亮、刘过等人。"},{"id":1057,"type":"单选题","text":"下列关于吴文英的描述错误的是____。","options":[{"key":"A","text":"《梦窗词》的作者"},{"key":"B","text":"在南宋词坛与辛弃疾、姜夔鼎足而三的作家"},{"key":"C","text":"在讲究字面漂亮和章法绵密方面，是周邦彦的继承者"},{"key":"D","text":"是姜夔的羽翼"}],"answer":["D"],"explanation":"D项史达祖可称姜夔的羽翼。"},{"id":1058,"type":"单选题","text":"楚⽂化的特点有____。","options":[{"key":"A","text":"以儒家思想为核心，强调礼乐秩序"},{"key":"B","text":"浪漫奔放，重视巫鬼文化与自然崇拜"},{"key":"C","text":"以农耕为唯一经济基础，排斥商业"},{"key":"D","text":"艺术风格质朴厚重，与中原文化完全一致"}],"answer":["B"],"explanation":"楚文化具有浪漫奔放的特质，如屈原《楚辞》中的奇幻想象，且重视巫鬼祭祀（如《九歌》是祭祀乐歌）、自然崇拜（如对日月、山川的崇拜）"},{"id":1059,"type":"单选题","text":"下列关于关汉卿的描述错误的是____。","options":[{"key":"A","text":"元杂剧最优秀的代表作家"},{"key":"B","text":"由金人元的作家"},{"key":"C","text":"历史剧《赵氏孤儿》的作者"},{"key":"D","text":"元代杂剧作家申创作数量最多的作家"}],"answer":["C"],"explanation":"《赵氏孤儿》是元代纪君祥创作的杂剧，是元代四大悲剧之一。"},{"id":1060,"type":"单选题","text":"下列作品用到比兴手法的是____。","options":[{"key":"A","text":"《桃夭》"},{"key":"B","text":"《离骚》"},{"key":"C","text":"《喻老》"},{"key":"D","text":"《关雎》"}],"answer":["C"],"explanation":"《韩非子·喻老》出自《韩非子》。在短篇幅中，用二十五则历史故事和民间传说分别解释了《老子》十二章，其中《德经》八章、《道经》四章，使《老子》抽象的哲学思想有了具体可感的呈现，在中国哲学史和训诂学史上起着发凡起例的作用，同时也使他的刑名法术之学有了比较精深的理论凭藉。《弹歌》为上古歌谣。"},{"id":1061,"type":"单选题","text":"下列作品中元代四大传奇有____。","options":[{"key":"A","text":"《拜月亭》"},{"key":"B","text":"《牡丹亭》"},{"key":"C","text":"《桃花扇》"},{"key":"D","text":"《长生殿》"}],"answer":["A"],"explanation":"元代四大传奇包括《荆钗记》、《拜月亭记》、《白兔记》、《杀狗记》，时人以传奇称之。"},{"id":1062,"type":"单选题","text":"中国戏曲角色的基本行不包括____。","options":[{"key":"A","text":"生"},{"key":"B","text":"旦"},{"key":"C","text":"净"},{"key":"D","text":"末"}],"answer":["D"],"explanation":"戏曲行当的名称。戏曲角色的分行十分细致，早先分为十行，后来才归并为生旦净丑四行。"},{"id":1063,"type":"单选题","text":"韩愈古文运动的理论主张不包括____。","options":[{"key":"A","text":"文以明道"},{"key":"B","text":"惟陈言之务去"},{"key":"C","text":"不平则鸣"},{"key":"D","text":"用事绵密"}],"answer":["D"],"explanation":"韩愈在贞元九年（793）所写的《争臣论》中，第一次提出“文以明道”的观念，从而确定了“古文”创作的指导思想。从“明道”的要求出发，韩愈特别强调“惟陈言之务去”的重要性。在具体的创作实践中，他又提出了“不平则鸣”（《送孟东野序》）的口号。这一看法，把“明道”与对现实的批判联系了起来。"},{"id":1064,"type":"单选题","text":"唐代传奇在艺术上的主要特点有____。","options":[{"key":"A","text":"以志怪为主，情节简单"},{"key":"B","text":"情节完整曲折，人物形象鲜明"},{"key":"C","text":"语言质朴，多为口语化"},{"key":"D","text":"以四言为主，句式整齐"}],"answer":["B"],"explanation":"唐代传奇标志着中国古代小说的成熟，艺术上突破了此前志怪小说 “粗陈梗概” 的局限。B 项 “情节完整曲折，人物形象鲜明” 是其核心特点，如《柳毅传》《莺莺传》等，都有复杂的情节与鲜活的人物；A 项是魏晋南北朝志怪小说的特点；C 项 “口语化” 多为宋元话本的特点；D 项 “四言为主” 是《诗经》等早期文学的语言特征。"},{"id":1065,"type":"单选题","text":"北宋瓦舍表演中，最能体现市民⼝味的表演形式包括蹴鞠和____。","options":[{"key":"A","text":"武术"},{"key":"B","text":"⽪影"},{"key":"C","text":"杂剧"},{"key":"D","text":"雅乐"}],"answer":["C"],"explanation":"瓦舍勾栏是当时市民娱乐时候最主要去的场所,也是宋朝市民文化兴盛的一种体现。瓦舍勾栏时演出的内容很多,形式也多种多样,主要有说唱、戏剧、杂技和武术等等。"},{"id":1066,"type":"单选题","text":"李贺诗歌的艺术特点包括____。","options":[{"key":"A","text":"语言浅近，通俗易懂"},{"key":"B","text":"风格沉郁顿挫，忧国忧民"},{"key":"C","text":"想象奇特，善用神话意象，风格奇崛"},{"key":"D","text":"风格豪放飘逸，充满浪漫主义色彩"}],"answer":["C"],"explanation":"李贺被称为 “诗鬼”，其诗歌最突出的特点是想象奇特，常借用神话传说、鬼魅意象，风格奇崛冷艳。C 项符合其特点；A 项是白居易新乐府诗的特点；B 项是杜甫诗歌的特点；D 项是李白诗歌的特点。"},{"id":1067,"type":"单选题","text":"19世纪末以来中国文化在现代化的过程中，文化思潮的互动不包括？","options":[{"key":"A","text":"全盘西化论"},{"key":"B","text":"中体西化论"},{"key":"C","text":"综合创新论"},{"key":"D","text":"儒学复兴论与综合创新论"}],"answer":["C"],"explanation":"综合创新论是多民族文化融合与中外文化交汇。这并不是中国文化在现代化的思潮互动。"},{"id":1068,"type":"单选题","text":"下列人物不属于《桃花扇》的有____。","options":[{"key":"A","text":"李香君"},{"key":"B","text":"席方平"},{"key":"C","text":"阮大铖"},{"key":"D","text":"侯方域"}],"answer":["B"],"explanation":"《席方平》是清代文学家蒲松龄创作的文言短篇小说，席方平是其主人公。"},{"id":1069,"type":"单选题","text":"下列戏剧大家不属于清代前期的有____。","options":[{"key":"A","text":"李玉"},{"key":"B","text":"李渔"},{"key":"C","text":"洪昇"},{"key":"D","text":"汤显祖"}],"answer":["D"],"explanation":"汤显祖是中国明代戏曲家、文学家。"},{"id":1070,"type":"单选题","text":"下列戏剧著作属于洪昇的有____。","options":[{"key":"A","text":"《桃花扇》"},{"key":"B","text":"《长生殿》"},{"key":"C","text":"《牡丹亭》"},{"key":"D","text":"《西厢记》"}],"answer":["B"],"explanation":"洪昇是清代前期的传奇大家，其代表作《长生殿》以唐玄宗与杨玉环的爱情故事为核心，融合历史兴亡之感。B 项正确；A 项《桃花扇》作者是孔尚任；C 项《牡丹亭》作者是汤显祖；D 项《西厢记》作者是王实甫。"},{"id":1071,"type":"单选题","text":"下列作家不属于桐城派的有____。","options":[{"key":"A","text":"陈维崧"},{"key":"B","text":"姚鼐"},{"key":"C","text":"方苞"},{"key":"D","text":"刘大櫆"}],"answer":["A"],"explanation":"姚鼐与方苞、刘大櫆并称为“桐城派三祖”。"},{"id":1072,"type":"单选题","text":"“文”的本义是指各色交错的纹理，其后来的引申意义有____。","options":[{"key":"A","text":"文章、文献"},{"key":"B","text":"武器、战争"},{"key":"C","text":"粮食、作物"},{"key":"D","text":"房屋、建筑"}],"answer":["A"],"explanation":"“文” 的本义是 “纹理”，后因 “纹理” 有 “条理、装饰” 之义，逐渐引申为与 “文字、文章” 相关的含义，如 “文辞”“文献”。A 项正确；B 项 “武器、战争” 与 “武” 的含义相关；C 项 “粮食、作物” 与 “禾”“谷” 等字相关；D 项 “房屋、建筑” 与 “宅”“宇” 等字相关，均非 “文” 的引申义。"},{"id":1073,"type":"单选题","text":"我国新石器文化最集中、最有代表性的区域是____。","options":[{"key":"A","text":"黄河流域和长江流域"},{"key":"B","text":"珠江流域和黑龙江流域"},{"key":"C","text":"塔里木河流域和淮河流域"},{"key":"D","text":"雅鲁藏布江流域和澜沧江流域"}],"answer":["A"],"explanation":"我国新石器文化最集中、最有代表性的区域是黄河流域、长江流域。"},{"id":1074,"type":"单选题","text":"夏商周时期中国传统文化的主要标志不包括____。","options":[{"key":"A","text":"创造了甲骨文与金文"},{"key":"B","text":"宗法制度和家国同构政治结构的形成"},{"key":"C","text":"诸子蜂起，百家争鸣"},{"key":"D","text":"初步形成传统伦理道德思想"}],"answer":["C"],"explanation":"诸子蜂起，百家争鸣不是夏商周时期中国传统文化的主要标志。"},{"id":1075,"type":"单选题","text":"秦汉科技方面的主要成果不包括____。","options":[{"key":"A","text":"造纸术"},{"key":"B","text":"《甘石星经》"},{"key":"C","text":"《氾胜之书》"},{"key":"D","text":"《九章算术》"}],"answer":["B"],"explanation":"《甘石星经》不是秦汉科技方面的主要成果。《甘石星经》是一部天文学专著，甘经、石经各八卷，共十六卷，大致成书于战国时期。"},{"id":1076,"type":"单选题","text":"魏晋南北朝时期中国传统文化的主要标志是____。","options":[{"key":"A","text":"中央集权强化、科举制完善"},{"key":"B","text":"玄学兴起、佛教传播、书法艺术成熟"},{"key":"C","text":"理学形成、宋词兴盛"},{"key":"D","text":"小说繁荣、戏曲成熟"}],"answer":["B"],"explanation":"魏晋南北朝时期的传统文化标志：玄学兴起（以老庄思想为核心，如王弼、郭象）、佛教传入后广泛传播（如石窟艺术兴起）、书法艺术成熟（如王羲之《兰亭集序》，楷书、行书定型）。B 项正确；A 项中央集权强化、科举制完善在隋唐；C 项理学形成、宋词兴盛在宋代；D 项小说繁荣、戏曲成熟在明清，均不属于魏晋南北朝时期。"},{"id":1077,"type":"单选题","text":"魏晋南北朝时期文学成就的主要标志不包括____。","options":[{"key":"A","text":"以曹操父子、建安七子为代表的建安文学"},{"key":"B","text":"陶渊明为代表的田园、山水诗"},{"key":"C","text":"赋与五言古诗"},{"key":"D","text":"刘勰《文心雕龙》为代表的文学评论"}],"answer":["C"],"explanation":"赋与五言古诗不是魏晋南北朝时期文学成就的主要标志。"},{"id":1078,"type":"单选题","text":"魏晋南北朝时期科技成就的主要标志有____。","options":[{"key":"A","text":"造纸术发明、火药应用"},{"key":"B","text":"《齐民要术》（贾思勰）、《水经注》（郦道元）、祖冲之计算圆周率"},{"key":"C","text":"活字印刷术发明、指南针应用"},{"key":"D","text":"《本草纲目》问世、地动仪发明"}],"answer":["B"],"explanation":"魏晋南北朝科技成就：北魏贾思勰《齐民要术》是中国现存最早的农书；北魏郦道元《水经注》是地理学专著；南朝祖冲之将圆周率计算到小数点后七位，领先世界。B 项正确；A 项造纸术发明于汉代，火药应用于唐代；C 项活字印刷术、指南针应用于宋代；D 项《本草纲目》是明代著作，地动仪发明于东汉，均不符合时期。"},{"id":1079,"type":"单选题","text":"下列不属于中国古代儿童识字教材的有____。","options":[{"key":"A","text":"《三字经》"},{"key":"B","text":"《百家姓》"},{"key":"C","text":"《千字文》"},{"key":"D","text":"《诗经》"}],"answer":["D"],"explanation":"我国古代儿童启蒙教育都是从《百家姓》，《三字经》，《千字文》开始。"},{"id":1080,"type":"单选题","text":"宋代最突出的科技成果发明不包括？","options":[{"key":"A","text":"造纸术"},{"key":"B","text":"指南针"},{"key":"C","text":"印刷术"},{"key":"D","text":"火药武器"}],"answer":["A"],"explanation":"造纸术不是宋代的科技成果。"},{"id":1081,"type":"单选题","text":"明代至清代中期（1840年前）的科技成果主要有____。","options":[{"key":"A","text":"《本草纲目》（李时珍）、《农政全书》（徐光启）、《天工开物》（宋应星）"},{"key":"B","text":"活字印刷术、指南针"},{"key":"C","text":"火药、造纸术"},{"key":"D","text":"《齐民要术》、地动仪"}],"answer":["A"],"explanation":"明代至清代中期的科技成果：明代李时珍《本草纲目》是药物学巨著；明代徐光启《农政全书》是农学名著；明代宋应星《天工开物》是手工业技术专著。A 项正确；B 项活字印刷术、指南针在宋代；C 项火药、造纸术在唐、汉；D 项《齐民要术》是北魏著作，地动仪是东汉发明，均不符合时期。"},{"id":1082,"type":"单选题","text":"中国古人避讳的方式有____。","options":[{"key":"A","text":"改字、空字、缺笔"},{"key":"B","text":"改姓、改名、改籍贯"},{"key":"C","text":"改官职、改年号、改地名"},{"key":"D","text":"改日期、改服饰、改礼仪"}],"answer":["A"],"explanation":"避讳的方法有四种：\n1. 改字法：就是把帝王及所尊者之名改用其他同义字或同音字来代替。\n2. 空字法：即将应避讳的字空而不书，或作“某”，或作“口”。\n3. 缺笔法：即对所避之字少写一笔。但少写的一笔在什么地方是有严格规定的。\n4. 改音法：就是读书时遇到讳字，应改变声调或读别的字音。"},{"id":1083,"type":"单选题","text":"明代至清代中期（1840年前）的主要图书典籍不包括____。","options":[{"key":"A","text":"《永乐大典》"},{"key":"B","text":"《康熙字典》"},{"key":"C","text":"《本草纲目》"},{"key":"D","text":"《四库全书》"}],"answer":["C"],"explanation":"明代至清代中期（ 1840 年前）的图书典籍不包括《本草纲目》。"},{"id":1084,"type":"单选题","text":"中国传统人本主义精神不包括____层次。","options":[{"key":"A","text":"以民为本"},{"key":"B","text":"重人伦远鬼神"},{"key":"C","text":"“人文”精神"},{"key":"D","text":"肯定个体的心性向善"}],"answer":["C"],"explanation":"中国传统人本主义精神不包括“人文”精神层次。"},{"id":1085,"type":"单选题","text":"中国传统文化的基本特征有____。","options":[{"key":"A","text":"伦理中心、天人合一、注重整体、务实精神"},{"key":"B","text":"宗教主导、个人主义、注重个体、冒险精神"},{"key":"C","text":"科技主导、理性主义、注重分析、创新精神"},{"key":"D","text":"商业主导、利益至上、注重竞争、开放精神"}],"answer":["A"],"explanation":"中国传统文化的基本特征：伦理中心（以儒家伦理为核心，如 “三纲五常”）、天人合一（强调人与自然和谐，如儒家 “仁者乐山，智者乐水”、道家 “道法自然”）、注重整体（如中医的整体观、哲学的 “阴阳五行” 整体思维）、务实精神（如儒家重视现实生活，反对空谈）。A 项正确；其他选项中的 “宗教主导”“科技主导”“商业主导” 均不符合中国传统文化的核心特征。"},{"id":1086,"type":"单选题","text":"《周易》建构了中国伦理精神的原初的哲学模式，即____。","options":[{"key":"A","text":"阴阳五行模式"},{"key":"B","text":"天人合一模式"},{"key":"C","text":"性善论模式"},{"key":"D","text":"因果报应模式"}],"answer":["B"],"explanation":"《周易》的核心思想是 “天人合一”，认为天、地、人三者相互关联、和谐统一，这种思维模式为中国伦理精神奠定了哲学基础 —— 伦理规范需符合 “天道”，如 “天行健，君子以自强不息”“地势坤，君子以厚德载物”。B 项正确；A 项 “阴阳五行” 是战国时期发展的学说；C 项 “性善论” 是孟子的观点；D 项 “因果报应” 是佛教传入后影响的观念，均非《周易》建构的原初哲学模式。"},{"id":1087,"type":"单选题","text":"孟子的“四端”包括人性天然就具有的____。","options":[{"key":"A","text":"仁、义、礼、信"},{"key":"B","text":"忠、孝、节、义"},{"key":"C","text":"仁、义、礼、智"},{"key":"D","text":"温、良、恭、俭"}],"answer":["C"],"explanation":"孟子提出 “性善论”，认为人性本善，“四端” 是人性中天然具有的善的萌芽，即 “恻隐之心，仁之端也；羞恶之心，义之端也；辞让之心，礼之端也；是非之心，智之端也”，对应 “仁、义、礼、智”。"},{"id":1088,"type":"单选题","text":"法家的主要代表著作有____。","options":[{"key":"A","text":"《老子》《庄子》"},{"key":"B","text":"《墨子》《吕氏春秋》"},{"key":"C","text":"《韩非子》《商君书》"},{"key":"D","text":"《论语》《孟子》"}],"answer":["C"],"explanation":"法家的主要代表著作有《商君书》、《韩非子》。"},{"id":1089,"type":"单选题","text":"王充的主要哲学观点有____。","options":[{"key":"A","text":"天人感应、君权神授"},{"key":"B","text":"元气自然论、批判谶纬神学"},{"key":"C","text":"性善论、仁政思想"},{"key":"D","text":"心外无物、知行合一"}],"answer":["B"],"explanation":"王充是东汉唯物主义思想家，其主要哲学观点：元气自然论（认为世界由 “元气” 构成，万物自然生成，否定 “神创论”）、批判谶纬神学（反对汉代流行的迷信思想，如 “天人感应”“祥瑞灾异”，著有《论衡》）。B 项正确；A 项 “天人感应、君权神授” 是董仲舒的观点；C 项 “性善论、仁政思想” 是孟子的观点；D 项 “心外无物、知行合一” 是王阳明的观点。"},{"id":1090,"type":"单选题","text":"王夫之的主要哲学著作不包括____。","options":[{"key":"A","text":"《周易外传》"},{"key":"B","text":"《尚书引义》"},{"key":"C","text":"《明儒学案》"},{"key":"D","text":"《读四书大全说》"}],"answer":["C"],"explanation":"《明儒学案》不是王夫之的哲学著作。"},{"id":1091,"type":"单选题","text":"董仲舒天人感应说的要点有____。","options":[{"key":"A","text":"天与人相互独立，互不影响"},{"key":"B","text":"天是万物的主宰，人是天的副本，天能干预人事，人能感应上天"},{"key":"C","text":"世界由元气构成，万物自然生成"},{"key":"D","text":"心外无物，心外无理"}],"answer":["B"],"explanation":"董仲舒是西汉儒家代表，天人感应说的核心是：天是有意志的主宰，人是天的 “副本”（“人副天数”）；天通过 “祥瑞”（如嘉禾、麒麟）奖励君主的善政，通过 “灾异”（如地震、水灾）警示君主的过失，即 “天能干预人事，人能感应上天”。B 项正确；A 项是唯物主义观点，与董仲舒不符；C 项是王充的元气自然论；D 项是王阳明的唯心主义观点。"},{"id":1092,"type":"单选题","text":"人本主义精神主要不包括____层次。","options":[{"key":"A","text":"以民为本"},{"key":"B","text":"重人伦远鬼神"},{"key":"C","text":"肯定个体的心性向善"},{"key":"D","text":"重义轻利"}],"answer":["D"],"explanation":"人本主义精神不包括重义轻利层次。"},{"id":1093,"type":"单选题","text":"春秋战国时期文学领域的主要成就不包括____。","options":[{"key":"A","text":"《诗经》"},{"key":"B","text":"《楚辞》"},{"key":"C","text":"诸子百家的著作"},{"key":"D","text":"乐府诗"}],"answer":["D"],"explanation":"春秋战国时期文学领域的成就不包括乐府诗。"},{"id":1094,"type":"单选题","text":"汉语共同语在不同的时代有着不同的称谓，下列属于共同语别称的有____。","options":[{"key":"A","text":"雅言"},{"key":"B","text":"方言"},{"key":"C","text":"土语"},{"key":"D","text":"俚语"}],"answer":["A"],"explanation":"汉语共同语在不同时代有特定称谓，如先秦时期称 “雅言”，汉代称 “通语”，明清称 “官话” 等。B、C、D 均指某一地区的地方语言，不属于共同语别称，故排除。"},{"id":1095,"type":"单选题","text":"魏晋南北朝时期文学领域的主要成就不包括____。","options":[{"key":"A","text":"曹操父子、建安七子为代表的建安文学"},{"key":"B","text":"陶渊明为代表的田园、山水诗"},{"key":"C","text":"乐府诗"},{"key":"D","text":"刘勰《文心雕龙》为代表的文学评论"}],"answer":["C"],"explanation":"魏晋南北朝时期文学领域的成果不包括乐府诗。"},{"id":1096,"type":"单选题","text":"魏晋南北朝时期科技领域的主要成果不包括____。","options":[{"key":"A","text":"刘徽的《九章算术注》"},{"key":"B","text":"祖冲之计算出的圆周率和编制的《大明历》"},{"key":"C","text":"造纸术"},{"key":"D","text":"贾思勰的《齐民要术》"}],"answer":["C"],"explanation":"魏晋南北朝时期科技领域的成果不包括造纸术。"},{"id":1097,"type":"单选题","text":"隋唐时期科技领域的重要成就主要有____。","options":[{"key":"A","text":"《本草纲目》编撰"},{"key":"B","text":"火药发明与应用"},{"key":"C","text":"《天工开物》问世"},{"key":"D","text":"地动仪发明"}],"answer":["B"],"explanation":"A 项《本草纲目》是明代李时珍的著作；C 项《天工开物》是明代宋应星的作品；D 项地动仪是东汉张衡发明。隋唐时期已发明火药，并开始应用于军事（如唐末火药箭），故选 B。"},{"id":1098,"type":"单选题","text":"孔子以后，孟子从主观能动的方面发挥了孔子的伦理思想，其中不包括____。","options":[{"key":"A","text":"五伦说"},{"key":"B","text":"性善论"},{"key":"C","text":"修养论"},{"key":"D","text":"义利合一说"}],"answer":["D"],"explanation":"孔子以后，孟子从主观能动的方面发挥了孔子的伦理思想，其中不包括义利合一说。"},{"id":1099,"type":"单选题","text":"宋元时期史学领域的代表作不包括____。","options":[{"key":"A","text":"《资治通鉴》"},{"key":"B","text":"《通鉴纪事本末》"},{"key":"C","text":"《通典》"},{"key":"D","text":"《文献通考》"}],"answer":["D"],"explanation":"《文献通考》不是宋元时期史学领域的代表作。"},{"id":1100,"type":"单选题","text":"董仲舒把人性分为三类，其中不包括____。","options":[{"key":"A","text":"“君子之性”"},{"key":"B","text":"“中民之性”"},{"key":"C","text":"“斗筲之性”"},{"key":"D","text":"“圣人之性”"}],"answer":["A"],"explanation":"董仲舒把人性分“中民之性” 、“斗筲之性”、“圣人之性”。"},{"id":1101,"type":"单选题","text":"中国优秀传统伦理道德规范包括____。","options":[{"key":"A","text":"损人利己"},{"key":"B","text":"诚实守信"},{"key":"C","text":"骄奢淫逸"},{"key":"D","text":"见利忘义"}],"answer":["B"],"explanation":"A、C、D 均为负面道德行为，与传统优秀伦理相悖。“诚实守信” 是中国传统伦理的核心规范之一（如孔子 “言必信，行必果”），贯穿儒家伦理体系，故选 B。"},{"id":1102,"type":"单选题","text":"孝悌之德的基本内容是____。","options":[{"key":"A","text":"尊敬师长、团结同学"},{"key":"B","text":"孝顺父母、友爱兄弟"},{"key":"C","text":"忠于君主、报效国家"},{"key":"D","text":"关爱他人、乐于助人"}],"answer":["B"],"explanation":"“孝” 指孝顺父母，“悌”（tì）指友爱兄长，二者是儒家伦理的基础（《论语・学而》：“孝悌也者，其为仁之本与”）。A、C、D 均不属于 “孝悌” 的核心内涵，故选 B。"},{"id":1103,"type":"单选题","text":"我国原始宗教有很多分野，总的来讲，主要不包括____。","options":[{"key":"A","text":"自然崇拜"},{"key":"B","text":"动植物崇拜"},{"key":"C","text":"图腾崇拜"},{"key":"D","text":"圣贤崇拜"}],"answer":["D"],"explanation":"我国原始宗教有很多分野，不包括圣贤崇拜。"},{"id":1104,"type":"单选题","text":"封建正统法律思想的内容主要有____。","options":[{"key":"A","text":"德主刑辅"},{"key":"B","text":"无为而治"},{"key":"C","text":"严刑峻法"},{"key":"D","text":"法律面前人人平等"}],"answer":["A"],"explanation":"B 项是道家治国思想，与 “正统法律思想” 无关；C 项是法家思想（如秦朝），非封建正统（封建正统以儒家为核心）；D 项是近代法治理念，古代封建法律无此原则。封建正统法律思想以儒家 “德治” 为核心，主张 “德主刑辅”（如董仲舒提出），故选 A。"},{"id":1105,"type":"单选题","text":"中国伦理思想体系的三大构成要素不包括____。","options":[{"key":"A","text":"人情"},{"key":"B","text":"人伦"},{"key":"C","text":"人道"},{"key":"D","text":"人性"}],"answer":["A"],"explanation":"中国伦理思想体系的三大构成要素是人伦、人道、人性。"},{"id":1106,"type":"单选题","text":"孔子将修身称为____。","options":[{"key":"A","text":"明明德"},{"key":"B","text":"克己复礼"},{"key":"C","text":"致良知"},{"key":"D","text":"知行合一"}],"answer":["B"],"explanation":"A “明明德” 出自《大学》，是宋代理学强调的修养目标；C “致良知”、D “知行合一” 均是王阳明的主张。孔子在《论语・颜渊》中提出 “克己复礼为仁”，“克己复礼” 即通过约束自身、遵守礼的规范来修身，故选 B。"},{"id":1107,"type":"单选题","text":"____是中国佛教石窟的代表。","options":[{"key":"A","text":"敦煌莫高窟"},{"key":"B","text":"云冈石窟"},{"key":"C","text":"龙门石窟"},{"key":"D","text":"以上都是"}],"answer":["D"],"explanation":"以上都正确。"},{"id":1108,"type":"单选题","text":"____不属于封建法律“八议”制度内容。","options":[{"key":"A","text":"议亲"},{"key":"B","text":"议贤"},{"key":"C","text":"议功"},{"key":"D","text":"议尊"}],"answer":["D"],"explanation":"“八议”为：一议亲，二议故，三议贤，四议能，五议功，六议贵，七议勤，八议宾。"},{"id":1109,"type":"单选题","text":"____不是《开皇律》确定的刑名。","options":[{"key":"A","text":"死刑"},{"key":"B","text":"流刑"},{"key":"C","text":"肉刑"},{"key":"D","text":"徒刑"}],"answer":["C"],"explanation":"《开皇律》删除了魏晋以来一些残酷的刑罚,确立了封建时代比较进步的五种刑名: 答 、杖、徒、流、死。"},{"id":1110,"type":"单选题","text":"玄学不以____为主要依据企图用道家学说调整失衡的社会关系和伦理关系，其宗旨是“贵无” ,崇尚自然。","options":[{"key":"A","text":"《孟子》"},{"key":"B","text":"《周易》"},{"key":"C","text":"《老子》"},{"key":"D","text":"《庄子》"}],"answer":["A"],"explanation":"玄学没有以《孟子》为主要依据企图用道家学说调整失衡的社会关系和伦理关系，其宗旨是“贵无” ,崇尚自然。"},{"id":1111,"type":"单选题","text":"中国传统文化的形成有两个重要的基础，即____。","options":[{"key":"A","text":"小农经济、中央集权"},{"key":"B","text":"小农经济、宗法制度"},{"key":"C","text":"商品经济、宗法制度"},{"key":"D","text":"商品经济、中央集权"}],"answer":["B"],"explanation":"中国传统文化的核心基础是经济与社会结构：经济上，小农经济（自给自足的农耕经济）是传统经济的主体，决定了文化的务实、保守特质；社会结构上，宗法制度（以血缘为核心的家族制度）是传统社会的骨架，决定了文化的伦理导向（如孝悌、等级）。A 中中央集权是政治制度，是文化的上层建筑；C、D 中商品经济非传统经济基础，故选 B。"},{"id":1112,"type":"单选题","text":"孔子对教师职业道德的要求有____。","options":[{"key":"A","text":"学而不厌，诲人不倦"},{"key":"B","text":"因材施教，有教无类"},{"key":"C","text":"为人师表，以身作则"},{"key":"D","text":"以上都是"}],"answer":["D"],"explanation":"以上都正确。"},{"id":1113,"type":"单选题","text":"《学记》与教育教学的原则无关的有____。","options":[{"key":"A","text":"预防性原则"},{"key":"B","text":"及时施教原则"},{"key":"C","text":"长善救失原则"},{"key":"D","text":"有教无类"}],"answer":["D"],"explanation":"有教无类出自《论语》。"},{"id":1114,"type":"单选题","text":"《学记》关于教学方法的内容不包括___。","options":[{"key":"A","text":"讲解法"},{"key":"B","text":"问答法"},{"key":"C","text":"讨论法"},{"key":"D","text":"练习法"}],"answer":["C"],"explanation":"《学记》概括的教学方法有：讲解法、问答法、练习法、类比法。"},{"id":1115,"type":"单选题","text":"朱子读书六法不包括____。","options":[{"key":"A","text":"循序渐进"},{"key":"B","text":"熟读精思"},{"key":"C","text":"虚心涵泳"},{"key":"D","text":"温故知新"}],"answer":["D"],"explanation":"循序渐进、熟读精思、虚心涵泳、切己体察、着紧用力、居敬持志是朱子读书六法。"},{"id":1116,"type":"单选题","text":"中国传统的中医学的基础理论包括____。","options":[{"key":"A","text":"四诊法"},{"key":"B","text":"阴阳五行学说"},{"key":"C","text":"针灸疗法"},{"key":"D","text":"本草学"}],"answer":["B"],"explanation":"A 四诊法（望、闻、问、切）是诊断方法；C 针灸疗法是治疗方法；D 本草学是药物学体系。阴阳五行学说是中医学的核心基础理论，贯穿生理、病理、诊断、治疗等所有领域（如 “阴阳平衡”“五行相生相克” 解释人体机能），故选 B。"},{"id":1117,"type":"单选题","text":"孟子存养式教学法的主要内容包括____。","options":[{"key":"A","text":"循序渐进、积少成多"},{"key":"B","text":"存心养性、深造自得"},{"key":"C","text":"知行合一、学以致用"},{"key":"D","text":"格物致知、穷理尽性"}],"answer":["B"],"explanation":"以上都正确。"},{"id":1118,"type":"单选题","text":"荀子积渐式教学法的内容不包括____。","options":[{"key":"A","text":"闻、见、知、行的教学审视过程"},{"key":"B","text":"虚壹而静，专心有恒"},{"key":"C","text":"解蔽救偏，兼陈中恒"},{"key":"D","text":"教亦多术"}],"answer":["D"],"explanation":"教亦多术是孟子存养式教学法的主要内容。"},{"id":1119,"type":"单选题","text":"中国古代最具特色的思维模式不包括____。","options":[{"key":"A","text":"整体思维"},{"key":"B","text":"抽象思维"},{"key":"C","text":"类比思维"},{"key":"D","text":"辩证思维"}],"answer":["B"],"explanation":"中国传统思维方式最有特色的是整体思维、直观思维、类比思维、辨证思维。"},{"id":1120,"type":"单选题","text":"孔子通过对春秋以前中国文化成果的总结，继承周公的思想，创造了以____为核心的一整套伦理思想体系。","options":[{"key":"A","text":"德"},{"key":"B","text":"道"},{"key":"C","text":"法"},{"key":"D","text":"仁"}],"answer":["D"],"explanation":"春秋时期,孔子通过对春秋以前中国文化成果的总结,成功地对中国社会的生活秩序进行了伦理化、道德化的提升,创造了以礼、仁、中庸为内核的伦理思想体系。"},{"id":1121,"type":"单选题","text":"李白的著名诗篇不包括____。","options":[{"key":"A","text":"《蜀道难》"},{"key":"B","text":"《梦游天姥吟留别》"},{"key":"C","text":"《将进酒》"},{"key":"D","text":"《丽人行》"}],"answer":["D"],"explanation":"《丽人行》是杜甫所作。"},{"id":1122,"type":"单选题","text":"近代_____被称为“四大谴责小说”。","options":[{"key":"A","text":"李宝嘉的《官场现形记》"},{"key":"B","text":"吴沃尧的《二十年目睹之怪现状》"},{"key":"C","text":"刘鹗的《老残游记》"},{"key":"D","text":"以上都是"}],"answer":["D"],"explanation":"以上都正确。"},{"id":1123,"type":"单选题","text":"中国传统的天文学包括____。","options":[{"key":"A","text":"历法制定"},{"key":"B","text":"行星观测"},{"key":"C","text":"星象占卜"},{"key":"D","text":"以上都是"}],"answer":["D"],"explanation":"中国传统天文学兼具实用性和政治性：实用性方面，包括制定历法（如农历，指导农业生产）、观测行星（记录日月食、彗星等）；政治性方面，包括星象占卜（认为星象与国运相关，如 “天人感应”）。三者均属于中国传统天文学的范畴，故选 D。"},{"id":1124,"type":"单选题","text":"唐代颜真卿的主要书法作品不包括____。","options":[{"key":"A","text":"《颜氏家庙碑》"},{"key":"B","text":"《多宝塔感应碑》"},{"key":"C","text":"《颜勤礼碑》"},{"key":"D","text":"《皇甫诞碑》"}],"answer":["D"],"explanation":"《皇甫诞碑》是欧阳询所书。"},{"id":1125,"type":"单选题","text":"欧阳询的主要书法作品不包括____。","options":[{"key":"A","text":"《九成宫醴泉铭》"},{"key":"B","text":"《卜商帖》"},{"key":"C","text":"《寒切贴》"},{"key":"D","text":"《皇甫诞碑》"}],"answer":["C"],"explanation":"《寒切贴》是王羲之所书。"},{"id":1126,"type":"单选题","text":"魏晋南北朝时期的著名史学家不包括____。","options":[{"key":"A","text":"陈寿"},{"key":"B","text":"裴松之"},{"key":"C","text":"荀悦"},{"key":"D","text":"范晔"}],"answer":["C"],"explanation":"荀悦是东汉史学家。"},{"id":1127,"type":"单选题","text":"北宋书法家米芾的传世墨迹主要有____。","options":[{"key":"A","text":"《蜀素帖》"},{"key":"B","text":"《兰亭序》"},{"key":"C","text":"《九成宫醴泉铭》"},{"key":"D","text":"《祭侄文稿》"}],"answer":["A"],"explanation":"B《兰亭序》（王羲之，东晋）；C《九成宫醴泉铭》（欧阳询，唐）；D《祭侄文稿》（颜真卿，唐）。米芾是北宋 “宋四家”（苏、黄、米、蔡）之一，其传世墨迹《蜀素帖》被誉为 “天下第八行书”，故选 A。"},{"id":1128,"type":"单选题","text":"元代赵孟頫的主要书法作品不包括____。","options":[{"key":"A","text":"《仇锷墓碑铭》"},{"key":"B","text":"《鹊华秋色图》"},{"key":"C","text":"《度人经》"},{"key":"D","text":"《兰亭十三跋》"}],"answer":["B"],"explanation":"《鹊华秋色图》属于赵孟頫的山水画。"},{"id":1129,"type":"单选题","text":"建于公元前3世纪的都江堰工程不包括以下哪个部分组成。","options":[{"key":"A","text":"大坝"},{"key":"B","text":"宝瓶口"},{"key":"C","text":"飞沙堰"},{"key":"D","text":"分水鱼嘴"}],"answer":["A"],"explanation":"都江堰主要由鱼嘴、飞沙堰、宝瓶口三大主体工程构成。"},{"id":1130,"type":"单选题","text":"我国汉代时的医学已有“四诊”的诊断技术，“四诊”指的是____。","options":[{"key":"A","text":"望、闻、问、切"},{"key":"B","text":"视、听、触、叩"},{"key":"C","text":"望、触、叩、听"},{"key":"D","text":"问、闻、查、验"}],"answer":["A"],"explanation":"“四诊法” 是汉代张仲景在《伤寒杂病论》中系统总结的诊断方法，包括望诊（观察面色、舌苔）、闻诊（听声音、闻气味）、问诊（询问症状、病史）、切诊（摸脉象）。B、C 是现代医学的物理诊断方法；D 是现代医学的诊断流程，故选 A。"},{"id":1131,"type":"单选题","text":"战国时期是先秦史学发展的繁荣时期， ____不是该时期留存于现在的史籍。","options":[{"key":"A","text":"《左传》"},{"key":"B","text":"《战国策》"},{"key":"C","text":"《春秋》"},{"key":"D","text":"《竹书纪年》"}],"answer":["C"],"explanation":"《春秋》不属于战国时期的作品。"},{"id":1132,"type":"单选题","text":"____不是宋元时期的薪金石学和考古学的代表性著作。","options":[{"key":"A","text":"欧阳修的《集古录》"},{"key":"B","text":"吴大临的《考古图》"},{"key":"C","text":"赵明诚的《金石录》"},{"key":"D","text":"裴秀所绘的《禹贡地域图》"}],"answer":["D"],"explanation":"裴秀是魏晋时期名臣。约在泰始四年至七年(268～271)，裴秀主编完成《禹贡地域图》18篇，它是中国有文献可考的最早的历史地图集，并在序言中提出了绘制地图的6项原则，即著名的“制图六体”，为中国传统地图（平面测量绘制的地图）奠定了理论基础。"},{"id":1133,"type":"单选题","text":"编年体史书发展过程中的分支不包括____。","options":[{"key":"A","text":"纪事本末体"},{"key":"B","text":"起居注"},{"key":"C","text":"实录"},{"key":"D","text":"纲目"}],"answer":["A"],"explanation":"纪事本末体不属于编年体。"},{"id":1134,"type":"单选题","text":"____属于 “史才四长”的内容。","options":[{"key":"A","text":"德、智、体、美"},{"key":"B","text":"才、学、识、德"},{"key":"C","text":"仁、义、礼、智"},{"key":"D","text":"忠、孝、节、义"}],"answer":["B"],"explanation":"“史才四长” 是唐代史学家刘知几在《史通》中提出的史学人才标准，包括 “才”（编撰能力）、“学”（史学知识）、“识”（历史见识），清代章学诚补充 “德”（史学道德），形成 “才、学、识、德” 四长。B 是现代教育目标；C 是孟子 “四德”；D 是传统道德规范，故选 A。"},{"id":1135,"type":"单选题","text":"中国传统科技的特点有____。","options":[{"key":"A","text":"注重实用"},{"key":"B","text":"注重理论"},{"key":"C","text":"注重实验"},{"key":"D","text":"注重抽象"}],"answer":["A"],"explanation":"中国传统科技以解决实际问题为核心，注重实用（如农学服务于农业生产，医学服务于治病救人，天文学服务于历法制定），但缺乏系统的理论总结和实验验证。B 注重理论、C 注重实验、D 注重抽象是西方近代科技的特点，故选 A。"},{"id":1136,"type":"单选题","text":"____不属于古代吉礼范围。","options":[{"key":"A","text":"祭天神"},{"key":"B","text":"祭地祗"},{"key":"C","text":"祭人鬼"},{"key":"D","text":"荒礼"}],"answer":["D"],"explanation":"吉礼是五礼之冠，主要是对天神、地祇、人鬼的祭祀典礼。主要内容有：（1）祀天神：昊天上帝；祀日月星辰；祀司中、司命、雨师。（2）祭地祗：祭社稷、五帝、五岳；祭山林川泽；祭四方百物，即诸小神。（3）祭人鬼：祭先王、先祖；禘祭先王、先祖；春祠、秋尝、享祭先王、先祖。"},{"id":1137,"type":"单选题","text":"____不属于古代嘉礼范围。","options":[{"key":"A","text":"饮食之礼"},{"key":"B","text":"大田之礼"},{"key":"C","text":"婚冠之礼"},{"key":"D","text":"宾射之礼"}],"answer":["B"],"explanation":"嘉礼，西周五礼之一，嘉礼是饮宴婚冠、节庆活动方面的礼节仪式。嘉，美、善的意思。后代的帝王登基、太后垂帘、帝王圣诞、立储册封、帝王巡狩等，也属嘉礼。嘉礼是和合人际关系、沟通、联络感情的礼仪。其主要内容有六：一曰饮食，二曰婚冠，三曰宾射，四曰飨燕，五曰脤膰，六曰庆贺。"},{"id":1138,"type":"单选题","text":"中国长期流传的饮食观念不包括____。","options":[{"key":"A","text":"民本思想"},{"key":"B","text":"节约粮食"},{"key":"C","text":"好客"},{"key":"D","text":"人格教育"}],"answer":["C"],"explanation":"中国长期流传的饮食观念主要包括：1、民本思想；2、人格教育；3、食疗观；4、节约粮食。"},{"id":1139,"type":"单选题","text":"____属于古代婚礼“六礼”范围。","options":[{"key":"A","text":"纳采"},{"key":"B","text":"问名"},{"key":"C","text":"纳征"},{"key":"D","text":"以上均是"}],"answer":["D"],"explanation":"以上都正确。"},{"id":1140,"type":"单选题","text":"____属于古代的丧葬习俗。","options":[{"key":"A","text":"火葬"},{"key":"B","text":"石棺葬"},{"key":"C","text":"悬棺葬"},{"key":"D","text":"以上均是"}],"answer":["D"],"explanation":"以上都正确。"},{"id":1141,"type":"单选题","text":"容仪有整主要不包括____。","options":[{"key":"A","text":"衣着容貌"},{"key":"B","text":"行为举止"},{"key":"C","text":"言语辞令"},{"key":"D","text":"礼尚往来"}],"answer":["D"],"explanation":"容仪有整不包括礼尚往来。"},{"id":1142,"type":"单选题","text":"头衣亦称“元衣”，即我们现代的帽子。____属于我国传统的头衣种类。","options":[{"key":"A","text":"冠"},{"key":"B","text":"冕"},{"key":"C","text":"帻"},{"key":"D","text":"以上均是"}],"answer":["D"],"explanation":"以上都正确。"},{"id":1143,"type":"单选题","text":"____不是古代最主要的运输工具。","options":[{"key":"A","text":"船"},{"key":"B","text":"车"},{"key":"C","text":"轿"},{"key":"D","text":"马"}],"answer":["D"],"explanation":"马不是古代最主要的运输工具。"},{"id":1144,"type":"单选题","text":"____是我国古代经验科学出现的标志，是当时人们从实践经验加以抽象概括的成果。","options":[{"key":"A","text":"《墨经》"},{"key":"B","text":"《论语》"},{"key":"C","text":"《道德经》"},{"key":"D","text":"《韩非子》"}],"answer":["A"],"explanation":"《墨经》是墨家学派的著作，包含丰富的自然科学知识（如力学、光学、几何学），是对当时生产实践经验的抽象概括，标志着我国古代经验科学的出现。B《论语》是儒家伦理著作；C《道德经》是道家哲学著作；D《韩非子》是法家政治著作，均无系统的科学知识，故选 A。"},{"id":1145,"type":"单选题","text":"居住建筑的文化含义主要表现不包括____。","options":[{"key":"A","text":"居住方式"},{"key":"B","text":"居住风水"},{"key":"C","text":"居住建筑格局"},{"key":"D","text":"居住建筑仪式"}],"answer":["B"],"explanation":"居住建筑的文化含义主要表现在三个方面：居住方式、居住建筑格局和仪式。"},{"id":1146,"type":"单选题","text":"中国传统艺术的民族特色不包括____。","options":[{"key":"A","text":"天人合一、物我合一的审美境界追求"},{"key":"B","text":"重言志，追求美善合一的审美旨趣"},{"key":"C","text":"圆融贯通的表现手法"},{"key":"D","text":"较强的功利性"}],"answer":["D"],"explanation":"中国传统艺术的民族特色没有功利性。"},{"id":1147,"type":"单选题","text":"学习中国传统文化的目的、意义____。","options":[{"key":"A","text":"可以增强民族自豪感和爱国情怀"},{"key":"B","text":"有助于改革开放和现代化建设"},{"key":"C","text":"有助于祖国统一、振兴中华"},{"key":"D","text":"以上均是"}],"answer":["D"],"explanation":"以上都正确。"},{"id":1148,"type":"单选题","text":"中国传统科学技术的总体特征不包括____。","options":[{"key":"A","text":"实用功利性"},{"key":"B","text":"辨证整体性"},{"key":"C","text":"科学实践性"},{"key":"D","text":"经验直观性"}],"answer":["C"],"explanation":"中国传统科学技术的总体特征包括实用功利性、辨证整体性和经验直观性。中国古代科学技术的总体特征三方面既不可分割，又相互独立。"},{"id":1149,"type":"单选题","text":"中国传统哲学的特点是____。","options":[{"key":"A","text":"侧重于人生哲理的探讨"},{"key":"B","text":"哲学与政治、伦理含融不分"},{"key":"C","text":"整体把握、直觉体悟的思维方式"},{"key":"D","text":"以上均是"}],"answer":["D"],"explanation":"以上都正确。"},{"id":1150,"type":"单选题","text":"中国传统文化在西方的传播主要包括____。","options":[{"key":"A","text":"造纸术约在唐朝中期传入西亚，再到欧洲"},{"key":"B","text":"火药 13、14世纪由阿拉伯人传到欧洲，很快被应用于军事"},{"key":"C","text":"中国美术、绘画、陶瓷对欧洲人来说不仅实用，而且是有价值的艺术品"},{"key":"D","text":"以上均是"}],"answer":["D"],"explanation":"以上都正确。"},{"id":1151,"type":"单选题","text":"中国优秀的史学文化传统包括____。","options":[{"key":"A","text":"求实精神"},{"key":"B","text":"惩恶扬善的批判精神"},{"key":"C","text":"以史为鉴的经邦致用精神"},{"key":"D","text":"以上均是"}],"answer":["D"],"explanation":"以上都正确。"},{"id":1152,"type":"单选题","text":"中华民族传统美德的主要内容包括____。","options":[{"key":"A","text":"仁爱孝悌、谦和好礼"},{"key":"B","text":"诚信知报、精忠爱国"},{"key":"C","text":"克己奉公、修己独慎"},{"key":"D","text":"以上均是"}],"answer":["D"],"explanation":"以上都正确。"},{"id":1153,"type":"单选题","text":"董仲舒的思想主要不包括____。","options":[{"key":"A","text":"人君受命于天"},{"key":"B","text":"“道之大原出于天，天不变，道亦不变\""},{"key":"C","text":"效法天道，德刑并用"},{"key":"D","text":"经世致用"}],"answer":["D"],"explanation":"经世致用一词由明清之际思想家王夫之、黄宗羲、顾炎武等提出。"},{"id":1154,"type":"单选题","text":"中国古代书法的特点不包括____。","options":[{"key":"A","text":"通过书法的点、划结构和章法表现形式美"},{"key":"B","text":"通过字的力度来展现神采美"},{"key":"C","text":"通过字的形态来展现神采美"},{"key":"D","text":"通过字的形、神表现书法家的精神美和时代特征"}],"answer":["B"],"explanation":"中国古代书法是通过字的形态来展现神采美，而非字的力度。"},{"id":1155,"type":"单选题","text":"魏晋南北朝史学发展的特点不包括____。","options":[{"key":"A","text":"史著数量大为增加"},{"key":"B","text":"史学发展成熟期"},{"key":"C","text":"史学成为一门独立的学科"},{"key":"D","text":"史著种类繁多"}],"answer":["B"],"explanation":"史学发展成熟期在隋唐时期。"},{"id":1156,"type":"单选题","text":"关于《齐民要术》的描述，正确的是____。","options":[{"key":"A","text":"由唐代贾思勰编撰，是我国现存最早的农书"},{"key":"B","text":"涵盖农业生产、农产品加工，还涉及畜牧、渔业等领域"},{"key":"C","text":"主要记载南方农业生产技术，对北方农业无参考价值"},{"key":"D","text":"是一部综合性的医学著作，重点论述中医养生之道"}],"answer":["B"],"explanation":"《齐民要术》是北魏农学家贾思勰编撰的农书，并非唐代（选项 A 错误），是我国现存最早、最完整的农书。其内容丰富，不仅包含粮食作物、经济作物的种植技术，还涉及农产品加工（如酿造、腌制）、畜牧养殖、渔业捕捞等领域（选项 B 正确）。该书以黄河流域（北方）农业生产为主要记载对象，但其中的许多农业原理对南方农业也有借鉴意义（选项 C 错误），且其本质是农书，而非医学著作（选项 D 错误），故选择 B。"},{"id":1157,"type":"单选题","text":"“⽂化”之“⽂”的引申义有____。","options":[{"key":"A","text":"纹理，如 “木成文”"},{"key":"B","text":"文字、文章，如 “文以载道”"},{"key":"C","text":"自然界的原始形态，如 “天文”"},{"key":"D","text":"未经加工的粗糙状态"}],"answer":["B"],"explanation":"“文” 的本义是 “纹理”（选项 A 属于本义，非引申义），指事物表面的纹路。随着语义发展，“文” 引申为与 “文字”“文章” 相关的含义，如 “文以载道” 中的 “文” 即指文章，这是典型的引申义（选项 B 正确）。选项 C 中 “天文” 的 “文” 虽与自然现象相关，但仍偏向 “条理、秩序” 的本义延伸，未形成独立的引申义；选项 D 描述的是 “质” 的含义，与 “文”（代表修饰、条理）相反，并非 “文” 的引申义，故选择 B。"},{"id":1158,"type":"单选题","text":"“中”字的引申义有____。","options":[{"key":"A","text":"内部、里面，如 “室内”"},{"key":"B","text":"方位词，指东方"},{"key":"C","text":"⽂化政治中⼼"},{"key":"D","text":"军事堡垒"}],"answer":["C"],"explanation":"“中”字的引中义有空间的中央、文化政治的中心。"},{"id":1159,"type":"单选题","text":"“中体西⽤”论的严重缺陷是____。","options":[{"key":"A","text":"颠倒经济与伦理的序列关系"},{"key":"B","text":"以忠孝为本， 以中国经史之学为基"},{"key":"C","text":"主张学习西方先进技术，推动了近代化"},{"key":"D","text":"回避现实冲突，停留在⼀种经验论的理论⽔平上"}],"answer":["D"],"explanation":"“中体西用”论的严重缺陷是仍存“华夷”等级秩序、文化中心主义心理定势;回避现实冲突, 停留在一种经验论的理论⽔平上。"},{"id":1160,"type":"单选题","text":"按照四分法，以下哪个不是中国文化？","options":[{"key":"A","text":"物质文化"},{"key":"B","text":"宗教文化"},{"key":"C","text":"精神文化"},{"key":"D","text":"制度文化"}],"answer":["B"],"explanation":"还有语言文化。"},{"id":1161,"type":"单选题","text":"竺可桢先生在《中国近五千年气候变化的初步研究》一文中将我国五千年的气候变化分为四个大的时期，其中不包括____。","options":[{"key":"A","text":"温暖期"},{"key":"B","text":"寒暖交错期"},{"key":"C","text":"寒冷期"},{"key":"D","text":"第一冷期"}],"answer":["D"],"explanation":"中国五千年气候的变化大势是由暖变冷,大致分为四个大的时期:1)温暖期：从公元前3000年到公元前1100年,下限正好在商朝末年。2)寒暖交错期：从公元前1100年到公元1400年,下限到明朝初期。3)方志时期,又叫寒冷时期。从公元1400年到1900年,下限到清朝末年。4)仪器观测期。"},{"id":1162,"type":"单选题","text":"中国古代文化的基干包括____。","options":[{"key":"A","text":"源于齐鲁的儒家文化、源于三晋的法家文化"},{"key":"B","text":"戏曲文化"},{"key":"C","text":"源于江浙的商业文化"},{"key":"D","text":"源于印度的佛教文化"}],"answer":["A"],"explanation":"中国古代文化的基干包括源于齐鲁的儒家文化 、源于三晋的法家文化、源于南楚的道家及楚辞文化。"},{"id":1163,"type":"单选题","text":"概括起来说，我国古代改造利用自然的成就包括____。","options":[{"key":"A","text":"水利的兴修"},{"key":"B","text":"土地的开垦"},{"key":"C","text":"都江堰的修建"},{"key":"D","text":"AB均是"}],"answer":["D"],"explanation":"传说:大禹治水。战国:都江堰和郑国渠。关中:井渠法。汉代:王景治黄河"},{"id":1164,"type":"单选题","text":"新石器时代三大文明成就是不包括____。","options":[{"key":"A","text":"青铜器制造"},{"key":"B","text":"农业"},{"key":"C","text":"制陶"},{"key":"D","text":"石器的磨制与钻孔"}],"answer":["A"],"explanation":"（1）农业的发展：农业的发生是人类历史划时代的大事。在世界为数不多的几个农业起源中心中，中国独一无二，即黄河中下游地区的耐旱谷物农业和长江中下游地区的稻作农业。\n（2）石器的磨制与钻孔：石器的磨制和钻孔，体现着生产力水平的提高。磨制石器的发展与农业发生同步。　　\n（3）制陶业的发展：陶器的制造是贯穿于新石器时代重要的手工业。制陶技术经历过贴塑、泥条盘筑及慢轮加工和快轮加工几个大的阶段。快轮加工陶器在仰韶文化时就已经出现，经过不断提高，到龙山时期已遍及黄河及长江流域。"},{"id":1165,"type":"单选题","text":"在汉武帝数十年对匈奴的战争中，大的战役不包括____。","options":[{"key":"A","text":"河南战役"},{"key":"B","text":"河西战役"},{"key":"C","text":"河东战役"},{"key":"D","text":"漠北战役"}],"answer":["C"],"explanation":"河东战役是显王三年至四十七年(公元前366年—前322年)，秦军收复被魏国夺占的河西地区(今山西、陕西间黄河南段以西地区)的作战。"},{"id":1166,"type":"单选题","text":"“三公九卿”中“三公”不包括____。","options":[{"key":"A","text":"丞相"},{"key":"B","text":"尚书"},{"key":"C","text":"太尉"},{"key":"D","text":"御史大夫"}],"answer":["B"],"explanation":"秦以丞相，太尉，御史大夫为三公。"},{"id":1167,"type":"单选题","text":"中国古代四大发明中，在唐宋之际发明并应用的不包括____。","options":[{"key":"A","text":"火药"},{"key":"B","text":"指南针"},{"key":"C","text":"造纸术"},{"key":"D","text":"活字印刷术"}],"answer":["C"],"explanation":"造纸术，是中国四大发明之一，发明于西汉时期、改进于东汉时期。"},{"id":1168,"type":"单选题","text":"明末清初的“三先生”不包括____。","options":[{"key":"A","text":"王夫之"},{"key":"B","text":"顾炎武"},{"key":"C","text":"黄宗羲"},{"key":"D","text":"徐光启"}],"answer":["D"],"explanation":"清初出现了许多具有唯物主义思想与民主色彩的先进知识份子，黄宗羲、王夫之、顾炎武就是其杰出代表。他们被并称为“清初三先生” ，均曾参加过反清复明的爱国活动，失败后，拒绝同满清权贵合作，表现出崇高的民族气节。"},{"id":1169,"type":"单选题","text":"我国传统的市商贸易活动的主要模式不包括____。","options":[{"key":"A","text":"市"},{"key":"B","text":"商"},{"key":"C","text":"墟"},{"key":"D","text":"集"}],"answer":["B"],"explanation":"市、墟、集、会是传统市商贸易活动的主要模式。"},{"id":1170,"type":"单选题","text":"唐宋以来，行会的管理方式主要不包括____。","options":[{"key":"A","text":"祖师崇拜"},{"key":"B","text":"行业竞争"},{"key":"C","text":"师徒传承"},{"key":"D","text":"行业禁忌"}],"answer":["B"],"explanation":"我国古代行会的主要管理方式：\n① 祖师崇拜,各行各业都有自己崇拜的祖师。\n②师徒传承,手工行业的技术传承是在师傅和徒弟之间进行的,徒弟入行、拜师、岀师都有一套行规,不可逾越。\n③行业禁忌,传统手工业有许多行业忌讳,反映了过去手工业生存艰难的另一面。"},{"id":1171,"type":"单选题","text":"“福”字，是我国最古老的文字之一，目前发现的“福”字，最早见于____。","options":[{"key":"A","text":"甲骨文"},{"key":"B","text":"金文"},{"key":"C","text":"大篆"},{"key":"D","text":"小篆"}],"answer":["A"],"explanation":"目前发现的最早的“福”字见于甲骨文，早期文字具有图画性的特点，象形性很强。甲骨文中的“福”字为合体会意字，与祭祀祈祷有关。"},{"id":1172,"type":"单选题","text":"《陈情表》“臣生当陨首，死当结草”一句中的“结草”，后世常用来代指报恩，请问“结草”的典故最早出自____。","options":[{"key":"A","text":"《庄子》"},{"key":"B","text":"《左传》"},{"key":"C","text":"《列子》"},{"key":"D","text":"《史记》"}],"answer":["B"],"explanation":"“结草”的典故见于《左传·宣公十五年》。公元前594年的秋七月，秦桓公出兵伐晋，晋军和秦兵在晋地辅氏（今陕西大荔县）交战，晋将魏颗与秦将杜回相遇，二人厮杀在一起，正在难分难解之际，魏颗突然见一老人用草编的绳子套住杜回，使这位堂堂的秦国大力士站立不稳，摔倒在地，当场被魏颗所俘，使得魏颗在这次战役中大败秦师。"},{"id":1173,"type":"单选题","text":"下列关于孟浩然《过故人庄》一诗中字词的解释，不正确一项的是____。","options":[{"key":"A","text":"“故人具鸡黍”中的“具”意思为“准备”"},{"key":"B","text":"“绿树村边合”中的“合”意思为“环绕”"},{"key":"C","text":"“青山郭外斜”中的“郭”意思为“古代城墙的内城”"},{"key":"D","text":"“还来就菊花”中的“就”意思为“靠近”"}],"answer":["C"],"explanation":"古代城墙有内外两重，内为城，外为郭。这里的“郭”指村庄的外墙。"},{"id":1174,"type":"单选题","text":"在唐代，针对时人耻学于师的偏见，韩愈不顾流俗，勇为人师，广招后学，并抨击时弊、倡导师道，撰写《师说》一文送给______","options":[{"key":"A","text":"李商隐"},{"key":"B","text":"李蟠"},{"key":"C","text":"李颀"},{"key":"D","text":"李治"}],"answer":["B"],"explanation":"《师说》最后一段说：“李氏子蟠，年十七，好古文，六艺经传皆通习之，不拘于时，学于余。余嘉其能行古道，作《师说》以贻之。”"},{"id":1175,"type":"单选题","text":"2022年北京冬季奥运会是第____届。","options":[{"key":"A","text":"23"},{"key":"B","text":"24"},{"key":"C","text":"25"},{"key":"D","text":"26"}],"answer":["B"],"explanation":"第24届冬季奥林匹克运动会，简称2022年北京冬季奥运会，是由中国举办的国际性奥林匹克赛事，于2022年2月4日开幕，2月20日闭幕。"},{"id":1176,"type":"单选题","text":"五行是指什么？","options":[{"key":"A","text":"圣行、梵行、天行、佛行、病行"},{"key":"B","text":"行动、行为、形成、行测、行乐"},{"key":"C","text":"幸福、快乐、健康、平安、长寿"},{"key":"D","text":"金、木、水、火、土"}],"answer":["D"],"explanation":"金、木、水、火、土合称五行，五行是“气”的五种运行状态，是“气”运行产生的结果，“行”即运动。中国古代哲学家用五行理论来说明世界万物的形成及其相互关系。"},{"id":1177,"type":"单选题","text":"《国语》是____。","options":[{"key":"A","text":"一部国别体史书"},{"key":"B","text":"一部编年体史书"},{"key":"C","text":"一部纪传体史书"},{"key":"D","text":"一部纪事本末体史书"}],"answer":["A"],"explanation":"《国语》相传是春秋时期左丘明所撰的一部国别体著作。他的编纂方法是以国分类，以语为主，故名“国语”。"},{"id":1178,"type":"单选题","text":"一口气提出170名个问题的屈原的长诗是____。","options":[{"key":"A","text":"《离骚》"},{"key":"B","text":"《天问》"},{"key":"C","text":"《招魂》"},{"key":"D","text":"《九歌》"}],"answer":["B"],"explanation":"在《天问》中，屈原以诗人哲学家的胸怀与视野，一口气提出了170多个问题，他以恢宏的气势、深刻的追问、奇幻的哲思为中国诗歌埋藏了一条理性和质疑的河流。"},{"id":1179,"type":"单选题","text":"《九章》共____篇。","options":[{"key":"A","text":"9"},{"key":"B","text":"18"},{"key":"C","text":"90"},{"key":"D","text":"99"}],"answer":["A"],"explanation":"《九章》是短篇抒情诗集，包括9篇作品。依王逸《楚辞章句》的次序是：《惜诵》、《涉江》、《哀郢》、《抽思》、《怀沙》、《思美人》、《惜往日》、《橘颂》、《悲回风》。这9篇的作者，王逸都定为屈原。"},{"id":1180,"type":"单选题","text":"“不要人夸好颜色，只留清气满乾坤”出自哪一首诗？","options":[{"key":"A","text":"《乡村四月》"},{"key":"B","text":"《滁州西涧》"},{"key":"C","text":"《墨梅》"},{"key":"D","text":"《古朗月行》"}],"answer":["C"],"explanation":"墨梅\n吾家洗砚池头树，个个花开淡墨痕。\n不要人夸好颜色，只留清气满乾坤。"},{"id":1181,"type":"单选题","text":"因秦王不愿用城池换美玉，而持璧倚柱、怒发冲冠的是哪一个人？","options":[{"key":"A","text":"廉颇"},{"key":"B","text":"蔺相如"},{"key":"C","text":"赵括"},{"key":"D","text":"赵奢"}],"answer":["B"],"explanation":"完璧归赵是一个历史典故演化而成的成语，出自《史记·廉颇蔺相如列传》。"},{"id":1182,"type":"单选题","text":"《七发》的作者是____。","options":[{"key":"A","text":"贾谊"},{"key":"B","text":"东方朔"},{"key":"C","text":"王褒"},{"key":"D","text":"枚乘"}],"answer":["D"],"explanation":"在文学上，枚乘所作的《七发》在辞赋的发展史上具有重要地位，是汉大赋正式形成的标志性作品；在思想上，枚乘的政治思想表现为对大一统有精神上的认同。"},{"id":1183,"type":"单选题","text":"中国历史上第一次大规模的平民起义，发生在现在的安徽境内的是____。","options":[{"key":"A","text":"赤眉起义"},{"key":"B","text":"陈胜吴广起义"},{"key":"C","text":"绿林起义"},{"key":"D","text":"黄巾起义"}],"answer":["B"],"explanation":"大泽乡起义，又称“陈胜吴广起义”，是秦末农民战争的一部分。此次起义沉重打击了秦朝，揭开了秦末农民起义的序幕，是中国历史上第一次大规模的平民起义。"},{"id":1184,"type":"单选题","text":"我国古代第一部历史散文集是____。","options":[{"key":"A","text":"《尚书》"},{"key":"B","text":"《逸周书》"},{"key":"C","text":"《论语》"},{"key":"D","text":"《春秋》"}],"answer":["A"],"explanation":"《尚书》是儒家主要经典之一，是我国第一部上古历史文献和部分追述古代事迹著作的汇编，保存了商周特别是西周初期的一些重要史料，对研究上古历史具有很高的价值。就文学成就而言，《尚书》是中国古代散文已经形成的标志。"},{"id":1185,"type":"单选题","text":"“美”字最初的含义是____。","options":[{"key":"A","text":"羊大即为美"},{"key":"B","text":"戴着头饰站立的人"},{"key":"C","text":"土地里生长的花朵"},{"key":"D","text":"远方茂盛的森林"}],"answer":["B"],"explanation":"美，初文见于商代甲骨文。美的古字形像戴着头饰站立的人，本义指漂亮、好看。"},{"id":1186,"type":"单选题","text":"“芒种”属于哪一个季节？","options":[{"key":"A","text":"春季"},{"key":"B","text":"夏季"},{"key":"C","text":"秋季"},{"key":"D","text":"冬季"}],"answer":["B"],"explanation":"二十四节气\n1.春季：立春、雨水；惊郵、春分：清明、谷雨。\n2.夏季：立夏、小满;芒种、夏至：小暑、大暑。\n3.秋季：立秋、处暑：白露、秋分：寒露、霜降。\n4.冬季：立冬、小雪；大雪、冬至：小寒、大寒。"},{"id":1187,"type":"单选题","text":"重阳佳节是在农历几月几？","options":[{"key":"A","text":"五月初五"},{"key":"B","text":"七月十五"},{"key":"C","text":"八月十五"},{"key":"D","text":"九月初九"}],"answer":["D"],"explanation":"重阳(九月初九)：习俗有登高望远、赏菊赋诗、喝菊花酒、插菜英等。现定为老人节。"},{"id":1188,"type":"单选题","text":"以下哪一项并非兵马俑制成兵马的形状的殉葬品？","options":[{"key":"A","text":"战车"},{"key":"B","text":"战马"},{"key":"C","text":"士兵"},{"key":"D","text":"战地"}],"answer":["D"],"explanation":"兵马俑是古代墓葬雕塑的一个类别。古代施行人殉，奴隶是奴隶主生前的附属品，奴隶主死后奴隶要作为殉葬品为奴隶主陪葬。兵马俑即制成兵马（战车、战马、士兵）形状的殉葬品。"},{"id":1189,"type":"单选题","text":"把汉大赋推向高峰的人是____。","options":[{"key":"A","text":"班固"},{"key":"B","text":"张衡"},{"key":"C","text":"司马相如"},{"key":"D","text":"扬雄"}],"answer":["C"],"explanation":"“因为司马相如生活的时代,大一统政权、汉民族国家正处于蒸蒸日上的发展态势。为此而欢欣鼓舞并产生自豪夸耀心理,才是大赋创作的底色,讽谏之意并不是全部的创作初衷。豪迈的时代精神,铺陈的赋体特性,不甚独立的作家身份和维护盛世的诚意,种种因素综合考量,“曲终奏雅”相对来说倒是顺理成章的处理方案。"},{"id":1190,"type":"单选题","text":"饺子由____演变而来的。","options":[{"key":"A","text":"汤圆"},{"key":"B","text":"年糕"},{"key":"C","text":"面粉"},{"key":"D","text":"馄饨"}],"answer":["D"],"explanation":"饺子由馄饨演变而来 ，源于中国古代的角子，原名“娇耳”，汉族传统面食，距今已有一千八百多年的历史 。由东汉南阳涅阳（今河南南阳邓州）人张仲景发明  ，最初作为药用。饺子又称水饺，深受中国人民喜爱，是中国北方民间的主食和地方小吃，也是年节食品。"},{"id":1191,"type":"单选题","text":"四大名著包括？","options":[{"key":"A","text":"《三国演义》"},{"key":"B","text":"《水浒传》"},{"key":"C","text":"《红楼梦》"},{"key":"D","text":"以上皆正确"}],"answer":["D"],"explanation":"中国古典长篇小说四大名著，简称四大名著，是指《水浒传》《三国演义》《西游记》《红楼梦》（按照成书先后顺序）这四部巨著。"},{"id":1192,"type":"单选题","text":"木版水印的生产主要分四道工序是什么？","options":[{"key":"A","text":"勾描→印刷→装裱→雕刻木版"},{"key":"B","text":"勾描→雕刻木版→印刷→装裱"},{"key":"C","text":"雕刻木版→印刷→装裱→勾描"},{"key":"D","text":"勾描→雕刻木版→装裱→印刷"}],"answer":["B"],"explanation":"木版水印的生产主要分四道工序：勾描→雕刻木版→印刷→装裱。"},{"id":1193,"type":"单选题","text":"孔子认为“身正”是为政者的重要品质，“不能正其身，如正人何?”韩非子主张立法者“不游意于法之外，不为惠于法之内”。他们这是倡导统治者____。","options":[{"key":"A","text":"推行仁政"},{"key":"B","text":"以法治国"},{"key":"C","text":"规范行为"},{"key":"D","text":"监督民众"}],"answer":["C"],"explanation":"根据“不能正其身，如正人何？”可得出孔子强调要身正。根据“不游意于法之外，不为惠于法之内”可得出韩非子强调要遵守法律。二者分别从不同的角度要求人们要遵守规则，规范行为，C项正确；A项是孟子的，B项是法家的，排除；D项在材料中没有体现，排除。"},{"id":1194,"type":"单选题","text":"《桃花扇》的故事发生在哪个城市？","options":[{"key":"A","text":"苏州"},{"key":"B","text":"上海"},{"key":"C","text":"南京"},{"key":"D","text":"杭州"}],"answer":["C"],"explanation":"《桃花扇》所写的是明代末年发生在南京的故事。全剧以侯方域、李香君的悲欢离合为主线，展现了明末南京的社会现实。同时也揭露了弘光政权衰亡的原因，歌颂了对国家忠贞不渝的民族英雄和底层百姓，展现了明朝遗民的亡国之痛。"},{"id":1195,"type":"单选题","text":"下列对文化常识的解说，错误的一项是：____","options":[{"key":"A","text":"削：革职罢官。谪：降职远调。"},{"key":"B","text":"免：免除官职。黜：废黜、贬退。"},{"key":"C","text":"拜：授给官职。废：罢免或废黜。"},{"key":"D","text":"除：免除官职。退：（1）撤销或降低官职；（2）自己辞职。"}],"answer":["D"],"explanation":"除：免除旧职任新职。"},{"id":1196,"type":"单选题","text":"《钦定四库全书》分多少部？","options":[{"key":"A","text":"4"},{"key":"B","text":"16"},{"key":"C","text":"40"},{"key":"D","text":"44"}],"answer":["A"],"explanation":"四库全书：全称《钦定四库全书》，分“经、史、子、集”四部，故名四库。"},{"id":1197,"type":"单选题","text":"冬奥会、冬残奥会主题口号是____。","options":[{"key":"A","text":"一起向未来"},{"key":"B","text":"激情同在"},{"key":"C","text":"激情冰火属于你"},{"key":"D","text":"用炽热的心"}],"answer":["A"],"explanation":"2022年北京冬奥会：一起向未来（Together for a Shared Future)\n2018年平昌冬奥会：激情同在（Passion Connected)\n2014年索契冬奥会：激情冰火属于你（Hot Cool Yours)\n2010年温哥华冬奥会：用炽热的心（With Glowing Hearts)"},{"id":1198,"type":"单选题","text":"贾谊的文集是_____。","options":[{"key":"A","text":"《新书》"},{"key":"B","text":"《新语》"},{"key":"C","text":"《至言》"},{"key":"D","text":"《治安策》"}],"answer":["A"],"explanation":"贾谊的文集有:《新书》、《贾长沙集》、《贾谊集》,其中以《贾谊集》最为有名,代表作有《过秦论》、《论积贮疏》、《陈政事疏》等。"},{"id":1199,"type":"单选题","text":"以下哪一项并非制做皮影的雕刻用料？","options":[{"key":"A","text":"马皮"},{"key":"B","text":"驴皮"},{"key":"C","text":"羊皮"},{"key":"D","text":"猪皮"}],"answer":["D"],"explanation":"在影人的制作上要选用坚固耐用、柔韧性好的材料，可以用羊皮、驴皮、马皮、牛皮等，其中驴皮应用最为广泛，刻画出的影人形态逼真、薄厚均匀、色彩鲜亮，各种精美的皮影艺术造型标志着皮影制作技术日渐成熟。"},{"id":1200,"type":"单选题","text":"以下哪一项属于中国古代十大乐器里的“革”类乐器？","options":[{"key":"A","text":"钟"},{"key":"B","text":"鼓"},{"key":"C","text":"瑟"},{"key":"D","text":"笙"}],"answer":["B"],"explanation":"中国古典乐器一般按“八音”分类。\n“金”类：钟\n“土”类：埙\n“革”类：鼓\n“丝”类：琴、瑟、二胡、琵琶等\n“匏”类：笙\n“竹”类：箫、笛等"},{"id":1201,"type":"单选题","text":"五脏六腑的“五脏”是哪五个？","options":[{"key":"A","text":"心、肝、腰、肺、肾"},{"key":"B","text":"心、肝、脾、肺、肾"},{"key":"C","text":"心、肝、脾、胆、肾"},{"key":"D","text":"心、脏、脾、肺、肾"}],"answer":["B"],"explanation":"五脏六腑是人体脏器的总称，五脏指肝、心、脾、肺、肾，与之相对应或者相表里的六腑是指胆、小肠、大肠、胃、膀胱，还有特殊的腑，称为三焦。"},{"id":1202,"type":"单选题","text":"饺子起源于我国哪个时期？","options":[{"key":"A","text":"隋"},{"key":"B","text":"东汉"},{"key":"C","text":"秦"},{"key":"D","text":"春秋战国"}],"answer":["B"],"explanation":"饺子起源于东汉时期，为东汉河南邓州人\"医圣\"张仲景首创。当时饺子是药用，张仲景用面皮包上一些祛寒的药材用来治病(羊肉、胡椒等)，避免病人耳朵上生冻疮。"},{"id":1203,"type":"单选题","text":"以下关于甲骨文的表述不正确的是____。","options":[{"key":"A","text":"甲骨文对研究夏朝的历史有非常重要的价值"},{"key":"B","text":"甲骨文是殷墟出士的刻在龟甲和兽骨上的文字"},{"key":"C","text":"甲骨文是目前中国己知最早的一种成系统的文字"},{"key":"D","text":"甲骨文字形成熟，奠定了汉字的基础"}],"answer":["A"],"explanation":"甲骨文是我国商朝时期的一种文字。甲骨文主要指中国商朝晚期王室用于占卜记事而在龟甲或兽骨上契刻的文字，是中国及东亚已知最早的成体系的商代文字的一种载体。"},{"id":1204,"type":"单选题","text":"汉宇形体的演变过程为____。","options":[{"key":"A","text":"金文→隶书→楷书→篆书"},{"key":"B","text":"甲骨文→金文→篆书→隶书。"},{"key":"C","text":"隶书→篆书→楷书→金文"},{"key":"D","text":"金文→隶书→篆书→楷书"}],"answer":["B"],"explanation":"演变顺序：甲骨文→金文→大篆→小篆→隶书→草书→楷书→行书。"},{"id":1205,"type":"单选题","text":"武术的作用表述中,正确的一项是____。","options":[{"key":"A","text":"改善和增强体质,提高防身自卫能力,广泛适应性,内外合一"},{"key":"B","text":"磨练意志,培养道德情操娱乐观赏,寓技击于体育中"},{"key":"C","text":"改善和增强体质,提高防身自卫能力,磨练意志培养道德情操,娱乐观赏丰富文化生活"},{"key":"D","text":"提高防身自卫能力,娱乐观赏丰富文化生活,寓技击于体育中，广泛适应性"}],"answer":["C"],"explanation":"武术是古代军事战争一种传承的技术。习武可以强身健体，亦可以防御敌人进攻。习武之人以“制止侵袭”为技术导向、引领修习者进入认识人与自然、社会客观规律的传统教化（武化）方式，是人类物质文明的导向和保障，是当代传统武学艺术的一种展示。"},{"id":1206,"type":"单选题","text":"“赋”作为一种文体，最早见于____。","options":[{"key":"A","text":"贾谊的文章"},{"key":"B","text":"屈原的文章"},{"key":"C","text":"荀子的文章"},{"key":"D","text":"宋玉的文章"}],"answer":["C"],"explanation":"“赋”的名称最早见于战国后期荀况的《赋篇》。"},{"id":1207,"type":"单选题","text":"《汉书》的作者是____。","options":[{"key":"A","text":"范晔"},{"key":"B","text":"张衡"},{"key":"C","text":"司马迁"},{"key":"D","text":"班固"}],"answer":["D"],"explanation":"《汉书》的作者是班固。《汉书》,又称《前汉书》,是中国第一部纪传体断代史,“二十四史”之一。由汉朝东汉时期史学家儒客大家班固编撰,前后历时二十余年,于建初年中基本修成,后唐朝颜师古为之释注。"},{"id":1208,"type":"单选题","text":"中国古代十大乐器里的瑟有多少根弦？","options":[{"key":"A","text":"20"},{"key":"B","text":"25"},{"key":"C","text":"30"},{"key":"D","text":"35"}],"answer":["B"],"explanation":"瑟，形状似琴，有25根弦，弦的粗细不同，每弦瑟有一柱，按五声音阶定弦。最早的瑟有五十弦，故又称“五十弦”。"},{"id":1209,"type":"单选题","text":"基本茶类可分为绿茶、红茶、乌龙茶、白茶、____和黑茶六类。","options":[{"key":"A","text":"花茶"},{"key":"B","text":"黄茶"},{"key":"C","text":"青茶"},{"key":"D","text":"春茶"}],"answer":["B"],"explanation":"“茶叶的六大基本茶类有白茶、黄茶、绿茶、红茶、乌龙茶、黑茶”。"},{"id":1210,"type":"单选题","text":"傣族建造竹筒楼的原因不包括？","options":[{"key":"A","text":"防蛇"},{"key":"B","text":"防热"},{"key":"C","text":"防潮"},{"key":"D","text":"防洪"}],"answer":["D"],"explanation":"防洪不是竹筒楼的功能。"},{"id":1211,"type":"单选题","text":"《红楼梦》中贾蓉向王熙凤要一件“借去略摆一摆”的用来隔断和装饰的家具是什么？","options":[{"key":"A","text":"椅子"},{"key":"B","text":"桌子"},{"key":"C","text":"屏风"},{"key":"D","text":"柜子"}],"answer":["C"],"explanation":"屏风，中国传统建筑物内部挡风用的一种家具，所谓“屏其风也”。屏风作为传统家具的重要组成部分，历史由来已久。屏风一般陈设于室内的显著位置，起到分隔、美化、挡风、协调等作用。它与古典家具相互辉映，相得益彰，浑然一体，成为中式家居装饰不可分割的整体，而呈现出一种和谐之美、宁静之美。《红楼梦》中贾蓉向王熙凤要一件“借去略摆一摆”的用来隔断和装饰的家具便是“屏风”。"},{"id":1212,"type":"单选题","text":"战国中后期，屈原根据民间祭祀歌所加工而成的作品是____。","options":[{"key":"A","text":"《九章》"},{"key":"B","text":"《九歌》"},{"key":"C","text":"《天问》"},{"key":"D","text":"《招魂》"}],"answer":["B"],"explanation":"战国中后期屈原根据民间祭祀所加工而成的作品是《九歌》。"},{"id":1213,"type":"单选题","text":"甲骨文中已经出现记数单字，最小的是一，最大的是____。","options":[{"key":"A","text":"三千"},{"key":"B","text":"三万"},{"key":"C","text":"三十万"},{"key":"D","text":"三亿"}],"answer":["B"],"explanation":"目前发现的最大的甲骨文数字是30000。"},{"id":1214,"type":"单选题","text":"下列哪种青铜器不属于用来盛装食物的食器？","options":[{"key":"A","text":"青铜鼎"},{"key":"B","text":"青铜簋"},{"key":"C","text":"青铜甗"},{"key":"D","text":"青铜爵"}],"answer":["D"],"explanation":"青铜爵是夏商周时期重要的酒器，作用相当于酒杯。圆腹，也有个别方腹，一侧的口部前端有流（即倒酒的流槽），后部有尖状尾，流与口之间有立柱，腹部一旁有把手，下有三个锥状长足。"},{"id":1215,"type":"单选题","text":"古代代表性的兵器有战车与投石器，而一下哪一项并非典型武器？","options":[{"key":"A","text":"剑"},{"key":"B","text":"枪"},{"key":"C","text":"斧"},{"key":"D","text":"箭"}],"answer":["D"],"explanation":"“代表性的兵器有战车与投石器，而武器的典型则是剑、枪、斧。”"},{"id":1216,"type":"单选题","text":"在哪个朝代中秋节才开始成为固定的节日？","options":[{"key":"A","text":"唐朝"},{"key":"B","text":"宋朝"},{"key":"C","text":"元朝"},{"key":"D","text":"明朝"}],"answer":["A"],"explanation":"中秋节从唐朝开始成为固定节日。"},{"id":1217,"type":"单选题","text":"张衡发明的地动仪上有几条龙？","options":[{"key":"A","text":"8"},{"key":"B","text":"10"},{"key":"C","text":"12"},{"key":"D","text":"18"}],"answer":["A"],"explanation":"“张衡发明的地动仪上共有八条龙,每一条龙代表着一个方位,分别是东、南、西、北、东南、西南、东北、西北,每个方位上均有口含龙珠的龙头,而且在每条龙头的下方都有一只蟾蜍与之相对应。"},{"id":1218,"type":"单选题","text":"中国古代兵器____除了是实战作用，又被列于门前，体现主人身份地位。","options":[{"key":"A","text":"铖"},{"key":"B","text":"戈"},{"key":"C","text":"戟"},{"key":"D","text":"矛"}],"answer":["C"],"explanation":"中国古代兵器戟除了实战作用又被列于门前，以体现主人的身份地位。戟是古代兵器之一，是戈和矛的合体，具有勾啄和刺击双重功能，杀伤力比戈矛强，古代的显贵之家，将戟立于门前，以示官勋，所以戟有兼为仪仗。后来军队中戟逐渐为刀所取代，但仍作为仪仗器具。"},{"id":1219,"type":"单选题","text":"2011年3月30日国务院常务会议将每年的____确定为中国旅游日。","options":[{"key":"A","text":"五月十九"},{"key":"B","text":"五月二九"},{"key":"C","text":"九月十九"},{"key":"D","text":"九月二九"}],"answer":["A"],"explanation":"中国旅游日，是每年的5月19日，非法定节假日。该节日起源于2001年5月19日，浙江宁海人麻绍勤以宁海徐霞客旅游俱乐部的名义，向社会发出设立“中国旅游日”的倡议，建议《徐霞客游记》首篇《游天台山日记》开篇之日（5月19日）定名为中国旅游日。"},{"id":1220,"type":"单选题","text":"我国人口最多及最少的少数民族分别是____、_____。","options":[{"key":"A","text":"回族、裕固族"},{"key":"B","text":"壮族、珞巴族"},{"key":"C","text":"回族、珞巴族"},{"key":"D","text":"壮族、裕固族"}],"answer":["B"],"explanation":"我国共有56个民族，壮族是我国少数民族中人口最多的民族；人口最少的是珞巴族。"},{"id":1221,"type":"单选题","text":"饮茶可以延年益寿，解渴提神，下列选项中哪些不属于饮茶的益处？","options":[{"key":"A","text":"防蛀牙"},{"key":"B","text":"抗原子辐射"},{"key":"C","text":"治坏血病"},{"key":"D","text":"治疗颈椎病"}],"answer":["D"],"explanation":"饮茶并不能治疗颈椎病。"},{"id":1222,"type":"单选题","text":"“宰相”的“宰”最早指____。","options":[{"key":"A","text":"高级官吏"},{"key":"B","text":"官吏统称"},{"key":"C","text":"低级官吏"},{"key":"D","text":"皇帝"}],"answer":["B"],"explanation":"宰相”的“宰”最早指夏商周时期祭祀用的祭品,之后发展为国家的官职。 “宰”的意思是主宰,“宰相”是商朝时为管理家务和奴隶之官;周朝有执掌国政的太宰,也有掌贵族家务的家宰、掌管一邑的邑宰,实已为官的通称。"},{"id":1223,"type":"单选题","text":"乌龙茶又称青茶，属半发酵茶。主产于福建、广东和____。","options":[{"key":"A","text":"广西"},{"key":"B","text":"江西"},{"key":"C","text":"海南"},{"key":"D","text":"台湾"}],"answer":["D"],"explanation":"台湾乌龙的主要产区包括扩台北、桃园、新竹、苗栗和宜兰等地，著名品种有青心乌龙、冰顶乌龙、东方美人、金萱茶、翠玉茶、阿里山茶、杉林溪高山茶、梨山高冷茶等。"},{"id":1224,"type":"单选题","text":"目的在手 “究天人之际，通古今之变，成一家之言”的著作是____。","options":[{"key":"A","text":"《楚辞》"},{"key":"B","text":"《史记》"},{"key":"C","text":"《汉帛》"},{"key":"D","text":"《新书》"}],"answer":["B"],"explanation":"“究天人之际,通古今之变,成一家之言”的文学巨著是《史记》."},{"id":1225,"type":"单选题","text":"“尽道隋亡为此河，至今千里赖通波。若无水殿龙舟事，共禹论功不较多。”下列关于大运河说法正确的是____。","options":[{"key":"A","text":"从扬州借助大运河可以到达大兴（长安）"},{"key":"B","text":"大运河以汴州为中心"},{"key":"C","text":"大运河全程是人工开挖的"},{"key":"D","text":"大运河的主要作用是供隋炀帝乘船南下江南游玩"}],"answer":["A"],"explanation":"大运河以洛阳为中心；大运河运用了原有的自然河道，并不全是人工开挖的；大运河的主要作用是军事、经济方面；从扬州经大运河到巩县后，经三门峡，过广通渠可以到达长安（大兴）。"},{"id":1226,"type":"单选题","text":"在古代月圆和月缺一般形容什么？","options":[{"key":"A","text":"天气好坏"},{"key":"B","text":"悲欢离合"},{"key":"C","text":"凶吉象征"},{"key":"D","text":"身体是否健康"}],"answer":["B"],"explanation":"在古代月圆和月缺一般形容人的悲欢离合。“人有悲欢离合，月有阴晴圆缺”，在地球上所看到的月球被日光照亮部分的不"},{"id":1227,"type":"单选题","text":"我国现存最早的药学专著是____。","options":[{"key":"A","text":"《海药本草》"},{"key":"B","text":"《新修本草》"},{"key":"C","text":"《五七二病方》"},{"key":"D","text":"《神农本草经》"}],"answer":["D"],"explanation":"我国现存最早的中药学著作是《神农本草经》《神农本草经》又称《本草经》或《本经》,托名“神农”所作,实 成书于汉代,是中医四大经典著作之一,是现存最早的中药学著作。"},{"id":1228,"type":"单选题","text":"传说中的嫦娥是吃了谁送的灵药才飞进广寒宫的？","options":[{"key":"A","text":"西王母"},{"key":"B","text":"东王母"},{"key":"C","text":"玉帝"},{"key":"D","text":"太白金星"}],"answer":["A"],"explanation":"传说是后羿射下九个太阳后被贬下凡，嫦娥叫后羿到西王母那里去求长生不老药，后羿求得两包并打算和嫦娥一起服下，"},{"id":1229,"type":"单选题","text":"青铜器有什么用途？","options":[{"key":"A","text":"货币"},{"key":"B","text":"乐器"},{"key":"C","text":"牛产工貝"},{"key":"D","text":"以上皆是"}],"answer":["D"],"explanation":"古代青铜器的主要用于食器、酒器、水器、乐器、兵器、车马器、农器与工具、货币、玺印与符节、度量衡器、铜镜、杂器等。"},{"id":1230,"type":"单选题","text":"成语“一衣带水”中的“水”原指什么？","options":[{"key":"A","text":"黄河"},{"key":"B","text":"长江"},{"key":"C","text":"淮河"},{"key":"D","text":"珠江"}],"answer":["B"],"explanation":"“一衣带水”中的“水”原指长江。长江发源于青藏高原的唐古拉山脉各拉丹冬峰西南侧，全长约6300㎞，比黄河长800余公里，在世界大河中长度仅次于非洲的尼罗河和南美洲的亚马逊河"},{"id":1231,"type":"单选题","text":"《诗经》被称为“经”是在____。","options":[{"key":"A","text":"先秦"},{"key":"B","text":"秦代"},{"key":"C","text":"汉代"},{"key":"D","text":"南北朝"}],"answer":["C"],"explanation":"诗经被称为经是在“西汉时期”。《诗经》在先秦时期称为《诗》，或取其整数称《诗三百》。西汉时被尊为儒家经典，始称《诗经》，并沿用至今。"},{"id":1232,"type":"单选题","text":"“从来佳茗似佳人”是我国古代哪位著名诗人的名句？","options":[{"key":"A","text":"李白"},{"key":"B","text":"杜甫"},{"key":"C","text":"苏轼"},{"key":"D","text":"李清照"}],"answer":["C"],"explanation":"“从来佳茗似佳人”出自苏轼的《次韵曹辅寄壑源试焙新芽》。"},{"id":1233,"type":"单选题","text":"____拳是一种流传于我国南方个省拳势刚烈的拳术","options":[{"key":"A","text":"太极拳"},{"key":"B","text":"形意拳"},{"key":"C","text":"长拳"},{"key":"D","text":"南拳"}],"answer":["D"],"explanation":"南拳又称南方拳，是明代以来流行于南方的拳种的总称。它以福建、广东为中心，广泛流传于长江以南地区，故称南拳。作为南少林等拳种与中国南方各地拳种相结合的产物，技术套路繁多，遍布各省。由于历史悠久，再加上师承关系的演变，形成了多种打法，但多数套路..."},{"id":1234,"type":"单选题","text":"《左传》全称是____。","options":[{"key":"A","text":"《春秋左氏传》"},{"key":"B","text":"《左氏春秋》"},{"key":"C","text":"《春秋内传》"},{"key":"D","text":"《春秋外传》"}],"answer":["A"],"explanation":"《春秋左传》又名《左传》，是我国现存的史类文学作品。相传为春秋末年的左丘明为解释孔子的《春秋》而作，实际上成书时间当在战国或两汉之间。作品记事起于鲁隐公元年(公元前722年)，止于鲁悼公十四年(公元前454年)，比《春秋》记事时间延长了许多。"},{"id":1235,"type":"单选题","text":"先秦最后一位儒学大师是____。","options":[{"key":"A","text":"孟子"},{"key":"B","text":"子夏"},{"key":"C","text":"颜渊"},{"key":"D","text":"荀子"}],"answer":["D"],"explanation":"先秦最后一位儒学大师是荀子，他是先秦集诸子百家之大成的著名学者，是我国古代杰出的唯物主义哲学家，又是卓有成效的大教育家。"},{"id":1236,"type":"单选题","text":"夏季烈日炎炎，骄阳似火，古人常常借此机会曝晒衣物、书籍及其他物品，这一天被俗称为曝晒节。曝晒节是农历哪一天？","options":[{"key":"A","text":"五月初八"},{"key":"B","text":"六月初六"},{"key":"C","text":"七月初五"},{"key":"D","text":"六月初九"}],"answer":["B"],"explanation":"暴晒节，是指阴历六月初六，正是盛夏，是一年中太阳光最猛的日子。"},{"id":1237,"type":"单选题","text":"“文章合为时而著，歌诗合为事而作”是由谁提出的？","options":[{"key":"A","text":"白居易"},{"key":"B","text":"柳宗元"},{"key":"C","text":"周敦颐"},{"key":"D","text":"刘禹锡"}],"answer":["A"],"explanation":"白居易是中唐时期影响极大的大诗人，他提出了自己的文学主张：“文章合为时而著，歌诗合为事而作。”而他的诗歌主张，也主要是就早期的讽谕诗的创作而发的。"},{"id":1238,"type":"单选题","text":"传说中的嫦娥，是谁的妻子？","options":[{"key":"A","text":"黄帝"},{"key":"B","text":"后羿"},{"key":"C","text":"大禹"},{"key":"D","text":"纣王"}],"answer":["B"],"explanation":"后羿，本称羿，是中国古代神话传说中的人物，擅于射箭，曾助尧帝射落九日，只留一日，因此在民间流传有“羿射九日”的典故。其为太阳神帝俊的臣子，嫦娥(姮娥)仙子的丈夫。"},{"id":1239,"type":"单选题","text":"《战国策》的编订者是____。","options":[{"key":"A","text":"孔子"},{"key":"B","text":"刘向"},{"key":"C","text":"班固"},{"key":"D","text":"司马迁"}],"answer":["B"],"explanation":"《战国策》是西汉刘向整理编订的。这是我国历史上第一部国别体史书,主要记述了战国时期的纵横家(游说之士)的政治主张和策略,展示了战国时代的历史特点和社会风貌,是研究战国历史的重要典籍。"},{"id":1240,"type":"单选题","text":"钢笔书法书写前的执笔角度大约为____度。","options":[{"key":"A","text":"10"},{"key":"B","text":"20"},{"key":"C","text":"40"},{"key":"D","text":"60"}],"answer":["C"],"explanation":"执笔的角度一般以40度左右为宜，执笔不要太低。"},{"id":1241,"type":"单选题","text":"月饼最初是用来做什么的？","options":[{"key":"A","text":"馈赠亲友的礼物"},{"key":"B","text":"祭奉月神的祭品"},{"key":"C","text":"节日食品"},{"key":"D","text":"地方小吃"}],"answer":["B"],"explanation":"祭月在我国是一种十分古老的习俗，月饼是古代中秋拜祭月神的供品，也是中秋节的时节食品。月饼圆又圆，又是合家分吃，象征着团圆和睦。在古时候每逢中秋夜都要举行祭月。设大香案，摆上月饼、水果等祭品。在月下，将月亮神像放在月亮的那个方向，红烛高燃，全家人依次拜祭月亮，然后由当家主妇切开团圆月饼。"},{"id":1242,"type":"单选题","text":"“白日依山尽，黄河入海流。欲穷千里目，更上一层楼。”是王之涣《登鹳雀楼》中的诗句，请问，鹳雀楼在下面哪个省？","options":[{"key":"A","text":"山西"},{"key":"B","text":"陕西"},{"key":"C","text":"山东"},{"key":"D","text":"江西"}],"answer":["A"],"explanation":"鹳雀楼在山西省。鹳雀楼又名鹳鹊楼,因时有鹳雀栖其上而得名,位于山西省永济市蒲州古城西面的黄河东岸。"},{"id":1243,"type":"单选题","text":"中国四大名楼不包括哪一项？","options":[{"key":"A","text":"黄鹤楼"},{"key":"B","text":"红楼"},{"key":"C","text":"滕王阁"},{"key":"D","text":"岳阳楼"}],"answer":["B"],"explanation":"中国四大名楼一般指四大名楼。 四大名楼，中国古代四大名楼的总称，江西南昌滕王阁，湖北武汉黄鹤楼，湖南岳阳岳阳楼，山东烟台蓬莱阁。"},{"id":1244,"type":"单选题","text":"武术最初作为_____训练手段。","options":[{"key":"A","text":"搏斗"},{"key":"B","text":"军事"},{"key":"C","text":"健身"},{"key":"D","text":"娱乐"}],"answer":["B"],"explanation":"武术最初作为军事训练手段，与古代军事斗争紧密相连，技击性非常明显。"},{"id":1245,"type":"单选题","text":"下列哪个不是合肥的别称？","options":[{"key":"A","text":"庐州"},{"key":"B","text":"泸州"},{"key":"C","text":"庐阳"},{"key":"D","text":"合州"}],"answer":["B"],"explanation":"泸州，古称“江阳”，别称酒城、江城，四川省辖地级市，全国区域中心城市。"},{"id":1246,"type":"单选题","text":"下列书法文字最多的篇目是_____。","options":[{"key":"A","text":"千字文"},{"key":"B","text":"兰亭序"},{"key":"C","text":"平复帖"},{"key":"D","text":"圣教序"}],"answer":["D"],"explanation":"《千字文》，内容有1000字；《兰亭序》全文28行、324字；《平复帖》共9行84字；《圣教序》有1904字。"},{"id":1247,"type":"单选题","text":"史称陶渊明不事权贵的性格表现是____。","options":[{"key":"A","text":"土木形骸，不自藻饰，恬静寡欲"},{"key":"B","text":"傲然独得，任性不羁，而喜怒不形于色"},{"key":"C","text":"岂能为五斗米折腰向乡里小儿"},{"key":"D","text":"安能摧眉折腰事权贵，使我不得开心颜"}],"answer":["C"],"explanation":"中国古代有不少因维护人格，保持气节而不食的故事。“陶渊明不为五斗米折腰”就是其中最具代表性的一例。"},{"id":1248,"type":"单选题","text":"红茶属于什么茶？","options":[{"key":"A","text":"不发酵茶"},{"key":"B","text":"半发酵茶"},{"key":"C","text":"完全发酵茶"},{"key":"D","text":"微发酵茶"}],"answer":["C"],"explanation":"红茶属于全发酵茶类，为六大茶类之一，是采摘茶树鲜叶为原料，经萎凋、揉捻、发酵、干燥、精制等工艺制成，成品茶具有条索紧结、金毫显露、滋味甜爽、汤色红亮等特点，如金骏眉、正山小种、滇红、祁门红茶、川红、英德红茶、九曲红梅都属于红茶。"},{"id":1249,"type":"单选题","text":"在人类历史上，第三次“兵器革命”是指什么发明？","options":[{"key":"A","text":"导弹"},{"key":"B","text":"弓箭"},{"key":"C","text":"火药"},{"key":"D","text":"原子弹"}],"answer":["C"],"explanation":"在人类历史上,具有“兵器革命”意义的事件共有五次，分别是弓与投石带的发明，车轮与战车的发明，火药的发明，军用飞行器的实用化以及原子弹的发明。"},{"id":1250,"type":"单选题","text":"“中国结”一般都是由多少条丝绳编织而成的？","options":[{"key":"A","text":"一"},{"key":"B","text":"二"},{"key":"C","text":"三"},{"key":"D","text":"四"}],"answer":["A"],"explanation":"中国结从头到尾都是用一根丝线编结而成，每一个基本结又根据其形、意命名。把不同的结饰互相结合在一起，或用其它具有吉祥图案的饰物搭配组合，就形成了造型独特、绚丽多彩、寓意深刻、内涵丰富的中国传统吉祥装饰物品。"},{"id":1251,"type":"单选题","text":"“揭竿为旗，斩木为兵”形容的是哪一场起义？","options":[{"key":"A","text":"赤眉起义"},{"key":"B","text":"陈胜吴广起义"},{"key":"C","text":"绿林起义"},{"key":"D","text":"黄巾起义"}],"answer":["B"],"explanation":"“揭竿为旗，斩木为兵”形容的是秦末陈胜、吴广领导的农民起义。公元前209年，九百多个农民被征发到渔阳守长城。他们走到大泽乡，遇上了连日大雨冲毁了道路，不能按期到达。按照秦法，误期者要被处斩。小队长陈胜和吴广设计杀死军官，号召大家起义，于是秦末农民起义爆发 。"},{"id":1252,"type":"单选题","text":"“拱手而立”表示对长者的尊敬，一般来说，男子行拱手礼时应该____。","options":[{"key":"A","text":"左手在外"},{"key":"B","text":"右手在外"},{"key":"C","text":"双手交叉"},{"key":"D","text":"双手相握"}],"answer":["A"],"explanation":"男子行拱手礼时，右手握拳在内，左手在外。以左示人，表示真诚与尊敬。男子右手代表攻击，左手代表尊敬，因此是左手在外包着右手。"},{"id":1253,"type":"单选题","text":"“一琴一鹤”所形容的是什么样的品质？","options":[{"key":"A","text":"为政清简"},{"key":"B","text":"平安长乐"},{"key":"C","text":"淡泊名利"},{"key":"D","text":"骄奢淫逸"}],"answer":["A"],"explanation":"一琴一鹤原指宋朝赵抃去四川做官随身携带的东西仅有一张琴和一只鹤；形容行装简少，也比喻为官清廉。"},{"id":1254,"type":"单选题","text":"壁画《飞天》是下面哪个石窟的代表作？","options":[{"key":"A","text":"莫高窟"},{"key":"B","text":"云冈石窟"},{"key":"C","text":"龙门石窟"},{"key":"D","text":"麦积山石窟"}],"answer":["A"],"explanation":"敦煌飞天从艺术形象上说，它不是一种文化的艺术形象，而是多种文化的复合体。飞天的故乡虽在印度，但敦煌飞天却是印度文化、西域文化、中原文化共同孕育成的。它是佛教天人和道教羽人、西域飞天和中原飞天长期交流后融合为一，具有中国文化特色的飞天。它是不长翅膀不生羽毛、没有圆光、借助云而不依靠云，主要凭借飘逸的衣裙、飞舞的彩带而凌空翱翔的飞天。敦煌飞天可以说是中国艺术家最天才的创作，是世界美术史上的一个奇迹。"},{"id":1255,"type":"单选题","text":"“近朱者赤，近墨者黑”所蕴含的道理和下列哪句话最相似？","options":[{"key":"A","text":"青出于蓝而胜于蓝"},{"key":"B","text":"蓬生麻中，不扶而直"},{"key":"C","text":"公生明，偏生暗"},{"key":"D","text":"出淤泥而不染，濯清涟而不妖"}],"answer":["B"],"explanation":"二者都是用于比喻客观环境对人有很大影响。"},{"id":1256,"type":"单选题","text":"“桃李满天下”的“桃李”指什么？","options":[{"key":"A","text":"朋友"},{"key":"B","text":"学生"},{"key":"C","text":"同事"},{"key":"D","text":"产业"}],"answer":["B"],"explanation":"比喻所栽培的后辈或所教的学生很多，各地都有。"},{"id":1257,"type":"单选题","text":"“楚河”和“汉界”在今天的哪个省？","options":[{"key":"A","text":"湖北"},{"key":"B","text":"河南"},{"key":"C","text":"河北"},{"key":"D","text":"湖南"}],"answer":["B"],"explanation":"“楚河汉界”指的是河南省荥阳市黄河南岸广武山上的鸿沟。相传“楚河汉界”是汉高祖刘邦和西楚霸王项羽划定的楚汉边界，后来才慢慢搬到了棋盘上。"},{"id":1258,"type":"单选题","text":"“鼎”的最初用途是什么？","options":[{"key":"A","text":"祭祀用礼器"},{"key":"B","text":"地位象征物"},{"key":"C","text":"烹煮器具"},{"key":"D","text":"家具装饰"}],"answer":["C"],"explanation":"最初的鼎是由远古时期陶制的食具演变而来的，主要用途是烹煮食物。自从青铜鼎出现后，它又多了一项功能，成为祭祀神灵的一种重要礼器。"},{"id":1259,"type":"单选题","text":"“水”字属于下列哪种汉字构成方式？","options":[{"key":"A","text":"象形字"},{"key":"B","text":"表意字"},{"key":"C","text":"形声字"},{"key":"D","text":"假借字"}],"answer":["A"],"explanation":"水字属于汉字构成方式里的象形字。 象形字又被称为表意文字,是一 种最古老的字体,是由图画文字演化而来的。"},{"id":1260,"type":"单选题","text":"中国古代哲学中，有“阴阳八卦”的理论，这一理论出自什么书？","options":[{"key":"A","text":"《尚书》"},{"key":"B","text":"《论语》"},{"key":"C","text":"《周易》"},{"key":"D","text":"《孟子》"}],"answer":["C"],"explanation":"阴阳八卦的理论出自《周易》。易为太极,是生两仪,两仪生四象,四象生八卦。"},{"id":1261,"type":"单选题","text":"李白的诗风是什么？","options":[{"key":"A","text":"沉郁、雄浑"},{"key":"B","text":"豪迈、奔放"},{"key":"C","text":"通俗、易懂"},{"key":"D","text":"狂傲、不驯"}],"answer":["B"],"explanation":"李白的诗风:豪迈奔放,清新飘逸,想象丰富,意境奇妙,语言奇妙,浪漫主义,立意清晰。"},{"id":1262,"type":"单选题","text":"传说春节放炮是为了驱赶一个怪兽，这个怪兽是____。","options":[{"key":"A","text":"麒麟"},{"key":"B","text":"蒲牢"},{"key":"C","text":"年"},{"key":"D","text":"龙"}],"answer":["C"],"explanation":"“年”是汉族民间传说的凶兽,头长尖角,凶猛异常。年兽长年深居海底,每到除夕,爬上岸来吞食牲畜伤害人命。因此每到除夕,村村寨寨的人们扶老携幼,逃往深山,以躲避“年”的伤害。后来,一个老人用“贴红纸”和“放鞭炮”的办法成功赶走了年兽,人们从此过年不再惧怕年兽,于是过年放鞭炮的传统也就流传了下来。"},{"id":1263,"type":"单选题","text":"2022年是农历什么年？","options":[{"key":"A","text":"乙亥年"},{"key":"B","text":"丁亥年"},{"key":"C","text":"壬寅年"},{"key":"D","text":"辛亥年"}],"answer":["C"],"explanation":"2022年,农历是壬寅年,属相虎。"},{"id":1264,"type":"单选题","text":"《霓裳羽衣曲》是由谁编制的道教乐曲？","options":[{"key":"A","text":"唐太宗"},{"key":"B","text":"唐高宗"},{"key":"C","text":"唐玄宗"},{"key":"D","text":"唐宪宗"}],"answer":["C"],"explanation":"《霓裳羽衣曲》即《霓裳羽衣舞》是唐玄宗为道教所作之曲,用于在太清宫祭献老子时演奏。"},{"id":1265,"type":"单选题","text":"我国小说史上繁荣时期在____。","options":[{"key":"A","text":"秦汉"},{"key":"B","text":"三国"},{"key":"C","text":"隋唐"},{"key":"D","text":"明清"}],"answer":["D"],"explanation":"明清时期是我国古典小说的繁荣时期，秦汉、三国和隋唐时期的主要文学形式不是小说。"},{"id":1266,"type":"单选题","text":"主持修建芍陂水利工程的是____。","options":[{"key":"A","text":"孙叔敖"},{"key":"B","text":"李冰"},{"key":"C","text":"西门豹"},{"key":"D","text":"郑国"}],"answer":["A"],"explanation":"楚国令尹孙叔敖主持治水,倾尽家资,历时三载,终于修筑了中国历史上第一座水利工程——芍陂。"},{"id":1267,"type":"单选题","text":"中国的古典小说中，有些在成书之前就有说书人说演。下列哪部作品在成书之前没有说书人说演？","options":[{"key":"A","text":"《西游记》"},{"key":"B","text":"《红楼梦》"},{"key":"C","text":"《三国演义》"},{"key":"D","text":"《水浒传》"}],"answer":["B"],"explanation":"四大名著中《红楼梦》在成书之前没有说书人说演。"},{"id":1268,"type":"单选题","text":"古琴是在哪一年被联合国教科文组织列为世界第二批“人类口头和非物质遗产代表作”之一的？","options":[{"key":"A","text":"2001年"},{"key":"B","text":"2002年"},{"key":"C","text":"2003年"},{"key":"D","text":"2004年"}],"answer":["C"],"explanation":"2003年11月7日下午，联合国教科文组织总干事松浦晃一郎在巴黎宣布，中国的古琴成为“人类口头和非物质文化遗产”。"},{"id":1269,"type":"单选题","text":"明代思想家、文学家____继承了王阳明的心学思想，他提出的“童心说”对当时的思想界以及文坛形成了巨大冲击。","options":[{"key":"A","text":"袁宏道"},{"key":"B","text":"袁中道"},{"key":"C","text":"李梦阳"},{"key":"D","text":"李贽"}],"answer":["D"],"explanation":"《童心说》是明代末期杰出思想家李贽的一篇议论文，收录于《焚书》。该文写于明神宗万历十四年（1585年），主要是用来驳斥耿定向的理论。李贽在该文中主要阐述了“童心”的文学观念。“童心”就是赤子之心，“一念之本心”，实际上只是表达个体的真实感受与真实愿望的“私心”，是真心与真人得以成立的依据。李贽将认知的是非标准归结为童心。他认为文学都必须真实坦率地表露作者内心的情感和人生的欲望。"},{"id":1270,"type":"单选题","text":"《论语》“父母在，不远游，游必有方”一句中“方”的意思是____。","options":[{"key":"A","text":"方向，去处"},{"key":"B","text":"方法，办法"},{"key":"C","text":"区域，地方"},{"key":"D","text":"理由，道理"}],"answer":["A"],"explanation":"“父母在世的时候,不出远门去求学、做官,万一要出远门,必须有一定的去处.这里“方”指一定的去处,不让父母担心的去处。”"},{"id":1271,"type":"单选题","text":"我国第一个热带植物园是____。","options":[{"key":"A","text":"兴隆热带植物园"},{"key":"B","text":"呀路古热带植物园"},{"key":"C","text":"葫芦岛热带植物园"},{"key":"D","text":"西双版纳热带植物园"}],"answer":["D"],"explanation":"中国科学院西双版纳热带植物园，隶属于中国科学院，始建于1958年，是我国第一个热带植物园位于中国云南省西双版纳傣族自治州勐腊县勐仑镇，是集科学研究、物种保存和科普教育为一体的综合性研究机构和风景名胜区，在2011年7月被评为国家5A级旅游景区。"},{"id":1272,"type":"单选题","text":"位于滇西边陲、高黎贡山西麓，早在公元前2世纪便是西南丝绸之路上的边关小镇，被称为“极边第一城”的是____。","options":[{"key":"A","text":"施甸"},{"key":"B","text":"祥云"},{"key":"C","text":"腾冲"},{"key":"D","text":"龙陵"}],"answer":["C"],"explanation":"​​腾冲被称为“极边第一城”,相传是徐霞客所题。"},{"id":1273,"type":"单选题","text":"抗日战争时期，中国唯一的一条国际通道是____。","options":[{"key":"A","text":"中印公路"},{"key":"B","text":"滇桂公路"},{"key":"C","text":"滇缅公路"},{"key":"D","text":"滇黔公路"}],"answer":["C"],"explanation":"抗日期间，我国沿海口岸及对外交通要道先后沦陷，1938年新开辟的滇缅公路，成为战时我国唯一的国际通道。"},{"id":1274,"type":"单选题","text":"韩非子是战国末期法家思想的集大成者，下列著作中，与韩非子无关的是____。","options":[{"key":"A","text":"《孤愤》"},{"key":"B","text":"《五蠹》"},{"key":"C","text":"《德立》"},{"key":"D","text":"《说难》"}],"answer":["C"],"explanation":"《德立》的作者为慎子。"},{"id":1275,"type":"单选题","text":"作为先秦法家的主要代表人物，商鞅在推行变法改革中最大的特点是____。","options":[{"key":"A","text":"“壹刑”"},{"key":"B","text":"“重刑”"},{"key":"C","text":"“任法”"},{"key":"D","text":"“明法”"}],"answer":["B"],"explanation":"商鞅变法核心内容是“重农”和“法治”。为推行“法治”而提出“重刑”,指轻罪重罚,就是用恐怖手段制造一种威慑力量,驱使民众就统治阶级之范。即公开主张“禁奸止过,莫若重刑”。"},{"id":1276,"type":"单选题","text":"春秋时期，推行富国强兵的改革措施，建议齐桓公树立“尊王攘夷”旗帜的是____。","options":[{"key":"A","text":"管仲"},{"key":"B","text":"鲍叔牙"},{"key":"C","text":"孙叔敖"},{"key":"D","text":"商鞅"}],"answer":["A"],"explanation":"齐桓公元年（前685年），管仲得到鲍叔牙推荐，担任国相，辅佐齐桓公成为春秋五霸之首。对内大兴改革、富国强兵；对外尊王攘夷，九合诸侯，一匡天下，被尊称为“仲父”。"},{"id":1277,"type":"单选题","text":"神话是苗族文学中最古老的类型，体现了苗族先民对宇宙万物的认识。下列神话故事中，不属于苗族的是____。","options":[{"key":"A","text":"《天地争霸》"},{"key":"B","text":"《枫木生人》"},{"key":"C","text":"《板东辰》"},{"key":"D","text":"《人祖阿丹》"}],"answer":["D"],"explanation":"《人祖阿丹》是回族古代神话传说之一。"},{"id":1278,"type":"单选题","text":"谁通过多年征战，于1616年统一了女真各部，建立后金政权？","options":[{"key":"A","text":"完颜阿骨打"},{"key":"B","text":"努尔哈赤"},{"key":"C","text":"皇太极"},{"key":"D","text":"多尔衮"}],"answer":["B"],"explanation":"明朝后期，女真杰出首领努尔哈赤统一了女真各部。1616年努尔哈赤自立为汗，建立了后金。后金建立后，多次打败明军，夺取了明朝广大地区。1635年，皇太极改女真族名为满洲，1636年，皇太极改国号为清。"},{"id":1279,"type":"单选题","text":"在中国古代科举考试制度中，殿试的第一名被称为____。","options":[{"key":"A","text":"状元"},{"key":"B","text":"榜首"},{"key":"C","text":"榜眼"},{"key":"D","text":"解元"}],"answer":["A"],"explanation":"中国古代科举制度中，通过最后一级考试者，称为进士。是古代科举殿试及第者之称。意为可以进授爵位之人。此称始见于《礼记·王制》。隋炀帝大业年间始置进士科目。唐亦设此科，凡应试者谓之举进士，中试者皆称进士。元、明、清时，贡士经殿试后，及第者皆赐出身，称进士。且分为三甲：一甲3人，赐进士及第；二、三甲，分赐进士出身、同进士出身。考中进士，一甲即授官职，其余二甲参加翰林院考试，学习三年再授官职。"},{"id":1280,"type":"单选题","text":"《三国演义》讲述了许多经典故事，也塑造了许多栩栩如生的人物形象。“单骑救主”故事中的主人公是____。","options":[{"key":"A","text":"关羽"},{"key":"B","text":"张飞"},{"key":"C","text":"赵云"},{"key":"D","text":"马超"}],"answer":["C"],"explanation":"单骑救主，出自元末明初罗贯中的小说《三国演义》第四十一回“刘玄德携民渡江 赵子龙单骑救主”，原型为东汉建安十三年(公元208年)曹操追击刘备于当阳长坂坡，随军眷属被曹军围困，部将赵云身抱刘备之子阿斗，奋勇血战，力保刘妻甘夫人突围，使其母子二人幸免于难之事。"},{"id":1281,"type":"单选题","text":"被世人形容“口蜜腹剑”的是唐朝哪一个大臣？","options":[{"key":"A","text":"李林甫"},{"key":"B","text":"杨国忠"},{"key":"C","text":"魏征"},{"key":"D","text":"房玄龄"}],"answer":["A"],"explanation":"“口蜜腹剑”是李林甫官场攀升之路的武器，凡是有才能、功绩、声望的人才必定要受到李林甫的打压，他依靠这种本事，久居宰相之位，对朝廷和国家造成不可估量的损失。"},{"id":1282,"type":"单选题","text":"我国长期以来把“和平共处五项原则”作为我们处理对外关系的基本准则。请问，它与哪位思想家“兼爱非攻”的思想不谋而合？","options":[{"key":"A","text":"韩非子"},{"key":"B","text":"墨子"},{"key":"C","text":"庄子"},{"key":"D","text":"荀子"}],"answer":["B"],"explanation":"“兼爱非攻”墨家学派的主要思想观点。其它节用、节葬、非乐等主张，也都是由此而派生出来的。"},{"id":1283,"type":"单选题","text":"俗称“昆明海”或“昆明湖”，为中国西南地区第一大湖，有“高原明珠”之誉的是____。","options":[{"key":"A","text":"鄱阳湖"},{"key":"B","text":"太湖"},{"key":"C","text":"滇池"},{"key":"D","text":"青海湖"}],"answer":["C"],"explanation":"滇池,位于昆明市的西南,它也被称昆明湖和滇海。注入它的河流有很多,有盘龙江等,所以它的面积是很大的。它还是云南省最大的淡水湖,有着高原明珠的称号。"},{"id":1284,"type":"单选题","text":"在云南，三多节是哪个少数民族的传统节日？","options":[{"key":"A","text":"傈僳族"},{"key":"B","text":"纳西族"},{"key":"C","text":"景颇族"},{"key":"D","text":"傣族"}],"answer":["B"],"explanation":"三多节为每年的农历二月初八，纳西语叫“三多颂”，源于白沙玉龙村北岳庙会，是纳西族法定民族节日、纳西族传统节日、纳西族祭祀本民族的最大保护神的盛大节日。"},{"id":1285,"type":"单选题","text":"《猴梨园》讲述了一只猴子经过主人训练之后，可以灵活模仿梨园戏子的各种动作的故事。《猴梨园》的作者是____。","options":[{"key":"A","text":"朱熹"},{"key":"B","text":"袁枚"},{"key":"C","text":"徐芳"},{"key":"D","text":"李梦阳"}],"answer":["C"],"explanation":"《猴梨园》讲述了一只猴子经过主人训练之后，可以灵活模仿梨园戏子的各种动作的故事。"},{"id":1286,"type":"单选题","text":"“止戈为武”的意思是，停止动用武器才是真正的武功，最早提出这一观点的是____。","options":[{"key":"A","text":"齐桓公"},{"key":"B","text":"楚庄王"},{"key":"C","text":"晋文公"},{"key":"D","text":"汉文帝"}],"answer":["B"],"explanation":"“止戈为武”的意思是，停止动用武器才是真正的武功，最早提出这一观点的是楚庄王。"},{"id":1287,"type":"单选题","text":"在《论语·宪问》里，孔子说：“微管仲，吾其披发左衽矣。”其中“衽”的意思是____。","options":[{"key":"A","text":"压襟"},{"key":"B","text":"袖口"},{"key":"C","text":"衣襟"},{"key":"D","text":"腰带"}],"answer":["C"],"explanation":"《论语·宪问》里有一条孔子语录：“微管仲，吾其被发左衽矣”。这句话直接翻译的意思是：如果没有管仲，我们恐怕要披头散发穿左衽的衣服了。其中“衽”指的是衣襟。"},{"id":1288,"type":"单选题","text":"“我善养吾浩然之气”是诸子中谁说的？","options":[{"key":"A","text":"孔子"},{"key":"B","text":"孟子"},{"key":"C","text":"庄子"},{"key":"D","text":"老子"}],"answer":["B"],"explanation":"“我善养吾浩然之气”是孟子说的。原文：（公孙丑问曰）：“敢问夫子恶乎长？”曰：“我知言，我善养吾浩然之气。”"},{"id":1289,"type":"单选题","text":"“古今多少事，都付笑谈中”表达了词人淡泊洒脱的情怀，词句的作者是____。","options":[{"key":"A","text":"苏轼"},{"key":"B","text":"陆游"},{"key":"C","text":"杨慎"},{"key":"D","text":"辛弃疾"}],"answer":["C"],"explanation":"“古今多少事,都付笑谈中”表达了词人淡泊洒脱的情怀,词句的作者是杨慎。"},{"id":1290,"type":"单选题","text":"我国自古就是农业大国，水患治理和农业灌溉关系国计民生。春秋战国时期，掌管土木工程的大臣官职名称为____。","options":[{"key":"A","text":"司徒"},{"key":"B","text":"司空"},{"key":"C","text":"司马"},{"key":"D","text":"司寇"}],"answer":["B"],"explanation":"司徒掌管土地和劳役；司马掌管军事；司空掌管土木工程建立；司寇掌管刑罚。"},{"id":1291,"type":"单选题","text":"汉武帝时期实施的____首次将“二十四节气”订入历法。","options":[{"key":"A","text":"《大衍历》"},{"key":"B","text":"《太初历》"},{"key":"C","text":"《授时历》"},{"key":"D","text":"《大明历》"}],"answer":["B"],"explanation":"汉武帝时期实施的《太初历》首次将“二十四节气”订入历法。"},{"id":1292,"type":"单选题","text":"“今圣王没，名守慢，奇辞起，名实乱。”这句话出自____。","options":[{"key":"A","text":"《荀子》"},{"key":"B","text":"《孟子》"},{"key":"C","text":"《论语》"},{"key":"D","text":"《老子》"}],"answer":["A"],"explanation":"“今圣王没，名守慢，奇辞起，名实乱”出自《荀子》。《荀子》全书一共32篇，是战国时期荀子和弟子们整理或记录他人言行的哲学著作。"},{"id":1293,"type":"单选题","text":"中国古代著名医药典籍《滇南本草》的作者是____。","options":[{"key":"A","text":"张仲景"},{"key":"B","text":"兰茂"},{"key":"C","text":"李时珍"},{"key":"D","text":"孙思邈"}],"answer":["B"],"explanation":"《滇南本草》是我国民族医药经典名著。作者兰茂，字廷秀，号止庵，云南嵩明杨林人，祖籍河南洛阳。"},{"id":1294,"type":"单选题","text":"《三十六计》是体现我国古代卓越军事思想的一部兵书，下列不属于《三十六计》的是____。","options":[{"key":"A","text":"浑水摸鱼"},{"key":"B","text":"反戈一击"},{"key":"C","text":"笑里藏刀"},{"key":"D","text":"反客为主"}],"answer":["B"],"explanation":"反戈一击不是三十六计。 反戈一击不属于三十六计,反戈一击的出处明代罗贯中的《三国演义》第十七回,反戈一击指的是调转枪头向原来所属的阵营进攻,比喻一旦觉悟,回过头来对自己一方的坏人坏事进行揭露和斗争。"},{"id":1295,"type":"单选题","text":"下面哪个剧种被称为“中国百戏之师”？","options":[{"key":"A","text":"京剧"},{"key":"B","text":"黄梅戏"},{"key":"C","text":"昆曲"},{"key":"D","text":"越剧"}],"answer":["C"],"explanation":"昆曲。昆曲是明朝中叶至清代中叶戏曲中影响最大的声腔剧种，很多剧种都是在昆剧的基础上发展起来的，被称为“百戏之祖，百戏之师”，有 “中国戏曲之拓展资料昆剧（Kun Opera），原名“昆山腔”、“昆腔”，是中国古老的戏曲声腔、剧种。清代以来被称为“昆曲”，现又被称为“昆剧"},{"id":1296,"type":"单选题","text":"被誉为“万国之园”的是____。","options":[{"key":"A","text":"颐和园"},{"key":"B","text":"圆明园"},{"key":"C","text":"静明园"},{"key":"D","text":"西花园"}],"answer":["B"],"explanation":"被誉为“万国之园”的是圆明园。 圆明园又称圆明三园,是清代一座大型皇家园林,它坐落在北京西北郊,与颐和园毗邻,由圆明园、长春园和绮春园组成,所以也叫圆明三园。"},{"id":1297,"type":"单选题","text":"哪个不是中国六大古都？","options":[{"key":"A","text":"南昌"},{"key":"B","text":"开封"},{"key":"C","text":"西安"},{"key":"D","text":"洛阳"}],"answer":["A"],"explanation":"六大古都是西安、洛阳、开封、杭州、南京、北京。"},{"id":1298,"type":"单选题","text":"柳宗元在《三戒》中通过叙述哪三种动物的故事，隐喻应当引以为戒的三种社会现象？","options":[{"key":"A","text":"麋鹿、驴子、老鼠"},{"key":"B","text":"老虎、驴子、老鼠"},{"key":"C","text":"狼、狐狸、老虎"},{"key":"D","text":"麋鹿、狼、狐狸"}],"answer":["A"],"explanation":"作者通过麋、驴、鼠这三种动物形象，借题发挥，揭露了当时一些达官贵人、得意小人的丑态，并预言其必然灭亡的命运。文章语言简洁凝练，以小见大，耐人寻味，具有强烈的现实讽刺意义。"},{"id":1299,"type":"单选题","text":"老子认为，“失道而后德，失德而后仁，失仁而后义，失义而后礼”。孔子则说，“不学礼，无以立”，要“非礼勿视，非礼勿听，非礼勿言，非礼勿动”。这反映出，当时的他们____。","options":[{"key":"A","text":"迎合封建贵族政治诉求"},{"key":"B","text":"反思西周的礼乐文化"},{"key":"C","text":"主张维护夏商周制度"},{"key":"D","text":"得到统治者的积极支持"}],"answer":["B"],"explanation":"老子的意思是，失去了“道”而后才有“德”，失去了“德”而后才有“仁”，失去了“仁”而后才有“义”，失去了“义”而后才有“礼”。他认为礼是道德缺失后的产物，所以是反对礼；而孔子则认为礼是一个人立身之本，倡导礼。这体现了两位思想家对周礼的反思，B项正确。"},{"id":1300,"type":"单选题","text":"李清照“绿肥红瘦”描写的是什么季节的景色？","options":[{"key":"A","text":"晚春"},{"key":"B","text":"仲夏"},{"key":"C","text":"孟夏"},{"key":"D","text":"深秋"}],"answer":["A"],"explanation":"李清照词中的绿肥红瘦描写的是晚春的景色。"},{"id":1301,"type":"单选题","text":"西汉初期，道家学说兼采阴阳、儒、墨、名、法各家学说的精髓；后来董仲舒的儒家学说也吸收阴阳五行、法、道等各种思想。促成当时学术思想上呈现这种特征的主要因素是____。","options":[{"key":"A","text":"王国势力强大"},{"key":"B","text":"百家争鸣局面的延续"},{"key":"C","text":"现实统治需要"},{"key":"D","text":"兼收并蓄的文化政策"}],"answer":["C"],"explanation":"根据所学知识可知，“王国势力强大”是董仲舒新儒学出现的一个因素，但不是主要因素，A项错误；百家争鸣局面在秦朝建立后被中断，其政治、经济社会环境均不存在，B项错误；汉初，统治者信奉黄老之学，是适应汉初经济恢复的需要，汉武帝时代，为适应加强中央集权的需要，董仲舒修正儒家学说，兼采他家思想，符合时代需求，故C项正确。汉武帝采纳董仲舒的建议，实行“罢黜百家，独尊儒术”的思想政策，D项错误。"},{"id":1302,"type":"单选题","text":"八斗正在参观一场书法展，当他看到一幅幅书法作品时便觉得好奇——古人是如何创造出汉字的？为了解开心中的疑惑，八斗准备去图书馆查找相关图书，探究古人造字的艺术。下面哪本书对八斗最有帮助？","options":[{"key":"A","text":"《尔雅》"},{"key":"B","text":"《方言》"},{"key":"C","text":"《释名》"},{"key":"D","text":"《说文解字》"}],"answer":["D"],"explanation":"《尔雅》是我国最早的一部词典，收集了比较丰富的古代汉语词汇，它是辞书之祖;《方言》是世界语言学史上最早的方言比较词汇集;《释名》是我国词源学第一部专著，该书主要以声训来探寻事物命名之源;《说文解字》是中国第一部系统地分析汉字字形和考究字源的字书，首次对汉字造字法（即“六书”）做出了具体的解释。"},{"id":1303,"type":"单选题","text":"祝岁习俗古已有之。《诗经》云:“称彼兕觥(酒杯)，万寿无疆。”汉代岁首，皇帝“大朝受贺”“百官受赐宴飨”。民间亦在岁首祭祀，其时全家依次列坐，向家长敬酒祝寿。该习俗____。","options":[{"key":"A","text":"出现于战国并兴盛于汉代"},{"key":"B","text":"体现礼仪教化与伦理秩序"},{"key":"C","text":"植根于我国古代商业文明"},{"key":"D","text":"仅是官方举行的庆祝仪式"}],"answer":["B"],"explanation":"由材料可知，祝岁习俗由来已久，从皇帝到普通百姓都很重视，通过举行各种仪式来体现对君主或长辈的敬意与美好期盼，体现了通过节庆礼仪进行教化和对伦理秩序的认同，B项正确。由材料中《诗经》的记述可知，该习俗在西周时就已经出现，排除A项；该习俗植根于我国古代农耕文明，排除C项；由材料可知，祝岁习俗并不仅是官方举行的庆祝仪式，在民间也有，排除D项。"},{"id":1304,"type":"单选题","text":"木板年画发源于四大名镇中的____。","options":[{"key":"A","text":"汉口镇"},{"key":"B","text":"景德镇"},{"key":"C","text":"朱仙镇"},{"key":"D","text":"佛山镇"}],"answer":["C"],"explanation":"木版年画发源于四大名镇中的朱仙镇。朱仙镇木版年画起源于唐，兴于宋，鼎盛于明清，历史悠久，源远流长，是中国四大木版年画之一，其制作采用木版与镂版相结合，水印套色，种类繁多，所用原料为炮制工序，用纸讲究，色彩艳丽，庄重深厚，题材和内容大多取材于历史戏剧、演义小说、神话故事和民间传说"},{"id":1305,"type":"单选题","text":"李贺在唐代被称为____。","options":[{"key":"A","text":"诗佛"},{"key":"B","text":"诗仙"},{"key":"C","text":"诗圣"},{"key":"D","text":"诗鬼"}],"answer":["D"],"explanation":"诗佛是唐代诗人王维，诗仙是指李白，诗圣是杜甫。"},{"id":1306,"type":"单选题","text":"唐代著名画家阎立本的《步辇图》，描绘了唐太宗李世民接见吐蕃使臣的情景。该作品体现了____。","options":[{"key":"A","text":"西域风情与中土文化的交汇"},{"key":"B","text":"文人意趣与市井风情的杂糅"},{"key":"C","text":"艺术审美与史料价值的统一"},{"key":"D","text":"现实主义与浪漫主义的融合"}],"answer":["C"],"explanation":"《步辇图》反映的是唐太宗接见吐蕃使臣的情景，可作为研究唐朝民族关系的史料，具有一定的史料价值；该绘画作品典雅绚丽，线条流畅，构图错落有致，画面中人物栩栩如生，具有较高的艺术价值，可见该作品是艺术审美和史料价值的统一，C项正确。该绘画作品反映的是唐太宗接见吐蕃使者，不能体现西域风情与中土文化交汇，排除A项；“市井风情”“浪漫主义”在材料中不能体现，排除B、D项。"},{"id":1307,"type":"单选题","text":"经魏晋多名士，有著名的竹林七贤，《与山巨源绝交书》是竹林七贤中的谁写给山涛的？","options":[{"key":"A","text":"阮籍"},{"key":"B","text":"嵇康"},{"key":"C","text":"刘伶"},{"key":"D","text":"向秀"}],"answer":["B"],"explanation":"嵇康《与山巨源绝交书》,是魏晋时期“竹林七贤”之一的嵇康写给朋友山涛(字巨源)的一封信,也是一篇名传千古的著名散文。"},{"id":1308,"type":"单选题","text":"唐代杜佑《通典》称:“理(治)道之先，在乎行教化。”该书内容分为食货、选举、职官、礼、乐、兵、刑、州郡、边防九门，其中“礼门”占全书篇幅的一半。从内容上看，杜佑修撰《通典》特别强调____。","options":[{"key":"A","text":"道家的无为而治"},{"key":"B","text":"史学的通古贯今"},{"key":"C","text":"儒家的伦理纲常"},{"key":"D","text":"理学的格物致知"}],"answer":["C"],"explanation":"结合所学内容可知，礼是儒家重要的思想范畴，“礼门”占了《通典》全书篇幅的一半，说明该书强调儒家的伦理纲常，C项正确。根据“礼门”所占篇幅可知是强调了儒家的伦理纲常，而非道家的无为而治和史学的通古贯今，排除AB项；理学出现在宋代，排除D项。"},{"id":1309,"type":"单选题","text":"我国首次完成太空授课的是____。","options":[{"key":"A","text":"刘洋"},{"key":"B","text":"王亚平"},{"key":"C","text":"杨利伟"},{"key":"D","text":"聂海胜"}],"answer":["B"],"explanation":"我国首次太空授课的人是王亚平。授课的具体时间是神舟十号，在2013年6月20日10时许，当时我国首次太空授课开始，由王亚平航天员在天宫一号开展基础物理实验，展示失重环境下物体运动特性、液体表面张力特性等物理现象。"},{"id":1310,"type":"单选题","text":"北宋时期，平民____发明了活字印刷术。","options":[{"key":"A","text":"毕昇"},{"key":"B","text":"蔡伦"},{"key":"C","text":"张衡"},{"key":"D","text":"祖冲之"}],"answer":["A"],"explanation":"北宋毕昇发明的活字印刷术。印刷术是中国古代汉族劳动人民的四大发明之一。它开始于唐朝的雕版印刷术，经宋仁宗时代的毕昇发展、完善，产生了活字印刷。"},{"id":1311,"type":"单选题","text":"下列历史事件发生在我国封建社会的是____。","options":[{"key":"A","text":"夏朝建立"},{"key":"B","text":"盘庚迁都"},{"key":"C","text":"武王伐纣"},{"key":"D","text":"陈胜吴广起义"}],"answer":["D"],"explanation":"A、B、C项均是发生在我国奴隶社会时期的历史事件，D项发生在秦朝末年。"},{"id":1312,"type":"单选题","text":"我国第一部纪传体通史是____。","options":[{"key":"A","text":"《尚书》"},{"key":"B","text":"《春秋》"},{"key":"C","text":"《左传》"},{"key":"D","text":"《史记》"}],"answer":["D"],"explanation":"我国第一部纪传体通史是《史记》。《史记》是我国西汉著名史学家司马迁撰写的一部纪传体史书,位列二十四史之首,与后来的《汉书》、《后汉书》、《三国志》合称。"},{"id":1313,"type":"单选题","text":"明中叶以后，添加插画的书籍大量刊行，出现了众多以绘画为主体的画本，甚至一些知名画家也受雇于坊刻。这说明当时____。","options":[{"key":"A","text":"画本成为知识传播主要载体"},{"key":"B","text":"市民文化是社会主流文化"},{"key":"C","text":"社会审美旨趣出现阶层分化"},{"key":"D","text":"书籍出版商业化程度加深"}],"answer":["D"],"explanation":"根据“添加插画的书籍大量刊行，出现了众多以绘画为主体的画本，甚至一些知名画家也受雇于坊刻”可得出随着商品经济的发展，书画为了适应商品经济发展而作出了调整，即应市场所需进行创作，D项正确。A项与材料主旨无关，排除；市民文化不是主流，排除B项；阶级分化的说法从材料不能得出，排除C项。"},{"id":1314,"type":"单选题","text":"被誉为“东方的莎士比亚”的明代戏剧家是____。","options":[{"key":"A","text":"关汉卿"},{"key":"B","text":"汤显祖"},{"key":"C","text":"王实甫"},{"key":"D","text":"孔尚任"}],"answer":["B"],"explanation":"汤显祖是明代伟大的戏剧家，被誉为“东方的莎士比亚”。他的代表作是《牡丹亭》。"},{"id":1315,"type":"单选题","text":"在我国古代的朋友交往中，情趣一致、十分要好的朋友是下面的哪一种？","options":[{"key":"A","text":"肺腑之交"},{"key":"B","text":"莫逆之交"},{"key":"C","text":"八拜之交"},{"key":"D","text":"同道之交"}],"answer":["B"],"explanation":"“莫逆之交”指非常要好的朋友，出自于战国·庄周《庄子·大宗师》。"},{"id":1316,"type":"单选题","text":"我国现存唐代最古老，规模最大的木质建筑群是____。","options":[{"key":"A","text":"唐代五台山古刹佛光寺和南禅寺"},{"key":"B","text":"应县木塔"},{"key":"C","text":"阿房宫"},{"key":"D","text":"唐代西安大雁塔"}],"answer":["A"],"explanation":"我国现存最早的木建筑古建木结构建筑是山西五台山南禅寺。"},{"id":1317,"type":"单选题","text":"国画《愚公移山》作者是____。","options":[{"key":"A","text":"齐白石"},{"key":"B","text":"徐悲鸿"},{"key":"C","text":"祝允明"},{"key":"D","text":"唐伯虎"}],"answer":["B"],"explanation":"《愚公移山》创作于1940年，是徐悲鸿在印度期间历时三个月绘制完成的巨幅设色水墨画。"},{"id":1318,"type":"单选题","text":"唐宋八大家属于唐朝的是____。","options":[{"key":"A","text":"韩愈"},{"key":"B","text":"王安石"},{"key":"C","text":"苏轼"},{"key":"D","text":"欧阳修"}],"answer":["A"],"explanation":"唐宋八大家是唐代韩愈、柳宗元和宋代欧阳修、苏洵、苏轼、苏辙、王安石、曾巩八位散文家的合称。"},{"id":1319,"type":"单选题","text":"台湾在三国时期称为____。","options":[{"key":"A","text":"夷州"},{"key":"B","text":"流求"},{"key":"C","text":"东番"},{"key":"D","text":"铜鼎"}],"answer":["A"],"explanation":"台湾在三国时期被称为夷州。根据西晋陈寿《三国志·吴志·孙权传》中记载，孙权听说夷州（今台湾）有数万家。"},{"id":1320,"type":"单选题","text":"中国小年要吃____。","options":[{"key":"A","text":"元宵"},{"key":"B","text":"饴糖"},{"key":"C","text":"腊八粥"},{"key":"D","text":"饺子"}],"answer":["B"],"explanation":"小年这一天，有吃饴糖的习俗，如有民谣说“二十三，糖瓜粘”。"},{"id":1321,"type":"单选题","text":"明清两代的科举考试中,会试放榜在农历四月十五日,该榜也被称为以下哪种?","options":[{"key":"A","text":"杏榜"},{"key":"B","text":"桂榜"},{"key":"C","text":"正榜"},{"key":"D","text":"副榜"}],"answer":["A"],"explanation":"因为当时正值阳春四月，杏花绽放，故称“杏榜”。会试放榜，可谓“杏榜题名”，得中者就是“贡士”，杏榜的头名就是“会元”。"},{"id":1322,"type":"单选题","text":"张渭《别韦郎中》一诗中有“不知郎中桑落酒，教人无奈别离何”一句，句中所提到的“桑落酒”原产地在____。","options":[{"key":"A","text":"永济"},{"key":"B","text":"桑落"},{"key":"C","text":"汾阳"},{"key":"D","text":"绵竹"}],"answer":["A"],"explanation":"桑落酒是我国传统的历史名酒，产于永济市。永济古称“河东”“阿中”“蒲州” 据文献记载：“北魏，河东郡多流离，谓之徙民。民有姓刘名白堕者，宿擅工酿，采挹河流，酿成芳酎，悬食同枯枝之年，排干桑落之辰，故酒得其名，最佳酌矣。”距今已有1600年的历史。"},{"id":1323,"type":"单选题","text":"“天道有常，不为尧存，不为桀亡。”是百家中哪位思想家的观点？","options":[{"key":"A","text":"孟子"},{"key":"B","text":"韩非子"},{"key":"C","text":"荀子"},{"key":"D","text":"老子"}],"answer":["C"],"explanation":"“天道有常,不为尧存,不为桀亡”是儒家荀子的观点。"},{"id":1324,"type":"单选题","text":"下列哪个不是端午节的意义？","options":[{"key":"A","text":"纪念屈原"},{"key":"B","text":"纪念伍子胥"},{"key":"C","text":"纪念范蠡"},{"key":"D","text":"纪念秋瑾"}],"answer":["C"],"explanation":"端午节的意义有纪念屈原、伍子胥和秋瑾。"},{"id":1325,"type":"单选题","text":"下列不属于中医的“五术”是____。","options":[{"key":"A","text":"山"},{"key":"B","text":"医"},{"key":"C","text":"命"},{"key":"D","text":"坤"}],"answer":["D"],"explanation":"中医中的五术是指山、医、命、相、卜。"},{"id":1326,"type":"单选题","text":"爵是一种典礼时用的酒器，那么爵有几只脚?","options":[{"key":"A","text":"三只脚"},{"key":"B","text":"两只脚"},{"key":"C","text":"四只脚"},{"key":"D","text":"五只脚"}],"answer":["A"],"explanation":"爵是中国古代一种用于饮酒的容器，三足，以不同的形状显示使用者的身份，在商代和的西周青铜礼器的考古发现中是非常常见的。"},{"id":1327,"type":"单选题","text":"孔子是____人。","options":[{"key":"A","text":"秦国"},{"key":"B","text":"鲁国"},{"key":"C","text":"卫国"},{"key":"D","text":"宋国"}],"answer":["B"],"explanation":"孔子(公元前551年9月28日－公元前479年4月11日)，子姓，孔氏，名丘，字仲尼，鲁国陬邑(今山东曲阜市)人，祖籍宋国栗邑(今河南省夏邑县)，中国古代思想家、政治家、教育家，儒家学派创始人。"},{"id":1328,"type":"单选题","text":"陶渊明的故乡是____。","options":[{"key":"A","text":"九江县"},{"key":"B","text":"星子县"},{"key":"C","text":"九江市"},{"key":"D","text":"南昌市"}],"answer":["A"],"explanation":"陶渊明的故乡在今天的江西九江。"},{"id":1329,"type":"单选题","text":"以下哪一个名称的由来与伍子胥有关?","options":[{"key":"A","text":"月老"},{"key":"B","text":"千金小姐"},{"key":"C","text":"新郎"},{"key":"D","text":"岳父"}],"answer":["B"],"explanation":"古时把富贵人家的未婚女孩称为“千金小姐”。公元前522年，伍子胥父兄被楚平王杀害。伍子胥逃离楚国，投奔吴国。途中他饥困交加，见一位浣纱姑娘竹筐里有饭，于是上前求乞。姑娘顿生恻隐之心，慨然相赠。伍子胥饱餐之后，出于安全原因，要求对方为他的行为保密。姑娘觉得人格受辱，遂抱起一石，投水而亡，以死明志。伍子胥见状，羞愤不已。他咬破手指，在石上血书：“尔浣纱，我行乞；我腹饱，尔身溺。十年之后，千金报德！”后来，伍子胥在吴国当了国相，吴王调遣劲旅攻入楚国。公元前506年，伍子胥“掘楚平王墓，其尸鞭之三百”。伍子胥报了大仇之后，又想到要报恩，但苦于不知姑娘家地址，于是就把千金投入她当时跳水的地方。这就是千金小姐的由来。"},{"id":1330,"type":"单选题","text":"苏轼的《题西林壁》如今刻在____。","options":[{"key":"A","text":"西林寺"},{"key":"B","text":"东林寺"},{"key":"C","text":"庐山"},{"key":"D","text":"龙虎山"}],"answer":["A"],"explanation":"苏轼的题西林壁原本是刻在江西庐山西林寺,后面经过移动后,又到了庐山的东林寺,随着时间的推移,遗迹早已被毁,为了纪念当时,东林寺现有仿制刻在东林寺寺碑之上。"},{"id":1331,"type":"单选题","text":"王维擅长的诗体是____。","options":[{"key":"A","text":"咏物诗"},{"key":"B","text":"咏景诗"},{"key":"C","text":"山水田园诗"},{"key":"D","text":"叙事诗"}],"answer":["C"],"explanation":"王维擅长的诗体是山水田园诗。"},{"id":1332,"type":"单选题","text":"耳环最原始的作用是____。","options":[{"key":"A","text":"女性身份的象征"},{"key":"B","text":"约束女性的行为"},{"key":"C","text":"装扮作用"},{"key":"D","text":"表示女性已婚"}],"answer":["B"],"explanation":"“耳环最原始的作用是约束女性的行为,据说当时因为有些妇女过于活跃,不甘居守,有人便想出在女子的耳上扎上一孔,并悬挂上耳珠,以提醒她们生活检点,行动谨慎。"},{"id":1333,"type":"单选题","text":"我们用“羞花”来形容历史上哪位美女？","options":[{"key":"A","text":"西施"},{"key":"B","text":"杨贵妃"},{"key":"C","text":"貂蝉"},{"key":"D","text":"王昭君"}],"answer":["B"],"explanation":"西施、王昭君、貂蝉和杨玉环被称为中国古代四大美女,沉鱼讲的是西施浣纱的故事,落雁讲的是昭君出塞的故事,闭月讲的是貂蝉拜月的故事,羞花讲的是杨玉环醉酒观花的故事。"},{"id":1334,"type":"单选题","text":"王冕在“冰雪林中著此身，不同桃李混芳尘。忽然一夜清香发，散作乾坤万里春。”这首诗中赞美的是什么花？","options":[{"key":"A","text":"菊花"},{"key":"B","text":"兰花"},{"key":"C","text":"梅花"},{"key":"D","text":"杏花"}],"answer":["C"],"explanation":"这首诗歌咏了白梅的高洁品格。它生长在冰天雪地的严冬，傲然开放，不与桃李凡花相混同。忽然一夜花开，芳香便传遍天下。诗人既是咏物，也是歌咏人的精神品格。表达了作者对白梅的喜爱之情。"},{"id":1335,"type":"单选题","text":"在我国汉代,缴纳一定数额的钱财，就可以入选做官，这种方式属于下面的哪一种？","options":[{"key":"A","text":"献赋"},{"key":"B","text":"纳赀"},{"key":"C","text":"通经"},{"key":"D","text":"通事"}],"answer":["B"],"explanation":"纳赀捐官，意思是向朝廷交纳钱财得到一个官职。赀的意思是钱财。"},{"id":1336,"type":"单选题","text":"《红楼梦》四大家族中没有下列哪个姓氏？","options":[{"key":"A","text":"吴"},{"key":"B","text":"贾"},{"key":"C","text":"王"},{"key":"D","text":"史"}],"answer":["A"],"explanation":"《红楼梦》中的四大家族是：贾家、史家、王家、薛家。"},{"id":1337,"type":"单选题","text":"以下不属于中医别称的是____。","options":[{"key":"A","text":"杏林"},{"key":"B","text":"悬壶"},{"key":"C","text":"黄芪"},{"key":"D","text":"歧黄"}],"answer":["C"],"explanation":"杏林、岐黄及悬壶都是中医的别称。"},{"id":1338,"type":"单选题","text":"中国古代宫殿建筑普遍采用什么颜色？","options":[{"key":"A","text":"黄色"},{"key":"B","text":"紫色"},{"key":"C","text":"红色"},{"key":"D","text":"蓝色"}],"answer":["C"],"explanation":"中国古代宫殿主体能够被阳光晒到的地方一般都是用的暖色，特别是朱红色，在阴影的部位一般都是用更多蓝绿相配的冷色，形成一种悦目的对比。"},{"id":1339,"type":"单选题","text":"中国全部少数民族语言分为几个系？","options":[{"key":"A","text":"5个"},{"key":"B","text":"6个"},{"key":"C","text":"7个"},{"key":"D","text":"8个"}],"answer":["A"],"explanation":"中国的全部少数民族语言分属五个语系:汉藏语系、阿尔泰语系、南亚语系、南岛语系、印欧语系。"},{"id":1340,"type":"单选题","text":"七夕节中国人通常吃____。","options":[{"key":"A","text":"蒿饼"},{"key":"B","text":"巧果"},{"key":"C","text":"汤圆"},{"key":"D","text":"竹筒饭"}],"answer":["B"],"explanation":"七夕节中国人通常吃巧果、酥糖等。巧果即是七夕果、乞巧果子,主要原材料是面粉和鸡蛋,是山东地区的特色传统糕点、七夕的应节食品,也是绍兴地区的七夕必备食品。"},{"id":1341,"type":"单选题","text":"苗族的传统乐器是____。","options":[{"key":"A","text":"笙"},{"key":"B","text":"笛"},{"key":"C","text":"萧"},{"key":"D","text":"芦笙"}],"answer":["D"],"explanation":"苗族的传统乐器有芦笙、唢呐、箫笛、胡琴、月琴等。"},{"id":1342,"type":"单选题","text":"清代，纂修宗谱成为一种普遍的社会行为，每部宗谱均有族规、家训，其内容主要包括血缘伦理、持家立业、报效国家等。这表明，宗谱的纂修____。","options":[{"key":"A","text":"反映了科举制度的导向作用"},{"key":"B","text":"体现了儒家思想观念"},{"key":"C","text":"维持了士族家庭的血统纯正"},{"key":"D","text":"确立了四民社会结构"}],"answer":["B"],"explanation":"根据题目中“主要包括血缘伦理、持家立业、报效国家等”可知清代纂修宗谱重视宗族血缘关系，强调齐家治国平天下的理念，可见深受儒家思想的影响，B项正确。题目中没有涉及科举选官制的作用，排除A项；宗谱中族规是对各阶层的本宗族成员日常生活行为的规定，不只是针对士族家庭，排除C项；四民社会是传统中国社会形态特征，其主体由士、农、工、商四大社会集团构成，题目中未涉及这一内容，排除D项。"},{"id":1343,"type":"单选题","text":"不属于中国四大佛山的是____。","options":[{"key":"A","text":"普陀山"},{"key":"B","text":"武当山"},{"key":"C","text":"九华山"},{"key":"D","text":"峨眉山"}],"answer":["B"],"explanation":"四大佛山分别是山西五台山、浙江普陀山、四川峨眉山、安徽九华山。"},{"id":1344,"type":"单选题","text":"秦始皇统一了全国汉字，这种字叫做____。","options":[{"key":"A","text":"隶书"},{"key":"B","text":"小篆"},{"key":"C","text":"楷书"},{"key":"D","text":"行书"}],"answer":["B"],"explanation":"秦始皇统一天下后,丞相李斯在大篆的基础上创制小篆,作为秦朝文字的统一标准。"},{"id":1345,"type":"单选题","text":"中华民族的摇篮是____。","options":[{"key":"A","text":"黑龙江流域"},{"key":"B","text":"松花江流域"},{"key":"C","text":"黄河流域"},{"key":"D","text":"长江流域"}],"answer":["C"],"explanation":"我国境内早期的先民称华夏族,华夏民族的祖先是炎帝和黄帝,他们都生活在黄河中游一带,因此,黄河流域是中华民族的摇篮。"},{"id":1346,"type":"单选题","text":"我们常说”鸿雁传书“源自于哪个历史故事？","options":[{"key":"A","text":"文姬归汉"},{"key":"B","text":"霸王别姬"},{"key":"C","text":"苏武牧羊"},{"key":"D","text":"楚汉相争"}],"answer":["C"],"explanation":"我们常说的鸿雁传书源自于汉武帝时期苏武的故事。汉武帝时期，有个特别有名的人物叫苏武。"},{"id":1347,"type":"单选题","text":"“一日不见，如隔三秋”里的“三秋”是指____。","options":[{"key":"A","text":"三个月"},{"key":"B","text":"三年"},{"key":"C","text":"三个季度"},{"key":"D","text":"三十年"}],"answer":["C"],"explanation":"“三秋”指的是时间：三个季度/季节（九个月时间）。经常用“一日不见，如隔三秋”来表达对别人的思念。一般被用来比喻虽然时间很短暂，却但却让人感觉很久一样。"},{"id":1348,"type":"单选题","text":"“阳关大道”原是指通往____的道路。","options":[{"key":"A","text":"东海"},{"key":"B","text":"西域"},{"key":"C","text":"南国"},{"key":"D","text":"中原"}],"answer":["B"],"explanation":"阳关大道原指经过阳关通往西域的官道，阳关是汉朝设置的边关名，故址在今甘肃省敦煌县西南，古代跟玉门关同是出塞必经的关口。《元和郡县志》云，因在玉门之南，故称阳关。"},{"id":1349,"type":"单选题","text":"下列哪个称号不是端午节的别称？","options":[{"key":"A","text":"诗人节"},{"key":"B","text":"六月节"},{"key":"C","text":"地腊节"},{"key":"D","text":"女儿节"}],"answer":["B"],"explanation":"六月节不是端午节的别称。在我国传统节日中,端午节有别名近30个,堪称节日别名之最,如端阳节、重午节、五月节、午日节、浴兰节、菖蒲节、女儿节、龙舟节、龙日节、天中节、地腊节、躲午节、当五汛、解粽节、粽子节、屈原日、诗人节等。"},{"id":1350,"type":"单选题","text":"《爱莲说》中，“花之隐逸者，花之富贵者，花之君子者”分别指的是哪个？","options":[{"key":"A","text":"梅 兰 竹"},{"key":"B","text":"菊 牡丹 竹"},{"key":"C","text":"菊 牡丹 莲"},{"key":"D","text":"兰 牡丹 莲"}],"answer":["C"],"explanation":"予谓菊，花之隐逸者也；牡丹，花之富贵者也；莲，花之君子者也。"},{"id":1351,"type":"单选题","text":"下列选项中不属于古文字范畴的是____。","options":[{"key":"A","text":"小篆"},{"key":"B","text":"行书"},{"key":"C","text":"金文"},{"key":"D","text":"甲骨文"}],"answer":["B"],"explanation":"书是一种字体，不属于古文字范畴。"},{"id":1352,"type":"单选题","text":"宗教对文学艺术作品的创作影响深远，下列艺术作品中，受到道教影响的是哪一项？","options":[{"key":"A","text":"吴道子《八十七神仙卷》"},{"key":"B","text":"顾恺之《洛神赋图》"},{"key":"C","text":"黄公望《富春山居图》"},{"key":"D","text":"张萱《捣练图》"}],"answer":["A"],"explanation":"《八十七神仙卷》是一幅白描画像，描绘了87位道教人物从天而降，列队行进的场景。"},{"id":1353,"type":"单选题","text":"下列哪项不是端午节的习俗？","options":[{"key":"A","text":"挂香包"},{"key":"B","text":"插艾蒿"},{"key":"C","text":"登高采菊"},{"key":"D","text":"喝雄黄酒"}],"answer":["C"],"explanation":"登高采菊是重阳节的习俗。"},{"id":1354,"type":"单选题","text":"“福兮祸之所倚，祸兮福之所伏”一语出自哪里？","options":[{"key":"A","text":"孔子"},{"key":"B","text":"老子"},{"key":"C","text":"庄子"},{"key":"D","text":"孟子"}],"answer":["B"],"explanation":"《老子》第五十八章：“祸兮福之所倚；福兮祸之所伏。”"},{"id":1355,"type":"单选题","text":"孟子说：“不以规矩，不成方圆”，这里“规矩”的意思是____。","options":[{"key":"A","text":"法律法度"},{"key":"B","text":"美德善行"},{"key":"C","text":"圆规曲尺"},{"key":"D","text":"道德准则"}],"answer":["C"],"explanation":"“不以规矩,不成方圆。”其中“规矩”的意思是圆规曲尺。"},{"id":1356,"type":"单选题","text":"中国古代以干支纪年。韩国平昌冬奥会举办的2018年是戊戌年，那么北京冬奥会举办的2022年是什么年？","options":[{"key":"A","text":"甲辰年"},{"key":"B","text":"壬寅年"},{"key":"C","text":"辛丑年"},{"key":"D","text":"庚子年"}],"answer":["B"],"explanation":"冬奥会的举办时间是 2022 年，对应的是壬寅年。"},{"id":1357,"type":"单选题","text":"道家思想在我国影响深远，请问历史中的哪一时期最接近道家所主张的无为而治？","options":[{"key":"A","text":"文景之治"},{"key":"B","text":"光武中兴"},{"key":"C","text":"贞观之治"},{"key":"D","text":"开元盛世"}],"answer":["A"],"explanation":"文景之治是指西汉汉文帝、汉景帝统治时期出现的治世。汉初，因多年战乱导致社会经济凋敝，汉廷推崇黄老治术，采取“轻徭薄赋”、“与民休息”的政策。"},{"id":1358,"type":"单选题","text":"下列哪个不是北京的别称？","options":[{"key":"A","text":"大都"},{"key":"B","text":"中都"},{"key":"C","text":"上都"},{"key":"D","text":"北平"}],"answer":["C"],"explanation":"自秦汉以来北京地区一直是中国北方的军事和商业重镇，名称先后称为蓟城、燕都、燕京、涿郡、幽州、南京、中都、大都、京师、顺天府、北平、北京等。上都地区在金代称金莲川或凉陉﹐筑有景明宫。位于今内蒙古自治区锡林郭勒盟正蓝旗境内，多伦县西北闪电河畔。所以说“上都”不是北京古代的称号。"},{"id":1359,"type":"单选题","text":"八斗的爷爷正在翻阅一本有关古代器具的书，八斗凑过去看到了很多有趣的器皿。爷爷将图注遮住，问他：你知道哪个是专门用来盛酒的器皿吗？八斗一时回答不上来，你能帮他找出来吗？","options":[{"key":"A","text":"觚"},{"key":"B","text":"爵"},{"key":"C","text":"鼎"},{"key":"D","text":"卣"}],"answer":["D"],"explanation":"觚、爵是古代的饮酒器，鼎是古代用来煮肉和盛肉的器皿，卣是古代的盛酒器。"},{"id":1360,"type":"单选题","text":"《古诗十九首》是中国古代文人五言诗选辑，有人认为它是“五言之冠冕”，还有人认为其“文温而丽，意悲而远，惊心动魄”，这两句对《古诗十九首》的评价出自以下哪两位名家？","options":[{"key":"A","text":"锺嵘、严羽"},{"key":"B","text":"严羽、袁枚"},{"key":"C","text":"刘勰、锺嵘"},{"key":"D","text":"刘勰、袁枚"}],"answer":["C"],"explanation":"“五言之冠冕”是刘勰在《文心雕龙》中对《古诗十九首》的评价，言其代表五言诗的最高成就;“文温而丽，意悲而远，惊心动魄”是锺嵘在《诗品》中对《古诗十九首》的高度赞美，极言其辞藻华丽、意境深邃、深入人心。"},{"id":1361,"type":"单选题","text":"假如你是古希腊时期的公民，正在街头围观苏格拉底宣扬他的哲学思想，而此刻，你的好友小文正在位于世界东方的中国聆听当地思想家的言论，那么他可能听到以下哪种言论？","options":[{"key":"A","text":"万物皆只是一个天理"},{"key":"B","text":"刑过不避大臣，赏善不遗匹夫"},{"key":"C","text":"己所不欲，勿施于人"},{"key":"D","text":"天行有常，不为尧存，不为桀亡"}],"answer":["C"],"explanation":"“己所不欲，勿施于人”是孔子（公元前551年—公元前479年）的主張，他生活的时期早于苏格拉底（公元前469年—公元前399年）。“万物皆只有一个天理”是宋代二程（程颢、程颐）（约1032—1107年）的思想主张。“刑过不避大臣，赏善不遗匹夫”是韩非子（约公元前280年—公元前233年）的主张。“天行有常，不为尧存，不为桀亡”是荀子（约公元前313年—公元前238年）的观点。"},{"id":1362,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"癸巳、戊戌都指年份。中国自古便有十天干与十二地支，形成天干地支纪年法。"},{"key":"B","text":"微服，是指为隐藏身份、避人耳口而改换成平民的服装，古代专指有身份的官吏私访。"},{"key":"C","text":"请老，指古代官吏请求退休。退休制度是我国古代官僚制度的一个重要组成部分。"},{"key":"D","text":"行辈，即排行和辈分。儒家文化强调论资排辈，汉族重宗族的观念一直延续至今。"}],"answer":["B"],"explanation":"“专指有身份的官吏”错误，还有帝王。"},{"id":1363,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"从春秋战国至宋元明清，多把中原王朝政权统辖范围之内的地区称为“中国”。"},{"key":"B","text":"北宋时，为加强中央集权，将领不能专兵，凡遇战事，在将领中选拔一人给予“都统制”的名义节制兵马。"},{"key":"C","text":"年号是中国古代封建皇帝用以纪年的名号，一个皇帝只有一个年号，所以常常用年号来称呼皇帝。"},{"key":"D","text":"古代的官员因为年龄或别的原因辞官不做了，称“致仕”或“休致”，也指官员退休。"}],"answer":["C"],"explanation":"一个皇帝可以有多个年号。"},{"id":1364,"type":"单选题","text":"下列说法正确的一项是____。","options":[{"key":"A","text":"嗣位、即位：特指皇帝登上皇位，表示此意思的词还有登基、禅位、践阼等等。"},{"key":"B","text":"古代常用纪年法有干支纪年法（十天干与十二地支两字相配，60年周而复始），王公即位年次纪年法，年号纪年法，年号干支兼用法，生肖纪年法等。"},{"key":"C","text":"进士，中国古代科举制度中，通过朝廷最后一级考试者，称为进士。古代科举考试按照等级次序先后分为院试、会试、乡试、殿试。"},{"key":"D","text":"车驾、陛下指皇帝，习惯上，唐朝以前对殁世的皇帝一般简称谥号，如汉武帝、隋炀帝；唐朝以后，由于谥号的文字加长，则改称庙号，如唐太宗、宋太祖等，到了明清两代才用年号来称呼，比如“英宗”。"}],"answer":["B"],"explanation":"A项，嗣位指父亲传位或传业给嫡长子，不是皇帝登临皇位。\nC项，古代科举考试按照等级次序先后分为院试、乡试、会试、殿试。\nD项，“英宗”是庙号，不是年号。"},{"id":1365,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"“中嘉祐二年进士第”中“第”指科举考试及格的等次，“进士”是古代科举制度中通过最后一级考试者，意为可以进授爵位之人。"},{"key":"B","text":"古代任命或调任官职的词语很多，“拜中书舍人”指“授予中书舍人一职”，“徙明、亳、沧三州”指“调任明州、亳州、沧州知州”。"},{"key":"C","text":"“丁母艰”是指母亲去世，回乡守丧。守丧有一定的时间规定，这在古代是一种孝顺行为，表明当事人对已故之人的崇敬和不舍。"},{"key":"D","text":"“六经”指六部儒家经典著作，是指经过孔子整理而传授的六部先秦古籍。它们是《论语》《诗经》《尚书》《礼记》《乐经》《周易》。"}],"answer":["D"],"explanation":"《论语》不是六经。"},{"id":1366,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"明经，汉朝出现之选举官员的科目，始于汉武帝时期，至宋神宗时期废除。被推举者须明习经学，故以“明经”为名。"},{"key":"B","text":"行在，也称行在所。第一释义指天子所在的地方。第二释义专指天子巡行所到之地。此处是第二种释义。"},{"key":"C","text":"社稷是土神和谷神的总称。由于古时的君主为了祈求国事太平，五谷丰登，每年都要到郊外祭祀土地和五谷神。社稷也就成了国家的象征，后来人们就用“社稷”来代表国家。"},{"key":"D","text":"视事，视察、巡视政事。旧时指官吏被皇帝派往某地巡视政事，考核官员。"}],"answer":["D"],"explanation":"视事，旧时指官吏到职办公。"},{"id":1367,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"国子监，我国封建时代最高的教育管理机关，在有的朝代兼为最高学府。"},{"key":"B","text":"教授，学官名。始于宋代，为讲解经义、掌管课试的一种文职官员。"},{"key":"C","text":"礼部，中国古代官署，掌管国家的典章制度、祭祀、贡举、户籍等事项。"},{"key":"D","text":"受禅，是中国古代推举部落首领的一种方式。文中指新皇帝接受旧皇帝让给的帝位。"}],"answer":["C"],"explanation":"户籍应该是由户部掌管。"},{"id":1368,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"贞元，年号。年号是我国从汉朝初年开始使用的封建王朝用来纪年的一种名号，古代帝王凡遇到大事、要事，常常要更改年号。"},{"key":"B","text":"明经，汉朝出现的选举官员的科目，始于汉武帝时期，至宋神宗时期废除。被推举者须明习经学，故以“明经”为名。"},{"key":"C","text":"谥号是朝廷对死去的帝王、大臣、贵族（包括其它地位很高的人）、平民按其生平事迹进行评定后，给予或褒或贬或同情的称号。"},{"key":"D","text":"乞骸骨，乞求自己的尸骨能回到故乡安葬，指古代官吏因年老请求退职，回老家安度晚年。这是古代官员请求退休的萎婉说法。"}],"answer":["C"],"explanation":"朝廷不会给平民封谥号。"},{"id":1369,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"“知峨眉县”意思是担任峨眉知县。宋代多用中央机关的官做县官，称“知县事”，后简称为“知县”。"},{"key":"B","text":"天宝，为唐玄宗李隆基的年号。中国古代的纪年法有许多种，采用皇帝年号来纪年是其中一种。"},{"key":"C","text":"户部是尚书省六部之一，掌管全国土地、户籍、屯田、赋税、财政收支、典章法度等事务。"},{"key":"D","text":"青苗法为宋代王安石变法的措施之一，也称“常平新法”，其最终目的是充实国库，调节贫富差距。"}],"answer":["C"],"explanation":"户部尚书掌管全国土地、赋税、户籍、军需、俸禄、粮饷、财政收支。“典章法度”属礼部掌管。"},{"id":1370,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"六经，是《诗》《书》《礼》《易》《论语》《春秋》的合称。“六艺经传皆通习之”中的“六艺”指的就是“六经”。"},{"key":"B","text":"参知政事，宋代的一个常设官职，相当于副宰相，设置这一官职的根本目的是削弱相权，加强皇权。"},{"key":"C","text":"枢密院，官署名称，长官称枢密使，在宋代，枢密院主要管理军事机密及边防等事，与中书省合称“二府”。"},{"key":"D","text":"致仕，指古代官员交还官职，即退休。《张衡传》中的“乞骸骨”也是这个意思。"}],"answer":["A"],"explanation":"《论语》不是六经。"},{"id":1371,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"唐初设翰林院，作为文人和卜医技术待诏的处所，并非中央机关。后来另建学士院，入院的称为翰林学士，专掌皇帝的机密诏令。"},{"key":"B","text":"南面，古代以坐北朝南为尊位，故帝王召见群臣时，都面向南而坐，因此南面指帝王之位。后泛指居尊位或官位。"},{"key":"C","text":"宰相指辅助皇帝、统领群僚、总揽政务的最高行政长官，其中宰是辅助、相是主宰的意思。"},{"key":"D","text":"礼部，为六部之一，主管典礼、科举、学校等事务，长官为礼部尚书，副长官为侍郎。"}],"answer":["C"],"explanation":"“宰”指主宰、“相”指辅助。"},{"id":1372,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"古代男女成年时要行冠礼，戴上表示已经成人的帽子，而“弱冠”就是还没有成年。"},{"key":"B","text":"“释褐”通常是指脱去平民衣服，开始担任官职；有时也指新考中的进士被授予官职。"},{"key":"C","text":"“人爵”是与天爵相对而言的，它是指尘世人们所封的爵位，例如国君所赐的公、侯等。"},{"key":"D","text":"古人认为我国疆土四面为海所环抱，因而称国境以内为“海内”，国境以外为海外。"}],"answer":["A"],"explanation":"应为“古代男子成年时要行冠礼”，另外“还没有成年”有误，男子20岁称弱冠，此时已经成年。"},{"id":1373,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"国子监，中国封建时代最高的教育管理机构，有的朝代兼为最高学府。"},{"key":"B","text":"朔，农历每月月中。古人用“晦”“朔”“望”既望等名称来标识日期。"},{"key":"C","text":"衣冠，“衣”指衣服“冠”指帽子。“衣冠”指士大夫的穿戴，借指士大夫、官绅。"},{"key":"D","text":"经传，原指经典和注释、阐述经义的著作，后来泛指比较重要的古书。"}],"answer":["B"],"explanation":"朔，农历每月初一。"},{"id":1374,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"韩愈世称韩昌黎，又称韩吏部。谥号“文”，又称韩文公。宋代苏轼称他“文起八代之衰”，明人推他为唐宋八大家之首，与柳宗元并称“韩柳”。"},{"key":"B","text":"“汝”即你，多用于后辈。古汉语中表示“你”的称呼还有“尔、公、君、卿、足下”等。"},{"key":"C","text":"“矣、呜呼”语气助词的运用强化了这一段情感发展变化的节奏，也准确地抒发了作者强烈的不愿相信、不能相信又不得不相信的失去亲人的悲痛感情。"},{"key":"D","text":"殁在殡葬中的区别：古代对身份和地位不同的人去世后，称呼也不同。天子死曰崩，诸侯死曰薨，大夫死曰禄，士死称不卒，庶人死称死。小孩夭折和病死的，称为殁。"}],"answer":["D"],"explanation":"D项表述错误，大夫死曰卒，士死称不禄。"},{"id":1375,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"“漕运”是指利用水道调运粮食（主要是公粮）的一种专业运输。运送粮食的目的是供宫廷消费、百官俸禄、军饷支付和民食调剂。"},{"key":"B","text":"“隆庆”属于年号，“隆庆元年”指该帝王即位第一年。年号是我国从汉武帝开始使用封建王朝用来纪年的一种名号。"},{"key":"C","text":"“致仕”是指古代官员正常退休，古人还常用致事、致政、休致等名称，一般致仕的年龄为七十岁，有疾患则提前。"},{"key":"D","text":"“卒”是古代称大夫的死，古代帝王和王后死叫崩，古代诸侯王死叫薨，古代所有人之死亡均可称“死”。"}],"answer":["D"],"explanation":"死就是指古代平民的死亡，而非泛指所有人的死亡。"},{"id":1376,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"庶吉士，其名称源自《书经·立政》篇中“庶常吉士”之意。是中国明、清两朝时翰林院内的短期职位。由通过科举考试中进士的人当中选择有潜质者担任，为皇帝近臣，负责起草诏书，有为皇帝讲解经籍等责，是为明内阁辅臣的重要来源之一。"},{"key":"B","text":"言官又称谏官，职在讽议左右，以匡人君，监察方式主要是谏诤封驳，审核诏令章奏。统治者既然把特权赋予言官，也就会对言官的政治素质提出特别的要求。正如宋代司马光所言：“凡择言官，当以三事为先：第一不爱富贵，次则重惜名节，次则晓知治体。"},{"key":"C","text":"中国儒家学派创始人孔子晚年整理的《诗》《书》《礼》《易》《乐》《春秋》，后人称之为“六经”。其中《乐经》已失传，所以通常称“五经”。"},{"key":"D","text":"古代官员正常退休叫作“致仕”，古人还常用致事、致政、休致等名称，盖指官员辞职归家。按照封建礼法，官员欲退，则皇帝必称社稷所倚而加以挽留，官员则以不能阻塞后人予以坚持，反复数次之后，皇帝不再勉强，以优厚待遇让官员回乡安度晚年。“乞骸骨”“丁忧”也可理解为告老还乡，退休之意。"}],"answer":["D"],"explanation":"为父母守制27个月，称丁忧。处于丁优期间的一些人由于国家需要，不必弃官去职，不着公服，素服治事，不预庆贺，祭祀、宴会等由佐贰代理，称“夺情”。或有的守制未满，而应朝廷之召出来应职者，称起复。"},{"id":1377,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"丁忧，也称“丁艰”。在我国古代，官员的父亲或母亲去世，官员则必须停职守制，处于丁忧期间的人皆不得为官，概无例外。"},{"key":"B","text":"笏，古代君臣在朝廷上相见时手中所拿的长方形板子，按品第分别用玉、象牙或竹制成，以为指画及记事之用。"},{"key":"C","text":"古代官员正常退休叫作“致仕”，古人还常用致政、休致等名称，都指官员辞职归家。"},{"key":"D","text":"谥号是一般指古代帝王、诸侯、卿大夫、高官大臣等死后，朝廷根据他们的生平行为颁赐的一种称号，带有评定性质。"}],"answer":["A"],"explanation":"处于丁优期间的一些人由于国家需要，不必弃官去职，不着公服，素服治事，不预庆贺，祭祀、宴会等由佐贰代理，称“夺情”。或有的守制未满，而应朝廷之召出来应职者，称起复。"},{"id":1378,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"“牙将”即牙门将，负责在防御工事“牙门”里统领士兵指挥作战的将领被称为牙门将，后来演变成类似于主将帐下的偏将、副将的职位。"},{"key":"B","text":"“迁”，意思是调动官职，一般指提升，但有时候也表示降职远调，如《岳阳楼记》中的“迁客骚人”和《琵琶行》中的“予左迁九江郡司马”。"},{"key":"C","text":"“节度使”，唐代设立的地方军政长官，因受职之时，朝廷赐以旌节而得名，节度使集军、民、財三政于一身，威权甚重，最终酿成安史之乱。"},{"key":"D","text":"“河朔”，地区名，古代泛指黄河以北地区，“朔”在古代又可以表示时间概念，朔日是农历每个月的初一，而晦日是农历每个月的三十。"}],"answer":["D"],"explanation":"晦日是农历每个月的最后一天。"},{"id":1379,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"明清形成了完备的科举考试制度，共分四级：院试、乡试、会试和殿试。考中会试的称为进士。"},{"key":"B","text":"舅，文中是指丈夫的父亲。有如“洞房昨夜停红烛，待晓堂前拜舅姑”。"},{"key":"C","text":"古代人的名字和现代有很大的差别。名是出生后不久父母起的，供长辈呼唤；字是二十岁举行冠礼或行笄礼时才起的，以表示对本人尊重或供朋友称呼。"},{"key":"D","text":"除，是任命，授职，如“除徽州推官”；擢，是在原官职上提拔，如“擢礼科给事中”。"}],"answer":["A"],"explanation":"考中会试的称为贡士。"},{"id":1380,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"户部，中国古代官署名。明清时，户部掌管田地、户籍、赋税、俸饷及一切财政事宜，长官为户部尚书，副职为左、右侍郎。"},{"key":"B","text":"大计，是明清两代考核官员的制度，分为京察、外察，每三年举行一次。通过考核来决定在京和在外官员的任免及职位的升降。"},{"key":"C","text":"嫡母，是封建家庭中子女对亲生母亲的称呼。在古代，嫡妻所生子女称作嫡出，而姬妾所生的子女称作庶出。"},{"key":"D","text":"登极，本指登上屋顶，后指皇帝即位。古代还有很多类似的词语，生动形象地形容皇帝即位，如：践极、南面、荣登大宝等。"}],"answer":["C"],"explanation":"“是封建家庭中子女对亲生母亲的称呼”错，嫡母是“妾生的子女对父亲的正妻的称呼”。"},{"id":1381,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"七庙，天子的宗庙。即帝王设七庙供奉祖先，太祖庙位居正中，其左右各为三昭三穆。后世以“七庙”作为王朝的代称，《过秦论》中的“七庙隳”就是指秦朝灭亡。"},{"key":"B","text":"终丧，守完父母的丧期。这缘于古代的“丁忧”制度。古代官员的父母死去，官员一般须停职守丧三年，因特殊原因国家强招丁忧的人为官，叫做“起复”。"},{"key":"C","text":"乞骸骨是古代官吏因年老请求退职的一种说法，意谓使骸骨得归葬故乡。下文的“听致仕”，表示朝廷同意了，批准他退休。"},{"key":"D","text":"古代帝王、诸侯、卿大夫、高官大臣等死后，朝廷根据他们的生平行为给予一种称号以褒贬善恶，称为谥或谥号。比如“唐高祖”、“隋炀帝”都是谥号。"}],"answer":["D"],"explanation":"中国古代，皇帝的称呼往往和年号、谥号和庙号联系在一起，唐高祖就是庙号。"},{"id":1382,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"“会试”，是中国古代科举制度中的中央考试，是考取贡士的考试，考中的前三名分别叫状元、榜眼、探花。"},{"key":"B","text":"“勤王”,多指君主的统治受到威胁而动摇时,臣子起兵救援王朝。"},{"key":"C","text":"“工部”,三省六部是西汉以来逐步形成的封建王朝最高政府机构。三省:中书省、门下省、尚书省。六部:吏部、户部、礼部、兵部、刑部、工部。"},{"key":"D","text":"“敕”,中国古代帝王诏令文书的名称之一，用于任官封爵和告诫臣僚。"}],"answer":["A"],"explanation":"在会试中考中的贡生，再参加由皇帝主持的殿试，殿试一般分为三甲（宋代为五甲），其中第一甲的前三名分别为状元、榜眼、探花。"},{"id":1383,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"字，古人幼时取字，成年取名。对平辈或尊辈称字是出于礼貌或尊敬，如文中“刘文静字肇仁。”"},{"key":"B","text":"高祖，庙号，庙号是皇帝死后，在太庙立室奉祀时特起的名号。"},{"key":"C","text":"关，古代在险要地方或国界设立的守卫处所。如：关塞，关卡，关隘。"},{"key":"D","text":"践，文中特指皇帝登临帝位，如:践作，践极。"}],"answer":["A"],"explanation":"幼时取名，成年取字。"},{"id":1384,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"《汉书》是我国第一部纪传体断代史，它与《史记》、《后汉书》、《三国志》合称为“前四史”。"},{"key":"B","text":"“吏部”掌管全国文武官员的选用、任免、考核、调动等事务，主管是吏部尚书和吏部侍郎。"},{"key":"C","text":"“春秋”既可指春季秋季，也可指我国特定的历史时代，还可指儒家经典，文中用以指年龄。"},{"key":"D","text":"“少牢”指我国古代祭祀时用羊和猪当祭品，“太牢”则指祭祀帝王时用牛、羊和猪当祭品。"}],"answer":["B"],"explanation":"吏部掌管全国文官，兵部掌管全国武官。"},{"id":1385,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"后唐是五代政权之一，李存勖所建，都洛阳。五代指后梁、后唐、后晋、后汉、后周，文中“汉祖（南下）”指“后汉高祖（南下时）”。"},{"key":"B","text":"称疾，是古文中较为常见的一种托词，当事人本身或许没有生病，却以生病为由，以回避某事某人，文中“称疾不行”暗示传主的微妙心态。"},{"key":"C","text":"祭酒，古代学官名。晋武帝咸宁四年设，以后历代多沿用，为国子学或国子监的主管官。刘温叟当时以工部侍郎的身份兼任国子监主管。"},{"key":"D","text":"丁内艰，是指遭遇父亲去世。丁忧就是遭遇父母亲去世。古代朝廷官员，无论任什么官职，从得知丧事的那一天起，必须回到祖籍守丧一段时间。"}],"answer":["D"],"explanation":"丁内艰，是遭遇母亲去世。"},{"id":1386,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"博士是学官名，秦汉时是指掌管书籍文典、通晓史事的官职，后指学术上专通一经或精通一艺、从事教授生徒的官职。"},{"key":"B","text":"出，常常指官员离开家居地出任某个官职或京官外调为地方官员。本文的“出”指的是后者，相当于京官外放、外迁。"},{"key":"C","text":"祠部是东晋时设的以祠部尚书为主官、掌祭祀之事的官署。朝代不同，其主官有不同的称呼，管辖的部门也有所不同。"},{"key":"D","text":"我国古代常用的纪年法有王公即位年次纪年法、年号纪年法、干支纪年法等，“永明三年”是用王公即位年次来纪年的。"}],"answer":["D"],"explanation":"“永明三年”是年号纪年法。"},{"id":1387,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"“幼孤，随母适胡氏”，古人有“鳏寡孤独”之说，其中“鳏”指无妻或丧偶，“寡”指女子丧夫，“孤”指幼年丧父，“独”指老而无子。"},{"key":"B","text":"“洪熙元年”中，“洪熙”足指明仁宗年号。年号始于汉武帝，此后皇帝即位都要改元，并以年号纪年，如“庆历四年”“元和十年”均是如此。"},{"key":"C","text":"“海盐民”中，“民”足对百姓的称谓，常见的百姓称谓还有布衣、黔首、黎民、生民、庶民、黎庶、苍生、黎元、氓和足下等。"},{"key":"D","text":"由于受时代的限制，^人对四方异族的了解有限，往往用蛮、夷、戎、狄、胡、越等来泛指四方异族，对南方各族常称“百越”或“越族”。"}],"answer":["C"],"explanation":"“足下”不是对百姓的称谓。"},{"id":1388,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"古代中国汉族男性年满二十岁要举行冠礼，表示成年。未冠又称弱冠，即不到二十岁。白居易就是在尚未成年时得到了顾况的高度称赞。"},{"key":"B","text":"擢进士，指被选拔为进士。中国古代科举制度中，通过最后一级中央政府朝廷考试者（古代科举殿试及第者），称为进士。"},{"key":"C","text":"浮屠，亦作浮图、休屠。古人称佛教徒为浮屠，都是佛陀的异译。后人认为佛陀二字太麻烦，于是简化成了一个字“佛”。"},{"key":"D","text":"“赞”是纪传体史书中写在篇末的评论性文字，可用来表达对传主的肯定和赞美。本文篇末的“赞”中称赞白居易为贤者。"}],"answer":["A"],"explanation":"“未冠”不是“弱冠”。"},{"id":1389,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"“赵葵，字南仲”。古人幼时命名，成年(男20岁、女15岁)取字，字和名使用有别，名供长辈呼唤；字是供平辈和晚辈称呼。"},{"key":"B","text":"文中“授两淮宣抚使、判扬州，进封鲁国公”中的“授”指授给、给予官职。“判”指低位兼低职。“封”指帝王把土地、封号或爵位授予亲属或臣僚。"},{"key":"C","text":"文中“寻奉祠”的“奉祠”指只领官俸而无职事。宋代设宫观使、判官、都监、提举、主管等职，以安置五品以上不能任事或年老退休的官员。因宫观使等职原主祭祀,故亦称奉祠。"},{"key":"D","text":"文中“谥忠靖”的“谥”是谥号。古代帝王、贵族、大臣或其他有地位的人死后被追加的称号叫谥号，一般根据他们的生平事迹与品德修养，进行一种褒扬的评价，也有表贬抑的评价。"}],"answer":["B"],"explanation":"“判”指高位兼低职。"},{"id":1390,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"偏将，副将，将军的辅佐，此官制始设于春秋，通常由帝王拜授，也有大将军拜授的。"},{"key":"B","text":"刑部，古代“六部”之一，掌管刑法、狱讼事务的官署职务，其最高掌管为刑部尚书。"},{"key":"C","text":"实封，食邑制度之一。封户有虚实之别，其封国并无疆土，封户亦徒有虚名，唯加实封者，才能收其所得封户的租税。"},{"key":"D","text":"“迁”一般指升官，但也有作一般调动讲的，也有作降职远调的例“左迁”，表升迁的词语还有“擢”、“升”、“出”、“陟”等。"}],"answer":["D"],"explanation":"出：指出京受任。《张衡传》中“永和初，出为河间相”的“出”，就是指张衡离京任河间王的相。"},{"id":1391,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"“教授”是指把知识技能传授给学生，后成为一种学官名，掌管学校课试等事，位居提督学事司之下。现在是高等学校教师学衔或职务名称之一。"},{"key":"B","text":"“母忧乞身”是指遭逢母亲去世，在朝廷任职的官员，请求辞职前去为母守孝。"},{"key":"C","text":"“五更”是指年老还乡但富有学识经验的德高望重之人。古代设五更之位，天子要以父兄之礼来对待。"},{"key":"D","text":"“结发”，汉族婚姻习俗，一种象征夫妻结合酌仪式。当夫妻成婚时，各取头上一根头发，合而作一结。"}],"answer":["D"],"explanation":"此处“结发”意为“束发，扎结头发”。古代汉族男子20岁束发而冠，女子15岁束发而笄，表示成年。男女成年的标志分别为“加冠”“加笄”。"},{"id":1392,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"制书，即制式文书，是朝廷大员颁布重要法令或褒奖惩戒官员时采用的专用文书。"},{"key":"B","text":"弃市，为死刑的一种，自商周即有。《礼记》：“刑人于市，与众弃之。”即在人众聚集的闹市，对犯人执行死刑，用于处决某些罪大恶极者。"},{"key":"C","text":"乾德，是北宋太祖赵匡胤的年号。年号是帝王为纪在位之年而立的名号。古人纪年主要有干支纪年和帝王纪年两种。"},{"key":"D","text":"卒，古代指大夫死亡，后为死亡的通称。《礼记·曲礼下》：“天子死曰崩，诸侯死曰薨，大夫曰卒，士曰不禄，庶人曰死。”"}],"answer":["A"],"explanation":"制就是皇帝说的话。所谓“天子之言曰制，书则载其言”。在周代，帝王的命令叫命。秦始皇灭六国后，改命为制，“制”即成为用以颁布皇帝重要的法制命令的专用文书。"},{"id":1393,"type":"单选题","text":"下列说法不正确的一项是____。","options":[{"key":"A","text":"每月的初一称为“望日”，“夏四月之望”是指初夏的四月一日。"},{"key":"B","text":"野史，是私家编撰的史书，“野史氏”在文中是作者自谓。"},{"key":"C","text":"古代科举殿试及第者称为进士，武侯是丁丑年的进士。"},{"key":"D","text":"“庙社”指宗庙和社稷，古人在春季和秋季祭祀社神。"}],"answer":["A"],"explanation":"在农历的每月十五日称为“望日”，每月的初一称为“朔”。“夏四月之望”是指夏历（农历）的四月十五日。"},{"id":1394,"type":"单选题","text":"1932年，清华大学招生试题中有一道对对子题，上联孙行者，下面下联中最合适的是____。","options":[{"key":"A","text":"胡适之"},{"key":"B","text":"周作人"},{"key":"C","text":"郁达夫"},{"key":"D","text":"唐三藏"}],"answer":["A"],"explanation":"解答此类题目首先要看字数，对联要求字数相等，内容相关；其次要求词性相当、结构相称。猢狲，“孙”对“胡”；“适”在古文中是“到、行”的意思，所以所以“行”对“适”；“之”和“者”是文言文里的常用虚词（之乎者也），所以“之”对“者”。"},{"id":1395,"type":"单选题","text":"后羿斩巴蛇的雕像立在____广场。","options":[{"key":"A","text":"人民广场"},{"key":"B","text":"恒隆广场"},{"key":"C","text":"牡丹广场"},{"key":"D","text":"巴陵广场"}],"answer":["D"],"explanation":"后羿斩巴蛇的雕像立在巴陵广场。"},{"id":1396,"type":"单选题","text":"下列对相关文化常识的解说，不正确的一项是____。","options":[{"key":"A","text":"举孝廉，同“察茂才”“征”“辟”一样，都是自上而下选拔官吏的制度。"},{"key":"B","text":"博士：指专管经学传授的的学官。"},{"key":"C","text":"“劾”意为揭发罪状，劾奏，向皇帝检举官吏的过失或罪行。"},{"key":"D","text":"疏是一种文体，是臣子分条向帝王分条陈述说明的意见书。"}],"answer":["A"],"explanation":"举孝廉，同“察茂才”一样，是自下而上选拔官吏的制度。"},{"id":1397,"type":"单选题","text":"下列对相关文化常识的解说，不正确的一项是____。","options":[{"key":"A","text":"羽林，皇帝卫军的名称，其意为国羽翼，如林之盛。是中国古代封建王朝时专门护卫皇帝、皇家、皇城的特殊军队。"},{"key":"B","text":"“陛下”的“陛”指帝王宫殿的台阶，“陛下”原来指的是站在台阶下的侍者，后来被借用为对帝王的尊称。"},{"key":"C","text":"公，诸侯获封赐的封建等级，爵位的一种，旧说周代有公、候、伯、子、爵等爵位，而后代爵位制度往往因时而异。"},{"key":"D","text":"朔望，即朔日和望日，晦朔，即晦日和朔日。晦，阴历每月的第一日。朔，阴历每月的最后一日。望，阴历每月的十五日。"}],"answer":["D"],"explanation":"“朔”是农历每月的初一，“晦”是农历每月的最后一天。"},{"id":1398,"type":"单选题","text":"下列对相关文化常识的解说，不正确的一项是____。","options":[{"key":"A","text":"武帝是皇帝谥号，“武”是褒扬皇帝生前德行之词，有“威武睿智”之意。"},{"key":"B","text":"吕望即姜子牙，他与文王相遇渭滨，因功封于吕地，后代指辅佐国君的贤才。"},{"key":"C","text":"神兽门，即神武门，又称玄武门。玄武主北方，后宫宫殿将北宫门称为玄武门。"},{"key":"D","text":"践祚, 也称践位，在古代专门用来指帝王即位登基。践，践履。祚，天祚、福祚。"}],"answer":["C"],"explanation":"玄武门是帝王宫殿的北宫门，而非后宫宫殿的北宫门。"},{"id":1399,"type":"单选题","text":"下列对相关文化常识的解说，不正确的一项是____。","options":[{"key":"A","text":"进士，指古代科举殿试及第者，根据成绩分为一甲、二甲、三甲，一甲的第一、二、三名依次叫做状元、榜眼、探花。"},{"key":"B","text":"社稷，我国古代称谷神为社，土神称为稷，粮食和土地是以农为本的中华民族的根本所在，故而人们也用社稷代指国家。"},{"key":"C","text":"礼部，古代官署，掌管祭祀、典礼、外宾接待等事务，科举取士、学校事务也归礼部管辖。礼部的最高长官是礼部尚书。"},{"key":"D","text":"服除，意思是脱掉丧服，即守丧期满。根据传统孝道观念，官员遭逢父母去世，一般都要辞官回到祖籍，为父母守制。"}],"answer":["B"],"explanation":"古代称土神为社，谷神为稷。"},{"id":1400,"type":"单选题","text":"下列对相关文化常识的解说，不正确的一项是____。","options":[{"key":"A","text":"“男” 是中国封建社会爵位名，其位次为第五等，位列于公侯伯子之后。"},{"key":"B","text":"“公主”是中国古代对望族女子的称谓。唐朝开始公主只是帝女或者和亲公主的称谓。"},{"key":"C","text":"“疏”是一种文体，“上疏”中的“疏”是指在朝官员专门上奏皇帝的一种文书形式。"},{"key":"D","text":"“先帝”指远古帝王，也指前代已故的帝王或本朝皇帝的亡父，本文即为此意。"}],"answer":["B"],"explanation":"“公主”是中国古代对皇女。王女，宗女的称谓。"},{"id":1401,"type":"单选题","text":"下列对相关文化常识的解说，不正确的一项是____。","options":[{"key":"A","text":"总角，古时未成年的人把头发梳成两个发髻，如头顶两角，后来代称儿童时代。"},{"key":"B","text":"龙门，古代身份高的人的府邸，“一世龙门”是指文人所崇仰的人物，后起的文人登门拜访，可称为“登龙门”。"},{"key":"C","text":"长揖，是古代的相见礼节。行礼时，施礼者屈膝跪地，左手按右手，拱手于地，头也缓缓至于地，向对方表示敬意。"},{"key":"D","text":"三公，中国古代朝廷中最尊显的三个官职的合称，在不同朝代对三公的具体所指不尽相同。"}],"answer":["C"],"explanation":"长揖，是古代不分尊卑的相见礼。稽首行礼时，施礼者屈膝跪地，左手按右手，拱手于地，头也缓缓至于地，向对方表示敬意。"},{"id":1402,"type":"单选题","text":"下列对相关文化常识的解说，不正确的一项是____。","options":[{"key":"A","text":"《周易》即《易经》，相传系周文王姬昌所作，与《诗经》《尚书》《礼记》《春秋》合称“五经”。"},{"key":"B","text":"伊、吕指伊尹和吕尚，殷商时期伊尹、吕尚两位贤臣辅佐朝政，皆有大功，后来以伊吕来泛指辅弼重臣。"},{"key":"C","text":"征是我由皇帝征聘社会知名人士充任官职。辟，指由中央官署征聘，然后向上举荐，任以官职。"},{"key":"D","text":"太建为年号，年号是中国封建王朝用来纪年的一种名号，自汉武帝始，此后每个皇帝即位都要改元。"}],"answer":["B"],"explanation":"伊尹是商朝重臣，辅佐商汤；吕尚是西周重臣，辅佐周武王。李白《行路难（其一）》中“闲来垂钓，碧溪上忽复乘舟梦日边” 即用此典故。"},{"id":1403,"type":"单选题","text":"下列对相关文化常识的解说，不正确的一项是____。","options":[{"key":"A","text":"三公，是中国古代朝廷中最尊显的三个官职的合称。自周代以来，三公专指太师、太傅、太保，唐宋后成为一种虚职。"},{"key":"B","text":"敕，封建社会常作自上命下之词，特指皇帝的诏书，如奉敕、宣敕。本文“敕镇代”指皇帝下令让于烈镇守代邑。"},{"key":"C","text":"称制，指封建社会里君主即位执政，也可指由皇后、皇太后或太皇太后等女性统治者代理皇帝执掌国政。"},{"key":"D","text":"稽首，古代一种跪拜礼，叩头至地，是九拜中最恭敬者。本文中“稽首”即为臣子跪拜国君的礼节。"}],"answer":["A"],"explanation":"“专指”错误。"},{"id":1404,"type":"单选题","text":"下列对相关文化常识的解说，不正确的一项是____。","options":[{"key":"A","text":"太学，古代设于京城的最高学府。博士，古代设置的国家最高学位。"},{"key":"B","text":"知贡举，主试者称为“知贡举”，就是“特命主掌贡举考试”的意思。"},{"key":"C","text":"经筵,是指汉唐以来帝王为讲经论史而特没的御前讲席。"},{"key":"D","text":"循吏，正史中记述的那些重农宣教、奉公守法、爱民富民的地方官。"}],"answer":["A"],"explanation":"“博士，古代设置的国家最高学位”错，博士，在文中是官名。"},{"id":1405,"type":"单选题","text":"下列对相关文化常识的解说，不正确的一项是____。","options":[{"key":"A","text":"至元，是元世祖忽必烈的年号，从1264年到1294年忽必烈驾崩，一共使用了31年，因此忽必烈又被称为“至元大帝”。"},{"key":"B","text":"丞相，是封建官僚机构中的最高官职，是辅佐皇帝总理百政的官员，自有此职以来就只能由一人担任，处于一人之下，万人之上的位置。"},{"key":"C","text":"御史，本为史官，秦以后置御史大夫，职位仅次于丞相，主管弹劾、纠察官员过失诸事。"},{"key":"D","text":"闾巷，古时二十五家为一闾，后来称居民的区域为闾里、闾巷，泛指乡里民间。"}],"answer":["B"],"explanation":"“自有此职以来就只能由一人担任 ”错，有些朝代可由多人担任。"},{"id":1406,"type":"单选题","text":"下列对相关文化常识的解说，不正确的一项是____。","options":[{"key":"A","text":"御史，自秦朝开始，御史专门为监察性质的官职，一直延续到清朝。汉朝御史统归御史台领导，按职掌分为侍御史和治书侍御史。"},{"key":"B","text":"国本，古代特指确定皇位继承人，建立太子为国本。“国本”也指国家藏本。例如韩愈《画记》中“余少时，常有志乎兹事，得国本，绝人事而摸得之”。"},{"key":"C","text":"闾阎，间泛指门户；人家。阎指里巷的门。闾阎，原指古代里巷内外的门，后泛指平民百姓，不再指房屋建筑。"},{"key":"D","text":"公卿，“三公九卿”的简称，夏朝始设，周代沿袭。“公”即是周代封爵之首，“卿”是古时高级长官或爵位的称谓。“三公”即是最尊贵的三个官职的合称。周之“三公”指太师、太傅、太保，也有说为司马、司空、司徒。"}],"answer":["C"],"explanation":"“不再指房屋建筑”错误，“闾阎”也指房屋建筑。"},{"id":1407,"type":"单选题","text":"下列对相关文化常识的解说，不正确的一项是____。","options":[{"key":"A","text":"讼牒，诉状的旧称，即封建社会打官司的文书。讼，在法庭上争辩是非曲直；牒，文书，常指古代官府的往来文书。"},{"key":"B","text":"御史，古代行政官职。自秦朝开始，御史专门作为监察性质的官职，负责监察朝廷、诸侯官吏，一直延续到清朝。"},{"key":"C","text":"“卒”，古代称大夫的死，古代称帝王和王后的死为“崩”，称诸侯王的死为“薨”。古代所有人之死亡均可称作“死”。"},{"key":"D","text":"“壬戌”是干支之一，夏历中用干支来编排年号和时日，选文中指的是壬戌年。壬戌年的前一年是辛酉年，后一年是癸亥年。"}],"answer":["C"],"explanation":"古代所有人之死亡均可称作“死”错。"},{"id":1408,"type":"单选题","text":"下列对相关文化常识的解说，不正确的一项是____。","options":[{"key":"A","text":"孝宗，南宋皇帝赵眘的庙号。庙号指皇帝死后，在太庙立室奉祀时特起的名号。如：太祖、高祖、世祖、圣祖、太宗、高宗、显宗、肃宗等。"},{"key":"B","text":"宫、商、角、徵、羽是中国五声音阶中五个不同音的名称，古人认为这五声分别代表君、臣、民、事、物，五声不乱，国家的政治就会清明。"},{"key":"C","text":"定省，即昏定晨省，本指晚间为父母安定床衽，早晨起来省问父母安否，即称子女早晚向亲长问安；后来泛指探望问候父母或亲长。"},{"key":"D","text":"陛辞，临行前向皇帝告别。陛，特指皇帝宫殿的台阶；“陛下”与“殿下”都指宫殿的台阶下，后来用于对帝王的尊称。"}],"answer":["D"],"explanation":"“陛下”用于对帝王的尊称，而“殿下”用于对皇族成员的尊称，次于代表君主的陛下。汉朝开始称呼太子、诸侯王为殿下，三国开始皇太后、皇后也称殿下。"},{"id":1409,"type":"单选题","text":"下列对相关文化常识的解说，不正确的一项是____。","options":[{"key":"A","text":"在古代官职变化方面，代表升官的词语有拜、晋、迁、拔、擢、徙、升、提等。"},{"key":"B","text":"“赠”，一是指把东西给别人，二是皇帝为已死的官员及其亲属加封，亦叫追赠。"},{"key":"C","text":"舍人在古代的意思有：豪门贵族家里的门客，官职名称，宋元后用以称呼权贵子弟。"},{"key":"D","text":"谥号是古人死后被授予的称号，帝王的谥号一般由礼官议上，大臣的谥号由朝廷赐予。"}],"answer":["A"],"explanation":"迁、徙，都不一定是升官。"},{"id":1410,"type":"单选题","text":"中国传统文化是以什么文化为主体的文化？","options":[{"key":"A","text":"儒家文化、道家文化、法家文化"},{"key":"B","text":"儒家文化、道家文化、墨家文化"},{"key":"C","text":"儒家文化、道家文化、佛家文化"},{"key":"D","text":"儒家文化、道家文化、农家文化"}],"answer":["C"],"explanation":"中国传统文化是以儒家文化、道家文化、佛家文化为主体的文化‌。儒家文化强调仁、义、礼、智、信，道家文化注重领悟道、修养德、求自然，佛家文化则强调奉献和心灵安定。‌"},{"id":1411,"type":"单选题","text":"以下哪个不是修建长城的材料？","options":[{"key":"A","text":"石头"},{"key":"B","text":"芦苇"},{"key":"C","text":"土"},{"key":"D","text":"水泥"}],"answer":["D"],"explanation":"古代是没有水泥的，石头、芦苇、柳条、土都是修建长城的重要原料。一般用糯米、红糖、加一些竹条搅拌，有点像混凝土。"},{"id":1412,"type":"单选题","text":"“一门三文子，都是大文豪。诗赋传千古，峨眉共比高”是指____。","options":[{"key":"A","text":"曹操、曹植、曹丕"},{"key":"B","text":"苏洵、苏轼、苏澈"},{"key":"C","text":"班彪、班固。班超"},{"key":"D","text":"杜甫、杜牧、杜苟鹤"}],"answer":["B"],"explanation":"该说法说的是苏洵苏辙苏轼三人。"},{"id":1413,"type":"单选题","text":"中国古代的教育，可分为____和____两大类。","options":[{"key":"A","text":"官学 私学"},{"key":"B","text":"正学  私学"},{"key":"C","text":"国学 民学"},{"key":"D","text":"国学 家学"}],"answer":["A"],"explanation":"中国古代的教育，可分为官学和私学两大类。"},{"id":1414,"type":"单选题","text":"我国最古老的词典是____。","options":[{"key":"A","text":"诗经"},{"key":"B","text":"尔雅"},{"key":"C","text":"说文解字"},{"key":"D","text":"七录"}],"answer":["B"],"explanation":"我国最早的词典是《尔雅》。"},{"id":1415,"type":"单选题","text":"截止民国，我国规模最大，数字最多的一部字典是____。","options":[{"key":"A","text":"《康熙字典》"},{"key":"B","text":"《辞源》"},{"key":"C","text":"《辞海》"},{"key":"D","text":"《中华大字典》"}],"answer":["D"],"explanation":"现在收录汉字最多的是《中华大字典》。"},{"id":1416,"type":"单选题","text":"《尚书》中的“尚”是什么意思？","options":[{"key":"A","text":"上古"},{"key":"B","text":"崇尚"},{"key":"C","text":"官名"},{"key":"D","text":"姓氏"}],"answer":["A"],"explanation":"“尚”即“上”，《尚书》就是上古时代的书，它是中国最早的一部历史文献汇编。"},{"id":1417,"type":"单选题","text":"在我国历史上”学士”是指什么？","options":[{"key":"A","text":"学位"},{"key":"B","text":"官名"},{"key":"C","text":"文人"},{"key":"D","text":"以上都是"}],"answer":["B"],"explanation":"南北朝以后，以学士为司文学撰述之官。"},{"id":1418,"type":"单选题","text":"《窦娥冤》的作者是____。","options":[{"key":"A","text":"关汉卿"},{"key":"B","text":"白朴"},{"key":"C","text":"马致远"},{"key":"D","text":"郑光祖"}],"answer":["A"],"explanation":"《感天动地窦娥冤》（简称《窦娥冤》）是元代戏曲家关汉卿创作的杂剧，刊行于明万历十年（公元1582年）。"},{"id":1419,"type":"单选题","text":"“大珠小珠落玉盘”所形容的是什么乐器的弹奏声？","options":[{"key":"A","text":"古筝"},{"key":"B","text":"琵琶"},{"key":"C","text":"古琴"},{"key":"D","text":"箫笛"}],"answer":["B"],"explanation":"“大珠小珠落玉盘”本意是指大小雨点落在荷叶上的声音。在白居易的《琵琶行》中是指琵琶弹奏出的动人声乐。"},{"id":1420,"type":"单选题","text":"我国历史上的六朝古都指的是____。","options":[{"key":"A","text":"北京"},{"key":"B","text":"西安"},{"key":"C","text":"洛阳"},{"key":"D","text":"南京"}],"answer":["D"],"explanation":"六朝古都就是南京。"},{"id":1421,"type":"单选题","text":"著有医学巨著《千金方》，第一个倡导建立妇科。儿科，宋徽宗敕封为“妙应真人”，后世尊称为“药王”等，这是对我国隋唐野菜哪们医药学家的描述？","options":[{"key":"A","text":"孙思邈"},{"key":"B","text":"华佗"},{"key":"C","text":"李时珍"},{"key":"D","text":"扁鹊"}],"answer":["A"],"explanation":"《千金要方》又称《备急千金要方》、《千金方》，是中国古代中医学经典著作之一，作者孙思邈，共30卷，是综合性临床医著，被誉为中国最早的临床百科全书。"},{"id":1422,"type":"单选题","text":"成语“鹤立鸡群”的由来，与下面哪一位有关？","options":[{"key":"A","text":"嵇康"},{"key":"B","text":"嵇绍"},{"key":"C","text":"嵇璜"},{"key":"D","text":"阮籍"}],"answer":["B"],"explanation":"出自“嵇绍入洛，或谓王戎曰：‘昨于稠人中始见嵇绍，昂昂然若野鹤之在鸡群。’”（东晋·戴逵《竹林七贤论》）。"},{"id":1423,"type":"单选题","text":"一种特殊的工艺美术制品，采用蓝色的原料，用紫铜打成胎型，填上釉料，入炉反复烧结再磨光而成。这指的是____。","options":[{"key":"A","text":"景泰蓝"},{"key":"B","text":"彩陶"},{"key":"C","text":"琉璃"},{"key":"D","text":"铜鼎"}],"answer":["A"],"explanation":"景泰蓝，又名“铜胎掐丝珐琅”，是一种瓷铜结合的独特工艺品。景泰蓝以紫铜作坯，制成各种造型，再用金线或铜丝掐成各种花，中充珐琅釉，经烧制、磨光、镀金等工序制成。这种铜的珐琅器创始于明代景泰年间，因初创时只有蓝色，故名景泰蓝。"},{"id":1424,"type":"单选题","text":"“话说天下大势，分久必合，合久必分”，这一名言是我国哪一部著名古典小说的开头?","options":[{"key":"A","text":"《水浒传》"},{"key":"B","text":"《封神演义》"},{"key":"C","text":"《三国演义》"},{"key":"D","text":"《七侠五义》"}],"answer":["C"],"explanation":"“天下大势,分久必合,合久必分”是《三国演义》的开头语。"},{"id":1425,"type":"单选题","text":"世界上最早的纸币是我国宋代出现的____。","options":[{"key":"A","text":"银票"},{"key":"B","text":"当票"},{"key":"C","text":"交子"},{"key":"D","text":"粮票"}],"answer":["C"],"explanation":"交子是中国最早的纸币，也是世界上最早使用的纸币。宋、金纸币名称之一。"},{"id":1426,"type":"单选题","text":"海南岛在历史上相当长时间是罪犯的重要流放地，以下哪位历史人物曾被流放到海南岛？","options":[{"key":"A","text":"苏轼"},{"key":"B","text":"王安石"},{"key":"C","text":"韩愈"},{"key":"D","text":"柳宗元"}],"answer":["A"],"explanation":"苏轼晚年因新党执政被贬惠州、儋州（海南）。"},{"id":1427,"type":"单选题","text":"中国的面食文化源远流长，各地都有自己的特色面食，以下面食与相应的地区对应不正确的是____。","options":[{"key":"A","text":"刀削面——山西"},{"key":"B","text":"烩面——河南"},{"key":"C","text":"牛肉拉面——新疆"},{"key":"D","text":"担担面——四川"}],"answer":["C"],"explanation":"牛肉拉面（牛肉面）是甘肃的传统美食。"},{"id":1428,"type":"单选题","text":"“民贵君轻”之说是由____提出的。","options":[{"key":"A","text":"韩非子"},{"key":"B","text":"庄子"},{"key":"C","text":"孔子"},{"key":"D","text":"孟子"}],"answer":["D"],"explanation":"孟子提出的社会政治思想。意为从天下国家的立场来看，民是基础，是根本，民比君更加重要。“民贵君轻”是孟子仁政学说的核心，具有民本主义色彩，对中国后世的思想家有极大的影响。"},{"id":1429,"type":"单选题","text":"下列哪一句不是《大学》中的句子？","options":[{"key":"A","text":"物有本末事有始终，知所失后，则近道矣。"},{"key":"B","text":"自天子以至于庶人，一是皆以修身为本。"},{"key":"C","text":"是故君子不用其极。"},{"key":"D","text":"父母在，不远游，游必有方。"}],"answer":["D"],"explanation":"出自《论语·里仁》。子曰：“父母在，不远游，游必有方。”表明孔子既强调子女应奉养并孝敬父母(远游就做不到了)，但又不反对一个人在有了正当明确的目标时外出去奋斗。"},{"id":1430,"type":"单选题","text":"“庭下如积水空明，水中藻荇交横，盖竹柏影也。”这句话写的是承天寺夜晚之景，作者是谁？","options":[{"key":"A","text":"纪昀"},{"key":"B","text":"袁枚"},{"key":"C","text":"杜牧"},{"key":"D","text":"苏轼"}],"answer":["D"],"explanation":"出自苏轼 《记承天寺夜游》。"},{"id":1431,"type":"单选题","text":"“衔远山，吞长江，浩浩汤汤，横无际涯；朝晖夕阴，气象万千”写的是哪里的景色？","options":[{"key":"A","text":"太湖"},{"key":"B","text":"西湖"},{"key":"C","text":"洞庭湖"},{"key":"D","text":"三峡"}],"answer":["C"],"explanation":"出自范仲淹的岳阳楼记，描述的是洞庭湖。"},{"id":1432,"type":"单选题","text":"“民以食为天”，“仓廪实则知礼节”，这是____对治国治礼的认识。","options":[{"key":"A","text":"孔子"},{"key":"B","text":"庄子"},{"key":"C","text":"管仲"},{"key":"D","text":"孟子"}],"answer":["C"],"explanation":"仓廪实则知礼节，衣食足则知荣辱（出自《管子—牧民》）。"},{"id":1433,"type":"单选题","text":"“下邳拾履”的故事与下列哪个历史人物有关？","options":[{"key":"A","text":"刘邦"},{"key":"B","text":"项羽"},{"key":"C","text":"张良"},{"key":"D","text":"韩信"}],"answer":["C"],"explanation":"《张良下邳拾履》出自《史记留侯世家》。"},{"id":1434,"type":"单选题","text":"中国古代社会历代王朝的统治者都十分重视官吏选拔制度，从隋唐到明清主要实行____制度。","options":[{"key":"A","text":"察举"},{"key":"B","text":"禅让"},{"key":"C","text":"科举"},{"key":"D","text":"九品中正制"}],"answer":["C"],"explanation":"中国古代社会历代王朝的统治者都十分重视官吏选拔制度，从隋唐到明清主要实行科举制度。"},{"id":1435,"type":"单选题","text":"“青梅竹马”取自下列哪个典故？","options":[{"key":"A","text":"李白《长干行》"},{"key":"B","text":"白居易《长恨歌》"},{"key":"C","text":"李煜《虞美人》"},{"key":"D","text":"李商隐《无题》"}],"answer":["A"],"explanation":"“青梅竹马”原典出自唐·李白《长干行》诗：“郎骑竹马来，绕床弄青梅。同居长干里，两小无嫌猜。”"},{"id":1436,"type":"单选题","text":"下列属于西汉名将的是？","options":[{"key":"A","text":"卫青"},{"key":"B","text":"岳飞"},{"key":"C","text":"戚继光"},{"key":"D","text":"林则徐"}],"answer":["A"],"explanation":"岳飞是南宋抗击金军的将领，戚继光是明朝抗击倭寇的将领。林则徐是清朝政治家、思想家和诗人。"},{"id":1437,"type":"单选题","text":"北方人年夜饭要一般都要吃饺子，其象征意义是____。","options":[{"key":"A","text":"团圆美好"},{"key":"B","text":"年年有余"},{"key":"C","text":"更岁交子"},{"key":"D","text":"五福临门"}],"answer":["C"],"explanation":"饺子是一种历史悠久的中国民间吃食，吃饺子也是国人在春节时特有的民俗传统。因为取“更岁交子”之意，所以深受老百姓的欢迎。"},{"id":1438,"type":"单选题","text":"《五柳先生传》是一篇自传性散文，读此文我们知道五柳先生的三大志趣，下面哪个不是？","options":[{"key":"A","text":"种菊花"},{"key":"B","text":"好读书"},{"key":"C","text":"嗜饮酒"},{"key":"D","text":"著文章"}],"answer":["A"],"explanation":"《五柳先生传》是晋宋之际文学家陶渊明创作的自传文（存争议）。在文中作者表明其三大志趣，一是读书，二是饮酒，三是写文章，塑造了一个真实的自我，表现了卓然不群的高尚品格，透露出强烈的人格个性之美。"},{"id":1439,"type":"单选题","text":"重阳节人们有登高、赏菊、插茱萸和喝____的风俗。","options":[{"key":"A","text":"菊花酒"},{"key":"B","text":"雄黄酒"},{"key":"C","text":"葡萄酒"},{"key":"D","text":"黄酒"}],"answer":["A"],"explanation":"重阳节又称“登高节”。还有重九节、茱萸、菊花节等说法。"},{"id":1440,"type":"单选题","text":"中国民间“送灶神”时要吃粘牙的甜食,这是为了____。","options":[{"key":"A","text":"用糖粘住灶神的牙"},{"key":"B","text":"苦尽甘来之意"},{"key":"C","text":"节日吃美食"},{"key":"D","text":"寄托对逝去亲人的思念"}],"answer":["A"],"explanation":"送灶神时要吃粘牙的甜食是为了用糖粘住灶神的牙。"},{"id":1441,"type":"单选题","text":"“业精于勤，荒于嬉”是我国哪位古人提出来的思想？","options":[{"key":"A","text":"孔子"},{"key":"B","text":"韩愈"},{"key":"C","text":"老子"},{"key":"D","text":"欧阳修"}],"answer":["B"],"explanation":"这句话出自韩愈·《进学解》，意思是说，学业由于勤奋而精通，但它却能荒废在游戏玩耍中。"},{"id":1442,"type":"单选题","text":"辛弃疾词“天下英雄谁敌手？曹刘”中的“曹刘”指的是谁？","options":[{"key":"A","text":"曹操 刘表"},{"key":"B","text":"曹丕 刘备"},{"key":"C","text":"曹植 刘表"},{"key":"D","text":"曹操 刘备"}],"answer":["D"],"explanation":"曹刘指的是曹操和刘备。"},{"id":1443,"type":"单选题","text":"早在2300多年前，我国就有思想家提出了“卫生”这个词，这位思想家是谁？","options":[{"key":"A","text":"庄子"},{"key":"B","text":"孟子"},{"key":"C","text":"老子"},{"key":"D","text":"荀子"}],"answer":["A"],"explanation":"“卫生”一词典出《庄子·庚桑楚》。"},{"id":1444,"type":"单选题","text":"中国民族乐器种类繁多，其中古筝具有自己的分类，现在国内最普及的古筝是多少根琴弦?","options":[{"key":"A","text":"21"},{"key":"B","text":"23"},{"key":"C","text":"24"},{"key":"D","text":"25"}],"answer":["A"],"explanation":"古筝的统一规格为:1.63米，21弦。"},{"id":1445,"type":"单选题","text":"下列哪项不属于中国古代与凤凰有关的传说？","options":[{"key":"A","text":"凤求凰"},{"key":"B","text":"百鸟朝凤"},{"key":"C","text":"凤凰涅槃"},{"key":"D","text":"以箫引凤"}],"answer":["C"],"explanation":"凤凰涅槃的神话故事出自天方国。"},{"id":1446,"type":"单选题","text":"我国是茶叶的故乡，绿茶是最古老的品种，是我国品种最多，产量最大的第一大茶种，下列哪一项不是我国著名的绿茶？","options":[{"key":"A","text":"西湖龙井"},{"key":"B","text":"太湖碧螺春"},{"key":"C","text":"庐山云雾"},{"key":"D","text":"铁观音"}],"answer":["D"],"explanation":"绿茶中最有名的茶有：西湖龙井、洞庭碧螺春、信阳毛尖、黄山毛峰、太平猴魁、六安瓜片、竹叶青、安吉白茶、南京雨花茶等。庐山云雾一般指庐山云雾茶。庐山云雾茶是汉族传统名茶，是中国名茶系列之一，属于绿茶中的一种。铁观音茶，中国传统名茶，属于青茶类，是中国十大名茶之一。"},{"id":1447,"type":"单选题","text":"蹴鞠盛行于哪个朝代？","options":[{"key":"A","text":"隋朝"},{"key":"B","text":"唐朝"},{"key":"C","text":"五代十国"},{"key":"D","text":"清朝"}],"answer":["B"],"explanation":"蹴鞠流传了两千三百多年，它起源于春秋战国时期的齐国故都临淄，唐宋时期最为繁荣，经常出现“球终日不坠”，“球不离足，足不离球，华庭观赏，万人瞻仰”的情景。"},{"id":1448,"type":"单选题","text":"诗句“疏影横斜水清浅，暗香浮动月黄昏”中“暗香”指的是____。","options":[{"key":"A","text":"菊花之香"},{"key":"B","text":"荷花之香"},{"key":"C","text":"梅花之香"},{"key":"D","text":"丁香花之香"}],"answer":["C"],"explanation":"林逋种梅养鹤成癖，终身不娶，世称“梅妻鹤子”，所以他眼中的梅含波带情，笔下的梅更是引人入胜。 首联以梅不畏严寒、笑立风中起句，“众”与“独”字对出，言天地间只有此花，这是何等的峻洁清高。"},{"id":1449,"type":"单选题","text":"“天知、神知、我知、子知”，最早是汉代人杨震说的，他说这句话的目的是为了____。","options":[{"key":"A","text":"拒绝收礼"},{"key":"B","text":"劝人投案"},{"key":"C","text":"替人投案"},{"key":"D","text":"向人发誓"}],"answer":["A"],"explanation":"当时任昌邑任昌邑县令的是王密，杨震做荆州刺史期间，曾举荐过王密，王密为了报恩，就趁他路过昌邑的机会，送给他我黄金十斤。杨震对王密说：“我知道你的为人，你却不知道我的为人，你这是干什么呢？”王密说：“现在是晚上，不会有人知道，你就收下吧。”杨震说：“天知，神知、我知、子知，何谓无知？”执意不收，令王密无地自容。他说这句话的目的是为了拒绝收礼。"},{"id":1450,"type":"单选题","text":"厦门大学校训“自强不息，止于至善”中的“止于至善”出自____。","options":[{"key":"A","text":"《论语》"},{"key":"B","text":"《诗经》"},{"key":"C","text":"《礼记》"},{"key":"D","text":"《太平经》"}],"answer":["C"],"explanation":"“自强不息,止于至善”最早出自儒家经典《礼记·大学》,后来成为许多高校的校训。"},{"id":1451,"type":"单选题","text":"“交头接耳”这个成语出自下列哪部作品？","options":[{"key":"A","text":"《单刀会》"},{"key":"B","text":"《三国演义》"},{"key":"C","text":"《红楼梦》"},{"key":"D","text":"《西游记》"}],"answer":["A"],"explanation":"元·关汉卿《单刀会》第三折：“不许交头接耳，不许笑语喧哗。”"},{"id":1452,"type":"单选题","text":"下列哪项不是上古神话中的四大凶兽？","options":[{"key":"A","text":"梼杌"},{"key":"B","text":"混沌"},{"key":"C","text":"穷奇"},{"key":"D","text":"狌狌"}],"answer":["D"],"explanation":"狌狌不属于上古四大凶兽。"},{"id":1453,"type":"单选题","text":"“在天愿做比翼鸟,在地愿为连理枝”描述的是哪两个人的爱情故事？","options":[{"key":"A","text":"嫦娥 后羿"},{"key":"B","text":"唐明皇 杨贵妃"},{"key":"C","text":"梁山伯 祝英台"},{"key":"D","text":"范蠡 西施"}],"answer":["B"],"explanation":"“在天愿做比翼鸟,在地愿为连理枝”描述的是唐明皇和杨贵妃的爱情故事。"},{"id":1454,"type":"单选题","text":"“群山万壑赴荆门,生长明妃尚有村”，“明妃”是指____。","options":[{"key":"A","text":"西施"},{"key":"B","text":"王昭君"},{"key":"C","text":"貂蝉"},{"key":"D","text":"杨贵妃"}],"answer":["B"],"explanation":"这是杜甫经过昭君村时所作的咏史诗。想到昭君生于名邦，殁于塞外，去国之怨，难以言表。"},{"id":1455,"type":"单选题","text":"刘桢《赠从弟》中“冰霜正惨凄，终岁常端正”描写的是____。","options":[{"key":"A","text":"梅"},{"key":"B","text":"竹"},{"key":"C","text":"松"},{"key":"D","text":"菊"}],"answer":["C"],"explanation":"《赠从弟三首》是汉末三国时期诗人刘桢的组诗作品。这三首诗运用比兴之法，分咏蘋藻、松柏、凤凰三物，诗人以蘋藻、松柏、凤凰高洁、坚贞的品性、远大的怀抱，勉励其堂弟坚贞自守，不因外力压迫而改变本性，亦以自勉。全诗长于比兴，文字平实，言简意明，风格古朴。“冰霜正惨凄，终岁常端正”描写的是松。"},{"id":1456,"type":"单选题","text":"“分道扬镳”中的“镳”指的是什么？","options":[{"key":"A","text":"马鞭"},{"key":"B","text":"马鞍"},{"key":"C","text":"标枪"},{"key":"D","text":"马嚼子"}],"answer":["D"],"explanation":"分道扬镳是一则来源于历史故事的成语，最早出自《魏书·河间公齐传》。“镳”指的是马嚼子。"},{"id":1457,"type":"单选题","text":"“回光返照”这个成语出自哪部作品？","options":[{"key":"A","text":"《红楼梦》"},{"key":"B","text":"《陈涉世家》"},{"key":"C","text":"《烈女传》"},{"key":"D","text":"《三国志》"}],"answer":["A"],"explanation":"高鹗、程伟元版《红楼梦》:贾宝玉失了命根子“通灵宝玉”后失魂落魄、疯疯癫癫。贾母和王夫人决定让他娶薛宝钗来冲喜。这对林黛玉是当头一棒，气得直吐鲜血，从此一蹶不振，面无血色。在宝玉结婚的当晚，林黛玉也一病不起，回光返照时间不长，郁闷而死。"},{"id":1458,"type":"单选题","text":"下列哪项不是凤凰在中国文化中的含义？","options":[{"key":"A","text":"幸福姻缘"},{"key":"B","text":"坚强勇敢"},{"key":"C","text":"祥瑞和平"},{"key":"D","text":"贤才人才"}],"answer":["B"],"explanation":"中国文化中凤凰没有坚强不屈的含义。"},{"id":1459,"type":"单选题","text":"善于画松树，并能双管齐下，两手同时作画的画家是谁？","options":[{"key":"A","text":"吴道子"},{"key":"B","text":"阎立本"},{"key":"C","text":"张璪"},{"key":"D","text":"赵孟頫"}],"answer":["C"],"explanation":"张璪约活跃于8世纪后期，擅长文学，善画山水松石，尤以画松为人所称道。擅水墨山水，尤精松石，传说他能双手分别执笔画松，“一为生枝，一为枯枝，气傲烟霞，势凌风云，槎枒之形，鳞皴之状，随意纵横，应手间出。"},{"id":1460,"type":"单选题","text":"俗话说“一寸光阴一寸金。”这里的“一寸”是用哪种古代计时器量出的时间单位？","options":[{"key":"A","text":"圭表"},{"key":"B","text":"日晷"},{"key":"C","text":"漏刻"},{"key":"D","text":"漏壶"}],"answer":["B"],"explanation":"“一寸光阴一寸金”中的测量用具是日晷,用晷指示日影的长度来代表时间长短。"},{"id":1461,"type":"单选题","text":"我国古代历法中的24节气中“立夏”这一节气大约是现行公历的什么日子？","options":[{"key":"A","text":"4月5-6号"},{"key":"B","text":"5月5-6号"},{"key":"C","text":"5月7-8号"},{"key":"D","text":"4月7-8号"}],"answer":["B"],"explanation":"立夏，是二十四节气中的第7个节气，夏季的第一个节气，交节时间在每年公历5月05-07日。"},{"id":1462,"type":"单选题","text":"一般认为，北宋风俗画，《清明上河图》描绘的是什么季节的景象？","options":[{"key":"A","text":"春天"},{"key":"B","text":"夏天"},{"key":"C","text":"秋天"},{"key":"D","text":"冬天"}],"answer":["A"],"explanation":"《清明上河图》描绘的是春季的景象。"},{"id":1463,"type":"单选题","text":"苏轼在《前赤壁赋》中写道：“壬戌之秋，七月既望”，其中，“既望”指的是____。","options":[{"key":"A","text":"月初"},{"key":"B","text":"十五"},{"key":"C","text":"月末"},{"key":"D","text":"十六"}],"answer":["D"],"explanation":"既望指的是一月内的有些天有特定的称呼，十六称既望。"},{"id":1464,"type":"单选题","text":"古书中男子手里常握有“三尺”,请问它指什么？","options":[{"key":"A","text":"玉佩"},{"key":"B","text":"剑"},{"key":"C","text":"马鞭"},{"key":"D","text":"匕首"}],"answer":["B"],"explanation":"指剑，剑约长三尺，故以“三尺”为剑的代称。"},{"id":1465,"type":"单选题","text":"我国最早的佛寺是？","options":[{"key":"A","text":"嵩山少林寺"},{"key":"B","text":"大理崇圣寺"},{"key":"C","text":"陕西法门寺"},{"key":"D","text":"洛阳白马寺"}],"answer":["D"],"explanation":"洛阳白马寺是佛教传入中国汉地后营建的第一座寺院，位于河南洛阳市东10公里。"},{"id":1466,"type":"单选题","text":"古时,指南针为什么不叫“指北针”？","options":[{"key":"A","text":"面南为尊,面北为卑"},{"key":"B","text":"因为磁针箭头总是朝向南面"},{"key":"C","text":"因为磁针箭头总是朝向北面"},{"key":"D","text":"因为南方经济更发达"}],"answer":["A"],"explanation":"这与我国对方位的认识有关，在我国古代文化里，南为阳，北为阴，且有“南面为王，北面而朝”之说，即面朝南方位的称帝王，面朝北方的则是朝拜君王的臣子。正屋的门窗都开向南，所以指示方向也以南为主。在我国叫指南针是习惯叫法，当然也可以叫指北针，在国外和军事领域就都叫指北针。"},{"id":1467,"type":"单选题","text":"按风俗,“腊八粥”应在阴历哪一天喝？","options":[{"key":"A","text":"十二月初八"},{"key":"B","text":"正月初八"},{"key":"C","text":"十一月初八"},{"key":"D","text":"二月初八"}],"answer":["A"],"explanation":"腊八节，即每年农历十二月八日，又称为“法宝节”“佛成道节”“成道会”等。本为佛教纪念释迦牟尼佛成道之节日，后逐渐也成为民间节日。"},{"id":1468,"type":"单选题","text":"“有板有眼”的\"板\"是我国传统音乐节奏中的____。","options":[{"key":"A","text":"弱拍"},{"key":"B","text":"强拍"},{"key":"C","text":"三连音"},{"key":"D","text":"大切分"}],"answer":["B"],"explanation":"“有板有眼”指民族音乐和戏曲中的节拍，每小节中最强的拍子叫板，其余的拍子叫眼。"},{"id":1469,"type":"单选题","text":"李白笔下的“飞流直下三千尺,疑是银河落九天”指的是哪个风景区？","options":[{"key":"A","text":"黄山"},{"key":"B","text":"九华山"},{"key":"C","text":"普陀山"},{"key":"D","text":"庐山"}],"answer":["D"],"explanation":"《望庐山瀑布二首》是唐代大诗人李白创作的两首诗，一为五言古诗，一为七言绝句。这两首诗，紧扣题目中的“望”字，都以庐山的香炉峰入笔描写庐山瀑布之景。"},{"id":1470,"type":"单选题","text":"先秦时,龙的形象和图案被普遍地比喻为____。","options":[{"key":"A","text":"国王"},{"key":"B","text":"君子"},{"key":"C","text":"神灵"},{"key":"D","text":"妖魔"}],"answer":["B"],"explanation":"先秦时，龙的形象和图案被普遍比喻为君子。"},{"id":1471,"type":"单选题","text":"中国的尼姑最早是何时出现的？","options":[{"key":"A","text":"南北朝"},{"key":"B","text":"汉代"},{"key":"C","text":"唐代"},{"key":"D","text":"宋代"}],"answer":["A"],"explanation":"中国的尼姑最早是南北朝时出现的。"},{"id":1472,"type":"单选题","text":"吴敬梓是____一书的作者。","options":[{"key":"A","text":"《儒林外史》"},{"key":"B","text":"《红楼梦》"},{"key":"C","text":"《镜花缘》"},{"key":"D","text":"《老残游记》"}],"answer":["A"],"explanation":"《儒林外史》是清代吴敬梓创作的长篇小说，成书于乾隆十四年（1749年）或稍前，现以抄本传世，初刻于嘉庆八年（1803年）。"},{"id":1473,"type":"单选题","text":"下列哪部作品不是冯梦龙的著作？","options":[{"key":"A","text":"《古今谭概》"},{"key":"B","text":"《喻世明言》"},{"key":"C","text":"《醒世恒言》"},{"key":"D","text":"《西厢记》"}],"answer":["D"],"explanation":"《崔莺莺待月西厢记》（简称《西厢记》，又称《王西厢》《北西厢》）是元代王实甫创作杂剧，大约写于元贞、大德年间（1295~1307年）。"},{"id":1474,"type":"单选题","text":"中国近代签订的第一个不平等条约是？","options":[{"key":"A","text":"《黄埔条约》"},{"key":"B","text":"《望厦条约》"},{"key":"C","text":"《南京条约》"},{"key":"D","text":"《虎门条约》"}],"answer":["C"],"explanation":"《南京条约》是中国近代史上第一个不平等条约。"},{"id":1475,"type":"单选题","text":"“山药蛋派”形成于20世纪50年代,作品坚持现实主义的创作方法和口语化的写作特点,追求生活的真实,反映生活的矛盾和问题。这一流派的代表作家是____。","options":[{"key":"A","text":"赵树理"},{"key":"B","text":"柳青"},{"key":"C","text":"贾平凹"},{"key":"D","text":"苏童"}],"answer":["A"],"explanation":"山药蛋派是中国当代小说流派之一，形成于20世纪50年代至60年代中期。指以赵树理为代表的一个当代的文学流派。又称为“赵树理派”“山西派”或“火花派”，这是因为新中国成立后该派的作品大都发表在山西文艺刊物《火花》上。"},{"id":1476,"type":"单选题","text":"“不著一字，尽得风流”，出自我国唐代诗论家司空图的哪一篇文章？","options":[{"key":"A","text":"《与李生伦诗书》"},{"key":"B","text":"《诗品》"},{"key":"C","text":"《丁末岁归王官谷》"},{"key":"D","text":"《四溟诗话》"}],"answer":["B"],"explanation":"不著一字，尽得风流是唐司空图关于诗的艺术特征的命题。即要求文学创作做到含蓄蕴藉、意在言外。“不著一字，尽得风流。语不涉难，已不堪忧。是有真宰，与之沉浮。浅深聚散，万取一收，”（《二十四诗品·含蓄》）认为无一字直接述说自己的情思，而自己的情思却在寻常事物的描绘中得到了最完满的表现。"},{"id":1477,"type":"单选题","text":"古代的“会稽”在今天什么省？","options":[{"key":"A","text":"浙江"},{"key":"B","text":"江苏"},{"key":"C","text":"山东"},{"key":"D","text":"安徽"}],"answer":["A"],"explanation":"会稽郡中国古代郡名，位于长江下游江南一带。于公元前222年（秦朝）置郡，郡治山阴县（今浙江省绍兴市），历史上曾管辖春秋时长江以南的越国和吴国故地。"},{"id":1478,"type":"单选题","text":"中国古代称戏曲演员为“梨园子弟”，“梨园子弟”的称号出自哪个朝代？","options":[{"key":"A","text":"宋朝"},{"key":"B","text":"元朝"},{"key":"C","text":"唐朝"},{"key":"D","text":"明朝"}],"answer":["C"],"explanation":"“梨园子弟”的称号出现在唐朝。出自：清·吴敬梓《儒林外史》第三十回：“通省梨园子弟各班愿与者，书名画知，届时齐集湖亭，各演杂剧。"},{"id":1479,"type":"单选题","text":"北宋一个皇帝爱琴，特别设立了“官琴局”；又善画画，代表作有《听琴图》。请问这位皇帝下面的哪一位？","options":[{"key":"A","text":"赵佶"},{"key":"B","text":"赵祯"},{"key":"C","text":"赵构"},{"key":"D","text":"赵昀"}],"answer":["A"],"explanation":"《听琴图》是传为北宋宋徽宗赵佶创作的一幅绢本设色工笔画，此画现藏于北京故宫博物院。"},{"id":1480,"type":"单选题","text":"李清照是我国历史上杰出的女词人。她中年以后作品的突出特点是____。","options":[{"key":"A","text":"怀念中原故土，渗透了忧伤的感情。"},{"key":"B","text":"着重揭露封建统治的腐朽和黑暗。"},{"key":"C","text":"着重表达豪迈奔放的思想感情。"},{"key":"D","text":"反映市民生活面貌，具有浓厚的市民气息。"}],"answer":["A"],"explanation":"前期多写其悠闲生活，后期多悲叹身世，情调感伤。"},{"id":1481,"type":"单选题","text":"名句“孔雀东南飞，五里一徘徊”出自哪里？","options":[{"key":"A","text":"诗经"},{"key":"B","text":"元曲"},{"key":"C","text":"乐府"},{"key":"D","text":"戏剧"}],"answer":["C"],"explanation":"《孔雀东南飞》是中国文学史上第一部长篇叙事诗，也是乐府诗发展史上的高峰之作。"},{"id":1482,"type":"单选题","text":"古代祭祀时所用“三牲”，指的是____。","options":[{"key":"A","text":"牛、羊、猪"},{"key":"B","text":"鸡、鸭、鹅"},{"key":"C","text":"牛、羊、鹅"},{"key":"D","text":"猪、马、牛"}],"answer":["A"],"explanation":"用于祭祀的牛、羊、猪。"},{"id":1483,"type":"单选题","text":"被认为是我国古代中华民族共有的崇拜物是____。","options":[{"key":"A","text":"麒麟"},{"key":"B","text":"龙"},{"key":"C","text":"虎"},{"key":"D","text":"彪"}],"answer":["B"],"explanation":"龙被认为是我国古代中华民族共有的崇拜物。"},{"id":1484,"type":"单选题","text":"我国古代的“拜年”一词特指行为____。","options":[{"key":"A","text":"向长辈叩岁"},{"key":"B","text":"平辈相互道贺"},{"key":"C","text":"亲戚互相走动"},{"key":"D","text":"馈赠礼品"}],"answer":["A"],"explanation":"古时“拜年”一词原有的含义是为长者拜贺新年，包括向长者叩头施礼、祝贺新年如意、问候生活安好等内容。"},{"id":1485,"type":"单选题","text":"我国古代的“贺年”一词特指行为____。","options":[{"key":"A","text":"向长辈叩岁"},{"key":"B","text":"平辈相互道贺"},{"key":"C","text":"亲戚互相走动"},{"key":"D","text":"馈赠礼品"}],"answer":["B"],"explanation":"贺年指平辈相互道贺。"},{"id":1486,"type":"单选题","text":"小说是我国古典文学的一种重要体裁,明清时期是我国古代小说发展的顶峰,涌现出许多著名的小说,如《红楼梦》、《三国演义》、《水浒传》、《西游记》就是其中最为著名的代表,被后人并称为四大名著。《水浒传》的作者是？","options":[{"key":"A","text":"吴承恩"},{"key":"B","text":"曹雪芹"},{"key":"C","text":"施耐庵"},{"key":"D","text":"罗贯中"}],"answer":["C"],"explanation":"《水浒传》的作者是施耐庵。"},{"id":1487,"type":"单选题","text":"下面是四大名著中的人物与情节，其中搭配不当的一项是____。","options":[{"key":"A","text":"鲁智深——倒拔垂杨柳"},{"key":"B","text":"孙悟空——大闹天空"},{"key":"C","text":"诸葛亮——三顾茅庐"},{"key":"D","text":"刘姥姥——三进大观园"}],"answer":["C"],"explanation":"刘备——三顾茅庐。"},{"id":1488,"type":"单选题","text":"“孺子牛”一词出自下列哪一部著作？","options":[{"key":"A","text":"《春秋》"},{"key":"B","text":"《诗经》"},{"key":"C","text":"《左传》"},{"key":"D","text":"《庄子》"}],"answer":["C"],"explanation":"“孺子牛”出自《左传·哀公六年》中记载的一个典故，原意是表示父母对子女的过分疼爱。后来现代伟大文学家鲁迅《自嘲》中的“横眉冷对千夫指，俯首甘为孺子牛”名句使“孺子牛”的精神得到升华，人们用“孺子牛”来比喻心甘情愿为人民大众服务，无私奉献的人。"},{"id":1489,"type":"单选题","text":"下列选项对成语“河东狮吼”阐释最准确的一项是哪个？","options":[{"key":"A","text":"妇人善妒，大吵大闹"},{"key":"B","text":"妇人泼皮，动辄大叫"},{"key":"C","text":"妇人暴躁，总发脾气"},{"key":"D","text":"妇人霸道，爱打丈夫"}],"answer":["A"],"explanation":"河东狮吼是一个成语，最早出自《寄吴德仁兼简陈季常》。用来比喻悍妒的妻子对丈夫大吵大闹，借以讥讽惧内的人。"},{"id":1490,"type":"单选题","text":"“问世间情为何物，直教生死相许”这句诗是谁写的？","options":[{"key":"A","text":"元好问"},{"key":"B","text":"柳永"},{"key":"C","text":"晏殊"},{"key":"D","text":"李煜"}],"answer":["A"],"explanation":"“问世间情为何物，直教生死相许”两句词出自金、元之际著名文学家元好问的《摸鱼儿·雁丘词》一词。"},{"id":1491,"type":"单选题","text":"“滥竽充数”出自哪部书？","options":[{"key":"A","text":"《孟子》"},{"key":"B","text":"《墨子》"},{"key":"C","text":"《韩非子》"},{"key":"D","text":"《庄子》"}],"answer":["C"],"explanation":"滥竽充数是一则由寓言故事演化而来的成语，成语最早出自《韩非子·内储说上》。"},{"id":1492,"type":"单选题","text":"下列标题中不属于词牌的是____。","options":[{"key":"A","text":"《忆江南》"},{"key":"B","text":"《凉州词》"},{"key":"C","text":"《虞美人》"},{"key":"D","text":"《沁园春》"}],"answer":["B"],"explanation":"凉州词，又称凉州曲，是达官显贵、宗室名流为凉州歌所填唱词，是唐朝时流行的一种曲调名。"},{"id":1493,"type":"单选题","text":"我国最早的刻本琴谱《神奇秘谱》刊刻于下面哪个朝代？","options":[{"key":"A","text":"唐朝"},{"key":"B","text":"宋朝"},{"key":"C","text":"元代"},{"key":"D","text":"明代"}],"answer":["D"],"explanation":"《神奇秘谱》是明太祖之子朱权编纂的古琴谱集，成书于明初洪熙乙巳（公元1425年），是现存最早的中国琴曲专集。"},{"id":1494,"type":"单选题","text":"成语“逃之夭夭”最早形容的对象是下面的哪一种？","options":[{"key":"A","text":"歹徒"},{"key":"B","text":"猕猴"},{"key":"C","text":"桃花"},{"key":"D","text":"敌人"}],"answer":["C"],"explanation":"逃之夭夭由“桃之夭夭”引申而来，用“逃之夭夭”表示逃跑，是诙谐的说法。“桃之夭夭”出自《诗经·周南·桃夭》。《诗经·周南·桃夭》：“桃之夭夭，灼灼其华。”"},{"id":1495,"type":"单选题","text":"白居易《暮江吟》中“露似真珠月似弓”写的是哪一天夜晚的月亮？","options":[{"key":"A","text":"九月初九"},{"key":"B","text":"八月初四"},{"key":"C","text":"九月初三"},{"key":"D","text":"八月初三"}],"answer":["C"],"explanation":"暮江吟\n一道残阳铺水中 ，半江瑟瑟半江红。\n可怜九月初三夜，露似真珠月似弓。"},{"id":1496,"type":"单选题","text":"古语云“博学之，审问之，慎思之，明辨之，笃行之”，此句出自哪里？","options":[{"key":"A","text":"《大学》"},{"key":"B","text":"《中庸》"},{"key":"C","text":"《论语》"},{"key":"D","text":"《荀子》"}],"answer":["B"],"explanation":"“博学之，审问之，慎思之，明辨之，笃行之”是一个汉语词汇，意思是要博学多才，就要对学问详细地询问，彻底搞懂，要慎重地思考，要明白地辨别，要切实地力行。出自《礼记·中庸》。"},{"id":1497,"type":"单选题","text":"“人生而静，天之性也”的意思是？","options":[{"key":"A","text":"人生很平静，这是上天注定的"},{"key":"B","text":"人生没有大起大落"},{"key":"C","text":"人生来是没有欲望，这是天赋予的本性"},{"key":"D","text":"人生的情欲是由上天注定的"}],"answer":["C"],"explanation":"人生来沉静，这是人的先天禀性。而由外界事物的影响而生出不同的感受,这也是天性的一种本能。"},{"id":1498,"type":"单选题","text":"“为天地立心，为生民立命，为往圣继绝学，为万世开太平。”是下面哪一位的名言？","options":[{"key":"A","text":"张载"},{"key":"B","text":"朱熹"},{"key":"C","text":"程颐"},{"key":"D","text":"王守仁"}],"answer":["A"],"explanation":"为天地立心是宋朝思想家张载的名言。"},{"id":1499,"type":"单选题","text":"尘世难逢开口笑，菊花须插满头归。但将酩酊酬佳节，不用登临恨落晖。”这几句诗写出了诗人杜牧面对佳节美景时的矛盾心情。请问，这里的“佳节”指的是？","options":[{"key":"A","text":"中秋节"},{"key":"B","text":"元宵节"},{"key":"C","text":"重阳节"},{"key":"D","text":"端午节"}],"answer":["C"],"explanation":"出自杜牧作品《九日齐山登高》，佳节指的是重阳节。"},{"id":1500,"type":"单选题","text":"明代王世贞诗“昔闻李供奉，长啸独登楼”中的“李供奉”指的是？","options":[{"key":"A","text":"李白"},{"key":"B","text":"李贺"},{"key":"C","text":"李商隐"},{"key":"D","text":"李世民"}],"answer":["A"],"explanation":"《登太白楼》为明代诗人王世贞之作，是一首登临怀古诗，诗中缅怀李白，对其文章、风采表示了极为崇敬的心情。直写李白的飘逸神姿，感叹楼仍在而大诗人李白之后无人可及。"},{"id":1501,"type":"单选题","text":"“世上疮痍，诗中圣哲；人间疾苦，笔底波澜”是对哪位诗人的评价？","options":[{"key":"A","text":"范仲淹"},{"key":"B","text":"辛弃疾"},{"key":"C","text":"陆游"},{"key":"D","text":"杜甫"}],"answer":["D"],"explanation":"杜甫作品被称为世上疮痍,诗中圣哲;民间疾苦,笔底波澜。是现实主义诗歌的代表作。"},{"id":1502,"type":"单选题","text":"对下列词语的相关内容的解说，不正确的一项是____。","options":[{"key":"A","text":"大理寺，中央司法机构。北齐定制，历代沿置，掌司狱定刑，长官为大理寺卿。"},{"key":"B","text":"黄河在古代被称为“河”或“河汉”，习惯上人们把注入外海外洋的称为“河”，把注入内湖内海的称为“江”。"},{"key":"C","text":"宋代实行重文抑武的国策，文官地位比武将要高，宰相的权力比较大。"},{"key":"D","text":"雅歌投壶，是古代秦汉以后贵族内部的吟诗与游戏活动，雅歌谓歌《雅诗》，投壶就是将箭矢投入到装有小豆的小口壶中，能够投中者即获胜。后常用以指武将之儒雅行为。"}],"answer":["B"],"explanation":"“河汉”指的是“银河”，“人们把注入外海外洋的河流称为江，把注入内湖内海的河流成为河”。"},{"id":1503,"type":"单选题","text":"王勃是哪个时代的诗人？他的死因是____。","options":[{"key":"A","text":"初唐 病死"},{"key":"B","text":"盛唐 溺死"},{"key":"C","text":"初唐 溺死"},{"key":"D","text":"盛唐 病死"}],"answer":["C"],"explanation":"王勃(约650年-约676年)，字子安，汉族，唐代诗人。古绛州龙门(今山西河津)人，出身儒学世家，与杨炯、卢照邻、骆宾王并称为“初唐四杰”，王勃为四杰之首。上元三年(676年)八月，自交趾探望父亲返回时，不幸渡海溺水，惊悸而死。"},{"id":1504,"type":"单选题","text":"传统节日的形成过程，是一个民族或国家的历史文化长期积淀凝聚的过程，我国的传统节日，无一不是从远古发展过来的。下面关于传统节日的描述，正确的是____。","options":[{"key":"A","text":"七夕节，来自牛郎与织女的传说，在农历七月初七庆祝，以乞巧为主。"},{"key":"B","text":"上元节，俗称“鬼节”“七月半”，在阴历七月十五日，以祭鬼为主。"},{"key":"C","text":"清明节，亦称“禁烟节”，在这一日，禁烟火，只吃冷食。"},{"key":"D","text":"中元节，农历正月十五，以吃元宵、赏灯、舞狮和未婚男女交往为习俗。"}],"answer":["A"],"explanation":"上元节，是农历正月十五元宵节，以吃元宵、赏灯、舞狮和未婚男女出游交往幽会为习俗。中元节，俗称“鬼节”“七月半”，在阴历七月十五日，以祭鬼为主。寒食节，亦称“禁烟节”，在这一日，禁烟火，只吃冷食。"},{"id":1505,"type":"单选题","text":"《满井游记》开篇：“燕地寒，花朝节后，余寒犹厉。”请问“花朝节”在农历的几月？","options":[{"key":"A","text":"二月"},{"key":"B","text":"三月"},{"key":"C","text":"四月"},{"key":"D","text":"五月"}],"answer":["A"],"explanation":"花朝节，是指中国百花的生日，简称花朝，也称“花神节”、“百花生日”、“花神生日”、“挑菜节”，汉族传统节日，流行于东北、华北、华东、中南等地，一般于农历二月初二、二月十二或二月十五、二月二十五举行。"},{"id":1506,"type":"单选题","text":"被后世称为“梅妻鹤子”的是谁？","options":[{"key":"A","text":"梅尧臣"},{"key":"B","text":"晏殊"},{"key":"C","text":"苏舜钦"},{"key":"D","text":"林逋"}],"answer":["D"],"explanation":"以梅为妻，以鹤为子。比喻清高或隐居。宋·林逋隐居西湖孤山，植梅养鹤，终生不娶，人谓“梅妻鹤子”。"},{"id":1507,"type":"单选题","text":"下面哪个成语与秦始皇有关？","options":[{"key":"A","text":"指鹿为马"},{"key":"B","text":"奇货可居"},{"key":"C","text":"图穷匕见"},{"key":"D","text":"一诺千金"}],"answer":["C"],"explanation":"与秦始皇有关的成语有：图穷匕见、焚书坑儒、书同文,车同轨、封禅泰山、千古一帝。"},{"id":1508,"type":"单选题","text":"龚自珍《咏史》“牢盆狎客操全算，团扇才人踞上游”中，“团扇才人”是指谁？","options":[{"key":"A","text":"名妓"},{"key":"B","text":"高官"},{"key":"C","text":"文人"},{"key":"D","text":"盐商"}],"answer":["C"],"explanation":"“团扇才人”是对轻薄文人的贬称。"},{"id":1509,"type":"单选题","text":"下列哪项不属于《山海经》中的异兽？","options":[{"key":"A","text":"朱獳"},{"key":"B","text":"蛊雕"},{"key":"C","text":"猾褢"},{"key":"D","text":"少辛"}],"answer":["D"],"explanation":"少辛是一种植物。"},{"id":1510,"type":"单选题","text":"下列哪项跟炎帝没有关系？","options":[{"key":"A","text":"女娲"},{"key":"B","text":"祝融"},{"key":"C","text":"嫘祖"},{"key":"D","text":"伯陵"}],"answer":["C"],"explanation":"嫘祖是轩辕皇帝的妃子。"},{"id":1511,"type":"单选题","text":"成语“请君入瓮”，“请”的是谁？","options":[{"key":"A","text":"来俊臣"},{"key":"B","text":"周兴"},{"key":"C","text":"李林甫"},{"key":"D","text":"赵高"}],"answer":["B"],"explanation":"成语“请君入瓮”，“请”的是周兴。"},{"id":1512,"type":"单选题","text":"“路漫漫其修远兮，吾将上下而求索”是谁的名言？","options":[{"key":"A","text":"孔子"},{"key":"B","text":"屈原"},{"key":"C","text":"孟子"},{"key":"D","text":"老子"}],"answer":["B"],"explanation":"\"路漫漫其修远兮，吾将上下而求索\"出自屈原《离骚》第97句。"},{"id":1513,"type":"单选题","text":"成语“一鸣惊人”的由来，与下面哪一位有关？","options":[{"key":"A","text":"齐桓公"},{"key":"B","text":"楚庄王"},{"key":"C","text":"晋文公"},{"key":"D","text":"齐宣王"}],"answer":["B"],"explanation":"一鸣惊人主要讲的是楚庄王励精图治收服南方许多部落，到第6年，打败了宋国，第8年，又打败了陆浑的戎族，一直打到周都洛邑附近的故事。"},{"id":1514,"type":"单选题","text":"孔子谓季氏：“八佾舞于庭，____。”","options":[{"key":"A","text":"士可忍，孰不可忍"},{"key":"B","text":"是可忍，孰不可忍"},{"key":"C","text":"士可忍也，孰不可忍也"},{"key":"D","text":"是可忍也，孰不可忍也"}],"answer":["D"],"explanation":"孔子谓季氏：“八佾舞于庭，是可忍也，孰不可忍也?”"},{"id":1515,"type":"单选题","text":"下面哪个是农历五月的别称？","options":[{"key":"A","text":"杏月"},{"key":"B","text":"桃月"},{"key":"C","text":"榴月"},{"key":"D","text":"荷月"}],"answer":["C"],"explanation":"以花命名的农历各月份的诗意别称：正月——柳月，银柳插瓶头，又称柳月；二月——杏月，杏花闹枝头，又称杏月；三月——桃月，桃花粉面羞，又称桃月；四月——槐月，槐花挂满枝，又称槐月；五月——榴月，石榴红似火，又称榴月；六月——荷月，荷花满池放，又称荷月；七月——巧月，凤仙节节开，又称巧月；八月——桂月，桂花遍地香，又称桂月；九月——菊月，菊花傲霜雪，又称菊月；十月——阳月，芙蓉显小阳，又称阳月；十一月——葭月，葭草吐绿头，又称葭月；腊月——梅月，梅花吐幽香，又称梅月。"},{"id":1516,"type":"单选题","text":"“一饭千金”的故事主人公是谁？","options":[{"key":"A","text":"韩信"},{"key":"B","text":"刘邦"},{"key":"C","text":"项羽"},{"key":"D","text":"萧何"}],"answer":["A"],"explanation":"西汉·司马迁《史记·淮阴侯列传》：“信钓于城下，诸漂母漂，有一母见信饥，饭信，竟漂数十日。”又：“信至国，如所从食漂母，赐千金。”"},{"id":1517,"type":"单选题","text":"下列哪个成语典故说的是吕不韦的故事？","options":[{"key":"A","text":"一字千金"},{"key":"B","text":"一诺千金"},{"key":"C","text":"一饭千金"},{"key":"D","text":"一掷千金"}],"answer":["A"],"explanation":"一字千金出自《史记•吕不韦列传》：“布成阳市门，悬千金其上，延诸侯游士宾客有能增损一字者予千金”。“一字千金”后来也形容诗文的价值极高，以表示对文辞的赞美。"},{"id":1518,"type":"单选题","text":"子在川上曰：“逝者如斯夫！不舍昼夜。”对其中“逝者”理解正确的一项是哪个？","options":[{"key":"A","text":"失去的人"},{"key":"B","text":"消逝的时光"},{"key":"C","text":"流淌的水"},{"key":"D","text":"消逝的友情"}],"answer":["B"],"explanation":"“逝者如斯夫”出自《论语》，形容时间像流水一样不停地流逝，一去不复返，感慨人生世事变换之快，亦有惜时之意在其中。逝者：指流逝的时光"},{"id":1519,"type":"单选题","text":"“国家兴亡，匹夫有责”是下列哪一位名人的名言？","options":[{"key":"A","text":"魏征"},{"key":"B","text":"陆游"},{"key":"C","text":"顾炎武"},{"key":"D","text":"魏源"}],"answer":["C"],"explanation":"语本清·顾炎武《日知录·正始》“保国者，其君其臣，肉食者谋；保天下者，匹夫之贱，与有责焉耳矣”。"},{"id":1520,"type":"单选题","text":"“文官不爱钱，武官不惜死，果如公言，宋室何至南渡;罪名莫须有，忠冢栖霞山，长留人愿，国魂几时北来。” 这幅对联描写的历史人物是谁？","options":[{"key":"A","text":"岳飞"},{"key":"B","text":"辛弃疾"},{"key":"C","text":"范仲淹"},{"key":"D","text":"陆游"}],"answer":["A"],"explanation":"《宋史·岳飞传》：“或问： ‘天下何时太平?’飞曰：‘文臣不爱钱，武臣不惜死，天下太平矣。’”"},{"id":1521,"type":"单选题","text":"王实甫在《西厢记》中写道:“淋漓襟袖啼红泪，比司马青衫更湿”，其中“司马青衫”指的是谁？","options":[{"key":"A","text":"司马相如"},{"key":"B","text":"崔莺莺"},{"key":"C","text":"白居易"},{"key":"D","text":"杜甫"}],"answer":["C"],"explanation":"“司马青衫”的意思是“司马的衣衫为泪水所湿”，形容“极度悲伤”，“司马”是古代官名，唐代诗人白居易曾贬官为江州司马，“司马青衫”出自《琵琶行》。"},{"id":1522,"type":"单选题","text":"文人对各种植物有自己的偏爱，陶渊明喜爱菊花，苏东坡则说过:宁可食无肉，不可什么？","options":[{"key":"A","text":"居无松"},{"key":"B","text":"居无竹"},{"key":"C","text":"居无梅"},{"key":"D","text":"居无菊"}],"answer":["B"],"explanation":"宁可食无肉不可居无竹。"},{"id":1523,"type":"单选题","text":"《在水一方》的歌词来源于哪一部文学经典？","options":[{"key":"A","text":"《诗经》"},{"key":"B","text":"《陌上桑》"},{"key":"C","text":"《楚辞》"},{"key":"D","text":"《孔雀东南飞》"}],"answer":["A"],"explanation":"“在水一方”在诗经秦风《蒹葭》中的意思是：在河的另一边（对岸）。"},{"id":1524,"type":"单选题","text":"“得鱼忘筌”中的“筌”指的是什么？","options":[{"key":"A","text":"鱼竿"},{"key":"B","text":"鱼钩"},{"key":"C","text":"捕鱼用的竹器"},{"key":"D","text":"鱼饵"}],"answer":["C"],"explanation":"出自《庄子·外物》，“筌者所以在鱼，得鱼而忘筌；言者所以在意，得意而忘言”，原意为得到了想要的对象，手段便不重要了。后被引申比喻事情成功以后就忘了本来依靠的东西。筌，通荃，意为捕鱼的竹器。"},{"id":1525,"type":"单选题","text":"世界上最早的纸币\"交子\"出现在哪里？","options":[{"key":"A","text":"北宋的四川成都"},{"key":"B","text":"唐代的长安"},{"key":"C","text":"南宋的临安"},{"key":"D","text":"元代的大都"}],"answer":["A"],"explanation":"交子是世界上最早的纸币，出现于北宋的四川地区，因当地用铁钱笨重、商界发行代用券而得名。"},{"id":1526,"type":"单选题","text":"清代著名的商帮中，实力最强的是哪一支？","options":[{"key":"A","text":"徽商"},{"key":"B","text":"晋商"},{"key":"C","text":"潮商"},{"key":"D","text":"鲁商"}],"answer":["B"],"explanation":"清代著名商帮中，晋商（山西商帮）是发展起来且实力最强的。"},{"id":1527,"type":"单选题","text":"科举中\"连中三元\"的\"三元\"具体指什么？","options":[{"key":"A","text":"解元、会元、状元"},{"key":"B","text":"秀才、举人、进士"},{"key":"C","text":"状元、榜眼、探花"},{"key":"D","text":"乡试、会试、殿试"}],"answer":["A"],"explanation":"乡试第一名称\"解元\"，会试第一名称\"会元\"，殿试第一名称\"状元\"，三级考试皆得第一即\"连中三元\"。"},{"id":1528,"type":"单选题","text":"科举取得第一名被称为\"独占鳌头\"，这与什么有关？","options":[{"key":"A","text":"殿试状元站在鳌头（雕刻的鳌的头部）上迎榜"},{"key":"B","text":"状元帽上的鳌形饰物"},{"key":"C","text":"考场大门上的鳌形浮雕"},{"key":"D","text":"皇帝座位上的鳌纹"}],"answer":["A"],"explanation":"殿试发榜时状元站在殿前台阶正中鳌头之上迎榜，故称中状元为\"独占鳌头\"。"},{"id":1529,"type":"单选题","text":"戏曲艺人被称为\"梨园子弟\"，这一行业起源与谁有关？","options":[{"key":"A","text":"唐太宗"},{"key":"B","text":"唐玄宗"},{"key":"C","text":"宋徽宗"},{"key":"D","text":"乾隆帝"}],"answer":["B"],"explanation":"唐玄宗在宫廷梨园中教习乐工、培训艺人，后世遂称戏曲艺人为\"梨园子弟\"。"},{"id":1530,"type":"单选题","text":"中国古代音乐的\"五音\"指的是哪五个音级？","options":[{"key":"A","text":"宫、商、角、徵、羽"},{"key":"B","text":"金、石、丝、竹"},{"key":"C","text":"哆、来、咪、发、嗦"},{"key":"D","text":"黄钟、大吕、太簇、夹钟、姑洗"}],"answer":["A"],"explanation":"古代五音又称五声，即宫、商、角、徵、羽，相当于简谱中的1、2、3、5、6。"},{"id":1531,"type":"单选题","text":"\"生、旦、净、末、丑\"指的是什么？","options":[{"key":"A","text":"古代五种官职"},{"key":"B","text":"戏曲的五种角色行当"},{"key":"C","text":"五种乐器"},{"key":"D","text":"五种科考科目"}],"answer":["B"],"explanation":"生旦净末丑是戏曲的五种角色行当，人们用这些字眼来命名角色类型。"},{"id":1532,"type":"单选题","text":"\"三省六部\"制度是什么时候创立的？","options":[{"key":"A","text":"秦汉"},{"key":"B","text":"隋唐"},{"key":"C","text":"宋元"},{"key":"D","text":"明清"}],"answer":["B"],"explanation":"三省六部制创立于隋朝、经唐代完善，三省指中书省、门下省、尚书省，六部为尚书省所辖。"},{"id":1533,"type":"单选题","text":"科举制度是什么时候创立的？","options":[{"key":"A","text":"汉朝"},{"key":"B","text":"隋朝"},{"key":"C","text":"唐朝"},{"key":"D","text":"宋朝"}],"answer":["B"],"explanation":"科举制度创立于隋朝（隋文帝废除九品中正制、隋炀帝设进士科），到唐代进一步完善。"},{"id":1534,"type":"单选题","text":"\"杏林\"的说法是怎么来的？它与哪位名医有关？","options":[{"key":"A","text":"华佗"},{"key":"B","text":"张仲景"},{"key":"C","text":"董奉"},{"key":"D","text":"李时珍"}],"answer":["C"],"explanation":"三国名医董奉为人治病不收钱财，只求愈者植杏，日久蔚然成林，后世遂以\"杏林\"代称医界。"},{"id":1535,"type":"单选题","text":"中药店多称\"堂\"而不称\"店\"，这个叫法与谁有关？","options":[{"key":"A","text":"神农氏"},{"key":"B","text":"张仲景"},{"key":"C","text":"孙思邈"},{"key":"D","text":"扁鹊"}],"answer":["B"],"explanation":"相传医圣张仲景任长沙太守时\"坐堂行医\"，在后堂为百姓诊病，中药店遂沿用\"堂\"的叫法。"},{"id":1536,"type":"单选题","text":"万里长城被称为\"主线\"的是哪一段？","options":[{"key":"A","text":"东起辽东、西至临洮的秦长城"},{"key":"B","text":"东起山海关、西到嘉峪关的部分"},{"key":"C","text":"汉武帝修建的河西长城"},{"key":"D","text":"明代的辽东边墙"}],"answer":["B"],"explanation":"万里长城东起山海关、西到嘉峪关的部分被称为\"主线\"，是长城文化的核心。"},{"id":1537,"type":"单选题","text":"古人送别多会\"折柳\"，这个习俗的寓意是什么？","options":[{"key":"A","text":"\"柳\"谐音\"留\"，表达挽留惜别之情"},{"key":"B","text":"柳枝可驱邪避凶"},{"key":"C","text":"柳枝象征长寿"},{"key":"D","text":"折柳是当地的特产礼物"}],"answer":["A"],"explanation":"汉代起人们以柳寄情，\"柳\"与\"留\"谐音，折柳赠别寓意惜别与祝愿远行者随遇而安。"},{"id":1538,"type":"单选题","text":"民间所谓\"五毒\"，下列哪一项不在其列？","options":[{"key":"A","text":"蝎子"},{"key":"B","text":"蜈蚣"},{"key":"C","text":"蜘蛛"},{"key":"D","text":"蟾蜍"}],"answer":["C"],"explanation":"\"五毒\"一般指蛇、蝎、蜈蚣、壁虎、蟾蜍，蜘蛛不在其列。"},{"id":1539,"type":"单选题","text":"古代男子二十岁行冠礼，这个年龄称为什么？","options":[{"key":"A","text":"弱冠"},{"key":"B","text":"而立"},{"key":"C","text":"不惑"},{"key":"D","text":"知天命"}],"answer":["A"],"explanation":"男子二十岁行冠礼、表示成年，称\"弱冠\"；三十而立、四十不惑、五十知天命。"},{"id":1540,"type":"单选题","text":"古人把国家称为\"江山社稷\"，\"社稷\"指的是什么？","options":[{"key":"A","text":"土地神和谷神"},{"key":"B","text":"天地和四季"},{"key":"C","text":"宗庙和宫殿"},{"key":"D","text":"江山和疆域"}],"answer":["A"],"explanation":"\"社\"为土地之神，\"稷\"为五谷之神，君主年年祭祀社稷以求风调雨顺，后来\"社稷\"就代指国家。"},{"id":1541,"type":"单选题","text":"古代帝王举行封禅大典，主要在哪里进行？","options":[{"key":"A","text":"华山"},{"key":"B","text":"泰山"},{"key":"C","text":"嵩山"},{"key":"D","text":"黄山"}],"answer":["B"],"explanation":"封禅是帝王祭告天地的大典，在泰山举行：\"封\"为在泰山之顶祭天，\"禅\"为在泰山之下小山祭地。"},{"id":1542,"type":"单选题","text":"皇帝的龙袍上绣有几条龙？","options":[{"key":"A","text":"五条"},{"key":"B","text":"七条"},{"key":"C","text":"九条"},{"key":"D","text":"十二条"}],"answer":["C"],"explanation":"龙袍上绣九条龙，九为极数、象征至尊；龙袍看似五条龙，是因有一条绣在里襟上。"},{"id":1543,"type":"单选题","text":"古代针对女子的\"人彘\"酷刑，最早是谁施用的？","options":[{"key":"A","text":"吕后"},{"key":"B","text":"武则天"},{"key":"C","text":"慈禧"},{"key":"D","text":"妲己"}],"answer":["A"],"explanation":"汉高祖死后，吕后将戚夫人断手足、去眼熏耳、饮哑药，置于厕中称为\"人彘\"，这是\"人彘\"酷刑的最早记载。"},{"id":1544,"type":"单选题","text":"古代\"笞刑\"只打屁股不打背，相传是谁规定的？","options":[{"key":"A","text":"汉文帝"},{"key":"B","text":"唐太宗"},{"key":"C","text":"宋太祖"},{"key":"D","text":"明太祖"}],"answer":["B"],"explanation":"相传唐太宗看到针灸图，知道人体重要经络多附于背部，于是规定笞刑不得鞭背，只打臀部。"},{"id":1545,"type":"单选题","text":"古代军队把人头称为\"首级\"，与什么有关？","options":[{"key":"A","text":"以斩首计军功，斩一首进爵一级"},{"key":"B","text":"首领的级别"},{"key":"C","text":"祭祀首级之礼"},{"key":"D","text":"\"首\"与\"级\"音近"}],"answer":["A"],"explanation":"\"首级\"与古代军功爵制有关：作战以斩获敌人首级的数目来计功进爵，一首进爵一级。"},{"id":1546,"type":"单选题","text":"\"大战三百回合\"的\"回合\"原指什么？","options":[{"key":"A","text":"双方战车交错后各自返回再战的一个循环"},{"key":"B","text":"一炷香的时间"},{"key":"C","text":"一支箭的射程"},{"key":"D","text":"阵前一次对骂"}],"answer":["A"],"explanation":"\"回合\"源于古代车战：双方战车冲向对方，交错之后再调头返回，准备第二次厮杀，这样一个来回叫一个\"回合\"。"},{"id":1547,"type":"单选题","text":"参军被称为\"入伍\"，源于古代军队编制中几人为一\"伍\"？","options":[{"key":"A","text":"三人"},{"key":"B","text":"五人"},{"key":"C","text":"十人"},{"key":"D","text":"百人"}],"answer":["B"],"explanation":"古代军队以\"伍\"为基层编制，五人为一伍，因此参军被称为\"入伍\"。"},{"id":1548,"type":"单选题","text":"宋高宗连发十二道\"金牌\"召回岳飞，\"金牌\"指什么？","options":[{"key":"A","text":"黄金铸造的奖牌"},{"key":"B","text":"皇帝急递文书的红漆金字木牌"},{"key":"C","text":"调兵的兵符"},{"key":"D","text":"免死金牌"}],"answer":["B"],"explanation":"\"金牌\"是宋代皇帝发出、由驿站急递的红漆金字木牌，用于传递最紧急的诏命文书，并非黄金奖牌。"},{"id":1549,"type":"单选题","text":"我国古代最早的印刷术是哪一种？","options":[{"key":"A","text":"活字印刷"},{"key":"B","text":"雕版印刷"},{"key":"C","text":"套色印刷"},{"key":"D","text":"铅字印刷"}],"answer":["B"],"explanation":"我国最早的印刷技术是雕版印刷，先在木板上刻出反字再刷墨印制，活字印刷是后来的改进。"},{"id":1550,"type":"单选题","text":"中医被称为\"岐黄之术\"，\"岐黄\"指的是谁？","options":[{"key":"A","text":"岐伯与黄帝"},{"key":"B","text":"扁鹊与仓公"},{"key":"C","text":"张仲景与华佗"},{"key":"D","text":"岐山黄姓名医"}],"answer":["A"],"explanation":"\"岐黄\"指岐伯与黄帝，相传黄帝与岐伯论医，总结出中医的基本理论，故中医称\"岐黄之术\"。"},{"id":1551,"type":"单选题","text":"成语\"对牛弹琴\"中，对牛弹琴的那个人是谁？","options":[{"key":"A","text":"伯牙"},{"key":"B","text":"公明仪"},{"key":"C","text":"师旷"},{"key":"D","text":"嵇康"}],"answer":["B"],"explanation":"\"对牛弹琴\"说的是古时琴师公明仪，他对着牛弹奏高雅的曲子，牛只顾吃草。"},{"id":1552,"type":"单选题","text":"孔子在齐国听到一种音乐，着迷得\"三月不知肉味\"，这是什么音乐？","options":[{"key":"A","text":"《武》乐"},{"key":"B","text":"《韶》乐"},{"key":"C","text":"《雅》乐"},{"key":"D","text":"《颂》乐"}],"answer":["B"],"explanation":"孔子在齐国听到《韶》乐，陶醉得\"三月不知肉味\"，称赞它尽善尽美。"},{"id":1553,"type":"单选题","text":"把知心朋友称为\"知音\"，源于哪个故事？","options":[{"key":"A","text":"伯牙与钟子期"},{"key":"B","text":"管仲与鲍叔牙"},{"key":"C","text":"廉颇与蔺相如"},{"key":"D","text":"刘关张桃园结义"}],"answer":["A"],"explanation":"伯牙鼓琴，钟子期能听懂他琴声中的高山流水之意，子期死后伯牙终身不复鼓琴，\"知音\"由此而来。"},{"id":1554,"type":"单选题","text":"被后世尊为\"画圣\"的是哪位画家？","options":[{"key":"A","text":"顾恺之"},{"key":"B","text":"吴道子"},{"key":"C","text":"张择端"},{"key":"D","text":"唐伯虎"}],"answer":["B"],"explanation":"吴道子画艺超群，后世史家数不胜数的画家中独尊他为\"画圣\"。"},{"id":1555,"type":"单选题","text":"名画《清明上河图》的作者是谁？","options":[{"key":"A","text":"张择端"},{"key":"B","text":"王希孟"},{"key":"C","text":"范宽"},{"key":"D","text":"黄公望"}],"answer":["A"],"explanation":"《清明上河图》是北宋画家张择端的名作，描绘了汴京的繁华景象。"},{"id":1556,"type":"单选题","text":"传统的音乐盒叫\"八音盒\"，\"八音\"原指什么？","options":[{"key":"A","text":"八种制作乐器的材料"},{"key":"B","text":"八种乐器"},{"key":"C","text":"八个音阶"},{"key":"D","text":"八种曲调"}],"answer":["A"],"explanation":"\"八音\"指金、石、丝、竹、匏、土、革、木八类制作乐器的材料，故乐器曲统称音乐，音乐盒也因此称\"八音盒\"。"},{"id":1557,"type":"单选题","text":"\"一亩三分地\"的说法与皇帝的哪种礼仪有关？","options":[{"key":"A","text":"春耕前的\"籍田\"礼"},{"key":"B","text":"祭天大典"},{"key":"C","text":"耕战之礼"},{"key":"D","text":"分封诸侯之礼"}],"answer":["A"],"explanation":"古代皇帝重视农业，春耕之前要行\"籍田\"礼亲自下地耕作，皇帝亲耕的那块地就是\"一亩三分地\"。"},{"id":1558,"type":"单选题","text":"古时的\"寒食节\"为什么不允许生火做饭？","options":[{"key":"A","text":"纪念介子推"},{"key":"B","text":"纪念屈原"},{"key":"C","text":"祭祀灶神"},{"key":"D","text":"防止火灾"}],"answer":["A"],"explanation":"相传寒食节为纪念宁死不出山的介子推而设，节日期间禁止生火，只能冷食，故称\"寒食\"。"},{"id":1559,"type":"单选题","text":"关于端午节的由来，除了纪念屈原，还有人认为是纪念谁？","options":[{"key":"A","text":"伍子胥"},{"key":"B","text":"介子推"},{"key":"C","text":"韩信"},{"key":"D","text":"曹娥"}],"answer":["A"],"explanation":"端午节为纪念屈原的说法流传最广，也有人认为是纪念伍子胥。"},{"id":1560,"type":"单选题","text":"主张\"人性本恶\"的先秦儒学大师是谁？","options":[{"key":"A","text":"孟子"},{"key":"B","text":"荀子"},{"key":"C","text":"告子"},{"key":"D","text":"韩非"}],"answer":["B"],"explanation":"孟子主张\"人性本善\"，荀子则主张\"人性本恶\"，两位儒学大师观点针锋相对。"},{"id":1561,"type":"单选题","text":"向汉武帝提出\"罢黜百家，独尊儒术\"的是谁？","options":[{"key":"A","text":"董仲舒"},{"key":"B","text":"司马迁"},{"key":"C","text":"主父偃"},{"key":"D","text":"桑弘羊"}],"answer":["A"],"explanation":"汉武帝时董仲舒提出\"罢黜百家，独尊儒术\"，儒家从此成为封建社会的统治思想。"},{"id":1562,"type":"单选题","text":"\"存天理，灭人欲\"是哪位理学家的主张？","options":[{"key":"A","text":"周敦颐"},{"key":"B","text":"朱熹"},{"key":"C","text":"王阳明"},{"key":"D","text":"程颢"}],"answer":["B"],"explanation":"\"存天理，灭人欲\"是南宋理学家朱熹提出的哲学主张。"},{"id":1563,"type":"单选题","text":"\"治大国若烹小鲜\"出自哪部典籍？","options":[{"key":"A","text":"《论语》"},{"key":"B","text":"《道德经》"},{"key":"C","text":"《庄子》"},{"key":"D","text":"《韩非子》"}],"answer":["B"],"explanation":"\"治大国若烹小鲜\"出自老子的《道德经》，意为治理大国要像烹小鱼一样小心谨慎。"},{"id":1564,"type":"单选题","text":"\"大一统\"一词最早见于哪部典籍？","options":[{"key":"A","text":"《春秋公羊传》"},{"key":"B","text":"《史记》"},{"key":"C","text":"《尚书》"},{"key":"D","text":"《吕氏春秋》"}],"answer":["A"],"explanation":"\"大一统\"最早见于《春秋公羊传》\"何言乎王正月？大一统也\"。"},{"id":1565,"type":"单选题","text":"唐僧西天取经，\"西天\"指的是哪里？","options":[{"key":"A","text":"天竺（今印度一带）"},{"key":"B","text":"西域楼兰"},{"key":"C","text":"波斯"},{"key":"D","text":"埃及"}],"answer":["A"],"explanation":"\"西天\"指天竺，即今天的印度一带；唐僧的原型玄奘法师曾赴天竺取经。"},{"id":1566,"type":"单选题","text":"孙悟空\"齐天大圣\"的名号是怎么来的？","options":[{"key":"A","text":"孙悟空自封，后被天庭追认"},{"key":"B","text":"如来佛祖所赐"},{"key":"C","text":"观音菩萨所封"},{"key":"D","text":"唐僧所起"}],"answer":["A"],"explanation":"\"齐天大圣\"是孙悟空自封的名号，天庭为安抚他，后来只好追认了这个封号。"},{"id":1567,"type":"单选题","text":"《红楼梦》的原名是什么？","options":[{"key":"A","text":"《石头记》"},{"key":"B","text":"《金陵十二钗》"},{"key":"C","text":"《风月宝鉴》"},{"key":"D","text":"《情僧录》"}],"answer":["A"],"explanation":"《红楼梦》原名《石头记》，\"红楼梦\"这一名字是后来才有的。"},{"id":1568,"type":"单选题","text":"奸臣高俅因踢得一脚好球而得荣华富贵，他擅长的运动叫什么？","options":[{"key":"A","text":"蹴鞠"},{"key":"B","text":"马球"},{"key":"C","text":"相扑"},{"key":"D","text":"投壶"}],"answer":["A"],"explanation":"高俅因擅长蹴鞠（古代足球）而深得宋徽宗宠信，由此飞黄腾达。"},{"id":1569,"type":"单选题","text":"人们为何把绘画称为\"丹青\"？","options":[{"key":"A","text":"丹砂和青雘是古代常用的两种矿物颜料"},{"key":"B","text":"画家丹、青两人发明了绘画"},{"key":"C","text":"出自画院之名\"丹青院\""},{"key":"D","text":"丹为朱印、青为印泥"}],"answer":["A"],"explanation":"\"丹\"指丹砂，\"青\"指青雘，是古代绘画最常用的两种矿物颜料，因此绘画被称为\"丹青\"。"},{"id":1570,"type":"单选题","text":"中国历史上第一个王朝是？","options":[{"key":"A","text":"夏"},{"key":"B","text":"商"},{"key":"C","text":"周"},{"key":"D","text":"秦"}],"answer":["A"],"explanation":"禹传启，\"公天下\"变为\"家天下\"，夏朝成为中国历史上第一个王朝。"},{"id":1571,"type":"单选题","text":"\"烽火戏诸侯\"中博得千金一笑的美人是？","options":[{"key":"A","text":"妲己"},{"key":"B","text":"褒姒"},{"key":"C","text":"骊姬"},{"key":"D","text":"西施"}],"answer":["B"],"explanation":"周幽王为博宠妃褒姒一笑，点燃烽火戏弄诸侯，最终身死国灭。"},{"id":1572,"type":"单选题","text":"夏朝王位继承中，大禹之后的继位者是他的儿子？","options":[{"key":"A","text":"启"},{"key":"B","text":"桀"},{"key":"C","text":"汤"},{"key":"D","text":"纣"}],"answer":["A"],"explanation":"禹死后其子启继位，禅让制被世袭制取代。"},{"id":1573,"type":"单选题","text":"商朝前期屡次迁都，最终把都城稳定下来的是盘庚迁？","options":[{"key":"A","text":"亳"},{"key":"B","text":"殷"},{"key":"C","text":"朝歌"},{"key":"D","text":"镐京"}],"answer":["B"],"explanation":"盘庚迁殷（今河南安阳）后商朝稳定下来，故商朝又称殷商。"},{"id":1574,"type":"单选题","text":"商纣王的宠妃是？","options":[{"key":"A","text":"妲己"},{"key":"B","text":"褒姒"},{"key":"C","text":"骊姬"},{"key":"D","text":"西施"}],"answer":["A"],"explanation":"商纣王宠爱妲己，作酒池肉林，最终身死国灭。"},{"id":1575,"type":"单选题","text":"秦朝在地方上推行的是？","options":[{"key":"A","text":"分封制"},{"key":"B","text":"郡县制"},{"key":"C","text":"行省制"},{"key":"D","text":"土司制"}],"answer":["B"],"explanation":"秦废分封、立郡县，郡县长官由中央任免，开创了中央集权的地方行政制度。"},{"id":1576,"type":"单选题","text":"中国历史上第一位平民出身的开国皇帝是？","options":[{"key":"A","text":"刘邦"},{"key":"B","text":"朱元璋"},{"key":"C","text":"刘秀"},{"key":"D","text":"赵匡胤"}],"answer":["A"],"explanation":"刘邦出身布衣，是第一位平民出身的开国皇帝；朱元璋继其后。"},{"id":1577,"type":"单选题","text":"汉武帝时被派往西域联络大月氏夹击匈奴的是？","options":[{"key":"A","text":"张骞"},{"key":"B","text":"苏武"},{"key":"C","text":"班超"},{"key":"D","text":"甘英"}],"answer":["A"],"explanation":"张骞两次出使西域，虽未达成军事目的，却开辟了丝绸之路。"},{"id":1578,"type":"单选题","text":"东汉的建立者是？","options":[{"key":"A","text":"刘秀"},{"key":"B","text":"刘邦"},{"key":"C","text":"刘备"},{"key":"D","text":"刘裕"}],"answer":["A"],"explanation":"西汉末年王莽篡汉，汉宗室刘秀起兵重建汉朝，史称东汉。"},{"id":1579,"type":"单选题","text":"隋代大运河以洛阳为中心，北达？","options":[{"key":"A","text":"涿郡"},{"key":"B","text":"余杭"},{"key":"C","text":"江都"},{"key":"D","text":"番禺"}],"answer":["A"],"explanation":"隋大运河北达涿郡（今北京），南至余杭（今杭州）。"},{"id":1580,"type":"单选题","text":"\"贞观\"是谁在位时使用的年号？","options":[{"key":"A","text":"唐高祖"},{"key":"B","text":"唐太宗"},{"key":"C","text":"唐高宗"},{"key":"D","text":"武则天"}],"answer":["B"],"explanation":"唐太宗李世民年号贞观，其统治时期史称\"贞观之治\"。"},{"id":1581,"type":"单选题","text":"开创\"开元盛世\"的皇帝是？","options":[{"key":"A","text":"唐太宗"},{"key":"B","text":"武则天"},{"key":"C","text":"唐玄宗"},{"key":"D","text":"唐肃宗"}],"answer":["C"],"explanation":"唐玄宗统治前期励精图治，年号开元，出现\"开元盛世\"。"},{"id":1582,"type":"单选题","text":"\"陈桥兵变、黄袍加身\"的主角是？","options":[{"key":"A","text":"赵匡胤"},{"key":"B","text":"赵光义"},{"key":"C","text":"柴荣"},{"key":"D","text":"石敬瑭"}],"answer":["A"],"explanation":"后周殿前都点检赵匡胤在陈桥驿被部下黄袍加身，建立北宋。"},{"id":1583,"type":"单选题","text":"定国号\"大元\"并完成全国统一的蒙古大汗是？","options":[{"key":"A","text":"成吉思汗"},{"key":"B","text":"忽必烈"},{"key":"C","text":"蒙哥"},{"key":"D","text":"窝阔台"}],"answer":["B"],"explanation":"成吉思汗统一蒙古各部，其孙忽必烈定国号大元并灭南宋统一全国。"},{"id":1584,"type":"单选题","text":"明朝开国皇帝朱元璋起义前的身份是？","options":[{"key":"A","text":"和尚、乞丐"},{"key":"B","text":"屠夫"},{"key":"C","text":"盐贩"},{"key":"D","text":"驿卒"}],"answer":["A"],"explanation":"朱元璋幼年贫苦，做过放牛娃、和尚和乞丐，后参加起义军终成帝业。"},{"id":1585,"type":"单选题","text":"清朝入关后的第一位皇帝是？","options":[{"key":"A","text":"皇太极"},{"key":"B","text":"顺治"},{"key":"C","text":"康熙"},{"key":"D","text":"多尔衮"}],"answer":["B"],"explanation":"顺治帝福临于1644年清军入关后即皇帝位，是入关后的第一位皇帝。"},{"id":1586,"type":"单选题","text":"清朝末年长期\"垂帘听政\"的太后是？","options":[{"key":"A","text":"慈安"},{"key":"B","text":"慈禧"},{"key":"C","text":"吕后"},{"key":"D","text":"孝庄"}],"answer":["B"],"explanation":"慈禧太后在同治、光绪两朝实际掌握最高权力近半个世纪。"},{"id":1587,"type":"单选题","text":"传说中以\"禅让\"方式继尧位的部落联盟首领是？","options":[{"key":"A","text":"舜"},{"key":"B","text":"禹"},{"key":"C","text":"启"},{"key":"D","text":"颛顼"}],"answer":["A"],"explanation":"尧年老时推举舜为继承人，舜又传位于禹，是为禅让。"},{"id":1588,"type":"单选题","text":"秦朝\"三公\"中负责监察百官的是？","options":[{"key":"A","text":"丞相"},{"key":"B","text":"太尉"},{"key":"C","text":"御史大夫"},{"key":"D","text":"刺史"}],"answer":["C"],"explanation":"秦朝三公为丞相、太尉、御史大夫，御史大夫负责监察。"},{"id":1589,"type":"单选题","text":"秦朝\"三公\"中主管军事的是？","options":[{"key":"A","text":"丞相"},{"key":"B","text":"太尉"},{"key":"C","text":"御史大夫"},{"key":"D","text":"将军"}],"answer":["B"],"explanation":"太尉掌管全国军事，与丞相、御史大夫并称三公。"},{"id":1590,"type":"单选题","text":"汉武帝为监察地方各郡国设立的官职是？","options":[{"key":"A","text":"刺史"},{"key":"B","text":"太守"},{"key":"C","text":"都尉"},{"key":"D","text":"县令"}],"answer":["A"],"explanation":"汉武帝把全国分为十三州部，每部派刺史一人监察地方。"},{"id":1591,"type":"单选题","text":"隋唐六部中主管官吏任免、考核、升迁的是？","options":[{"key":"A","text":"吏部"},{"key":"B","text":"户部"},{"key":"C","text":"礼部"},{"key":"D","text":"刑部"}],"answer":["A"],"explanation":"六部中吏部掌官吏任免考核，户部掌财政，礼部掌礼仪科举，刑部掌刑狱。"},{"id":1592,"type":"单选题","text":"古代的\"大理寺\"掌管？","options":[{"key":"A","text":"祭祀"},{"key":"B","text":"刑狱案件的审理"},{"key":"C","text":"外交"},{"key":"D","text":"财政"}],"answer":["B"],"explanation":"大理寺是全国最高审判机关，与刑部、都察院合称\"三法司\"。"},{"id":1593,"type":"单选题","text":"明代著名的特务机构不包括？","options":[{"key":"A","text":"锦衣卫"},{"key":"B","text":"东厂"},{"key":"C","text":"西厂"},{"key":"D","text":"理藩院"}],"answer":["D"],"explanation":"锦衣卫与东厂、西厂合称\"厂卫\"，是明代特务机构；理藩院是清代管理民族事务的机构。"},{"id":1594,"type":"单选题","text":"清代\"军机处\"设立于哪位皇帝在位时？","options":[{"key":"A","text":"康熙"},{"key":"B","text":"雍正"},{"key":"C","text":"乾隆"},{"key":"D","text":"嘉庆"}],"answer":["B"],"explanation":"雍正年间设军机房处理西北军务，后改为军机处。"},{"id":1595,"type":"单选题","text":"汉代\"察举制\"下最主要的察举科目是？","options":[{"key":"A","text":"孝廉"},{"key":"B","text":"明经"},{"key":"C","text":"进士"},{"key":"D","text":"军功"}],"answer":["A"],"explanation":"察举制由地方向中央推荐人才，以\"孝廉\"为最重要科目。"},{"id":1596,"type":"单选题","text":"\"九品中正制\"创立于哪个政权？","options":[{"key":"A","text":"曹魏"},{"key":"B","text":"蜀汉"},{"key":"C","text":"东吴"},{"key":"D","text":"西晋"}],"answer":["A"],"explanation":"曹魏黄初元年魏文帝采纳陈群建议创立九品中正制。"},{"id":1597,"type":"单选题","text":"\"上品无寒门，下品无势族\"评价的是哪项选官制度的弊端？","options":[{"key":"A","text":"察举制"},{"key":"B","text":"九品中正制"},{"key":"C","text":"科举制"},{"key":"D","text":"世卿世禄制"}],"answer":["B"],"explanation":"九品中正制后期被门阀士族把持，造成\"上品无寒门，下品无势族\"。"},{"id":1598,"type":"单选题","text":"被百姓称为\"包青天\"的北宋名臣是？","options":[{"key":"A","text":"包拯"},{"key":"B","text":"寇准"},{"key":"C","text":"范仲淹"},{"key":"D","text":"狄青"}],"answer":["A"],"explanation":"包拯为官刚正、执法如山，民间尊称\"包青天\"。"},{"id":1599,"type":"单选题","text":"明代废除丞相制度与哪个事件直接相关？","options":[{"key":"A","text":"靖难之役"},{"key":"B","text":"胡惟庸案"},{"key":"C","text":"土木堡之变"},{"key":"D","text":"夺门之变"}],"answer":["B"],"explanation":"洪武十三年朱元璋以谋逆罪处死丞相胡惟庸，借此废除丞相制度。"},{"id":1600,"type":"单选题","text":"推行\"一条鞭法\"改革的明代政治家是？","options":[{"key":"A","text":"张居正"},{"key":"B","text":"海瑞"},{"key":"C","text":"于谦"},{"key":"D","text":"严嵩"}],"answer":["A"],"explanation":"万历初年内阁首辅张居正推行一条鞭法，简化赋役征收。"},{"id":1601,"type":"单选题","text":"\"戊戌变法\"又被称为？","options":[{"key":"A","text":"洋务运动"},{"key":"B","text":"百日维新"},{"key":"C","text":"辛亥革命"},{"key":"D","text":"清末新政"}],"answer":["B"],"explanation":"1898年戊戌年间的变法仅维持103天即失败，故又称\"百日维新\"。"},{"id":1602,"type":"单选题","text":"自荐出使楚国的毛遂是谁的门客？","options":[{"key":"A","text":"平原君"},{"key":"B","text":"孟尝君"},{"key":"C","text":"信陵君"},{"key":"D","text":"春申君"}],"answer":["A"],"explanation":"毛遂自荐随平原君使楚，按剑定纵，赵国转危为安。"},{"id":1603,"type":"单选题","text":"\"指鹿为马\"的宦官（权臣）是？","options":[{"key":"A","text":"赵高"},{"key":"B","text":"嫪毐"},{"key":"C","text":"魏忠贤"},{"key":"D","text":"刘瑾"}],"answer":["A"],"explanation":"秦二世时权臣赵高指鹿为马，试探并威慑群臣。"},{"id":1604,"type":"单选题","text":"以\"养士三千\"著称、门客中有\"鸡鸣狗盗\"之徒的战国公子是？","options":[{"key":"A","text":"孟尝君"},{"key":"B","text":"平原君"},{"key":"C","text":"信陵君"},{"key":"D","text":"春申君"}],"answer":["A"],"explanation":"齐国的孟尝君田文养士数千，鸡鸣狗盗之徒各有所用。"},{"id":1605,"type":"单选题","text":"《孙子兵法》的作者是？","options":[{"key":"A","text":"孙膑"},{"key":"B","text":"孙武"},{"key":"C","text":"孙权"},{"key":"D","text":"孙思邈"}],"answer":["B"],"explanation":"春秋末期齐人孙武著《孙子兵法》十三篇，被尊为\"兵圣\"。"},{"id":1606,"type":"单选题","text":"\"兵者，国之大事，死生之地，存亡之道，不可不察也\"出自？","options":[{"key":"A","text":"《孙子兵法》"},{"key":"B","text":"《六韬》"},{"key":"C","text":"《孙膑兵法》"},{"key":"D","text":"《尉缭子》"}],"answer":["A"],"explanation":"这是《孙子兵法》开篇第一句，强调战争关乎国家存亡。"},{"id":1607,"type":"单选题","text":"\"田忌赛马\"中为田忌献策的军事家是？","options":[{"key":"A","text":"孙武"},{"key":"B","text":"孙膑"},{"key":"C","text":"吴起"},{"key":"D","text":"乐毅"}],"answer":["B"],"explanation":"孙膑以\"以下驷对上驷\"之策助田忌赛马取胜，后为齐国军师。"},{"id":1608,"type":"单选题","text":"\"围魏救赵\"中率齐军解赵国之围的军师是？","options":[{"key":"A","text":"孙膑"},{"key":"B","text":"孙武"},{"key":"C","text":"田忌"},{"key":"D","text":"邹忌"}],"answer":["A"],"explanation":"桂陵之战中孙膑攻魏都大梁以解邯郸之围，大败魏军。"},{"id":1609,"type":"单选题","text":"\"破釜沉舟\"的典故主人公是？","options":[{"key":"A","text":"项羽"},{"key":"B","text":"刘邦"},{"key":"C","text":"韩信"},{"key":"D","text":"英布"}],"answer":["A"],"explanation":"巨鹿之战中项羽砸锅沉船、以示决死，大破秦军主力。"},{"id":1610,"type":"单选题","text":"\"明修栈道，暗度陈仓\"与哪位军事家有关？","options":[{"key":"A","text":"韩信"},{"key":"B","text":"张良"},{"key":"C","text":"萧何"},{"key":"D","text":"樊哙"}],"answer":["A"],"explanation":"楚汉相争之初韩信明面上修复栈道，暗中率军从陈仓出兵，大败章邯。"},{"id":1611,"type":"单选题","text":"\"安史之乱\"中首先起兵叛乱的是？","options":[{"key":"A","text":"安禄山"},{"key":"B","text":"史思明"},{"key":"C","text":"郭子仪"},{"key":"D","text":"李光弼"}],"answer":["A"],"explanation":"755年范阳节度使安禄山起兵叛乱，史思明继之，史称\"安史之乱\"。"},{"id":1612,"type":"单选题","text":"明代东南沿海抗倭的名将是？","options":[{"key":"A","text":"戚继光"},{"key":"B","text":"袁崇焕"},{"key":"C","text":"郑成功"},{"key":"D","text":"史可法"}],"answer":["A"],"explanation":"戚继光组建\"戚家军\"，荡平东南沿海倭患。"},{"id":1613,"type":"单选题","text":"平定\"三藩之乱\"的清朝皇帝是？","options":[{"key":"A","text":"顺治"},{"key":"B","text":"康熙"},{"key":"C","text":"雍正"},{"key":"D","text":"乾隆"}],"answer":["B"],"explanation":"康熙帝历时八年平定吴三桂等三藩叛乱，巩固了统一。"},{"id":1614,"type":"单选题","text":"\"鸣金收兵\"的\"金\"指的是？","options":[{"key":"A","text":"黄金"},{"key":"B","text":"铜制的钲"},{"key":"C","text":"铜锣"},{"key":"D","text":"金铃"}],"answer":["B"],"explanation":"\"金\"指钲，一种铜制打击乐器，敲击钲表示收兵。"},{"id":1615,"type":"单选题","text":"秦始皇陵\"兵马俑\"的用途是？","options":[{"key":"A","text":"守卫陵园的陪葬军阵"},{"key":"B","text":"练兵模型"},{"key":"C","text":"商品"},{"key":"D","text":"贡品"}],"answer":["A"],"explanation":"兵马俑是秦始皇陵的陪葬坑，象征守卫地下王国的军队。"},{"id":1616,"type":"单选题","text":"主持修建都江堰的是？","options":[{"key":"A","text":"李冰父子"},{"key":"B","text":"西门豹"},{"key":"C","text":"郑国"},{"key":"D","text":"大禹"}],"answer":["A"],"explanation":"战国时期秦蜀郡守李冰父子主持修建都江堰。"},{"id":1617,"type":"单选题","text":"秦代沟通长江与珠江水系的人工运河是？","options":[{"key":"A","text":"灵渠"},{"key":"B","text":"邗沟"},{"key":"C","text":"鸿沟"},{"key":"D","text":"永济渠"}],"answer":["A"],"explanation":"秦为统一岭南开凿灵渠，沟通湘江与漓江，即长江与珠江水系。"},{"id":1618,"type":"单选题","text":"\"盐铁官营\"大力推行于？","options":[{"key":"A","text":"汉武帝时期"},{"key":"B","text":"秦始皇时期"},{"key":"C","text":"唐太宗时期"},{"key":"D","text":"宋太祖时期"}],"answer":["A"],"explanation":"汉武帝任用桑弘羊等推行盐铁官营，盐铁之利收归国家。"},{"id":1619,"type":"单选题","text":"宋代管理海外贸易的专门机构是？","options":[{"key":"A","text":"市舶司"},{"key":"B","text":"理藩院"},{"key":"C","text":"宣政院"},{"key":"D","text":"枢密院"}],"answer":["A"],"explanation":"宋在广州、泉州等地设市舶司，管理海外贸易、征收关税。"},{"id":1620,"type":"单选题","text":"徽商的主要发源地是？","options":[{"key":"A","text":"安徽徽州"},{"key":"B","text":"山西平遥"},{"key":"C","text":"浙江宁波"},{"key":"D","text":"广东潮汕"}],"answer":["A"],"explanation":"徽商兴起于安徽徽州一带，以盐、茶、木材和典当业闻名。"},{"id":1621,"type":"单选题","text":"《清明上河图》描绘的城市是？","options":[{"key":"A","text":"北宋东京汴梁"},{"key":"B","text":"唐代长安"},{"key":"C","text":"南宋临安"},{"key":"D","text":"明代北京"}],"answer":["A"],"explanation":"张择端《清明上河图》描绘了北宋都城汴梁（开封）的繁华景象。"},{"id":1622,"type":"单选题","text":"古代商铺挂\"幌子\"的作用是？","options":[{"key":"A","text":"招揽顾客、标识经营内容"},{"key":"B","text":"避邪驱鬼"},{"key":"C","text":"遮阳避雨"},{"key":"D","text":"标示官府许可"}],"answer":["A"],"explanation":"幌子是店铺门前悬挂的标志物，向路人标明经营内容以招揽生意。"},{"id":1623,"type":"单选题","text":"把圆周率精确推算到小数点后七位的南朝科学家是？","options":[{"key":"A","text":"祖冲之"},{"key":"B","text":"刘徽"},{"key":"C","text":"张衡"},{"key":"D","text":"沈括"}],"answer":["A"],"explanation":"祖冲之求得圆周率在3.1415926与3.1415927之间，保持世界纪录近千年。"},{"id":1624,"type":"单选题","text":"活字印刷术的发明者是？","options":[{"key":"A","text":"毕昇"},{"key":"B","text":"蔡伦"},{"key":"C","text":"王祯"},{"key":"D","text":"沈括"}],"answer":["A"],"explanation":"北宋毕昇发明胶泥活字印刷术，沈括《梦溪笔谈》有记载。"},{"id":1625,"type":"单选题","text":"《梦溪笔谈》的作者是？","options":[{"key":"A","text":"沈括"},{"key":"B","text":"苏轼"},{"key":"C","text":"徐光启"},{"key":"D","text":"宋应星"}],"answer":["A"],"explanation":"北宋沈括的《梦溪笔谈》被李约瑟誉为\"中国科学史上的坐标\"。"},{"id":1626,"type":"单选题","text":"元代编制《授时历》的科学家是？","options":[{"key":"A","text":"郭守敬"},{"key":"B","text":"一行"},{"key":"C","text":"祖冲之"},{"key":"D","text":"张衡"}],"answer":["A"],"explanation":"郭守敬等人编制的《授时历》是元代最精密的历法。"},{"id":1627,"type":"单选题","text":"我国现存最早的中医理论经典是？","options":[{"key":"A","text":"《黄帝内经》"},{"key":"B","text":"《伤寒杂病论》"},{"key":"C","text":"《神农本草经》"},{"key":"D","text":"《千金方》"}],"answer":["A"],"explanation":"《黄帝内经》系统阐述中医理论，是现存最早的中医理论经典。"},{"id":1628,"type":"单选题","text":"我国现存最早的药物学专著是？","options":[{"key":"A","text":"《神农本草经》"},{"key":"B","text":"《本草纲目》"},{"key":"C","text":"《唐本草》"},{"key":"D","text":"《千金方》"}],"answer":["A"],"explanation":"《神农本草经》成书于汉代，收药365种，是现存最早的药物学专著。"},{"id":1629,"type":"单选题","text":"\"望闻问切\"四诊法的奠定者是？","options":[{"key":"A","text":"扁鹊"},{"key":"B","text":"华佗"},{"key":"C","text":"张仲景"},{"key":"D","text":"李时珍"}],"answer":["A"],"explanation":"四诊法在战国名医扁鹊时代已具雏形，后世不断完善。"},{"id":1630,"type":"单选题","text":"发明\"麻沸散\"、施行外科手术的神医是？","options":[{"key":"A","text":"华佗"},{"key":"B","text":"扁鹊"},{"key":"C","text":"孙思邈"},{"key":"D","text":"葛洪"}],"answer":["A"],"explanation":"华佗用麻沸散麻醉后为病人施行剖腹手术，被尊为外科鼻祖。"},{"id":1631,"type":"单选题","text":"被后世尊为\"医圣\"的是？","options":[{"key":"A","text":"张仲景"},{"key":"B","text":"华佗"},{"key":"C","text":"孙思邈"},{"key":"D","text":"李时珍"}],"answer":["A"],"explanation":"东汉张仲景著《伤寒杂病论》，奠定辨证论治基础，被尊为\"医圣\"。"},{"id":1632,"type":"单选题","text":"著《千金方》、被尊为\"药王\"的唐代医学家是？","options":[{"key":"A","text":"孙思邈"},{"key":"B","text":"华佗"},{"key":"C","text":"扁鹊"},{"key":"D","text":"李时珍"}],"answer":["A"],"explanation":"孙思邈认为\"人命至重，有贵千金\"，其著作以\"千金\"命名，被尊为药王。"},{"id":1633,"type":"单选题","text":"战国时期在秦国关中地区修建的大型灌溉工程是？","options":[{"key":"A","text":"郑国渠"},{"key":"B","text":"都江堰"},{"key":"C","text":"灵渠"},{"key":"D","text":"芍陂"}],"answer":["A"],"explanation":"郑国渠由水工郑国主持修建，灌溉关中平原。"},{"id":1634,"type":"单选题","text":"儒家学派的创始人是？","options":[{"key":"A","text":"孔子"},{"key":"B","text":"孟子"},{"key":"C","text":"荀子"},{"key":"D","text":"老子"}],"answer":["A"],"explanation":"孔子开创私学、创立儒家学派，其学说成为两千多年传统文化的主干。"},{"id":1635,"type":"单选题","text":"先秦法家思想的集大成者是？","options":[{"key":"A","text":"韩非"},{"key":"B","text":"李斯"},{"key":"C","text":"商鞅"},{"key":"D","text":"申不害"}],"answer":["A"],"explanation":"韩非集法、术、势之大成，其思想为秦朝治国所用。"},{"id":1636,"type":"单选题","text":"道家学派的创始人是？","options":[{"key":"A","text":"老子"},{"key":"B","text":"庄子"},{"key":"C","text":"列子"},{"key":"D","text":"惠施"}],"answer":["A"],"explanation":"老子著《道德经》五千言，开创道家学派。"},{"id":1637,"type":"单选题","text":"《庄子》在唐代被尊称为？","options":[{"key":"A","text":"《南华经》"},{"key":"B","text":"《道德经》"},{"key":"C","text":"《冲虚经》"},{"key":"D","text":"《通玄经》"}],"answer":["A"],"explanation":"唐玄宗封庄子为\"南华真人\"，《庄子》遂称《南华经》。"},{"id":1638,"type":"单选题","text":"\"三教九流\"中的\"三教\"指的是？","options":[{"key":"A","text":"儒、释、道"},{"key":"B","text":"儒、道、法"},{"key":"C","text":"佛、道、回"},{"key":"D","text":"儒、墨、道"}],"answer":["A"],"explanation":"\"三教\"指儒教、佛教、道教，是传统文化中的三大思想体系。"},{"id":1639,"type":"单选题","text":"\"天行健，君子以自强不息\"出自？","options":[{"key":"A","text":"《周易》"},{"key":"B","text":"《论语》"},{"key":"C","text":"《老子》"},{"key":"D","text":"《孟子》"}],"answer":["A"],"explanation":"这是《周易》乾卦《象传》的名句，与\"厚德载物\"相对。"},{"id":1640,"type":"单选题","text":"明代创立\"心学\"、主张\"知行合一\"的思想家是？","options":[{"key":"A","text":"王阳明"},{"key":"B","text":"朱熹"},{"key":"C","text":"陆九渊"},{"key":"D","text":"李贽"}],"answer":["A"],"explanation":"王阳明集心学之大成，提出\"知行合一\"\"致良知\"。"},{"id":1641,"type":"单选题","text":"《周易》中\"经\"的部分包含？","options":[{"key":"A","text":"六十四卦的卦辞与爻辞"},{"key":"B","text":"\"十翼\""},{"key":"C","text":"《系辞》"},{"key":"D","text":"《序卦》"}],"answer":["A"],"explanation":"《周易》的\"经\"指六十四卦卦画及卦辞、爻辞；解释经文的《易传》称\"十翼\"。"},{"id":1642,"type":"单选题","text":"\"精卫填海\"的故事出自？","options":[{"key":"A","text":"《山海经》"},{"key":"B","text":"《淮南子》"},{"key":"C","text":"《穆天子传》"},{"key":"D","text":"《搜神记》"}],"answer":["A"],"explanation":"精卫填海见《山海经·北山经》，体现不屈不挠的精神。"},{"id":1643,"type":"单选题","text":"《诗经》主要的表现手法是？","options":[{"key":"A","text":"赋、比、兴"},{"key":"B","text":"风、雅、颂"},{"key":"C","text":"起、承、转、合"},{"key":"D","text":"抑、扬、顿、挫"}],"answer":["A"],"explanation":"赋、比、兴与风、雅、颂合称\"六义\"。"},{"id":1644,"type":"单选题","text":"\"路漫漫其修远兮，吾将上下而求索\"出自？","options":[{"key":"A","text":"《离骚》"},{"key":"B","text":"《九歌》"},{"key":"C","text":"《天问》"},{"key":"D","text":"《九章》"}],"answer":["A"],"explanation":"这是屈原《离骚》中的千古名句。"},{"id":1645,"type":"单选题","text":"投江自尽的屈原投的是？","options":[{"key":"A","text":"汨罗江"},{"key":"B","text":"湘江"},{"key":"C","text":"长江"},{"key":"D","text":"乌江"}],"answer":["A"],"explanation":"公元前278年秦军破郢，屈原自沉汨罗江殉国。"},{"id":1646,"type":"单选题","text":"与《孔雀东南飞》并称\"乐府双璧\"的是？","options":[{"key":"A","text":"《木兰诗》"},{"key":"B","text":"《陌上桑》"},{"key":"C","text":"《长恨歌》"},{"key":"D","text":"《琵琶行》"}],"answer":["A"],"explanation":"《孔雀东南飞》与北朝民歌《木兰诗》合称\"乐府双璧\"。"},{"id":1647,"type":"单选题","text":"\"问君能有几多愁，恰似一江春水向东流\"的作者是？","options":[{"key":"A","text":"李煜"},{"key":"B","text":"李清照"},{"key":"C","text":"柳永"},{"key":"D","text":"纳兰性德"}],"answer":["A"],"explanation":"南唐后主李煜亡国后写下《虞美人》，此为其绝笔名句。"},{"id":1648,"type":"单选题","text":"开豪放词风先河的北宋词人是？","options":[{"key":"A","text":"苏轼"},{"key":"B","text":"柳永"},{"key":"C","text":"秦观"},{"key":"D","text":"周邦彦"}],"answer":["A"],"explanation":"苏轼以诗为词，开创豪放词风，辛弃疾继之。"},{"id":1649,"type":"单选题","text":"\"寻寻觅觅，冷冷清清，凄凄惨惨戚戚\"的作者是？","options":[{"key":"A","text":"李清照"},{"key":"B","text":"朱淑真"},{"key":"C","text":"蔡文姬"},{"key":"D","text":"卓文君"}],"answer":["A"],"explanation":"这是李清照《声声慢》开篇的十四个叠字，为词史绝唱。"},{"id":1650,"type":"单选题","text":"《西厢记》的作者是？","options":[{"key":"A","text":"王实甫"},{"key":"B","text":"关汉卿"},{"key":"C","text":"汤显祖"},{"key":"D","text":"孔尚任"}],"answer":["A"],"explanation":"元代王实甫的《西厢记》被誉为\"天下夺魁\"之作。"},{"id":1651,"type":"单选题","text":"目前所见最早的成体系汉字是？","options":[{"key":"A","text":"甲骨文"},{"key":"B","text":"金文"},{"key":"C","text":"小篆"},{"key":"D","text":"隶书"}],"answer":["A"],"explanation":"甲骨文已是成熟的文字体系，具备象形、会意、形声等造字法。"},{"id":1652,"type":"单选题","text":"甲骨文被发现是在哪个朝代？","options":[{"key":"A","text":"清朝"},{"key":"B","text":"明朝"},{"key":"C","text":"元朝"},{"key":"D","text":"宋朝"}],"answer":["A"],"explanation":"1899年（清末）金石学家王懿荣首先从\"龙骨\"上鉴识出甲骨文。"},{"id":1653,"type":"单选题","text":"秦始皇\"书同文\"采用的标准字体是？","options":[{"key":"A","text":"小篆"},{"key":"B","text":"隶书"},{"key":"C","text":"楷书"},{"key":"D","text":"草书"}],"answer":["A"],"explanation":"秦统一后以丞相李斯整理的小篆为全国标准文字。"},{"id":1654,"type":"单选题","text":"《资治通鉴》的作者是？","options":[{"key":"A","text":"司马光"},{"key":"B","text":"司马迁"},{"key":"C","text":"欧阳修"},{"key":"D","text":"王安石"}],"answer":["A"],"explanation":"北宋司马光主持编纂《资治通鉴》，是一部编年体通史。"},{"id":1655,"type":"单选题","text":"世界上现存最早的有明确纪年的雕版印刷品是？","options":[{"key":"A","text":"唐咸通九年《金刚经》卷子"},{"key":"B","text":"明《永乐大典》"},{"key":"C","text":"宋版《资治通鉴》"},{"key":"D","text":"清《四库全书》"}],"answer":["A"],"explanation":"868年印制的《金刚经》卷子于敦煌发现，是现存最早的标有年代的雕版印刷品。"},{"id":1656,"type":"单选题","text":"改进造纸术、使纸得到推广使用的是？","options":[{"key":"A","text":"蔡伦"},{"key":"B","text":"毕昇"},{"key":"C","text":"张衡"},{"key":"D","text":"杜康"}],"answer":["A"],"explanation":"东汉蔡伦改进造纸术，用树皮、麻头等造纸，人称\"蔡侯纸\"。"},{"id":1657,"type":"单选题","text":"创办私学、打破\"学在官府\"局面的先贤是？","options":[{"key":"A","text":"孔子"},{"key":"B","text":"老子"},{"key":"C","text":"墨子"},{"key":"D","text":"孟子"}],"answer":["A"],"explanation":"孔子首开私人讲学之风，主张\"有教无类\"。"},{"id":1658,"type":"单选题","text":"\"学而时习之，不亦说乎\"出自？","options":[{"key":"A","text":"《论语》"},{"key":"B","text":"《孟子》"},{"key":"C","text":"《大学》"},{"key":"D","text":"《荀子》"}],"answer":["A"],"explanation":"这是《论语》开篇第一句。"},{"id":1659,"type":"单选题","text":"太学作为最高学府设立于？","options":[{"key":"A","text":"汉武帝时期"},{"key":"B","text":"秦始皇时期"},{"key":"C","text":"隋文帝时期"},{"key":"D","text":"唐太宗时期"}],"answer":["A"],"explanation":"汉武帝元朔五年设太学，置五经博士。"},{"id":1660,"type":"单选题","text":"科举制度正式废除于？","options":[{"key":"A","text":"1905年"},{"key":"B","text":"1911年"},{"key":"C","text":"1898年"},{"key":"D","text":"1912年"}],"answer":["A"],"explanation":"1905年清廷下诏停止科举，延续约1300年的科举制度终结。"},{"id":1661,"type":"单选题","text":"殿试一甲共录取几人？","options":[{"key":"A","text":"三人"},{"key":"B","text":"十人"},{"key":"C","text":"五十人"},{"key":"D","text":"百人"}],"answer":["A"],"explanation":"一甲仅三人：状元、榜眼、探花，赐进士及第。"},{"id":1662,"type":"单选题","text":"相传《百家姓》以\"赵\"姓开头是因为？","options":[{"key":"A","text":"\"赵\"是宋朝国姓"},{"key":"B","text":"按人口多少排序"},{"key":"C","text":"按笔画排序"},{"key":"D","text":"随机排列"}],"answer":["A"],"explanation":"《百家姓》成书于北宋初，首姓\"赵\"为宋朝皇帝之姓。"},{"id":1663,"type":"单选题","text":"《千字文》开篇的四个字是？","options":[{"key":"A","text":"天地玄黄"},{"key":"B","text":"人之初"},{"key":"C","text":"赵钱孙李"},{"key":"D","text":"大学之道"}],"answer":["A"],"explanation":"\"天地玄黄，宇宙洪荒\"是《千字文》的开篇。"},{"id":1664,"type":"单选题","text":"科举考试实行\"糊名\"（弥封）制度是为了？","options":[{"key":"A","text":"防止考官徇私舞弊"},{"key":"B","text":"节省纸张"},{"key":"C","text":"防止试卷受潮"},{"key":"D","text":"美观"}],"answer":["A"],"explanation":"糊名把考生姓名籍贯密封，使考官难以辨认，以示公平。"},{"id":1665,"type":"单选题","text":"\"蟾宫折桂\"比喻什么？","options":[{"key":"A","text":"科举及第"},{"key":"B","text":"隐居山林"},{"key":"C","text":"得道成仙"},{"key":"D","text":"长寿"}],"answer":["A"],"explanation":"古人以月宫折桂喻科举应试得中。"},{"id":1666,"type":"单选题","text":"\"颜筋柳骨\"中\"颜\"指的是哪位书法家？","options":[{"key":"A","text":"颜真卿"},{"key":"B","text":"颜之推"},{"key":"C","text":"颜回"},{"key":"D","text":"颜延之"}],"answer":["A"],"explanation":"颜真卿书法雄浑丰腴、筋力饱满，与柳公权的劲健并称\"颜筋柳骨\"。"},{"id":1667,"type":"单选题","text":"以狂草著称、人称\"张颠\"的唐代书法家是？","options":[{"key":"A","text":"张旭"},{"key":"B","text":"张芝"},{"key":"C","text":"怀素"},{"key":"D","text":"张怀瓘"}],"answer":["A"],"explanation":"张旭嗜酒，每大醉呼叫狂走而后落笔，人称\"张颠\"，与怀素并称\"颠张醉素\"。"},{"id":1668,"type":"单选题","text":"《千里江山图》的作者、年仅十八岁的北宋天才画家是？","options":[{"key":"A","text":"王希孟"},{"key":"B","text":"张择端"},{"key":"C","text":"范宽"},{"key":"D","text":"黄公望"}],"answer":["A"],"explanation":"王希孟得宋徽宗亲授，绘成近十二米长的青绿山水《千里江山图》。"},{"id":1669,"type":"单选题","text":"《富春山居图》的作者是？","options":[{"key":"A","text":"黄公望"},{"key":"B","text":"倪瓒"},{"key":"C","text":"吴镇"},{"key":"D","text":"王蒙"}],"answer":["A"],"explanation":"元代黄公望年近八十绘成《富春山居图》，为\"元四家\"之首的代表作。"},{"id":1670,"type":"单选题","text":"根据曹植《洛神赋》绘制《洛神赋图》的画家是？","options":[{"key":"A","text":"顾恺之"},{"key":"B","text":"吴道子"},{"key":"C","text":"阎立本"},{"key":"D","text":"周昉"}],"answer":["A"],"explanation":"东晋顾恺之以\"迁想妙得\"的笔法把洛神形象绘入画卷。"},{"id":1671,"type":"单选题","text":"\"徽墨\"产于？","options":[{"key":"A","text":"安徽徽州"},{"key":"B","text":"浙江湖州"},{"key":"C","text":"江西婺源"},{"key":"D","text":"广东肇庆"}],"answer":["A"],"explanation":"徽墨产于古徽州，以\"拈来轻、磨来清、嗅来馨\"著称。"},{"id":1672,"type":"单选题","text":"宣纸的主产地是？","options":[{"key":"A","text":"安徽泾县"},{"key":"B","text":"浙江富阳"},{"key":"C","text":"四川夹江"},{"key":"D","text":"河北迁安"}],"answer":["A"],"explanation":"宣纸因产于宣州泾县而得名，\"纸寿千年\"。"},{"id":1673,"type":"单选题","text":"端砚产于？","options":[{"key":"A","text":"广东肇庆"},{"key":"B","text":"安徽歙县"},{"key":"C","text":"甘肃卓尼"},{"key":"D","text":"山西绛州"}],"answer":["A"],"explanation":"端砚产于广东肇庆（古称端州），居四大名砚之首。"},{"id":1674,"type":"单选题","text":"传统古琴一般有多少根弦？","options":[{"key":"A","text":"七根"},{"key":"B","text":"五根"},{"key":"C","text":"十三根"},{"key":"D","text":"二十一弦"}],"answer":["A"],"explanation":"古琴又称七弦琴；二十一弦的是古筝。"},{"id":1675,"type":"单选题","text":"《霓裳羽衣曲》与哪位皇帝直接相关？","options":[{"key":"A","text":"唐玄宗"},{"key":"B","text":"唐太宗"},{"key":"C","text":"汉武帝"},{"key":"D","text":"宋徽宗"}],"answer":["A"],"explanation":"相传唐玄宗创制或改编了《霓裳羽衣曲》，杨贵妃善舞此曲。"},{"id":1676,"type":"单选题","text":"京剧的形成与哪一事件直接相关？","options":[{"key":"A","text":"徽班进京"},{"key":"B","text":"昆曲衰落"},{"key":"C","text":"元杂剧北移"},{"key":"D","text":"南戏北上"}],"answer":["A"],"explanation":"清乾隆末年起四大徽班陆续进京，与其他声腔融合形成京剧。"},{"id":1677,"type":"单选题","text":"相声讲究的\"四门功课\"是？","options":[{"key":"A","text":"说、学、逗、唱"},{"key":"B","text":"唱、念、做、打"},{"key":"C","text":"手、眼、身、法"},{"key":"D","text":"吹、拉、弹、唱"}],"answer":["A"],"explanation":"说学逗唱是相声演员的基本功；唱念做打是戏曲的四功。"},{"id":1678,"type":"单选题","text":"汉代的杂技、乐舞等表演统称为？","options":[{"key":"A","text":"百戏"},{"key":"B","text":"皮影戏"},{"key":"C","text":"傩戏"},{"key":"D","text":"参军戏"}],"answer":["A"],"explanation":"汉代把角抵、杂技、幻术等表演统称百戏。"},{"id":1679,"type":"单选题","text":"满汉全席形成并盛行于？","options":[{"key":"A","text":"清代"},{"key":"B","text":"明代"},{"key":"C","text":"元代"},{"key":"D","text":"民国"}],"answer":["A"],"explanation":"满汉全席是清代宫廷与官府宴席中满汉菜肴并陈的盛大筵席。"},{"id":1680,"type":"单选题","text":"北京传统民居的典型代表是？","options":[{"key":"A","text":"四合院"},{"key":"B","text":"土楼"},{"key":"C","text":"吊脚楼"},{"key":"D","text":"碉房"}],"answer":["A"],"explanation":"四合院由正房、厢房、倒座围合而成，是北方民居的典型。"},{"id":1681,"type":"单选题","text":"客家人聚居地区的典型民居是？","options":[{"key":"A","text":"土楼"},{"key":"B","text":"窑洞"},{"key":"C","text":"蒙古包"},{"key":"D","text":"干栏式竹楼"}],"answer":["A"],"explanation":"福建西南客家人为聚族防御而建土楼，圆形方楼蔚为壮观。"},{"id":1682,"type":"单选题","text":"古代杆秤一斤为十六两，成语\"半斤八两\"比喻？","options":[{"key":"A","text":"两者不相上下"},{"key":"B","text":"斤两不足"},{"key":"C","text":"交易公平"},{"key":"D","text":"缺斤短两"}],"answer":["A"],"explanation":"旧制十六两一斤，半斤即八两，比喻彼此一样、不相上下。"},{"id":1683,"type":"单选题","text":"中国象棋棋盘中间写着？","options":[{"key":"A","text":"楚河汉界"},{"key":"B","text":"泾渭分明"},{"key":"C","text":"井田阡陌"},{"key":"D","text":"鸿沟天堑"}],"answer":["A"],"explanation":"棋盘中央的\"楚河汉界\"源于楚汉以鸿沟为界的历史。"},{"id":1684,"type":"单选题","text":"风筝的古称是？","options":[{"key":"A","text":"纸鸢"},{"key":"B","text":"纸鹤"},{"key":"C","text":"飞鸢"},{"key":"D","text":"纸鹞"}],"answer":["A"],"explanation":"风筝古称纸鸢，五代时在鸢首装笛鸣声如筝，始称风筝。"},{"id":1685,"type":"单选题","text":"筷子在古代称为？","options":[{"key":"A","text":"箸"},{"key":"B","text":"匕"},{"key":"C","text":"觞"},{"key":"D","text":"俎"}],"answer":["A"],"explanation":"筷子古称\"箸\"，因行船人忌\"住\"而改称\"快（筷）\"。"},{"id":1686,"type":"单选题","text":"传统木构建筑中支撑出挑屋檐的构件是？","options":[{"key":"A","text":"斗拱"},{"key":"B","text":"榫卯"},{"key":"C","text":"藻井"},{"key":"D","text":"门钉"}],"answer":["A"],"explanation":"斗拱位于柱顶与屋檐之间，承托屋檐荷载，兼具装饰作用。"},{"id":1687,"type":"单选题","text":"\"天子驾六\"意思是周天子出行时用？","options":[{"key":"A","text":"六匹马拉的车"},{"key":"B","text":"六辆车"},{"key":"C","text":"六人抬轿"},{"key":"D","text":"六色仪仗"}],"answer":["A"],"explanation":"古礼天子之车驾六马，诸侯驾四，大夫驾三。"},{"id":1688,"type":"单选题","text":"川菜最突出的味型特点是？","options":[{"key":"A","text":"麻辣"},{"key":"B","text":"清淡"},{"key":"C","text":"酸甜"},{"key":"D","text":"咸鲜"}],"answer":["A"],"explanation":"川菜以麻辣著称，善用辣椒、花椒调味。"},{"id":1689,"type":"单选题","text":"北京著名老字号\"六必居\"经营的是？","options":[{"key":"A","text":"酱菜"},{"key":"B","text":"烤鸭"},{"key":"C","text":"布匹"},{"key":"D","text":"茶叶"}],"answer":["A"],"explanation":"六必居以酱菜闻名，相传创于明代。"},{"id":1690,"type":"单选题","text":"春节在古代曾被称为？","options":[{"key":"A","text":"元旦"},{"key":"B","text":"清明"},{"key":"C","text":"冬至"},{"key":"D","text":"上元"}],"answer":["A"],"explanation":"农历正月初一古称元旦、元日，1912年后元旦改指公历1月1日。"},{"id":1691,"type":"单选题","text":"压岁钱传说中\"祟\"是什么？","options":[{"key":"A","text":"作祟害人的小妖"},{"key":"B","text":"年兽"},{"key":"C","text":"瘟神"},{"key":"D","text":"鬼王"}],"answer":["A"],"explanation":"传说\"祟\"除夕摸小儿头致其生病，人们以铜钱压祟，称\"压祟钱\"，后讹为压岁钱。"},{"id":1692,"type":"单选题","text":"传统门神画像中最常见的一对武将是？","options":[{"key":"A","text":"秦叔宝与尉迟恭"},{"key":"B","text":"关羽与张飞"},{"key":"C","text":"岳飞与韩世忠"},{"key":"D","text":"秦琼与罗成"}],"answer":["A"],"explanation":"唐太宗命秦叔宝、尉迟恭守门驱邪，二人遂成为最流行的门神。"},{"id":1693,"type":"单选题","text":"元宵节的主要习俗是？","options":[{"key":"A","text":"赏灯、吃元宵"},{"key":"B","text":"登高、饮酒"},{"key":"C","text":"乞巧、拜月"},{"key":"D","text":"扫墓、踏青"}],"answer":["A"],"explanation":"正月十五元宵节张灯结彩，吃元宵（汤圆）寓意团圆。"},{"id":1694,"type":"单选题","text":"\"只许州官放火，不许百姓点灯\"的典故与哪个节日的放灯习俗有关？","options":[{"key":"A","text":"元宵节"},{"key":"B","text":"除夕"},{"key":"C","text":"重阳节"},{"key":"D","text":"中秋节"}],"answer":["A"],"explanation":"宋代州官田登忌讳\"灯\"字，元宵放灯令下百姓只好称\"放火\"，遂成此语。"},{"id":1695,"type":"单选题","text":"七夕节又被称为？","options":[{"key":"A","text":"乞巧节"},{"key":"B","text":"中元节"},{"key":"C","text":"下元节"},{"key":"D","text":"上巳节"}],"answer":["A"],"explanation":"七夕之夜女子向织女乞求巧艺，故称乞巧节。"},{"id":1696,"type":"单选题","text":"中秋节是农历的？","options":[{"key":"A","text":"八月十五"},{"key":"B","text":"九月初九"},{"key":"C","text":"七月初七"},{"key":"D","text":"正月十五"}],"answer":["A"],"explanation":"农历八月十五恰在秋季正中，故名中秋。"},{"id":1697,"type":"单选题","text":"民间\"数九寒天\"从哪一天开始数起？","options":[{"key":"A","text":"冬至"},{"key":"B","text":"立冬"},{"key":"C","text":"大寒"},{"key":"D","text":"腊八"}],"answer":["A"],"explanation":"从冬至起每九天为一九，数满九九八十一天，寒冬过去。"},{"id":1698,"type":"单选题","text":"腊八节喝腊八粥的习俗与哪一宗教有关？","options":[{"key":"A","text":"佛教"},{"key":"B","text":"道教"},{"key":"C","text":"伊斯兰教"},{"key":"D","text":"儒教"}],"answer":["A"],"explanation":"腊月初八相传为佛祖释迦牟尼成道日，佛寺施粥，民间遂有喝腊八粥之俗。"},{"id":1699,"type":"单选题","text":"祭灶的日期（腊月二十三或二十四）俗称？","options":[{"key":"A","text":"小年"},{"key":"B","text":"大年"},{"key":"C","text":"元宵"},{"key":"D","text":"上元"}],"answer":["A"],"explanation":"祭灶日是春节前的重要节点，民间称小年。"},{"id":1700,"type":"单选题","text":"十二生肖中排在首位的是？","options":[{"key":"A","text":"鼠"},{"key":"B","text":"牛"},{"key":"C","text":"虎"},{"key":"D","text":"龙"}],"answer":["A"],"explanation":"十二生肖与十二地支相配，鼠配子位居第一。"},{"id":1701,"type":"单选题","text":"除夕夜通宵不睡迎接新年叫？","options":[{"key":"A","text":"守岁"},{"key":"B","text":"踩岁"},{"key":"C","text":"压岁"},{"key":"D","text":"拜岁"}],"answer":["A"],"explanation":"除夕终夜不眠以待天明称守岁，寓意辞旧迎新。"},{"id":1702,"type":"单选题","text":"一年中最炎热的节气是？","options":[{"key":"A","text":"大暑"},{"key":"B","text":"小暑"},{"key":"C","text":"立秋"},{"key":"D","text":"夏至"}],"answer":["A"],"explanation":"大暑在夏至之后，是全年最热的节气。"},{"id":1703,"type":"单选题","text":"\"五岳\"之首是？","options":[{"key":"A","text":"泰山"},{"key":"B","text":"华山"},{"key":"C","text":"嵩山"},{"key":"D","text":"恒山"}],"answer":["A"],"explanation":"东岳泰山为五岳之首，历代帝王多往封禅。"},{"id":1704,"type":"单选题","text":"景泰蓝的正式工艺名称是？","options":[{"key":"A","text":"铜胎掐丝珐琅"},{"key":"B","text":"鎏金"},{"key":"C","text":"錾刻"},{"key":"D","text":"珐琅彩瓷"}],"answer":["A"],"explanation":"景泰蓝以铜作胎、掐丝填珐琅釉烧成，因明代景泰年间盛行而得名。"},{"id":1705,"type":"单选题","text":"唐三彩主要用于？","options":[{"key":"A","text":"随葬的明器"},{"key":"B","text":"日用餐具"},{"key":"C","text":"建筑琉璃"},{"key":"D","text":"货币"}],"answer":["A"],"explanation":"唐三彩以黄绿白三色为主，多为随葬明器。"},{"id":1706,"type":"单选题","text":"北宋\"交子\"之后，南宋主要流通的纸币是？","options":[{"key":"A","text":"会子"},{"key":"B","text":"宝钞"},{"key":"C","text":"飞钱"},{"key":"D","text":"铜钱券"}],"answer":["A"],"explanation":"南宋发行会子，是继交子之后的主要纸币。"},{"id":1707,"type":"单选题","text":"古代\"流放\"之刑是把犯人发配到？","options":[{"key":"A","text":"边远地区"},{"key":"B","text":"京城"},{"key":"C","text":"家乡"},{"key":"D","text":"军营"}],"answer":["A"],"explanation":"流刑将罪犯放逐到边远荒僻之地服劳役，是重于徒刑的刑罚。"},{"id":1708,"type":"单选题","text":"中国古代\"墨、劓、剕、宫、大辟\"合称？","options":[{"key":"A","text":"上古五刑"},{"key":"B","text":"五常"},{"key":"C","text":"五礼"},{"key":"D","text":"五服"}],"answer":["A"],"explanation":"这是上古时期的五种主要刑罚：墨（刺面）、劓（割鼻）、剕（断足）、宫、大辟（死刑）。"},{"id":1709,"type":"单选题","text":"战国时期各国变法中最彻底、影响最大的是？","options":[{"key":"A","text":"商鞅变法"},{"key":"B","text":"李悝变法"},{"key":"C","text":"吴起变法"},{"key":"D","text":"申不害改革"}],"answer":["A"],"explanation":"商鞅两次变法使秦国富强，为统一六国奠定基础。"},{"id":1710,"type":"单选题","text":"\"围魏救赵\"发生在齐魏之间的哪次战役中？","options":[{"key":"A","text":"桂陵之战"},{"key":"B","text":"马陵之战"},{"key":"C","text":"长平之战"},{"key":"D","text":"城濮之战"}],"answer":["A"],"explanation":"公元前354年齐军在桂陵设伏大败魏军，史称桂陵之战。"},{"id":1711,"type":"单选题","text":"\"风声鹤唳、草木皆兵\"的典故出自哪次战役？","options":[{"key":"A","text":"淝水之战"},{"key":"B","text":"赤壁之战"},{"key":"C","text":"官渡之战"},{"key":"D","text":"夷陵之战"}],"answer":["A"],"explanation":"前秦苻坚攻晋败于淝水，见八公山上草木皆以为晋兵，闻风声鹤唳而溃逃。"},{"id":1712,"type":"单选题","text":"\"东山再起\"说的是东晋哪位名士？","options":[{"key":"A","text":"谢安"},{"key":"B","text":"王导"},{"key":"C","text":"桓温"},{"key":"D","text":"祖逖"}],"answer":["A"],"explanation":"谢安隐居东山，年四十余复出执政，指挥淝水之战，人称\"东山再起\"。"},{"id":1713,"type":"单选题","text":"\"画龙点睛\"的传说与哪位画家有关？","options":[{"key":"A","text":"张僧繇"},{"key":"B","text":"顾恺之"},{"key":"C","text":"吴道子"},{"key":"D","text":"曹不兴"}],"answer":["A"],"explanation":"相传南朝张僧繇画龙不点睛，点睛之龙破壁飞去。"},{"id":1714,"type":"单选题","text":"\"东施效颦\"中的\"颦\"指的是？","options":[{"key":"A","text":"皱眉"},{"key":"B","text":"跳舞"},{"key":"C","text":"唱歌"},{"key":"D","text":"抚琴"}],"answer":["A"],"explanation":"西施因心口疼而皱眉，东施模仿反而更丑，\"颦\"即皱眉。"},{"id":1715,"type":"单选题","text":"\"高山流水\"最初的含义是？","options":[{"key":"A","text":"知音难遇"},{"key":"B","text":"风景优美"},{"key":"C","text":"琴艺高超"},{"key":"D","text":"水势浩大"}],"answer":["A"],"explanation":"钟子期死后，伯牙痛失知音，终身不复鼓琴，\"高山流水\"遂喻知音难觅。"},{"id":1716,"type":"单选题","text":"\"老骥伏枥，志在千里\"的作者是？","options":[{"key":"A","text":"曹操"},{"key":"B","text":"曹丕"},{"key":"C","text":"曹植"},{"key":"D","text":"刘备"}],"answer":["A"],"explanation":"此句出自曹操《龟虽寿》，抒写老当益壮的胸怀。"},{"id":1717,"type":"单选题","text":"\"三顾茅庐\"发生在哪个季节？","options":[{"key":"A","text":"冬季"},{"key":"B","text":"春季"},{"key":"C","text":"夏季"},{"key":"D","text":"秋季"}],"answer":["A"],"explanation":"《出师表》自述\"三顾臣于草庐之中\"，演义中描绘为隆冬时节冒雪拜访。"},{"id":1718,"type":"单选题","text":"\"不入虎穴，焉得虎子\"的典故与东汉哪位人物有关？","options":[{"key":"A","text":"班超"},{"key":"B","text":"张骞"},{"key":"C","text":"苏武"},{"key":"D","text":"甘英"}],"answer":["A"],"explanation":"班超出使西域，夜袭匈奴使团时以此语激励部下。"},{"id":1719,"type":"单选题","text":"\"囊萤\"\"映雪\"分别指哪两位苦学者的故事？","options":[{"key":"A","text":"车胤、孙康"},{"key":"B","text":"匡衡、车胤"},{"key":"C","text":"孙康、朱买臣"},{"key":"D","text":"苏秦、孙敬"}],"answer":["A"],"explanation":"晋代车胤夏日捕萤火虫照书，孙康冬夜借雪光读书。"},{"id":1720,"type":"单选题","text":"\"断机教子\"讲的也是哪位母亲的故事？","options":[{"key":"A","text":"孟母"},{"key":"B","text":"岳母"},{"key":"C","text":"陶母"},{"key":"D","text":"欧母"}],"answer":["A"],"explanation":"孟子逃学回家，孟母剪断织机上的布匹以喻学业中断，警醒儿子。"},{"id":1721,"type":"单选题","text":"\"曾子杀猪\"的故事体现了什么美德？","options":[{"key":"A","text":"言而有信"},{"key":"B","text":"勤俭节约"},{"key":"C","text":"尊老爱幼"},{"key":"D","text":"刻苦学习"}],"answer":["A"],"explanation":"曾子为兑现哄孩子的许诺真的杀猪，示范了言而有信。"},{"id":1722,"type":"单选题","text":"\"二十四孝\"中\"卧冰求鲤\"的主人公是？","options":[{"key":"A","text":"王祥"},{"key":"B","text":"黄香"},{"key":"C","text":"孟宗"},{"key":"D","text":"闵损"}],"answer":["A"],"explanation":"晋人王祥卧冰求鲤奉继母，为二十四孝故事之一。"},{"id":1723,"type":"单选题","text":"\"黄香温席\"讲的是哪类美德？","options":[{"key":"A","text":"孝敬父母"},{"key":"B","text":"勤奋好学"},{"key":"C","text":"诚实守信"},{"key":"D","text":"团结友爱"}],"answer":["A"],"explanation":"东汉黄香九岁即夏天扇枕、冬天以身体温暖被褥，事父至孝。"},{"id":1724,"type":"单选题","text":"\"孔融让梨\"体现的传统美德是？","options":[{"key":"A","text":"谦让"},{"key":"B","text":"诚信"},{"key":"C","text":"孝敬"},{"key":"D","text":"勤劳"}],"answer":["A"],"explanation":"孔融分梨自取其小，把大梨让给兄长，体现谦让美德。"},{"id":1725,"type":"单选题","text":"\"管宁割席\"的故事表达了对什么的态度？","options":[{"key":"A","text":"择友"},{"key":"B","text":"孝亲"},{"key":"C","text":"诚信"},{"key":"D","text":"勤学"}],"answer":["A"],"explanation":"管宁因华歆慕富贵而割席分坐，表示志趣不合、不愿为友。"},{"id":1726,"type":"单选题","text":"\"三过家门而不入\"说的是？","options":[{"key":"A","text":"大禹治水"},{"key":"B","text":"李冰治水"},{"key":"C","text":"西门豹治邺"},{"key":"D","text":"郑国修渠"}],"answer":["A"],"explanation":"大禹治水十三年，三次经过自家门口都没有进去。"},{"id":1727,"type":"单选题","text":"\"神医\"扁鹊的原名是？","options":[{"key":"A","text":"秦越人"},{"key":"B","text":"秦鸣鹤"},{"key":"C","text":"秦观"},{"key":"D","text":"仓公"}],"answer":["A"],"explanation":"扁鹊本名秦越人，因医术如上古神医扁鹊而得名。"},{"id":1728,"type":"单选题","text":"宋代发行的世界上最早纸币\"交子\"最初由谁发行？","options":[{"key":"A","text":"成都的商户"},{"key":"B","text":"朝廷太府"},{"key":"C","text":"钱庄"},{"key":"D","text":"镖局"}],"answer":["A"],"explanation":"交子最初由四川成都的十六家富商联合发行，后收归官办。"},{"id":1729,"type":"单选题","text":"\"洋务运动\"中创办的第一个大型近代军用企业是？","options":[{"key":"A","text":"江南制造总局"},{"key":"B","text":"福州船政局"},{"key":"C","text":"汉阳铁厂"},{"key":"D","text":"轮船招商局"}],"answer":["A"],"explanation":"1865年曾国藩、李鸿章创办江南制造总局，是洋务派最大的军工企业。"},{"id":1730,"type":"单选题","text":"主持修建赵州桥的隋代工匠是？","options":[{"key":"A","text":"李春"},{"key":"B","text":"鲁班"},{"key":"C","text":"喻皓"},{"key":"D","text":"样式雷"}],"answer":["A"],"explanation":"隋代匠师李春设计建造的赵州桥是世界现存最古老的敞肩石拱桥。"},{"id":1731,"type":"单选题","text":"《周髀算经》中记载的\"勾三股四弦五\"是关于什么的？","options":[{"key":"A","text":"勾股定理"},{"key":"B","text":"圆周率"},{"key":"C","text":"开平方"},{"key":"D","text":"方程求解"}],"answer":["A"],"explanation":"这是勾股定理的特例表述，早于西方毕达哥拉斯定理的记载。"},{"id":1732,"type":"单选题","text":"被誉为\"东方医药巨典\"的著作是？","options":[{"key":"A","text":"《本草纲目》"},{"key":"B","text":"《黄帝内经》"},{"key":"C","text":"《千金方》"},{"key":"D","text":"《伤寒论》"}],"answer":["A"],"explanation":"《本草纲目》被英国学者李约瑟誉为\"东方医药巨典\"。"},{"id":1733,"type":"单选题","text":"宋代瓷都景德镇在哪个朝代开始以皇帝年号命名？","options":[{"key":"A","text":"宋真宗景德年间"},{"key":"B","text":"宋徽宗时期"},{"key":"C","text":"元代"},{"key":"D","text":"明代"}],"answer":["A"],"explanation":"宋真宗景德年间该地所产青白瓷进御，遂以景德年号名镇。"},{"id":1734,"type":"单选题","text":"明代郑和下西洋的宝船队最远到达？","options":[{"key":"A","text":"非洲东海岸和红海沿岸"},{"key":"B","text":"美洲"},{"key":"C","text":"欧洲"},{"key":"D","text":"澳大利亚"}],"answer":["A"],"explanation":"郑和七下西洋最远到达非洲东海岸和红海沿岸。"},{"id":1735,"type":"单选题","text":"清代的\"文字狱\"在哪个皇帝在位时最盛行？","options":[{"key":"A","text":"康熙、雍正、乾隆"},{"key":"B","text":"顺治"},{"key":"C","text":"嘉庆"},{"key":"D","text":"道光"}],"answer":["A"],"explanation":"康雍乾三朝文字狱最盛，文人因诗文获罪者众多。"},{"id":1736,"type":"单选题","text":"\"改土归流\"是哪个朝代推行的边疆政策？","options":[{"key":"A","text":"清代"},{"key":"B","text":"唐代"},{"key":"C","text":"汉代"},{"key":"D","text":"元代"}],"answer":["A"],"explanation":"清雍正年间在西南地区废除土司制度、改设流官，称\"改土归流\"。"},{"id":1737,"type":"单选题","text":"古代官员上朝时手中所持的狭长板子称为？","options":[{"key":"A","text":"笏板"},{"key":"B","text":"令牌"},{"key":"C","text":"惊堂木"},{"key":"D","text":"如意"}],"answer":["A"],"explanation":"笏板是大臣朝见天子时用来记事的手板。"},{"id":1738,"type":"单选题","text":"古代\"击鼓鸣冤\"的鼓称为？","options":[{"key":"A","text":"登闻鼓"},{"key":"B","text":"更鼓"},{"key":"C","text":"战鼓"},{"key":"D","text":"堂鼓"}],"answer":["A"],"explanation":"衙门外设登闻鼓，百姓可击鼓鸣冤直诉于上。"},{"id":1739,"type":"单选题","text":"科举时代把考中进士比作\"登龙门\"，\"龙门\"的传说与哪条河流有关？","options":[{"key":"A","text":"黄河"},{"key":"B","text":"长江"},{"key":"C","text":"淮河"},{"key":"D","text":"洛水"}],"answer":["A"],"explanation":"传说黄河鲤鱼跳过龙门即化为龙，故以登龙门喻飞黄腾达。"},{"id":1740,"type":"单选题","text":"\"十年寒窗无人问，一举成名天下知\"形容的是？","options":[{"key":"A","text":"科举及第"},{"key":"B","text":"从军立功"},{"key":"C","text":"经商致富"},{"key":"D","text":"隐居修行"}],"answer":["A"],"explanation":"元代高明《琵琶记》名句，写尽科举士人的境遇反差。"},{"id":1741,"type":"单选题","text":"古人用\"桑梓\"代指什么？","options":[{"key":"A","text":"家乡"},{"key":"B","text":"朝廷"},{"key":"C","text":"学堂"},{"key":"D","text":"坟墓"}],"answer":["A"],"explanation":"桑与梓为古人宅旁常栽之树，故以\"桑梓\"代指家乡。"},{"id":1742,"type":"单选题","text":"古人以\"社\"祭祀土地神，秋季祭祀土地神的节日叫？","options":[{"key":"A","text":"秋社"},{"key":"B","text":"春社"},{"key":"C","text":"腊祭"},{"key":"D","text":"伏祭"}],"answer":["A"],"explanation":"立春后第五个戊日为春社祭土地祈丰收，立秋后第五个戊日为秋社酬神。"},{"id":1743,"type":"单选题","text":"古人把春节前的大扫除称为？","options":[{"key":"A","text":"扫尘（掸尘）"},{"key":"B","text":"扫墓"},{"key":"C","text":"扫房"},{"key":"D","text":"洗尘"}],"answer":["A"],"explanation":"腊月二十四掸尘扫房子，\"尘\"与\"陈\"谐音，寓意除旧布新。"},{"id":1744,"type":"单选题","text":"\"嫁女要选好日子\"，古代择吉婚嫁最看重的书籍是？","options":[{"key":"A","text":"黄历（历书）"},{"key":"B","text":"诗经"},{"key":"C","text":"族谱"},{"key":"D","text":"家训"}],"answer":["A"],"explanation":"黄历上标注每日宜忌，是古人婚丧嫁娶择日的依据。"},{"id":1745,"type":"单选题","text":"端午节在古人眼中最初是一个什么性质的节日？","options":[{"key":"A","text":"祛病防疫的\"恶月恶日\""},{"key":"B","text":"欢庆丰收"},{"key":"C","text":"祭祀祖先"},{"key":"D","text":"祈福姻缘"}],"answer":["A"],"explanation":"五月仲夏疫病易发，古人视五月为\"恶月\"，端午的习俗多与驱邪防疫有关。"},{"id":1746,"type":"单选题","text":"重阳节又称\"登高节\"，还被称为？","options":[{"key":"A","text":"老人节（今义）与菊花节"},{"key":"B","text":"团圆节"},{"key":"C","text":"乞巧节"},{"key":"D","text":"寒食节"}],"answer":["A"],"explanation":"九九重阳音同\"久久\"，今又定为老年节；古人重阳赏菊饮菊花酒。"},{"id":1747,"type":"多选题","text":"2006年5月，经国务院批准，被列入第一批国家级非物质文化遗产名录的民俗节日有：____、七夕节、重阳节等。","options":[{"key":"A","text":"春节"},{"key":"B","text":"清明节"},{"key":"C","text":"端午节"},{"key":"D","text":"中秋节"}],"answer":["A","B","C","D"],"explanation":"2006年5月，经国务院批准，被列入第一批国家级非物质文化遗产名录的民俗节日有：春节、清明节、端午节、中秋节、七夕节、重阳节等。"},{"id":1748,"type":"多选题","text":"唐朝是我国饮茶历史上的鼎盛时期，流行于唐朝的饮茶方式有____。","options":[{"key":"A","text":"煎茶"},{"key":"B","text":"庵茶"},{"key":"C","text":"点茶"},{"key":"D","text":"煮茶"}],"answer":["A","B","D"],"explanation":"宋代流行点茶。"},{"id":1749,"type":"多选题","text":"下列关于京杭大运河的说法中正确的有____。","options":[{"key":"A","text":"是古代南北水陆交通的重要通道"},{"key":"B","text":"肇始于秦汉，形成于隋代，发展于唐宋"},{"key":"C","text":"沟通海河、黄河、淮河、长江、钱塘江五大水系"},{"key":"D","text":"是世界上最长的人工运河"}],"answer":["A","C","D"],"explanation":"B项应为肇始于春秋。"},{"id":1750,"type":"多选题","text":"几千年来，中国人制造陶瓷，使用陶瓷，陶瓷文化已经融入中国人生活的方方面面。下列选项中，不属于陶瓷的有____。","options":[{"key":"A","text":"四羊方尊"},{"key":"B","text":"莲鹤方壶"},{"key":"C","text":"后母戊鼎"},{"key":"D","text":"三彩胡人背猴骑俑"}],"answer":["A","B","C"],"explanation":"ABC项都属于青铜器。"},{"id":1751,"type":"多选题","text":"我国古代为活字印刷术发展做出重大贡献的人物有____。","options":[{"key":"A","text":"毕昇"},{"key":"B","text":"周必大"},{"key":"C","text":"祖冲之"},{"key":"D","text":"王祯"}],"answer":["A","B","D"],"explanation":"C项祖冲之的主要成就是数学和天文学方面。"},{"id":1752,"type":"多选题","text":"中国地形多样，人们因地制宜，建造出适合自己的房屋,组成了丰富多彩的中式民居。以下地区与住房搭配正确的有____。","options":[{"key":"A","text":"北京--四合院"},{"key":"B","text":"内蒙古--窑洞"},{"key":"C","text":"山西--大院"},{"key":"D","text":"福建--土楼"}],"answer":["A","C","D"],"explanation":"B项窑洞主要分布于黄土高原上，是当地居民的传统居住场所。"},{"id":1753,"type":"多选题","text":"泰山的每一处都蕴含着悠久的历史和丰富的文化。以下位于泰山的古建筑有____。","options":[{"key":"A","text":"王母池"},{"key":"B","text":"万仙楼"},{"key":"C","text":"百尺峡"},{"key":"D","text":"碧霞祠"}],"answer":["A","B","D"],"explanation":"“百尺峡”也叫“百丈崖”，是华山的险境之一。"},{"id":1754,"type":"多选题","text":"自古以来，黄河常常是诗人吟咏的对象。下列关于黄河的诗句与其作者对应正确的有____。","options":[{"key":"A","text":"黄河之水天上来，奔流到海不复回--李白"},{"key":"B","text":"九曲黄河万里沙，浪淘风簸自天涯--刘禹锡"},{"key":"C","text":"黄河落天走东海。万里写人胸怀间--王维"},{"key":"D","text":"白日依山尽，黄河人海流--王之涣"}],"answer":["A","B","D"],"explanation":"黄河落天走东海，万里写入胸怀间出自李白的《赠裴十四》。"},{"id":1755,"type":"多选题","text":"北岳恒山的悬空寺称得上是天下独绝，寺中同时供奉着佛、道、儒三家的始祖,他们分别是____。","options":[{"key":"A","text":"释迦牟尼"},{"key":"B","text":"老子"},{"key":"C","text":"孔子"},{"key":"D","text":"孟子"}],"answer":["A","B","C"],"explanation":"孔子是儒家学派的始祖，孟子为孔子第四代弟子，发扬和继承了儒家学说，被尊称为亚圣。"},{"id":1756,"type":"多选题","text":"益者三友是____。","options":[{"key":"A","text":"友直"},{"key":"B","text":"友善柔"},{"key":"C","text":"友多闻"},{"key":"D","text":"友谅"}],"answer":["A","C","D"],"explanation":"益者三友指友直，友谅，友多闻的朋友（友直是指正直的朋友，友谅是指诚信（谅，诚信）的朋友，友多闻是指见闻广博的朋友）。"},{"id":1757,"type":"多选题","text":"西湖是中国著名的风景区，有着浓厚的历史文化气息，下列选项中属于西湖古时旧称的有____。","options":[{"key":"A","text":"上湖"},{"key":"B","text":"钱塘湖"},{"key":"C","text":"西子湖"},{"key":"D","text":"重湖"}],"answer":["A","B","C"],"explanation":"重湖是洞庭湖的旧称。"},{"id":1758,"type":"多选题","text":"彝族刺绣历史悠久，颜色以____为主。","options":[{"key":"A","text":"黑、白"},{"key":"B","text":"红、黄"},{"key":"C","text":"绿、蓝"},{"key":"D","text":"粉、紫"}],"answer":["A","B","C"],"explanation":"彝族刺绣的颜色主要以黑、白、红、黄、绿、蓝为主。每种不同的颜色均有着不同的含义。"},{"id":1759,"type":"多选题","text":"玉在我国古代具有十分深刻的寓意和文化内涵，人们认为玉拥有美好品质有____。","options":[{"key":"A","text":"仁"},{"key":"B","text":"利"},{"key":"C","text":"智"},{"key":"D","text":"洁"}],"answer":["A","C","D"],"explanation":"在《管子·水地》中，管仲认为玉有九种美德，分别为“仁、知、义、行、洁、勇、精、容、辞”。"},{"id":1760,"type":"多选题","text":"象脚鼓的用料十分讲究，鼓身木料选用___，这样不容易开裂损坏","options":[{"key":"A","text":"橡胶树"},{"key":"B","text":"攀枝花树"},{"key":"C","text":"椰子树"},{"key":"D","text":"芒果树"}],"answer":["B","D"],"explanation":"象脚鼓是是傣族古老的民族乐器，通常以当地盛产的攀枝花树和芒果树制成。"},{"id":1761,"type":"多选题","text":"东巴文化是云南纳西族先民馈赠给后人一份不菲的艺术遗产，下列选项哪些是东巴画的主要分类?","options":[{"key":"A","text":"木牌画"},{"key":"B","text":"经书绘画"},{"key":"C","text":"纸牌画"},{"key":"D","text":"卷轴画"}],"answer":["A","B","C","D"],"explanation":"东巴是纳西族对传统宗教神职人员的称呼，东巴在做宗教活动仪式时绘制的各种各样的佛神、人物、动物、植物以及妖魔鬼怪的形象被成为东巴画，主要有经卷图画、木牌画、纸牌画和卷轴画等形式。"},{"id":1762,"type":"多选题","text":"下列选项中属于怒江傈僳族自治州独特技艺的有____。","options":[{"key":"A","text":"“上刀山，下火海”技艺"},{"key":"B","text":"起奔乐器制作技艺"},{"key":"C","text":"柳溪竹雕制作技艺"},{"key":"D","text":"独龙族竹编技艺"}],"answer":["A","B","D"],"explanation":"柳溪竹雕制作技艺是云南省昭通市彝良县的·竹雕技艺。"},{"id":1763,"type":"多选题","text":"战国时期著名的思想家韩非在《韩非子》中提出____、____、____相结合的法治主张。","options":[{"key":"A","text":"法"},{"key":"B","text":"术"},{"key":"C","text":"礼"},{"key":"D","text":"势"}],"answer":["A","B","D"],"explanation":"韩非子结合商鞅、申不害、慎道三位前辈的思想，在其老师荀子之性恶论的基础上，提出了“法、术、势”的治国思想。"},{"id":1764,"type":"多选题","text":"“损者三友”是指____。","options":[{"key":"A","text":"友酒肉"},{"key":"B","text":"友便辟"},{"key":"C","text":"友善柔"},{"key":"D","text":"友便佞"}],"answer":["B","C","D"],"explanation":"孔子曰：“益者三友，损者三友。友直，友谅，友多闻，益矣。友便辟，友善柔，友便佞，损矣。”孔子说：“有益的朋友有三种，有害的朋友有三种。同正直的人交友，同诚信的人交友，同见闻广博的人交友，是有益的。同逢迎谄媚的人交友，同表面柔顺而内心奸诈的人交友，同花言巧语的人交友，是有害的。”"},{"id":1765,"type":"多选题","text":"古人倡导的“三不朽”是指____。","options":[{"key":"A","text":"立德"},{"key":"B","text":"立志"},{"key":"C","text":"立功"},{"key":"D","text":"立言"}],"answer":["A","C","D"],"explanation":"三不朽， 指立德、立功、立言。"},{"id":1766,"type":"多选题","text":"下列成语典故中，出自《庄子》的有____。","options":[{"key":"A","text":"邯郸学步"},{"key":"B","text":"东施效颦"},{"key":"C","text":"井底之蛙"},{"key":"D","text":"五十步笑百步"}],"answer":["A","B","C"],"explanation":"五十步笑百步是一则来源于寓言故事的成语，成语有关典故最早见于《孟子·梁惠王上》。"},{"id":1767,"type":"多选题","text":"孟子在《生于忧患，死于安乐》一文中，在开头列举了一系列历史人物，这些历史人物有____。","options":[{"key":"A","text":"舜"},{"key":"B","text":"大禹"},{"key":"C","text":"管仲"},{"key":"D","text":"百里奚"}],"answer":["A","C","D"],"explanation":"《生于忧患，死于安乐》中孟子举了舜、傅说、胶鬲、管夷吾、孙叔敖、百里奚六位名人的事例，得出困境出人才的结论。"},{"id":1768,"type":"多选题","text":"《大道之行也》的“矜、寡、孤、独、废疾者皆有所养”一句中，以下理解正确的是____。","options":[{"key":"A","text":"“矜”指老而无子的人"},{"key":"B","text":"“寡”指老而无夫的人"},{"key":"C","text":"“孤”指幼而无父的人"},{"key":"D","text":"“独”指无兄弟姐妹的人"}],"answer":["B","C"],"explanation":"A项“矜”指老而无妻的人，D项“独”指老而无子的人。"},{"id":1769,"type":"多选题","text":"以下选项属于司马迁在《报任安书》中所列举的书籍或文章有____。","options":[{"key":"A","text":"《离骚》"},{"key":"B","text":"《吕氏春秋》"},{"key":"C","text":"《孤愤》"},{"key":"D","text":"《国语》"}],"answer":["A","B","C","D"],"explanation":"司马迁在《报任安书》列举了《春秋》《离骚》《国语》《兵法》《吕氏春秋》《说难》《孤愤》《诗》等名著的编著过程来表达自己忍辱负重的原因和志向。"},{"id":1770,"type":"多选题","text":"在《颜氏家训》中，颜之推宣扬性三品说，“三品”指____。","options":[{"key":"A","text":"上中下三等人"},{"key":"B","text":"上智之人"},{"key":"C","text":"下愚之人"},{"key":"D","text":"中庸之人"}],"answer":["B","C","D"],"explanation":"颜之推及其《颜氏家训》，颜之推宣扬性三品说，他把人性分为三等，即上智之人，下愚之人和中庸之人。"},{"id":1771,"type":"多选题","text":"《诗经》是我国第一部诗歌总集，其主要分为哪几个部分？","options":[{"key":"A","text":"“风”"},{"key":"B","text":"“雅”"},{"key":"C","text":"“言”"},{"key":"D","text":"“颂”"}],"answer":["A","B","D"],"explanation":"《诗经》是中国最早的诗歌总集，收集了地方乐调、西周王畿的乐调及祭祀用的宗教音乐，分别被称为“风、雅、颂”。"},{"id":1772,"type":"多选题","text":"下列诗句中，表现送别时朋友之间深厚情谊的有____。","options":[{"key":"A","text":"但愿人长久，千里共婵娟"},{"key":"B","text":"洛阳亲友如相问，一片冰心在玉壶"},{"key":"C","text":"劝君更尽一杯酒，西出阳关无故人"},{"key":"D","text":"桃花潭水深千尺，不及汪伦送我情"}],"answer":["B","C","D"],"explanation":"“但愿人长久，千里共婵娟”出自苏轼写给弟弟的《水调歌头》，常用于表达对远方亲人的思念之情以及美好祝愿。"},{"id":1773,"type":"多选题","text":"下列词作中，作者是李清照的有____。","options":[{"key":"A","text":"三杯两盏淡酒，怎敌他、晚来风急"},{"key":"B","text":"梧桐更兼细雨，到黄昏、点点滴滴"},{"key":"C","text":"无可奈何花落去，似曾相识燕归来"},{"key":"D","text":"物是人非事事休，欲语泪先流"}],"answer":["A","B","D"],"explanation":"C项的作者是晏殊。"},{"id":1774,"type":"多选题","text":"下列选项中，属于老子思想主张的有____。","options":[{"key":"A","text":"无为"},{"key":"B","text":"礼"},{"key":"C","text":"道"},{"key":"D","text":"性善论"}],"answer":["A","C"],"explanation":"老子思想主张的核心为“道”和“无为而治”，“礼”为孔子思想，“性善论”是孟子提出的人性论述。"},{"id":1775,"type":"多选题","text":"下列选项中，被称为“吴中四士”的有____。","options":[{"key":"A","text":"贺知章"},{"key":"B","text":"张旭"},{"key":"C","text":"包融"},{"key":"D","text":"徐凝"}],"answer":["A","B","C"],"explanation":"“吴中四士”包括张若虚、贺知章、张旭和包融"},{"id":1776,"type":"多选题","text":"欧阳修是北宋著名文学家，后人将他和____、____、____并称“千古文章四大家”。","options":[{"key":"A","text":"韩愈"},{"key":"B","text":"柳宗元"},{"key":"C","text":"王安石"},{"key":"D","text":"苏轼"}],"answer":["A","B","D"],"explanation":"“千古文章四大家”分别为韩愈、柳宗元、欧阳修、苏轼。"},{"id":1777,"type":"多选题","text":"元代时期出现了很多优秀的杂剧家和曲作家，其中被誉为“元曲四大家”的有____。","options":[{"key":"A","text":"马致远"},{"key":"B","text":"王实甫"},{"key":"C","text":"白朴"},{"key":"D","text":"郑光祖"}],"answer":["A","C","D"],"explanation":"“元曲四大家”包括关汉卿，马致远，郑光祖，白朴。"},{"id":1778,"type":"多选题","text":"公安派是明代后期出现的一个文学流派，“公安三袁”是公安派的领袖。“公安三袁”指的是哪三个人？","options":[{"key":"A","text":"袁宏道"},{"key":"B","text":"袁中道"},{"key":"C","text":"袁崇焕"},{"key":"D","text":"袁宗道"}],"answer":["A","B","D"],"explanation":"“公安三袁”指的是袁宗道、袁宏道、袁中道，袁崇焕为明末抗清名将。"},{"id":1779,"type":"多选题","text":"下列选项中，属于“中国四大名亭”的有____。","options":[{"key":"A","text":"醉翁亭"},{"key":"B","text":"陶然亭"},{"key":"C","text":"问月亭"},{"key":"D","text":"爱晚亭"}],"answer":["A","B","D"],"explanation":"“中国四大名亭”包括滁州的醉翁亭、杭州的湖心亭、北京的陶然亭及长沙的爱晚亭。"},{"id":1780,"type":"多选题","text":"《白雪歌送武判官归京》里描写了主将营帐中为武判官送行的情景，其中演奏的时候用到了哪些乐器？","options":[{"key":"A","text":"胡琴"},{"key":"B","text":"洞箫"},{"key":"C","text":"琵琶"},{"key":"D","text":"羌笛"}],"answer":["A","C","D"],"explanation":"《白雪歌送武判官归京》中“胡琴琵琶与羌笛”的意思是：胡琴琵琶羌笛合奏来助兴。所以演奏的时候用到了胡琴、琵琶、羌笛。"},{"id":1781,"type":"多选题","text":"下列木材中属于硬木的有____。","options":[{"key":"A","text":"楠木"},{"key":"B","text":"紫檀"},{"key":"C","text":"红木"},{"key":"D","text":"黄花梨"}],"answer":["B","C","D"],"explanation":"楠木为软木。"},{"id":1782,"type":"多选题","text":"围棋的别称体现了中国棋文化的深厚底蕴。下列词语中，属于围棋别称的有____。","options":[{"key":"A","text":"黑白"},{"key":"B","text":"楚河"},{"key":"C","text":"手谈"},{"key":"D","text":"玉楸枰"}],"answer":["A","C","D"],"explanation":"“楚河”与象棋有关。"},{"id":1783,"type":"多选题","text":"下列选项中，属于魏晋时期著名的美男子有___？","options":[{"key":"A","text":"何晏"},{"key":"B","text":"潘岳"},{"key":"C","text":"宋玉"},{"key":"D","text":"卫玠"}],"answer":["A","B","D"],"explanation":"C项宋玉是战国时期的人。"},{"id":1784,"type":"多选题","text":"清代有两位围棋大家曾在浙江当湖对弈13局，留存下来11谱，史称“当湖十局”。这两个人是____。","options":[{"key":"A","text":"范西屏"},{"key":"B","text":"程兰如"},{"key":"C","text":"梁魏今"},{"key":"D","text":"施襄夏"}],"answer":["A","D"],"explanation":"清乾隆四年（公元1739年），两位围棋国手范西屏、施襄夏于浙江当湖的十盘对局，体现了当时围棋的最高水平，被称为“当湖十局”。"},{"id":1785,"type":"多选题","text":"《史记》中的“本纪”原为历代帝王的传记。下列选项中，不是帝王却被载入“本纪”中的有____。","options":[{"key":"A","text":"《高祖本纪》"},{"key":"B","text":"《孝文本纪》"},{"key":"C","text":"《项羽本纪》"},{"key":"D","text":"《吕太后本纪》"}],"answer":["C","D"],"explanation":"项羽和吕太后都没有当过皇帝。"},{"id":1786,"type":"多选题","text":"古时百姓的称谓有____。","options":[{"key":"A","text":"黔首"},{"key":"B","text":"生民"},{"key":"C","text":"黎元"},{"key":"D","text":"氓"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":1787,"type":"多选题","text":"中国古代神话故事“干将莫邪”，在多本书籍中均有提及。下列记载了此故事的书籍有____。","options":[{"key":"A","text":"《列士传》"},{"key":"B","text":"《孝子传》"},{"key":"C","text":"《聊斋志异》"},{"key":"D","text":"《西游记》"}],"answer":["A","B"],"explanation":"干将莫邪是古代中国神话传说，最早出自汉朝刘向《列士传》和《孝子传》中。"},{"id":1788,"type":"多选题","text":"下列关于道教的发展历程，说法正确的有____。","options":[{"key":"A","text":"隋唐至北宋是道教的兴盛时期。"},{"key":"B","text":"北魏寇谦之改革了道教，要求教徒“专以礼度为首”，为北天师道。"},{"key":"C","text":"《三经洞书目录》是道教史上第一部道经目录。"},{"key":"D","text":"张道陵撰写了《真灵位业图》，构造了道教的神仙谱系。"}],"answer":["A","B","C"],"explanation":"D项为陶弘景撰写了《真灵位业图》。"},{"id":1789,"type":"多选题","text":"下列话语体现了循序渐进教学原则的有____。","options":[{"key":"A","text":"不陵节而施"},{"key":"B","text":"温故而知新"},{"key":"C","text":"学而时习之"},{"key":"D","text":"学不躐等"}],"answer":["A","D"],"explanation":"B、C两项体现的是巩固性教学原则。"},{"id":1790,"type":"多选题","text":"下列诗句中与战争相关的是____。","options":[{"key":"A","text":"江畔何人初见月？江月何年初照人"},{"key":"B","text":"白骨露于野，千里无鸡鸣"},{"key":"C","text":"葡萄美酒夜光杯，欲饮琵琶马上催"},{"key":"D","text":"王师北定中原日，家祭无忘告乃翁"}],"answer":["B","C","D"],"explanation":"“江畔何人初见月？江月何年初照人”出自《春江花月夜》，抒写了游子思妇真挚动人的离情别绪以及富有哲理意味的人生感慨。"},{"id":1791,"type":"多选题","text":"墨子创立墨家学派，是古代著名的思想家、政治家。下列思想不是由墨子提出的是____。","options":[{"key":"A","text":"子非鱼，安知鱼之乐"},{"key":"B","text":"己所不欲，勿施于人"},{"key":"C","text":"官无常贵，民无终贱"},{"key":"D","text":"三人行，必有我师焉"}],"answer":["A","B","D"],"explanation":"“子非鱼安知鱼之乐”一句出自惠子，“己所不欲，勿施于人”、“三人行，必有我师焉”均为孔子提出的名句。"},{"id":1792,"type":"多选题","text":"下列人物与著名将领戚继光属于同一朝代的是___","options":[{"key":"A","text":"邓世昌"},{"key":"B","text":"于谦"},{"key":"C","text":"宗泽"},{"key":"D","text":"张居正"}],"answer":["B","D"],"explanation":"于谦、张居正与戚继光同为明朝人。"},{"id":1793,"type":"多选题","text":"我国近代历史上涌现出很多爱国进步人士，清代爱国政治家林则徐就是这样的人，他曾经____。","options":[{"key":"A","text":"开办福州船政局"},{"key":"B","text":"虎门销烟"},{"key":"C","text":"组织翻译西文书报"},{"key":"D","text":"组建北洋水师"}],"answer":["B","C"],"explanation":"A项是左宗棠创办的，D项是洋务运动时期李鸿章等人创办的。"},{"id":1794,"type":"多选题","text":"关于七夕有很多美好的传说，下面关于七夕的描述不正确的是____。","options":[{"key":"A","text":"七夕起源于汉代"},{"key":"B","text":"在七夕晚上，古代的男子会比赛穿针引线，祈求有一双能写出好文章的妙手"},{"key":"C","text":"七夕是传说中牵牛星和织女星运行在同一轨道的日子"},{"key":"D","text":"在七夕这一天人们会相约去登高"}],"answer":["B","C","D"],"explanation":"七夕起源于汉代，是相传牛郎和织女相聚的日子，在这一天古代的女人们会比赛穿针引线，以祈求一双巧手。"},{"id":1795,"type":"多选题","text":"我国每个少数民族都有自己独特的风俗习惯和传统节日。下面选项中各少数民族与其节日对应正确的是____。","options":[{"key":"A","text":"火把节——彝族"},{"key":"B","text":"泼水节——赫哲族"},{"key":"C","text":"雪顿节——壮族"},{"key":"D","text":"那达慕大会——蒙古族"}],"answer":["A","D"],"explanation":"泼水节是傣族的节日，雪顿节是藏族的节日。"},{"id":1796,"type":"多选题","text":"李清照是宋朝著名的女词人，下面选项中属于李清照的作品有____。","options":[{"key":"A","text":"《如梦令•常记溪亭日暮》"},{"key":"B","text":"《声声慢•寻寻觅觅》"},{"key":"C","text":"《回乡偶书》"},{"key":"D","text":"《夏日绝句》"}],"answer":["A","B","D"],"explanation":"C项《回乡偶书》出自贺知章。"},{"id":1797,"type":"多选题","text":"下列关于郑成功的说法正确的是____。","options":[{"key":"A","text":"郑成功出生于福建"},{"key":"B","text":"郑成功的父亲是一名渔夫"},{"key":"C","text":"郑成功收复台湾后，在台湾设置府县"},{"key":"D","text":"写有诗句“开辟荆榛逐荷夷，十年始克复先基”"}],"answer":["A","C","D"],"explanation":"郑成功的父亲为郑芝龙，初为海盗，后归顺明朝成为官员。"},{"id":1798,"type":"多选题","text":"下列属于清代民族英雄的是____。","options":[{"key":"A","text":"戚继光"},{"key":"B","text":"郑成功"},{"key":"C","text":"林则徐"},{"key":"D","text":"薛岳"}],"answer":["B","C"],"explanation":"戚继光和薛岳分别为明朝抗倭名将和民国时期抗日名将。"},{"id":1799,"type":"多选题","text":"在端午节时，有些地方还有吃“五黄”的习俗，据说可以避 “五毒”。下列属于“五毒”的有____。","options":[{"key":"A","text":"蝎"},{"key":"B","text":"蛇"},{"key":"C","text":"蜈蚣"},{"key":"D","text":"壁虎"}],"answer":["A","B","C","D"],"explanation":"五毒，是指蜈蚣、毒蛇、蝎子、壁虎和蟾蜍，这五种有毒动物的合称。"},{"id":1800,"type":"多选题","text":"下列自然景观位于云南大理州的是____。","options":[{"key":"A","text":"苍山"},{"key":"B","text":"听命湖"},{"key":"C","text":"五老山"},{"key":"D","text":"洱海"}],"answer":["A","D"],"explanation":"听命湖位于云南省泸水县，五老山位于云南省临沧市。"},{"id":1801,"type":"多选题","text":"下列自然景观位于迪庆藏族自治州的是____。","options":[{"key":"A","text":"梅里雪山"},{"key":"B","text":"泸沽湖"},{"key":"C","text":"白水台"},{"key":"D","text":"怒江第一湾"}],"answer":["A","C"],"explanation":"泸沽湖位于四川省盐源县与云南省宁蒗县交界处，怒江第一湾位于云南贡山县。"},{"id":1802,"type":"多选题","text":"一切景语皆情语。下列写景的诗句与其作者对应正确的是____。","options":[{"key":"A","text":"草满池塘水满陂，山衔落日浸寒漪。——雷震"},{"key":"B","text":"雨前初见花间蕊，雨后兼无叶里花。——王驾"},{"key":"C","text":"断肠江城雁，高高向北飞。——杜甫"},{"key":"D","text":"床前明月光，疑是地上霜。——王维"}],"answer":["A","B","C"],"explanation":"“床前明月光，疑是地上霜”出自李白的《静夜思》。"},{"id":1803,"type":"多选题","text":"下列名言出自《弟子规》的是____。","options":[{"key":"A","text":"泛爱众,而亲仁"},{"key":"B","text":"有余力,则学文"},{"key":"C","text":"兄道友,弟道恭"},{"key":"D","text":"财物轻,怨何生"}],"answer":["A","B","C","D"],"explanation":"《弟子规》是清朝李毓秀所作的三言韵文，列举了为人子弟在家、外出，待人、接物等应该有的礼仪规范，上述句子均出于此。"},{"id":1804,"type":"多选题","text":"以下寓言故事与出处对应正确的是____。","options":[{"key":"A","text":"滥竽充数——《孟子》"},{"key":"B","text":"屠龙之术——《庄子》"},{"key":"C","text":"掩耳盗铃——《吕氏春秋》"},{"key":"D","text":"与狐谋皮——《符子》"}],"answer":["B","C","D"],"explanation":"滥竽充数是一则由寓言故事演化而来的成语，最早出自《韩非子·内储说上》。"},{"id":1805,"type":"多选题","text":"下列名句与出处搭配正确的选项有____。","options":[{"key":"A","text":"爱人者，人恒爱之——《孟子》"},{"key":"B","text":"驽马十驾，功在不舍——《韩非子》"},{"key":"C","text":"己欲立而立人，己欲达而达人——《论语》"},{"key":"D","text":"真者，精诚之至也——《庄子》"}],"answer":["A","C","D"],"explanation":"“驽马十驾，功在不舍”出自荀子的《劝学》，"},{"id":1806,"type":"多选题","text":"梁山伯与祝英台坚贞的爱情故事感动了许多人。下列哪些是梁山伯与祝英台的爱情故事中的桥段？","options":[{"key":"A","text":"水漫金山"},{"key":"B","text":"草桥结拜"},{"key":"C","text":"三载同窗"},{"key":"D","text":"十八相送"}],"answer":["B","C","D"],"explanation":"水漫金山是中国著名四大爱情传说之《白蛇传》中的一段情节。"},{"id":1807,"type":"多选题","text":"中国传统绘画原本称为____等，明清时，西洋画传入中国才有了其他提法。","options":[{"key":"A","text":"画"},{"key":"B","text":"绘"},{"key":"C","text":"浮世绘"},{"key":"D","text":"丹青"}],"answer":["A","B","D"],"explanation":"浮世绘是指表现不断变幻的浮动世界的绘画，兴起于日本江户时代。"},{"id":1808,"type":"多选题","text":"苏州一带画家承接元代文人画风格形成“吴门画派”。下列选项属于“吴门四家”的有______。","options":[{"key":"A","text":"唐寅"},{"key":"B","text":"仇英"},{"key":"C","text":"文徵明"},{"key":"D","text":"祝枝山"}],"answer":["A","B","C"],"explanation":"“吴门四家”指的是四位著名的明代画家：沈周、文徵明、唐寅和仇英。"},{"id":1809,"type":"多选题","text":"国画按照题材可以分为三大类，分别是____。","options":[{"key":"A","text":"人物画"},{"key":"B","text":"花鸟画"},{"key":"C","text":"山水画"},{"key":"D","text":"宫室画"}],"answer":["A","B","C"],"explanation":"“宫室画”又指宫廷绘画，是指为封建帝王服务的绘画创作，并非国画的题材之一。"},{"id":1810,"type":"多选题","text":"下列诗题中属于七言绝句的是____。","options":[{"key":"A","text":"《九月九日忆山东兄弟》"},{"key":"B","text":"《山居秋暝》"},{"key":"C","text":"《望庐山瀑布》"},{"key":"D","text":"《滁州西涧》"}],"answer":["A","C","D"],"explanation":"王维的《山居秋暝》属于五言律诗。"},{"id":1811,"type":"多选题","text":"山水画可以细分为___多种类型。","options":[{"key":"A","text":"青绿山水"},{"key":"B","text":"金碧山水"},{"key":"C","text":"水墨山水"},{"key":"D","text":"浅绛山水"}],"answer":["A","B","C","D"],"explanation":"山水画为中国画的一种，主要描写山川等自然景色，主要分为：青绿山水、水墨山水、浅绛山水、金碧山水和没骨山水。"},{"id":1812,"type":"多选题","text":"下列画家与其画作搭配正确的一项是____。","options":[{"key":"A","text":"《清明上河图》——张择端"},{"key":"B","text":"《虢国夫人游春图》——张萱"},{"key":"C","text":"《步辇图》——阎立本"},{"key":"D","text":"《富春山居图》——赵孟頫"}],"answer":["A","B","C"],"explanation":"D项作者是黄公望。"},{"id":1813,"type":"多选题","text":"《清明上河图》生动地展现了北宋时期城市生活的多彩风貌，大致可以分为以下三段___。","options":[{"key":"A","text":"郊野春色"},{"key":"B","text":"大漠孤烟"},{"key":"C","text":"汴河码头"},{"key":"D","text":"市井街道"}],"answer":["A","C","D"],"explanation":"《清明上河图》展现的是汴京的城市景象，大漠孤烟为沙漠景色，不会出现在城市当中。"},{"id":1814,"type":"多选题","text":"藏族同胞会为远方的客人献上洁白的哈达，以表达他们对远道而来的客人祝福。对藏族同胞而言，白色象征着____。","options":[{"key":"A","text":"纯洁"},{"key":"B","text":"如意"},{"key":"C","text":"吉祥"},{"key":"D","text":"善良"}],"answer":["A","B","C","D"],"explanation":"藏族是一个特别崇尚白色的民族, 且将白色视为吉祥的象征，因此以上选项均是白色的象征意义。"},{"id":1815,"type":"多选题","text":"大观楼始建于康熙年间，见证了昆明三百多年来的成长、变化与发展，下面出自大观楼长联的选项有____。","options":[{"key":"A","text":"汉习楼船"},{"key":"B","text":"唐标铁柱"},{"key":"C","text":"宋挥玉斧"},{"key":"D","text":"洪武开疆"}],"answer":["A","B","C"],"explanation":"上联\n五百里滇池奔来眼底，披襟岸帻，喜茫茫空阔无边。看：东骧神骏，西翥灵仪，北走蜿蜒，南翔缟素。高人韵士何妨选胜登临。趁蟹屿螺洲，梳裹就风鬟雾鬓；更苹天苇地，点缀些翠羽丹霞，莫辜负：四围香稻，万顷晴沙，九夏芙蓉，三春杨柳。\n下联\n数千年往事注到心头，把酒凌虚，叹滚滚英雄谁在？想：汉习楼船，唐标铁柱，宋挥玉斧，元跨革囊。伟烈丰功费尽移山心力。尽珠帘画栋，卷不及暮雨朝云；便断碣残碑，都付与苍烟落照。只赢得：几杵疏钟，半江渔火，两行秋雁，一枕清霜。通读全诗，由此排除D选项。"},{"id":1816,"type":"多选题","text":"我国有很多名楼皆因文人杰作而名扬天下，下列选项中文人与其所写的关于名楼的作品对应正确的是____。","options":[{"key":"A","text":"辛弃疾——《岳阳楼记》"},{"key":"B","text":"王勃——《滕王阁序》"},{"key":"C","text":"王之涣——《登鹳雀楼》"},{"key":"D","text":"崔颢——《黄鹤楼》"}],"answer":["B","C","D"],"explanation":"A项岳阳楼记是范仲淹所写。"},{"id":1817,"type":"多选题","text":"战国时期频繁的战争产生了众多的军事家和能征善战的名将。下列选项中属于“战国四大名将”的是____。","options":[{"key":"A","text":"白起"},{"key":"B","text":"李牧"},{"key":"C","text":"廉颇"},{"key":"D","text":"张良"}],"answer":["A","B","C"],"explanation":"战国四大名将，秦赵各半，秦有白起、王翦，赵有李牧、廉颇，因此排除D项。"},{"id":1818,"type":"多选题","text":"《史记》不仅反映了中国古代历史，其本身也是一部优秀的文学作品，它主要分为____和列传五个部分。","options":[{"key":"A","text":"本纪"},{"key":"B","text":"世家"},{"key":"C","text":"表"},{"key":"D","text":"书"}],"answer":["A","B","C","D"],"explanation":"《史记》分为本纪、世家、列传、表、书等五个部分。"},{"id":1819,"type":"多选题","text":"被后人称为“天下三大行书”的字帖是____。","options":[{"key":"A","text":"《兰亭序》"},{"key":"B","text":"《祭侄文稿》"},{"key":"C","text":"《曹全碑》"},{"key":"D","text":"《黄州寒食帖》"}],"answer":["A","B","D"],"explanation":"天下三大行书”指的分别是王羲之的《兰亭序》、颜真卿的《祭侄文稿》和苏轼的《寒食帖》，因此排除C选项。"},{"id":1820,"type":"多选题","text":"孔林圣地承载着传播儒家文化的使命，影响一代又一代的人们，下列选项中有关孔林的叙述错误的是____。","options":[{"key":"A","text":"孔子“杏坛讲学”的杏坛亭是孔林的主要建筑之一"},{"key":"B","text":"孔林的主殿名为大成殿，与故宫太和殿、泰山岱庙天贶殿并称“东方三大殿”"},{"key":"C","text":"孔林的核心是“铁山园”"},{"key":"D","text":"孔子墓因墓形如隆起的马背，故名“马鬣封”"}],"answer":["A","B","C"],"explanation":"A选项中，孔子“杏坛讲学”的杏坛亭不是孔林的主要建筑之一，孔林的主要建筑包括大成殿、铁山园等，而杏坛亭位于孔庙内，并非孔林的一部分‌。B选项中，东方三大殿分别为山东曲阜孔庙的主殿大成殿、北京故宫太和殿、山东泰安岱庙天贶殿。C选项中，孔林的核心是“孔子墓”。"},{"id":1821,"type":"多选题","text":"下列哪些材料是用来制作活字印刷所使用的活字块的常见材料？","options":[{"key":"A","text":"木头"},{"key":"B","text":"胶泥"},{"key":"C","text":"金属"},{"key":"D","text":"龟甲"}],"answer":["A","B","C"],"explanation":"最早的活字是胶泥字（陶字）,木字、金属字是后来的进步之作。因此可以排除D选项。"},{"id":1822,"type":"多选题","text":"中国瓷器闻名世界，下列选项中哪些是清代的瓷器制作技艺？","options":[{"key":"A","text":"釉里红"},{"key":"B","text":"五彩"},{"key":"C","text":"粉彩"},{"key":"D","text":"珐琅彩"}],"answer":["B","C","D"],"explanation":"A项釉里红瓷是传统陶瓷中的艺术珍品，属于元代中期景德镇劳动人民的重要发明之一。"},{"id":1823,"type":"多选题","text":"苏州园林中比较有代表性的有沧浪亭、狮子林、拙政园、留园，它们代表的朝代的艺术风格包括____。","options":[{"key":"A","text":"唐"},{"key":"B","text":"宋"},{"key":"C","text":"元"},{"key":"D","text":"明"}],"answer":["B","C","D"],"explanation":"沧浪亭、狮子林、拙政园和留园分别代表着宋、元、明、清四个朝代的艺术风格，因此排除A选项。"},{"id":1824,"type":"多选题","text":"造纸术在4世纪传到了___，直至19世纪中叶，造纸术已传遍世界。","options":[{"key":"A","text":"美洲"},{"key":"B","text":"朝鲜半岛"},{"key":"C","text":"日本"},{"key":"D","text":"越南"}],"answer":["B","C","D"],"explanation":"造纸术在四世纪传到了朝鲜半岛、日本、越南，因此排除A选项。"},{"id":1825,"type":"多选题","text":"莫高窟为我们呈现出一个神秘、瑰丽的艺术世界，下列关于莫高窟壁画描述正确的是____。","options":[{"key":"A","text":"莫高窟壁画题材与佛教息息相关，有佛像画、佛教故事的画作等"},{"key":"B","text":"莫高窟壁画绘画技巧风格多样，线条精细"},{"key":"C","text":"壁画所用的全部颜料均从矿石中提炼而来"},{"key":"D","text":"莫高窟壁画有4500平方米"}],"answer":["A","B","C"],"explanation":"D项目莫高窟壁画面积约45000平方米。"},{"id":1826,"type":"多选题","text":"宋代是瓷器发展的重要时期，其中五大名窑包含____。","options":[{"key":"A","text":"定窑"},{"key":"B","text":"官窑"},{"key":"C","text":"哥窑"},{"key":"D","text":"钧窑"}],"answer":["A","B","C","D"],"explanation":"中国古代五大名窑是钧窑、汝窑、官窑、定窑、哥窑。"},{"id":1827,"type":"多选题","text":"下列选项中哪些是东巴经籍文学的代表作品？","options":[{"key":"A","text":"《创世纪》"},{"key":"B","text":"《黑白战争》"},{"key":"C","text":"《彩虹》"},{"key":"D","text":"《鲁般鲁饶》"}],"answer":["A","B","D"],"explanation":"《东巴经》除记载迎神驱鬼、祈福求寿、消灾消难等内容外,还记载了大量的纳西族古典文学作品,包括神话故事、叙事长诗、谚语歌谣等。 神话中最著名的是创世史诗《创世纪》、英雄史诗《黑白战争》、悲剧长诗《鲁般鲁饶》。它们合称纳西族的三大史诗。"},{"id":1828,"type":"多选题","text":"《战国策》重点记述了战国时期纵横家们游说各国的历史，下列选项中属于战国时期纵横家的有____。","options":[{"key":"A","text":"董仲舒"},{"key":"B","text":"张仪"},{"key":"C","text":"鲁仲连"},{"key":"D","text":"诸葛亮"}],"answer":["B","C"],"explanation":"A项董仲舒是西汉哲学家，D项诸葛亮是三国时期蜀汉丞相。"},{"id":1829,"type":"多选题","text":"下列史书与其体例搭配正确的有____。","options":[{"key":"A","text":"《国语》——纪事本末"},{"key":"B","text":"《史记》——纪传体"},{"key":"C","text":"《左传》——编年体"},{"key":"D","text":"《战国策》——国别体"}],"answer":["B","C","D"],"explanation":"A项《国语》是我国第一部国别体史记。"},{"id":1830,"type":"多选题","text":"形声是一种造字方法。下列汉字属于形声字的是____。","options":[{"key":"A","text":"睁"},{"key":"B","text":"吐"},{"key":"C","text":"咏"},{"key":"D","text":"灰"}],"answer":["A","B","C"],"explanation":"形声字是由两个文或字复合成体，其中的一个文或字表示事物的类别而另一个表示事物的读音，因此选择A,B,C选项。"},{"id":1831,"type":"多选题","text":"关于夸父追日的神话故事，下列描述正确的是____。","options":[{"key":"A","text":"夸父倒下后变成了一座大山"},{"key":"B","text":"在追逐太阳的过程中，夸父即便又渴又累，也没有放弃"},{"key":"C","text":"夸父最终追上了太阳"},{"key":"D","text":"夸父最终死在了路上"}],"answer":["A","B","D"],"explanation":"夸父追日指的是相传在黄帝时期，夸父族首领夸父想要把太阳摘下，于是开始逐日，和太阳赛跑，在口渴时喝干了黄河、渭水之后，在奔于大泽路途中渴死。死后他的手杖化作桃林，身躯化作夸父山，因此排除C选项。"},{"id":1832,"type":"多选题","text":"传说神农对中华民族的生存繁衍和发展做出了重要贡献。人们为了纪念这位无私爱民的首领，尊称他为____。","options":[{"key":"A","text":"“药王”"},{"key":"B","text":"“药圣”"},{"key":"C","text":"“五谷之神”"},{"key":"D","text":"“五谷先帝”"}],"answer":["A","D"],"explanation":"B项药圣是李时珍；C项五谷之神为后稷。"},{"id":1833,"type":"多选题","text":"清明节是我国的重要传统节日之一，下列哪些属于清明节的节日习俗？","options":[{"key":"A","text":"扫墓"},{"key":"B","text":"踏青"},{"key":"C","text":"吃粽子"},{"key":"D","text":"放风筝"}],"answer":["A","B","D"],"explanation":"C项吃粽子是端午节的习俗。"},{"id":1834,"type":"多选题","text":"下列属于寒食节节日习俗的有____。","options":[{"key":"A","text":"禁火"},{"key":"B","text":"吃冷食"},{"key":"C","text":"扫墓"},{"key":"D","text":"猜灯谜"}],"answer":["A","B","C"],"explanation":"D项猜灯谜又称打灯谜，是从古代就开始流传的元宵节特色活动。"},{"id":1835,"type":"多选题","text":"传说夸父在追赶太阳的路途上，因为口渴，喝干了哪些河流里的水？","options":[{"key":"A","text":"长江"},{"key":"B","text":"黄河"},{"key":"C","text":"渭河"},{"key":"D","text":"淮河"}],"answer":["B","C"],"explanation":"《山海经·海外北经》:“夸父与日逐走，入日，渴欲得饮，饮于河渭，河渭不足，北饮大泽。未至，道渴而死。弃杖，化为邓林。”古文中“河”常特指黄河。渭河，古称渭水，是黄河的最大支流。因此选B,C选项。"},{"id":1836,"type":"多选题","text":"请问，下面哪些神话传说与太阳有关？","options":[{"key":"A","text":"夸父逐日"},{"key":"B","text":"愚公移山"},{"key":"C","text":"后羿射日"},{"key":"D","text":"天狗食日"}],"answer":["A","C","D"],"explanation":"B项愚公移山讲述的是愚公不畏艰难，坚持不懈，挖山不止，最终感动天帝而将山挪走的故事，与太阳无关。"},{"id":1837,"type":"多选题","text":"下列选项中，既属于农历二十四节气，又是我国传统节日的是____。","options":[{"key":"A","text":"清明"},{"key":"B","text":"端午"},{"key":"C","text":"冬至"},{"key":"D","text":"七夕"}],"answer":["A","C"],"explanation":"二十四节气中,既是节气又是传统节日的是清明和冬至，因此选A,C选项。"},{"id":1838,"type":"多选题","text":"在我国，每个地区、每个民族都有自己的特色美食，下列选项中，哪些属于云南地区的特色美食？","options":[{"key":"A","text":"过桥米线"},{"key":"B","text":"竹筒饭"},{"key":"C","text":"汽锅鸡"},{"key":"D","text":"虾饺"}],"answer":["A","B","C"],"explanation":"D项虾饺是广东的特色美食。"},{"id":1839,"type":"多选题","text":"六经，是六部儒学经典的统称，下列选项中属于六经的是____。","options":[{"key":"A","text":"《诗经》"},{"key":"B","text":"《论语》"},{"key":"C","text":"《礼记》"},{"key":"D","text":"《春秋》"}],"answer":["A","C","D"],"explanation":"六经，是指《诗》、《书》、《礼》、《易》、《乐》、《春秋》的合称，排除B选项。"},{"id":1840,"type":"多选题","text":"尊老爱幼是我们中华民族的传统美德。下列选项中，属于尊老爱幼的是____。","options":[{"key":"A","text":"单老孤稚有所养"},{"key":"B","text":"老吾老以及人之老，幼吾幼以及人之幼"},{"key":"C","text":"子不学，非所宜。幼不学，老何为"},{"key":"D","text":"臣无祖母，无以至今日；祖母无臣，无以终余年"}],"answer":["A","B","D"],"explanation":"C项意思是：一个人倘若小时候不好好学习，到老的时候既不懂做人的道理，又无知识，那么到老的时候都很难有所作为的，与题目不符。"},{"id":1841,"type":"多选题","text":"婉约派为中国宋词流派。下列词人属于婉约派的是____。","options":[{"key":"A","text":"李清照"},{"key":"B","text":"辛弃疾"},{"key":"C","text":"晏殊"},{"key":"D","text":"周邦彦"}],"answer":["A","C","D"],"explanation":"婉约派代表人物有柳永、晏殊、秦观、周邦彦、李清照等人；B选项辛弃疾是豪放派代表人物。"},{"id":1842,"type":"多选题","text":"豪放派是形成于宋代的词学流派之一，豪放派的代表人物有____。","options":[{"key":"A","text":"李煜"},{"key":"B","text":"辛弃疾"},{"key":"C","text":"柳永"},{"key":"D","text":"苏轼"}],"answer":["B","D"],"explanation":"豪放派的代表人物主要有苏轼、辛弃疾、王安石等；A,C选项是婉约派代表人物。"},{"id":1843,"type":"多选题","text":"百日礼，是我国古代较为重要的礼俗之一。下列哪些关键词与“百日礼”有关？","options":[{"key":"A","text":"三月看相，百日看长"},{"key":"B","text":"满月酒"},{"key":"C","text":"百家衣"},{"key":"D","text":"洗三朝"}],"answer":["A","C"],"explanation":"B项满月酒，是指婴儿出生后一个月而设立的酒宴。D项洗三朝是婴儿出生3日后重要的洗浴仪式，意在洗净秽污，令其洁白入世，使其健康成长。"},{"id":1844,"type":"多选题","text":"《周礼》记载的“六艺”包括____。","options":[{"key":"A","text":"诗"},{"key":"B","text":"礼"},{"key":"C","text":"射"},{"key":"D","text":"书"}],"answer":["B","C","D"],"explanation":"“六艺”分别是：礼、乐、射、御、书、数，因此排除A选项。"},{"id":1845,"type":"多选题","text":"射箭已经成为现代奥运会的比赛项目之一，我国自古以来就有这项运动，下列哪些人物是射箭能手？","options":[{"key":"A","text":"李广"},{"key":"B","text":"养由基"},{"key":"C","text":"蒙万赢"},{"key":"D","text":"长孙晟"}],"answer":["A","B","D"],"explanation":"C项蒙万赢是相扑高手。"},{"id":1846,"type":"多选题","text":"汉语中有很多词语是从“纺织”中发展而来的。下列选项中的词语，哪些与纺织无关？","options":[{"key":"A","text":"综合"},{"key":"B","text":"分析"},{"key":"C","text":"经纬"},{"key":"D","text":"规矩"}],"answer":["B","D"],"explanation":"A项综合：综，是织布机上使经线上下交错以受纬线的装置；综合，就是把几千根不同的经线合并起来，后来便引申为将不同事物或不同部分合并为一个整体。C项经纬：原指织物的纵线和横线，后来引申为地球的经度和纬度。"},{"id":1847,"type":"多选题","text":"作为中国古代四大发明之一，印刷术为人类文明的进步做出了重大贡献。下列哪些词语与印刷无关？","options":[{"key":"A","text":"模勒"},{"key":"B","text":"叫板"},{"key":"C","text":"付梓"},{"key":"D","text":"亮相"}],"answer":["B","D"],"explanation":"B、D项“叫板”“亮相”是戏曲行业中的术语。"},{"id":1848,"type":"多选题","text":"在瓷器鉴赏节目中，我们常常能听到一些专业术语，下列哪些术语与瓷器有关？","options":[{"key":"A","text":"重皮"},{"key":"B","text":"棕眼"},{"key":"C","text":"倒口儿"},{"key":"D","text":"口磕"}],"answer":["A","B","D"],"explanation":"C项“倒口儿”是曲艺行业术语，意思是“说方言”。"},{"id":1849,"type":"多选题","text":"太和殿是故宫内规模最大、最高的殿宇。主要供____大朝会和其他大典，如皇帝登基或大婚册封时使用。","options":[{"key":"A","text":"花朝节"},{"key":"B","text":"寒食"},{"key":"C","text":"元旦"},{"key":"D","text":"冬至"}],"answer":["C","D"],"explanation":"太和殿是紫禁城外朝主殿,是供天子登基、颁布重要政令、召见朝臣、授命出兵征讨,以及举行元旦、冬至大朝会和万寿(皇帝诞辰)等活动的主要场所，因此排除A,B选项。"},{"id":1850,"type":"多选题","text":"清朝有专门供皇家使用的藏书楼即“北方四阁”,下列哪些属于“北方四阁”？","options":[{"key":"A","text":"文渊阁"},{"key":"B","text":"文津阁"},{"key":"C","text":"文澜阁"},{"key":"D","text":"文源阁"}],"answer":["A","B","D"],"explanation":"“北方四阁”分别是：北京故宫的文渊阁、沈阳故宫的文溯阁、北京圆明园的文源阁、河北承德避暑山庄的文津阁。"},{"id":1851,"type":"多选题","text":"北京是我国首都，也是文化中心，这里有许多名胜古迹。下列名胜古迹位于北京的是____。","options":[{"key":"A","text":"故宫"},{"key":"B","text":"颐和园"},{"key":"C","text":"灵隐寺"},{"key":"D","text":"鄱阳湖"}],"answer":["A","B"],"explanation":"C项灵隐寺位于杭州西湖，D项鄱阳湖位于江西。"},{"id":1852,"type":"多选题","text":"颐和园规模宏大，气象万千。下列选项中，哪些景点位于颐和园中？","options":[{"key":"A","text":"沁芳亭"},{"key":"B","text":"冠云峰"},{"key":"C","text":"万寿山"},{"key":"D","text":"昆明湖"}],"answer":["C","D"],"explanation":"A项沁芳亭位于北京的大观园中，B项冠云峰位于苏州的留园中。"},{"id":1853,"type":"多选题","text":"中国文化又可称为____。","options":[{"key":"A","text":"中华文化"},{"key":"B","text":"华夏文化"},{"key":"C","text":"炎黄文化"},{"key":"D","text":"中原文化"}],"answer":["A","B","C"],"explanation":"中国文化又称中华文化、华夏文化、炎黄文化，它属于国别文化。"},{"id":1854,"type":"多选题","text":"古代人们对月亮有着美好的想象，对其有很多种称呼，下列哪项不是古人对月亮的称呼？","options":[{"key":"A","text":"玉盘"},{"key":"B","text":"羲和"},{"key":"C","text":"婵娟"},{"key":"D","text":"金乌"}],"answer":["B","D"],"explanation":"B项羲和与D项金乌是对太阳的别称。"},{"id":1855,"type":"多选题","text":"《四时幽赏录》主要记述西湖一年四季的不同境趣，如春时____，夏时____，秋时“西泠桥畔醉红树”，冬时“三茅山顶望雪霁”。","options":[{"key":"A","text":"天然阁上看雨"},{"key":"B","text":"东风渐绿西湖柳"},{"key":"C","text":"花褪残红青杏小"},{"key":"D","text":"三生石谈月"}],"answer":["A","D"],"explanation":"B选项出自宋代周密的《高阳台·送陈君衡被召》，C项出自宋代苏轼的《蝶恋花·春景》。"},{"id":1856,"type":"多选题","text":"历史上对学生的称谓种类繁多，下列称谓哪些是对学生的称呼？","options":[{"key":"A","text":"生员"},{"key":"B","text":"监生"},{"key":"C","text":"弟子"},{"key":"D","text":"足下"}],"answer":["A","B","C"],"explanation":"D项足下常用于对平辈或是朋友之间的敬称。"},{"id":1857,"type":"多选题","text":"中元节与___同为中国传统的祭祖节日。","options":[{"key":"A","text":"除夕"},{"key":"B","text":"清明节"},{"key":"C","text":"端午节"},{"key":"D","text":"重阳节"}],"answer":["A","B","D"],"explanation":"清明节、中元节、重阳节、除夕是中国民间传统的四大祭祖大节，因此排除C选项。"},{"id":1858,"type":"多选题","text":"“岁寒三友”指的是____。","options":[{"key":"A","text":"兰花"},{"key":"B","text":"松树"},{"key":"C","text":"翠竹"},{"key":"D","text":"梅花"}],"answer":["B","C","D"],"explanation":"“岁寒三友”意思是松、竹经冬不凋，梅花耐寒开放，因此有“岁寒三友”之称。"},{"id":1859,"type":"多选题","text":"下列名称中属于茶的古称或别称的有____。","options":[{"key":"A","text":"荼"},{"key":"B","text":"茗"},{"key":"C","text":"炙"},{"key":"D","text":"诧"}],"answer":["A","B","D"],"explanation":"茶的别称很多，据陆羽《茶经》中介绍，除茶外，其名尚有槚、蔎、茗和荈。另外，据其他古籍中的记载，还有诧、皋芦、葭荼、酪妈等称呼，因此排除C选项。"},{"id":1860,"type":"多选题","text":"我国古代就已出现了专门为学童编写的书目。下列选项中，属于古代启蒙教材的有____。","options":[{"key":"A","text":"《三字经》"},{"key":"B","text":"《增广贤文》"},{"key":"C","text":"《菜根谭》"},{"key":"D","text":"《弟子规》"}],"answer":["A","B","D"],"explanation":"C项《菜根谭》是以处世思想为主的格言式小品文集，采用语录体，揉合了儒家的中庸思想和佛家的出世思想的人生处世哲学。"},{"id":1861,"type":"多选题","text":"下列诗句中，描写的是洞庭湖的有____。","options":[{"key":"A","text":"月落乌啼霜满天，江枫渔火对愁眠"},{"key":"B","text":"湖光秋月两相和，潭面无风镜未磨"},{"key":"C","text":"最爱湖东行不足，绿杨阴里白沙堤"},{"key":"D","text":"气蒸云梦泽，波撼岳阳城"}],"answer":["B","D"],"explanation":"A项地处苏州；C项描写的是钱塘湖。"},{"id":1862,"type":"多选题","text":"下列句子中，描写西湖风光的有____。","options":[{"key":"A","text":"雾凇沆砀，天与云与山与水，上下一白"},{"key":"B","text":"寒雨连江夜入吴，平明送客楚山孤"},{"key":"C","text":"一道残阳铺水中，半江瑟瑟半江红"},{"key":"D","text":"水光潋滟晴方好，山色空蒙雨亦奇"}],"answer":["A","D"],"explanation":"B项描述王昌龄在芙蓉楼送别时的吴江夜雨，C项是诗人白居易在赴杭州任刺史的途中写的，表示出诗人自愿远离朝廷后轻松愉悦的解放情绪和个性色彩。"},{"id":1863,"type":"多选题","text":"下面属于瑶族盘王节习俗的是____。","options":[{"key":"A","text":"跳“盘王舞”"},{"key":"B","text":"唱“盘王歌”"},{"key":"C","text":"还盘王愿"},{"key":"D","text":"吃五色饭"}],"answer":["A","B","C"],"explanation":"D项是壮族歌圩时候的习俗。"},{"id":1864,"type":"多选题","text":"茶马古道是中国西南民族经济文化交流的走廊。下面对茶马古道介绍正确的是____。","options":[{"key":"A","text":"易武、倚帮都是茶马古道上的重要古镇"},{"key":"B","text":"茶马古道始于明清"},{"key":"C","text":"运输的最主要货物是云南大叶种晒青紧压茶"},{"key":"D","text":"普洱是茶马古道上独具优势的货物产地和中转集散地，具有悠久的历史"}],"answer":["A","C","D"],"explanation":"B项茶马古道始于唐代。"},{"id":1865,"type":"多选题","text":"明代围棋之风兴盛，流派纷起，形成了三个著名的流派，这三个流派分别是____。","options":[{"key":"A","text":"永嘉派"},{"key":"B","text":"江西派"},{"key":"C","text":"新安派"},{"key":"D","text":"京师派"}],"answer":["A","C","D"],"explanation":"明代正德、嘉靖年间，形成了三个著名的围棋流派：以鲍一中为冠的永嘉派，以程汝亮为冠的新安派，以及以颜伦、李釜为冠的京师派，因此排除B选项。"},{"id":1866,"type":"多选题","text":"《三国演义》中出现了两次美人计，涉及的两位美人分别是____。","options":[{"key":"A","text":"小乔"},{"key":"B","text":"貂蝉"},{"key":"C","text":"蔡琰"},{"key":"D","text":"孙尚香"}],"answer":["B","D"],"explanation":"《三国演义》中有两个著名的美人计，第一个是貂蝉离间吕布与董卓，另一个则是孙权把妹妹孙尚香嫁给刘备，预想骗其到东吴作人质。"},{"id":1867,"type":"多选题","text":"戏曲演员要具备的四项基本功，俗称“四功”，包括____。","options":[{"key":"A","text":"唱"},{"key":"B","text":"说"},{"key":"C","text":"念"},{"key":"D","text":"做"}],"answer":["A","C","D"],"explanation":"“四功”是唱、念、做、打，因此排除B选项。“唱”指歌唱，是戏曲表演中的核心内容；“念”指具有音乐性的念白；“做”指舞蹈化的形体动作，即戏曲演员在戏曲表演过程中做工的基本功夫；“打”指武打和翻跌的技艺，即戏曲表演艺术中武戏中的武打功夫。"},{"id":1868,"type":"多选题","text":"下面的关键词中，与陶渊明有关的是____。","options":[{"key":"A","text":"端午节"},{"key":"B","text":"桃花源"},{"key":"C","text":"采菊东篱下"},{"key":"D","text":"五柳先生"}],"answer":["B","C","D"],"explanation":"A选项端午节是为了纪念战国时期跳汨罗江自尽的楚国诗人——屈原。"},{"id":1869,"type":"多选题","text":"书法碑帖集中展示了中国传统书法之美，下列书法碑帖中现存于山东曲阜孔庙的有____。","options":[{"key":"A","text":"《乙瑛碑》"},{"key":"B","text":"《史晨碑》"},{"key":"C","text":"《礼器碑》"},{"key":"D","text":"《曹全碑》"}],"answer":["A","B","C"],"explanation":"D项《曹全碑》现存于西安碑林博物馆。"},{"id":1870,"type":"多选题","text":"下列属于韩愈在文学上的主张有____。","options":[{"key":"A","text":"“致君尧舜上，再使风俗淳”"},{"key":"B","text":"“文道合一”"},{"key":"C","text":"“务去陈言”"},{"key":"D","text":"“文从字顺”"}],"answer":["B","C","D"],"explanation":"A项“致君尧舜上，再使风俗淳”，出自唐代杜甫《奉赠韦左丞丈二十二韵》诗。"},{"id":1871,"type":"多选题","text":"每逢春节，大街小巷就会挂上红色的中国结，以营造喜庆的节日氛围。下列属于中国结特点的有____。","options":[{"key":"A","text":"上下一致"},{"key":"B","text":"左右对称"},{"key":"C","text":"首尾互衔"},{"key":"D","text":"正反不同"}],"answer":["A","B","C"],"explanation":"中国结讲究上下一致，左右对称，正反相同，首尾可接，因此排除D选项。"},{"id":1872,"type":"多选题","text":"下列书法家与其作品搭配正确的有____。","options":[{"key":"A","text":"王羲之——《快雪时晴帖》"},{"key":"B","text":"怀素——《自叙帖》"},{"key":"C","text":"张旭——《论书帖》"},{"key":"D","text":"黄庭坚——《鸭头丸帖》"}],"answer":["A","B"],"explanation":"C项《论书帖》的作者是怀素，D项《鸭头丸帖》的作者是王献之。"},{"id":1873,"type":"多选题","text":"下列属于相声演员四大基本功的是____。","options":[{"key":"A","text":"说"},{"key":"B","text":"逗"},{"key":"C","text":"唱"},{"key":"D","text":"捧"}],"answer":["A","B","C"],"explanation":"相声的四大基本功是说、学、逗、唱。"},{"id":1874,"type":"多选题","text":"下列有关戏曲角色行当的说法正确的有____。","options":[{"key":"A","text":"花旦主要扮演天真活泼或性格泼辣的青年女性，常带有喜剧色彩"},{"key":"B","text":"武旦主要扮演勇武的女性，多是擅长武艺的巾帼英雄"},{"key":"C","text":"武丑包括方巾丑、褶子丑、茶衣丑等"},{"key":"D","text":"彩旦主要扮演滑稽或奸刁的女性，又称“丑旦”"}],"answer":["A","B","D"],"explanation":"C项方巾丑、褶子丑、茶衣丑属于文丑。"},{"id":1875,"type":"多选题","text":"下列关于鲁班的说法中正确的是____。","options":[{"key":"A","text":"鲁班姓鲁，名公输"},{"key":"B","text":"传说锯子为鲁班所发明"},{"key":"C","text":"“班门弄斧”的成语故事与鲁班有关"},{"key":"D","text":"《墨子》中记载了鲁班造云梯的故事"}],"answer":["B","C","D"],"explanation":"A项鲁班姓公输，名般，或称“公输子”“班输”等。因他是春秋时期鲁国人，又被称为“鲁班”。"},{"id":1876,"type":"多选题","text":"我国古代神医扁鹊医术出神入化，下列有关扁鹊的描述中正确的有____。","options":[{"key":"A","text":"“病入膏肓”的故事与扁鹊有关"},{"key":"B","text":"他在总结前人经验的基础上，结合自己的行医实践，创制了“四诊法”"},{"key":"C","text":"他被誉为“中医学的奠基人”"},{"key":"D","text":"他是春秋时期的医学家，姓秦，名越人"}],"answer":["A","B","C"],"explanation":"D项扁鹊是战国时期的医学家。"},{"id":1877,"type":"多选题","text":"下列属于“干栏式”建筑的有____。","options":[{"key":"A","text":"傣族竹楼"},{"key":"B","text":"景颇族矮脚长屋"},{"key":"C","text":"独龙族千脚落地屋"},{"key":"D","text":"客家围龙屋"}],"answer":["A","B","C"],"explanation":"D项客家围龙屋属于半圆形客家围屋（客家围村）。"},{"id":1878,"type":"多选题","text":"《大学》中的“三纲领”指的是____。","options":[{"key":"A","text":"格物"},{"key":"B","text":"亲民"},{"key":"C","text":"明德"},{"key":"D","text":"至善"}],"answer":["B","C","D"],"explanation":"《大学》中的““三纲领”指的是“明德”、“亲民”、“至善”。"},{"id":1879,"type":"多选题","text":"昆曲是中国戏曲中的古老剧种之一，昆曲又称____。","options":[{"key":"A","text":"“昆山腔”"},{"key":"B","text":"“昆腔”"},{"key":"C","text":"“昆剧”"},{"key":"D","text":"“文曲”"}],"answer":["A","B","C"],"explanation":"昆曲,原名“昆山腔”或简称“昆腔”，清代以来被称为“昆曲”，现又被称为“昆剧”。"},{"id":1880,"type":"多选题","text":"下列选项中，关于琴的诗词与其作者及出处对应正确的是____。","options":[{"key":"A","text":"七弦为益友，两耳是知音（白居易《船夜援琴》）"},{"key":"B","text":"泠泠七弦上，静听松风寒（韦应物《听弹琴》）"},{"key":"C","text":"为我一挥手，如听万壑松（李白《听蜀僧濬弹琴》）"},{"key":"D","text":"归去无眠，一夜余音在耳边（苏轼《减字木兰花》）"}],"answer":["A","C","D"],"explanation":"B项应为刘长卿的《听弹琴》。"},{"id":1881,"type":"多选题","text":"纺织与我们的生活息息相关。下列诗句中与丝绸生产和流通相关的有____。","options":[{"key":"A","text":"夜市卖菱藕，春船载绮罗"},{"key":"B","text":"小妇连宵上绢机，大耆催税急于飞"},{"key":"C","text":"将缣来比素，新人不如故"},{"key":"D","text":"掷柳迁乔太有情，交交时作弄机声"}],"answer":["A","B","C"],"explanation":"D项描写的是鸟的鸣叫声像织布声。"},{"id":1882,"type":"多选题","text":"下列诗句与“边城暮雨雁飞低，芦笋初生渐欲齐”作者相同的是____。","options":[{"key":"A","text":"湘水无潮秋水阔，湘中月落行人发"},{"key":"B","text":"停车坐爱枫林晚，霜叶红于二月花"},{"key":"C","text":"千里莺啼绿映红，水村山郭酒旗风"},{"key":"D","text":"洛阳城里见秋风，欲作家书意万重"}],"answer":["A","D"],"explanation":"题干中的作者与A、D项同为张籍，B、C项的作者均为杜牧。"},{"id":1883,"type":"多选题","text":"下列关于古琴的说法中正确的是____。","options":[{"key":"A","text":"古琴额、首、肩的部分较窄，而自身至腰再至琴尾处，则渐宽"},{"key":"B","text":"古琴的表面，即面板的表面，镶嵌有十三个圆点，表示音位，称为“徵”"},{"key":"C","text":"古琴的十三个徵，象征一年十二个月加一个闰月"},{"key":"D","text":"古琴的长度是一米多，按照古人的说法就是“三尺六寸五分”，象征一年三百六十五天"}],"answer":["B","C","D"],"explanation":"A项古琴额、首、肩的部分较宽，而自身至腰再至琴尾处，则渐窄。"},{"id":1884,"type":"多选题","text":"下列词牌名得名于道教故事的是____。","options":[{"key":"A","text":"解佩令"},{"key":"B","text":"华胥引"},{"key":"C","text":"浪淘沙"},{"key":"D","text":"蝶恋花"}],"answer":["A","B"],"explanation":"C、D项原为唐教坊曲名。"},{"id":1885,"type":"多选题","text":"下列选项中属于历史演义小说的是____。","options":[{"key":"A","text":"余邵鱼《列国志传》"},{"key":"B","text":"冯梦龙《新列国志》"},{"key":"C","text":"诸圣邻《大唐秦王词话》"},{"key":"D","text":"熊大木《大宋中兴通俗演义》"}],"answer":["A","B","C"],"explanation":"D项熊大木的《大宋中兴通俗演义》是英雄传奇小说。"},{"id":1886,"type":"多选题","text":"古人论琴，有“四善九德”之说，这“四善九德”说的都是音色和音质。其中，“四善”包含____。","options":[{"key":"A","text":"苍"},{"key":"B","text":"松"},{"key":"C","text":"润"},{"key":"D","text":"脆"}],"answer":["A","B","D"],"explanation":"四善九德中“四善”指的是苍、松、脆、滑,也就是说古琴的音质一般具备苍老、清亮、浑厚圆润、古朴等特点，因此排除C选项。"},{"id":1887,"type":"多选题","text":"书院的出现，形成了中国古代教育三足鼎立的局面。另外两个是____。","options":[{"key":"A","text":"官学"},{"key":"B","text":"瓦舍"},{"key":"C","text":"馆阁"},{"key":"D","text":"私学"}],"answer":["A","D"],"explanation":"B项在宋朝的一些大城市,有固定的娱乐场所,人们称之为瓦舍；C项馆阁指北宋至清朝时期，分掌图书经籍和编修国史等事务的人或地方。"},{"id":1888,"type":"多选题","text":"早在春秋时期，人们就用圭表测试日影长短的方法确立了哪些节气？","options":[{"key":"A","text":"立春"},{"key":"B","text":"春分"},{"key":"C","text":"夏至"},{"key":"D","text":"冬至"}],"answer":["B","C","D"],"explanation":"利用圭表测量日影的长短,就可以确定冬至(日影最长)夏至(日影最短)和春分、秋分(日影在最长、最短之间)四个节气，因此排除A选项。"},{"id":1889,"type":"多选题","text":"下列哪些水利工程始建于春秋战国时期？","options":[{"key":"A","text":"郑国渠"},{"key":"B","text":"灵渠"},{"key":"C","text":"都江堰"},{"key":"D","text":"漳水十二渠"}],"answer":["A","C","D"],"explanation":"B项灵渠，又称湘桂运河，或兴安运河，秦朝时期开凿的渠道。灵渠位于广西壮族自治区兴安县境内。建成于秦始皇三十三年（公元前二一四年）。"},{"id":1890,"type":"多选题","text":"下列选项中，赞美辛勤劳动的诗句有____。","options":[{"key":"A","text":"昼出耘田夜绩麻，村庄儿女各当家"},{"key":"B","text":"蓬头赤脚沙中子，荡桨拏钩学捕鱼"},{"key":"C","text":"满面尘灰烟火色，两鬓苍苍十指黑"},{"key":"D","text":"乡村四月闲人少，才了蚕桑又插田"}],"answer":["A","B","D"],"explanation":"C项来自《卖炭翁》，解释了老百姓承受剥削阶级肆意剥削的现实，反映当时社会的黑暗。"},{"id":1891,"type":"多选题","text":"下列说法中，包含环保思想的有____。","options":[{"key":"A","text":"草木荣华滋硕之时，则斧斤不入山林，不夭其生，不绝其长也"},{"key":"B","text":"天行有常，不为尧存，不为桀亡"},{"key":"C","text":"不夏月，毋敢夜草为灰"},{"key":"D","text":"凡窃木者，有刑罚"}],"answer":["A","C","D"],"explanation":"B项出自荀子《天论》。荀子认为，社会是清明富足还是动荡飘摇，全是人事的结果，和自然界没有什么关系。"},{"id":1892,"type":"多选题","text":"“大同”是一种社会理想，指向一种克服了“家天下”制度下亲疏远近区分，打破人我界限，以成至公之境的状态。其特点是____。","options":[{"key":"A","text":"天下为公"},{"key":"B","text":"选贤与能"},{"key":"C","text":"内圣外王"},{"key":"D","text":"各得其所"}],"answer":["A","B","D"],"explanation":"C项内圣外王是道家的政治思想。出自《庄子·天下》。"},{"id":1893,"type":"多选题","text":"诚信是一个人安身立命之本。下列选项中，反映诚信的有____。","options":[{"key":"A","text":"无人信高洁，谁为表予心"},{"key":"B","text":"人而无信，不知其可也"},{"key":"C","text":"诚，五常之本，百行之源也"},{"key":"D","text":"人无信不立"}],"answer":["B","C","D"],"explanation":"A项出自骆宾王《咏蝉》，信是相信的意思。"},{"id":1894,"type":"多选题","text":"下列节气中，反映温度变化的有____。","options":[{"key":"A","text":"寒露"},{"key":"B","text":"处暑"},{"key":"C","text":"霜降"},{"key":"D","text":"大寒"}],"answer":["B","D"],"explanation":"二十四节气反映温度变化的节气有:小暑、大暑、处暑、小寒、大寒5个节气。"},{"id":1895,"type":"多选题","text":"下列句子中，与中秋节有关的有____。","options":[{"key":"A","text":"今岁上元君记取，红灯白月雪中看"},{"key":"B","text":"闻道长安灯夜好，雕轮宝马如云"},{"key":"C","text":"今夜月明人尽望，不知秋思落谁家"},{"key":"D","text":"此夜若无月，一年虚过秋"}],"answer":["C","D"],"explanation":"C项的意思是今天晚上人们都仰望当空明月，不知道这秋思之情落在了谁家？此句诗人没有正面写自己的思亲之愁，而是用一种疑问式的委婉语气道出那绵绵的愁念会落在谁家，更具月明人远、思深情长的意境。D项的意思是今天晚上如果再没有圆满的月亮，今年的秋天就算是虚度光阴了。这句诗以月喻人生，若缺少美好与圆满，即便时光流逝，也如同虚度。诗人借此表达了对人生价值的深刻思考。"},{"id":1896,"type":"多选题","text":"《三国演义》中讲述了许多经典故事，也塑造了很多栩栩如生的人物形象。下列经典故事，属于《三国演义》的有____。","options":[{"key":"A","text":"舌战群儒"},{"key":"B","text":"三顾茅庐"},{"key":"C","text":"智取生辰纲"},{"key":"D","text":"计取荆州"}],"answer":["A","B","D"],"explanation":"C项“智取生辰纲”是《水浒传》中的故事情节。"},{"id":1897,"type":"多选题","text":"宋江是《水浒传》中梁山好汉之首。下列属于对宋江称呼的有____。","options":[{"key":"A","text":"“及时雨”"},{"key":"B","text":"“神算子”"},{"key":"C","text":"“呼保义”"},{"key":"D","text":"“宋押司”"}],"answer":["A","C","D"],"explanation":"B项“神算子”是蒋敬。"},{"id":1898,"type":"多选题","text":"下列选项中，不属于《水浒传》中人物的是____。","options":[{"key":"A","text":"郭嘉"},{"key":"B","text":"王英"},{"key":"C","text":"卢俊义"},{"key":"D","text":"严监生"}],"answer":["A","D"],"explanation":"A项郭嘉是《三国演义》中的人物，D项严监生是《儒林外史》中的人物。"},{"id":1899,"type":"多选题","text":"《三国演义》所依据的重要典籍《三国志》与哪三部著作并称“前四史”?","options":[{"key":"A","text":"《史记》"},{"key":"B","text":"《左传》"},{"key":"C","text":"《汉书》"},{"key":"D","text":"《后汉书》"}],"answer":["A","C","D"],"explanation":"前四史指的是汉朝西汉史学家司马迁的《史记》、汉朝东汉史学家班固的《汉书》、南朝宋史学家范晔的《后汉书》、晋朝西晋史学家陈寿的《三国志》。"},{"id":1900,"type":"多选题","text":"那达慕大会是蒙古族历史悠久的传统节日。在传统的那达慕大会上，男子要进行哪三项竞技活动？","options":[{"key":"A","text":"赛马"},{"key":"B","text":"摔跤"},{"key":"C","text":"投壶"},{"key":"D","text":"射箭"}],"answer":["A","B","D"],"explanation":"C项投壶是中国古代士大夫宴饮时做的一种投掷游戏。“摔跤、射箭、赛马。 自古以来,内蒙古大草原上的人们，热烈地崇拜摔跤、赛马和射箭的能手,将这三项比赛统称为“男儿三艺”。"},{"id":1901,"type":"多选题","text":"下列古语中的用兵作战思想，出自《孙子兵法》的是____。","options":[{"key":"A","text":"上兵伐谋"},{"key":"B","text":"知己知彼，百战百胜"},{"key":"C","text":"不战而屈人之兵"},{"key":"D","text":"必攻不守"}],"answer":["A","B","C"],"explanation":"D选项“必攻不守”是孙膑的用兵作战理念。"},{"id":1902,"type":"多选题","text":"下列属于春秋时期法家思想先驱人物的是____。","options":[{"key":"A","text":"管仲"},{"key":"B","text":"子产"},{"key":"C","text":"李悝"},{"key":"D","text":"申不害"}],"answer":["A","B"],"explanation":"C项李悝是战国时期法家代表人物，D申不害是战国时期思想家。"},{"id":1903,"type":"多选题","text":"下列选项中，哪些属于墨子的观点？","options":[{"key":"A","text":"“兼爱”"},{"key":"B","text":"“仁爱”"},{"key":"C","text":"“尚贤”"},{"key":"D","text":"“无为”"}],"answer":["A","C"],"explanation":"B项“仁爱”是儒家孔子的思想主张，D项 “无为”是道家老子的主张。"},{"id":1904,"type":"多选题","text":"墨子认为“言必有三表”，其中，“三表”具体指的是____。","options":[{"key":"A","text":"“本”"},{"key":"B","text":"“原”"},{"key":"C","text":"“用”"},{"key":"D","text":"“爱”"}],"answer":["A","B","C"],"explanation":"“言必有三表，何谓三表，子墨子言曰，有本之者，有原之者，有用之者”，因此排除D选项。"},{"id":1905,"type":"多选题","text":"《孙子兵法》在概括战争的要素时提出了“五事”，即道、天、地、将、法五项内容。下列关于这五项内容的具体含义，正确的是____。","options":[{"key":"A","text":"道——道德和正义"},{"key":"B","text":"天——有利的气象条件"},{"key":"C","text":"地——有利的地形地貌和地理位置"},{"key":"D","text":"将——善于作战的将领"}],"answer":["B","C","D"],"explanation":"A项“道”指君民一致"},{"id":1906,"type":"多选题","text":"三十六计是指中国古代三十六个兵法策略。下列选项中，不属于“三十六计”的是____。","options":[{"key":"A","text":"抱薪救火"},{"key":"B","text":"暗度陈仓"},{"key":"C","text":"釜底抽薪"},{"key":"D","text":"兵贵神速"}],"answer":["A","D"],"explanation":"“三十六计”包含：金蝉脱壳、抛砖引玉、借刀杀人、以逸待劳、擒贼擒王、趁火打劫、关门捉贼、浑水摸鱼、打草惊蛇、瞒天过海、反间计、笑里藏刀、顺手牵羊、调虎离山、李代桃僵、指桑骂槐、隔岸观火、树上开花、暗度陈仓、走为上计、假痴不癫、欲擒故纵、釜底抽薪、空城计、苦肉计、远交近攻、反客为主、上屋抽梯、偷梁换柱、无中生有、美人计、借尸还魂、声东击西、围魏救赵、连环计、假道伐虢。因此A，D错误。"},{"id":1907,"type":"多选题","text":"北宋的苏轼是中国古代文化艺术集大成者。下列作品中，作者是苏轼的有____。","options":[{"key":"A","text":"《赤壁赋》"},{"key":"B","text":"《行路难》"},{"key":"C","text":"《念奴娇·赤壁怀古》"},{"key":"D","text":"《将进酒》"}],"answer":["A","C"],"explanation":"B项《行路难》和D项《将进酒》的作者是李白。"},{"id":1908,"type":"多选题","text":"我国素以“礼仪之邦”著称，我国古代有“五礼”之说，下列选项中，属于“五礼”的有____。","options":[{"key":"A","text":"嘉礼"},{"key":"B","text":"吉礼"},{"key":"C","text":"宾礼"},{"key":"D","text":"凶礼"}],"answer":["A","B","C","D"],"explanation":"“五礼”包括吉礼、凶礼、军礼、宾礼、嘉礼。"},{"id":1909,"type":"多选题","text":"下列关于《论语》的说法，正确的是____。","options":[{"key":"A","text":"《论语》约成书于春秋战国时期，由孔子弟子及再传弟子编写而成"},{"key":"B","text":"儒家学派的经典著作之一，主要记录孔子及其弟子的言行"},{"key":"C","text":"全书共20篇，以语录体和对话体为主"},{"key":"D","text":"书中提出了“仁政”学说"}],"answer":["A","B","C"],"explanation":"D项仁政学说是孟子提出的。"},{"id":1910,"type":"多选题","text":"下列人物中，并称为“文章四友”的有____。","options":[{"key":"A","text":"杨炯"},{"key":"B","text":"李峤"},{"key":"C","text":"杜审言"},{"key":"D","text":"崔融"}],"answer":["B","C","D"],"explanation":"“文章四友”是李峤、杜审言、崔融、苏味道，因此排除A选项。"},{"id":1911,"type":"多选题","text":"下列哪些作品是张衡的著作？","options":[{"key":"A","text":"《西京赋》"},{"key":"B","text":"《归田赋》"},{"key":"C","text":"《东京赋》"},{"key":"D","text":"《过秦论》"}],"answer":["A","B","C"],"explanation":"D《过秦论》是贾谊政论文的代表作，分上中下三篇。全文从各个方面分析秦王朝的过失，故名为《过秦论》。"},{"id":1912,"type":"多选题","text":"司马迁《史记》中的鸿门宴一幕，都有哪些人物？","options":[{"key":"A","text":"项羽"},{"key":"B","text":"范增"},{"key":"C","text":"刘备"},{"key":"D","text":"刘邦"}],"answer":["A","B","D"],"explanation":"鸿门宴涉及的主要人物共有8位，分别是刘邦、张良、樊哙、范增、项庄、项伯、曹无伤、项羽，因此排除C。"},{"id":1913,"type":"多选题","text":"下面不属于藏戏传统剧目的是____。","options":[{"key":"A","text":"《诺桑王子》"},{"key":"B","text":"《窦娥冤》"},{"key":"C","text":"《拜月亭记》"},{"key":"D","text":"《云乘王子》"}],"answer":["B","C"],"explanation":"B项《窦娥冤》是元代戏曲家关汉卿的杂剧代表作，C《拜月亭记》（又名《拜月亭》、《幽闺记》）相传是元代施惠创作的传奇（戏剧）。"},{"id":1914,"type":"多选题","text":"中医博大精深，历史悠久，才人辈出。下列属于中医学方面杰出人物的有____。","options":[{"key":"A","text":"张仲景"},{"key":"B","text":"宋应星"},{"key":"C","text":"孙思邈"},{"key":"D","text":"董奉"}],"answer":["A","C","D"],"explanation":"宋应星是明朝著名科学家，他的著作和研究领域涉及自然科学及人文科学的不同学科，而其中最杰出的作品《天工开物》被誉为“中国17世纪的工艺百科全书”。"},{"id":1915,"type":"多选题","text":"冯梦龙是明代文学家、戏曲家，他的“三言”是中国白话短篇小说的经典代表，这“三言”指的是____。","options":[{"key":"A","text":"《喻世明言》"},{"key":"B","text":"《喻世通言》"},{"key":"C","text":"《警世通言》"},{"key":"D","text":"《醒世恒言》"}],"answer":["A","C","D"],"explanation":"冯梦龙的“三言”是：《喻世明言》、《醒世恒言》和《警世通言》。三言收录了宋元话本与明代拟话本，每部40篇，共120篇，分别刊行于天启元年、天启四年和天启七年。因为书名中都有一个“言”字，统称“三言”。"},{"id":1916,"type":"多选题","text":"《枫桥夜泊》这首诗中提到的意象有____。","options":[{"key":"A","text":"渔火"},{"key":"B","text":"乌啼"},{"key":"C","text":"美酒"},{"key":"D","text":"客船"}],"answer":["A","B","D"],"explanation":"《枫桥夜泊》是唐代诗人张继的诗作。此诗精确而细腻地描述了一个客船夜泊者对江南深秋夜景的观察和感受，勾画了月落乌啼、霜天寒夜、江枫渔火、孤舟客子等景象，有景有情有声有色。"},{"id":1917,"type":"多选题","text":"“吾日三省吾身”，是教我们要对自己的言行时时反省、检查。下列属于“三省”内容的是____。","options":[{"key":"A","text":"为人谋而不忠乎"},{"key":"B","text":"与朋友交而不信乎"},{"key":"C","text":"学而时习之，不亦说乎"},{"key":"D","text":"传不习乎"}],"answer":["A","B","D"],"explanation":"曾子曰：“吾日三省吾身：为人谋而不忠乎？与朋友交而不信乎？传不习乎？”"},{"id":1918,"type":"多选题","text":"下列城市与其所在的省份对应正确的是____。","options":[{"key":"A","text":"洛阳--河南"},{"key":"B","text":"太原--山西"},{"key":"C","text":"南京--江西"},{"key":"D","text":"哈尔滨--黑龙江"}],"answer":["A","B","D"],"explanation":"C项南京在江苏省。"},{"id":1919,"type":"多选题","text":"杭州西湖上有白堤和苏堤两条大堤，分别是为了纪念____。","options":[{"key":"A","text":"白居易"},{"key":"B","text":"白朴"},{"key":"C","text":"苏辙"},{"key":"D","text":"苏轼"}],"answer":["A","D"],"explanation":"A项唐代诗人白居易任杭州刺史时有诗云：“最爱湖东行不足，绿杨荫里白沙堤。”即指此堤。后人为纪念这位诗人，称为白堤。D项北宋大诗人苏轼任杭州知州时，疏浚西湖，利用挖出的葑泥构筑而成的。后人为了纪念苏轼治理西湖的功绩将它命名为苏堤。"},{"id":1920,"type":"多选题","text":"宋明时期兴盛不衰的理学，又被称为____。","options":[{"key":"A","text":"新儒学"},{"key":"B","text":"性理之学"},{"key":"C","text":"心性之学"},{"key":"D","text":"陆王心学"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":1921,"type":"多选题","text":"下列诗人与其号对应正确的有____。","options":[{"key":"A","text":"陆游--放翁"},{"key":"B","text":"杨万里--诚斋"},{"key":"C","text":"白居易--乐天"},{"key":"D","text":"王安石--半山"}],"answer":["A","B","D"],"explanation":"C 项“乐天”是诗人白居易的字，号是香山居士。"},{"id":1922,"type":"多选题","text":"苏轼与____合称“三苏”。","options":[{"key":"A","text":"苏武"},{"key":"B","text":"苏迈"},{"key":"C","text":"苏辙"},{"key":"D","text":"苏洵"}],"answer":["C","D"],"explanation":"三苏是指其中的苏洵、苏轼、苏辙这三人。在唐宋时期，三苏是唐宋八大家当中的三位，其中苏洵是苏轼和苏辙的父亲，苏轼是苏辙的哥哥。"},{"id":1923,"type":"多选题","text":"成语“刮目相看”的故事中涉及下列哪些人物?","options":[{"key":"A","text":"吕蒙"},{"key":"B","text":"刘备"},{"key":"C","text":"张飞"},{"key":"D","text":"鲁肃"}],"answer":["A","D"],"explanation":"主人公是吕蒙与鲁肃。三国时期,东吴大将吕蒙原来是个大老粗,只懂厮杀,不爱读书,鲁肃因此看不起他.后来孙权说服吕蒙多读书,鲁肃再去看吕蒙,吕蒙密献对付关羽的计策,鲁肃大喜,说：“吾谓大弟但有武略耳,至于今者,学识英博,非复吴下阿蒙。”,吕蒙答道：“士别三日,即更刮目相看!”从此二人结为好友.这就是成语“士别三日当刮目相看”和“吴下阿蒙”的出处。"},{"id":1924,"type":"多选题","text":"下列作品中属周部族史诗的是____。","options":[{"key":"A","text":"《生民》"},{"key":"B","text":"《公刘》"},{"key":"C","text":"《绵》"},{"key":"D","text":"《皇矣》"}],"answer":["A","B","C","D"],"explanation":"《诗经·大雅》中《生民》、《公刘》、《绵》、《皇矣》和《大明》这五首构成了周部族史诗,这五首史诗记录了周部族发展史的几次重要的部族大事,再现了周部族发展史,具有非凡的艺术魅力"},{"id":1925,"type":"多选题","text":"明代中晚期市民⽂学的理论表现是____。","options":[{"key":"A","text":"童⼼说"},{"key":"B","text":"良知说"},{"key":"C","text":"天理说"},{"key":"D","text":"性灵说"}],"answer":["A","D"],"explanation":"明代中后期市民文学兴起,其理论表现是李贽的“童心说”和公安派“独抒性灵”口号的提出,其代表作品则有长篇小说《金瓶梅》、短篇小说集“三言”、“二拍”等。"},{"id":1926,"type":"多选题","text":"先秦诸子百家中，被称为“显学”的是____。","options":[{"key":"A","text":"儒家"},{"key":"B","text":"道家"},{"key":"C","text":"墨家"},{"key":"D","text":"法家"}],"answer":["A","C"],"explanation":"儒家是先秦诸子百家中较大的一支学派,与墨家并称“显学”。"},{"id":1927,"type":"多选题","text":"下列人物属战国时代的是____。","options":[{"key":"A","text":"老子"},{"key":"B","text":"庄子"},{"key":"C","text":"韩非"},{"key":"D","text":"荀子"}],"answer":["B","C","D"],"explanation":"老子属于春秋时代人物。"},{"id":1928,"type":"多选题","text":"下列人物属儒家学派的是____。","options":[{"key":"A","text":"孔子"},{"key":"B","text":"庄子"},{"key":"C","text":"孟子"},{"key":"D","text":"老子"}],"answer":["A","C"],"explanation":"孔子和孟子都是儒家学说的代表性任务，他们的学说被尊称为“孔孟之道”。"},{"id":1929,"type":"多选题","text":"荀子是____。","options":[{"key":"A","text":"战国后期人"},{"key":"B","text":"战国中期人"},{"key":"C","text":"法家集大成者"},{"key":"D","text":"儒家最后一位代表人物"}],"answer":["A","D"],"explanation":"荀子是战国后期人，批判地接受并创造性地发展了儒家正统的思想和理论，为传播保存儒家思想文化做出巨大贡献。"},{"id":1930,"type":"多选题","text":"“春秋三传”指____。","options":[{"key":"A","text":"《春秋》"},{"key":"B","text":"《春秋左氏传》"},{"key":"C","text":"《春秋公羊传》"},{"key":"D","text":"《春秋榖梁传》"}],"answer":["B","C","D"],"explanation":"古代“传”的意思是解读别的书的书籍。春秋三传就是解读《春秋》的书，包括《春秋左氏传》《春秋公羊传》《春秋榖梁传》。"},{"id":1931,"type":"多选题","text":"以下著作属于国别史的是____。","options":[{"key":"A","text":"《国语》"},{"key":"B","text":"《春秋》"},{"key":"C","text":"《左传》"},{"key":"D","text":"《战国策》"}],"answer":["A","D"],"explanation":"《春秋》《左传》都是编年体史书。是以年代为线索编排有关历史事件的史书。"},{"id":1932,"type":"多选题","text":"以下著作属于编年史的是____。","options":[{"key":"A","text":"《国语》"},{"key":"B","text":"《春秋》"},{"key":"C","text":"《左传》"},{"key":"D","text":"《战国策》"}],"answer":["B","C"],"explanation":"《国语》《战国策》为国别体史书，是以是一种以国家为单位，分别记叙历史事件的史书。"},{"id":1933,"type":"多选题","text":"下列作品选自《战国策》的有____。","options":[{"key":"A","text":"《苏秦始将连横说秦》"},{"key":"B","text":"《邹忌讽齐王纳谏》"},{"key":"C","text":"《触龙说赵太后》"},{"key":"D","text":"《郑伯克段于鄢》"}],"answer":["A","B","C"],"explanation":"《郑伯克段于鄢》是编年体史书《左传》的一个片段。"},{"id":1934,"type":"多选题","text":"下列作品属屈原的是____。","options":[{"key":"A","text":"《离骚》"},{"key":"B","text":"《天问》"},{"key":"C","text":"《九歌》"},{"key":"D","text":"《九辩》"}],"answer":["A","B","C"],"explanation":"《九辩》是战国时期楚国文学家宋玉创作的一首长篇抒情诗，宋玉为屈原的弟子。"},{"id":1935,"type":"多选题","text":"下列作品属组诗的是____。","options":[{"key":"A","text":"《九辩》"},{"key":"B","text":"《九歌》"},{"key":"C","text":"《九章》"},{"key":"D","text":"《招魂》"}],"answer":["B","C"],"explanation":"组诗是指由表现同一主题和采用相关题材的若干首诗所组成的一组诗篇。《九辩》、《招魂》均为单首诗歌。"},{"id":1936,"type":"多选题","text":"“汉赋四大家”包含____。","options":[{"key":"A","text":"枚乘"},{"key":"B","text":"司马相如"},{"key":"C","text":"扬雄"},{"key":"D","text":"班固"}],"answer":["B","C","D"],"explanation":"汉赋四大家包括：司马相如、扬雄、班固、张衡。"},{"id":1937,"type":"多选题","text":"司马相如的代表赋作是____。","options":[{"key":"A","text":"《长杨赋》"},{"key":"B","text":"《子虚赋》"},{"key":"C","text":"《上林赋》"},{"key":"D","text":"《哀秦二世赋》"}],"answer":["B","C","D"],"explanation":"《长杨赋》是西汉辞赋家扬雄创作的一篇赋，故排除A选项。"},{"id":1938,"type":"多选题","text":"扬雄的大赋作品有____。","options":[{"key":"A","text":"《长门赋》"},{"key":"B","text":"《甘泉赋》"},{"key":"C","text":"《河东赋》"},{"key":"D","text":"《长杨赋》"}],"answer":["B","C","D"],"explanation":"《长门赋》这是汉代文学家司马相如受汉武帝失宠皇后陈阿娇的百金重托而作的一篇骚体赋，故排除A选项。"},{"id":1939,"type":"多选题","text":"以下作品属于抒情小赋的是____。","options":[{"key":"A","text":"《吊屈原赋》"},{"key":"B","text":"《归田赋》"},{"key":"C","text":"《鹦鹉赋》"},{"key":"D","text":"《两都赋》"}],"answer":["B","C"],"explanation":"赋按体裁形式可分为骚体赋、散体大赋和抒情小赋三种。《吊屈原赋》属于骚体赋体裁，《两都赋》属于大体体裁。"},{"id":1940,"type":"多选题","text":"《史记》共分五部分，其中包括____。","options":[{"key":"A","text":"十二本纪"},{"key":"B","text":"八志"},{"key":"C","text":"十表"},{"key":"D","text":"三十世家"}],"answer":["A","C","D"],"explanation":"《史记》是中国的一部纪传体通史，被人们称为信史，由西汉武帝时期的司马迁花了13年的时间所写成的。全书共一百三十卷，约五十二万六千五百字，有十表、八书、十二本纪、三十世家、七十列传。"},{"id":1941,"type":"多选题","text":"司马迁的作品有____。","options":[{"key":"A","text":"《士不遇赋》"},{"key":"B","text":"《悲士不遇赋》"},{"key":"C","text":"《报任安书》"},{"key":"D","text":"《报孙会宗书》"}],"answer":["B","C"],"explanation":"《士不遇赋》是西汉董仲舒创作的一篇抒情赋。《报孙会宗书》是西汉杨恽写给孙会宗的一封书信。"},{"id":1942,"type":"多选题","text":"贾谊的作品有____。","options":[{"key":"A","text":"《新书》"},{"key":"B","text":"《论贵粟疏》"},{"key":"C","text":"《治安策》"},{"key":"D","text":"《论积贮疏》"}],"answer":["A","C","D"],"explanation":"《论贵粟疏》是汉代大臣晁错的文章，出自《汉书·食货志》，是当时给汉文帝的奏疏。文章全面论述了“贵粟”（重视粮食）的重要性，提出重农抑商、入粟于官、拜爵除罪等一系列主张。"},{"id":1943,"type":"多选题","text":"清代出现了官方的和民间的报纸是____。","options":[{"key":"A","text":"《京报》"},{"key":"B","text":"《宫门钞》"},{"key":"C","text":"《塘报》"},{"key":"D","text":"《辕门钞》"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":1944,"type":"多选题","text":"柳宗元的诗歌主要包括____。","options":[{"key":"A","text":"贬谪诗"},{"key":"B","text":"山水田园诗"},{"key":"C","text":"民歌体诗"},{"key":"D","text":"新乐府诗"}],"answer":["A","B"],"explanation":"柳宗元的诗作大部分作于贬官的永州、柳州时期。他诗作的重要内容就是抒写被贬谪的抑郁悲伤和思乡之情。柳宗元在贬谪期间也写过一些山水田园诗，并且试图以清静幽寂的自然境界来净化心灵，从而消除现实郁闷。民歌体诗歌则是刘禹锡的代表风格。"},{"id":1945,"type":"多选题","text":"下列作品属于志怪小说的有____。","options":[{"key":"A","text":"《博物志》"},{"key":"B","text":"《搜神记》"},{"key":"C","text":"《幽明录》"},{"key":"D","text":"《拾遗记》"}],"answer":["A","B","C","D"],"explanation":"志怪小说晋代比较有代表性的是《博物志》和《搜神记》，南北朝比较著名的是《异苑》、《幽明录》、《续齐谐记》、《拾遗记》。这些作品都对后世小说产生了一定的影响。"},{"id":1946,"type":"多选题","text":"《孔雀东南飞》的男女主人公是____。","options":[{"key":"A","text":"焦仲卿"},{"key":"B","text":"罗敷"},{"key":"C","text":"子都"},{"key":"D","text":"刘兰芝"}],"answer":["A","D"],"explanation":"《孔雀东南飞》的男主是焦仲卿,女主是刘兰芝。主要讲述了焦仲卿、刘兰芝夫妇被迫分离并双双自杀的故事,控诉了封建礼教的残酷无情,歌颂了焦刘夫妇的真挚感情和反抗精神。"},{"id":1947,"type":"多选题","text":"下列东汉乐府诗歌属乐府民歌中的爱情题材的有____。","options":[{"key":"A","text":"《艳歌行》"},{"key":"B","text":"《上邪》"},{"key":"C","text":"《有所思》"},{"key":"D","text":"《江南》"}],"answer":["B","C","D"],"explanation":"《艳歌行》是汉代乐府古辞，属《相和歌辞·瑟调曲》。此诗写游子思乡。一个普通的家庭“兄弟两三人”为了生计，流浪他乡。因女主人为他们缝补衣裳而被归来的女主人丈夫发现而产生了误会。"},{"id":1948,"type":"多选题","text":"下列作家属“建安七子”的有____。","options":[{"key":"A","text":"王粲"},{"key":"B","text":"刘桢"},{"key":"C","text":"徐干"},{"key":"D","text":"曹植"}],"answer":["A","B","C"],"explanation":"“建安七子”包括孔融、陈琳、王粲、徐干、阮瑀、应玚、刘桢。这七人大体上代表了建安时期除曹氏父子（即曹操、曹丕、曹植）外的文学成就。"},{"id":1949,"type":"多选题","text":"下列作品属曹操的有____。","options":[{"key":"A","text":"《燕歌行》"},{"key":"B","text":"《蒿里行》"},{"key":"C","text":"《短歌行》"},{"key":"D","text":"《步出夏门行》"}],"answer":["B","C","D"],"explanation":"《燕歌行》是唐代诗人高适的诗作。此诗概括一般的边塞战争，主要是揭露主将骄逸轻敌，不恤士卒，致使战事失利。"},{"id":1950,"type":"多选题","text":"下列作品属陶渊明辞赋的有____。","options":[{"key":"A","text":"《归去来兮辞》"},{"key":"B","text":"《登楼赋》"},{"key":"C","text":"《闲情赋》"},{"key":"D","text":"《归园田居》"}],"answer":["A","C"],"explanation":"《登楼赋》是东汉文学家王粲的赋作，而《归园田居》属于陶渊明的组诗，而非辞赋。"},{"id":1951,"type":"多选题","text":"骈文的主要特征是____。","options":[{"key":"A","text":"对偶"},{"key":"B","text":"夸饰"},{"key":"C","text":"用典"},{"key":"D","text":"声律"}],"answer":["A","C","D"],"explanation":"骈文的特点主要有：讲究声律的调谐、用字的绮丽、辞汇的对偶和用典。"},{"id":1952,"type":"多选题","text":"韩愈散文包括多种文体，其中有____。","options":[{"key":"A","text":"杂文"},{"key":"B","text":"赠序文"},{"key":"C","text":"稗志"},{"key":"D","text":"传记"}],"answer":["A","B","C","D"],"explanation":"韩愈散文包括多种文体，其中有杂文、赠序文、稗志和传记。"},{"id":1953,"type":"多选题","text":"下列说法正确的是____。","options":[{"key":"A","text":"《世说新语》记述了汉末至东晋的士族阶层的遗闻轶事，特别是士族人物的清谈"},{"key":"B","text":"《世说新语》是中国魏晋南北朝时期“笔记小说”的代表作"},{"key":"C","text":"《世说新语》的作者是干宝"},{"key":"D","text":"《世说新语》是一部志人小说"}],"answer":["A","B","D"],"explanation":"C选项《世说新语》的作者是刘义庆。"},{"id":1954,"type":"多选题","text":"唐代传奇的创作特点主要有____。","options":[{"key":"A","text":"人物形象栩栩如生"},{"key":"B","text":"故事情节曲折，引人入胜"},{"key":"C","text":"语言华美，凝练传神"},{"key":"D","text":"题材丰富多彩"}],"answer":["A","B","C","D"],"explanation":"从艺术上看，唐代传奇在人物描写、情节安排和语言运用等方面都取得了巨大的成就，标志着中国古代小说艺术的渐趋成熟。\n（1）在人物描写方面，唐传奇善于通过对话和行动的具体描绘来表现人物的性格特征；善于通过对比、烘托，使人物形象更加丰满；善于运用细节描写、肖像描写和心理刻画，更细致深入地展现人物性格的复杂性，等等。因此，唐传奇塑造了众多的，栩栩如生的人物形象。（2）在情节结构的安排方面，不少唐传奇都做到了波澜起伏，严密完整，引人入胜；\n（3）在语言运用方面，唐传奇主要用散体古文，兼用通俗口语和骈文技巧，并大量插入诗歌，具有华实相扶、凝练传神的特点。\n（4）唐传奇题材丰富，美不胜收。唐传奇是我国文学史上有意识的写作小说的开始，它的产生，标志着中国小说的发展已渐趋成熟。"},{"id":1955,"type":"多选题","text":"下列作家属盛唐边塞诗人的是____。","options":[{"key":"A","text":"孟浩然"},{"key":"B","text":"高适"},{"key":"C","text":"岑参"},{"key":"D","text":"王之涣"}],"answer":["B","C","D"],"explanation":"孟浩然是唐代山水田园诗人。"},{"id":1956,"type":"多选题","text":"下列作品属岑参的有____。","options":[{"key":"A","text":"《白雪歌送武判官归京》"},{"key":"B","text":"《走马川行奉送出师西征》"},{"key":"C","text":"《燕歌行》（汉家烟尘）"},{"key":"D","text":"《逢人京使》"}],"answer":["A","B","D"],"explanation":"《燕歌行》（汉家烟尘）为高适作品。"},{"id":1957,"type":"多选题","text":"下列属李白的作品有____。","options":[{"key":"A","text":"《蜀道难》"},{"key":"B","text":"《登高》"},{"key":"C","text":"《行路难》（金樽清酒斗十千）"},{"key":"D","text":"《将进酒君不见）"}],"answer":["A","C","D"],"explanation":"《登高》是唐代诗人杜甫的诗作。故排除B选项。"},{"id":1958,"type":"多选题","text":"下列属杜甫的作品有____。","options":[{"key":"A","text":"《自京赴奉先县咏怀五百字》"},{"key":"B","text":"“三吏”、“三别”"},{"key":"C","text":"《梦游天姥吟留别》"},{"key":"D","text":"《茅屋为秋风所破歌》"}],"answer":["A","B","D"],"explanation":"《梦游天姥吟留别》是唐代诗人李白的诗作。故排除C选项。"},{"id":1959,"type":"多选题","text":"下列作品属李白的诗篇是____。","options":[{"key":"A","text":"《望庐山瀑布》"},{"key":"B","text":"《望天门山》"},{"key":"C","text":"《江畔独步寻花》"},{"key":"D","text":"《黄鹤楼送孟浩然之广陵》"}],"answer":["A","B","D"],"explanation":"《江畔独步寻花七绝句》是唐代诗人杜甫的组诗作品，共有七首。"},{"id":1960,"type":"多选题","text":"构成“汉字⽂化圈”的要素有____。","options":[{"key":"A","text":"汉字"},{"key":"B","text":"儒学"},{"key":"C","text":"道教"},{"key":"D","text":"律令制度"}],"answer":["A","B","D"],"explanation":"汉字文化圈为文化圈的概念之一。日本学者西嶋定生（1919－1988）给出的“汉字文化圈”的构成要素是：以汉字为传意媒介，以儒家为思想伦理基础，以律令制为法政体制，以汉传佛教为宗教信仰等等作为共同的价值标准。"},{"id":1961,"type":"多选题","text":"下列属“元白诗派“的有____。","options":[{"key":"A","text":"元稹"},{"key":"B","text":"白居易"},{"key":"C","text":"姚合"},{"key":"D","text":"王建"}],"answer":["A","B","D"],"explanation":"元白诗派：重写实，尚通俗，主要代表人物是白居易、元稹、王建、张籍等。"},{"id":1962,"type":"多选题","text":"白居易把自己的诗歌分为四类，其中包括____。","options":[{"key":"A","text":"讽喻诗"},{"key":"B","text":"乐府诗"},{"key":"C","text":"感伤诗"},{"key":"D","text":"闲适诗"}],"answer":["A","C","D"],"explanation":"白居易曾把自己的诗分为四类：讽喻诗、闲适诗、感伤诗、杂律诗。"},{"id":1963,"type":"多选题","text":"韩愈提出的文学主张有____。","options":[{"key":"A","text":"“文以明道”"},{"key":"B","text":"“唯陈言之务去”"},{"key":"C","text":"“汉魏风骨”、“风雅寄兴”"},{"key":"D","text":"“不平则鸣”"}],"answer":["A","B","D"],"explanation":"C项初唐杰出诗人陈子昂于他的《与东方左史虬修竹篇序》中明确提出了风雅兴寄和汉魏风骨的诗歌主张."},{"id":1964,"type":"多选题","text":"下列诗歌中属于李商隐作品的是____。","options":[{"key":"A","text":"《无题二首》"},{"key":"B","text":"《锦瑟》"},{"key":"C","text":"《无题》"},{"key":"D","text":"《夜雨寄北》"}],"answer":["A","B","C","D"],"explanation":"以上四首均是李商隐所作。"},{"id":1965,"type":"多选题","text":"晚唐继承新乐府写实批判精神的诗人有____。","options":[{"key":"A","text":"韦庄"},{"key":"B","text":"聂夷中"},{"key":"C","text":"杜荀鹤"},{"key":"D","text":"温庭筠"}],"answer":["B","C"],"explanation":"除了皮日休,继承元、白新乐府写实批判精神的晚唐诗人,还有聂夷中(837--884)、杜荀鹤(846--907)、罗隐(833--909)等,他们忧时忧民,用诗歌揭露尖锐的社会矛盾,语言质朴浅近。"},{"id":1966,"type":"多选题","text":"宋初诗坛流行的诗歌流派主要有____。","options":[{"key":"A","text":"白体"},{"key":"B","text":"西昆体"},{"key":"C","text":"晚唐体"},{"key":"D","text":"馆阁体"}],"answer":["A","B","C"],"explanation":"宋初诗派林立,但主要有白体、西昆体、晚唐体三派。"},{"id":1967,"type":"多选题","text":"下列作家属于北宋初期的有____。","options":[{"key":"A","text":"柳开"},{"key":"B","text":"王禹僵"},{"key":"C","text":"杨亿"},{"key":"D","text":"白居易"}],"answer":["A","B","C"],"explanation":"白居易是唐代伟大的现实主义诗人，故排除D选项。"},{"id":1968,"type":"多选题","text":"黄庭坚著名的文论观点有____。","options":[{"key":"A","text":"点铁成金"},{"key":"B","text":"夺胎换骨"},{"key":"C","text":"别材别趣"},{"key":"D","text":"别是一家"}],"answer":["A","B"],"explanation":"黄庭坚诗歌理论中最著名的主张是:“夺胎换骨”、“点铁成金”。 即或师承前人之辞、或师承前人之意的一种方法,目的是要在诗歌创作中“以故为新”。"},{"id":1969,"type":"多选题","text":"下列关于苏轼的描述正确的是____。","options":[{"key":"A","text":"宋代文学发展到巅峰时期的伟大代表作家"},{"key":"B","text":"宋代古文家里最重视“文”的一位"},{"key":"C","text":"苏轼是婉约派的代表词人"},{"key":"D","text":"对宋诗能别开生面起关键作用的作家"}],"answer":["A","B","D"],"explanation":"苏轼代表的是豪放派。"},{"id":1970,"type":"多选题","text":"下列作家中，属于南宋“中兴四大诗人”的有____。","options":[{"key":"A","text":"伟大的爱国主义诗人陆游"},{"key":"B","text":"江湖诗人中成就最高的刘克庄"},{"key":"C","text":"爱国诗人文天祥"},{"key":"D","text":"擅写“活法”诗的杨万里"}],"answer":["A","D"],"explanation":"南宋“中兴四大诗人”包括尤袤、杨万里、范成大、陆游。"},{"id":1971,"type":"多选题","text":"下列作家属于辛派词人的有____。","options":[{"key":"A","text":"朱敦儒"},{"key":"B","text":"吴文英"},{"key":"C","text":"陈亮"},{"key":"D","text":"刘过"}],"answer":["C","D"],"explanation":"辛派词人指的是南渡前后词风与辛弃疾相似或相近的作家。既包括早于辛弃疾的南渡初期作家张元干、颖孝祥等，也包括和辛弃疾同时或后于辛弃疾在作词方面追步辛弃疾的作家陈亮、刘过等人。"},{"id":1972,"type":"多选题","text":"下列关于吴文英的描述正确的是____。","options":[{"key":"A","text":"《梦窗词》的作者"},{"key":"B","text":"在南宋词坛与辛弃疾、姜夔鼎足而三的作家"},{"key":"C","text":"在讲究字面漂亮和章法绵密方面，是周邦彦的继承者"},{"key":"D","text":"是姜夔的羽翼"}],"answer":["A","B","C"],"explanation":"D项史达祖可称姜夔的羽翼。"},{"id":1973,"type":"多选题","text":"楚⽂化的特点有____。","options":[{"key":"A","text":"崇凤"},{"key":"B","text":"拜火"},{"key":"C","text":"尚东"},{"key":"D","text":"尊左"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":1974,"type":"多选题","text":"下列前期元杂剧中属于历史剧的有____。","options":[{"key":"A","text":"《梧桐雨》"},{"key":"B","text":"《西厢记》"},{"key":"C","text":"《汉宫秋》"},{"key":"D","text":"《墙头马上》"}],"answer":["A","C"],"explanation":"《西厢记》和《墙头马上》都是元朝冲破封建礼教，追求自由恋爱的爱情剧，并非历史剧。"},{"id":1975,"type":"多选题","text":"下列赋作属于扬雄的有____。","options":[{"key":"A","text":"《长杨赋》"},{"key":"B","text":"《河东赋》"},{"key":"C","text":"《甘泉赋》"},{"key":"D","text":"《逐贫赋》"}],"answer":["A","B","C","D"],"explanation":"扬雄年轻时喜好辞赋，初入京师，便接连上奏《甘泉赋》、《河东赋》、《校猎赋》（又称《羽猎赋》）、《长杨赋》。"},{"id":1976,"type":"多选题","text":"下列作品中元代四大传奇有____。","options":[{"key":"A","text":"《荆钗记》"},{"key":"B","text":"《白兔记》"},{"key":"C","text":"《拜月亭记》"},{"key":"D","text":"《杀狗记》"}],"answer":["A","B","C","D"],"explanation":"元代四大传奇包括《荆钗记》、《拜月亭记》、《白兔记》、《杀狗记》，时人以传奇称之。"},{"id":1977,"type":"多选题","text":"中国戏曲角色的基本行是指____。","options":[{"key":"A","text":"生"},{"key":"B","text":"旦"},{"key":"C","text":"净"},{"key":"D","text":"末"}],"answer":["A","B","C"],"explanation":"戏曲行当的名称。戏曲角色的分行十分细致，早先分为十行，后来才归并为生旦净丑四行。"},{"id":1978,"type":"多选题","text":"下列作家属于唐宋派的有____。","options":[{"key":"A","text":"张岱"},{"key":"B","text":"唐顺之"},{"key":"C","text":"茅坤"},{"key":"D","text":"归有光"}],"answer":["B","C","D"],"explanation":"张岱是明末清初史学家、文学家。"},{"id":1979,"type":"多选题","text":"陶渊明今传散文有____。","options":[{"key":"A","text":"《兰亭集序》"},{"key":"B","text":"《五柳先生传》"},{"key":"C","text":"《桃花源记》"},{"key":"D","text":"《晋故征西大将军长史孟府君传》"}],"answer":["B","C","D"],"explanation":"陶渊明今传散文有《五柳先生传》、《桃花源记》、《晋故征西大将军长史孟府君传》、《与子俨等书》。"},{"id":1980,"type":"多选题","text":"韩愈古文运动的理论主张有____。","options":[{"key":"A","text":"文以明道"},{"key":"B","text":"惟陈言之务去"},{"key":"C","text":"不平则鸣"},{"key":"D","text":"用事绵密"}],"answer":["A","B","C"],"explanation":"韩愈在贞元九年（793）所写的《争臣论》中，第一次提出“文以明道”的观念，从而确定了“古文”创作的指导思想。从“明道”的要求出发，韩愈特别强调“惟陈言之务去”的重要性。在具体的创作实践中，他又提出了“不平则鸣”（《送孟东野序》）的口号。这一看法，把“明道”与对现实的批判联系了起来。"},{"id":1981,"type":"多选题","text":"唐代传奇在艺术上的主要特点有____。","options":[{"key":"A","text":"善于描写人物性格"},{"key":"B","text":"情节波澜起伏，引人入胜"},{"key":"C","text":"语言华实相扶，凝炼传神"},{"key":"D","text":"插入诗歌"}],"answer":["A","B","C","D"],"explanation":"（1）从艺术上看，唐代传奇在人物描写、情节安排和语言运用等方面都取得了巨大的成就，标志着中国古代小说艺术的渐趋成熟；\n（2）在人物描写方面，唐传奇善于通过对话和行动的具体描绘来表现人物的性格特征；在情节结构的安排方面，不少唐传奇都做到了波澜起伏，严密完整，引人入胜；\n（3）在语言运用方面，唐传奇主要用散体古文，兼用通俗口语和骈文技巧，并大量插入诗歌，具有华实相扶、凝练传神的特点。"},{"id":1982,"type":"多选题","text":"北宋瓦舍表演中，最能体现市民⼝味的表演形式是____。","options":[{"key":"A","text":"蹴鞠"},{"key":"B","text":"武术"},{"key":"C","text":"⽪影"},{"key":"D","text":"杂剧"}],"answer":["A","D"],"explanation":"瓦舍勾栏是当时市民娱乐时候最主要去的场所,也是宋朝市民文化兴盛的一种体现。瓦舍勾栏时演出的内容很多,形式也多种多样,主要有说唱、戏剧、杂技和武术等等。"},{"id":1983,"type":"多选题","text":"李贺诗歌的艺术特点包括____。","options":[{"key":"A","text":"造语奇丽"},{"key":"B","text":"偏爱描写鬼魂"},{"key":"C","text":"诗风怪奇"},{"key":"D","text":"主观色彩强烈"}],"answer":["A","B","C","D"],"explanation":"李贺诗歌的艺术特点包括造语奇丽、偏爱描写鬼魂、诗风怪奇、主观色彩强烈。"},{"id":1984,"type":"多选题","text":"19世纪末以来中国文化在现代化的过程中，存在着____等文化思潮的互动。","options":[{"key":"A","text":"全盘西化论"},{"key":"B","text":"中体西化论"},{"key":"C","text":"综合创新论"},{"key":"D","text":"儒学复兴论与综合创新论"}],"answer":["A","B","D"],"explanation":"综合创新论是多民族文化融合与中外文化交汇。这并不是中国文化在现代化的思潮互动。"},{"id":1985,"type":"多选题","text":"《诗经》的下列诗篇属于史诗的有____。","options":[{"key":"A","text":"《生民》"},{"key":"B","text":"《公刘》"},{"key":"C","text":"《绵》"},{"key":"D","text":"《皇矣》"}],"answer":["A","B","C","D"],"explanation":"《诗经》的下列诗篇属于史诗的有《生民》《公刘》《绵》《皇矣》《大明》。"},{"id":1986,"type":"多选题","text":"下列赋作属于“汉大赋”的有____。","options":[{"key":"A","text":"贾谊《旱云赋》"},{"key":"B","text":"扬雄《羽猎赋》"},{"key":"C","text":"司马相如《上林赋》"},{"key":"D","text":"班固《两都赋》"}],"answer":["B","C","D"],"explanation":"赋作属于“汉大赋”的有扬雄《羽猎赋》司马相如《上林赋》和班固《两都赋》。"},{"id":1987,"type":"多选题","text":"元稹诗歌内容广阔，形式多样，主要包括____。","options":[{"key":"A","text":"新乐府诗"},{"key":"B","text":"山水诗"},{"key":"C","text":"悼亡诗"},{"key":"D","text":"酬唱诗"}],"answer":["A","C","D"],"explanation":"元稹诗歌内容广阔，形式多样，主要包括新乐府诗、悼亡诗、酬唱诗。"},{"id":1988,"type":"多选题","text":"标志着明代传奇根本性转变的三大传奇作品是____。","options":[{"key":"A","text":"《宝剑记》"},{"key":"B","text":"《鸣凤记》"},{"key":"C","text":"《浣纱记》"},{"key":"D","text":"《娇红记》"}],"answer":["A","B","C"],"explanation":"李开先的《宝剑记》，梁辰鱼的《浣纱记》，王士贞的《鸣凤记》是明中期传奇著名的“三大传奇”，标志着传奇的成熟，也标志着传奇的兴盛。"},{"id":1989,"type":"多选题","text":"下列人物，属于《儒林外史》中潇洒士人的有____。","options":[{"key":"A","text":"匡超人"},{"key":"B","text":"杜少卿"},{"key":"C","text":"王冕"},{"key":"D","text":"范进"}],"answer":["B","C"],"explanation":"A项匡超人在小说中从纯朴善良到人格沦丧，一步一步地走向堕落。D项范进是一个热衷功名、懦弱迂腐、圆滑世故的典型儒生形象。"},{"id":1990,"type":"多选题","text":"下列人物属于《桃花扇》的有____。","options":[{"key":"A","text":"李香君"},{"key":"B","text":"席方平"},{"key":"C","text":"阮大铖"},{"key":"D","text":"侯方域"}],"answer":["A","C","D"],"explanation":"《席方平》是清代文学家蒲松龄创作的文言短篇小说，席方平是其主人公。"},{"id":1991,"type":"多选题","text":"下列戏剧大家属于清代前期的有____。","options":[{"key":"A","text":"李玉"},{"key":"B","text":"李渔"},{"key":"C","text":"洪昇"},{"key":"D","text":"汤显祖"}],"answer":["A","B","C"],"explanation":"汤显祖是中国明代戏曲家、文学家。"},{"id":1992,"type":"多选题","text":"下列作家属于桐城派的有____。","options":[{"key":"A","text":"陈维崧"},{"key":"B","text":"姚鼐"},{"key":"C","text":"方苞"},{"key":"D","text":"刘大櫆"}],"answer":["B","C","D"],"explanation":"姚鼐与方苞、刘大櫆并称为“桐城派三祖”。"},{"id":1993,"type":"多选题","text":"中国汉字艺术主要包括____。","options":[{"key":"A","text":"扇面艺术"},{"key":"B","text":"书法艺术"},{"key":"C","text":"碑贴艺术"},{"key":"D","text":"玺印艺术"}],"answer":["B","D"],"explanation":"中国汉字艺术主要包括书法艺术玺印艺术。"},{"id":1994,"type":"多选题","text":"明代至清代中期（1840年前）的文学名著主要有____。","options":[{"key":"A","text":"《三国演义》"},{"key":"B","text":"《水浒传》"},{"key":"C","text":"《红楼梦》"},{"key":"D","text":"《永乐大典》"}],"answer":["A","B","C"],"explanation":"《永乐大典》是明永乐年间一部集中国古代典籍于大成的类书，是中国最大的一部类书，明代官修的大型综合性类书，不是文学名著，因此排除D选项。"},{"id":1995,"type":"多选题","text":"“文”的本义是指各色交错的纹理，其后来的引申意义有____。","options":[{"key":"A","text":"引申为文字、文章"},{"key":"B","text":"引申为古代的礼乐制度，在此基础上又引申为法令条文"},{"key":"C","text":"引申为精神修养，在此基础上又引申为文彩"},{"key":"D","text":"引申为美、善、德行之义"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":1996,"type":"多选题","text":"夏商周时期中国传统文化的主要标志有____。","options":[{"key":"A","text":"创造了甲骨文与金文"},{"key":"B","text":"宗法制度和家国同构政治结构的形成"},{"key":"C","text":"诸子蜂起，百家争鸣"},{"key":"D","text":"初步形成传统伦理道德思想"}],"answer":["A","B","D"],"explanation":"诸子蜂起，百家争鸣不是夏商周时期中国传统文化的主要标志。"},{"id":1997,"type":"多选题","text":"春秋战国时期中国传统文化的主要标志有____。","options":[{"key":"A","text":"天命神权思想和阴阳五行学说的产生"},{"key":"B","text":"诸子蜂起，百家争鸣"},{"key":"C","text":"儒家经典的初步形成和传统伦理道德思想的发展"},{"key":"D","text":"科技文化的成就杰出"}],"answer":["B","C","D"],"explanation":"天命神权思想和阴阳五行学说的产生不是春秋战国时期中国传统文化的主要标志。"},{"id":1998,"type":"多选题","text":"秦汉时期中国传统文化的主要标志有____。","options":[{"key":"A","text":"儒家经典的初步形成和传统伦理道德思想的发展"},{"key":"B","text":"王充著《论衡》"},{"key":"C","text":"基本形成以儒家为核心的传统文化模式"},{"key":"D","text":"佛教的传入和道教的产生"}],"answer":["C","D"],"explanation":"秦汉时期中国传统文化的主要标志有基本形成以儒家为核心的传统文化模式、佛教的传入和道教的产生。"},{"id":1999,"type":"多选题","text":"魏晋南北朝时期中国传统文化的主要标志是____。","options":[{"key":"A","text":"佛教的传入和道教的产生"},{"key":"B","text":"道教的完善与佛教的传播"},{"key":"C","text":"玄学的兴起"},{"key":"D","text":"儒学的繁荣"}],"answer":["B","C"],"explanation":"魏晋南北朝时期中国传统文化的主要标志是道教的完善与佛教的传播、玄学的兴起。"},{"id":2000,"type":"多选题","text":"魏晋南北朝时期文学成就的主要标志有____。","options":[{"key":"A","text":"以曹操父子、建安七子为代表的建安文学"},{"key":"B","text":"陶渊明为代表的田园、山水诗"},{"key":"C","text":"赋与五言古诗"},{"key":"D","text":"刘勰《文心雕龙》为代表的文学评论"}],"answer":["A","B","D"],"explanation":"赋与五言古诗不是魏晋南北朝时期文学成就的主要标志。"},{"id":2001,"type":"多选题","text":"明代至清代中期（1840年前）的科技成果主要有____。","options":[{"key":"A","text":"李时珍的《本草纲目》"},{"key":"B","text":"徐光启的《农政全书》"},{"key":"C","text":"宋应星的《天工开物》"},{"key":"D","text":"《徐霞客游记》"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2002,"type":"多选题","text":"中国古人避讳的方式有____。","options":[{"key":"A","text":"拆字"},{"key":"B","text":"用同义字代替"},{"key":"C","text":"用同音字代替"},{"key":"D","text":"缺笔"}],"answer":["A","B","C","D"],"explanation":"避讳的方法有四种：\n1. 改字法：就是把帝王及所尊者之名改用其他同义字或同音字来代替。\n2. 空字法：即将应避讳的字空而不书，或作“某”，或作“口”。\n3. 缺笔法：即对所避之字少写一笔。但少写的一笔在什么地方是有严格规定的。\n4. 改音法：就是读书时遇到讳字，应改变声调或读别的字音。"},{"id":2003,"type":"多选题","text":"《周易》建构了中国伦理精神的原初的哲学模式，即____。","options":[{"key":"A","text":"天人合一的宇宙论体系"},{"key":"B","text":"“自强不息”、“厚德载物”的精神"},{"key":"C","text":"善恶报应的信念"},{"key":"D","text":"阴阳二分的思维方式"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2004,"type":"多选题","text":"墨家主张____。","options":[{"key":"A","text":"“节用”"},{"key":"B","text":"“节葬”"},{"key":"C","text":"“非攻”"},{"key":"D","text":"法治"}],"answer":["A","B","C"],"explanation":"墨家不主张法治。"},{"id":2005,"type":"多选题","text":"王夫之的主要哲学著作有____。","options":[{"key":"A","text":"《周易外传》"},{"key":"B","text":"《尚书引义》"},{"key":"C","text":"《明儒学案》"},{"key":"D","text":"《读四书大全说》"}],"answer":["A","B","D"],"explanation":"《明儒学案》不是王夫之的哲学著作。"},{"id":2006,"type":"多选题","text":"董仲舒天人感应说的要点有____。","options":[{"key":"A","text":"神学的灾异谴告说"},{"key":"B","text":"“天人同类”、“天人相副”说"},{"key":"C","text":"人性论"},{"key":"D","text":"“三纲五常”"}],"answer":["A","B"],"explanation":"董仲舒天人感应说的要点有神学的灾异谴告说、“天人同类”、“天人相副”说"},{"id":2007,"type":"多选题","text":"王夫之在历史观方面系统批判了历代史学中弥漫着的____。","options":[{"key":"A","text":"神学史观"},{"key":"B","text":"复古谬论"},{"key":"C","text":"厚今薄古"},{"key":"D","text":"进化论"}],"answer":["A","B"],"explanation":"王夫之在历史观方面系统批判了历代史学中弥漫着的神学史观、复古谬论。"},{"id":2008,"type":"多选题","text":"人本主义精神主要包括____层次。","options":[{"key":"A","text":"以民为本"},{"key":"B","text":"重人伦远鬼神"},{"key":"C","text":"肯定个体的心性向善"},{"key":"D","text":"重义轻利"}],"answer":["A","B","C"],"explanation":"人本主义精神不包括重义轻利层次。"},{"id":2009,"type":"多选题","text":"春秋战国时期史学领域的成就主要有____。","options":[{"key":"A","text":"《春秋》及其三传"},{"key":"B","text":"《国语》"},{"key":"C","text":"《华阳国志》"},{"key":"D","text":"《战国策》"}],"answer":["A","B","D"],"explanation":"春秋战国时期史学领域的成就不包括《华阳国志》。《华阳国志》又名《华阳国记》，地方志著作，是由东晋时期成汉常璩撰写于晋穆帝永和四年至永和十年（348年—354年）的一部专门记述古代中国西南地区地方历史、地理、人物等的地方志著作。"},{"id":2010,"type":"多选题","text":"魏晋南北朝时期文学领域的成就主要有____。","options":[{"key":"A","text":"曹操父子、建安七子为代表的建安文学"},{"key":"B","text":"陶渊明为代表的田园、山水诗"},{"key":"C","text":"乐府诗"},{"key":"D","text":"刘勰《文心雕龙》为代表的文学评论"}],"answer":["A","B","D"],"explanation":"魏晋南北朝时期文学领域的成果不包括乐府诗。"},{"id":2011,"type":"多选题","text":"魏晋南北朝时期科技领域的成果主要有____。","options":[{"key":"A","text":"刘徽的《九章算术注》"},{"key":"B","text":"祖冲之计算出的圆周率和编制的《大明历》"},{"key":"C","text":"造纸术"},{"key":"D","text":"贾思勰的《齐民要术》"}],"answer":["A","B","D"],"explanation":"魏晋南北朝时期科技领域的成果不包括造纸术。"},{"id":2012,"type":"多选题","text":"隋唐时期科技领域的重要成就主要有____。","options":[{"key":"A","text":"雕版印刷术的发明"},{"key":"B","text":"刘焯的《皇极历》"},{"key":"C","text":"孙思邈的《千金方》和《千金翼方》"},{"key":"D","text":"僧一行等制作的黄道游仪和实测子午线"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2013,"type":"多选题","text":"孔子以后，孟子从主观能动的方面发挥了孔子的伦理思想，提出了____。","options":[{"key":"A","text":"五伦说"},{"key":"B","text":"性善论"},{"key":"C","text":"修养论"},{"key":"D","text":"义利合一说"}],"answer":["A","B","C"],"explanation":"孔子以后，孟子从主观能动的方面发挥了孔子的伦理思想，其中不包括义利合一说。"},{"id":2014,"type":"多选题","text":"宋元时期史学领域的代表作有____。","options":[{"key":"A","text":"《资治通鉴》"},{"key":"B","text":"《通鉴纪事本末》"},{"key":"C","text":"《通典》"},{"key":"D","text":"《文献通考》"}],"answer":["A","B","C"],"explanation":"《文献通考》不是宋元时期史学领域的代表作。"},{"id":2015,"type":"多选题","text":"董仲舒把人性分____。","options":[{"key":"A","text":"“君子之性”"},{"key":"B","text":"“中民之性”"},{"key":"C","text":"“斗筲之性”"},{"key":"D","text":"“圣人之性”"}],"answer":["B","C","D"],"explanation":"董仲舒把人性分“中民之性” 、“斗筲之性”、“圣人之性”。"},{"id":2016,"type":"多选题","text":"中国优秀传统伦理道德规范包括____。","options":[{"key":"A","text":"公忠爱国"},{"key":"B","text":"三从四德"},{"key":"C","text":"三纲"},{"key":"D","text":"仁爱孝悌"}],"answer":["A","D"],"explanation":"中国优秀传统伦理道德规范包括公忠爱国、仁爱孝悌"},{"id":2017,"type":"多选题","text":"孝悌之德的基本内容是____。","options":[{"key":"A","text":"父慈子孝"},{"key":"B","text":"兄友弟恭"},{"key":"C","text":"中和宽容"},{"key":"D","text":"谦虚好礼"}],"answer":["A","B"],"explanation":"孝悌之德的基本内容是父慈子孝、兄友弟恭。"},{"id":2018,"type":"多选题","text":"我国原始宗教有很多分野，总的来讲，主要有____。","options":[{"key":"A","text":"自然崇拜"},{"key":"B","text":"动植物崇拜"},{"key":"C","text":"图腾崇拜"},{"key":"D","text":"圣贤崇拜"}],"answer":["A","B","C"],"explanation":"我国原始宗教有很多分野，不包括圣贤崇拜。"},{"id":2019,"type":"多选题","text":"孟子所谓的“四德”有____。","options":[{"key":"A","text":"仁"},{"key":"B","text":"礼"},{"key":"C","text":"信"},{"key":"D","text":"义"}],"answer":["A","B","D"],"explanation":"儒家孟子提出“四德”，即“仁”，“义”，“礼”，“智”。"},{"id":2020,"type":"多选题","text":"封建正统法律思想的内容主要有____。","options":[{"key":"A","text":"则天顺时，法自君出"},{"key":"B","text":"礼律结合，法有差等"},{"key":"C","text":"德主刑辅，先教后刑"},{"key":"D","text":"据经解律，引经决狱"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2021,"type":"多选题","text":"孟子的道德修养论，是通过____等修养方法，把有的人失去的善性再找回来。","options":[{"key":"A","text":"反省"},{"key":"B","text":"养气"},{"key":"C","text":"存心"},{"key":"D","text":"内求"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2022,"type":"多选题","text":"道家宣扬“清静无为”的“出世”思想和悲观厌世的人生观，主张____，崇尚自然、柔弱、知足。","options":[{"key":"A","text":"无知"},{"key":"B","text":"无欲"},{"key":"C","text":"无为"},{"key":"D","text":"尚贤"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2023,"type":"多选题","text":"孔子将修身称为____。","options":[{"key":"A","text":"“修德”"},{"key":"B","text":"“克己”"},{"key":"C","text":"“正身”"},{"key":"D","text":"“修己”"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2024,"type":"多选题","text":"东汉时期，早期道教派别____相继出现，标志着道教的正式诞生。","options":[{"key":"A","text":"全真道"},{"key":"B","text":"五斗米道"},{"key":"C","text":"正一道"},{"key":"D","text":"太平道"}],"answer":["B","D"],"explanation":"道教正式创立于东汉末年，其标志是太平道和五斗米道的出现。"},{"id":2025,"type":"多选题","text":"____是中国佛教石窟的代表。","options":[{"key":"A","text":"敦煌莫高窟"},{"key":"B","text":"云冈石窟"},{"key":"C","text":"龙门石窟"},{"key":"D","text":"大足石窟"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2026,"type":"多选题","text":"____是《开皇律》确定的刑名。","options":[{"key":"A","text":"死刑"},{"key":"B","text":"流刑"},{"key":"C","text":"肉刑"},{"key":"D","text":"徒刑"}],"answer":["A","B","D"],"explanation":"《开皇律》删除了魏晋以来一些残酷的刑罚,确立了封建时代比较进步的五种刑名: 答 、杖、徒、流、死。"},{"id":2027,"type":"多选题","text":"玄学以____为主要依据企图用道家学说调整失衡的社会关系和伦理关系，其宗旨是“贵无” ,崇尚自然。","options":[{"key":"A","text":"《孟子》"},{"key":"B","text":"《周易》"},{"key":"C","text":"《老子》"},{"key":"D","text":"《庄子》"}],"answer":["B","C","D"],"explanation":"玄学没有以《孟子》为主要依据企图用道家学说调整失衡的社会关系和伦理关系，其宗旨是“贵无” ,崇尚自然。"},{"id":2028,"type":"多选题","text":"忠恕之德的基本要求是____。","options":[{"key":"A","text":"以诚待人"},{"key":"B","text":"推己及人"},{"key":"C","text":"相互尊重"},{"key":"D","text":"相互同情"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2029,"type":"多选题","text":"中国传统文化的形成有两个重要的基础，即____。","options":[{"key":"A","text":"小农自然经济的生产方式"},{"key":"B","text":"礼制"},{"key":"C","text":"家国一体"},{"key":"D","text":"儒家思想"}],"answer":["A","C"],"explanation":"中国传统文化的形成有两个重要的基础；一是小农自给经济的生产方式；二是家国一体，即由家及国的宗法社会政治结构。\n在这个基础上产生的必然是以伦理道德为核心的文化价值系统。"},{"id":2030,"type":"多选题","text":"中国古人典型的宇宙观有____。","options":[{"key":"A","text":"天人合一"},{"key":"B","text":"天人交胜"},{"key":"C","text":"天人相分"},{"key":"D","text":"天人之分"}],"answer":["A","B","D"],"explanation":"天人相分论，亦即认为“天”与“人”是两个互相独立的个体，都具有客观运行的规律，但无法互相干涉。不是中国古人的宇宙观。"},{"id":2031,"type":"多选题","text":"战国时期的诸子百家中，影响最大的学派有____。","options":[{"key":"A","text":"法家"},{"key":"B","text":"名家"},{"key":"C","text":"儒家"},{"key":"D","text":"道家"}],"answer":["A","C","D"],"explanation":"战国时期思想文化领域的繁荣局面被称为百家争鸣，春秋战国时期，社会急剧变化，许多问题亟待解决，各学派纷纷著书立说，发表意见，并相互辩论，形成了“百家争鸣”的学术繁荣局面。这一时期出现了许多学派如儒家、道家、法家、墨家、兵家等，其中对后世影响最大的是儒家、道家、法家、墨家。"},{"id":2032,"type":"多选题","text":"《学记》关于教育教学的原则有____。","options":[{"key":"A","text":"预防性原则"},{"key":"B","text":"及时施教原则"},{"key":"C","text":"长善救失原则"},{"key":"D","text":"有教无类"}],"answer":["A","B","C"],"explanation":"有教无类出自《论语》。"},{"id":2033,"type":"多选题","text":"《学记》关于教学方法的内容有____。","options":[{"key":"A","text":"讲解法"},{"key":"B","text":"问答法"},{"key":"C","text":"讨论法"},{"key":"D","text":"练习法"}],"answer":["A","B","D"],"explanation":"《学记》概括的教学方法有：讲解法、问答法、练习法、类比法。"},{"id":2034,"type":"多选题","text":"朱熹有关道德教育的内容包括____。","options":[{"key":"A","text":"立志"},{"key":"B","text":"居敬"},{"key":"C","text":"存养"},{"key":"D","text":"省察"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2035,"type":"多选题","text":"朱子读书六法包括____。","options":[{"key":"A","text":"循序渐进"},{"key":"B","text":"熟读精思"},{"key":"C","text":"虚心涵泳"},{"key":"D","text":"温故知新"}],"answer":["A","B","C"],"explanation":"循序渐进、熟读精思、虚心涵泳、切己体察、着紧用力、居敬持志是朱子读书六法。"},{"id":2036,"type":"多选题","text":"孟子存养式教学法的主要内容包括____。","options":[{"key":"A","text":"深造自得"},{"key":"B","text":"盈科而进"},{"key":"C","text":"专心有恒"},{"key":"D","text":"教亦多术"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2037,"type":"多选题","text":"《黄帝内经》是指____等著作的合称。","options":[{"key":"A","text":"《难经》"},{"key":"B","text":"《针灸甲乙经》"},{"key":"C","text":"《素问》"},{"key":"D","text":"《灵枢》"}],"answer":["C","D"],"explanation":"《黄帝内经》分《灵枢》、《素问》两部分，是中国最早的医学典籍。"},{"id":2038,"type":"多选题","text":"孔子通过对春秋以前中国文化成果的总结，继承周公的思想，创造了以____为核心的一整套伦理思想体系。","options":[{"key":"A","text":"德"},{"key":"B","text":"道"},{"key":"C","text":"仁"},{"key":"D","text":"礼"}],"answer":["C","D"],"explanation":"春秋时期,孔子通过对春秋以前中国文化成果的总结,成功地对中国社会的生活秩序进行了伦理化、道德化的提升,创造了以礼、仁、中庸为内核的伦理思想体系。"},{"id":2039,"type":"多选题","text":"李白的著名诗篇有____。","options":[{"key":"A","text":"《蜀道难》"},{"key":"B","text":"《梦游天姥吟留别》"},{"key":"C","text":"《将进酒》"},{"key":"D","text":"《丽人行》"}],"answer":["A","B","C"],"explanation":"《丽人行》是杜甫所作。"},{"id":2040,"type":"多选题","text":"杜甫的著名诗篇有____。","options":[{"key":"A","text":"《将进酒》"},{"key":"B","text":"《兵车行》"},{"key":"C","text":"《闻官军收河南河北》"},{"key":"D","text":"《秋兴八首》"}],"answer":["B","C","D"],"explanation":"《将进酒》是李白所作。"},{"id":2041,"type":"多选题","text":"近代_____被称为“四大谴责小说”。","options":[{"key":"A","text":"李宝嘉的《官场现形记》"},{"key":"B","text":"吴沃尧的《二十年目睹之怪现状》"},{"key":"C","text":"刘鹗的《老残游记》"},{"key":"D","text":"曾朴的《孽海花》"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2042,"type":"多选题","text":"中国传统的天文学包括____。","options":[{"key":"A","text":"天象观测"},{"key":"B","text":"研究计时制度"},{"key":"C","text":"历法制定"},{"key":"D","text":"星系研究"}],"answer":["A","C"],"explanation":"中国传统的天文学包括天象观测、历法制定。"},{"id":2043,"type":"多选题","text":"唐代颜真卿的主要书法作品有____。","options":[{"key":"A","text":"《颜氏家庙碑》"},{"key":"B","text":"《多宝塔感应碑》"},{"key":"C","text":"《颜勤礼碑》"},{"key":"D","text":"《皇甫诞碑》"}],"answer":["A","B","C"],"explanation":"《皇甫诞碑》是欧阳询所书。"},{"id":2044,"type":"多选题","text":"欧阳询的主要书法作品有____。","options":[{"key":"A","text":"《九成宫醴泉铭》"},{"key":"B","text":"《卜商帖》"},{"key":"C","text":"《寒切贴》"},{"key":"D","text":"《皇甫诞碑》"}],"answer":["A","B","D"],"explanation":"《寒切贴》是王羲之所书。"},{"id":2045,"type":"多选题","text":"魏晋南北朝时期的著名史学家有____等人。","options":[{"key":"A","text":"陈寿"},{"key":"B","text":"裴松之"},{"key":"C","text":"荀悦"},{"key":"D","text":"范晔"}],"answer":["A","B","D"],"explanation":"荀悦是东汉史学家。"},{"id":2046,"type":"多选题","text":"____是魏晋南北朝时期编撰的“正史”。","options":[{"key":"A","text":"《后汉书》"},{"key":"B","text":"《三国志》"},{"key":"C","text":"《魏书》"},{"key":"D","text":"《华阳国志》"}],"answer":["A","B","C"],"explanation":"《华阳国志》属于地方志。"},{"id":2047,"type":"多选题","text":"北宋书法家米芾的传世墨迹主要有____。","options":[{"key":"A","text":"《苕溪诗卷》"},{"key":"B","text":"《蜀素帖》"},{"key":"C","text":"《天马赋》"},{"key":"D","text":"《方圆庵记》"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2048,"type":"多选题","text":"元代赵孟頫的主要书法作品有____。","options":[{"key":"A","text":"《仇锷墓碑铭》"},{"key":"B","text":"《鹊华秋色图》"},{"key":"C","text":"《度人经》"},{"key":"D","text":"《兰亭十三跋》"}],"answer":["A","C","D"],"explanation":"《鹊华秋色图》属于赵孟頫的山水画。"},{"id":2049,"type":"多选题","text":"建于公元前3世纪的都江堰工程由____部分组成。","options":[{"key":"A","text":"大坝"},{"key":"B","text":"宝瓶口"},{"key":"C","text":"飞沙堰"},{"key":"D","text":"分水鱼嘴"}],"answer":["B","C","D"],"explanation":"都江堰主要由鱼嘴、飞沙堰、宝瓶口三大主体工程构成。"},{"id":2050,"type":"多选题","text":"中国古代杏黄色衣服是皇室的标志，这种标志指的是____。","options":[{"key":"A","text":"自然范围内的服饰标志"},{"key":"B","text":"人文范围内的服饰标志"},{"key":"C","text":"服饰的信仰标志"},{"key":"D","text":"服饰的阶层标志"}],"answer":["B","D"],"explanation":"中国古代杏黄色衣服是皇室的标志，这种标志指的是人文范围内的服饰标志和服饰的阶层标志。"},{"id":2051,"type":"多选题","text":"我国汉代时的医学已有“四诊”的诊断技术，“四诊”指的是____。","options":[{"key":"A","text":"闻"},{"key":"B","text":"望"},{"key":"C","text":"问"},{"key":"D","text":"切"}],"answer":["A","B","C","D"],"explanation":"四诊指的是望、闻、问、切。古称“诊法”。四诊具有直观性和朴素性的特点，在感官所及的范围内，直接地获取信息，医生即刻进行分析综合，及时作出判断。"},{"id":2052,"type":"多选题","text":"____属于《学记》提倡的教育教学原则。","options":[{"key":"A","text":"预防性原则"},{"key":"B","text":"循序渐进原则"},{"key":"C","text":"学习观摩原则"},{"key":"D","text":"启发诱导原则"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2053,"type":"多选题","text":"战国时期是先秦史学发展的繁荣时期， ____是该时期留存于现在的史籍。","options":[{"key":"A","text":"《左传》"},{"key":"B","text":"《战国策》"},{"key":"C","text":"《春秋》"},{"key":"D","text":"《竹书纪年》"}],"answer":["A","B","D"],"explanation":"《春秋》不属于战国时期的作品。"},{"id":2054,"type":"多选题","text":"____是宋元时期的地理志、地方志著作。","options":[{"key":"A","text":"《太平寰宇记》"},{"key":"B","text":"《元丰九域志》"},{"key":"C","text":"《东京梦华录》"},{"key":"D","text":"《武林旧事》"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2055,"type":"多选题","text":"____是宋元时期的薪金石学和考古学的代表性著作。","options":[{"key":"A","text":"欧阳修的《集古录》"},{"key":"B","text":"吴大临的《考古图》"},{"key":"C","text":"赵明诚的《金石录》"},{"key":"D","text":"裴秀所绘的《禹贡地域图》"}],"answer":["A","B","C"],"explanation":"裴秀是魏晋时期名臣。约在泰始四年至七年(268～271)，裴秀主编完成《禹贡地域图》18篇，它是中国有文献可考的最早的历史地图集，并在序言中提出了绘制地图的6项原则，即著名的“制图六体”，为中国传统地图（平面测量绘制的地图）奠定了理论基础。"},{"id":2056,"type":"多选题","text":"编年体史书发展过程中的分支有____。","options":[{"key":"A","text":"纪事本末体"},{"key":"B","text":"起居注"},{"key":"C","text":"实录"},{"key":"D","text":"纲目"}],"answer":["B","C","D"],"explanation":"纪事本末体不属于编年体。"},{"id":2057,"type":"多选题","text":"____属于 “史才四长”的内容。","options":[{"key":"A","text":"史德"},{"key":"B","text":"史才"},{"key":"C","text":"史学"},{"key":"D","text":"史识"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2058,"type":"多选题","text":"中国传统科技的特点有____。","options":[{"key":"A","text":"延续性"},{"key":"B","text":"政治伦理性"},{"key":"C","text":"整体性"},{"key":"D","text":"实用性"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2059,"type":"多选题","text":"汉代主要有“论天三家”，即____。","options":[{"key":"A","text":"盖天说"},{"key":"B","text":"浑天说"},{"key":"C","text":"宣夜说"},{"key":"D","text":"盘古开天说"}],"answer":["A","B","C"],"explanation":"汉代主要有“论天三家”，即盖天说、浑天说、宣夜说。"},{"id":2060,"type":"多选题","text":"____属于古代军礼范围。","options":[{"key":"A","text":"大师之礼"},{"key":"B","text":"大田之礼"},{"key":"C","text":"大封之礼"},{"key":"D","text":"大均之礼"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2061,"type":"多选题","text":"中国长期流传的饮食观念包括____。","options":[{"key":"A","text":"民本思想"},{"key":"B","text":"节约粮食"},{"key":"C","text":"好客"},{"key":"D","text":"人格教育"}],"answer":["A","B","D"],"explanation":"中国长期流传的饮食观念主要包括：1、民本思想；2、人格教育；3、食疗观；4、节约粮食。"},{"id":2062,"type":"多选题","text":"____属于古代婚礼“六礼”范围。","options":[{"key":"A","text":"纳采"},{"key":"B","text":"问名"},{"key":"C","text":"纳征"},{"key":"D","text":"请期"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2063,"type":"多选题","text":"____属于古代的丧葬习俗。","options":[{"key":"A","text":"土葬"},{"key":"B","text":"火葬"},{"key":"C","text":"石棺葬"},{"key":"D","text":"悬棺葬"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2064,"type":"多选题","text":"头衣亦称“元衣”，即我们现代的帽子。____属于我国传统的头衣种类。","options":[{"key":"A","text":"冠"},{"key":"B","text":"冕"},{"key":"C","text":"帻"},{"key":"D","text":"胄"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2065,"type":"多选题","text":"____是我国古代经验科学出现的标志，是当时人们从实践经验加以抽象概括的成果。","options":[{"key":"A","text":"《黄帝内经》"},{"key":"B","text":"《甘石星经》"},{"key":"C","text":"《墨经》"},{"key":"D","text":"《考工记》"}],"answer":["C","D"],"explanation":"《考工记》与《墨经》作为我国古代经验科学出现的标志,是春秋战国时期人们将生产、生活实践中取得的丰富经验进行抽象概括的成果。"},{"id":2066,"type":"多选题","text":"居住建筑的文化含义主要表现在____。","options":[{"key":"A","text":"居住方式"},{"key":"B","text":"居住风水"},{"key":"C","text":"居住建筑格局"},{"key":"D","text":"居住建筑仪式"}],"answer":["A","C","D"],"explanation":"居住建筑的文化含义主要表现在三个方面：居住方式、居住建筑格局和仪式。"},{"id":2067,"type":"多选题","text":"天人之辩的主要观点是____。","options":[{"key":"A","text":"重人事，轻天道"},{"key":"B","text":"天道自然"},{"key":"C","text":"天人相分"},{"key":"D","text":"天人交相胜，还相用"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2068,"type":"多选题","text":"中国传统文化的主要特点是____。","options":[{"key":"A","text":"以人为本"},{"key":"B","text":"强大的延续力"},{"key":"C","text":"以和为贵"},{"key":"D","text":"重道德"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2069,"type":"多选题","text":"书院近代转型迟滞的原因主要有____。","options":[{"key":"A","text":"腐败的专制制度和残酷的经济剥削"},{"key":"B","text":"腐败专制的官僚政治"},{"key":"C","text":"禁海锁国，画牢自封"},{"key":"D","text":"文化专制，扼杀异端"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2070,"type":"多选题","text":"学习中国传统文化的目的、意义____。","options":[{"key":"A","text":"可以增强民族自豪感和爱国情怀"},{"key":"B","text":"有助于改革开放和现代化建设"},{"key":"C","text":"有助于祖国统一、振兴中华"},{"key":"D","text":"可以提高个人的文化素养和思想品位"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2071,"type":"多选题","text":"中国传统哲学的特点是____。","options":[{"key":"A","text":"侧重于人生哲理的探讨"},{"key":"B","text":"哲学与政治、伦理含融不分"},{"key":"C","text":"整体把握、直觉体悟的思维方式"},{"key":"D","text":"注重对事物的整体把握，较少做细部论证；注重对道理的直觉体悟，而较少做逻辑分析"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2072,"type":"多选题","text":"中国佛教的主要宗派是____。","options":[{"key":"A","text":"天台宗"},{"key":"B","text":"唯识宗"},{"key":"C","text":"华严宗"},{"key":"D","text":"净土宗"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2073,"type":"多选题","text":"中国传统文化在西方的传播主要包括____。","options":[{"key":"A","text":"造纸术约在唐朝中期传入西亚，再到欧洲"},{"key":"B","text":"火药 13、14世纪由阿拉伯人传到欧洲，很快被应用于军事"},{"key":"C","text":"中国美术、绘画、陶瓷对欧洲人来说不仅实用，而且是有价值的艺术品"},{"key":"D","text":"在学术思想方面，儒家思想由传教士传播到欧洲"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2074,"type":"多选题","text":"中国优秀的史学文化传统包括____。","options":[{"key":"A","text":"求实精神"},{"key":"B","text":"惩恶扬善的批判精神"},{"key":"C","text":"以史为鉴的经邦致用精神"},{"key":"D","text":"融贯诸学，吸纳百家的会通精神"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2075,"type":"多选题","text":"董仲舒的思想主要有哪些方面____。","options":[{"key":"A","text":"人君受命于天"},{"key":"B","text":"“道之大原出于天，天不变，道亦不变\""},{"key":"C","text":"效法天道，德刑并用"},{"key":"D","text":"经世致用"}],"answer":["A","B","C"],"explanation":"经世致用一词由明清之际思想家王夫之、黄宗羲、顾炎武等提出。"},{"id":2076,"type":"多选题","text":"中国古代书法的特点____。","options":[{"key":"A","text":"通过书法的点、划结构和章法表现形式美"},{"key":"B","text":"通过字的力度来展现神采美"},{"key":"C","text":"通过字的形态来展现神采美"},{"key":"D","text":"通过字的形、神表现书法家的精神美和时代特征"}],"answer":["A","C","D"],"explanation":"中国古代书法是通过字的形态来展现神采美，而非字的力度。"},{"id":2077,"type":"多选题","text":"魏晋南北朝史学发展的特点____。","options":[{"key":"A","text":"史著数量大为增加"},{"key":"B","text":"史学发展成熟期"},{"key":"C","text":"史学成为一门独立的学科"},{"key":"D","text":"史著种类繁多"}],"answer":["A","C","D"],"explanation":"史学发展成熟期在隋唐时期。"},{"id":2078,"type":"多选题","text":"属于明代小说的是____。","options":[{"key":"A","text":"蒲松龄《聊斋志异》"},{"key":"B","text":"罗贯中《三国志通俗演义》"},{"key":"C","text":"吴承恩《西游记》"},{"key":"D","text":"施耐庵《水浒传》"}],"answer":["B","C","D"],"explanation":"蒲松龄《聊斋志异》是清代文言短篇小说集。"},{"id":2079,"type":"多选题","text":"墨学针对儒学提出的相反主张有____。","options":[{"key":"A","text":"兼爱"},{"key":"B","text":"天志"},{"key":"C","text":"节葬"},{"key":"D","text":"⾮乐"}],"answer":["A","B","C","D"],"explanation":"以上都正确。"},{"id":2080,"type":"多选题","text":"儒教的基本思想是____。","options":[{"key":"A","text":"祖先崇拜"},{"key":"B","text":"圣贤崇拜"},{"key":"C","text":"天人合一"},{"key":"D","text":"宗教与政治、伦理的紧密结合"}],"answer":["A","B","C","D"],"explanation":"儒教的基本思想祖先崇拜、圣贤崇拜、天人合一与宗教与政治、伦理的紧密结合。"},{"id":2081,"type":"多选题","text":"关于《齐民要术》的描述，正确的是____。","options":[{"key":"A","text":"中国现存最完整的一部农书"},{"key":"B","text":"北魏时贾思勰编写"},{"key":"C","text":"全书10卷，92篇，11万多字"},{"key":"D","text":"提出了按照自然规律搞好农业生产的宝贵思想"}],"answer":["A","B","C","D"],"explanation":"《齐民要术》是北魏时贾思勰编写，中国现存最完整的一部农书，全书10卷，92篇，11万多字，提出了按照自然规律搞好农业生产的宝贵思想。"},{"id":2082,"type":"多选题","text":"“城市”在宋代又叫____。","options":[{"key":"A","text":"市井"},{"key":"B","text":"井⾢"},{"key":"C","text":"都会"},{"key":"D","text":"城郭"}],"answer":["A","B","C","D"],"explanation":"“城市”在宋代⼜叫市井、井⾢、都会、城郭。"},{"id":2083,"type":"多选题","text":"“中”字的引申义有____。","options":[{"key":"A","text":"旗帜"},{"key":"B","text":"空间的中央"},{"key":"C","text":"⽂化政治中⼼"},{"key":"D","text":"军事堡垒"}],"answer":["B","C"],"explanation":"“中”字的引中义有空间的中央、文化政治的中心。"},{"id":2084,"type":"多选题","text":"“中体西⽤”论的严重缺陷是____。","options":[{"key":"A","text":"颠倒经济与伦理的序列关系"},{"key":"B","text":"以忠孝为本， 以中国经史之学为基"},{"key":"C","text":"仍存“华夷”等级秩序、⽂化中⼼主义⼼理定势"},{"key":"D","text":"回避现实冲突，停留在⼀种经验论的理论⽔平上"}],"answer":["C","D"],"explanation":"“中体西用”论的严重缺陷是仍存“华夷”等级秩序、文化中心主义心理定势;回避现实冲突, 停留在一种经验论的理论⽔平上。"},{"id":2085,"type":"多选题","text":"下列属于文化事象的有____。","options":[{"key":"A","text":"原始的巫术"},{"key":"B","text":"行业禁忌"},{"key":"C","text":"文学上的建安风骨"},{"key":"D","text":"中国戏曲的程式化动作"}],"answer":["A","B","C","D"],"explanation":"当一种现象以同样的形式反复出现时，其中就含有规律性，成为某一历史时期、某一国家（民族或地域）文化发展中带有典型和标志作用的事情，这些现象称为文化事象。"},{"id":2086,"type":"多选题","text":"按照四分法可将中国文化分为____。","options":[{"key":"A","text":"物质文化"},{"key":"B","text":"宗教文化"},{"key":"C","text":"精神文化"},{"key":"D","text":"制度文化"}],"answer":["A","C","D"],"explanation":"还有语言文化。"},{"id":2087,"type":"多选题","text":"竺可桢先生在《中国近五千年气候变化的初步研究》一文中将我国五千年的气候变化分为四个大的时期，按时间先后它们是____。","options":[{"key":"A","text":"温暖期"},{"key":"B","text":"寒暖交错期"},{"key":"C","text":"寒冷期"},{"key":"D","text":"第一冷期"}],"answer":["A","B","C"],"explanation":"中国五千年气候的变化大势是由暖变冷,大致分为四个大的时期:1)温暖期：从公元前3000年到公元前1100年,下限正好在商朝末年。2)寒暖交错期：从公元前1100年到公元1400年,下限到明朝初期。3)方志时期,又叫寒冷时期。从公元1400年到1900年,下限到清朝末年。4)仪器观测期。"},{"id":2088,"type":"多选题","text":"用现代地理学的观点观察中国地理的自然特征，可以将中国领土划分为____。","options":[{"key":"A","text":"东部季风区"},{"key":"B","text":"东部平原区"},{"key":"C","text":"西北干旱区"},{"key":"D","text":"中部山地区"}],"answer":["A","C"],"explanation":"东部季风区，西北干旱半干旱区，青藏高原区。"},{"id":2089,"type":"多选题","text":"中国古代文化的基干包括____。","options":[{"key":"A","text":"源于印度的佛教文化"},{"key":"B","text":"源于齐鲁的儒家文化"},{"key":"C","text":"源于三晋的法家文化"},{"key":"D","text":"源于江浙的商业文化"}],"answer":["B","C"],"explanation":"中国古代文化的基干包括源于齐鲁的儒家文化 、源于三晋的法家文化、源于南楚的道家及楚辞文化。"},{"id":2090,"type":"多选题","text":"概括起来说，我国古代改造利用自然的成就包括____。","options":[{"key":"A","text":"土地的开垦"},{"key":"B","text":"都江堰的修建"},{"key":"C","text":"京杭大运河的开通"},{"key":"D","text":"水利的兴修"}],"answer":["A","D"],"explanation":"传说:大禹治水。战国:都江堰和郑国渠。关中:井渠法。汉代:王景治黄河"},{"id":2091,"type":"多选题","text":"下列人物中属于“五帝”的是____。","options":[{"key":"A","text":"黄帝"},{"key":"B","text":"神农氏"},{"key":"C","text":"高辛"},{"key":"D","text":"颛顼"}],"answer":["A","C","D"],"explanation":"五帝是指黄帝、颛顼、帝喾、尧、舜。"},{"id":2092,"type":"多选题","text":"在汉武帝数十年对匈奴的战争中，大的战役有____。","options":[{"key":"A","text":"河南战役"},{"key":"B","text":"河西战役"},{"key":"C","text":"河东战役"},{"key":"D","text":"漠北战役"}],"answer":["A","B","D"],"explanation":"河东战役是显王三年至四十七年(公元前366年—前322年)，秦军收复被魏国夺占的河西地区(今山西、陕西间黄河南段以西地区)的作战。"},{"id":2093,"type":"多选题","text":"“三公九卿”中“三公”指的是____。","options":[{"key":"A","text":"丞相"},{"key":"B","text":"尚书"},{"key":"C","text":"太尉"},{"key":"D","text":"御史大夫"}],"answer":["A","C","D"],"explanation":"秦以丞相，太尉，御史大夫为三公。"},{"id":2094,"type":"多选题","text":"中国古代四大发明中，在唐宋之际发明并应用的包括____。","options":[{"key":"A","text":"火药"},{"key":"B","text":"指南针"},{"key":"C","text":"造纸术"},{"key":"D","text":"活字印刷术"}],"answer":["A","B","D"],"explanation":"造纸术，是中国四大发明之一，发明于西汉时期、改进于东汉时期。"},{"id":2095,"type":"多选题","text":"明末清初的“三先生”指的是____。","options":[{"key":"A","text":"王夫之"},{"key":"B","text":"顾炎武"},{"key":"C","text":"黄宗羲"},{"key":"D","text":"徐光启"}],"answer":["A","B","C"],"explanation":"清初出现了许多具有唯物主义思想与民主色彩的先进知识份子，黄宗羲、王夫之、顾炎武就是其杰出代表。他们被并称为“清初三先生” ，均曾参加过反清复明的爱国活动，失败后，拒绝同满清权贵合作，表现出崇高的民族气节。"},{"id":2096,"type":"多选题","text":"我国传统的市商贸易活动的主要模式有____。","options":[{"key":"A","text":"市"},{"key":"B","text":"商"},{"key":"C","text":"墟"},{"key":"D","text":"集"}],"answer":["A","C","D"],"explanation":"市、墟、集、会是传统市商贸易活动的主要模式。"},{"id":2097,"type":"多选题","text":"下列属于儒家\"五常\"的有哪些？","options":[{"key":"A","text":"仁"},{"key":"B","text":"义"},{"key":"C","text":"礼"},{"key":"D","text":"智"},{"key":"E","text":"信"},{"key":"F","text":"忠"}],"answer":["A","B","C","D","E"],"explanation":"\"五常\"即仁、义、礼、智、信，是儒家提倡的五种基本道德规范；\"忠\"虽也是传统道德，但不属于五常。"},{"id":2098,"type":"多选题","text":"下列属于古代\"六艺\"的有哪些？","options":[{"key":"A","text":"礼"},{"key":"B","text":"乐"},{"key":"C","text":"御"},{"key":"D","text":"画"},{"key":"E","text":"数"}],"answer":["A","B","C","E"],"explanation":"六艺为礼、乐、射、御、书、数，是周代贵族教育的基本科目；\"画\"不在六艺之中。"},{"id":2099,"type":"多选题","text":"下列属于《三国演义》中\"五虎上将\"的有哪些？","options":[{"key":"A","text":"关羽"},{"key":"B","text":"张飞"},{"key":"C","text":"赵云"},{"key":"D","text":"马超"},{"key":"E","text":"黄忠"},{"key":"F","text":"吕布"}],"answer":["A","B","C","D","E"],"explanation":"演义中关羽、张飞、赵云、马超、黄忠被封为\"五虎上将\"；书中指出此封号正史并无记载，且吕布不属五虎。"},{"id":2100,"type":"多选题","text":"下列属于\"金陵十二钗\"正册的有哪些？","options":[{"key":"A","text":"林黛玉"},{"key":"B","text":"薛宝钗"},{"key":"C","text":"贾探春"},{"key":"D","text":"史湘云"},{"key":"E","text":"晴雯"},{"key":"F","text":"香菱"}],"answer":["A","B","C","D"],"explanation":"正册十二人为黛玉、宝钗、元春、迎春、探春、惜春、湘云、妙玉、凤姐、巧姐、李纨、秦可卿；晴雯在又副册，香菱在副册。"},{"id":2101,"type":"多选题","text":"下列传统节日与习俗的对应，正确的有哪些？","options":[{"key":"A","text":"端午节——插艾蒿"},{"key":"B","text":"七夕节——乞巧"},{"key":"C","text":"重阳节——插茱萸"},{"key":"D","text":"腊八节——喝腊八粥"},{"key":"E","text":"清明节——扫墓踏青"},{"key":"F","text":"中元节——赏月吃饼"}],"answer":["A","B","C","D","E"],"explanation":"端午插艾剪\"艾虎\"、七夕乞巧、重阳插茱萸、腊八喝腊八粥、清明扫墓踏青均有记述；赏月吃饼是中秋习俗。"},{"id":2102,"type":"多选题","text":"古代没有洗衣粉，下列哪些是古人使用的洗涤用品？","options":[{"key":"A","text":"草木灰水（灰水）"},{"key":"B","text":"皂角（皂荚）"},{"key":"C","text":"澡豆"},{"key":"D","text":"肥皂团"},{"key":"E","text":"洗衣液"}],"answer":["A","B","C","D"],"explanation":"《考工记》即记载草木灰水用于洗涤；皂角、澡豆、肥皂团（\"肥皂\"得名由来）均为古代洗涤用品；洗衣液是近代化工产品。"},{"id":2103,"type":"多选题","text":"下列哪些是书中提到的万里长城以外的古长城遗址？","options":[{"key":"A","text":"山东齐长城（穆陵关）"},{"key":"B","text":"华阴魏长城"},{"key":"C","text":"烧锅营子燕长城"},{"key":"D","text":"慕田峪长城"},{"key":"E","text":"八达岭长城"}],"answer":["A","B","C","D"],"explanation":"书中列举了齐长城、华阴魏长城、烧锅营子燕长城等古长城遗址；八达岭属明长城主线上的段落。"},{"id":2104,"type":"多选题","text":"下列属于戏曲角色行当的有哪些？","options":[{"key":"A","text":"生"},{"key":"B","text":"旦"},{"key":"C","text":"净"},{"key":"D","text":"末"},{"key":"E","text":"丑"},{"key":"F","text":"侠"}],"answer":["A","B","C","D","E"],"explanation":"生、旦、净、末、丑是戏曲的五种角色行当；\"侠\"不是行当。"},{"id":2105,"type":"多选题","text":"书中说\"十八般武器\"有具体所指，下列属于\"十八般兵器\"的有哪些？","options":[{"key":"A","text":"刀"},{"key":"B","text":"剑"},{"key":"C","text":"戟"},{"key":"D","text":"琴"},{"key":"E","text":"流星锤"}],"answer":["A","B","C","E"],"explanation":"十八般兵器一般指刀、枪、剑、戟、斧、钺、钩、叉、镋、棍、槊、棒、鞭、锏、锤、抓、拐子、流星等；\"琴\"不在其列。"},{"id":2106,"type":"多选题","text":"下列属于\"十二地支\"的有哪些？","options":[{"key":"A","text":"子"},{"key":"B","text":"丑"},{"key":"C","text":"巳"},{"key":"D","text":"玄"},{"key":"E","text":"亥"}],"answer":["A","B","C","E"],"explanation":"十二地支为子、丑、寅、卯、辰、巳、午、未、申、酉、戌、亥；\"玄\"不是地支。"},{"id":2107,"type":"多选题","text":"下列属于\"五经\"的有哪些？","options":[{"key":"A","text":"《诗经》"},{"key":"B","text":"《尚书》"},{"key":"C","text":"《周易》"},{"key":"D","text":"《春秋》"},{"key":"E","text":"《论语》"}],"answer":["A","B","C","D"],"explanation":"五经指《诗》《书》《礼》《易》《春秋》五部儒家经典；《论语》属于\"四书\"。"},{"id":2108,"type":"多选题","text":"世人常说的\"文房四宝\"具体指哪四宝？","options":[{"key":"A","text":"笔"},{"key":"B","text":"墨"},{"key":"C","text":"纸"},{"key":"D","text":"砚"},{"key":"E","text":"印章"}],"answer":["A","B","C","D"],"explanation":"文房四宝指笔、墨、纸、砚，书中也指出这一说法的内涵历代有所变化，但四宝所指大体如此。"},{"id":2109,"type":"多选题","text":"\"唐宋八大家\"包括下列哪些人？","options":[{"key":"A","text":"韩愈"},{"key":"B","text":"柳宗元"},{"key":"C","text":"欧阳修"},{"key":"D","text":"苏轼"},{"key":"E","text":"辛弃疾"}],"answer":["A","B","C","D"],"explanation":"唐宋八大家为韩愈、柳宗元、欧阳修、苏洵、苏轼、苏辙、王安石、曾巩；辛弃疾是词人，不在其列。"},{"id":2110,"type":"多选题","text":"属于\"岁寒三友\"的有哪些？","options":[{"key":"A","text":"松"},{"key":"B","text":"竹"},{"key":"C","text":"梅"},{"key":"D","text":"兰"}],"answer":["A","B","C"],"explanation":"岁寒三友指松、竹、梅；\"兰\"属\"花中四君子\"。"},{"id":2111,"type":"多选题","text":"属于\"花中四君子\"的有哪些？","options":[{"key":"A","text":"梅"},{"key":"B","text":"兰"},{"key":"C","text":"竹"},{"key":"D","text":"菊"},{"key":"E","text":"松"}],"answer":["A","B","C","D"],"explanation":"花中四君子指梅、兰、竹、菊；\"松\"属岁寒三友。"},{"id":2112,"type":"多选题","text":"下列属于我国\"四大名著\"的有哪些？","options":[{"key":"A","text":"《三国演义》"},{"key":"B","text":"《水浒传》"},{"key":"C","text":"《西游记》"},{"key":"D","text":"《红楼梦》"},{"key":"E","text":"《金瓶梅》"}],"answer":["A","B","C","D"],"explanation":"四大名著为《三国演义》《水浒传》《西游记》《红楼梦》；《金瓶梅》是世情小说，不属四大名著。"},{"id":2113,"type":"多选题","text":"京剧界的\"四大名旦\"指哪些人？","options":[{"key":"A","text":"梅兰芳"},{"key":"B","text":"程砚秋"},{"key":"C","text":"尚小云"},{"key":"D","text":"荀慧生"},{"key":"E","text":"周信芳"}],"answer":["A","B","C","D"],"explanation":"四大名旦为梅兰芳、程砚秋、尚小云、荀慧生；周信芳是京剧老生\"麒麟童\"，不属四大名旦。"},{"id":2114,"type":"多选题","text":"\"三从四德\"中的\"三从\"包括哪些？","options":[{"key":"A","text":"未嫁从父"},{"key":"B","text":"既嫁从夫"},{"key":"C","text":"夫死从子"},{"key":"D","text":"父死从兄"}],"answer":["A","B","C"],"explanation":"\"三从\"指未嫁从父、既嫁从夫、夫死从子；\"父死从兄\"是干扰项。"},{"id":2115,"type":"多选题","text":"\"八音\"是制作乐器的八类材料，下列属于其中的有哪些？","options":[{"key":"A","text":"金"},{"key":"B","text":"石"},{"key":"C","text":"丝"},{"key":"D","text":"木"},{"key":"E","text":"鼓"}],"answer":["A","B","C","D"],"explanation":"八音指金、石、丝、竹、匏、土、革、木八类材料；\"鼓\"是乐器名称，不是材料。"},{"id":2116,"type":"多选题","text":"毛评本《三国演义》中所说的\"三绝\"，指的是哪些人？","options":[{"key":"A","text":"诸葛亮（智绝）"},{"key":"B","text":"关羽（义绝）"},{"key":"C","text":"曹操（奸绝）"},{"key":"D","text":"赵云"}],"answer":["A","B","C"],"explanation":"\"三绝\"指诸葛亮之智绝、关羽之义绝、曹操之奸绝，赵云不在\"三绝\"之列。"},{"id":2117,"type":"多选题","text":"属于\"竹林七贤\"的有哪些？","options":[{"key":"A","text":"嵇康"},{"key":"B","text":"阮籍"},{"key":"C","text":"山涛"},{"key":"D","text":"王维"}],"answer":["A","B","C"],"explanation":"竹林七贤为嵇康、阮籍、山涛、向秀、刘伶、王戎、阮咸；王维是唐代诗人，不属七贤。"},{"id":2118,"type":"多选题","text":"下列属于中国历史上\"上古三代\"（夏商周）的有哪些？","options":[{"key":"A","text":"夏"},{"key":"B","text":"商"},{"key":"C","text":"周"},{"key":"D","text":"秦"}],"answer":["A","B","C"],"explanation":"夏、商、周合称\"三代\"；秦是三代之后的第一个大一统王朝。"},{"id":2119,"type":"多选题","text":"\"战国四公子\"指的是下列哪几位？","options":[{"key":"A","text":"孟尝君"},{"key":"B","text":"平原君"},{"key":"C","text":"信陵君"},{"key":"D","text":"春申君"},{"key":"E","text":"吕不韦"}],"answer":["A","B","C","D"],"explanation":"战国四公子为齐孟尝君、赵平原君、魏信陵君、楚春申君，均以养士著称；吕不韦是秦国丞相。"},{"id":2120,"type":"多选题","text":"秦始皇统一六国后推行巩固统一的措施包括？","options":[{"key":"A","text":"书同文"},{"key":"B","text":"车同轨"},{"key":"C","text":"统一度量衡"},{"key":"D","text":"统一货币"},{"key":"E","text":"分封诸侯"}],"answer":["A","B","C","D"],"explanation":"秦统一文字、车轨、度量衡和货币；秦废分封而行郡县，分封不是其措施。"},{"id":2121,"type":"多选题","text":"辅佐刘邦建立汉朝、史称\"汉初三杰\"的是？","options":[{"key":"A","text":"张良"},{"key":"B","text":"萧何"},{"key":"C","text":"韩信"},{"key":"D","text":"陈平"}],"answer":["A","B","C"],"explanation":"刘邦自述：运筹帷幄不如张良，镇国抚民不如萧何，战必胜攻必取不如韩信。"},{"id":2122,"type":"多选题","text":"\"文景之治\"时期推行的政策包括？","options":[{"key":"A","text":"轻徭薄赋"},{"key":"B","text":"与民休息"},{"key":"C","text":"提倡节俭"},{"key":"D","text":"大兴土木"}],"answer":["A","B","C"],"explanation":"文景二帝减田租、省刑罚、尚节俭；大兴土木与之背道而驰。"},{"id":2123,"type":"多选题","text":"\"开元盛世\"时期的著名贤相包括？","options":[{"key":"A","text":"姚崇"},{"key":"B","text":"宋璟"},{"key":"C","text":"杨国忠"},{"key":"D","text":"李林甫"}],"answer":["A","B"],"explanation":"姚崇、宋璟相继为相，辅佐唐玄宗开创开元盛世；杨国忠、李林甫为奸相。"},{"id":2124,"type":"多选题","text":"\"康乾盛世\"指的是哪几位皇帝在位时期？","options":[{"key":"A","text":"康熙"},{"key":"B","text":"雍正"},{"key":"C","text":"乾隆"},{"key":"D","text":"顺治"}],"answer":["A","B","C"],"explanation":"康乾盛世历经康熙、雍正、乾隆三朝，持续百余年。"},{"id":2125,"type":"多选题","text":"下列属于\"二十四史\"的有哪些？","options":[{"key":"A","text":"《史记》"},{"key":"B","text":"《汉书》"},{"key":"C","text":"《后汉书》"},{"key":"D","text":"《三国志》"},{"key":"E","text":"《资治通鉴》"}],"answer":["A","B","C","D"],"explanation":"二十四史为纪传体正史，《资治通鉴》是编年体，不在其列。"},{"id":2126,"type":"多选题","text":"下列属于编年体史书的有哪些？","options":[{"key":"A","text":"《春秋》"},{"key":"B","text":"《左传》"},{"key":"C","text":"《资治通鉴》"},{"key":"D","text":"《史记》"}],"answer":["A","B","C"],"explanation":"《春秋》《左传》《资治通鉴》均按年代编排；《史记》是纪传体。"},{"id":2127,"type":"多选题","text":"下列属于中国古代著名兵书的有哪些？","options":[{"key":"A","text":"《孙子兵法》"},{"key":"B","text":"《吴子》"},{"key":"C","text":"《六韬》"},{"key":"D","text":"《论语》"}],"answer":["A","B","C"],"explanation":"《孙子兵法》《吴子》《六韬》均为著名兵书；《论语》是儒家经典。"},{"id":2128,"type":"多选题","text":"下列《水浒传》人物与绰号对应正确的有哪些？","options":[{"key":"A","text":"及时雨——宋江"},{"key":"B","text":"豹子头——林冲"},{"key":"C","text":"智多星——吴用"},{"key":"D","text":"黑旋风——宋江"}],"answer":["A","B","C"],"explanation":"\"黑旋风\"是李逵的绰号，不是宋江。"},{"id":2129,"type":"多选题","text":"下列《西游记》人物与来历对应正确的有哪些？","options":[{"key":"A","text":"孙悟空——仙石孕育"},{"key":"B","text":"唐僧——以玄奘为原型"},{"key":"C","text":"猪八戒——天蓬元帅"},{"key":"D","text":"沙僧——卷帘大将"}],"answer":["A","B","C","D"],"explanation":"四组对应均正确：悟空出自仙石，八戒、沙僧分别是被贬的天蓬元帅和卷帘大将。"},{"id":2130,"type":"多选题","text":"下列《红楼梦》人物关系对应正确的有哪些？","options":[{"key":"A","text":"贾宝玉与林黛玉——姑表兄妹"},{"key":"B","text":"王熙凤——贾琏之妻"},{"key":"C","text":"贾政——贾宝玉之父"},{"key":"D","text":"贾探春——贾琏之妹"}],"answer":["A","B","C"],"explanation":"探春是贾政之女、贾宝玉的庶出妹妹，与贾琏是堂兄妹关系。"},{"id":2131,"type":"多选题","text":"\"唐宋八大家\"中属于唐代的有哪些？","options":[{"key":"A","text":"韩愈"},{"key":"B","text":"柳宗元"},{"key":"C","text":"欧阳修"},{"key":"D","text":"苏轼"}],"answer":["A","B"],"explanation":"八大家中唐代仅韩愈、柳宗元二人，其余六位为宋人。"},{"id":2132,"type":"多选题","text":"下列属于唐代著名边塞诗人的有哪些？","options":[{"key":"A","text":"高适"},{"key":"B","text":"岑参"},{"key":"C","text":"王昌龄"},{"key":"D","text":"王之涣"},{"key":"E","text":"王维"}],"answer":["A","B","C","D"],"explanation":"高适、岑参、王昌龄、王之涣均以边塞诗著称；王维以山水田园诗为主。"},{"id":2133,"type":"多选题","text":"\"元杂剧四大悲剧\"包括？","options":[{"key":"A","text":"《窦娥冤》"},{"key":"B","text":"《汉宫秋》"},{"key":"C","text":"《梧桐雨》"},{"key":"D","text":"《赵氏孤儿》"},{"key":"E","text":"《西厢记》"}],"answer":["A","B","C","D"],"explanation":"四大悲剧为《窦娥冤》《汉宫秋》《梧桐雨》《赵氏孤儿》；《西厢记》是喜剧。"},{"id":2134,"type":"多选题","text":"明代\"四大奇书\"指的是？","options":[{"key":"A","text":"《三国演义》"},{"key":"B","text":"《水浒传》"},{"key":"C","text":"《西游记》"},{"key":"D","text":"《金瓶梅》"},{"key":"E","text":"《红楼梦》"}],"answer":["A","B","C","D"],"explanation":"四大奇书为《三国演义》《水浒传》《西游记》《金瓶梅》；《红楼梦》成书于清代，不在其列。"},{"id":2135,"type":"多选题","text":"古人总结的汉字造字方法\"六书\"包括？","options":[{"key":"A","text":"象形"},{"key":"B","text":"指事"},{"key":"C","text":"会意"},{"key":"D","text":"形声"},{"key":"E","text":"拼音"}],"answer":["A","B","C","D"],"explanation":"六书为象形、指事、会意、形声、转注、假借；拼音是近现代注音方法。"},{"id":2136,"type":"多选题","text":"\"楷书四大家\"指的是？","options":[{"key":"A","text":"欧阳询"},{"key":"B","text":"颜真卿"},{"key":"C","text":"柳公权"},{"key":"D","text":"赵孟頫"},{"key":"E","text":"王羲之"}],"answer":["A","B","C","D"],"explanation":"楷书四大家为唐代的欧阳询、颜真卿、柳公权和元代的赵孟頫。"},{"id":2137,"type":"多选题","text":"我国传统\"四大名绣\"指的是？","options":[{"key":"A","text":"苏绣"},{"key":"B","text":"湘绣"},{"key":"C","text":"粤绣"},{"key":"D","text":"蜀绣"},{"key":"E","text":"京绣"}],"answer":["A","B","C","D"],"explanation":"四大名绣为苏州苏绣、湖南湘绣、广东粤绣、四川蜀绣。"},{"id":2138,"type":"多选题","text":"我国古代\"四大古都\"指的是？","options":[{"key":"A","text":"西安"},{"key":"B","text":"洛阳"},{"key":"C","text":"南京"},{"key":"D","text":"北京"},{"key":"E","text":"杭州"}],"answer":["A","B","C","D"],"explanation":"四大古都为西安、洛阳、南京、北京；杭州属\"六大古都\"之列。"},{"id":2139,"type":"多选题","text":"下列属于\"五岳\"的有哪些？","options":[{"key":"A","text":"泰山"},{"key":"B","text":"华山"},{"key":"C","text":"恒山"},{"key":"D","text":"嵩山"},{"key":"E","text":"衡山"},{"key":"F","text":"黄山"}],"answer":["A","B","C","D","E"],"explanation":"五岳为东岳泰山、西岳华山、北岳恒山、中岳嵩山、南岳衡山；黄山不在五岳之列。"},{"id":2140,"type":"多选题","text":"中国\"四大道教名山\"指的是？","options":[{"key":"A","text":"武当山"},{"key":"B","text":"青城山"},{"key":"C","text":"龙虎山"},{"key":"D","text":"齐云山"},{"key":"E","text":"五台山"}],"answer":["A","B","C","D"],"explanation":"四大道教名山为湖北武当山、四川青城山、江西龙虎山、安徽齐云山；五台山是佛教名山。"},{"id":2141,"type":"多选题","text":"下列属于传统七夕节习俗的有哪些？","options":[{"key":"A","text":"乞巧"},{"key":"B","text":"拜织女"},{"key":"C","text":"穿针引线"},{"key":"D","text":"登高远眺"}],"answer":["A","B","C"],"explanation":"七夕女子穿针乞巧、拜织女星；登高远眺是重阳节习俗。"},{"id":2142,"type":"多选题","text":"下列属于清明节习俗的有哪些？","options":[{"key":"A","text":"扫墓祭祖"},{"key":"B","text":"踏青"},{"key":"C","text":"插柳"},{"key":"D","text":"放风筝"},{"key":"E","text":"赏月"}],"answer":["A","B","C","D"],"explanation":"清明扫墓、踏青、插柳、放风筝均为其习俗；赏月是中秋习俗。"},{"id":2143,"type":"多选题","text":"下列属于端午节习俗的有哪些？","options":[{"key":"A","text":"赛龙舟"},{"key":"B","text":"吃粽子"},{"key":"C","text":"挂艾草"},{"key":"D","text":"佩香囊"},{"key":"E","text":"登高远眺"}],"answer":["A","B","C","D"],"explanation":"端午赛龙舟、吃粽子、挂艾草菖蒲、佩香囊；登高远眺是重阳习俗。"},{"id":2144,"type":"多选题","text":"下列属于春节习俗的有哪些？","options":[{"key":"A","text":"贴春联"},{"key":"B","text":"守岁"},{"key":"C","text":"拜年"},{"key":"D","text":"给压岁钱"},{"key":"E","text":"插茱萸"}],"answer":["A","B","C","D"],"explanation":"贴春联、守岁、拜年、压岁钱均为春节习俗；插茱萸是重阳节习俗。"},{"id":2145,"type":"多选题","text":"中医诊断疾病的\"四诊\"指的是？","options":[{"key":"A","text":"望"},{"key":"B","text":"闻"},{"key":"C","text":"问"},{"key":"D","text":"切"},{"key":"E","text":"针"}],"answer":["A","B","C","D"],"explanation":"四诊即望诊、闻诊、问诊、切诊；针灸是治疗方法而非诊法。"},{"id":2146,"type":"多选题","text":"\"中医四大经典\"指的是？","options":[{"key":"A","text":"《黄帝内经》"},{"key":"B","text":"《难经》"},{"key":"C","text":"《伤寒杂病论》"},{"key":"D","text":"《神农本草经》"},{"key":"E","text":"《本草纲目》"}],"answer":["A","B","C","D"],"explanation":"中医四大经典为《黄帝内经》《难经》《伤寒杂病论》《神农本草经》；《本草纲目》是明代药学巨著。"},{"id":2147,"type":"多选题","text":"下列属于中国传统弹拨乐器的有哪些？","options":[{"key":"A","text":"古琴"},{"key":"B","text":"古筝"},{"key":"C","text":"琵琶"},{"key":"D","text":"二胡"}],"answer":["A","B","C"],"explanation":"古琴、古筝、琵琶均为弹拨乐器；二胡是拉弦乐器。"},{"id":2148,"type":"多选题","text":"下列关于李白的说法正确的有哪些？","options":[{"key":"A","text":"被称为\"诗仙\""},{"key":"B","text":"号青莲居士"},{"key":"C","text":"诗风豪放飘逸"},{"key":"D","text":"被称为\"诗圣\""}],"answer":["A","B","C"],"explanation":"李白号青莲居士、诗风豪放飘逸，被称\"诗仙\"；\"诗圣\"是杜甫。"},{"id":2149,"type":"多选题","text":"儒家经典\"三礼\"指的是？","options":[{"key":"A","text":"《周礼》"},{"key":"B","text":"《仪礼》"},{"key":"C","text":"《礼记》"},{"key":"D","text":"《诗经》"}],"answer":["A","B","C"],"explanation":"三礼为《周礼》《仪礼》《礼记》，是记载古代礼制的经典。"},{"id":2150,"type":"多选题","text":"下列属于唐代\"传奇\"（文言短篇小说）的有哪些？","options":[{"key":"A","text":"《柳毅传》"},{"key":"B","text":"《莺莺传》"},{"key":"C","text":"《南柯太守传》"},{"key":"D","text":"《牡丹亭》"}],"answer":["A","B","C"],"explanation":"唐传奇以《柳毅传》《莺莺传》《南柯太守传》等为代表；《牡丹亭》是明代戏曲。"},{"id":2151,"type":"多选题","text":"明末清初的三大思想家指的是？","options":[{"key":"A","text":"黄宗羲"},{"key":"B","text":"顾炎武"},{"key":"C","text":"王夫之"},{"key":"D","text":"纪昀"}],"answer":["A","B","C"],"explanation":"黄宗羲、顾炎武、王夫之并称明末清初三大思想家；纪昀是清代《四库全书》总纂官。"},{"id":2152,"type":"多选题","text":"下列属于中国历史上著名\"治世\"或\"盛世\"的有哪些？","options":[{"key":"A","text":"文景之治"},{"key":"B","text":"贞观之治"},{"key":"C","text":"开元盛世"},{"key":"D","text":"康乾盛世"},{"key":"E","text":"安史之乱"}],"answer":["A","B","C","D"],"explanation":"文景之治、贞观之治、开元盛世、康乾盛世均为治世；安史之乱是唐由盛转衰的战乱。"},{"id":2153,"type":"多选题","text":"科举取士的三级最高考试是？","options":[{"key":"A","text":"乡试"},{"key":"B","text":"会试"},{"key":"C","text":"殿试"},{"key":"D","text":"武试"}],"answer":["A","B","C"],"explanation":"科举正式的三级考试为乡试、会试、殿试；童试为入门考试。"},{"id":2154,"type":"多选题","text":"下列属于对老年人年龄的雅称有哪些？","options":[{"key":"A","text":"花甲（六十岁）"},{"key":"B","text":"古稀（七十岁）"},{"key":"C","text":"耄耋（八九十岁）"},{"key":"D","text":"期颐（百岁）"},{"key":"E","text":"豆蔻（十三四岁）"}],"answer":["A","B","C","D"],"explanation":"花甲、古稀、耄耋、期颐均指老年；豆蔻指少女十三四岁。"},{"id":2155,"type":"多选题","text":"下列年龄称谓与年龄对应正确的有哪些？","options":[{"key":"A","text":"弱冠——男子二十岁"},{"key":"B","text":"而立——三十岁"},{"key":"C","text":"不惑——四十岁"},{"key":"D","text":"花甲——七十岁"}],"answer":["A","B","C"],"explanation":"弱冠二十、而立三十、不惑四十均正确；花甲指六十岁，七十岁称古稀。"},{"id":2156,"type":"多选题","text":"下列属于传统启蒙读物的有哪些？","options":[{"key":"A","text":"《三字经》"},{"key":"B","text":"《百家姓》"},{"key":"C","text":"《千字文》"},{"key":"D","text":"《弟子规》"},{"key":"E","text":"《史记》"}],"answer":["A","B","C","D"],"explanation":"三字经、百家姓、千字文、弟子规均为蒙学读物；《史记》是史书。"},{"id":2157,"type":"多选题","text":"下列少数民族与其传统节日对应正确的有哪些？","options":[{"key":"A","text":"泼水节——傣族"},{"key":"B","text":"火把节——彝族"},{"key":"C","text":"那达慕大会——蒙古族"},{"key":"D","text":"开斋节——回族"},{"key":"E","text":"樱花节——傣族"}],"answer":["A","B","C","D"],"explanation":"四组对应均正确；\"樱花节\"并非傣族传统节日，属干扰项。"},{"id":2158,"type":"多选题","text":"古代婚礼\"六礼\"中的前四礼是？","options":[{"key":"A","text":"纳采"},{"key":"B","text":"问名"},{"key":"C","text":"纳吉"},{"key":"D","text":"纳征"},{"key":"E","text":"出家"}],"answer":["A","B","C","D"],"explanation":"六礼为纳采、问名、纳吉、纳征、请期、亲迎，前三到四礼均在议婚阶段。"},{"id":2159,"type":"多选题","text":"下列属于\"二十四节气\"的有哪些？","options":[{"key":"A","text":"芒种"},{"key":"B","text":"白露"},{"key":"C","text":"霜降"},{"key":"D","text":"大寒"},{"key":"E","text":"腊八"}],"answer":["A","B","C","D"],"explanation":"芒种、白露、霜降、大寒均为节气；腊八是传统节日。"},{"id":2160,"type":"多选题","text":"古代天文学\"四象\"与方位的对应正确的有哪些？","options":[{"key":"A","text":"东方——青龙"},{"key":"B","text":"西方——白虎"},{"key":"C","text":"南方——朱雀"},{"key":"D","text":"北方——玄武"},{"key":"E","text":"中央——麒麟"}],"answer":["A","B","C","D"],"explanation":"东青龙、西白虎、南朱雀、北玄武；\"中央麒麟\"是干扰项。"},{"id":2161,"type":"多选题","text":"下列\"五行相生\"关系正确的有哪些？","options":[{"key":"A","text":"木生火"},{"key":"B","text":"火生土"},{"key":"C","text":"土生金"},{"key":"D","text":"金生水"},{"key":"E","text":"水生火"}],"answer":["A","B","C","D"],"explanation":"五行相生为木生火、火生土、土生金、金生水、水生木；\"水生火\"错误。"},{"id":2162,"type":"多选题","text":"下列属于中国传统节令食品的有哪些？","options":[{"key":"A","text":"月饼"},{"key":"B","text":"元宵"},{"key":"C","text":"粽子"},{"key":"D","text":"重阳糕"},{"key":"E","text":"汉堡"}],"answer":["A","B","C","D"],"explanation":"月饼、元宵、粽子、重阳糕为传统节令食品；汉堡是西式食品。"},{"id":2163,"type":"多选题","text":"下列属于中国传统民间手工艺的有哪些？","options":[{"key":"A","text":"剪纸"},{"key":"B","text":"刺绣"},{"key":"C","text":"泥塑"},{"key":"D","text":"面塑"},{"key":"E","text":"油画"}],"answer":["A","B","C","D"],"explanation":"剪纸、刺绣、泥塑、面塑均为传统手工艺；油画是西方画种。"},{"id":2164,"type":"多选题","text":"下列属于中国传统戏曲剧种的有哪些？","options":[{"key":"A","text":"京剧"},{"key":"B","text":"越剧"},{"key":"C","text":"黄梅戏"},{"key":"D","text":"豫剧"},{"key":"E","text":"话剧"}],"answer":["A","B","C","D"],"explanation":"京剧、越剧、黄梅戏、豫剧均为传统戏曲剧种；话剧是西方传入的戏剧形式。"},{"id":2165,"type":"多选题","text":"下列成语出自《论语》的有哪些？","options":[{"key":"A","text":"温故知新"},{"key":"B","text":"举一反三"},{"key":"C","text":"不耻下问"},{"key":"D","text":"任重道远"},{"key":"E","text":"草木皆兵"}],"answer":["A","B","C","D"],"explanation":"前四个成语均出自《论语》；\"草木皆兵\"出自淝水之战典故。"},{"id":2166,"type":"多选题","text":"下列典故与项羽有关的有哪些？","options":[{"key":"A","text":"破釜沉舟"},{"key":"B","text":"四面楚歌"},{"key":"C","text":"霸王别姬"},{"key":"D","text":"乌江自刎"},{"key":"E","text":"约法三章"}],"answer":["A","B","C","D"],"explanation":"前四项均与项羽有关；\"约法三章\"是刘邦入关中之事。"},{"id":2167,"type":"多选题","text":"下列典故与韩信有关的有哪些？","options":[{"key":"A","text":"胯下之辱"},{"key":"B","text":"背水一战"},{"key":"C","text":"明修栈道、暗度陈仓"},{"key":"D","text":"多多益善"},{"key":"E","text":"破釜沉舟"}],"answer":["A","B","C","D"],"explanation":"前四项均与韩信有关；\"破釜沉舟\"是项羽之事。"},{"id":2168,"type":"多选题","text":"下列史事与岳飞有关的有哪些？","options":[{"key":"A","text":"背刺\"精忠报国\""},{"key":"B","text":"郾城大捷"},{"key":"C","text":"风波亭遇害"},{"key":"D","text":"被十二道金牌召回"},{"key":"E","text":"完璧归赵"}],"answer":["A","B","C","D"],"explanation":"前四项均与岳飞有关；\"完璧归赵\"是战国蔺相如之事。"},{"id":2169,"type":"多选题","text":"中国古代\"四大美女\"指的是？","options":[{"key":"A","text":"西施"},{"key":"B","text":"王昭君"},{"key":"C","text":"貂蝉"},{"key":"D","text":"杨玉环"},{"key":"E","text":"赵飞燕"}],"answer":["A","B","C","D"],"explanation":"四大美女为西施、王昭君、貂蝉、杨玉环；赵飞燕是汉成帝皇后，不在其列。"},{"id":2170,"type":"多选题","text":"\"沉鱼落雁、闭月羞花\"与四大美女的对应正确的有哪些？","options":[{"key":"A","text":"沉鱼——西施"},{"key":"B","text":"落雁——王昭君"},{"key":"C","text":"闭月——貂蝉"},{"key":"D","text":"羞花——杨玉环"},{"key":"E","text":"闭月——西施"}],"answer":["A","B","C","D"],"explanation":"四组对应均正确；\"闭月\"指的是貂蝉，不是西施。"},{"id":2171,"type":"多选题","text":"\"建安七子\"包括下列哪些人？","options":[{"key":"A","text":"孔融"},{"key":"B","text":"陈琳"},{"key":"C","text":"王粲"},{"key":"D","text":"曹植"}],"answer":["A","B","C"],"explanation":"建安七子为孔融、陈琳、王粲、徐干、阮瑀、应玚、刘桢；曹植属\"三曹\"，不在七子之列。"},{"id":2172,"type":"多选题","text":"宋代著名的\"四大书院\"包括？","options":[{"key":"A","text":"白鹿洞书院"},{"key":"B","text":"岳麓书院"},{"key":"C","text":"嵩阳书院"},{"key":"D","text":"应天书院"},{"key":"E","text":"东林书院"}],"answer":["A","B","C","D"],"explanation":"四大书院为白鹿洞、岳麓、嵩阳、应天书院；东林书院为明代讲学议政之所。"},{"id":2173,"type":"多选题","text":"我国\"四大石窟\"指的是？","options":[{"key":"A","text":"敦煌莫高窟"},{"key":"B","text":"云冈石窟"},{"key":"C","text":"龙门石窟"},{"key":"D","text":"麦积山石窟"},{"key":"E","text":"大足石刻"}],"answer":["A","B","C","D"],"explanation":"四大石窟为敦煌莫高窟、大同云冈石窟、洛阳龙门石窟、天水麦积山石窟。"},{"id":2174,"type":"多选题","text":"我国\"四大名亭\"指的是？","options":[{"key":"A","text":"醉翁亭"},{"key":"B","text":"陶然亭"},{"key":"C","text":"爱晚亭"},{"key":"D","text":"湖心亭"},{"key":"E","text":"兰亭"}],"answer":["A","B","C","D"],"explanation":"四大名亭为滁州醉翁亭、北京陶然亭、长沙爱晚亭、杭州湖心亭；绍兴兰亭因王羲之闻名，但不属四大名亭。"},{"id":2175,"type":"多选题","text":"下列属于\"十二生肖\"的有哪些？","options":[{"key":"A","text":"龙"},{"key":"B","text":"虎"},{"key":"C","text":"蛇"},{"key":"D","text":"马"},{"key":"E","text":"狼"}],"answer":["A","B","C","D"],"explanation":"十二生肖为鼠牛虎兔龙蛇马羊猴鸡狗猪；狼不在其列。"},{"id":2176,"type":"填空题","text":"春节贴____字，是中国民间由来已久的风俗，寄托了人们对美好生活的向往，也是对未来的祝愿。","options":[],"answer":["福"],"explanation":"春节贴“福”字，是中国民间由来已久的风俗，寄托了人们对美好生活的向往，也是对未来的祝愿。据宋代《梦粱录》记载:“岁旦在迩，席铺百货，画门神桃符，迎春牌儿……”“士庶家不论大小，俱洒扫门闾，去尘秽，净庭户，换门神，挂钟馗，钉桃符，贴春牌，祭祀祖宗”。文中的“贴春牌”即是写在红纸上的“福”字。"},{"id":2177,"type":"填空题","text":"有“文章巨公”和“百代文宗”之名的是____。","options":[],"answer":["韩愈"],"explanation":"韩愈，字退之，有“文章巨公”和“百代文宗”之称。"},{"id":2178,"type":"填空题","text":"醉翁亭位于安徽省滁州市西南琅琊山麓，其建造者是____。","options":[],"answer":["智仙"],"explanation":"原文中有“作亭者谁？山之僧智仙也。”"},{"id":2179,"type":"填空题","text":"“琴棋书画”是中国古代文人修身必备，被誉为“文人四友”，这里的“棋”指的是____。","options":[],"answer":["围棋"],"explanation":"四艺，通常指中国文人所推崇和要掌握的四门艺术，即琴、棋、书、画，又称为“文人四艺”，或“秀才四艺”。“琴”指的是弹琴（多指古琴）、“棋”指的是弈棋（多指围棋和中国象棋）、“书”指的是书法、“画”指的是绘画。"},{"id":2180,"type":"填空题","text":"写出下诗中缺失部分：____花落去，似曾相识燕归来。","options":[],"answer":["无可奈何"],"explanation":"出自宋代晏殊的《浣溪沙·一曲新词酒一杯》\n一曲新词酒一杯，去年天气旧亭台。夕阳西下几时回？\n无可奈何花落去，似曾相识燕归来。小园香径独徘徊。"},{"id":2181,"type":"填空题","text":"“唐太宗”的“太宗”指的是他的____。","options":[],"answer":["庙号"],"explanation":"庙号是中国君主死后在庙中被供奉时所称呼的名号，起源于重视祭祀与敬拜的商朝。唐太宗，名李世民（599年1月23日—649年7月10日。他的名字意思是“济世安民”，太宗是他死后的庙号。"},{"id":2182,"type":"填空题","text":"“三人行，必有我师”、“敏而好学，不耻下问”出自____。","options":[],"answer":["论语"],"explanation":"《论语》，是春秋时期思想家、教育家孔子的弟子及再传弟子记录孔子及其弟子言行而编成的语录文集，成书于战国前期。全书共20篇492章，以语录体为主，叙事体为辅，较为集中地体现了孔子及儒家学派的政治主张、伦理思想、道德观念、教育原则等。"},{"id":2183,"type":"填空题","text":"“好来宝”是____族的即兴诗。","options":[],"answer":["蒙古"],"explanation":"好来宝是中国蒙古族曲艺曲种，用蒙古语演唱。好来宝在蒙古语中意为“联韵”，即各句唱词的头一个音节谐韵，故又称联头韵。有的则将好来宝译为“连起来唱”或 “串起来唱”。2008年6月7日，好来宝经国务院批准列入第二批国家级非物质文化遗产名录。"},{"id":2184,"type":"填空题","text":"唐代人可以称“父亲”为____。","options":[],"answer":["哥哥"],"explanation":"“哥哥”在唐代既指“父亲”，也指“兄长”。哥哥原本不是中原的叫法，在唐朝属于外来语，一般称父亲为“耶耶”，私下里某些场合可以称“哥哥”，但在较为正式或者特殊的公开场合，还是得叫“父亲”或者“大人”。有时也把父亲叫做“阿耶”，和母亲在一起就叫“耶娘”，或“爷娘”。"},{"id":2185,"type":"填空题","text":"世界遗产委员会第24届会议决定把龙门石窟列入《世界遗产名录》，龙门石窟位于河南省____市。","options":[],"answer":["洛阳"],"explanation":"龙门石窟位于河南省洛阳市，是世界上造像最多、规模最大的石刻艺术宝库，被联合国科教文组织评为“中国石刻艺术的最高峰”，位居中国各大石窟之首。现为世界文化遗产、全国重点文物保护单位、国家AAAAA级旅游景区。"},{"id":2186,"type":"填空题","text":"中国的四大发明是造纸术、指南针、火药、____。","options":[],"answer":["印刷术"],"explanation":"中国四大发明是造纸术、指南针、火药、印刷术。四大发明是中国古代创新的智慧成果和科学技术，四大发明的概念却来源于西方学者，并在之后被中国人接受。意大利数学家杰罗姆·卡丹早在1550年就第一个指出，中国对世界所具有影响的“三大发明”：是司南（指南针）、印刷术和火药。来华传教士艾约瑟最先在三大发明中加入造纸术。"},{"id":2187,"type":"填空题","text":"我国思想家____曾提出：学校应成为民主议政的场所。","options":[],"answer":["黄宗羲"],"explanation":"黄宗羲“学校议政”思想主要体现于其著作《明夷待访录学校》中。该书曾被称为“反对君主专制主义的战斗檄文，代表了中国古代民主思想的最高成就”。学校议政思想可以概括为：学校反映民意，参与决策，舆论监督限制皇权、官权。在他看来，不是皇帝，而是“学校”形成的舆论，才是天下是非的标准，身为天子的皇上也要以其是非为是非。"},{"id":2188,"type":"填空题","text":"“吴带当风”是形容我国唐代画家____的笔法。","options":[],"answer":["吴道子"],"explanation":"吴道子是中国山水画的祖师，被后人尊称为“画圣”，素有“吴带当风”的美誉，他的人物绘画更是“冠绝于世”。所绘人物，善用状如兰叶或蓴菜条之线条表现衣褶，使有飘举之势，人称“吴带当风”；又喜以焦墨勾线，略加淡彩设色，又称“吴装”。"},{"id":2189,"type":"填空题","text":"我国历史上第一部编年体史书是____。","options":[],"answer":["春秋"],"explanation":"《春秋》是中国第一部编年体史书，共三十五卷，是儒家经典之一且为十三经中篇幅最长的，在四库全书中列为经部。记述范围从公元前722（鲁隐公元年）至公元前468。"},{"id":2190,"type":"填空题","text":"徐霞客曾经盛赞一座山为“四海名山皆过目，就中此景难图录”。这座山指的是____。","options":[],"answer":["雁荡山"],"explanation":"徐霞客曾经盛赞一座山为：“四海名山皆过目，就中此景难图录。”这座山指的就是以山水奇秀闻名，素有“海上名山、寰中绝胜”之誉，史称中国“东南第一山”的雁荡山。据说，是因山顶有湖，芦苇茂密，结草为荡，南归秋雁多宿于此，故名雁荡。雁荡山开山凿胜始于南北朝，兴于唐，盛于宋。历代文人墨客纷至沓来，谢灵运、沈括、徐霞客等都是雁荡山的忠实拥趸，留下了不少诗篇。"},{"id":2191,"type":"填空题","text":"____是中国境内最早的直立人。","options":[],"answer":["元谋人"],"explanation":"元谋人，学名元谋直立人，或称元谋猿人，是在中国发现的直立人化石。1965年发现于云南元谋上那蚌村附近，共计左右门齿两颗。"},{"id":2192,"type":"填空题","text":"三星堆遗址位于四川省广汉市，古蜀文化遗址，被誉为____文明之源。","options":[],"answer":["长江"],"explanation":"三星堆古遗址位于四川省广汉市西北的鸭子河南岸，分布面积12平方千米，距今已有5000至3000年历史，是迄今在西南地区发现的范围最大、延续时间最长、文化内涵最丰富的古城、古国、古蜀文化遗址。三星堆遗址被称为20世纪人类最伟大的考古发现之一，昭示了长江流域与黄河流域一样，同属中华文明的母体，被誉为“长江文明之源”。"},{"id":2193,"type":"填空题","text":"北宋书法四大家是黄庭坚、欧阳修、米芾、____。","options":[],"answer":["蔡襄"],"explanation":"宋四家是中国北宋时期四位书法家苏轼、黄庭坚、米芾和蔡襄的合称。这四个人大致可以代表宋代的书法风格，而且成就最高，故称“宋四家”。"},{"id":2194,"type":"填空题","text":"唐宋散文八大家是韩愈、柳宗元、欧阳修、苏洵、苏轼、苏辙、王安石、____。","options":[],"answer":["曾巩"],"explanation":"唐宋八大家，又称为“唐宋散文八大家”，是唐代和宋代八位散文家的合称，分别为唐代柳宗元、韩愈和宋代欧阳修、苏洵、苏轼、苏辙、王安石、曾巩八位。其中韩愈、柳宗元是唐代古文运动的领袖，欧阳修、三苏(苏轼、苏辙、苏洵)等四人是宋代古文运动的核心人物，王安石、曾巩是临川文学的代表人物。他们先后掀起的古文革新浪潮，使诗文发展的陈旧面貌焕然一新。"},{"id":2195,"type":"填空题","text":"四大名旦是梅兰芳、程砚秋、尚小云、____。","options":[],"answer":["荀慧生"],"explanation":"京剧四大名旦是指梅兰芳、程砚秋、尚小云、荀慧生，他们是中国京剧旦角行当中四大艺术流派的创始人。他们的优秀艺术，给人留下了不可磨灭的印象。"},{"id":2196,"type":"填空题","text":"《水浒传》中吴用的绰号是____。","options":[],"answer":["智多星"],"explanation":"智多星是《水浒传》人物吴用的绰号。吴用满腹经纶，通晓文韬武略，足智多谋，常以诸葛亮自比，道号“加亮先生”，人称“智多星”。"},{"id":2197,"type":"填空题","text":"“海上生明月，天涯共此时”的作者是____。","options":[],"answer":["张九龄"],"explanation":"“海上生明月，天涯共此时”出自张九龄的《望月怀远》。表示一轮明日从海上慢慢升起，远在天边的亲人这时候一定和我一样在凝视着它。后用来表达对远方亲人的思念之情。"},{"id":2198,"type":"填空题","text":"“无边落木萧萧下，不尽长江滚滚来”是____的作品。","options":[],"answer":["杜甫"],"explanation":"“无边落木萧萧下，不尽长江滚滚来”出自唐朝诗人杜甫的古诗作品《登高》第三四句，其全诗文如下：风急天高猿啸哀，渚清沙白鸟飞回。无边落木萧萧下，不尽长江滚滚来。万里悲秋常作客，百年多病独登台。艰难苦恨繁霜鬓，潦倒新停浊酒杯。"},{"id":2199,"type":"填空题","text":"红杏尚书指的是____。","options":[],"answer":["宋祁"],"explanation":"宋祁(公元998年-公元1061年)，字子京，小字选郎。是北宋官员、著名文学家、史学家、词人。司空宋庠之弟，宋祁与兄长宋庠并有文名，时称“二宋”。诗词语言工丽，因《玉楼春》词中有“红杏枝头春意闹”，世称“红杏尚书”。"},{"id":2200,"type":"填空题","text":"我国创作妇女诗最多的诗人是____。","options":[],"answer":["李白"],"explanation":"李白出生于商人家庭，曾经几次游历大江南北，也算是体察民情，在游历的过程中李白见过各种妇人不同的生活，也因此感叹颇多，所以在他的诗词中，很多是描写妇女的。有描写妇女的怨恨、离别、相思之情等。"},{"id":2201,"type":"填空题","text":"词这种文体起于唐代盛于____代。","options":[],"answer":["宋"],"explanation":"词最初称为“曲词”或“曲子词”,是配音乐的。 后来词也跟乐府一样，逐渐跟音乐分离，成为诗的别体，所以有人把词 称为“诗余”。 因其每句的长短丌一，所以又称“长短句”。"},{"id":2202,"type":"填空题","text":"负荆请罪的故事主角是廉颇和____。","options":[],"answer":["蔺相如"],"explanation":"《史记·廉颇蔺相如列传》：相如曰：“夫以秦王之威，而相如廷叱之，辱其群臣，相如虽弩，独畏廉将军哉！顾吾念之，强秦之所以不敢加兵予赵者，徒以吾两人在也，今两虎共斗，其势不俱生，吾所以为此者，以先国家之急而后私仇也。”廉颇闻之，肉袒负荆。因宾客至蔺相如门谢罪，曰：“鄙贱之人，不知将军宽之至此也!”卒相与欢，为刎颈之交。后世据此典故提炼出成语“负荆请罪”。"},{"id":2203,"type":"填空题","text":"“师者，所以传道受业解惑也。”中的“道”指的是____家礼教、思想。","options":[],"answer":["儒"],"explanation":"此句出自韩愈的《师说》，意思是：老师，是用来传授知识、教授学业、解答疑惑的人。“道”指的是儒家礼教、思想。"},{"id":2204,"type":"填空题","text":"“就像没有那回事一样，形容态度镇定，不把事情放在心上。”这句话描述的是成语____。","options":[],"answer":["若无其事"],"explanation":"好像没有那么回事似的，形容不动声色或漠不关心。"},{"id":2205,"type":"填空题","text":"《弟子规》总叙的全部内容为“弟子规，圣人训。____，次谨信。泛爱众，而亲仁。有余力，则学文。”","options":[],"answer":["首孝悌"],"explanation":"《弟子规》，原名《训蒙文》，是清朝李毓秀所作的三言韵文，约作于康熙年间。该文共为五个部分，其首章“总叙”将孔子的话，用三字句改编而成，为“弟子规，圣人训。首孝悌，次谨信。泛爱众，而亲仁。有余力，则学文。”"},{"id":2206,"type":"填空题","text":"我国传统图案里以石榴象征____。","options":[],"answer":["多子"],"explanation":"在中国传统文化中，石榴是吉祥的象征。它的果实里有很多石榴籽，寓意多子多福。所以可以送给已婚夫妇，代表多子多福。"},{"id":2207,"type":"填空题","text":"儒家代表人孔子在解释“仁”时说，“夫仁者，____，己欲达而达人”。","options":[],"answer":["己欲立而立人"],"explanation":"己欲立而立人，己欲达而达人出自于《论语·雍也》。欲:想要。立，站立。而，表转折，才能够。立人，使动用法，使人站立，意思是把摔倒的人扶起来。达，腾达。达人，使动用法，使人腾达，意思是周济需要帮助的人。"},{"id":2208,"type":"填空题","text":"“仁”最早出自____。","options":[],"answer":["尚书"],"explanation":"最早出自《尚书》。《尚书》中说：“克宽克仁，彰信兆民”，意思是说当年商汤用宽恕仁爱之德，明信于天下的百姓。“仁”最早的涵义是“亲人”的意思，《说文解字》中说：“亲，仁也”，又说：“仁，亲也”。主要是指家庭成员之间、氏族亲人之间要“亲爱”，这种“仁爱”之情，仅仅局限于家族亲属之间。"},{"id":2209,"type":"填空题","text":"“欲将轻骑逐”中“将”的意思是____。","options":[],"answer":["率领"],"explanation":"欲将轻骑逐，大雪满弓刀。出自卢纶的《和张仆射塞下曲六首》，意思是：正想要率领轻骑一路追杀，纷纷大雪，却已经洒满了将士的弓刀。"},{"id":2210,"type":"填空题","text":"“在危急的时刻，猛然想出办法。”这句话描述的是成语____。","options":[],"answer":["急中生智"],"explanation":"急中生智是，汉语成语，拼音是jí zhōng shēng zhì，意思是形容事态紧急的时候，突然想出办法。出自《和微之诗二十三首序》。"},{"id":2211,"type":"填空题","text":"“斯恶已”中“恶”的解释是____。","options":[],"answer":["丑陋"],"explanation":"天下皆知美之为美,斯恶已。皆知善之为善,斯不善已。摘自《老子·道经·第二章》 解释：当天下的人都知道都认为这件事是美好的话,那么它丑恶的一面就显现出来了。"},{"id":2212,"type":"填空题","text":"汉武帝时设立了一种专门的乐舞机构是____。","options":[],"answer":["乐府"],"explanation":"乐府是汉武帝时设立的专门管理音乐的机关。乐府负责培训乐工,制定乐谱,搜集和整理歌辞并配以乐曲。"},{"id":2213,"type":"填空题","text":"京剧的角色分为____。","options":[],"answer":["生旦净末丑"],"explanation":"京剧的角色分为生旦净末丑，其中“生”指男性角色,“旦”指女性角色,“净”指花脸,“末”指中年以上男子,“丑”指喜剧角色。"},{"id":2214,"type":"填空题","text":"三教九流中的“三教”指的是儒教、佛教、____。","options":[],"answer":["道教"],"explanation":"三教是指释道儒这三个传统宗教。儒家的创始人是孔子，所以儒教又叫做孔教，但是并不等同于儒学，儒教的教义是仁字，为民为天地，为求万事太平的仁是它们的最高教义，也是国内民族的本土宗教，历史悠久代表了所有文明礼乐。道教是用修炼追求得道成仙，寻求人与自然之间的和谐，它们的最高信仰其实是对于神仙的敬畏。"},{"id":2215,"type":"填空题","text":"我国文房四宝是____。","options":[],"answer":["笔墨纸砚"],"explanation":"笔墨纸砚，是中国独有的文书工具，即文房四宝。"},{"id":2216,"type":"填空题","text":"《礼记》中认为人的七情是指喜、怒、哀、乐、爱、恶、____。","options":[],"answer":["欲"],"explanation":"七情按《礼记》的观点指喜、怒、哀、惧、爱、恶、欲，按儒家的说法是喜、怒、哀、惧、爱、恶、欲，按佛教的说法则是喜、怒、忧、惧、爱、憎、欲，而医家的七情是喜、怒、忧、思、悲、恐、惊。"},{"id":2217,"type":"填空题","text":"“春城无处不飞花，寒食东风御柳斜。”出自____。","options":[],"answer":["寒食"],"explanation":"《寒食》是唐代诗人韩翃的一首七言绝句。全文为：春城无处不飞花，寒食东风御柳斜。日暮汉宫传蜡烛，轻烟散入五侯家。诗的前两句写的是白昼风光，描写了整个长安柳絮飞舞，落红无数的迷人春景和皇宫园林中的风光；后两句则是写夜晚景象，生动地画出了一幅夜晚走马传烛图，使人如见蜡烛之光，如闻轻烟之味。"},{"id":2218,"type":"填空题","text":"“天下第一行书”是王羲之的____。","options":[],"answer":["兰亭集序"],"explanation":"《兰亭集序》，又题为《临河序》、《禊帖》、《三月三日兰亭序》等。晋穆帝永和九年（公元353）三月三日，时任会稽内史的王羲之与友人谢安、孙绰等四十一人会聚兰亭，赋诗饮酒。王羲之将诸人名爵及所赋诗作编成一集，并作序一篇，记述流觞曲水一事，并抒写由此而引发的内心感慨。这篇序文就是《兰亭集序》。此序受石崇《金谷诗序》影响很大，其成就又远在《金谷诗序》之上。"},{"id":2219,"type":"填空题","text":"书法史上的“二王”是指王羲之和____两位书法家。","options":[],"answer":["王献之"],"explanation":"“二王”书法家是指王羲之和王献之，他们二人为父子，是东晋时期的大书法家。"},{"id":2220,"type":"填空题","text":"《祭侄文稿》被誉为“天下第二行书”，它的作者是____。","options":[],"answer":["颜真卿"],"explanation":"《祭侄文稿》，全名《祭侄赠赞善大夫季明文文稿》，俗谓《祭侄稿》。为唐朝书法家颜真卿所书，后世誉为“天下行书第二”，真迹现藏于台北国立故宫博物院。"},{"id":2221,"type":"填空题","text":"我国文学史上第一部诗歌总集____。","options":[],"answer":["诗经"],"explanation":"《诗经》，是中国古代诗歌开端，最早的一部诗歌总集，收集了西周初年至春秋中叶(前11世纪至前6世纪)的诗歌，共311篇，其中6篇为笙诗，即只有标题，没有内容，称为笙诗六篇(《南陔》《白华》《华黍》《由庚》《崇丘》《由仪》)，反映了周初至周晚期约五百年间的社会面貌。"},{"id":2222,"type":"填空题","text":"杰出的女纺织家黄道婆向____妇女学习棉纺织技术。","options":[],"answer":["黎族"],"explanation":"黄道婆，又名黄婆、黄母，是原松江府乌泥泾(今属上海市)人，宋末元初著名的棉纺织家、技术改革家。幼时为童养媳，曾因不堪虐待流落崖州(治所在今海南省三亚市崖城镇)，定居约40年，向黎族妇女学习棉纺织技艺并有改进，总结出“错纱、配色、综线、挈花”的织造技术。"},{"id":2223,"type":"填空题","text":"傈傈族语属于____语系。","options":[],"answer":["汉藏"],"explanation":"傈僳语属汉藏语系-藏缅语族-彝语支。"},{"id":2224,"type":"填空题","text":"芳华越剧团的创始人是____。","options":[],"answer":["尹桂芳"],"explanation":"福建省芳华越剧团，原为上海市芳华越剧团，由著名越剧表演艺术家尹桂芳于1946年在上海创建。"},{"id":2225,"type":"填空题","text":"“徐黄异体”指的是五代画家____和黄筌的花鸟画风格。","options":[],"answer":["徐熙"],"explanation":"徐熙画派，中国画流派之一。为五代花鸟画派的一支，代表画家徐熙。北宋郭若虚在《图画见闻志》\"论黄、徐体异\"时说\"黄家富贵，徐熙野逸。\"又说\"徐熙江南处士\"，\"多状江南所有，汀花野竹，水鸟渊鱼。\"此派多作粗笔浓墨，略施杂彩，而笔迹不隐，素有\"落墨花\"之称。"},{"id":2226,"type":"填空题","text":"中国现存最大的两座古代木构殿堂是____和凌恩殿。","options":[],"answer":["太和殿"],"explanation":"太和殿俗称金銮殿，为汉族宫殿建筑之精华，东方三大殿之一。中国现存最大的木结构大殿。位于北京紫禁城(故宫)南北主轴线的显要位置，明永乐十八年(1420年)建成，称奉天殿。明嘉靖四十一年(1562年)改称皇极殿，清顺治二年(1645年)改今名。建成后屡遭焚毁，多次重建，今殿为清康熙三十四年(1695年)重建后的形制。"},{"id":2227,"type":"填空题","text":"在我国古代，“鱼书”指的是____。","options":[],"answer":["书信"],"explanation":"鱼书是古时对书信的称谓。纸张出现以前，书信多写在白色丝绢上，为使传递过程中不致损毁，古人常把书信扎在两片竹木简中，简多刻成鱼形，故称鱼书。"},{"id":2228,"type":"填空题","text":"袁雪芬、严凤英、红线女、叶盛兰分别是越剧、____、粤剧、京剧的著名演员。","options":[],"answer":["黄梅戏"],"explanation":"袁雪芬、严凤英、红线女、叶盛兰分别是越剧、黄梅戏、粤剧、京剧的著名演员。"},{"id":2229,"type":"填空题","text":"京杭大运河数段中最早开凿的是____。","options":[],"answer":["邗沟"],"explanation":"京杭大运河最早开凿的河段是邗沟，从春秋吴王夫差十年起，以通江淮为起始点，之后是隋朝的运河系统，历经了元、明、清三个朝代的扩展，才初具规模，有了世界第一大运河的雏形，为我国的经济文化繁荣发展做出了杰出的贡献。"},{"id":2230,"type":"填空题","text":"耄耋之年指____岁。","options":[],"answer":["八九十"],"explanation":"耄耋之年是一个汉语成语，用作对老年人的泛称，指八九十岁。出自曹操《对酒》：“耄耋皆得以寿终，恩泽广及草木昆虫。”"},{"id":2231,"type":"填空题","text":"书法九势是____、转笔、藏峰、藏头、护尾、疾势、掠笔、涩势、横鳞竖勒。","options":[],"answer":["落笔"],"explanation":"书法九势为落笔、转笔、藏锋、藏头、护尾、疾势、掠笔、涩势、横鳞竖勒，为汉代书法家蔡邕对书法中行笔技巧的总结。"},{"id":2232,"type":"填空题","text":"饮中八仙为____、贺知章、李适之、李琎、崔宗之、苏晋、张旭、焦遂。","options":[],"answer":["李白"],"explanation":"醉八仙，指唐朝嗜酒的八位学者名人，亦称酒中八仙、饮中八仙。《新唐书·李白传》载，李白、贺知章、李适之、汝阳王李琎、崔宗之、苏晋、张旭、焦遂为“酒中八仙人”。杜甫有《饮中八仙歌》。瓷器画面绘饮中八仙，每每于人物之上书以人名，以清朝为多见。"},{"id":2233,"type":"填空题","text":"扬州八怪是郑板桥、汪士慎、李鱓、黄慎、金农、高翔、李方鹰、____。","options":[],"answer":["罗聘"],"explanation":"扬州八怪，是清康熙中期至乾隆末年活跃于扬州地区的一批风格相近的书画家总称，美术史上也常称其为“扬州画派”，指：金农、郑燮、黄慎、李鱓、李方膺、汪士慎、罗聘、高翔。"},{"id":2234,"type":"填空题","text":"“河鼓二”在天文学上是指____。","options":[],"answer":["牛郎星"],"explanation":"河鼓二指天鹰座α星，又称“牛郎星”。古代传说牛郎织女七月七日鹊桥相会。实际上牛郎织女相距16光年，即使乘现代最强大的火箭，几百年后也不曾相会。河鼓二的两侧各有一颗较暗的星，分别称为河鼓一、河鼓三，它们与河鼓二合称为“河鼓三星”。河鼓三星像一根长长的扁担，所以民间又叫它“扁担星”。"},{"id":2235,"type":"填空题","text":"唐宋八大家是____、柳宗元、欧阳修、苏洵、苏轼、苏辙、王安石、曾巩。","options":[],"answer":["韩愈"],"explanation":"唐宋八大家，又称为“唐宋散文八大家”，是唐代和宋代八位散文家的合称，分别为唐代韩愈、柳宗元和宋代欧阳修、苏洵、苏轼、苏辙、王安石、曾巩八位。其中韩愈、柳宗元是唐代古文运动的领袖，欧阳修、三苏（苏轼、苏辙、苏洵）等四人是宋代古文运动的核心人物，王安石、曾巩是临川文学的代表人物。他们先后掀起的古文革新浪潮，使诗文发展的陈旧面貌焕然一新。"},{"id":2236,"type":"填空题","text":"十三经是____、《诗经》、《尚书》、《礼记》、《仪礼》、《公羊传》、《榖梁传》、《左传》、《孝经》、《论语》、《尔雅》、《孟子》。","options":[],"answer":["易经"],"explanation":"《十三经》，南宋形成的十三部儒家经典，为历代儒客文人推崇。分别是《易经》《尚书》《诗经》《周礼》《仪礼》《礼记》《春秋左传》《春秋公羊传》《春秋榖梁传》《孝经》《论语》《孟子》《尔雅》。"},{"id":2237,"type":"填空题","text":"四大民间传说是____、孟姜女、梁山伯与祝英台、白蛇与许仙。","options":[],"answer":["牛郎织女"],"explanation":"在我国的古典文学宝库中，除了有史书记载的古典文学作品外，还有一类就是民间广为流传的神话传说，它不仅数量众多，内容丰富，而且绚丽多彩，充满诗情画意和艺术魅力，其中牛郎织女、孟姜女、梁山伯与祝英台与白蛇传被称为中国四大民间传说。"},{"id":2238,"type":"填空题","text":"五音是____。","options":[],"answer":["宫商角徵羽"],"explanation":"五音指中国五声音阶中的角、徵、宫、商、羽，五个音级。五音中各相邻两音间的音程，除角和徵、羽和宫（高八度的宫）之间为小三度外，余均为大二度。"},{"id":2239,"type":"填空题","text":"相声八德是____、玉德隆、焦德海、张德全、周德山、马德禄、刘德治、李德祥。","options":[],"answer":["李德钖"],"explanation":"李德钖(1881-1926)，相声艺人。原名李佩亭，艺名万人迷。北京人。时人誉之为“相声大王”，与其他七位“德”字辈著名相声艺人并称“相声八德”。作品有《老老年》《对对子》《哭当票》《十八愁绕口令》。"},{"id":2240,"type":"填空题","text":"四大名瓷窑是河北的瓷州窑、浙江的龙泉窑、江西的____、福建的德化窑。","options":[],"answer":["景德镇窑"],"explanation":"中国四大名瓷窑：河北磁州窑、浙江的龙泉窑、江西的景德镇窑、福建的德化窑。四大名窑是中国传统陶瓷烧制工艺中的艺术珍品，劳动人民生产的瓷器，继唐代“南青北白”的格局确定之后，到了宋代发展到了前所未有的高峰。"},{"id":2241,"type":"填空题","text":"昭陵六骏是什伐赤、青骓、特勤骠、飒露紫、拳毛騧、____。","options":[],"answer":["白蹄乌"],"explanation":"昭陵六骏分别叫飒露紫、拳毛騧、白蹄乌、特勒骠、青骓和什伐赤。六骏中,有侍者牵引的飒露紫塑造最为精采。"},{"id":2242,"type":"填空题","text":"五贡是____、拔贡、岁贡、副贡、优贡。","options":[],"answer":["恩贡"],"explanation":"清代科举制度中对五类贡生的总称.。包括:恩贡、拔贡、副贡、岁贡和优贡。这五类都是正途出身资格。另有捐纳取得的贡生，称为例贡。"},{"id":2243,"type":"填空题","text":"六朝是吴、东晋、宋、齐、梁、____。","options":[],"answer":["陈"],"explanation":"六朝(222年–589年)，一般是指中国历史上三国至隋朝的南方的六个朝代。即孙吴(或称东吴、三国吴)、东晋、南朝宋(或称刘宋)、南朝齐(或称萧齐)、南朝梁(或称萧梁)、南朝陈这六个朝代。又因六朝皆以建康(今南京)为京师，所以后世许多文献皆以六朝或南朝来代指南京，并常会用南京来指明六朝时期的人事物，所以南京又称六朝古都。"},{"id":2244,"type":"填空题","text":"六历是____、《颛顼历》、《夏历》、《殷历》、《周历》、《鲁历》。","options":[],"answer":["黄帝历"],"explanation":"古六历通常是指从春秋战国到秦朝时期制定的黄帝、颛、夏、殷、周、鲁六种历法。六历的不同主要是“历元”（年的起算点）、施行地区和所用的元朔。"},{"id":2245,"type":"填空题","text":"三山是指安徽____、江西庐山、浙江雁荡山。","options":[],"answer":["黄山"],"explanation":"三山是指旅游胜地闻名的黄山、庐山、雁荡山。"},{"id":2246,"type":"填空题","text":"诗经是我国第一部诗歌总集，其中包括____首诗。","options":[],"answer":["三百零五"],"explanation":"《诗经》是我国第一部诗歌总集，收集了自西周初年至春秋中叶五百多年的诗歌305篇。"},{"id":2247,"type":"填空题","text":"“月上柳梢头，人约黄昏后”描写的传统节日是____。","options":[],"answer":["元宵节"],"explanation":"“月上柳梢头，人约黄昏后”是北宋诗人欧阳修写的一首词，名为：《生查子•元夕》 ，全词：去年元夜时，花市灯如昼。月上柳梢头，人约黄昏后。今年元夜时，月与灯依旧。不见去年人，泪湿春衫袖。整首词创作背景是一年的伊始之际——元宵。"},{"id":2248,"type":"填空题","text":"“词苑千载，群芳竞秀，盛开一枝女儿花”说的是历史上的____。","options":[],"answer":["李清照"],"explanation":"“词苑千载，群芳竞秀，盛开一枝女儿花”说的是李清照。李清照号称为“易安居士”。"},{"id":2249,"type":"填空题","text":"诸子百家中名家的特点是注重逻辑辩证，____这个典故能表达名家的这一特点。","options":[],"answer":["白马非马"],"explanation":"“名家”是先秦时期以辩论名实问题为中心的一个思想派别,重视“名”(概念)和“实”(事)的关系的研究。包括“白马非马”、“离坚白”、“合同异”等观点。"},{"id":2250,"type":"填空题","text":"古人的婚礼在____（时间）举行。","options":[],"answer":["黄昏"],"explanation":"古人结婚时间一般是黄昏。无论是因为黄昏的昏和结婚的婚读音很接近的缘故，还是因为黄昏风景美丽的缘故，古人大多数都选择在黄昏结婚。"},{"id":2251,"type":"填空题","text":"“天时不如地利，地利不如人和”出自____。","options":[],"answer":["孟子"],"explanation":"《天时不如地利，地利不如人和》出自《孟子·公孙丑下》。天时不如地利，地利不如人和的意思是：有利的时机和气候不如有利的地势，有利的地势不如人心所向。"},{"id":2252,"type":"填空题","text":"文学史上被称作“小李杜”的是杜牧和____。","options":[],"answer":["李商隐"],"explanation":"唐诗中以李白、杜甫的作品最享负盛名。至中晚唐，诗风的发展已近末流。因珠玉在前，后人已难有突破。当时一般诗人虽偶有佳作，但惟有杜牧和李商隐二人，能被时人一致公认为最杰出的作家。鉴於二人刚巧一位姓李,一位姓杜，与盛唐李杜相同，故称其为小李杜，以示与李白杜甫齐名。"},{"id":2253,"type":"填空题","text":"我国书法艺术博大精深，“欧体”是指____的字体。","options":[],"answer":["欧阳询"],"explanation":"书法上的“欧体”是指欧阳询的字体，对应于楷书四大家“颜柳欧赵”中的欧，欧体结构严谨，于平正中见险绝，被尊为“唐人楷书第一”。"},{"id":2254,"type":"填空题","text":"“大禹治水”的故事家喻户晓，大禹治理的是____流域的洪水。","options":[],"answer":["黄河"],"explanation":"大禹治水(鲧禹治水)是古代的汉族神话传说故事，著名的上古大洪水传说。他是黄帝的后代，三皇五帝时期，黄河泛滥，鲧、禹父子二人受命于尧、舜二帝，任崇伯和夏伯，负责治水。这一时期，黄河流域水患特别严重，百姓经常因为水患而流离失所，庄家更是颗粒无收，正因如此，治理黄河水患的问题一直困扰着人们。到了尧舜时期，黄河流域流水情况更加不稳定，已经到了不可不治的状况了。"},{"id":2255,"type":"填空题","text":"《西游记》中唐僧的原型是____。","options":[],"answer":["玄奘"],"explanation":"唐僧，俗家姓陈，生于河南洛阳，法号“玄奘”，被尊称为“三藏法师”，世俗称为“唐僧”，小名叫“江流儿”。中国古典名著《西游记》中的主角之一，原型为唐代高僧玄奘。"},{"id":2256,"type":"填空题","text":"京剧《贵妃醉酒》是根据____这部古代戏曲改编而成的。","options":[],"answer":["长生殿"],"explanation":"京剧中《贵妃醉酒》是由《长生殿》这部古代戏曲改编而成的，这首曲子讲述的是唐玄宗和杨玉环的爱情故事。"},{"id":2257,"type":"填空题","text":"荀子把教学或学习过程具体化为闻、见、知、____四个环节。","options":[],"answer":["行"],"explanation":"闻、见、知、行为中国战国时期荀子提出的关于教学过程或学习过程的几个环节。荀子认为，学习当启始于“闻”，完成于“行”。提出:“君子之学也，入乎耳，箸乎心，布乎四体，形乎动静。"},{"id":2258,"type":"填空题","text":"“一门父子三词客，千古文章八大家”这幅对联中提到的“三父子”是苏洵、苏轼、____。","options":[],"answer":["苏辙"],"explanation":"“一门父子三词客，千古文章八大家”中三词客为：北宋苏洵、苏轼、苏辙；这是对苏轼、苏辙、苏洵三父子在文坛上的成就的褒奖"},{"id":2259,"type":"填空题","text":"“一问三不知”，“三不知”说的是事情的开始、经过、____。","options":[],"answer":["结果"],"explanation":"出自《左传·哀公二十七年》，原意是对某一事情的开始、发展、结果都不知道，现在用来表示对实际情况一点也不知道。"},{"id":2260,"type":"填空题","text":"水浒一百单八将中有____位女性。","options":[],"answer":["三"],"explanation":"水浒传108将中的三名女将分别是顾大嫂、扈三娘、还有孙二娘，其中顾大嫂的结局最好。"},{"id":2261,"type":"填空题","text":"“山重水复疑无路,柳暗花明又一村。”出自陆游的____。","options":[],"answer":["游山西村"],"explanation":"“山重水复疑无路，柳暗花明又一村”是宋代诗人陆游的作品《游山西村》中的一句诗。比喻在遇到困难一种办法不行时，可以用另一种办法去解决，通过探索去发现答案。"},{"id":2262,"type":"填空题","text":"____节来源于二十四节气。","options":[],"answer":["清明"],"explanation":"清明节的得名源于我国农历24节气中的清明节气。清明节气共有15天，作为节气的清明，时间在春分之后。"},{"id":2263,"type":"填空题","text":"____是我国北宋年间司马光主编的一部编年体。","options":[],"answer":["资治通鉴"],"explanation":"《资治通鉴》（常简作《通鉴》），由北宋司马光主编的一部多卷本编年体史书，共294卷，历时19年完成。主要以时间为纲，事件为目，从周威烈王二十三年（公元前403年）写起，到五代后周世宗显德六年（公元959年）征淮南停。"},{"id":2264,"type":"填空题","text":"金沙江发源于____。","options":[],"answer":["唐古拉山脉"],"explanation":"金沙江的发源地（即长江的发源地）20世纪70年代定于青海省唐古拉山主峰各拉丹冬雪山，正源沱沱河。"},{"id":2265,"type":"填空题","text":"诗句“二十四桥明月夜，玉人何处教吹箫”中的“二十四桥”位于____。","options":[],"answer":["扬州"],"explanation":"一说扬州城里原有二十四座桥；一说即吴家砖桥，因古时有二十四位美女吹箫于桥上而得名。"},{"id":2266,"type":"填空题","text":"苏轼在《念奴娇·赤壁怀古》中提到了“羽扇纶巾，谈笑间，樯橹灰飞烟灭”，“羽扇纶巾”形容的是____。","options":[],"answer":["周瑜"],"explanation":"羽扇纶巾，意思是拿着羽毛扇子，戴着青丝绶的头巾。形容态度从容。出自宋·苏轼《念奴娇·赤壁怀古》，指代汉末儒将周瑜的便装打扮 。"},{"id":2267,"type":"填空题","text":"“归去来兮，吾归何处？”是苏轼所发出的哀叹之音,似有归隐田园之意。东晋一田园诗人曾有《归去来兮辞》文章，其诗人是____。","options":[],"answer":["陶渊明"],"explanation":"《归去来兮辞》是晋宋之际文学家陶渊明创作的抒情小赋，也是一篇脱离仕途回归田园的宣言。这篇文章作于作者辞官之初，叙述了他辞官归隐后的生活情趣和内心感受，表现了他对官场的认识以及对人生的思索，表达了他洁身自好、不同流合污的精神情操。"},{"id":2268,"type":"填空题","text":"唐诗大变于中唐，代表这种新变的第一诗人群是____诗派。","options":[],"answer":["韩孟"],"explanation":"“韩孟诗派”是中唐的一个诗歌创作流派，以韩愈为领袖，包括孟郊、李贺、卢仝、马异、刘叉。他们主张“不平则鸣”，苦吟以抒愤，并互相切磋酬唱他们具有变态的审美趣味，“以丑为美”，以震荡光怪为美，以瘁索枯槁为美，以五彩斑斓为美。表现出重主观心理、尚奇险怪异的创作倾向。诗歌形成一种奇崛硬险的风格。他们在艺术上力求避熟就生，标新立异，力矫大历诗风的平弱纤巧。这种诗歌的新的追求与新的变化，积极推动了盛唐以后诗歌艺术境界的开拓。"},{"id":2269,"type":"填空题","text":"元曲在元代被称作____。","options":[],"answer":["新乐府"],"explanation":"元曲在元代被称“乐府”，“新乐府”，“北乐府”。人们通常所说的元曲，包括剧曲和散曲。剧曲指的是杂剧的曲辞，它是戏剧这一在舞台上表演的综合艺术的密不可分的组成部分。"},{"id":2270,"type":"填空题","text":"宋代最早提倡复古和文体复古的代表人物是____。","options":[],"answer":["柳开"],"explanation":"柳开（947年－1000年），原名肩愈，字绍先（一作绍元），后改名开，字仲涂，号东郊野夫、补亡先生，大名（今河北大名）人，北宋文学家。因官至如京使，世称柳如京。柳开是开宝六年进士，历任州、军长官，殿中侍御史，提倡韩愈、柳宗元的散文，以复兴古道、述作经典自命。反对宋初的华靡文风，为宋代古文运动倡导者。作品文字质朴，然有枯涩之病。诗作现存八首。著《河东集》。"},{"id":2271,"type":"填空题","text":"鲁迅先生称史记为“史家之绝唱，____”。","options":[],"answer":["无韵之离骚"],"explanation":"“史家之绝唱，无韵之离骚”的意思是史家独一无二的文章，没有韵的《离骚》。史家之绝唱，无韵之离骚是鲁迅对司马迁《史记》的评价，这是一个相当高的评价。《离骚》是屈原的代表作，在我国古代文学史上有着划时代的意义，书写了高洁的志向和人格。"},{"id":2272,"type":"填空题","text":"“四书”的构成为大学、孟子、论语、____。","options":[],"answer":["中庸"],"explanation":"四书包括：《论语》、《大学》、《中庸》、《孟子》。宋儒为明代进士。四书是教人做人的学问，是国人的精神之所在。"},{"id":2273,"type":"填空题","text":"《离骚》在诗歌形式上所属的体式是____。","options":[],"answer":["七言体"],"explanation":"离骚在诗歌形式上所属的体式是七言体。七言诗是中国诗歌体裁之一,主要特点是每句七字或以七字句为主,而离骚全诗大部分句子都是七字的,因此离骚属于七言体诗歌。"},{"id":2274,"type":"填空题","text":"与曹操有关的著名典故为____。","options":[],"answer":["望梅止渴"],"explanation":"南朝宋，刘义庆《世说新语·假谲》：有一次曹操带兵在外行军，一时找不到取水的地方，士兵都渴极了，曹操就骗他们说：“前面有个大梅林，梅子又甜又酸，可以解渴。”士兵听了，一个个都流出了口水，暂时止住了口渴。"},{"id":2275,"type":"填空题","text":"我国古代最早提出“废黜百家，独尊儒术”的是____。","options":[],"answer":["董仲舒"],"explanation":"“罢黜百家，独尊儒术”，是董仲舒于元光元年(公元前134年)提出的治国思想，在汉武帝时开始推行。"},{"id":2276,"type":"填空题","text":"____是我国湖北省的简称。","options":[],"answer":["鄂"],"explanation":"湖北省，位于中国中部偏南、长江中游，洞庭湖以北，故名湖北，简称“鄂”，省会武汉。"},{"id":2277,"type":"填空题","text":"变脸是____的绝活。","options":[],"answer":["川剧"],"explanation":"川剧变脸是川剧表演的特技之一，用于揭示剧中人物的内心及思想感情的变化，即把不可见、不可感的抽象的情绪和心理状态变成可见、可感的具体形象——脸谱。川剧变脸是运用在川剧艺术中塑造人物的一种特技。是揭示剧中人物内心思想感情的一种浪漫主义手法。"},{"id":2278,"type":"填空题","text":"长江三峡是指由巫峡、瞿塘峡和____。","options":[],"answer":["西陵峡"],"explanation":"长江三峡又名峡江或大三峡，位于中国重庆市、恩施州、宜昌市地区境内的长江干流上，西起重庆市奉节县的白帝城，东至湖北省宜昌市的南津关，全长193千米，由瞿塘峡、巫峡、西陵峡组成。"},{"id":2279,"type":"填空题","text":"沉鱼落雁其中的沉鱼最开始指____。","options":[],"answer":["毛嫱"],"explanation":"“沉鱼落雁”这个成语，源出自《庄子·齐物论》中的“毛嫱、丽姬，人之所美也，鱼见之深入，鸟见之高飞，麋鹿见之决骤。”"},{"id":2280,"type":"填空题","text":"“四象二十八星宿”是我国古代天文学最重要的成就，也是中国传统文化中最神秘的部分之一。其中的“四象”被称为“四方神”，影响及于我国古代的军事、宗教、文学、风水等各个领域。四象指的是青龙、____、朱雀、玄武。","options":[],"answer":["白虎"],"explanation":"“四象”通常指的是左青龙,右白虎,前朱雀,后玄武。古代汉族人民把东、西、南、北四方每一方的七宿想象为四种动物形象，叫作四象。"},{"id":2281,"type":"填空题","text":"我国古代贵族四术为诗、书、礼和____。","options":[],"answer":["乐"],"explanation":"《诗经》中的歌曲曾被列为上层社会教育的主要科目，所谓诗、书、礼、乐并称“四术”。"},{"id":2282,"type":"填空题","text":"中国四大名绣为苏绣、湘绣、蜀绣、____。","options":[],"answer":["粤绣"],"explanation":"中国四大名绣，是指中国中部湖南省的“湘绣”，中国西部四川省的“蜀绣”，中国南部广东省的“粤绣”和中国东部江苏省的“苏绣”的合称。"},{"id":2283,"type":"填空题","text":"《孙子兵法•火攻篇》在论及火攻时罗列了五种火攻，分别是火人、火积、火辎、火库和____。","options":[],"answer":["火队"],"explanation":"孙子曰：“凡火攻有五：一曰火人，二曰火积，三曰火辎，四曰火库，五曰火队。”"},{"id":2284,"type":"填空题","text":"六义是诗经学名词，指的是风、雅、颂、赋、比、____。","options":[],"answer":["兴"],"explanation":"《诗经》是中国文学史上第一部诗歌总集，收入西周初期至春秋中叶间的诗歌三百零五篇。所谓《诗经》中的“六义”，是指“风、雅、颂”三种诗歌形式与“赋、比、兴”三种表现手法。"},{"id":2285,"type":"填空题","text":"“按图索骥”中的“骥”本意指的是____。","options":[],"answer":["马"],"explanation":"索：找；骥：良马。按照画像去寻求好马。比喻墨守成规办事；也比喻按照线索去寻求。"},{"id":2286,"type":"填空题","text":"“环肥燕瘦”中的“燕”是指谁_____","options":[],"answer":["赵飞燕"],"explanation":"环是指的唐玄宗贵妃杨玉环，燕是指的汉成帝皇后赵飞燕。形容女子形态不同，各有各好看的地方。也借喻艺术作品风格不同，而各有所长。"},{"id":2287,"type":"填空题","text":"屈原在____中写道，“吾令羲和弭节兮，望崦嵫而勿迫。”","options":[],"answer":["离骚"],"explanation":"《离骚》是战国诗人屈原创作的文学作品。“离骚”，东汉王逸释为：“离，别也；骚，愁也。”《离骚》以理想与现实的冲突为主线，以花草禽鸟的比兴和瑰奇迷幻的“求女”神境作象征，借助于自传性回忆中的情感激荡，和复沓纷至、倏生倏灭的幻境交替展开全诗。作品倾诉了对楚国命运和人民生活的关心，“哀民生之多艰”，叹奸佞之当道。主张“举贤而授能”，“循绳墨而不颇”。提出“皇天无私阿”，对天命论进行批判。作品中大量的比喻和丰富的想像，表现出积极浪漫主义精神，并开创了中国文学上的“骚”体诗歌形式，对后世有深远影响。有东汉王逸《楚辞章句》、南宋朱熹《楚辞集注》、清代戴震《屈原赋注》等注本。"},{"id":2288,"type":"填空题","text":"“尔曹身与名俱灭，不废江河万古流。”出自____的《戏为六绝句》(其二)。","options":[],"answer":["杜甫"],"explanation":"出处：唐，杜甫《戏为六绝句》（其二）全文为：王杨卢骆当时体，轻薄为文哂未休。尔曹身与名俱灭，不废江河万古流。"},{"id":2289,"type":"填空题","text":"“相见争如不见，有〔多〕情何似无情。”出自宋代____的《西江月》。","options":[],"answer":["司马光"],"explanation":"相见争如不见，有情何似无情。出自宋代司马光的《西江月》，全文是：“宝髻松松挽就，铅华淡淡妆成。青烟翠雾罩轻盈，飞絮游丝无定。相见争如不见，有情何似无情。笙歌散后酒初醒，深院月斜人静。”"},{"id":2290,"type":"填空题","text":"“泪眼问花花不语，乱红飞过秋千去。”出自____的《蝶恋花》。","options":[],"answer":["欧阳修"],"explanation":"出自欧阳修的《蝶恋花》。全文是：“庭院深深深几许，杨柳堆烟，帘幕无重数。玉勒雕鞍游冶处,楼高不见章台路。雨横风狂三月暮，门掩黄昏，无计留春住。泪眼问花花不语，乱红飞过秋千去。”"},{"id":2291,"type":"填空题","text":"及笄之年是指____岁。","options":[],"answer":["十五"],"explanation":"及笄是指女子满了15岁。形容古代女子已到了结婚的年龄。"},{"id":2292,"type":"填空题","text":"中元节是我国的传统节日之一,而在民间中元节也被人们称为____。","options":[],"answer":["鬼节"],"explanation":"中元节是我国的传统节日之一，而在民间中元节也被人们称为鬼节。当日祭拜时着装得体，以黑色灰色着装为宜。忌红色等大红大紫之色。否则容易招致煞气，惹祸上身。拜祭时要态度端正，不要大声喧哗，出言不逊或有不雅举止。据说否则会打扰到死者的灵魂，重者更会招致怨气。七月十五要外出游玩的朋友，要在太阳落山前返回。否则阳气退去，阴气见长，体弱多病之人则容易受到阴气袭扰。"},{"id":2293,"type":"填空题","text":"补全诗句：“秋风吹不尽，____。”","options":[],"answer":["总是玉关情"],"explanation":"出自唐·李白《子夜吴歌·秋歌》。全文为：长安一片月，万户捣衣声。秋风吹不尽，总是玉关情。何日平胡虏，良人罢远征。"},{"id":2294,"type":"填空题","text":"补全词：“杜郎俊赏，算而今，重到须惊。纵豆蔻词工，青楼梦好，____。”","options":[],"answer":["难赋深情"],"explanation":"出自宋诗人姜夔的《扬州慢·淮左名都》。全文为：淳熙丙申至日，予过维扬。夜雪初霁，荠麦弥望。入其城，则四顾萧条，寒水自碧，暮色渐起，戍角悲吟。予怀怆然，感慨今昔，因自度此曲。千岩老人以为有“黍离”之悲也。淮左名都，竹西佳处，解鞍少驻初程。过春风十里。尽荠麦青青。自胡马窥江去后，废池乔木，犹厌言兵。渐黄昏，清角吹寒。都在空城。杜郎俊赏，算而今、重到须惊。纵豆蔻词工，青楼梦好，难赋深情。"},{"id":2295,"type":"填空题","text":"2013年4月，本着生态性、文化性、地方特色与时代性相结合的原则统筹考虑，最终选出“屯溪八景”，分别是谜窟探奇、新安怀古、华山思贤、老街问市、三江烟霞、稽灵松涛、龙山禅月和____。","options":[],"answer":["鬲山荷韵"],"explanation":"“屯溪八景”分别是“谜窟探奇”、“新安怀古”、“华山思贤”、“老街问市”、“三江烟霞”、“稽灵松涛”、“龙山禅月”和“鬲山荷韵”。"},{"id":2296,"type":"填空题","text":"清代出现的以满族菜为主，沿袭明代宫廷风格的菜肴，被称为____。","options":[],"answer":["满汉全席"],"explanation":"满汉全席，清朝时期宫廷盛宴。既有宫廷菜肴之特色，又有地方风味之精华；突出满族与汉族菜的特殊风味，烧烤、火锅、涮涮锅几乎不可缺少的菜点，同时又展示了汉族烹调的特色，扒、炸、炒、熘、烧等兼备，实乃中华菜系文化的瑰宝和最高境界。满汉全席原是清代宫廷中举办宴会时满人和汉人合坐的一种全席。"},{"id":2297,"type":"填空题","text":"中国画史上，被公认为水准最高的山水画作是元代画作____。","options":[],"answer":["富春山居图"],"explanation":"富春山居图是元代画家黄公望于1350年创作的纸本水墨画，中国十大传世名画之一。"},{"id":2298,"type":"填空题","text":"五岳中以“险”著称的是____。","options":[],"answer":["华山"],"explanation":"五岳即东岳泰山、西岳华山、北岳恒山、中岳嵩山、南岳衡山。论景观，五岳又各具特色：泰山雄、衡山秀、华山险，恒山奇，嵩山奥。"},{"id":2299,"type":"填空题","text":"成语“胸有成竹”源于宋代____画竹的故事。","options":[],"answer":["文同"],"explanation":"北宋时候，有一个著名的画家，名叫文同，他是当时画竹子的高手。文同为了画好竹子，不管是春夏秋冬，也不管是刮风下雨，或是天晴天阴，他都常年不断地在竹林子里头钻来钻去，为的就是把竹子不同时期的姿态记在心头。由于文同长年累月地对竹子作了细微的观察和研究，竹子在春夏秋冬四季的形状有什么变化；在阴晴雨雪天，竹子的颜色、姿势又有什么两样；在强烈的阳光照耀下和在明净的月光映照下，竹子又有什么不同；不同的竹子，又有哪些不同的样子，他都摸得一清二楚。所以画起竹子来，根本用不着画草图。有个名叫晁补之的人，称赞文同说：文同画竹，早已胸有成竹了。"},{"id":2300,"type":"填空题","text":"中国古代祭祀天地的仪式很多，其中最为隆重的是____。","options":[],"answer":["封禅"],"explanation":"封禅，封为“祭天”，禅为“祭地”，意思是指中国古代帝王在太平盛世或天降祥瑞之时的祭祀天地的大型典礼，一般由帝王亲自到泰山上举行。远古暨夏商周三代，已有封禅的传说。出自《管子·封禅篇》。"},{"id":2301,"type":"填空题","text":"自秦至今，我国一直沿用的行政区划单位是____。","options":[],"answer":["县"],"explanation":"秦始皇即位时推行“郡县制”；秦代沿袭了秦的郡县制，与郡国并存；东汉形成“州、郡、县三级制”；隋又改为“郡(州)、县二级制”；唐设“道”对地方实行监察，将“郡”改称“州”，实行“道、州、县三级制”；宋改“道”为“路”，实行“路、州、县三级制”；元推行行省制,形成“省、道路、州(府)、县四级制”；明承元制，改行省为“承宣布政使司”,形成“司、府(州)、县”三级制；清承明制，改司为省，省名与今相近。由此，“县”是自秦迄今一直沿用的行政区划单位。"},{"id":2302,"type":"填空题","text":"北魏时期，提出“除去三张伪法”，鼓动灭佛、改革天师道的道士是____。","options":[],"answer":["寇谦之"],"explanation":"北魏道士寇谦之称太上老君亲临嵩岳授以“天师之位”，赐以《云中音诵新科之戒》20卷，传其服气导引口诀之法；令其“清整道教，除去三张（指张陵、张衡、张鲁——引者）伪法，租米钱税及男女合气之术”。"},{"id":2303,"type":"填空题","text":"中国五岳是____、南岳衡山、西岳华山、北岳恒山和中岳嵩山。","options":[],"answer":["东岳泰山"],"explanation":"中国五岳，中华传统文化中五大名山的总称，是古代民间山神崇敬、五行观念和帝王巡猎封禅相结合的产物。五岳分别是中岳嵩山(海拔1491.71米，位于河南省郑州市登封市)、东岳泰山(海拔1532.7米， 位于山东省泰安市泰山区)、西岳华山(海拔2154.9米，位于陕西省渭南市华阴市)、南岳衡山(海拔1300.2米，位于湖南省衡阳市南岳区)、北岳恒山(海拔2016.1米，位于山西省大同市浑源县)。岳曾是封建帝王仰天功之巍巍而封禅祭祀的地方，更是封建帝王受命于天的象征。"},{"id":2304,"type":"填空题","text":"《金匮要略》是我国著名医学家____的传世著作。","options":[],"answer":["张仲景"],"explanation":"《金匮要略》是我国东汉著名医学家张仲景所著《伤寒杂病论》的杂病部分，也是我国现存最早的一部论述杂病诊治的专书，原名《金匮要略方论》。“金匮”是存放古代帝王圣训和实录的地方，意指本书内容之珍贵。全书分上、中、下三卷，共25篇，载疾病60余种，收方剂262首。所述病证以内科杂病为主，兼及外科、妇科疾病及急救卒死、饮食禁忌等内容。被后世誉为“方书之祖”。"},{"id":2305,"type":"填空题","text":"中国“四大石窟”指的是____、云冈石窟、龙门石窟、麦积山石窟。","options":[],"answer":["莫高窟"],"explanation":"四大石窟指的是以中国佛教文化为特色的巨型石窟艺术景观，包括：莫高窟（甘肃敦煌）、云冈石窟（山西大同）、龙门石窟（河南洛阳）、麦积山石窟（甘肃天水），是中国古代传统文化艺术的历史瑰宝。"},{"id":2306,"type":"填空题","text":"我国最早一部家庭教育专著是____的《颜氏家训》。","options":[],"answer":["颜之推"],"explanation":"《颜氏家训》是汉民族历史上第一部内容丰富，体系宏大的家训，也是一部学术著作。作者颜之推，是南北朝时期著名的文学家、教育家。"},{"id":2307,"type":"填空题","text":"“鹅湖之会”是书院史上的著名事件，他指的是朱熹和____在鹅湖书院进行的辩论。","options":[],"answer":["陆九渊"],"explanation":"著名学者吕祖谦为了调和朱熹“理学”和陆九渊“心学”两派之间在学术上的矛盾，邀请他们在江西鹅湖寺举行学术交流，史称“鹅湖之会”。这次大会进行了三天，双方各持己见、互不相让。虽然学术上的分歧没能得到解决。但是这次讨论会影响很大，是中国哲学史上堪称典范的一次学术讨论会，而且开启了书院会讲的先河。"},{"id":2308,"type":"填空题","text":"自汉代以来，太学内官设辟雍，专供____讲学之用。","options":[],"answer":["皇帝"],"explanation":"自汉代以来，太学内多设辟雍，供皇帝讲学。每逢皇帝来讲学，太学(或国子监)的官员和学生都要跪在泮水四周聆听。"},{"id":2309,"type":"填空题","text":"最早使用“教育”两字的是____。","options":[],"answer":["孟子"],"explanation":"在中国古代文献中，教育一词最早见于《孟子·尽心上》，“得天下英才而教育之”。《说文解字》释“教，上所施下所效”；“育，养子使作善也”，教育就是教诲培育的意思。"},{"id":2310,"type":"填空题","text":"根据古代“左庙右学”的传统，国子监与____毗邻。","options":[],"answer":["孔庙"],"explanation":"国子监是我国元、明、清三代国家管理教育的最高行政机关和国家设立的最高学府，孔庙则是皇家祭孔之地，两者相伴形成“左庙右学”。"},{"id":2311,"type":"填空题","text":"江南三大名楼是____、岳阳楼、黄鹤楼。","options":[],"answer":["滕王阁"],"explanation":"江南三大名楼指的是江西南昌的滕王阁、湖北武汉的黄鹤楼和湖南岳阳的岳阳楼。"},{"id":2312,"type":"填空题","text":"苏州四大园林指的是____、狮子林、拙政园和留园。","options":[],"answer":["沧浪亭"],"explanation":"沧浪亭、狮子林、拙政园和留园并称苏州四大园林，代表着宋（公元960～1278年）、元（公元1271～1368年）、明（公元1368～1644年）、清（公元1644～1911年）四个朝代的艺术风格，被称为苏州四大名园。"},{"id":2313,"type":"填空题","text":"被誉为“中国戏曲之母”的剧种是____。","options":[],"answer":["昆曲"],"explanation":"昆剧（别称昆腔、昆曲），原名“昆山腔”，发源于元末明初的苏州府昆山县，是中国戏曲的剧种之一，被誉为“百戏之祖”。"},{"id":2314,"type":"填空题","text":"诗歌起源于_____","options":[],"answer":["劳动"],"explanation":"诗歌起源于上古的社会生活，因劳动生产、两性相恋、原始宗教等而产生的一种有韵律、富有感情色彩的语言形式。"},{"id":2315,"type":"填空题","text":"被誉为“唐人楷书第一”的是____。","options":[],"answer":["欧阳询"],"explanation":"欧阳询唐朝著名书法家、书法理论家，与虞世南、褚遂良、薛稷并称初唐四大家。"},{"id":2316,"type":"填空题","text":"《广陵散》成为千古名曲，与“竹林七贤”之一的____有很大关系。","options":[],"answer":["嵇康"],"explanation":"据《晋书》记载，此曲乃嵇康游玩洛西时，为一古人所赠。"},{"id":2317,"type":"填空题","text":"魏晋时期的著名道士葛洪撰写的道教名著是____。","options":[],"answer":["抱朴子"],"explanation":"葛洪，字稚川，东晋时学者、文学家，《抱朴子》是其代表作，该书总结了战国时代以来神仙家的理论，确立了道教神仙理论体系；又继承魏伯阳炼丹理论，集魏晋炼丹术之大成，也是研究我国晋代宝贵以前道教史及思想史的宝贵陶瓷材料。"},{"id":2318,"type":"填空题","text":"天干地支纪年始于汉代，这种纪年是以_____为起点","options":[],"answer":["立春"],"explanation":"干支纪年是以立春作为一年的开始。农历最根本包含两部分,即农历历月和节气,其它的部分是由这两部分派生出来的,是为农业服务的。所以是以立春作为一年的起点。"},{"id":2319,"type":"填空题","text":"毕升发明的活字印刷实际上使用的是____。","options":[],"answer":["泥活字"],"explanation":"胶泥制成的用于排版印刷的反文单字。据中国北宋科学家沈括所著《梦溪笔谈》卷十八“技艺”载，泥活字为庆历年间平民毕升所发明。方法是用胶泥刻字，每字一印，经火烧硬而成泥活字，并用它们在两块铁板上交替排版和印刷。毕升发明的泥活字印书成功，标志着活字印刷术的诞生，比德国J.谷登堡活字印书早约400年。"},{"id":2320,"type":"填空题","text":"我国古代将科举殿试的第三名称为____。","options":[],"answer":["探花"],"explanation":"探花是中国古代科举考试中对位列第三的进士的称谓，与第一名状元、第二名榜眼合称“三鼎甲”。"},{"id":2321,"type":"填空题","text":"都江堰位于四川省，是____时期在李冰父子的主持下兴建的。","options":[],"answer":["战国"],"explanation":"都江堰始建于战国时期，是蜀郡太守李冰父子在前人鳖灵开凿的基础上组织修建的大型水利工程。"},{"id":2322,"type":"填空题","text":"颐和园是乾隆皇帝为其母孝圣宪皇太后祝寿而建，其前身是____。","options":[],"answer":["清漪园"],"explanation":"颐和园，中国清朝时期皇家园林，前身为清漪园，坐落在北京西郊，距城区十五公里，占地约二百九十公顷，与圆明园毗邻。"},{"id":2323,"type":"填空题","text":"“天下第一泉”共有四处，分别是庐山谷帘泉、____、济南趵突泉、镇江中泠泉。","options":[],"answer":["北京玉泉"],"explanation":"分别是北京玉泉山玉泉、山东济南趵突泉、镇江扬子江中冷泉和庐山康王谷谷帘泉。"},{"id":2324,"type":"填空题","text":"中国历史上的太平盛世出现的时期有____时期、汉文帝时期、唐玄宗前期。","options":[],"answer":["隋文帝"],"explanation":"开皇之治是隋文帝杨坚在位期间开创的盛世。隋文帝自灭陈统一天下，专心励精图治、锐意改革，最终出现了国家富庶、社会繁荣、突厥臣服、天下安定，读书人感觉生逢其时，老百姓各安其业的盛世局面。开皇盛世的大隋帝国疆域辽阔，气象恢弘磅礴。"},{"id":2325,"type":"填空题","text":"史学界认为的东周时期春秋与战国的分界点是____。","options":[],"answer":["三家分晋"],"explanation":"三家分晋是指春秋末年，晋国被韩、赵、魏三家瓜分的事件。“三家分晋”成为了中国春秋时代和战国时代的分界点。三家分晋标志着新兴地主阶级登上历史舞台，推动了封建制度的确立，揭开了七雄兼并的战国序幕。"},{"id":2326,"type":"填空题","text":"中国历史上的第一个王朝的建立者是____。","options":[],"answer":["大禹"],"explanation":"公元前2070年，禹建立了夏朝，这是我国历史上第一个王朝。"},{"id":2327,"type":"填空题","text":"考古发现，____已经大量使用石器并且懂得人工取火和管理火。","options":[],"answer":["北京人"],"explanation":"北京人遗址是世界上出土古人类遗骨和遗迹最丰富的遗址。先后发现五个比较完整的北京人头盖骨化石和一些其他部位的化石，还有大量的石器和石片，共十万件以上。距今约七十万年至二十万年，发现于北京周口店，保留了猿的某些特征，使用打制石器，已会使用天然火，过着群居的生活。"},{"id":2328,"type":"填空题","text":"著名的半坡遗址是____文化的代表。","options":[],"answer":["仰韶"],"explanation":"半坡遗址是新石器时代仰韶文化聚落遗址，年代为中国原始社会母系氏族繁荣时期遗留下的村落遗址，已有6000-6700多年历史。"},{"id":2329,"type":"填空题","text":"汉代主要的选才制度是____。","options":[],"answer":["察举制"],"explanation":"科举制从隋朝（一说唐朝）开始实行，直至清光绪卅一年（1905年），前后经历一千三百余年；九品中正制又称九品官人法，是魏晋南北朝时期的官吏选拔制度；察举制的确立时间是汉武帝元光元年（公元前134年）。"},{"id":2330,"type":"填空题","text":"郑樵的《通志》属于____。","options":[],"answer":["典章制度"],"explanation":"《通志》由南宋郑樵撰写，中国传统史学将其归入典章制度的政书，列为三通之一。"},{"id":2331,"type":"填空题","text":"司马迁《史记》中的本纪主要用于记述____。","options":[],"answer":["帝王事迹"],"explanation":"“本纪”是全书提纲，以王朝的更替为体，按年月时间记述帝王的言行政绩；其中记载先秦历史的五篇，依次是五帝，夏，殷，周，秦；记载秦汉历史的七篇，依次是秦始皇，楚霸王项羽，汉高祖刘邦，高后吕雉，汉文帝刘恒，汉景帝刘启和汉武帝刘彻。"},{"id":2332,"type":"填空题","text":"编年体史书起源于____。","options":[],"answer":["春秋"],"explanation":"中国编年体史书起源于春秋，它以时间为中心，按年、月、日顺序记述史事，目前数量极多，其中最出名的是《春秋》、《左传》、《竹书纪年》、《资治通鉴》，它们也被称为中国四大编年体史书。"},{"id":2333,"type":"填空题","text":"由汉武帝派遣出使西域的第一个使者是____。","options":[],"answer":["张骞"],"explanation":"张骞富有开拓和冒险精神，建元二年(前139年)，奉汉武帝之命，由甘父做向导，率领一百多人出使西域，打通了汉朝通往西域的南北道路，即赫赫有名的丝绸之路，汉武帝以军功封其为博望侯。"},{"id":2334,"type":"填空题","text":"迄今发现的铭文最多的古代青铜器是____。","options":[],"answer":["毛公鼎"],"explanation":"毛公鼎为西周晚期的重器，鼎内壁铸有铭文，32行，近500字，是现存青铜器铭文中最长的一篇，堪称西周青铜器中铭文之最。其内容叙事完整，记载详实，被誉为“抵得一篇《尚书》”，是研究西周晚年政治史的重要史料。"},{"id":2335,"type":"填空题","text":"云纹高足玉杯是一件珍贵文物，它出土于____。","options":[],"answer":["阿房宫遗址"],"explanation":"云纹高足玉杯1976年出土于西安车张村阿房宫遗址，青色玉，杯身呈直口筒状，近底部急收，小平底。"},{"id":2336,"type":"填空题","text":"被誉为“中华第一玉龙”的玉猪龙，是____时期的玉器。","options":[],"answer":["红山文化"],"explanation":"玉猪龙是红山文化时期中的代表玉器,又被称为玉兽玦,被专家们认为是龙最早的雏形。"},{"id":2337,"type":"填空题","text":"古代被称为“国瓷”的著名瓷器品种是____。","options":[],"answer":["青花瓷"],"explanation":"青花瓷，属于釉下彩瓷，是我国的国瓷。白地蓝花，素雅洁净，是景德镇的名品佳作。"},{"id":2338,"type":"填空题","text":"提出“宇宙便是吾心，吾心便是宇宙”哲学家是____。","options":[],"answer":["陆九渊"],"explanation":"陆九渊是宋代著名的理学家、主观唯心主义哲学家。他主张“吾心即是宇宙”，又倡“心即理”说。"},{"id":2339,"type":"填空题","text":"在形式逻辑领域提出“名辞说”理论的是____。","options":[],"answer":["墨家"],"explanation":"墨家在形式逻辑方面提出了以“名、辞、说”为思维的三种基本形式。"},{"id":2340,"type":"填空题","text":"《庄子》名篇《逍遥游》中写：“北冥有鱼，其名为鲲。鲲之大，不知其几千里也。”这种名叫鲲的大鱼可以变化成鸟，请问鸟的名字是____。","options":[],"answer":["鹏"],"explanation":"北冥有鱼，其名为鲲。鲲之大，不知其几千里也。化而为鸟，其名为鹏。鹏之背，不知其几千里也，怒而飞，其翼若垂天之云。"},{"id":2341,"type":"填空题","text":"以法制为中心，综合运用“法势术”是法家成熟的表现，而提出这一理论的是____。","options":[],"answer":["韩非子"],"explanation":"“法势术”这一理论是由秦国的韩非子提出的。在韩非之前已有申不害、商鞅、慎到等法家人物对法家学说做了许多论述，商鞅主要讲“法”，申不害主要讲“术”，慎到主要讲“势”。"},{"id":2342,"type":"填空题","text":"开创理学先河的是人物是孙复、石介和____。","options":[],"answer":["胡瑗"],"explanation":"北宋初期的胡瑗、孙复、石介是理学的先驱人物，他们以讲学授徒的方式，为理学培育了人才。"},{"id":2343,"type":"填空题","text":"首次在中国哲学史上明确提出“知行合一”的是____。","options":[],"answer":["王阳明"],"explanation":"知行合一，致良知，是阳明文化的核心。明武宗正德四年（1509），心学集大成者王守仁在贵阳文明书院讲学，首次提出知行合一说。"},{"id":2344,"type":"填空题","text":"“水则载舟，水则载舟”是我国古代思想史上____提出的著名论点。","options":[],"answer":["荀子"],"explanation":"“水则载舟,水则覆舟”出自《荀子・王制》。荀子,战国末期赵国人,著名思想家、文学家、政治家,荀子对儒家思想有所发展,在人性问题上,提倡性恶论,否认天赋的道德观念,强调后天环境和教育对人的影响。"},{"id":2345,"type":"填空题","text":"“天人合一”的说法是宋代哲学家____明确提出的。","options":[],"answer":["张载"],"explanation":"真正明确提出“天人合一”的是北宋哲学家张载。张载在天、人关系的研究上独树一帜，承前启后，以《孟子》《中庸》《大学》等经典之“性”“诚”“明”的理念贯通天人。"},{"id":2346,"type":"填空题","text":"汉代的董仲舒将天道和人事相比附，提出了____说，成为古代封建统治的理论基础之一。","options":[],"answer":["天人感应"],"explanation":"公元前134年，武帝下诏征求治国方略，董仲舒在著名的《举贤良对策》中将儒家思想结合社会需要，并融合各家思想，系统地提出了“天人感应”、“大一统”学说和“罢黜百家，独尊儒术”的主张，被武帝所采纳，使儒学成为中国社会正统思想。公元前104年病故，死后得武帝眷顾，被赐葬于长安下马陵。"},{"id":2347,"type":"填空题","text":"儒家提倡的“内圣外王”之道有其循序渐进的途径，依次是修身、齐家、治国、____。","options":[],"answer":["平天下"],"explanation":"《礼记·大学》：“古之欲明明德于天下者，先治其国；欲治其国者，先齐其家；欲齐其家者，先修其身；欲修其身者，先正其心；欲正其心者，先诚其意；欲诚其意者，先致其知，致知在格物。物格而后知至，知至而后意诚，意诚而后心正，心正而后身修，身修而后家齐，家齐而后国治，国治而后天下平。”"},{"id":2348,"type":"填空题","text":"属于道教的三天尊的是玉清原始天尊、上清灵宝君和太清____。","options":[],"answer":["道德天尊"],"explanation":"三清天尊是道教对其所崇奉的三位最高天神的合称。指居于三清仙境的三位尊神，即玉清境清微天元始天尊、上清境禹馀天灵宝天尊、太清境大赤天道德天尊。其中所谓玉清境、上清境、太清境是所居仙境的区别，清微天、禹余天、大赤天是所统天界的划分，而天尊的意思则是说，极道之尊，至尊至极，故名天尊。"},{"id":2349,"type":"填空题","text":"佛教四大菩萨是____、观音菩萨、普贤菩萨、地藏菩萨。","options":[],"answer":["文殊菩萨"],"explanation":"佛教中四大菩萨，指的是文殊菩萨、观音菩萨、普贤菩萨、地藏菩萨四位法力高深的菩萨。"},{"id":2350,"type":"填空题","text":"“太守与客来饮于此，饮少辄醉，而年又最高，故自号曰醉翁也”中的“太守”是____。","options":[],"answer":["欧阳修"],"explanation":"《醉翁亭记》最后一句：“太守谓谁？庐陵欧阳修也。”"},{"id":2351,"type":"填空题","text":"宣纸是中国独特的手工艺品，享有“千年寿纸”的美誉。它名字的来历与什么有关____。","options":[],"answer":["产地"],"explanation":"宣纸得名于其产地——安徽宣城。"},{"id":2352,"type":"填空题","text":"顾恺之创作的是____。","options":[],"answer":["洛神赋图"],"explanation":"《洛神赋图》是东晋顾恺之的画作，原《洛神赋图》卷为设色绢本。是由多个故事情节组成的类似连环画而又融会贯通的长卷。"},{"id":2353,"type":"填空题","text":"阎立本创作的是____。","options":[],"answer":["历代帝王图"],"explanation":"《历代帝王图》又名《列帝图》、《十三帝图》、《古列帝图卷》、《古帝王图》，传为唐代阎立本画作，绢本，设色，现存后人摹本。"},{"id":2354,"type":"填空题","text":"展子虔创作的是____。","options":[],"answer":["游春图"],"explanation":"《游春图》是隋朝画家展子虔创作的绘画作品，绢本、青绿设色，画上有宋徽宗题写的“展子虔游春图”六个字，现存北京故宫博物院绘画馆。、"},{"id":2355,"type":"填空题","text":"绘画“四品”指的是____、妙品 、能品 、逸品。","options":[],"answer":["神品"],"explanation":"四品是指唐朝朱景玄所著，是中国现存就早的绘画史，即：神、妙、能、逸。"},{"id":2356,"type":"填空题","text":"书法史上“楷书四大家”指的是欧阳询、____、柳公权、赵孟頫。","options":[],"answer":["颜真卿"],"explanation":"楷书四大家是对书法史上以楷书著称的四位书法家的合称,也称四大楷书。他们分别指：唐朝欧阳询(欧体)、唐朝颜真卿(颜体)、唐朝柳公权(柳体)、元代赵孟頫(赵体)。"},{"id":2357,"type":"填空题","text":"《闰中秋月诗帖》的笔法属于____。","options":[],"answer":["瘦金体"],"explanation":"《闰中秋月诗帖》是赵佶创作的一幅书法作品，现收藏于北京故宫博物院。《闰中秋月诗帖》为“瘦金体”的典型作品之一，“瘦金”即有“瘦筋”的含意。"},{"id":2358,"type":"填空题","text":"现存面积最大的地面城池是____。","options":[],"answer":["西安城"],"explanation":"古代的城市称作城池，“城”指城墙，“池”指城外环绕城墙的河池，俗称“护城河”。西安城是我国现存面积最大、保存最完整的古城。"},{"id":2359,"type":"填空题","text":"最早修建长城的是春秋时的____国。","options":[],"answer":["楚"],"explanation":"最早修建长城是春秋时期的楚国，《左传》上所说楚国“汉水以为池，方城以为城”的方城，即指此。"},{"id":2360,"type":"填空题","text":"佛教的创始人是乔达摩·____。","options":[],"answer":["悉达多"],"explanation":"乔达摩·悉达多是古印度著名思想家，古印度迦毗罗卫国释迦族人，佛教的创始者，被后世尊称为释迦牟尼佛。"},{"id":2361,"type":"填空题","text":"中国三大古建筑群的是____、曲阜孔庙、承德避暑山庄。","options":[],"answer":["北京故宫"],"explanation":"中国三大古建筑群，即北京故宫、曲阜孔庙和承德避暑山庄，中国三大古建筑群均已列入世界文化遗产名录。"},{"id":2362,"type":"填空题","text":"《论语》中认为“为仁之本”的是_____","options":[],"answer":["孝悌"],"explanation":"《论语》中认为“为仁之本”是孝悌，孝悌是仁的一部分，也是仁的根本。孝是指报答父母的养育之恩，悌指的是兄弟姐妹之间的友爱。孔子非常重视孝悌，他认为孝悌是做人、做学问的根本。"},{"id":2363,"type":"填空题","text":"古代茶圣是____。","options":[],"answer":["陆羽"],"explanation":"陆羽（733—804），字鸿渐，复州竟陵（今湖北天门）人，一名疾，字季疵，号竟陵子、桑苎翁、东冈子，又号“茶山御史”。是唐代著名的茶学家，被誉为“茶仙”，尊为“茶圣”，祀为“茶神”。"},{"id":2364,"type":"填空题","text":"李清照号____。","options":[],"answer":["易安居士"],"explanation":"李清照，南宋女词人。号易安居士，今山东济南人。长于诗、文、词,兼书法、绘画,且通音律。"},{"id":2365,"type":"填空题","text":"著名的候风地动仪的研制者是____。","options":[],"answer":["张衡"],"explanation":"候风地动仪的发明者东汉大科学家张衡。早在公元132年，中国就发明了地球的探测器——地动仪。它是中国古代科文并茂的巨星——张衡创制发明的，也是世界上最早的一台会测报地震方向的科学仪器，它首开人类科学测报地震的先河。"},{"id":2366,"type":"填空题","text":"李白号____。","options":[],"answer":["青莲居士"],"explanation":"李白（701年—762年） ，字太白，号青莲居士，又号“谪仙人”。"},{"id":2367,"type":"填空题","text":"国子监的最高官员称为____。","options":[],"answer":["祭酒"],"explanation":"国子监以师为官，最高职位是祭酒，一般的教学和管理人员也是朝廷命官，由吏部统一管理任免。国子监的学生称为监生，监生又分官生和民生。"},{"id":2368,"type":"填空题","text":"最早记录指南针存在偏差的是____。","options":[],"answer":["梦溪笔谈"],"explanation":"沈括是世界上第一个指出指南针不完全指南北的人，记载于《梦溪笔谈》中。"},{"id":2369,"type":"填空题","text":"____被誉为“天下名茶之冠”。","options":[],"answer":["西湖龙井"],"explanation":"杭州西湖龙井，被誉为“天下名茶之冠”，产于湘江省杭州市西湖周围的群山之中。"},{"id":2370,"type":"填空题","text":"唐太宗李世民登基前曾发动“玄武门事变”，按照古代五行说，大兴宫的“玄武门”一定位于该宫的____。","options":[],"answer":["北方"],"explanation":"玄武门之变，是唐高祖武德九年六月初四（公元626年7月2日），是由当时唐高祖李渊次子秦王李世民在唐王朝的首都长安城（今陕西省西安）太极宫的北宫门--玄武门附近发动的一次政变。"},{"id":2371,"type":"填空题","text":"在中国的饮茶史上，____皇帝是著名的泉水评定专家，被誉为“茶帝”。","options":[],"answer":["乾隆"],"explanation":"乾隆皇帝爱新觉罗弘历（1711——1799）在世89年,是我国历史上在位时间最长,寿命最长的皇帝,也是最爱茶的皇帝。"},{"id":2372,"type":"填空题","text":"“真龙天子”最早指的是____皇帝。","options":[],"answer":["刘邦"],"explanation":"《史记》记载，旧时一妇人在河边行走时，不知何故突然昏厥过去，他丈夫见她久久不回，于是到河边寻找，见有一条龙盘于那妇人身上，过不久这妇人便有孕上身，不久便产下一婴，这便是汉高祖刘邦。因此刘邦是历史上第一个被称为真龙天子的皇帝。"},{"id":2373,"type":"填空题","text":"中国的三大传统节日是____、中秋节、端午节。","options":[],"answer":["春节"],"explanation":"中国的三大传统节日是春节、端午节、中秋节。"},{"id":2374,"type":"填空题","text":"人殉制度是中国历史上最残忍的制度，他终止于____时期。","options":[],"answer":["明英宗"],"explanation":"明英宗朱祁镇即位后，对人殉制度非常厌恶，明确提出废止人殉，曾下旨说“藩王薨，妃、夫人以下不必从死，年少有父母者遣归”。"},{"id":2375,"type":"填空题","text":"二胡名曲《二泉映月》中的“二泉”指的是天下第二泉，它位于____。","options":[],"answer":["无锡"],"explanation":"二泉映月中的二泉，是江苏无锡市的西郊惠山九龙十三泉，中声名最大的“天下第二泉”，人们也称它为二泉。"},{"id":2376,"type":"填空题","text":"盖碗茶是____族所喜爱的特色饮茶方式。","options":[],"answer":["回"],"explanation":"盖碗茶是西北回族的一种独特的饮茶方式，相传始于唐代，相传至今，颇受回族人民喜爱。"},{"id":2377,"type":"填空题","text":"“登黄山天下无山，观止矣！”是____在游历黄山后写下的。","options":[],"answer":["徐霞客"],"explanation":"徐霞客(1586-1641)，名弘祖，字振之，号霞客，明朝南直隶江阴(今江苏江阴市)人。明地理学家、旅行家和文学家，地理名著《徐霞客游记》的作者，被称为\"千古奇人\"。徐霞客一生志在四方，足迹遍及今21个省、市、自治区 。\"达人所之未达，探人所之未知\" ，所到之处，探幽寻秘，并记有游记，记录观察到的各种现象、人文、地理、动植物等状况。他经30年考察撰成的60万字《徐霞客游记》，开辟了地理学上系统观察自然、描述自然的新方向，既是系统考察祖国地貌地质的地理名著，又是描绘华夏风景资源的旅游巨篇，还是文字优美的文学佳作，在国内外具有深远的影响。《徐霞客游记》开篇之日(5月19日)被定为中国旅游日。"},{"id":2378,"type":"填空题","text":"我国古代铜活字印书史上造字时间最长、耗费资金最大、刻字数量最多的人物是____。","options":[],"answer":["林春祺"],"explanation":"在我国古代印刷史上，林春祺造铜活字印书，造字时间最长，耗费资金最大，刻字数量最多。"},{"id":2379,"type":"填空题","text":"王维的诗句“朝为越溪女，暮作吴宫妃。”说的是我国古代的著名美女____。","options":[],"answer":["西施"],"explanation":"《西施咏》：“艳色天下重，西施宁久微。朝为越溪女，暮作吴宫妃。贱日岂殊众，贵来方悟稀。邀人傅脂粉，不自著罗衣。君宠益娇态，君怜无是非。当时浣纱伴，莫得同车归。持谢邻家子，效颦安可希。”《西施咏》是唐代诗人王维创作的一首诗。此诗借西施从平民到宫廷宠妃的历史典故，揭示人生浮沉全凭际遇的炎凉世态，并表达对小人的嘲讽，揭露当时社会上潜藏的危机，抒发诗人怀才不遇的不平与感慨。"},{"id":2380,"type":"填空题","text":"“香山居士”是我国唐代诗人____的别称。","options":[],"answer":["白居易"],"explanation":"白居易（772年2月28日－846年9月8日），字乐天，号香山居士，又号醉吟先生，生于河南新郑，祖籍山西太原。他是唐代著名现实主义诗人，有“诗魔”和“诗王”之称，与元稹共同倡导新乐府运动，世称“元白”，又与刘禹锡并称“刘白”。"},{"id":2381,"type":"填空题","text":"“苦心人，无不负，卧薪尝胆，三千越申可吞吴。”描写的是____。","options":[],"answer":["勾践"],"explanation":"出自蒲松龄“落第自勉联”：有志者，事竟成，破釜沉舟，百二秦关终属楚；苦心人，天不负，卧薪尝胆，三千越甲可吞吴。越王勾践（约前520年―前465年），姒姓，名勾践，又名鸠浅、菼执，夏禹后裔，越王允常之子，春秋末年越国国君。前496年即位，曾败于吴国，被迫求和。返国后重用范蠡、文种，卧薪尝胆使越国国力渐渐恢复起来。前482年，吴王夫差兴兵参加黄池之会，以彰显武力率精锐而出。越王勾践抓住机会率兵而起，大败吴师。夫差仓卒与晋国定盟而返，与勾践连战惨败。不得已与越议和。前473年夫差被迫自尽，灭吴国称霸，是春秋时期最后一位霸主。"},{"id":2382,"type":"填空题","text":"我国广州市的别称是____。","options":[],"answer":["羊城"],"explanation":"羊城是广州别称，广东省省会，位于广东省中南部，东江、西江、北江交汇处，珠江三角洲北缘，濒临中国南海。"},{"id":2383,"type":"填空题","text":"五谷中的“黍”是指____。","options":[],"answer":["黄米"],"explanation":"黄米又称黍、糜子、黄米、夏小米、黄小米，有糯质和非糯质之别，糯质黍多作以醇酒，非糯质黍，称为穄，以食用为主。"},{"id":2384,"type":"填空题","text":"田园诗派的开创者是____。","options":[],"answer":["陶渊明"],"explanation":"陶渊明，字元亮，又名潜，世称靖节先生，私谥靖节，世称靖节先生，浔阳柴桑（今江西九江）人，东晋著名诗人、辞赋家、散文家，被誉为“隐逸诗人之宗”“田园诗派之鼻祖”，江西首位文学巨匠。"},{"id":2385,"type":"填空题","text":"我国的第一部长篇历史小说是____。","options":[],"answer":["三国演义"],"explanation":"《三国演义》（全名为《三国志通俗演义》，又称《三国志传》）是中国古典四大名著之一，亦是中国第一部长篇历史章回小说，作者是元末明初的罗贯中。"},{"id":2386,"type":"填空题","text":"清朝文学家蒲松龄号“柳泉居士”，世称____。","options":[],"answer":["聊斋先生"],"explanation":"蒲松龄（1640年6月5日-1715年2月25日），字留仙，一字剑臣，别号柳泉居士，世称聊斋先生，自称异史氏。"},{"id":2387,"type":"填空题","text":"《水调歌头·明月几时有》一词的小序中提到的“子由”是苏轼的____。","options":[],"answer":["弟弟"],"explanation":"子由是苏轼弟弟苏辙的字。"},{"id":2388,"type":"填空题","text":"诗句“故人西辞黄鹤楼，烟花三月下扬州”中的“故人”指的是____。","options":[],"answer":["孟浩然"],"explanation":"故人：老朋友,这里指孟浩然。出自：唐·李白《黄鹤楼送孟浩然之广陵》。 原文：故人西辞黄鹤楼，烟花三月下扬州。孤帆远影碧空尽，唯见长江天际流。"},{"id":2389,"type":"填空题","text":"《与妻书》的作者是黄花岗起义七十二烈士之一的____，这封家书表现了他作为一个革命者以天下为己任，追求正义与真理，舍“小爱”取“大爱”的高尚情操和宽广胸怀，令人肃然起敬。","options":[],"answer":["林觉民"],"explanation":"林觉民（1887—1911），字洞意，黄花岗七十二烈士之一。《与妻书》是他参加孙中山领导的广州起义前写给妻子的绝笔书。"},{"id":2390,"type":"填空题","text":"____在古时是指结婚时把夫妻头发束在一起。","options":[],"answer":["结发"],"explanation":"结发是古时候的婚姻习俗，当夫妻成婚时，各取头上一根头发，合而作一结，男女双方结为夫妻。这就是古诗中所说的：“结发为夫妻，恩爱两不疑”。"},{"id":2391,"type":"填空题","text":"____是关于农业生产和农事活动的著作。","options":[],"answer":["齐民要术"],"explanation":"《齐民要术》大约成书于北魏末年(公元533年-544年)，是北朝北魏时期，南朝宋至梁时期，中国杰出农学家贾思勰所著的一部综合性农学著作，也是世界农学史上专著之一，是中国现存最早的一部完整的农书。"},{"id":2392,"type":"填空题","text":"“夕阳无限好，只是近黄昏。”是____的诗句。","options":[],"answer":["李商隐"],"explanation":"“夕阳无限好，只是近黄昏”是出自唐代李商隐的即景抒情的诗《登乐游原》中一句，意思是虽然夕阳无限美好，可惜的是已接近黄昏时刻，美好转瞬而逝。"},{"id":2393,"type":"填空题","text":"先秦两汉时期成就最高，影响最大，通过人物描写来反映历史面貌的是____。","options":[],"answer":["史记"],"explanation":"“通过人物描写反映历史面貌”，可知此书是纪传体，因为纪传体是通过记叙人物活动反映历史事件的史书体例。《史记》为西汉司马迁所作，是中国第一部纪传体通史，以人物传记为中心来反映历史内容，记载了从黄帝以来至汉武帝时期的历史，被列为“二十四史之首”。"},{"id":2394,"type":"填空题","text":"“态生两靥之愁，娇袭一身之病”是宝玉对黛玉的第一印象，其中“靥”是指____。","options":[],"answer":["酒窝"],"explanation":"“靥”是指酒窝儿，嘴两旁的小圆窝儿。"},{"id":2395,"type":"填空题","text":"被国内外人士誉为“中国三大国粹”的是“京剧、国画、____”。","options":[],"answer":["中医"],"explanation":"中国三大国粹分别为京剧、国画、中医。"},{"id":2396,"type":"填空题","text":"王羲之对一种动物十分偏爱，并从它的体态姿势上领悟到书法执笔运笔的理，这种动物是____。","options":[],"answer":["鹅"],"explanation":"王羲之爱鹅成癖，为见好鹅，不辞劳苦，更不惜墨宝。王羲之生性爱鹅，会稽有一位孤老太太养了只鹅，叫声很好听，想买而未能得到，于是就带着亲友去观看。老太太听说他要来，把鹅烹煮了用来招待他，王羲之难过了一整天。当时山阴有位道士，养了一群鹅，去观看，很高兴，多次恳求道士买他的鹅。道士说：“替我抄一遍《道德经》我就送你这群鹅。”王羲之欣然写完，把鹅装在笼子里回去了，一路上乐不可支。"},{"id":2397,"type":"填空题","text":"要成好人，____。引酵若酸，哪得甜酒。","options":[],"answer":["须寻好友"],"explanation":"出自吕德胜《小儿语》——要成好人，须寻好友。"},{"id":2398,"type":"填空题","text":"马可.波罗来中国的时候，中国处于____时期。","options":[],"answer":["元朝"],"explanation":"马可.波罗是世界著名的旅行家、商人，著有《马可.波罗游记》。他是第一个深入中国的西方人。元朝初年，马可.波罗来到中国。他的游记中记载了与忽必烈的相处。"},{"id":2399,"type":"填空题","text":"《红楼梦》中有“小宝钗\"，“小黛玉”之称的两人是袭人、____。","options":[],"answer":["晴雯"],"explanation":"小宝钗指的是袭人，他们俩都是封建思想的代表，实时劝谏宝玉读书封侯，与达官贵人结交。小黛玉指的是晴雯，第一是晴雯和黛玉关系本来就不错，又都是不喜欢宝玉读书考举人进士，厌恶世俗经济学问的人。"},{"id":2400,"type":"填空题","text":"曹植七步成诗，相传历史上还有一位三步就能成诗的人，他是____。","options":[],"answer":["寇准"],"explanation":"历史上能三步成诗的人是寇准。太平兴国五年(980年)，19岁的寇准考中进士甲科，授大理评事。"},{"id":2401,"type":"填空题","text":"“醉里挑灯看剑，梦回吹角连营”出自____的作品。","options":[],"answer":["辛弃疾"],"explanation":"“醉里挑灯看剑,梦回吹角连营”一句出自南宋爱国词人辛弃疾所写的一首名字为《破阵子》的词，题目为《为阵同甫赋壮词以寄》。"},{"id":2402,"type":"填空题","text":"“但愿人长久，千里共婵娟”，苏东坡借这首词表达了对____的思念之情。","options":[],"answer":["兄弟"],"explanation":"“但愿人长久，千里共婵娟。”苏东坡借这首词表达了对弟弟苏辙的思念之情。"},{"id":2403,"type":"填空题","text":"“春风得意”成为进士及第的代称与____有关。","options":[],"answer":["孟郊"],"explanation":"“春风得意”出自唐朝的孟郊写的七言绝句《登科后》，这里的春风既指大自然中的微风，又用来比喻皇恩。唐朝诗人孟郊曾多次进京赶考不中，终于在41岁的时候考中进士，因此写下《登科后》：“昔日龌龊不足夸，今朝放荡思无涯。春风得意马蹄疾，一日看尽长安花。”用以表达自己喜悦的心情。"},{"id":2404,"type":"填空题","text":"五湖指的是洞庭湖、鄱阳湖、太湖、巢湖、____。","options":[],"answer":["洪泽湖"],"explanation":"五湖指洞庭湖、鄱阳湖、太湖、巢湖和洪泽湖。"},{"id":2405,"type":"填空题","text":"元杂剧中的女主唱称为____。","options":[],"answer":["旦本"],"explanation":"旦本戏是戏剧用语，指元杂剧由女主角演唱的杂剧为旦本戏。"},{"id":2406,"type":"填空题","text":"“匪女之为美，美人之贻”中的“贻”的意思是____。","options":[],"answer":["赠送"],"explanation":"贻的意思是指： 赠给。解释：不是你的美好(让我动心)，(而是因为)美人送给我的(我才珍惜)。"},{"id":2407,"type":"填空题","text":"“彼采萧兮，一日不见，如三秋兮”中“三秋”的意思是____。","options":[],"answer":["三季"],"explanation":"《采葛》写主人公对友人的思念。这两句是用比喻方法构成的夸张句。三秋是指三个季度。"},{"id":2408,"type":"填空题","text":"旧时我国的老百姓称____为“仓神”。","options":[],"answer":["老鼠"],"explanation":"旧时我国民间曾将正月二十五日定为“填仓节”。人们管老鼠叫“仓神”。到“填仓节”这天，家家仓囤装满粮食，并虔诚祭祀，祈求“老鼠仓神”口下留情，少来偷吃，并祷祝年年五谷丰登，粮油满仓。"},{"id":2409,"type":"填空题","text":"与伯牙、钟子期“高山流水觅知音”故事相关的乐器是____。","options":[],"answer":["古琴"],"explanation":"两位“知音”的友谊感动了后人，人们在他们相遇的地方，筑起了一座古琴台。直至今天，人们还常用“知音”来形容朋友之间的情谊。两人千古传诵的诗篇:摔碎瑶琴凤尾寒，子期不在对谁弹！春风满面皆朋友，欲觅知音难上难。高山流水觅知音！"},{"id":2410,"type":"填空题","text":"“名不正言不顺”表达了中国的____思想。","options":[],"answer":["儒家"],"explanation":"“名不正言不顺”是儒家的思想。出处：《论语·子路》：“名不正则言不顺，言不顺则事不成。”"},{"id":2411,"type":"填空题","text":"山东曲阜有“三孔”，分别是“孔府”、“ 孔林 ”和____。","options":[],"answer":["孔庙"],"explanation":"曲阜三孔由孔庙、孔府和孔林构成，位于山东省曲阜市，是中国唯一且规模最大的集祭祀孔子的寺庙、孔子嫡系后裔的府邸和孔子及其子孙墓地于一体的建筑群。"},{"id":2412,"type":"填空题","text":"我国第一部中医学典籍是____。","options":[],"answer":["黄帝内经"],"explanation":"《黄帝内经》是一本综合性的医书，也是中国最早的医学典籍，对后世中医学理论的奠定有深远的影响。"},{"id":2413,"type":"填空题","text":"被称为“中国17世纪工艺百科全书”的《天工开物》是____创作的。","options":[],"answer":["宋应星"],"explanation":"宋应星是明朝著名科学家。宋应星的著作和研究领域涉及自然科学及人文科学的不同学科，而其中最杰出的作品《天工开物》被誉为“中国17世纪的工艺百科全书”。"},{"id":2414,"type":"填空题","text":"“霓裳羽衣”是我国____代的宫廷乐舞。","options":[],"answer":["唐"],"explanation":"霓裳羽衣舞，是一种唐代的宫廷乐舞，唐玄宗作曲。"},{"id":2415,"type":"填空题","text":"中国古代的“乐府双璧”是指____和孔雀东南飞。","options":[],"answer":["木兰诗"],"explanation":"“乐府双璧”即《木兰诗》和《孔雀东南飞》的喻称。《木兰诗》又名《木兰辞》，是北朝民歌；《孔雀东南飞》又名《古诗为焦仲卿妻作》，是古乐府民歌的代表作之一，也是保存下来的最早的一首长篇叙事诗。"},{"id":2416,"type":"填空题","text":"“字字看来皆是血，十年辛苦不寻常”描述的是名著____的成书过程。","options":[],"answer":["红楼梦"],"explanation":"《红楼梦》，又名《石头记》《金玉缘》，是清代作家曹雪芹创作的章回体长篇小说，被誉为中国古典四大名著之首。“字字看来皆是血，十年辛苦不寻常。”是《红楼梦》甲戌本第一回之前《凡例》的末尾。《凡例》的末段内容与其他诸本第一回第一段基本相同，是对全书的总评。"},{"id":2417,"type":"填空题","text":"“退避三舍”指的是军队____。","options":[],"answer":["后退九十里"],"explanation":"该成语最早出自于春秋·左丘明《左传·僖公二十三年》。退避三舍（舍，古时行军以三十里为一舍）原意指为了回避与对方的冲突，主动退让九十里；常用于比喻退让和回避，避免冲突。"},{"id":2418,"type":"填空题","text":"严复所说的“孔门四科”具体指德行、政事、文学和____。","options":[],"answer":["言语"],"explanation":"后世学者将德行、政事、文学、言语，视为“孔门四科”。"},{"id":2419,"type":"填空题","text":"中华文化源远流长，我国四大文化遗产分别为《明清档案》、《殷墟甲骨》、《居延汉简》、____。","options":[],"answer":["敦煌经卷"],"explanation":"四大文化遗产是指四本记录了中国历史的书籍，分别是《明清档案》、《殷墟甲骨》、《居延汉简》和《敦煌经卷》。"},{"id":2420,"type":"填空题","text":"明代有两大戏曲流派：以汤显祖为代表的____（重意趣）和以沈璟为代表的吴江派（重格律）。","options":[],"answer":["临川派"],"explanation":"临川派是明代传奇文学的一种流派。万历年间﹐临川汤显祖创作《牡丹亭》等传奇﹐着重刻划人物﹐讲究词藻﹐影响颇大。"},{"id":2421,"type":"填空题","text":"“不愤不启，不悱不发”中的____是想弄明白而弄不明白的意思。","options":[],"answer":["愤"],"explanation":"愤：心里想弄明白可还是不明白。"},{"id":2422,"type":"填空题","text":"沈括的《梦溪笔谈》、王应麟的《困学纪闻》，以及洪迈的____是宋代三大笔记。","options":[],"answer":["容斋随笔"],"explanation":"王应麟的《困学纪闻》，与沈括的《梦溪笔谈》、洪迈的《容斋随笔》，并称宋代三大笔记。"},{"id":2423,"type":"填空题","text":"对乐府诗的分类，以郭茂倩的____最为完备。","options":[],"answer":["乐府诗集"],"explanation":"《乐府诗集》是北宋文学家郭茂倩编撰的上古至唐、五代的乐府诗歌总集，成书于北宋时期。每一类有总序，每一曲有题解，对乐曲的起源、性质、演唱配器等均有详尽说明。其中还保存了不少已失传著作的内容。"},{"id":2424,"type":"填空题","text":"《汉书》的志尤为人们所重视。其中由《史记·平准书》演变而来的志被命名为____。","options":[],"answer":["食货志"],"explanation":"《食货志》是由《史记》的《平准书》演变来的，但有很大发展，内容也更加丰富了。"},{"id":2425,"type":"填空题","text":"《汉书》创立了中国现存最早的图书目录《汉书·____》。","options":[],"answer":["艺文志"],"explanation":"《汉书·艺文志》是汉代时期改撰而成的文学作品，是中国现存最早的目录学文献。"},{"id":2426,"type":"填空题","text":"赵州桥是隋朝工匠____修建的。","options":[],"answer":["李春"],"explanation":"建于隋朝年间公元595年－605年，由著名匠师李春设计建造，距今已有1400多年的历史，是当今世界上现存第二早（还有一座小商桥）、保存最完整的古代单孔敞肩石拱桥。"},{"id":2427,"type":"填空题","text":"唐文宗大和七年，朝廷下令将九经，《论语》、《孝经》、《尔雅》十二部书刻在石碑上，开成二年刻成，又称____。","options":[],"answer":["开成石经"],"explanation":"开成石经，唐代的十二经刻石。又称唐石经。始刻于文宗太和七年(833)，开成二年(837)完成。原碑立于唐长安城务本坊的国子监内，宋时移至府学北墉，即今西安碑林。中国清代以前所刻石经很多，唯开成石经保存最为完好，是研究中国经书历史的重要资料。1961年国务院公布为全国重点文物保护单位。"},{"id":2428,"type":"填空题","text":"“蒹葭苍苍，白露为霜。所谓伊人，在水一方”中“蒹葭”是指____。","options":[],"answer":["芦苇"],"explanation":"蒹葭者，芦苇也，飘零之物，随风而荡，却止于其根，若飘若止，若有若无。思绪无限，恍惚飘摇，而牵挂于根。根者，情也。相思莫不如是。露之为物，瞬息消亡。"},{"id":2429,"type":"填空题","text":"常用作表示第五位顺序的字是____。","options":[],"answer":["戊"],"explanation":"戊，天干的第五位，用作顺序第五的代称。"},{"id":2430,"type":"填空题","text":"文字是人类文明的重要标志，我国最古老的文字是____。","options":[],"answer":["甲骨文"],"explanation":"中国迄今发现的最古老的比较成熟的文字是甲骨文，是刻在龟甲和兽骨上的文字。"},{"id":2431,"type":"填空题","text":"清代皇帝的夫人有不同的称呼指代有不同的等级，其中地位最低的是____。","options":[],"answer":["答应"],"explanation":"在清朝，将之分为八等级，分别为：皇后一人，皇贵妃一人，贵妃两人，妃四人，嫔六人，贵人不限人数，常在不限人数，答应不限人数。"},{"id":2432,"type":"填空题","text":"故宫的三大殿是指太和殿、中和殿、保和殿，三大殿是封建皇帝行使权力或者举行盛典时用的宫殿。如果新皇帝要举行登基大典，一般会在____举行。","options":[],"answer":["太和殿"],"explanation":"太和殿俗称金銮殿，明清两朝皇帝都在太和殿举行盛大典礼，如皇帝登基即位、皇帝大婚、册立皇后、命将出征等。"},{"id":2433,"type":"填空题","text":"《山海经》中“迷谷”指的是____。","options":[],"answer":["植物"],"explanation":"《山海经》中迷谷是一种植物。"},{"id":2434,"type":"填空题","text":"上古神话中的四大神兽中____在山海经中没有明确的记载。","options":[],"answer":["梼杌"],"explanation":"梼杌在《山海经》中没有明确的记载。"},{"id":2435,"type":"填空题","text":"“勿以恶小而为之，勿以善小而不为。”语出三国志，出自____。","options":[],"answer":["刘备"],"explanation":"“勿以恶小而为之，勿以善小而不为”，出自蜀汉昭烈帝刘备的诏书中。意思是不要因为是件较小的坏事就去做，不要因为是件较小的善事就毫不关心。"},{"id":2436,"type":"填空题","text":"我国古代诗人中流传下来的诗作数量第一的诗人是____。","options":[],"answer":["陆游"],"explanation":"我国古代诗人中流传下来的诗作数量第一的诗人是陆游。陆游具有多方面文学才能，尤以诗的成就为最，自言“六十年间万首诗”，存世有九千三百余首。"},{"id":2437,"type":"填空题","text":"凤凰涅槃出自____先生的同名作品《凤凰涅槃》。","options":[],"answer":["郭沫若"],"explanation":"凤凰涅槃一说出自于郭沫若先生同名作品，非中国古代传说，在中国古代神话传说中并无凤凰会浴火重生的说法。"},{"id":2438,"type":"填空题","text":"西王母住在____山。","options":[],"answer":["昆仑"],"explanation":"西王母住在昆仑山。"},{"id":2439,"type":"填空题","text":"中国第一神山是____。","options":[],"answer":["昆仑山"],"explanation":"中国第一神山是昆仑山。"},{"id":2440,"type":"填空题","text":"又西九十里，曰夸父之山。其北有林焉，名曰桃林”这里的“桃林”出自神话故事____。","options":[],"answer":["夸父逐日"],"explanation":"《夸父逐日》中有一句话“弃其杖，化为邓林。”这里的“邓林”就是桃林的意思。"},{"id":2441,"type":"填空题","text":"“其鸣自叫也，见则其邑有讹火。”中的“讹火”指的是____。","options":[],"answer":["磷火"],"explanation":"讹火意思是指怪火，也指磷火。"},{"id":2442,"type":"填空题","text":"与王建齐名，并称“张王乐府”的唐代诗人是____。","options":[],"answer":["张籍"],"explanation":"张籍（约766年- 约830年），字文昌，和州乌江（今安徽和县乌江镇）人，唐代诗人，世称“张水部”、“张司业”。张籍为韩门大弟子，其乐府诗与王建齐名，并称“张王乐府”。"},{"id":2443,"type":"填空题","text":"“刑天舞干戚”“女娲补天”“精卫填海”都是出自____。","options":[],"answer":["山海经"],"explanation":"它们都出自《山海经》。"},{"id":2444,"type":"填空题","text":"根据《史记》当中的记载，秦始皇姓____。","options":[],"answer":["赵"],"explanation":"庄襄王为秦质子于赵，见吕不韦姬，悦而取之，生始皇。以秦昭王四十八年正月生于邯郸。及生，名为政，姓赵氏。"},{"id":2445,"type":"填空题","text":"战国时期著名变法家商鞅姓____。","options":[],"answer":["姬"],"explanation":"商鞅（约公元前390年－公元前338年），姬姓，公孙氏，名鞅，卫国人。"},{"id":2446,"type":"填空题","text":"____是六国中最后灭亡的。","options":[],"answer":["齐国"],"explanation":"从公元前230年攻打韩国到前221年灭齐国结束，共计10年的时间，先后按顺序消灭韩、赵、魏、楚、燕、齐六国，结束了中国自春秋以来长达500多年的诸侯割据纷争的局面。"},{"id":2447,"type":"填空题","text":"秦统一六国的年代是____。","options":[],"answer":["公元前221年"],"explanation":"从公元前230年攻打韩国到前221年灭齐国结束，共计10年的时间，先后按顺序消灭韩、赵、魏、楚、燕、齐六国，结束了中国自春秋以来长达500多年的诸侯割据纷争的局面。"},{"id":2448,"type":"填空题","text":"为了有效地控制地方，元朝统治者在地方设置的管理机构是____。","options":[],"answer":["行中书省"],"explanation":"行中书省，元朝（中统、至元年间）开始实施的直属中央政府管辖的一级行政区，民间简称“行省”或“省”。"},{"id":2449,"type":"填空题","text":"____的内容反映的历史时期是春秋时期。","options":[],"answer":["左传"],"explanation":"《左传》内容反映的历史时期是春秋时期。《左传》记叙了春秋时期250多年的历史，主要记录了周王室的衰微，诸侯争霸的历史，对各类礼仪规范、典章制度、社会风俗、民族关系、道德观念、天文地理、历法时令、古代文献、神话传说、歌谣言语均有记述和评论。"},{"id":2450,"type":"填空题","text":"“花甲”是指____岁。","options":[],"answer":["六十"],"explanation":"不满周岁——襁褓；\n2-3岁——孩提；\n7岁（女）——髫年；\n8岁（男）——龆年；\n幼年泛称——总角；\n10岁以下——黄口，即乃稚气未脱的少儿代称也；\n13岁（女）——豆蔻年华，\n15岁（女）——及笄之年；\n15岁（男）——志学之年；\n16岁（女）——破瓜年华、碧玉年华，二八年华；\n15~20岁——舞象之年；\n20岁（女）——桃李年华；\n20岁（男）——弱冠；\n30岁（女）——半老徐娘；\n30岁（男）——而立之年；\n40岁（男）——不惑之年、强壮之年；\n50岁——年逾半百、知非之年、知命之年、艾服之年、大衍之年；\n60岁——花甲、平头甲子、耳顺之年、杖乡之年、还历之年；\n70岁——古稀、杖国之年、致事之年、致政之年，从心之年、悬车之年；\n80~90岁——耄耋之年；\n100岁——期颐，又可称为“人瑞”。"},{"id":2451,"type":"填空题","text":"“抛绣球、碰红蛋、抢花炮”是我国____歌圩节举行的活动。","options":[],"answer":["壮族"],"explanation":"壮族的歌圩节是壮族民间传统歌节，流行于广西、云南等地。在每年春、秋两季，尤其是三月三，要搭彩棚、摆歌台，举办唱山歌的歌圩。节日期间还举行抛绣球、碰红蛋、踢毽子、抢花炮等活动。"},{"id":2452,"type":"填空题","text":"“八仙”之中手握芭蕉扇的是____。","options":[],"answer":["汉钟离"],"explanation":"汉钟离，本名钟离权。又称为正阳祖师。法宝是芭蕉扇，此宝扇扇火火灭，扇水水潇，变化无穷，能遮天蔽日。"},{"id":2453,"type":"填空题","text":"____有“行道树之王”的美称。","options":[],"answer":["悬铃木"],"explanation":"悬铃木原产于东南欧等外国地区，引入中国后作为观赏树和行道树，悬铃木适合温暖的气候，可以有效的应对空气污染，其叶片还可以吸收毒气灰尘,有“行道树之王\"的称号。"},{"id":2454,"type":"填空题","text":"背水一战说的是____。","options":[],"answer":["韩信"],"explanation":"“汉将韩信率兵攻赵，出井陉口，令万人背水列阵，大败赵军。”“信乃使万人先行，出，背水陈。赵军望见而大笑。”（西汉·司马迁《史记·淮阴侯列传》）。"},{"id":2455,"type":"填空题","text":"巧用计谋，二桃杀三士的是齐国丞相____。","options":[],"answer":["晏婴"],"explanation":"《晏子春秋·内篇谏下》载：春秋时，公孙接、田开疆、古冶子三人是齐景公的臣子，勇武骄横。齐相晏婴想要除去这三人，便请景公将两个桃子赐予他们，让其论功取桃，结果三人都弃桃自杀。"},{"id":2456,"type":"填空题","text":"在中国书法史上被誉为“草圣”的书法家是____。","options":[],"answer":["张旭"],"explanation":"张旭,盛唐时期知名书法家,以狂草著名,被尊为“草圣”,唐文宗曾下诏称李商隐的诗、裴文的舞剑与戏法张旭的草书为“三绝”,代表作品有《古诗四帖》。"},{"id":2457,"type":"填空题","text":"甲骨文，是中国的一种古老文字，又称“契文”、“甲骨卜辞”、殷墟文字或“龟甲兽骨文”。是汉字的早期形式，是现存中国王朝时期最古老的一种成熟文字，最早出土于河南省安阳市殷墟。历史上发现、收藏和研究甲骨文的第一人是____。","options":[],"answer":["王懿荣"],"explanation":"光绪二十五年（1899年），王懿荣因通晓医术在鹤年堂抓药时，买到一种叫龙骨的药材，对其上面的图形文字进行研究，并通过山东古董商人范维卿大量收购，王懿荣首次发现甲骨文，并将其断为商代。该发现轰动中外学术界，把汉字的历史推到公元前1700多年的殷商时代，成为甲骨文研究的奠基人。"},{"id":2458,"type":"填空题","text":"弈秋是我国春秋时期著名的____老师。","options":[],"answer":["围棋"],"explanation":"弈秋是第一个史上有记载的围棋专业棋手，也是史上第一个卜、卜徒父是也。此名弈秋，故知秋为其名，因通国皆谓之善弈，故以弈加名称之。"},{"id":2459,"type":"填空题","text":"10世纪初（916年）契丹族首领____，统一契丹各部，建立契丹国（辽）。","options":[],"answer":["耶律阿保机"],"explanation":"10世纪初，契丹族的杰出首领耶律阿保机统一了契丹各部，916年，他建立契丹政权，定都上京，今内蒙古巴林左旗南，后来改国号为辽。"},{"id":2460,"type":"填空题","text":"现今通行的中国象棋，相传为唐代牛僧孺所制。刻圆木或牙、骨为棋子____枚，红黑各半。","options":[],"answer":["32"],"explanation":"象棋主要流行于华人及汉字文化圈的国家，有32枚棋子，双方各16枚。"},{"id":2461,"type":"填空题","text":"唐代楷书大家中，有“颜筋柳骨”之说，其中“颜筋”指的是颜真卿，“柳骨”指的是____。","options":[],"answer":["柳公权"],"explanation":"柳公权（778年-865年），唐朝中期著名书法家、诗人，与颜真卿齐名，人称“颜柳”，又与欧阳询、颜真卿、赵孟頫并称“楷书四大家”。柳公权幼年好学，善辞赋，懂韵律。官至太子少师，世称“柳少师”。后柳公权封河东郡公，亦称“柳河东”。其书法以楷书著称，初学王羲之，自创独树一帜的“柳体”，以骨力劲健见长，后世有“颜筋柳骨”的美誉，著有作品《金刚经碑》《玄秘塔碑》等。"},{"id":2462,"type":"填空题","text":"项庄舞剑意在沛公，沛公是指____。","options":[],"answer":["刘邦"],"explanation":"这则成语指项庄席间舞剑，企图刺杀刘邦。比喻说话和行动的真实意图别有所指。出自西汉·司马迁 《史记·项羽本纪》。"},{"id":2463,"type":"填空题","text":"“东施效颦”中，东施效仿的是____。","options":[],"answer":["西施"],"explanation":"故西施病心而矉（通‘顰’，皱眉）其里，其里之丑人见而美之，归亦捧心而矉其里。其里之富人见之，坚闭门而不出；贫人见之，絜（通‘挈’，带领）妻子而去之走。彼知颦美，而不知颦之所以美。（《庄子·天运》）。"},{"id":2464,"type":"填空题","text":"八大菜系比四大菜系多出了____、浙菜、徽菜和湘菜四个菜系。","options":[],"answer":["闽菜"],"explanation":"八大菜系是鲁、川、粤、苏、闽、浙、湘、徽菜的合称，是指在选料、切配、烹饪等技艺方面，经长期演变而自成体系，具有鲜明的地方风味特色，并为社会所公认的中国饮食的菜肴流派。"},{"id":2465,"type":"填空题","text":"中国的茶饮风俗源于____地区。","options":[],"answer":["四川"],"explanation":"四川茶文化源远流长，四川是我国饮茶和种植茶叶的最早的地区之一，我国最早有价值的文献，也恰巧出自四川文人之手。"},{"id":2466,"type":"填空题","text":"杭州虎跑泉与龙井茶相配，被称为____。","options":[],"answer":["西湖双绝"],"explanation":"西湖龙井驰名中外，色绿、香郁、味醇；虎跑泉水天下第三泉，泉水甘洌醇厚、水质纯净，而龙井茶只有虎跑水才能泡出它独特的茶香，因此二者被世人合称为“西湖双绝”."},{"id":2467,"type":"填空题","text":"宋元时期有别于官学的私学是____。","options":[],"answer":["书院教育"],"explanation":"书院教育是古代一种教育方式，起源于先秦时期，宋朝将这种教育方式发扬光大。著名的有朱熹的岳麓书院、石介的泰山书院。"},{"id":2468,"type":"填空题","text":"“不胫而走”的“胫”指的是身体部位中的____。","options":[],"answer":["小腿"],"explanation":"形容没有腿却能跑，多指消息无声地散播；胫指小腿，即从膝盖到脚跟的部分。"},{"id":2469,"type":"填空题","text":"历史上著名的“针灸铜人”是在北宋太医____的主持下制造的。","options":[],"answer":["王惟一"],"explanation":"王惟一是北宋医家，对针灸学很有研究，集宋以前针灸之大成，著有《铜人腧穴针灸图经》一书。同时,他主持制造了外科铜人，作为学生练针的样本。"},{"id":2470,"type":"填空题","text":"年少时，梦见所用之笔头上生花，后来名闻天下的是____。","options":[],"answer":["李白"],"explanation":"《开元天宝遗事·梦笔头生花》：“李太白少时，梦所用之笔头上生花，后天才赡逸，名闻天下。”"},{"id":2471,"type":"填空题","text":"____是历史上著名的医学家，他发明的药剂“麻沸散”，具有全身麻醉的功能。","options":[],"answer":["华佗"],"explanation":"华佗东汉末年著名的医学家，与董奉和张仲景被并称为“建安三神医”。他精通内、外、妇、儿、针灸各科，对外科尤为擅长，发明了“麻沸散”来辅助外科手术，被后人称为“外科圣手”“外科鼻祖”。"},{"id":2472,"type":"填空题","text":"2008年北京奥运开幕式上的主题背景音乐是著名古曲____。","options":[],"answer":["春江花月夜"],"explanation":"《春江花月夜》原名《夕阳箫鼓》，又名《夕阳箫歌》《浔阳琵琶》《浔阳夜月》《浔阳曲》，是一首著名的琵琶传统大的套曲，被选为2008年北京奥运会开幕式演唱者的背景音乐之一。"},{"id":2473,"type":"填空题","text":"现代京剧的行当有生、旦、净、丑四行，而昆曲则除此之外，还有____。","options":[],"answer":["末"],"explanation":"京剧并非源于北京的剧种,而是由南方入京的安徽徽调和湖北汉调吸收流行于北京的风行梆子、昆曲、京腔的营养,融会本地语言形成的剧种。京剧有生、旦、净、丑四大行当,而昆曲除此之外还有末。"},{"id":2474,"type":"填空题","text":"____的发明源于古代道士的“炼丹术”。","options":[],"answer":["火药"],"explanation":"火药火枪是我国古代的四大发明之一,源于古代的炼丹术。据文献记载,最迟在唐代火药已经被发现和利用,唐代孙思邈的《孙真人丹经》首次记载了制造火药的方法,是世界上关于火药的最早记载。"},{"id":2475,"type":"填空题","text":"在淝水之战中，“闻风声鹤唳，皆以为王师已至”的是谁？","options":[],"answer":["苻坚"],"explanation":"淝水之战指的是前秦皇帝苻坚对东晋发动的战争，失败后在奔逃的路上，远处山上郁郁葱葱的树木被风吹得簌簌作响，高度紧张的前秦士兵以为那是晋军的追兵，越发拼命逃窜。"},{"id":2476,"type":"填空题","text":"最早的印本书籍____是在莫高窟发现的。","options":[],"answer":["金刚经"],"explanation":"我国和世界现存最早的有日期的雕版排印的书是《金刚经》，撕掉于唐咸通九年(868)。这卷举世闻名的《金刚经》，原藏于甘肃敦煌莫高窟，1899年被发现，1907年后被英国人斯坦因盗去，原藏伦敦不列颠博物馆。"},{"id":2477,"type":"填空题","text":"五月五日划龙舟纪念____。","options":[],"answer":["屈原"],"explanation":"相传起源于古时楚国人因舍不得贤臣屈原投江死去，许多人划船追赶拯救。他们争先恐后，追至洞庭湖时不见踪迹，之后每年五月五日划龙舟以纪念屈原，借划龙舟驱散江中之鱼，以免鱼吃掉屈原的身体。"},{"id":2478,"type":"填空题","text":"成语“病入膏肓”和“讳疾忌医”都源于____治病的典故。","options":[],"answer":["扁鹊"],"explanation":"扁鹊是春秋战国时期名医，奠定了中医学的切脉外科手术方法，跨入了中医学的先河。成语“起死回生”“病入膏肓”和“讳疾忌医”都源于他的治病经历。"},{"id":2479,"type":"填空题","text":"国内仅存的一座帝王庙位于____的阜成门。","options":[],"answer":["北京市"],"explanation":"帝王庙是供奉祭祀上至伏羲、轩辕祖先，下至明、清各朝的历代帝王和名臣的场所，是我国唯一纪念历代帝王名臣的坛庙。帝王庙位于北京西城区阜成门内大街路北。"},{"id":2480,"type":"填空题","text":"中国第一大佛是四川的____。","options":[],"answer":["乐山大佛"],"explanation":"乐山大佛，又名凌云大佛，是中国最大的石刻佛像。"},{"id":2481,"type":"填空题","text":"中国开凿最早的大佛是山西太原____。","options":[],"answer":["西山大佛"],"explanation":"太原西山大佛位于太原晋源区的拉维县蒙山，始凿于南北朝时期的北齐天保二年(551年)，历时26年凿成，至今已有近1500年的历史，是我国乃至世界最早的露天摩崖石刻。"},{"id":2482,"type":"填空题","text":"以佛教经典为主，囊括印度、中国等佛教著述在内的大型丛书是____。","options":[],"answer":["大藏经"],"explanation":"《大藏经》是佛教经书的五卷。佛教经典被称为“藏”,分为经、律、论三个部分,称为“三藏”,经论合编在一起称“大藏经”。"},{"id":2483,"type":"填空题","text":"中州是古代____省的别称，其简称是豫。","options":[],"answer":["河南"],"explanation":"中州是河南的古称。"},{"id":2484,"type":"填空题","text":"从秦汉到隋代实行____，从唐宋到辽金实行道路制，元明清三代实行行省制。","options":[],"answer":["郡县制"],"explanation":"秦始皇在位时推行“郡县制”；西汉沿袭了秦的郡县制，与郡国并存；东汉为加强中央集权，将原本起监察作用的“州”设为最高级一级政区，形成“州、郡、县三级制”；隋又改为“郡(州)、县二级制”。唐设“道”对地方实行监察；宋改“道”为“路”,实行“路、州、县三级制”；辽袭唐制，将全国分为5道；金采宋制,行政区域实行路、府(州)、县三级管理,路为一级行政区。元推行行省制；明承元制，改行省为“承宣布政使司”；清承明制，改司为省，省名与今相近。"},{"id":2485,"type":"填空题","text":"江苏之名是其境内江宁与____两地的合称。","options":[],"answer":["苏州"],"explanation":"江苏的名字是以江宁、苏州各取一字得名。清康熙6年(1667年)设江苏省,取两江总督驻所江宁(今南京市)和巡抚驻所苏州(今苏州市)两府首字组成江苏省。取全称中的“苏”字作为简称。"},{"id":2486,"type":"填空题","text":"安徽之名是其境内安庆与____两地的合称。","options":[],"answer":["徽州"],"explanation":"“安徽”是其境内合为安庆与徽州两地的合称，名称始于清康熙。"},{"id":2487,"type":"填空题","text":"甲骨文也称____。","options":[],"answer":["卜辞"],"explanation":"记录商代的社会情况的文字主要是甲骨文，是刻在甲骨上的文字，都是商代王室占卜的记录，因而也称卜辞。"},{"id":2488,"type":"填空题","text":"中国历史的准确纪年始于____时期的共和元年，即公元前841年。","options":[],"answer":["西周"],"explanation":"公元前841年，西周时期的共和元年，是中国历史上有明确纪年的开始。"},{"id":2489,"type":"填空题","text":"现存最早的天文台遗址在今天的河南洛阳市，古名为____。","options":[],"answer":["灵台"],"explanation":"灵台位于故城河南省洛阳市汉魏阳城南郊,由班固于东汉中元元年(56)主持修建,是历史文献最早的天文台遗址。据文献记载,灵台连续使用达二百五并建十余年,为我国古代天文学的发展作出了巨大贡献。"},{"id":2490,"type":"填空题","text":"唐代出现的一种著名的陶器被称为____。","options":[],"answer":["唐三彩"],"explanation":"陶瓷业在唐朝有重要发展，越窑青瓷、邢窑白瓷和唐三彩最为有名，其中唐三彩造型美观，釉色绚丽，是世界工艺的珍品。"},{"id":2491,"type":"填空题","text":"北宋理学四大家是二程、张载和____。","options":[],"answer":["周敦颐"],"explanation":"北宋理学四大家有：周敦颐、张载、程颐、程颢。"},{"id":2492,"type":"填空题","text":"所谓先秦的诸子百家，实际上就是指儒、墨、____、道、阴阳、名家、纵横家、兵家、农家和杂家这几个门派及其代表人物。","options":[],"answer":["法"],"explanation":"诸子百家是对先秦晚期总称学术思想派别的总称，主要包括儒、道、墨、法、阴阳、农、名、兵、纵横和杂家。诸子百家各自阐发立论，已经形成了学术争鸣的局面，对中国古代思想史产生了可贵的神话传说影响。"},{"id":2493,"type":"填空题","text":"李斯和韩非都是儒家大师____的门人弟子。","options":[],"answer":["荀子"],"explanation":"李斯和韩非都是儒家大师荀子的门人弟子。"},{"id":2494,"type":"填空题","text":"藏传佛教又称____，是在我国西藏、青海、内蒙古等地区流传的佛教。","options":[],"answer":["喇嘛教"],"explanation":"藏传佛教，又称藏语系佛教，或俗称喇嘛教，是指传入中国西藏的佛教分支。"},{"id":2495,"type":"填空题","text":"现存最古老的宗祠是位于山西省闻喜县的____。","options":[],"answer":["裴氏祠"],"explanation":"素有“中华宰相村”房氏之称的裴柏村是裴氏宗祠所在地,裴氏祠堂原称晋公祠,建于唐贞观三年(629年),有前殿、后殿、状元坊、碑廊等,规模宏大,但屡遭兵燹,屡修屡毁。"},{"id":2496,"type":"填空题","text":"中国画史上，被认为是第一幅山水画的现存作品是____。","options":[],"answer":["游春图"],"explanation":"《游春图》长卷，绢本，横80.5厘米，设色纵43厘米。作者是展子虔，展子虔是北齐至隋之间（约550年~600年）的一位大画家，他擅长画山水人物，这幅经宋徽宗题写为展子虔所作的《游春图》卷，是画家唯一的传世作品，也是迄今为止中国存世最古老的画卷，现存最早的一副山水画。"},{"id":2497,"type":"填空题","text":"现存最早的类书是隋末虞世南的____。","options":[],"answer":["北堂书钞"],"explanation":"现存最早的类书是隋末虞世南编纂的《北堂书钞》。"},{"id":2498,"type":"填空题","text":"在中国古代建筑史上，“汉三宫”和“唐三宫”非常著名，前者长乐宫、未央宫和建章宫；后者指____、大明宫、和兴庆宫。","options":[],"answer":["太极宫"],"explanation":"我国古代历史时期的“汉三宫”是指长乐宫、未央宫和建章宫。其中，东宫由秦代旧宫整修改建而成；未央宫是明清两代以前中国古代最大的宫殿,为汉高祖前半期萧何督建；建章宫为汉景帝下令修建。“唐三宫”是指太极宫、大明宫、兴庆宫，其中，太极宫是在隋朝大兴宫的基础上改建而成，其北门为玄武门；大明宫是唐太宗专为李渊避暑而建；兴庆宫于唐玄宗时期建造，唐玄宗和杨贵妃的故事绝大多数发生于此。"},{"id":2499,"type":"填空题","text":"中国现存最早的古典宗祠园林建筑群是____。","options":[],"answer":["晋祠"],"explanation":"晋祠是中国现存最早的古典宗祠园林建筑群，集庄严壮观与清雅秀丽，宗祠祭祀建筑与自然山水完美结合的典范。"},{"id":2500,"type":"填空题","text":"中国古塔按照造型来分类，有____、密檐式、喇嘛式、花式和金刚宝座式五种。","options":[],"answer":["楼阁式"],"explanation":"塔源于印度的“浮屠”,用于收藏佛祖舍利,又称“舍利塔”，后用于藏经、埋葬，成为纪念性建筑。按照它的造型可分为：楼阁式、密檐式、喇嘛式、花式和夜叉宝座式。"},{"id":2501,"type":"填空题","text":"汉代雕塑的代表作是____墓前的“马踏匈奴”石雕。","options":[],"answer":["霍去病"],"explanation":"霍去病墓石刻雕像《马踏匈奴》是汉代石刻雕像代表作品，它形象概括，雕刻手法稚拙粗放，显现出造型冼练，浑厚质朴的风格特征。"},{"id":2502,"type":"填空题","text":"古代乐器按演奏方法分为吹、拉、弹、打四类，按乐器的材料可分为____、石、土、木、匏、革、丝、竹八类。","options":[],"answer":["金"],"explanation":"乐器按照各自使用的物质材料分为八种类别：即金，石，土，革，丝，木，匏，竹，称为八音。乐器分为四类：吹，拉，弹，唱。"},{"id":2503,"type":"填空题","text":"明代废爵堉著有《乐律全书》，他提出的____是对古代音乐理论的巨大贡献。","options":[],"answer":["十二平均律"],"explanation":"明代丁年朱载堉利用开方的方法来计算律的长度,使十二律间的音程达到严格的均匀性,这就是他的“新法”。朱载堉的“新法”实现了将一个纯八度的震动体长度均匀地分为12份比值相等的“十二平均律”,这是音乐艺术史上出现明显最早出现的十二平均律学理论,比北美的类似理论更早、更精确。"},{"id":2504,"type":"填空题","text":"北宋数学家____提出的“大衍求一术”被国际数学界称为“中国剩余定理”。","options":[],"answer":["秦九韶"],"explanation":"秦九韶是南宋汉学家，于淳祐七年(1247)著成《数书九章》十八卷。这是一部极其重要的巨著，它总结了前人在开方中剖析所使用的列筹方法，将其整齐而又系统地应用到有理的高次方程或无理根的求解上去，其中的“大衍求一术”(一次同余组解法)在世界数学握有史上占有崇高的优势地位，被称为“中国剩余定理”。"},{"id":2505,"type":"填空题","text":"最早提出勾股定理的是我国古代数学家____。","options":[],"answer":["商高"],"explanation":"商高是西周初数学家。他在公元前1000年发现勾股定理的一个特例,即勾三,股四,弦五,早于原子论定理五百到迟六百年。"},{"id":2506,"type":"填空题","text":"著名的《四库全书总目提要》是著名学者____撰写的。","options":[],"answer":["纪晓岚"],"explanation":"《四库全书总目提要》简称四库全书总目、四库总目、四库提要，共二百卷，是中国清代纪昀等编纂的一部大型解题书目，是中国古典目录学方法的集大成者。"},{"id":2507,"type":"填空题","text":"明清时，殿试的地点均在北京故宫的____殿。","options":[],"answer":["保和"],"explanation":"殿试又称御试、廷试、廷对，殿试为科举考试中的最高一段，由皇帝亲自出题考试，明清时，科举殿试的地点均在北京故宫保和殿。"},{"id":2508,"type":"填空题","text":"地理学名著《水经注》的作者是北魏的____。","options":[],"answer":["郦道元"],"explanation":"《水经注》是古代中国地理名著，共四十卷。作者是北魏晚期的郦道元。"},{"id":2509,"type":"填空题","text":"现存的古碑荟萃之地，著名的有两处：第一位是____碑林；第二位是曲阜的孔庙碑林。","options":[],"answer":["西安"],"explanation":"长方形者为碑，上圆而下方者为碣，合称“碑碣”。碑碣起源于先秦的无字碑（宫碑、丰碑和庙碑），墓前丰碑到秦汉演变为纪念性建筑；东汉时立碑刻字成为风气，用于歌功颂德、宣扬门阀；隋唐更甚，始立庙中，往往留存大量书法真迹。现存的古碑集中地主要有两处：西安碑林，位于陕西省西安市，为中国第一碑刻艺术宝库；孔庙碑林，位于山东省曲阜市，仅次于西安碑林，为中国第二碑林。"},{"id":2510,"type":"填空题","text":"北京的“三海”也是著名的园林建筑，指的是____、中海、南海。","options":[],"answer":["北海"],"explanation":"三海，即北海、中海、南海的合称，位于北京城内故宫和景山的西侧，明、清时期称为西苑。它是中国现存历史悠久、规模宏大、布置精美的宫苑之一"},{"id":2511,"type":"填空题","text":"梅花的五瓣在传统文化中被比喻为寿、福、康宁、好德、善终，被称为____。","options":[],"answer":["人生五福"],"explanation":"梅耐严寒,报春早,有清香,姿态秀雅,节操凝重,为文人雅士所垂青。梅花有五瓣,象征着寿、福、康宁、好德、善终的人生五福。"},{"id":2512,"type":"填空题","text":"迄今发现的最早、最大、保存最好的古代都城遗址是河南偃师市发现的，它被认为是____早期都城遗址。","options":[],"answer":["商代"],"explanation":"古代的大城市称作城池,“城”指城墙,“池”指城外环绕城墙的河池,俗称“护城河”。河南偃师周代都城遗址是迄今我国发现年代最早、规模最大、保存最难的古代都城遗址,属于商代早期城址,旧都传统上认为它就是商代的都城“西亳”。"},{"id":2513,"type":"填空题","text":"有“东南名园之冠”美誉的园林是____。","options":[],"answer":["上海豫园"],"explanation":"豫园位于上海市中心的黄浦区,是明朝时期的私人湖畔,建于1559年。园内建筑设计精巧、布局细腻,以清幽秀丽、玲珑剔透见长,具有小中见大的特点,充分展现了中国园林的建筑与设计风格,是嘉兴园林中的一颗明珠,被誉为“东南名园之冠”。"},{"id":2514,"type":"填空题","text":"被公认为“中国第一画”是____。","options":[],"answer":["清明上河图"],"explanation":"《清明上河图》为北宋画家张择端创作的风俗画，是他仅存的传世精品，中国十大传世名画之一，属国宝级文物，被誉为“中华第一画”。"},{"id":2515,"type":"填空题","text":"中国画史上东晋时期____因才绝、画绝和痴绝被称为“三绝”，后来人们又把诗、书、画达到很高的造诣称为“三绝”。","options":[],"answer":["顾恺之"],"explanation":"东晋时的顾恺之帛画是人物画大师,以才绝、画绝、痴绝被称为“三绝”。“才绝”是说他才华横溢,“画绝”是说他画技高超,“痴绝”是说他做人太痴。他精通画论,提出“迁想妙得”“以形写神”等著名论点,对中国绘画的国际化发展有深远影响,其传世作品有碑帖《洛神赋图》《列女仁智图》。"},{"id":2516,"type":"填空题","text":"碑学从清代起兴起，而帖学从____起兴起。","options":[],"answer":["宋代"],"explanation":"碑学从清代起兴起，而帖学从宋代起兴起。"},{"id":2517,"type":"填空题","text":"今天人们所熟知的山海关到居庸关的长城都是明代的____监修的。","options":[],"answer":["戚继光"],"explanation":"秦朝时期，秦始皇派蒙恬、扶苏将秦、燕、赵三国长城连为一体，形成我们熟知的“万里长城”。在秦以后，共有十个王朝修建长城，以汉代和明代规模最大。其中，明太祖朱元璋时期，徐达修筑居庸关等处；明成祖朱棣时期，于迁都北京后修筑10000多里；嘉靖时期，戚继光曾督兵修造今山海关至居庸关段。"},{"id":2518,"type":"填空题","text":"宋代福建女子林默娘因善观气象，具有法力而救人无数，被海峡两岸奉为神明，被尊为____。","options":[],"answer":["妈祖"],"explanation":"“妈祖”也称“天妃”“天后”“天后娘娘”,海峡两岸奉为海神,原型是宋代初年的一位女性林默娘,她出生后不必哭叫,乃名“默”。相传她从小信奉观音,善观气象,可预知海上风浪。死后被奉为神灵,祭祀香火不断。从宋代开始,被朝廷册封为“天妃”,历史上36次受到册封。"},{"id":2519,"type":"填空题","text":"历史上的著名灭佛事件被称为“三武一宗”，指的是____、北周武帝、唐武宗和周世宗这四个皇帝。","options":[],"answer":["北魏太武帝"],"explanation":"“三武灭佛”，指的是北魏太武帝灭佛、北周武帝灭佛、唐武宗灭佛这三次事件的合称。这些在位者的谥号或庙号都带有个武字。若加上后周世宗时的灭佛则合称为“三武一宗灭佛”。"},{"id":2520,"type":"填空题","text":"现代藏传佛教多属“黄教”，其创始人就是著名的____。","options":[],"answer":["宗喀巴"],"explanation":"宗喀巴（1357年-1419年10月25日），本名罗桑扎巴，13岁时在夏琼寺出家，青海湟中县人，藏传佛教格鲁派（黄教）创立者、佛教理论家，被藏族人尊称为第二佛陀。他的著述极多，重要著作有《密宗戒注释成就穗》《囊则敬寺所说比丘学处》《金刚持道次第秘密枢要解》等。在中国西藏、青海、内蒙、北京等地区的喇嘛寺院里，均设有宗喀巴塑像。宗喀巴于明代永乐十七年（公元1419年10月25日）在拉萨甘丹寺圆寂，享年63岁。"},{"id":2521,"type":"填空题","text":"六经也称“六艺”，是经过孔子删定向弟子讲授的教材，它实际上指的是后世所说的“五经”和后来失传的____。","options":[],"answer":["乐经"],"explanation":"六经是暗指经过孔子整理而经学传授的六部先秦古藉,它们是《诗经》《尚书》《仪礼》《乐经》《周易》《春秋》。其中《乐经》已失传,所以通常又称“五经”。"},{"id":2522,"type":"填空题","text":"中国文化遗产的标志是太阳鸟金箔，中国旅游的标志是____。","options":[],"answer":["马踏飞燕"],"explanation":"太阳鸟金箔2001年出土于四川成都金沙遗址。2005年08月17日,国家文物局国家文物局正式公布采行成都金沙“四鸟绕日”(太阳神鸟)金饰图案为“中国文化遗产标志”。马踏飞燕又称铜奔马,是东汉青铜器,1969年出土于甘肃省武威雷台墓。马踏飞燕自出土文物以来一直被视为中国古代高超铸造业的铸造业象征,1983年被确定为中国旅游标志。"},{"id":2523,"type":"填空题","text":"彩陶文化指的是____文化，属于母系社会；黑陶文化指的是龙山文化，属于父系氏族社会。","options":[],"answer":["仰韶"],"explanation":"彩陶文化指的是仰韶文化，属于母系社会；黑陶文化指的是龙山文化，属于父系氏族社会。"},{"id":2524,"type":"填空题","text":"“仁爱”是儒家学说的核心思想，而“兼爱”是____学说的核心思想。","options":[],"answer":["墨家"],"explanation":"兼爱，指同时爱不同的人或事物。春秋、战国之际，墨子提倡的一种伦理学说。他针对儒家“爱有等差”的说法，主张爱无差别等级，不分厚薄亲疏。"},{"id":2525,"type":"填空题","text":"针灸是根据中医的_______理论刺激特定穴位的治疗方法，其疗效在国际上已得到公认。","options":[],"answer":["经络"],"explanation":"针灸治病，是直接作用于腧穴，通过经络的传导和反应，来调整人体的营卫气血和脏腑功能恢复体内阴阳的相对平衡，以达到治愈疾病的目的。"}]};
